static void ptn_serialize_append_spl_object_storage_object(
    PtnStringBuffer *buffer,
    PtnObject *object,
    PtnSerializeState *state
) {
    PtnSplObjectStorageData *data = object->native_data == NULL
        ? NULL
        : (PtnSplObjectStorageData *)object->native_data;
    ptn_string_buffer_append_format(
        buffer,
        "O:%zu:\"%s\":2:{i:0;",
        strlen(object->class_name),
        object->class_name
    );
    PtnValue pairs = ptn_spl_object_storage_flat_pairs_array(data);
    ptn_serialize_append_value_with_id(buffer, pairs, state, 0);
    ptn_value_destroy(&pairs);
    ptn_string_buffer_append(buffer, "i:1;");
    PtnValue properties = ptn_serialize_spl_object_storage_properties_value(state->runtime, object);
    ptn_serialize_append_value_with_id(buffer, properties, state, 0);
    ptn_value_destroy(&properties);
    ptn_string_buffer_append_char(buffer, '}');
}

static int ptn_serialize_object_is_spl_heap(PtnObject *object) {
    return object != NULL &&
        (ptn_declared_class_is_same_or_descendant(object->class_name, "SplHeap") ||
         ptn_declared_class_is_same_or_descendant(object->class_name, "SplPriorityQueue"));
}

static void ptn_serialize_append_spl_heap_object(
    PtnStringBuffer *buffer,
    PtnObject *object,
    PtnSerializeState *state
) {
    PtnSplHeapData *data = object == NULL || object->native_data == NULL
        ? NULL
        : (PtnSplHeapData *)object->native_data;
    if (data != NULL && data->is_corrupted) {
        if (state != NULL && state->runtime != NULL) {
            ptn_spl_heap_throw_corrupted(state->runtime);
        }
        ptn_string_buffer_append(buffer, "N;");
        return;
    }
    ptn_string_buffer_append_format(
        buffer,
        "O:%zu:\"%s\":2:{i:0;",
        strlen(object->class_name),
        object->class_name
    );
    PtnValue properties = ptn_spl_heap_serialized_properties_value(object);
    ptn_serialize_append_value_with_id(buffer, properties, state, 0);
    ptn_value_destroy(&properties);
    ptn_string_buffer_append(buffer, "i:1;");
    PtnValue heap_state = ptn_spl_heap_serialized_state_value(
        state == NULL ? NULL : state->runtime,
        data,
        state == NULL ? 0 : state->line
    );
    ptn_serialize_append_value_with_id(buffer, heap_state, state, 0);
    ptn_value_destroy(&heap_state);
    ptn_string_buffer_append_char(buffer, '}');
}

static void ptn_serialize_append_bcmath_number_object(
    PtnStringBuffer *buffer,
    PtnObject *object,
    PtnSerializeState *state
) {
    ptn_string_buffer_append_format(
        buffer,
        "O:%zu:\"%s\":1:{",
        strlen(object->class_name),
        object->class_name
    );
    ptn_serialize_append_string(buffer, "value", 5);

    PtnArrayKey key = ptn_array_string_key("value");
    PtnArrayEntry *entry = object == NULL || object->properties == NULL
        ? NULL
        : ptn_array_entry_for_key(object->properties, key);
    ptn_array_key_free(key);
    if (entry == NULL) {
        ptn_string_buffer_append(buffer, "N;");
    } else {
        ptn_serialize_append_value_with_id(buffer, entry->value, state, 0);
    }
    ptn_string_buffer_append_char(buffer, '}');
}

static int ptn_serialize_append_serializable_object(
    PtnStringBuffer *buffer,
    PtnObject *object,
    PtnSerializeState *state,
    int *handled
) {
    *handled = 0;
    if (state->runtime == NULL ||
        state->runtime->method_dispatch == NULL ||
        ptn_serialize_object_is_spl_dllist(object) ||
        !ptn_declared_class_implements_interface(object->class_name, "Serializable")) {
        return 0;
    }
    *handled = 1;
    PtnValue receiver = ptn_object(object);
    state->serializable_payload_depth++;
    PtnValue payload_value = state->runtime->method_dispatch(
        state->runtime,
        receiver,
        "serialize",
        0,
        NULL,
        state->line
    );
    state->serializable_payload_depth--;
    if (state->runtime->exceptions->active_exception != NULL) {
        ptn_value_destroy(&payload_value);
        ptn_string_buffer_append(buffer, "N;");
        return 0;
    }
    if (ptn_value_deref(payload_value).type == PTN_NULL) {
        ptn_value_destroy(&payload_value);
        ptn_string_buffer_append(buffer, "N;");
        return 0;
    }
    if (ptn_value_deref(payload_value).type != PTN_STRING) {
        char message[256];
        int written = snprintf(
            message,
            sizeof(message),
            "%s::serialize() must return a string or NULL",
            object->class_name
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_value_destroy(&payload_value);
        ptn_throw_exception(state->runtime, "Exception", message);
        return 0;
    }
    PtnStringOperand payload = ptn_value_to_string_operand(payload_value);
    ptn_string_buffer_append_format(
        buffer,
        "C:%zu:\"%s\":%zu:{",
        strlen(object->class_name),
        object->class_name,
        payload.len
    );
    ptn_string_buffer_append_len(buffer, payload.data, payload.len);
    ptn_string_buffer_append_char(buffer, '}');
    ptn_string_operand_free(payload);
    ptn_value_destroy(&payload_value);
    return 1;
}

static int ptn_serialize_declared_magic_method_exists(
    PtnSerializeState *state,
    PtnObject *object,
    const char *method_name
) {
    return state != NULL &&
        state->runtime != NULL &&
        state->runtime->method_dispatch != NULL &&
        object != NULL &&
        (ptn_declared_class_method_exists(object->class_name, method_name) ||
            ((ptn_internal_class_name_is_random_engine(object->class_name) ||
                 ptn_internal_class_name_is_random_randomizer(object->class_name)) &&
                ptn_internal_class_method_exists(object->class_name, method_name)));
}

static PtnArrayEntry *ptn_serialize_object_property_entry_for_name(
    PtnObject *object,
    const char *name,
    size_t name_len,
    const PtnObjectPropertyMetadata **metadata_out
) {
    if (metadata_out != NULL) {
        *metadata_out = NULL;
    }
    if (object == NULL || object->properties == NULL || name == NULL) {
        return NULL;
    }

    const char *declaring_class = NULL;
    size_t declaring_len = 0;
    const char *display_name = name;
    size_t display_len = name_len;
    PtnPropertyVisibility visibility = PTN_PROPERTY_PUBLIC;
    if (name_len >= 3 && name[0] == '\0') {
        if (name[1] == '*' && name[2] == '\0') {
            display_name = name + 3;
            display_len = name_len - 3;
            visibility = PTN_PROPERTY_PROTECTED;
        } else {
            const char *separator = memchr(name + 1, '\0', name_len - 1);
            if (separator != NULL && separator + 1 <= name + name_len) {
                declaring_class = name + 1;
                declaring_len = (size_t)(separator - declaring_class);
                display_name = separator + 1;
                display_len = (size_t)((name + name_len) - display_name);
                visibility = PTN_PROPERTY_PRIVATE;
            }
        }
    }

    PtnArrayKey key = ptn_array_string_key_len(name, name_len);
    PtnArrayEntry *entry = ptn_array_entry_for_key(object->properties, key);
    ptn_array_key_free(key);
    if (entry != NULL) {
        if (metadata_out != NULL && entry->key.type == PTN_ARRAY_KEY_STRING) {
            *metadata_out = ptn_object_property_metadata(object, entry->key.as.string);
        }
        return entry;
    }

    for (size_t i = 0; i < object->property_metadata_len; i++) {
        const PtnObjectPropertyMetadata *metadata = &object->property_metadata[i];
        if (strlen(metadata->display_name) != display_len ||
            memcmp(metadata->display_name, display_name, display_len) != 0) {
            continue;
        }
        if (visibility != PTN_PROPERTY_PUBLIC && metadata->read_visibility != visibility) {
            continue;
        }
        if (visibility == PTN_PROPERTY_PUBLIC &&
            metadata->read_visibility == PTN_PROPERTY_PRIVATE &&
            !ptn_ascii_case_equal(metadata->declaring_class, object->class_name)) {
            continue;
        }
        if (visibility == PTN_PROPERTY_PRIVATE &&
            (strlen(metadata->declaring_class) != declaring_len ||
             memcmp(metadata->declaring_class, declaring_class, declaring_len) != 0)) {
            continue;
        }
        if (metadata_out != NULL) {
            *metadata_out = metadata;
        }
        return ptn_object_property_entry_for_metadata(object, metadata);
    }
    return NULL;
}

static void ptn_serialize_emit_sleep_return_warning(
    PtnSerializeState *state,
    PtnObject *object
) {
    char message[512];
    int written = snprintf(
        message,
        sizeof(message),
        "serialize(): %s::__sleep() should return an array only containing the names of instance-variables to serialize",
        object == NULL ? "" : object->class_name
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_runtime_warning(state->runtime, message, state->line);
}

static char *ptn_serialize_sleep_display_name(
    PtnObject *object,
    PtnArrayEntry *property_entry,
    const char *fallback,
    size_t fallback_len
) {
    if (object != NULL &&
        property_entry != NULL &&
        property_entry->key.type == PTN_ARRAY_KEY_STRING) {
        const PtnObjectPropertyMetadata *metadata =
            ptn_object_property_metadata(object, property_entry->key.as.string);
        if (metadata != NULL) {
            return ptn_duplicate_string(metadata->display_name);
        }
    }
    if (fallback_len >= 3 && fallback != NULL && fallback[0] == '\0') {
        if (fallback[1] == '*' && fallback[2] == '\0') {
            return ptn_duplicate_string_len(fallback + 3, fallback_len - 3);
        }
        const char *separator = memchr(fallback + 1, '\0', fallback_len - 1);
        if (separator != NULL && separator + 1 <= fallback + fallback_len) {
            return ptn_duplicate_string_len(
                separator + 1,
                (size_t)((fallback + fallback_len) - (separator + 1))
            );
        }
    }
    return ptn_duplicate_string_len(fallback == NULL ? "" : fallback, fallback_len);
}

static int ptn_serialize_append_magic_serialize_object(
    PtnStringBuffer *buffer,
    PtnObject *object,
    PtnSerializeState *state,
    int *handled
) {
    *handled = 0;
    if (!ptn_serialize_declared_magic_method_exists(state, object, "__serialize")) {
        return 0;
    }
    *handled = 1;

    PtnValue receiver = ptn_object(object);
    PtnValue payload = state->runtime->method_dispatch(
        state->runtime,
        receiver,
        "__serialize",
        0,
        NULL,
        state->line
    );
    if (state->runtime->exceptions->active_exception != NULL) {
        ptn_value_destroy(&payload);
        ptn_string_buffer_append(buffer, "N;");
        return 0;
    }

    PtnValue payload_value = ptn_value_deref(payload);
    if (payload_value.type != PTN_ARRAY) {
        char message[256];
        int written = snprintf(
            message,
            sizeof(message),
            "%s::__serialize() must return an array",
            object->class_name
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_value_destroy(&payload);
        ptn_throw_exception(state->runtime, "TypeError", message);
        ptn_string_buffer_append(buffer, "N;");
        return 0;
    }

    ptn_string_buffer_append_format(
        buffer,
        "O:%zu:\"%s\":%zu:{",
        strlen(object->class_name),
        object->class_name,
        payload_value.as.array->len
    );
    for (size_t i = 0; i < payload_value.as.array->len; i++) {
        PtnArrayEntry *entry = &payload_value.as.array->entries[i];
        ptn_serialize_append_key(buffer, entry->key);
        ptn_serialize_append_value_with_id(buffer, entry->value, state, 0);
    }
    ptn_string_buffer_append_char(buffer, '}');
    ptn_value_destroy(&payload);
    return 1;
}

static int ptn_serialize_append_sleep_object(
    PtnStringBuffer *buffer,
    PtnObject *object,
    PtnSerializeState *state,
    int *handled
) {
    *handled = 0;
    if (!ptn_serialize_declared_magic_method_exists(state, object, "__sleep")) {
        return 0;
    }
    *handled = 1;

    PtnValue receiver = ptn_object(object);
    PtnValue names = state->runtime->method_dispatch(
        state->runtime,
        receiver,
        "__sleep",
        0,
        NULL,
        state->line
    );
    if (state->runtime->exceptions->active_exception != NULL) {
        ptn_value_destroy(&names);
        ptn_string_buffer_append(buffer, "N;");
        return 0;
    }

    PtnValue names_value = ptn_value_deref(names);
    if (names_value.type != PTN_ARRAY) {
        ptn_serialize_emit_sleep_return_warning(state, object);
        ptn_value_destroy(&names);
        ptn_string_buffer_append(buffer, "N;");
        return 0;
    }

    PtnStringBuffer body;
    ptn_string_buffer_init(&body);
    PtnValue seen = ptn_array_from_literal_entries(0, NULL);
    size_t emitted = 0;
    for (size_t i = 0; i < names_value.as.array->len; i++) {
        PtnValue name_value = ptn_value_deref(names_value.as.array->entries[i].value);
        PtnStringOperand name_operand;
        if (name_value.type == PTN_STRING) {
            name_operand = ptn_string_operand_borrowed_len(
                (const char *)name_value.as.string.data,
                name_value.as.string.len
            );
        } else {
            ptn_serialize_emit_sleep_return_warning(state, object);
            name_operand = ptn_value_to_string_operand_with_runtime(
                state->runtime,
                name_value,
                state->line
            );
            if (state->runtime != NULL && state->runtime->exceptions->active_exception != NULL) {
                ptn_string_operand_free(name_operand);
                continue;
            }
        }
        const PtnObjectPropertyMetadata *property_metadata = NULL;
        PtnArrayEntry *property_entry =
            ptn_serialize_object_property_entry_for_name(
                object,
                name_operand.data,
                name_operand.len,
                &property_metadata
            );
        if (property_entry == NULL) {
            if (ptn_object_property_metadata_dumps_uninitialized(object, property_metadata)) {
                ptn_string_operand_free(name_operand);
                continue;
            }
            char *property_name = ptn_serialize_sleep_display_name(
                object,
                NULL,
                name_operand.data,
                name_operand.len
            );
            char message[512];
            int written = snprintf(
                message,
                sizeof(message),
                "serialize(): \"%s\" returned as member variable from __sleep() but does not exist",
                property_name
            );
            free(property_name);
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_emit_runtime_warning(state->runtime, message, state->line);
            ptn_string_operand_free(name_operand);
            continue;
        }
        if (ptn_array_entry_for_key(seen.as.array, property_entry->key) != NULL) {
            char *property_name = ptn_serialize_sleep_display_name(
                object,
                property_entry,
                name_operand.data,
                name_operand.len
            );
            char message[512];
            int written = snprintf(
                message,
                sizeof(message),
                "serialize(): \"%s\" is returned from __sleep() multiple times",
                property_name
            );
            free(property_name);
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_emit_runtime_warning(state->runtime, message, state->line);
            ptn_string_operand_free(name_operand);
            continue;
        }
        ptn_array_set_entry(
            seen.as.array,
            ptn_array_key_clone(property_entry->key),
            ptn_bool(1)
        );
        ptn_serialize_append_object_property_key(&body, object, property_entry->key);
        ptn_serialize_append_value_with_id(&body, property_entry->value, state, 0);
        ptn_string_operand_free(name_operand);
        emitted++;
    }

    ptn_string_buffer_append_format(
        buffer,
        "O:%zu:\"%s\":%zu:{",
        strlen(object->class_name),
        object->class_name,
        emitted
    );
    ptn_string_buffer_append_len(buffer, body.data, body.len);
    ptn_string_buffer_append_char(buffer, '}');
    ptn_value_destroy(&seen);
    free(body.data);
    ptn_value_destroy(&names);
    return 1;
}

static void ptn_serialize_append_regular_object(
    PtnStringBuffer *buffer,
    PtnObject *object,
    PtnSerializeState *state
) {
    ptn_string_buffer_append_format(
        buffer,
        "O:%zu:\"%s\":%zu:{",
        strlen(object->class_name),
        object->class_name,
        object->properties->len
    );
    ptn_dump_seen_objects_push(&state->seen, object);
    for (size_t i = 0; i < object->properties->len; i++) {
        PtnArrayEntry *entry = &object->properties->entries[i];
        ptn_serialize_append_object_property_key(buffer, object, entry->key);
        ptn_serialize_append_value_with_id(buffer, entry->value, state, 0);
    }
    ptn_dump_seen_objects_pop(&state->seen);
    ptn_string_buffer_append_char(buffer, '}');
}

static int ptn_serialize_object_is_plain_root_user_class(PtnSerializeState *state, PtnObject *object) {
    if (state == NULL ||
        state->runtime == NULL ||
        object == NULL ||
        object->class_name == NULL ||
        object->native_data != NULL ||
        object->enum_case_name != NULL ||
        ptn_serialize_object_class_name_is_anonymous(object->class_name) ||
        !ptn_declared_runtime_plain_root_serializable_user_class(state->runtime, object->class_name)) {
        return 0;
    }
    return 1;
}

