static int ptn_array_user_compare_keys(
    PtnRuntime *runtime,
    const char *function_name,
    PtnValue callback,
    PtnArrayKey left,
    PtnArrayKey right,
    int *bool_deprecation_emitted,
    size_t line
) {
    PtnValue left_key = ptn_array_key_value(left);
    PtnValue right_key = ptn_array_key_value(right);
    int compared = ptn_array_user_compare_for_sort(
        runtime,
        function_name,
        callback,
        left_key,
        right_key,
        bool_deprecation_emitted,
        line
    );
    ptn_value_destroy(&left_key);
    ptn_value_destroy(&right_key);
    return compared;
}

static int ptn_array_user_compare_entries(
    PtnRuntime *runtime,
    const char *function_name,
    PtnValue callback,
    PtnArrayEntry *left,
    PtnArrayEntry *right,
    int compare_keys,
    int *bool_deprecation_emitted,
    size_t line
) {
    return compare_keys
        ? ptn_array_user_compare_keys(
            runtime,
            function_name,
            callback,
            left->key,
            right->key,
            bool_deprecation_emitted,
            line
        )
        : ptn_array_user_compare_for_sort(
            runtime,
            function_name,
            callback,
            left->value,
            right->value,
            bool_deprecation_emitted,
            line
        );
}

static void ptn_array_user_sort_three_entries(
    PtnRuntime *runtime,
    const char *function_name,
    PtnValue callback,
    PtnArrayEntry *entries,
    int compare_keys,
    int *bool_deprecation_emitted,
    size_t line
) {
    PtnArrayEntry first = entries[0];
    PtnArrayEntry second = entries[1];
    PtnArrayEntry third = entries[2];
    if (ptn_array_user_compare_entries(
            runtime,
            function_name,
            callback,
            &first,
            &second,
            compare_keys,
            bool_deprecation_emitted,
            line
        ) <= 0) {
        if (ptn_array_user_compare_entries(
                runtime,
                function_name,
                callback,
                &second,
                &third,
                compare_keys,
                bool_deprecation_emitted,
                line
            ) <= 0) {
            entries[0] = first;
            entries[1] = second;
            entries[2] = third;
            return;
        }
        if (ptn_array_user_compare_entries(
                runtime,
                function_name,
                callback,
                &first,
                &third,
                compare_keys,
                bool_deprecation_emitted,
                line
            ) <= 0) {
            entries[0] = first;
            entries[1] = third;
            entries[2] = second;
            return;
        }
        entries[0] = third;
        entries[1] = first;
        entries[2] = second;
        return;
    }

    if (ptn_array_user_compare_entries(
            runtime,
            function_name,
            callback,
            &third,
            &second,
            compare_keys,
            bool_deprecation_emitted,
            line
        ) <= 0) {
        entries[0] = third;
        entries[1] = second;
        entries[2] = first;
        return;
    }
    if (ptn_array_user_compare_entries(
            runtime,
            function_name,
            callback,
            &first,
            &third,
            compare_keys,
            bool_deprecation_emitted,
            line
        ) <= 0) {
        entries[0] = second;
        entries[1] = first;
        entries[2] = third;
        return;
    }
    entries[0] = second;
    entries[1] = third;
    entries[2] = first;
}

static void ptn_array_destroy_entry_buffer(PtnArrayEntry *entries, size_t len) {
    if (entries == NULL) {
        return;
    }
    for (size_t i = 0; i < len; i++) {
        ptn_array_key_free(entries[i].key);
        ptn_value_destroy(&entries[i].value);
    }
    free(entries);
}

static void ptn_array_adopt_storage(PtnArray *target, PtnArray *source);

static void ptn_array_user_sort_entries(
    PtnRuntime *runtime,
    const char *function_name,
    PtnArray *array,
    PtnValue callback,
    int compare_keys,
    int reindex,
    size_t line
) {
    int bool_deprecation_emitted = 0;
    size_t source_len = array->len;
    PtnArrayEntry *snapshot = NULL;
    if (source_len != 0) {
        if (source_len > SIZE_MAX / sizeof(PtnArrayEntry)) {
            ptn_abort_out_of_memory();
        }
        snapshot = malloc(source_len * sizeof(PtnArrayEntry));
        if (snapshot == NULL) {
            ptn_abort_out_of_memory();
        }
        for (size_t i = 0; i < source_len; i++) {
            snapshot[i].key = ptn_array_key_clone(array->entries[i].key);
            snapshot[i].value = ptn_value_clone(array->entries[i].value);
        }
    }

    ptn_array_retain(array);
    if (source_len == 3) {
        ptn_array_user_sort_three_entries(
            runtime,
            function_name,
            callback,
            snapshot,
            compare_keys,
            &bool_deprecation_emitted,
            line
        );
    } else {
        for (size_t i = 1; i < source_len; i++) {
            PtnArrayEntry moving = snapshot[i];
            size_t j = i;
            while (j > 0 && ptn_array_user_compare_entries(
                    runtime,
                    function_name,
                    callback,
                    &snapshot[j - 1],
                    &moving,
                    compare_keys,
                    &bool_deprecation_emitted,
                    line
                ) > 0) {
                snapshot[j] = snapshot[j - 1];
                j--;
            }
            snapshot[j] = moving;
        }
    }

    ptn_array_destroy_entry_buffer(array->entries, array->len);
    free(array->index_slots);
    array->entries = snapshot;
    array->index_slots = NULL;
    array->index_capacity = 0;
    array->len = source_len;
    array->capacity = source_len;
    if (reindex) {
        for (size_t i = 0; i < source_len; i++) {
            if (i > (size_t)INT64_MAX) {
                ptn_abort_out_of_memory();
            }
            ptn_array_key_free(array->entries[i].key);
            array->entries[i].key = ptn_array_int_key((int64_t)i);
        }
    }
    ptn_array_recompute_next_auto_key(array);
    array->current_index = 0;
    ptn_array_rebuild_index(array);
}

static PtnArray *ptn_array_user_sorted_snapshot(
    PtnRuntime *runtime,
    PtnArray *array,
    PtnValue callback,
    size_t line,
    void (*sorter)(PtnRuntime *, PtnArray *, PtnValue, size_t)
) {
    PtnArray *sorted = ptn_array_clone(array);
    sorter(runtime, sorted, callback, line);
    return sorted;
}

static void ptn_array_commit_sorted_snapshot_to_reference(PtnRuntime *runtime, PtnReference *reference, PtnArray *sorted) {
    PtnValue replacement = ptn_array(sorted);
    if (!ptn_reference_assign_publish_first(runtime, reference, replacement)) {
        ptn_value_destroy(&replacement);
        return;
    }
    ptn_value_destroy(&replacement);
}

static void ptn_array_commit_sorted_snapshot_to_slot(PtnRuntime *runtime, PtnValue *slot, PtnArray *sorted) {
    if (slot->type == PTN_REFERENCE) {
        ptn_array_commit_sorted_snapshot_to_reference(runtime, slot->as.reference, sorted);
        return;
    }
    PtnValue *target = slot;
    if (target->type == PTN_ARRAY) {
        PtnArray *target_array = ptn_array_detach_value(target);
        if (target_array != NULL) {
            ptn_array_adopt_storage(target_array, sorted);
            free(sorted);
            return;
        }
    }
    ptn_value_destroy(target);
    *target = ptn_array(sorted);
}

