static PtnValue ptn_runtime_user_comparator_sort_variable(
    PtnRuntime *runtime,
    const char *function_name,
    const char *name,
    PtnValue value,
    PtnValue callback,
    size_t line,
    void (*sorter)(PtnRuntime *, PtnArray *, PtnValue, size_t)
) {
    PtnArray *array = ptn_internal_expect_mutable_array_variable_arg(
        runtime,
        function_name,
        1,
        "array",
        name,
        value
    );
    if (array == NULL) {
        return ptn_bool(0);
    }
    PtnValue checked_callback = ptn_internal_expect_callback_arg(
        runtime,
        function_name,
        2,
        "callback",
        callback
    );
    PtnArray *sorted = ptn_array_user_sorted_snapshot(runtime, array, checked_callback, line, sorter);
    if (runtime->exceptions->active_exception == NULL) {
        PtnSymbol *symbol = ptn_symbols_slot_for_write(&runtime->symbols, name);
        ptn_array_commit_sorted_snapshot_to_slot(runtime, &symbol->value, sorted);
    } else {
        ptn_array_free(sorted);
    }
    ptn_value_destroy(&checked_callback);
    return ptn_bool(1);
}

static PtnValue ptn_runtime_user_comparator_sort_path(
    PtnRuntime *runtime,
    const char *function_name,
    const char *name,
    const PtnArrayPathSegment *segments,
    size_t segment_count,
    PtnValue callback,
    size_t line,
    void (*sorter)(PtnRuntime *, PtnArray *, PtnValue, size_t)
) {
    PtnArray *array = ptn_internal_expect_mutable_array_path_arg(
        runtime,
        function_name,
        1,
        "array",
        name,
        segments,
        segment_count,
        line
    );
    PtnValue checked_callback = ptn_internal_expect_callback_arg(
        runtime,
        function_name,
        2,
        "callback",
        callback
    );
    sorter(runtime, array, checked_callback, line);
    ptn_array_free(array);
    ptn_value_destroy(&checked_callback);
    return ptn_bool(1);
}

static PtnArray *ptn_internal_expect_mutable_array_property_arg(
    PtnRuntime *runtime,
    const char *function_name,
    size_t position,
    const char *argument_name,
    PtnValue receiver,
    const char *property,
    const char *access_scope,
    size_t line,
    PtnValue *reference
);

static PtnValue ptn_runtime_user_comparator_sort_property(
    PtnRuntime *runtime,
    const char *function_name,
    PtnValue receiver,
    const char *property,
    const char *access_scope,
    PtnValue callback,
    size_t line,
    void (*sorter)(PtnRuntime *, PtnArray *, PtnValue, size_t)
) {
    PtnValue reference = ptn_null();
    PtnArray *array = ptn_internal_expect_mutable_array_property_arg(
        runtime,
        function_name,
        1,
        "array",
        receiver,
        property,
        access_scope,
        line,
        &reference
    );
    PtnValue checked_callback = ptn_internal_expect_callback_arg(
        runtime,
        function_name,
        2,
        "callback",
        callback
    );
    PtnArray *sorted = ptn_array_user_sorted_snapshot(runtime, array, checked_callback, line, sorter);
    if (runtime->exceptions->active_exception == NULL) {
        if (reference.type == PTN_REFERENCE) {
            ptn_array_commit_sorted_snapshot_to_reference(runtime, reference.as.reference, sorted);
        } else {
            ptn_array_commit_sorted_snapshot_to_slot(runtime, &reference, sorted);
        }
    } else {
        ptn_array_free(sorted);
    }
    ptn_value_destroy(&checked_callback);
    ptn_value_destroy(&reference);
    return ptn_bool(1);
}

