static PtnArray *ptn_array_walk_slot_array_for_write(
    PtnRuntime *runtime,
    const char *function_name,
    PtnValue *slot,
    PtnValue value,
    size_t line
) {
    PtnValue current_value = slot == NULL ? value : *slot;
    PtnValue resolved = ptn_value_deref(current_value);
    if (resolved.type == PTN_OBJECT && resolved.as.object != NULL) {
        if (resolved.as.object->lazy_uninitialized && !resolved.as.object->lazy_initializing) {
            if (!ptn_lazy_object_initialize(runtime, resolved, line)) {
                return NULL;
            }
        }
        return resolved.as.object->properties;
    }
    PtnArray *array = ptn_internal_expect_array_arg(
        runtime,
        function_name,
        1,
        "array",
        current_value
    );
    if (slot == NULL) {
        return array;
    }

    PtnValue *slot_value = slot->type == PTN_REFERENCE ? &slot->as.reference->value : slot;
    if (slot_value->type != PTN_ARRAY) {
        return array;
    }

    PtnArray *detached = ptn_array_detach_value(slot_value);
    return detached == NULL ? slot_value->as.array : detached;
}

static PtnArray *ptn_array_walk_slot_current_array(PtnValue *slot) {
    if (slot == NULL) {
        return NULL;
    }
    PtnValue *slot_value = slot->type == PTN_REFERENCE ? &slot->as.reference->value : slot;
    if (slot_value->type == PTN_OBJECT && slot_value->as.object != NULL) {
        return slot_value->as.object->properties;
    }
    return slot_value->type == PTN_ARRAY ? slot_value->as.array : NULL;
}

static PtnObject *ptn_array_walk_slot_object(PtnValue *slot, PtnValue value) {
    PtnValue current_value = slot == NULL ? value : *slot;
    PtnValue resolved = ptn_value_deref(current_value);
    return resolved.type == PTN_OBJECT ? resolved.as.object : NULL;
}

static PtnValue *ptn_array_walk_current_slot(
    PtnRuntime *runtime,
    const char *name,
    PtnValue *local_slot
) {
    if (name == NULL) {
        return local_slot;
    }
    return ptn_symbols_value_slot(&runtime->symbols, name);
}

static PtnValue ptn_array_walk_property_key_value(PtnObject *object, PtnArrayKey key) {
    if (object == NULL || key.type != PTN_ARRAY_KEY_STRING) {
        return ptn_array_key_value(key);
    }
    const PtnObjectPropertyMetadata *metadata =
        ptn_object_property_metadata(object, key.as.string);
    if (metadata == NULL || metadata->read_visibility == PTN_PROPERTY_PUBLIC) {
        return ptn_array_key_value(key);
    }

    size_t display_len = strlen(metadata->display_name);
    if (metadata->read_visibility == PTN_PROPERTY_PROTECTED) {
        if (display_len > SIZE_MAX - 3) {
            ptn_abort_out_of_memory();
        }
        size_t key_len = display_len + 3;
        char *storage = malloc(key_len);
        if (storage == NULL) {
            ptn_abort_out_of_memory();
        }
        storage[0] = '\0';
        storage[1] = '*';
        storage[2] = '\0';
        memcpy(storage + 3, metadata->display_name, display_len);
        return ptn_owned_string_len(storage, key_len);
    }

    size_t declaring_len = strlen(metadata->declaring_class);
    if (declaring_len > SIZE_MAX - display_len - 2) {
        ptn_abort_out_of_memory();
    }
    size_t key_len = declaring_len + display_len + 2;
    char *storage = malloc(key_len);
    if (storage == NULL) {
        ptn_abort_out_of_memory();
    }
    storage[0] = '\0';
    memcpy(storage + 1, metadata->declaring_class, declaring_len);
    storage[declaring_len + 1] = '\0';
    memcpy(storage + declaring_len + 2, metadata->display_name, display_len);
    return ptn_owned_string_len(storage, key_len);
}

static const char *ptn_array_walk_exception_base_class(PtnException *exception) {
    const char *class_name = exception == NULL || exception->class_name == NULL
        ? "Exception"
        : exception->class_name;
    return ptn_exception_type_matches_name(class_name, "Error") ? "Error" : "Exception";
}

static PtnArrayKey ptn_array_walk_exception_property_key(
    const char *declaring_class,
    const char *display_name
) {
    size_t display_len = strlen(display_name);
    if (declaring_class == NULL) {
        if (display_len > SIZE_MAX - 3) {
            ptn_abort_out_of_memory();
        }
        size_t key_len = display_len + 3;
        char *storage = malloc(key_len);
        if (storage == NULL) {
            ptn_abort_out_of_memory();
        }
        storage[0] = '\0';
        storage[1] = '*';
        storage[2] = '\0';
        memcpy(storage + 3, display_name, display_len);
        PtnArrayKey key;
        key.type = PTN_ARRAY_KEY_STRING;
        key.string_len = key_len;
        key.as.string = storage;
        return key;
    }

    size_t declaring_len = strlen(declaring_class);
    if (declaring_len > SIZE_MAX - display_len - 2) {
        ptn_abort_out_of_memory();
    }
    size_t key_len = declaring_len + display_len + 2;
    char *storage = malloc(key_len);
    if (storage == NULL) {
        ptn_abort_out_of_memory();
    }
    storage[0] = '\0';
    memcpy(storage + 1, declaring_class, declaring_len);
    storage[declaring_len + 1] = '\0';
    memcpy(storage + declaring_len + 2, display_name, display_len);
    PtnArrayKey key;
    key.type = PTN_ARRAY_KEY_STRING;
    key.string_len = key_len;
    key.as.string = storage;
    return key;
}

static void ptn_array_walk_exception_add_property(
    PtnArray *array,
    PtnException *exception,
    const char *declaring_class,
    const char *display_name
) {
    ptn_array_set_entry(
        array,
        ptn_array_walk_exception_property_key(declaring_class, display_name),
        ptn_reflection_exception_property_value(exception, display_name)
    );
}

static PtnValue ptn_array_walk_exception_properties(PtnException *exception) {
    const char *base_class = ptn_array_walk_exception_base_class(exception);
    PtnValue properties = ptn_array_from_literal_entries(0, NULL);
    PtnArray *array = properties.as.array;

    ptn_array_walk_exception_add_property(array, exception, NULL, "message");
    ptn_array_walk_exception_add_property(array, exception, base_class, "string");
    ptn_array_walk_exception_add_property(array, exception, NULL, "code");
    ptn_array_walk_exception_add_property(array, exception, NULL, "file");
    ptn_array_walk_exception_add_property(array, exception, NULL, "line");
    ptn_array_walk_exception_add_property(array, exception, base_class, "trace");
    ptn_array_walk_exception_add_property(array, exception, base_class, "previous");

    if (
        exception != NULL &&
        exception->class_name != NULL &&
        ptn_exception_name_equal(exception->class_name, "ErrorException")
    ) {
        ptn_array_walk_exception_add_property(array, exception, "ErrorException", "severity");
    }

    if (exception != NULL) {
        PtnValue dynamic_properties = ptn_value_deref(exception->dynamic_properties);
        if (dynamic_properties.type == PTN_ARRAY && dynamic_properties.as.array != NULL) {
            PtnArray *dynamic_array = dynamic_properties.as.array;
            for (size_t i = 0; i < dynamic_array->len; i++) {
                ptn_array_set_entry(
                    array,
                    ptn_array_key_clone(dynamic_array->entries[i].key),
                    ptn_value_clone_deref(dynamic_array->entries[i].value)
                );
            }
        }
    }

    return properties;
}

static void ptn_array_walk_exception_sync_property(
    PtnException *exception,
    PtnArray *array,
    const char *declaring_class,
    const char *display_name
) {
    PtnArrayKey key = ptn_array_walk_exception_property_key(declaring_class, display_name);
    size_t index = ptn_array_find_key(array, key);
    ptn_array_key_free(key);
    if (index >= array->len) {
        return;
    }
    PtnValue written = ptn_reflection_exception_write_property(
        exception,
        display_name,
        array->entries[index].value
    );
    ptn_value_destroy(&written);
}

static void ptn_array_walk_exception_sync_dynamic_properties(
    PtnException *exception,
    PtnArray *array
) {
    if (exception == NULL) {
        return;
    }
    PtnValue dynamic_properties = ptn_value_deref(exception->dynamic_properties);
    if (dynamic_properties.type != PTN_ARRAY || dynamic_properties.as.array == NULL) {
        return;
    }
    PtnArray *dynamic_array = dynamic_properties.as.array;
    for (size_t i = 0; i < dynamic_array->len; i++) {
        PtnArrayKey key = ptn_array_key_clone(dynamic_array->entries[i].key);
        size_t index = ptn_array_find_key(array, key);
        if (index < array->len) {
            ptn_array_set_entry(
                dynamic_array,
                key,
                ptn_value_clone_deref(array->entries[index].value)
            );
            continue;
        }
        ptn_array_key_free(key);
    }
}

static void ptn_array_walk_exception_sync(PtnException *exception, PtnArray *array) {
    const char *base_class = ptn_array_walk_exception_base_class(exception);
    ptn_array_walk_exception_sync_property(exception, array, NULL, "message");
    ptn_array_walk_exception_sync_property(exception, array, base_class, "string");
    ptn_array_walk_exception_sync_property(exception, array, NULL, "code");
    ptn_array_walk_exception_sync_property(exception, array, NULL, "file");
    ptn_array_walk_exception_sync_property(exception, array, NULL, "line");
    ptn_array_walk_exception_sync_property(exception, array, base_class, "trace");
    ptn_array_walk_exception_sync_property(exception, array, base_class, "previous");

    if (
        exception != NULL &&
        exception->class_name != NULL &&
        ptn_exception_name_equal(exception->class_name, "ErrorException")
    ) {
        ptn_array_walk_exception_sync_property(exception, array, "ErrorException", "severity");
    }
    ptn_array_walk_exception_sync_dynamic_properties(exception, array);
}

static void ptn_array_walk_call_function(
    PtnRuntime *runtime,
    PtnValue callback,
    PtnArray *array,
    PtnObject *object,
    size_t index,
    int has_userdata,
    PtnValue userdata,
    size_t line
) {
    PtnArrayEntry *entry = &array->entries[index];
    int created_reference = entry->value.type != PTN_REFERENCE;
    if (entry->value.type != PTN_REFERENCE) {
        PtnValue current = entry->value;
        entry->value = ptn_reference_value(ptn_reference_new_owned(current));
    }
    PtnReference *walk_reference = entry->value.type == PTN_REFERENCE
        ? entry->value.as.reference
        : NULL;
    if (walk_reference != NULL && object != NULL && entry->key.type == PTN_ARRAY_KEY_STRING) {
        const PtnObjectPropertyMetadata *metadata =
            ptn_object_property_metadata(object, entry->key.as.string);
        ptn_reference_adopt_property_type(walk_reference, metadata);
    }
    PtnReference *created_walk_reference = created_reference ? walk_reference : NULL;

    PtnValue value_reference = ptn_value_clone(entry->value);
    PtnValue key = ptn_array_walk_property_key_value(object, entry->key);
    PtnValue callback_args[3] = {
        value_reference,
        key,
        has_userdata ? ptn_value_clone_deref(userdata) : ptn_null()
    };
    PtnTryFrame callback_frame;
    PtnTraceFrame *saved_trace_frame = runtime->trace_frame;
    int previous_suppress_user_call_frame_location =
        runtime->suppress_user_call_frame_location;
    ptn_try_frame_push(runtime, &callback_frame);
    if (setjmp(callback_frame.jump) != 0) {
        ptn_try_frame_pop(runtime, &callback_frame);
        runtime->trace_frame = saved_trace_frame;
        runtime->suppress_user_call_frame_location =
            previous_suppress_user_call_frame_location;
        ptn_value_destroy(&callback_args[0]);
        ptn_value_destroy(&callback_args[1]);
        if (has_userdata) {
            ptn_value_destroy(&callback_args[2]);
        }
        if (created_reference && created_walk_reference != NULL) {
            for (size_t i = 0; i < array->len; i++) {
                ptn_value_unwrap_reference_slots(&array->entries[i].value, created_walk_reference, 0);
            }
        }
        ptn_rethrow_exception(runtime);
    }
    runtime->suppress_user_call_frame_location = 1;
    PtnValue callback_result = ptn_internal_call_callback(
        runtime,
        callback,
        has_userdata ? 3 : 2,
        callback_args,
        line
    );
    runtime->suppress_user_call_frame_location =
        previous_suppress_user_call_frame_location;
    ptn_try_frame_pop(runtime, &callback_frame);
    ptn_value_destroy(&callback_args[0]);
    ptn_value_destroy(&callback_args[1]);
    if (has_userdata) {
        ptn_value_destroy(&callback_args[2]);
    }
    ptn_value_destroy(&callback_result);
    if (
        created_reference &&
        created_walk_reference != NULL &&
        created_walk_reference->refcount == 1
    ) {
        for (size_t i = 0; i < array->len; i++) {
            ptn_value_unwrap_reference_slots(&array->entries[i].value, created_walk_reference, 0);
        }
    }
    if (object != NULL) {
        ptn_lazy_object_sync_proxy_instance_properties(object);
    }
}

static PtnArrayKey *ptn_array_walk_snapshot_keys(PtnArray *array, size_t *count_out) {
    *count_out = array->len;
    if (array->len == 0) {
        return NULL;
    }
    PtnArrayKey *keys = malloc(array->len * sizeof(PtnArrayKey));
    if (keys == NULL) {
        ptn_abort_out_of_memory();
    }
    for (size_t i = 0; i < array->len; i++) {
        keys[i] = ptn_array_key_clone(array->entries[i].key);
    }
    return keys;
}

static void ptn_array_walk_free_snapshot_keys(PtnArrayKey *keys, size_t count) {
    if (keys == NULL) {
        return;
    }
    for (size_t i = 0; i < count; i++) {
        ptn_array_key_free(keys[i]);
    }
    free(keys);
}

static PtnValue ptn_array_walk_exception(
    PtnRuntime *runtime,
    PtnException *exception,
    PtnValue callback,
    int has_userdata,
    PtnValue userdata,
    size_t line
) {
    PtnValue properties = ptn_array_walk_exception_properties(exception);
    PtnArray *array = properties.as.array;
    PtnArrayKey *snapshot_keys = NULL;
    size_t snapshot_count = 0;
    snapshot_keys = ptn_array_walk_snapshot_keys(array, &snapshot_count);
    for (size_t i = 0; i < snapshot_count; i++) {
        PtnArrayKey key = ptn_array_key_clone(snapshot_keys[i]);
        size_t entry_index = ptn_array_find_key(array, key);
        ptn_array_key_free(key);
        if (entry_index < array->len) {
            ptn_array_walk_call_function(
                runtime,
                callback,
                array,
                NULL,
                entry_index,
                has_userdata,
                userdata,
                line
            );
        }
    }
    ptn_array_walk_free_snapshot_keys(snapshot_keys, snapshot_count);
    ptn_array_walk_exception_sync(exception, array);
    ptn_value_destroy(&properties);
    return ptn_bool(1);
}

static PtnValue ptn_array_walk_slot(
    PtnRuntime *runtime,
    const char *name,
    PtnValue *local_slot,
    PtnValue value,
    PtnValue callback,
    int has_userdata,
    PtnValue userdata,
    size_t line
) {
    PtnArray *last_array = NULL;
    PtnArrayKey *snapshot_keys = NULL;
    size_t snapshot_count = 0;
    size_t snapshot_index = 0;

    PtnValue *initial_slot = ptn_array_walk_current_slot(runtime, name, local_slot);
    PtnValue initial_value = initial_slot == NULL ? value : *initial_slot;
    PtnValue initial_resolved = ptn_value_deref(initial_value);
    if (initial_resolved.type == PTN_EXCEPTION && initial_resolved.as.exception != NULL) {
        return ptn_array_walk_exception(
            runtime,
            initial_resolved.as.exception,
            callback,
            has_userdata,
            userdata,
            line
        );
    }

    for (;;) {
        PtnValue *slot = ptn_array_walk_current_slot(runtime, name, local_slot);
        PtnArray *array = ptn_array_walk_slot_array_for_write(
            runtime,
            "array_walk",
            slot,
            value,
            line
        );
        if (array == NULL) {
            ptn_array_walk_free_snapshot_keys(snapshot_keys, snapshot_count);
            return ptn_null();
        }
        PtnObject *object = ptn_array_walk_slot_object(slot, value);
        if (array != last_array) {
            ptn_array_walk_free_snapshot_keys(snapshot_keys, snapshot_count);
            last_array = array;
            snapshot_keys = ptn_array_walk_snapshot_keys(array, &snapshot_count);
            snapshot_index = 0;
        }
        if (snapshot_index >= snapshot_count) {
            break;
        }

        PtnArrayKey key = ptn_array_key_clone(snapshot_keys[snapshot_index]);
        snapshot_index++;
        size_t entry_index = ptn_array_find_key(array, key);
        ptn_array_key_free(key);
        if (entry_index < array->len) {
            ptn_array_walk_call_function(
                runtime,
                callback,
                array,
                object,
                entry_index,
                has_userdata,
                userdata,
                line
            );
        }

        PtnValue *after_slot = ptn_array_walk_current_slot(runtime, name, local_slot);
        PtnArray *after_array = ptn_array_walk_slot_current_array(after_slot);
        if (after_array != array && after_slot != NULL) {
            last_array = NULL;
        }
    }

    ptn_array_walk_free_snapshot_keys(snapshot_keys, snapshot_count);
    return ptn_bool(1);
}

static PtnValue ptn_array_walk_checked(
    PtnRuntime *runtime,
    const char *name,
    PtnValue *local_slot,
    PtnValue value,
    PtnValue callback,
    int has_userdata,
    PtnValue userdata,
    int userdata_allows_reference,
    size_t line
) {
    PtnValue checked_callback = ptn_internal_expect_callback_arg(
        runtime,
        "array_walk",
        2,
        "callback",
        callback
    );
    int previous_warn_by_ref_argument_mismatch = runtime->warn_by_ref_argument_mismatch;
    int previous_throw_argument_count_errors = runtime->throw_argument_count_errors;
    int previous_by_ref_argument_notice_pending = runtime->by_ref_argument_notice_pending;
    int previous_by_ref_argument_notice_emitted = runtime->by_ref_argument_notice_emitted;
    size_t previous_by_ref_argument_notice_line = runtime->by_ref_argument_notice_line;
    runtime->warn_by_ref_argument_mismatch = 1;
    runtime->throw_argument_count_errors = 1;
    if (has_userdata && !userdata_allows_reference) {
        runtime->by_ref_argument_notice_pending = 1;
        runtime->by_ref_argument_notice_emitted = 0;
        runtime->by_ref_argument_notice_line = line;
    }
    PtnValue stable_userdata = has_userdata ? ptn_value_clone_deref(userdata) : ptn_null();
    PtnValue result = ptn_array_walk_slot(
        runtime,
        name,
        local_slot,
        value,
        checked_callback,
        has_userdata,
        stable_userdata,
        line
    );
    ptn_value_destroy(&stable_userdata);
    runtime->by_ref_argument_notice_line = previous_by_ref_argument_notice_line;
    runtime->by_ref_argument_notice_emitted = previous_by_ref_argument_notice_emitted;
    runtime->by_ref_argument_notice_pending = previous_by_ref_argument_notice_pending;
    runtime->throw_argument_count_errors = previous_throw_argument_count_errors;
    runtime->warn_by_ref_argument_mismatch = previous_warn_by_ref_argument_mismatch;
    ptn_value_destroy(&checked_callback);
    return result;
}

