typedef struct {
    const void *identity;
    size_t emitted_count;
} PtnArrayMultisortNumericWarning;

typedef struct {
    PtnArray *array;
    int mutable;
    int descending;
    int order_seen;
    int type_seen;
    int sort_type;
    int case_insensitive;
    PtnArrayMultisortNumericWarning *numeric_warnings;
    size_t numeric_warning_count;
    size_t numeric_warning_capacity;
} PtnArrayMultisortOperand;

static void ptn_array_multisort_throw_type_error(PtnRuntime *runtime, size_t position, const char *suffix) {
    char message[192];
    int written = snprintf(
        message,
        sizeof(message),
        "array_multisort(): Argument #%zu %s",
        position,
        suffix
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "TypeError", message);
}

static void ptn_array_multisort_throw_value_error(PtnRuntime *runtime, size_t position, const char *suffix) {
    char message[192];
    int written = snprintf(
        message,
        sizeof(message),
        "array_multisort(): Argument #%zu %s",
        position,
        suffix
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "ValueError", message);
}

static int ptn_array_multisort_compare_string_case(
    PtnRuntime *runtime,
    PtnValue left,
    PtnValue right,
    size_t line
) {
    PtnStringOperand left_string = ptn_value_to_string_operand_with_runtime(runtime, left, line);
    PtnStringOperand right_string = ptn_value_to_string_operand_with_runtime(runtime, right, line);
    const unsigned char *left_bytes = (const unsigned char *)left_string.data;
    const unsigned char *right_bytes = (const unsigned char *)right_string.data;
    size_t shared_len = left_string.len < right_string.len ? left_string.len : right_string.len;
    int compared = 0;
    for (size_t i = 0; i < shared_len; i++) {
        unsigned char left_byte = left_bytes[i];
        unsigned char right_byte = right_bytes[i];
        if (left_byte >= (unsigned char)'A' && left_byte <= (unsigned char)'Z') {
            left_byte = (unsigned char)(left_byte + ((unsigned char)'a' - (unsigned char)'A'));
        }
        if (right_byte >= (unsigned char)'A' && right_byte <= (unsigned char)'Z') {
            right_byte = (unsigned char)(right_byte + ((unsigned char)'a' - (unsigned char)'A'));
        }
        if (left_byte < right_byte) {
            compared = -1;
            break;
        }
        if (left_byte > right_byte) {
            compared = 1;
            break;
        }
    }
    if (compared == 0) {
        if (left_string.len < right_string.len) {
            compared = -1;
        } else if (left_string.len > right_string.len) {
            compared = 1;
        }
    }
    ptn_string_operand_free(left_string);
    ptn_string_operand_free(right_string);
    return compared;
}

static int ptn_array_multisort_compare_string(
    PtnRuntime *runtime,
    PtnValue left,
    PtnValue right,
    size_t line
) {
    PtnStringOperand left_string = ptn_value_to_string_operand_with_runtime(runtime, left, line);
    PtnStringOperand right_string = ptn_value_to_string_operand_with_runtime(runtime, right, line);
    int compared = ptn_compare_string_bytes(
        (const unsigned char *)left_string.data,
        left_string.len,
        (const unsigned char *)right_string.data,
        right_string.len
    );
    ptn_string_operand_free(left_string);
    ptn_string_operand_free(right_string);
    if (compared == PTN_COMPARE_LESS) {
        return -1;
    }
    if (compared == PTN_COMPARE_GREATER) {
        return 1;
    }
    return 0;
}

static const void *ptn_array_multisort_numeric_object_identity(PtnValue value, const char **class_name_out) {
    value = ptn_value_deref(value);
    if (value.type == PTN_OBJECT) {
        *class_name_out = value.as.object->class_name;
        return value.as.object;
    }
    if (value.type == PTN_CLOSURE) {
        *class_name_out = "Closure";
        return value.as.closure;
    }
    if (value.type == PTN_EXCEPTION) {
        *class_name_out = value.as.exception->class_name;
        return value.as.exception;
    }
    *class_name_out = NULL;
    return NULL;
}

static void ptn_array_multisort_emit_numeric_object_warning(
    PtnRuntime *runtime,
    PtnArrayMultisortOperand *operand,
    PtnValue value,
    size_t line
) {
    const char *class_name = NULL;
    const void *identity = ptn_array_multisort_numeric_object_identity(value, &class_name);
    if (runtime == NULL || operand == NULL || identity == NULL || class_name == NULL) {
        return;
    }

    PtnArrayMultisortNumericWarning *warning = NULL;
    for (size_t i = 0; i < operand->numeric_warning_count; i++) {
        if (operand->numeric_warnings[i].identity == identity) {
            warning = &operand->numeric_warnings[i];
            break;
        }
    }
    if (warning == NULL) {
        if (operand->numeric_warning_count == operand->numeric_warning_capacity) {
            size_t new_capacity = operand->numeric_warning_capacity == 0
                ? 4
                : operand->numeric_warning_capacity * 2;
            if (new_capacity < operand->numeric_warning_capacity) {
                ptn_abort_out_of_memory();
            }
            PtnArrayMultisortNumericWarning *new_warnings = realloc(
                operand->numeric_warnings,
                new_capacity * sizeof(PtnArrayMultisortNumericWarning)
            );
            if (new_warnings == NULL) {
                ptn_abort_out_of_memory();
            }
            operand->numeric_warnings = new_warnings;
            operand->numeric_warning_capacity = new_capacity;
        }
        warning = &operand->numeric_warnings[operand->numeric_warning_count++];
        warning->identity = identity;
        warning->emitted_count = 0;
    }
    if (warning->emitted_count >= 2) {
        return;
    }

    char message[192];
    int written = snprintf(
        message,
        sizeof(message),
        "Object of class %s could not be converted to float",
        class_name
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_spaced_warning(&runtime->diagnostics, message, line);
    warning->emitted_count++;
}

static PtnNumber ptn_array_multisort_numeric_number(
    PtnRuntime *runtime,
    PtnArrayMultisortOperand *operand,
    PtnValue value,
    size_t line
) {
    ptn_array_multisort_emit_numeric_object_warning(runtime, operand, value, line);
    return ptn_to_number(value);
}

static int ptn_array_multisort_compare_numeric(
    PtnRuntime *runtime,
    PtnArrayMultisortOperand *operand,
    PtnValue left,
    PtnValue right,
    size_t line
) {
    PtnNumber left_number = ptn_array_multisort_numeric_number(runtime, operand, left, line);
    PtnNumber right_number = ptn_array_multisort_numeric_number(runtime, operand, right, line);
    if (left_number.type == PTN_NUMBER_INT && right_number.type == PTN_NUMBER_INT) {
        if (left_number.integer < right_number.integer) {
            return -1;
        }
        if (left_number.integer > right_number.integer) {
            return 1;
        }
        return 0;
    }
    if (left_number.floating < right_number.floating) {
        return -1;
    }
    if (left_number.floating > right_number.floating) {
        return 1;
    }
    return 0;
}

static int ptn_array_multisort_compare_string_operands(
    PtnStringOperand left_string,
    PtnStringOperand right_string
) {
    int compared = ptn_compare_string_bytes(
        (const unsigned char *)left_string.data,
        left_string.len,
        (const unsigned char *)right_string.data,
        right_string.len
    );
    if (compared == PTN_COMPARE_LESS) {
        return -1;
    }
    if (compared == PTN_COMPARE_GREATER) {
        return 1;
    }
    return 0;
}

static int ptn_array_multisort_compare_regular(
    PtnRuntime *runtime,
    PtnValue left,
    PtnValue right,
    size_t line
) {
    PtnStringOperand left_string;
    PtnStringOperand right_string;
    int left_stringable = ptn_try_object_to_string_operand(runtime, left, line, &left_string);
    int right_stringable = ptn_try_object_to_string_operand(runtime, right, line, &right_string);
    PtnValue left_resolved = ptn_value_deref(left);
    PtnValue right_resolved = ptn_value_deref(right);

    if (left_stringable && right_stringable) {
        int compared = ptn_array_multisort_compare_string_operands(left_string, right_string);
        ptn_string_operand_free(left_string);
        ptn_string_operand_free(right_string);
        return compared;
    }
    if (left_stringable && right_resolved.type == PTN_STRING) {
        PtnStringOperand right_operand = ptn_string_operand_borrowed_len(
            (const char *)right_resolved.as.string.data,
            right_resolved.as.string.len
        );
        int compared = ptn_array_multisort_compare_string_operands(left_string, right_operand);
        ptn_string_operand_free(left_string);
        return compared;
    }
    if (right_stringable && left_resolved.type == PTN_STRING) {
        PtnStringOperand left_operand = ptn_string_operand_borrowed_len(
            (const char *)left_resolved.as.string.data,
            left_resolved.as.string.len
        );
        int compared = ptn_array_multisort_compare_string_operands(left_operand, right_string);
        ptn_string_operand_free(right_string);
        return compared;
    }
    if (left_stringable) {
        ptn_string_operand_free(left_string);
        if (
            right_resolved.type == PTN_OBJECT ||
            right_resolved.type == PTN_CLOSURE ||
            right_resolved.type == PTN_EXCEPTION
        ) {
            return -1;
        }
    }
    if (right_stringable) {
        ptn_string_operand_free(right_string);
        if (
            left_resolved.type == PTN_OBJECT ||
            left_resolved.type == PTN_CLOSURE ||
            left_resolved.type == PTN_EXCEPTION
        ) {
            return 1;
        }
    }
    return ptn_array_value_compare_ascending(left, right);
}

static int ptn_array_multisort_compare_operand(
    PtnRuntime *runtime,
    PtnArrayMultisortOperand *operand,
    size_t left_index,
    size_t right_index,
    size_t line
) {
    PtnValue left = operand->array->entries[left_index].value;
    PtnValue right = operand->array->entries[right_index].value;
    int compared = 0;
    switch (operand->sort_type) {
        case PTN_SORT_NUMERIC:
            compared = ptn_array_multisort_compare_numeric(runtime, operand, left, right, line);
            break;
        case PTN_SORT_STRING:
        case PTN_SORT_LOCALE_STRING:
            compared = operand->case_insensitive
                ? ptn_array_multisort_compare_string_case(runtime, left, right, line)
                : ptn_array_multisort_compare_string(runtime, left, right, line);
            break;
        case PTN_SORT_NATURAL:
            compared = operand->case_insensitive
                ? ptn_array_value_compare_natural_case(left, right, runtime, line)
                : ptn_array_value_compare_natural(left, right, runtime, line);
            break;
        case PTN_SORT_REGULAR:
        default:
            compared = ptn_array_multisort_compare_regular(runtime, left, right, line);
            break;
    }
    return operand->descending ? -compared : compared;
}

static int ptn_array_multisort_compare_indices(
    PtnRuntime *runtime,
    PtnArrayMultisortOperand *operands,
    size_t operand_count,
    size_t left_index,
    size_t right_index,
    size_t line
) {
    for (size_t i = 0; i < operand_count; i++) {
        int compared = ptn_array_multisort_compare_operand(
            runtime,
            &operands[i],
            left_index,
            right_index,
            line
        );
        if (compared != 0) {
            return compared;
        }
    }
    if (left_index < right_index) {
        return -1;
    }
    if (left_index > right_index) {
        return 1;
    }
    return 0;
}

static int ptn_array_multisort_flag_is_valid(int64_t flag) {
    return flag == PTN_SORT_ASC ||
        flag == PTN_SORT_DESC ||
        flag == PTN_SORT_REGULAR ||
        flag == PTN_SORT_NUMERIC ||
        flag == PTN_SORT_STRING ||
        flag == PTN_SORT_LOCALE_STRING ||
        flag == PTN_SORT_NATURAL ||
        flag == (PTN_SORT_STRING | PTN_SORT_FLAG_CASE) ||
        flag == (PTN_SORT_NATURAL | PTN_SORT_FLAG_CASE);
}

static int ptn_array_multisort_apply_flag(
    PtnRuntime *runtime,
    PtnArrayMultisortOperand *operand,
    size_t position,
    int64_t flag
) {
    if (flag == PTN_SORT_ASC || flag == PTN_SORT_DESC) {
        if (operand->order_seen) {
            ptn_array_multisort_throw_type_error(
                runtime,
                position,
                "must be an array or a sort flag that has not already been specified"
            );
            return 0;
        }
        operand->order_seen = 1;
        operand->descending = flag == PTN_SORT_DESC;
        return 1;
    }

    int sort_type = -1;
    int case_insensitive = 0;
    if (flag == PTN_SORT_REGULAR) {
        sort_type = PTN_SORT_REGULAR;
    } else if (flag == PTN_SORT_NUMERIC) {
        sort_type = PTN_SORT_NUMERIC;
    } else if (flag == PTN_SORT_STRING) {
        sort_type = PTN_SORT_STRING;
    } else if (flag == PTN_SORT_LOCALE_STRING) {
        sort_type = PTN_SORT_LOCALE_STRING;
    } else if (flag == PTN_SORT_NATURAL) {
        sort_type = PTN_SORT_NATURAL;
    } else if (flag == (PTN_SORT_STRING | PTN_SORT_FLAG_CASE)) {
        sort_type = PTN_SORT_STRING;
        case_insensitive = 1;
    } else if (flag == (PTN_SORT_NATURAL | PTN_SORT_FLAG_CASE)) {
        sort_type = PTN_SORT_NATURAL;
        case_insensitive = 1;
    }

    if (sort_type < 0) {
        ptn_array_multisort_throw_value_error(runtime, position, "must be a valid sort flag");
        return 0;
    }
    if (operand->type_seen) {
        ptn_array_multisort_throw_type_error(
            runtime,
            position,
            "must be an array or a sort flag that has not already been specified"
        );
        return 0;
    }
    operand->type_seen = 1;
    operand->sort_type = sort_type;
    operand->case_insensitive = case_insensitive;
    return 1;
}

static void ptn_array_multisort_apply_order(PtnArray *array, const size_t *order) {
    if (array->len == 0) {
        array->current_index = 0;
        ptn_array_rebuild_index(array);
        return;
    }
    PtnArrayEntry *entries = malloc(array->len * sizeof(PtnArrayEntry));
    if (entries == NULL) {
        ptn_abort_out_of_memory();
    }
    for (size_t i = 0; i < array->len; i++) {
        entries[i] = array->entries[order[i]];
    }
    free(array->entries);
    array->entries = entries;

    int64_t next_int_key = 0;
    for (size_t i = 0; i < array->len; i++) {
        if (array->entries[i].key.type != PTN_ARRAY_KEY_INT) {
            continue;
        }
        if (next_int_key == INT64_MAX) {
            ptn_abort_out_of_memory();
        }
        array->entries[i].key = ptn_array_int_key(next_int_key);
        next_int_key++;
    }
    array->current_index = 0;
    ptn_array_recompute_next_auto_key(array);
    ptn_array_rebuild_index(array);
}

static int ptn_array_multisort_validate_string_operands(
    PtnRuntime *runtime,
    const PtnArrayMultisortOperand *operand,
    size_t line
) {
    if (
        operand->sort_type != PTN_SORT_STRING &&
        operand->sort_type != PTN_SORT_LOCALE_STRING &&
        operand->sort_type != PTN_SORT_NATURAL
    ) {
        return 1;
    }
    for (size_t i = 0; i < operand->array->len; i++) {
        PtnValue value = ptn_value_deref(operand->array->entries[i].value);
        const char *class_name = NULL;
        if (value.type == PTN_OBJECT) {
            class_name = value.as.object->class_name;
        } else if (value.type == PTN_CLOSURE) {
            class_name = "Closure";
        } else if (value.type == PTN_EXCEPTION) {
            class_name = value.as.exception->class_name;
        }
        if (class_name == NULL) {
            continue;
        }
        if (value.type == PTN_OBJECT) {
            PtnStringOperand object_string;
            if (ptn_try_object_to_string_operand(runtime, value, line, &object_string)) {
                ptn_string_operand_free(object_string);
                if (runtime->exceptions->active_exception != NULL) {
                    return 0;
                }
                continue;
            }
        }

        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "Object of class %s could not be converted to string",
            class_name
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception_at(runtime, "Error", message, runtime->source_path, line);
        return 0;
    }
    return 1;
}

static void ptn_array_multisort_free_operands(
    PtnArrayMultisortOperand *operands,
    size_t operand_count
) {
    if (operands == NULL) {
        return;
    }
    for (size_t i = 0; i < operand_count; i++) {
        free(operands[i].numeric_warnings);
    }
    free(operands);
}

static PtnValue ptn_internal_array_multisort(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnArrayMultisortOperand *operands = calloc(argc, sizeof(PtnArrayMultisortOperand));
    if (operands == NULL) {
        ptn_abort_out_of_memory();
    }
    size_t operand_count = 0;

    for (size_t i = 0; i < argc; i++) {
        PtnValue value = ptn_value_deref(args[i]);
        if (value.type == PTN_ARRAY) {
            PtnArray *array = value.as.array;
            int mutable = 0;
            if (ptn_value_is_by_ref_argument_source(args[i]) &&
                args[i].as.reference->value.type == PTN_ARRAY) {
                array = ptn_array_detach_value(&args[i].as.reference->value);
                mutable = 1;
            }
            operands[operand_count].array = array;
            operands[operand_count].mutable = mutable;
            operands[operand_count].descending = 0;
            operands[operand_count].order_seen = 0;
            operands[operand_count].type_seen = 0;
            operands[operand_count].sort_type = PTN_SORT_REGULAR;
            operands[operand_count].case_insensitive = 0;
            operand_count++;
            continue;
        }

        if (operand_count == 0) {
            ptn_array_multisort_free_operands(operands, operand_count);
            if (value.type == PTN_INT) {
                if (ptn_array_multisort_flag_is_valid(value.as.integer)) {
                    ptn_array_multisort_throw_type_error(
                        runtime,
                        i + 1,
                        "($array) must be an array or a sort flag that has not already been specified"
                    );
                } else {
                    ptn_array_multisort_throw_value_error(
                        runtime,
                        i + 1,
                        "($array) must be a valid sort flag"
                    );
                }
            } else {
                ptn_array_multisort_throw_type_error(
                    runtime,
                    i + 1,
                    "($array) must be an array or a sort flag"
                );
            }
            return ptn_null();
        }
        if (value.type != PTN_INT) {
            ptn_array_multisort_free_operands(operands, operand_count);
            ptn_array_multisort_throw_type_error(
                runtime,
                i + 1,
                "must be an array or a sort flag"
            );
            return ptn_null();
        }
        if (!ptn_array_multisort_apply_flag(runtime, &operands[operand_count - 1], i + 1, value.as.integer)) {
            ptn_array_multisort_free_operands(operands, operand_count);
            return ptn_null();
        }
    }

    size_t len = operands[0].array->len;
    for (size_t i = 1; i < operand_count; i++) {
        if (operands[i].array->len != len) {
            ptn_array_multisort_free_operands(operands, operand_count);
            ptn_throw_exception(runtime, "ValueError", "Array sizes are inconsistent");
            return ptn_null();
        }
    }
    for (size_t i = 0; i < operand_count; i++) {
        if (!ptn_array_multisort_validate_string_operands(runtime, &operands[i], line)) {
            ptn_array_multisort_free_operands(operands, operand_count);
            return ptn_null();
        }
    }

    size_t *order = malloc((len == 0 ? 1 : len) * sizeof(size_t));
    if (order == NULL) {
        ptn_abort_out_of_memory();
    }
    for (size_t i = 0; i < len; i++) {
        order[i] = i;
    }
    for (size_t i = 1; i < len; i++) {
        size_t moving = order[i];
        size_t j = i;
        while (j > 0) {
            int compared = ptn_array_multisort_compare_indices(
                runtime,
                operands,
                operand_count,
                order[j - 1],
                moving,
                line
            );
            if (runtime->exceptions->active_exception != NULL) {
                free(order);
                ptn_array_multisort_free_operands(operands, operand_count);
                return ptn_null();
            }
            if (compared <= 0) {
                break;
            }
            order[j] = order[j - 1];
            j--;
        }
        order[j] = moving;
    }

    for (size_t i = 0; i < operand_count; i++) {
        if (operands[i].mutable) {
            ptn_array_multisort_apply_order(operands[i].array, order);
        }
    }
    free(order);
    ptn_array_multisort_free_operands(operands, operand_count);
    return ptn_bool(1);
}

static const char *ptn_array_aggregate_type_name(PtnValue value) {
    value = ptn_value_deref(value);
    if (value.type == PTN_OBJECT) {
        return value.as.object->class_name;
    }
    if (value.type == PTN_EXCEPTION) {
        return value.as.exception->class_name;
    }
    if (value.type == PTN_CLOSURE) {
        return "Closure";
    }
    return ptn_offset_container_type_name(value);
}

static void ptn_array_aggregate_warn_unsupported(
    PtnRuntime *runtime,
    const char *function_name,
    const char *operation_name,
    PtnValue value,
    size_t line
) {
    char message[192];
    int written = snprintf(
        message,
        sizeof(message),
        "%s(): %s is not supported on type %s",
        function_name,
        operation_name,
        ptn_array_aggregate_type_name(value)
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_warning(&runtime->diagnostics, message, line);
}

static PtnNumber ptn_array_aggregate_number(
    PtnRuntime *runtime,
    const char *function_name,
    const char *operation_name,
    PtnValue value,
    int product_mode,
    size_t line
) {
    value = ptn_value_deref(value);
    switch (value.type) {
        case PTN_NULL:
        case PTN_BOOL:
        case PTN_INT:
        case PTN_FLOAT:
            return ptn_to_number(value);
        case PTN_STRING:
            if (!ptn_string_has_embedded_nul(value.as.string)) {
                double unused = 0.0;
                if (ptn_is_numeric_string((const char *)value.as.string.data, &unused)) {
                    return ptn_string_to_number((const char *)value.as.string.data);
                }
            }
            ptn_array_aggregate_warn_unsupported(runtime, function_name, operation_name, value, line);
            return ptn_number_int(0);
        case PTN_RESOURCE:
            ptn_array_aggregate_warn_unsupported(runtime, function_name, operation_name, value, line);
            return ptn_number_int(value.as.resource->id);
        case PTN_ARRAY:
        case PTN_OBJECT:
        case PTN_CLOSURE:
        case PTN_EXCEPTION:
            ptn_array_aggregate_warn_unsupported(runtime, function_name, operation_name, value, line);
            return ptn_number_int(product_mode ? 1 : 0);
        case PTN_REFERENCE:
            return ptn_number_int(0);
    }
    return ptn_number_int(0);
}

static int ptn_int64_add_overflows(int64_t left, int64_t right, int64_t *result) {
    if ((right > 0 && left > INT64_MAX - right) || (right < 0 && left < INT64_MIN - right)) {
        return 1;
    }
    *result = left + right;
    return 0;
}

static int ptn_int64_multiply_overflows(int64_t left, int64_t right, int64_t *result) {
    long double product = (long double)left * (long double)right;
    if (product > (long double)INT64_MAX || product < (long double)INT64_MIN) {
        return 1;
    }
    *result = left * right;
    return 0;
}

static PtnValue ptn_internal_array_sum(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnArray *array = ptn_internal_expect_array_arg(runtime, "array_sum", 1, "array", args[0]);
    int use_float = 0;
    int64_t integer_sum = 0;
    double float_sum = 0.0;
    for (size_t i = 0; i < array->len; i++) {
        PtnNumber number = ptn_array_aggregate_number(runtime, "array_sum", "Addition", array->entries[i].value, 0, line);
        if (number.type == PTN_NUMBER_FLOAT) {
            if (!use_float) {
                float_sum = (double)integer_sum;
                use_float = 1;
            }
            float_sum += number.floating;
        } else if (use_float) {
            float_sum += (double)number.integer;
        } else {
            int64_t next_sum = 0;
            if (ptn_int64_add_overflows(integer_sum, number.integer, &next_sum)) {
                float_sum = (double)integer_sum + (double)number.integer;
                use_float = 1;
            } else {
                integer_sum = next_sum;
            }
        }
    }
    return use_float ? ptn_float(float_sum) : ptn_int(integer_sum);
}

static PtnValue ptn_internal_array_product(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnArray *array = ptn_internal_expect_array_arg(runtime, "array_product", 1, "array", args[0]);
    int use_float = 0;
    int64_t integer_product = 1;
    double float_product = 1.0;
    for (size_t i = 0; i < array->len; i++) {
        PtnNumber number = ptn_array_aggregate_number(runtime, "array_product", "Multiplication", array->entries[i].value, 1, line);
        if (number.type == PTN_NUMBER_FLOAT) {
            if (!use_float) {
                float_product = (double)integer_product;
                use_float = 1;
            }
            float_product *= number.floating;
        } else if (use_float) {
            float_product *= (double)number.integer;
        } else {
            int64_t next_product = 0;
            if (ptn_int64_multiply_overflows(integer_product, number.integer, &next_product)) {
                float_product = (double)integer_product * (double)number.integer;
                use_float = 1;
            } else {
                integer_product = next_product;
            }
        }
    }
    return use_float ? ptn_float(float_product) : ptn_int(integer_product);
}

static PtnArrayKey ptn_array_change_key_case_key(PtnArrayKey source, int uppercase) {
    if (source.type == PTN_ARRAY_KEY_INT) {
        return ptn_array_int_key(source.as.integer);
    }

    size_t len = source.string_len;
    char *changed = malloc(len + 1);
    if (changed == NULL) {
        ptn_abort_out_of_memory();
    }
    for (size_t i = 0; i < len; i++) {
        unsigned char byte = (unsigned char)source.as.string[i];
        changed[i] = (char)(uppercase ? toupper(byte) : tolower(byte));
    }
    changed[len] = '\0';

    PtnArrayKey key;
    key.type = PTN_ARRAY_KEY_STRING;
    key.string_len = len;
    key.as.string = changed;
    return key;
}

static PtnValue ptn_internal_array_change_key_case(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)line;
    PtnArray *array = ptn_internal_expect_array_arg(runtime, "array_change_key_case", 1, "array", args[0]);
    int64_t case_value = argc >= 2 ? ptn_value_to_integer(args[1]) : 0;
    if (case_value != 0 && case_value != 1) {
        ptn_throw_exception(
            runtime,
            "ValueError",
            "array_change_key_case(): Argument #2 ($case) must be either CASE_LOWER or CASE_UPPER"
        );
    }

    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    int uppercase = case_value == 1;
    for (size_t i = 0; i < array->len; i++) {
        ptn_array_set_entry(
            result.as.array,
            ptn_array_change_key_case_key(array->entries[i].key, uppercase),
            ptn_value_clone_deref(array->entries[i].value)
        );
    }
    return result;
}

static void ptn_array_chunk_append_result(PtnValue *result, PtnValue chunk, int64_t *chunk_index) {
    ptn_array_set_entry(
        result->as.array,
        ptn_array_int_key(*chunk_index),
        chunk
    );
    if (*chunk_index == INT64_MAX) {
        ptn_abort_out_of_memory();
    }
    (*chunk_index)++;
}

static PtnValue ptn_internal_array_chunk(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)line;
    PtnArray *array = ptn_internal_expect_array_arg(runtime, "array_chunk", 1, "array", args[0]);
    int64_t length = ptn_value_to_integer(args[1]);
    if (length < 1) {
        ptn_throw_exception(
            runtime,
            "ValueError",
            "array_chunk(): Argument #2 ($length) must be greater than 0"
        );
    }

    int preserve_keys = argc >= 3 && ptn_is_truthy(args[2]);
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    PtnValue chunk = ptn_null();
    int64_t chunk_index = 0;
    int64_t chunk_len = 0;

    for (size_t i = 0; i < array->len; i++) {
        if (chunk_len == 0) {
            chunk = ptn_array_from_literal_entries(0, NULL);
        }

        PtnArrayEntry *source = &array->entries[i];
        PtnArrayKey key = preserve_keys
            ? ptn_array_key_clone(source->key)
            : ptn_array_int_key(chunk.as.array->next_auto_key);
        PtnValue value = ptn_array_reindexing_internal_value(source->value);
        ptn_array_set_entry(chunk.as.array, key, ptn_value_clone(value));

        chunk_len++;
        if (chunk_len == length) {
            ptn_array_chunk_append_result(&result, chunk, &chunk_index);
            chunk = ptn_null();
            chunk_len = 0;
        }
    }

    if (chunk_len != 0) {
        ptn_array_chunk_append_result(&result, chunk, &chunk_index);
    }

    return result;
}

typedef struct {
    int is_null;
    PtnArrayKey array_key;
    char *property_name;
} PtnArrayColumnKey;

static char *ptn_array_column_integer_property_name(int64_t integer) {
    char buffer[32];
    int written = snprintf(buffer, sizeof(buffer), "%lld", (long long)integer);
    if (written < 0 || (size_t)written >= sizeof(buffer)) {
        ptn_abort_out_of_memory();
    }
    return ptn_duplicate_string(buffer);
}

static const char *ptn_array_column_argument_type_name(PtnValue value) {
    value = ptn_value_deref(value);
    if (value.type == PTN_BOOL) {
        return value.as.boolean ? "true" : "false";
    }
    if (value.type == PTN_OBJECT) {
        return value.as.object->class_name;
    }
    return ptn_offset_container_type_name(value);
}

static PtnArrayColumnKey ptn_array_column_key_from_arg(
    PtnRuntime *runtime,
    size_t position,
    const char *argument_name,
    PtnValue value,
    size_t line
) {
    value = ptn_value_deref(value);
    PtnArrayColumnKey key;
    key.is_null = 0;
    key.property_name = NULL;

    int64_t integer = 0;
    switch (value.type) {
        case PTN_NULL:
            key.is_null = 1;
            key.array_key = ptn_array_int_key(0);
            return key;
        case PTN_BOOL:
            integer = value.as.boolean ? 1 : 0;
            if (!runtime->strict_types) {
                key.array_key = ptn_array_int_key(integer);
                key.property_name = ptn_array_column_integer_property_name(integer);
                return key;
            }
            break;
        case PTN_INT:
            key.array_key = ptn_array_int_key(value.as.integer);
            key.property_name = ptn_array_column_integer_property_name(value.as.integer);
            return key;
        case PTN_FLOAT:
            if (!runtime->strict_types) {
                integer = ptn_value_to_integer(value);
                key.array_key = ptn_array_int_key(integer);
                key.property_name = ptn_array_column_integer_property_name(integer);
                return key;
            }
            break;
        case PTN_STRING:
            key.array_key = ptn_array_key_from_value(value);
            key.property_name = ptn_duplicate_string_len((const char *)value.as.string.data, value.as.string.len);
            return key;
        case PTN_OBJECT: {
            PtnStringOperand object_string;
            if (ptn_try_object_to_string_operand(runtime, value, line, &object_string)) {
                PtnValue key_value = ptn_string_literal(object_string.data, object_string.len);
                key.array_key = ptn_array_key_from_value(key_value);
                key.property_name = ptn_duplicate_string_len(object_string.data, object_string.len);
                ptn_string_operand_free(object_string);
                return key;
            }
            char message[192];
            int written = snprintf(
                message,
                sizeof(message),
                "array_column(): Argument #%zu ($%s) must be of type string|int|null, %s given",
                position,
                argument_name,
                ptn_array_column_argument_type_name(value)
            );
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_throw_exception(runtime, "TypeError", message);
            key.is_null = 1;
            key.array_key = ptn_array_int_key(0);
            return key;
        }
        case PTN_RESOURCE:
        case PTN_ARRAY:
        case PTN_CLOSURE:
        case PTN_EXCEPTION:
        case PTN_REFERENCE:
            break;
    }
    {
            char message[192];
            int written = snprintf(
                message,
                sizeof(message),
                "array_column(): Argument #%zu ($%s) must be of type string|int|null, %s given",
                position,
                argument_name,
                ptn_array_column_argument_type_name(value)
            );
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_throw_exception(runtime, "TypeError", message);
            key.is_null = 1;
            key.array_key = ptn_array_int_key(0);
            return key;
    }
}

static void ptn_array_column_key_free(PtnArrayColumnKey key) {
    if (key.is_null) {
        return;
    }
    ptn_array_key_free(key.array_key);
    free(key.property_name);
}

static int ptn_array_column_lookup(
    PtnRuntime *runtime,
    PtnValue row,
    PtnArrayColumnKey key,
    size_t line,
    PtnValue *value_out
) {
    row = ptn_value_deref(row);
    if (key.is_null) {
        *value_out = ptn_value_clone_deref(row);
        return 1;
    }

    if (row.type == PTN_ARRAY) {
        PtnArrayEntry *entry = ptn_array_entry_for_key(row.as.array, key.array_key);
        if (entry == NULL) {
            return 0;
        }
        *value_out = ptn_value_clone_deref(entry->value);
        return 1;
    }

    if (row.type == PTN_OBJECT) {
        PtnLookupResult lookup =
            ptn_object_property_lookup_quiet(runtime, row, key.property_name, NULL, line);
        if (lookup.exists) {
            *value_out = lookup.value;
            return 1;
        }
        if (
            runtime != NULL &&
            runtime->magic_property_read != NULL &&
            runtime->magic_property_read(
                runtime,
                row,
                key.property_name,
                strlen(key.property_name),
                line,
                1,
                value_out
            )
        ) {
            return 1;
        }
        return 0;
    }

    return 0;
}

static void ptn_array_column_add_value(
    PtnRuntime *runtime,
    PtnValue *result,
    PtnValue row,
    PtnArrayColumnKey index_key,
    size_t line,
    PtnValue value
) {
    if (!index_key.is_null) {
        PtnValue index_value;
        if (ptn_array_column_lookup(runtime, row, index_key, line, &index_value)) {
            ptn_emit_array_offset_key_conversion_diagnostic(runtime, index_value, line, 1);
            PtnArrayKey result_key;
            if (!ptn_array_offset_key_from_value(runtime, index_value, line, 0, &result_key)) {
                ptn_value_destroy(&index_value);
                ptn_value_destroy(&value);
                return;
            }
            ptn_value_destroy(&index_value);
            ptn_array_set_entry(result->as.array, result_key, value);
            return;
        }
    }

    PtnArrayKey next_key = ptn_array_int_key(result->as.array->next_auto_key);
    ptn_array_set_entry(result->as.array, next_key, value);
}

static PtnValue ptn_internal_array_column(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnArray *array = ptn_internal_expect_array_arg(runtime, "array_column", 1, "array", args[0]);
    PtnArrayColumnKey column_key = ptn_array_column_key_from_arg(runtime, 2, "column_key", args[1], line);
    PtnArrayColumnKey index_key = argc >= 3
        ? ptn_array_column_key_from_arg(runtime, 3, "index_key", args[2], line)
        : (PtnArrayColumnKey){ 1, { 0 }, NULL };

    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    for (size_t i = 0; i < array->len; i++) {
        PtnValue value;
        if (!ptn_array_column_lookup(runtime, array->entries[i].value, column_key, line, &value)) {
            continue;
        }
        ptn_array_column_add_value(runtime, &result, array->entries[i].value, index_key, line, value);
    }

    ptn_array_column_key_free(column_key);
    ptn_array_column_key_free(index_key);
    return result;
}

static int ptn_array_count_values_key_from_value(PtnRuntime *runtime, PtnValue value, size_t line, PtnArrayKey *key_out) {
    value = ptn_value_deref(value);
    switch (value.type) {
        case PTN_INT:
        case PTN_STRING:
            *key_out = ptn_array_key_from_value(value);
            return 1;
        case PTN_NULL:
        case PTN_BOOL:
        case PTN_FLOAT:
        case PTN_RESOURCE:
        case PTN_ARRAY:
        case PTN_OBJECT:
        case PTN_CLOSURE:
        case PTN_EXCEPTION:
        case PTN_REFERENCE:
            ptn_emit_spaced_warning(
                &runtime->diagnostics,
                "array_count_values(): Can only count string and integer values, entry skipped",
                line
            );
            return 0;
    }
    return 0;
}

static PtnValue ptn_internal_array_count_values(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnArray *array = ptn_internal_expect_array_arg(runtime, "array_count_values", 1, "array", args[0]);
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    for (size_t i = 0; i < array->len; i++) {
        PtnArrayKey key;
        if (!ptn_array_count_values_key_from_value(runtime, array->entries[i].value, line, &key)) {
            continue;
        }

        int64_t count = 1;
        PtnArrayEntry *existing = ptn_array_entry_for_key(result.as.array, key);
        if (existing != NULL) {
            PtnValue existing_value = ptn_value_deref(existing->value);
            count = existing_value.as.integer + 1;
        }
        ptn_array_set_entry(result.as.array, key, ptn_int(count));
    }
    return result;
}

static int ptn_array_flip_key_from_value(PtnRuntime *runtime, PtnValue value, size_t line, PtnArrayKey *key_out) {
    value = ptn_value_deref(value);
    switch (value.type) {
        case PTN_INT:
        case PTN_STRING:
            *key_out = ptn_array_key_from_value(value);
            return 1;
        case PTN_NULL:
        case PTN_BOOL:
        case PTN_FLOAT:
        case PTN_RESOURCE:
        case PTN_ARRAY:
        case PTN_OBJECT:
        case PTN_CLOSURE:
        case PTN_EXCEPTION:
        case PTN_REFERENCE:
            ptn_emit_spaced_warning(
                &runtime->diagnostics,
                "array_flip(): Can only flip string and integer values, entry skipped",
                line
            );
            return 0;
    }
    return 0;
}

static PtnValue ptn_internal_array_flip(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnArray *array = ptn_internal_expect_array_arg(runtime, "array_flip", 1, "array", args[0]);
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    for (size_t i = 0; i < array->len; i++) {
        PtnArrayKey key;
        if (!ptn_array_flip_key_from_value(runtime, array->entries[i].value, line, &key)) {
            continue;
        }
        ptn_array_set_entry(result.as.array, key, ptn_array_key_value(array->entries[i].key));
    }
    return result;
}

static PtnValue ptn_internal_array_keys(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnArray *array = ptn_internal_expect_array_arg(runtime, "array_keys", 1, "array", args[0]);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    if (argc >= 2 && ptn_value_is_missing(args[1])) {
        ptn_throw_exception(
            runtime,
            "ArgumentCountError",
            "array_keys(): Argument #2 ($filter_value) must be passed explicitly, because the default value is not known"
        );
        return ptn_null();
    }
    int has_search_value = argc >= 2 && !ptn_value_is_missing(args[1]);
    int strict = argc >= 3 && !ptn_value_is_missing(args[2]) && ptn_is_truthy(args[2]);
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    for (size_t i = 0; i < array->len; i++) {
        PtnArrayEntry *entry = &array->entries[i];
        if (has_search_value) {
            int matched = strict
                ? ptn_compare_identical(runtime, args[1], entry->value, line)
                : ptn_compare_equal(runtime, args[1], entry->value, line);
            if (!matched) {
                continue;
            }
        }

        ptn_array_set_entry(
            result.as.array,
            ptn_array_int_key(result.as.array->next_auto_key),
            ptn_array_key_value(entry->key)
        );
    }
    return result;
}

