static int64_t ptn_internal_expect_integer_arg(
    PtnRuntime *runtime,
    const char *function_name,
    size_t position,
    const char *argument_name,
    PtnValue value,
    size_t line
);

static PtnValue ptn_array_pick_keys_with_state(
    PtnRuntime *runtime,
    const char *function_name,
    PtnArray *array,
    int64_t requested,
    PtnMt19937State *state,
    int always_array
) {
    if (state == NULL) {
        state = &ptn_global_mt19937_state;
    }
    if (array->len == 0) {
        char message[160];
        int written = snprintf(
            message,
            sizeof(message),
            "%s(): Argument #1 ($array) must not be empty",
            function_name
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(
            runtime,
            "ValueError",
            message
        );
        return ptn_null();
    }
    if (requested < 1 || (uint64_t)requested > (uint64_t)array->len) {
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "%s(): Argument #2 ($num) must be between 1 and the number of elements in argument #1 ($array)",
            function_name
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(
            runtime,
            "ValueError",
            message
        );
        return ptn_null();
    }
    if (requested == 1) {
        size_t index = ptn_mt19937_bounded_index(state, array->len - 1);
        PtnValue key = ptn_array_key_value(array->entries[index].key);
        if (!always_array) {
            return key;
        }
        PtnValue result = ptn_array_from_literal_entries(0, NULL);
        ptn_array_set_entry(result.as.array, ptn_array_int_key(0), key);
        return result;
    }

    size_t num_avail = array->len;
    int negative_bitset = requested > (int64_t)(num_avail >> 1);
    size_t sample_count = negative_bitset ? num_avail - (size_t)requested : (size_t)requested;
    unsigned char *selected = calloc(num_avail == 0 ? 1 : num_avail, sizeof(unsigned char));
    if (selected == NULL) {
        ptn_abort_out_of_memory();
    }

    size_t remaining = sample_count;
    while (remaining > 0) {
        size_t index = ptn_mt19937_bounded_index(state, num_avail - 1);
        if (selected[index]) {
            continue;
        }
        selected[index] = 1;
        remaining--;
    }

    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    size_t out = 0;
    for (size_t i = 0; i < num_avail; i++) {
        if ((selected[i] != 0) ^ negative_bitset) {
            if (out > (size_t)INT64_MAX) {
                free(selected);
                ptn_abort_out_of_memory();
            }
            ptn_array_set_entry(
                result.as.array,
                ptn_array_int_key((int64_t)out++),
                ptn_array_key_value(array->entries[i].key)
            );
        }
    }
    free(selected);
    return result;
}

static PtnValue ptn_internal_array_rand(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnArray *array = ptn_internal_expect_array_arg(runtime, "array_rand", 1, "array", args[0]);
    int64_t requested = argc >= 2
        ? ptn_internal_expect_integer_arg(runtime, "array_rand", 2, "num", args[1], line)
        : 1;
    return ptn_array_pick_keys_with_state(
        runtime,
        "array_rand",
        array,
        requested,
        &ptn_global_mt19937_state,
        0
    );
}

