static PtnValue ptn_internal_array_intersect_key(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)line;
    PtnArray *source = ptn_internal_expect_array_arg(runtime, "array_intersect_key", 1, "array", args[0]);
    PtnArray **arrays = ptn_array_set_operation_arrays(runtime, "array_intersect_key", argc, args);
    PtnValue result = ptn_array_key_intersect_or_diff(source, argc - 1, arrays, 1);
    free(arrays);
    return result;
}

typedef enum {
    PTN_ARRAY_SET_VALUE_NONE,
    PTN_ARRAY_SET_VALUE_STRING,
    PTN_ARRAY_SET_VALUE_CALLBACK
} PtnArraySetValueMode;

typedef enum {
    PTN_ARRAY_SET_KEY_NONE,
    PTN_ARRAY_SET_KEY_EXACT,
    PTN_ARRAY_SET_KEY_CALLBACK
} PtnArraySetKeyMode;

static int ptn_array_custom_keys_match(
    PtnRuntime *runtime,
    PtnArrayKey left,
    PtnArrayKey right,
    PtnArraySetKeyMode key_mode,
    PtnValue key_callback,
    size_t line
) {
    if (key_mode == PTN_ARRAY_SET_KEY_NONE) {
        return 1;
    }
    if (key_mode == PTN_ARRAY_SET_KEY_EXACT) {
        return ptn_array_keys_equal(left, right);
    }

    PtnValue left_key = ptn_array_key_value(left);
    PtnValue right_key = ptn_array_key_value(right);
    int matched = ptn_array_user_compare(runtime, key_callback, left_key, right_key, line) == 0;
    ptn_value_destroy(&left_key);
    ptn_value_destroy(&right_key);
    return matched;
}

static int ptn_array_custom_values_match(
    PtnRuntime *runtime,
    PtnValue left,
    PtnValue right,
    PtnArraySetValueMode value_mode,
    PtnValue value_callback,
    size_t line
) {
    if (value_mode == PTN_ARRAY_SET_VALUE_NONE) {
        return 1;
    }
    if (value_mode == PTN_ARRAY_SET_VALUE_STRING) {
        return ptn_array_value_strings_equal(runtime, left, right, line, 0);
    }
    return ptn_array_user_compare(runtime, value_callback, left, right, line) == 0;
}

static int ptn_array_custom_entry_matches_candidate(
    PtnRuntime *runtime,
    PtnArrayEntry *entry,
    PtnArrayEntry *candidate,
    PtnArraySetValueMode value_mode,
    PtnValue value_callback,
    PtnArraySetKeyMode key_mode,
    PtnValue key_callback,
    size_t line
) {
    if (!ptn_array_custom_keys_match(runtime, entry->key, candidate->key, key_mode, key_callback, line)) {
        return 0;
    }
    return ptn_array_custom_values_match(runtime, entry->value, candidate->value, value_mode, value_callback, line);
}

static int ptn_array_custom_entry_matches_array(
    PtnRuntime *runtime,
    PtnArrayEntry *entry,
    PtnArray *array,
    PtnArraySetValueMode value_mode,
    PtnValue value_callback,
    PtnArraySetKeyMode key_mode,
    PtnValue key_callback,
    size_t line
) {
    for (size_t i = 0; i < array->len; i++) {
        PtnArrayEntry *candidate = &array->entries[i];
        if (ptn_array_custom_entry_matches_candidate(
                runtime,
                entry,
                candidate,
                value_mode,
                value_callback,
                key_mode,
                key_callback,
                line
            )) {
            return 1;
        }
    }
    return 0;
}

static PtnValue ptn_array_custom_set_operation(
    PtnRuntime *runtime,
    PtnArray *source,
    size_t array_count,
    PtnArray **arrays,
    PtnArraySetValueMode value_mode,
    PtnValue value_callback,
    PtnArraySetKeyMode key_mode,
    PtnValue key_callback,
    int keep_matches,
    size_t line
) {
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    for (size_t i = 0; i < source->len; i++) {
        PtnArrayEntry *entry = &source->entries[i];
        size_t matched_arrays = 0;
        for (size_t array_index = 0; array_index < array_count; array_index++) {
            int matched = ptn_array_custom_entry_matches_array(
                    runtime,
                    entry,
                    arrays[array_index],
                    value_mode,
                    value_callback,
                    key_mode,
                    key_callback,
                    line
                );
            if (keep_matches && !matched) {
                matched_arrays = 0;
                break;
            }
            if (matched) {
                matched_arrays++;
                if (!keep_matches) {
                    break;
                }
            }
        }
        int keep = keep_matches ? matched_arrays == array_count : matched_arrays == 0;
        if (keep) {
            ptn_array_set_entry(
                result.as.array,
                ptn_array_key_clone(entry->key),
                ptn_value_clone(ptn_array_reindexing_internal_value(entry->value))
            );
        }
    }
    return result;
}

static PtnArray *ptn_array_value_callback_sorted_snapshot(
    PtnRuntime *runtime,
    const char *function_name,
    PtnArray *array,
    PtnValue callback,
    size_t line
) {
    PtnArray *sorted = ptn_array_clone(array);
    ptn_array_user_sort_entries(runtime, function_name, sorted, callback, 0, 0, line);
    return sorted;
}

static int ptn_array_sorted_value_callback_contains(
    PtnRuntime *runtime,
    PtnArray *array,
    PtnValue value,
    PtnValue callback,
    size_t *cursor,
    size_t line
) {
    size_t index = *cursor;
    while (index < array->len) {
        int candidate_order = ptn_array_user_compare(
            runtime,
            callback,
            array->entries[index].value,
            value,
            line
        );
        if (candidate_order < 0) {
            index++;
            continue;
        }
        if (candidate_order == 0) {
            *cursor = index;
            return 1;
        }
        int value_order = ptn_array_user_compare(
            runtime,
            callback,
            value,
            array->entries[index].value,
            line
        );
        *cursor = index;
        return value_order == 0;
    }
    *cursor = index;
    return 0;
}

static size_t ptn_array_index_for_existing_key(PtnArray *array, PtnArrayKey key) {
    PtnArrayEntry *entry = ptn_array_entry_for_key(array, key);
    if (entry == NULL) {
        return SIZE_MAX;
    }
    return (size_t)(entry - array->entries);
}

static PtnValue ptn_array_value_callback_sorted_set_operation(
    PtnRuntime *runtime,
    const char *function_name,
    PtnArray *source,
    size_t array_count,
    PtnArray **arrays,
    PtnValue value_callback,
    int keep_matches,
    size_t line
) {
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    PtnArray *sorted_source = ptn_array_value_callback_sorted_snapshot(
        runtime,
        function_name,
        source,
        value_callback,
        line
    );
    PtnArray **sorted_arrays = NULL;
    size_t *cursors = NULL;
    unsigned char *keep = NULL;
    if (array_count != 0) {
        if (array_count > SIZE_MAX / sizeof(PtnArray *)) {
            ptn_abort_out_of_memory();
        }
        sorted_arrays = calloc(array_count, sizeof(PtnArray *));
        cursors = calloc(array_count, sizeof(size_t));
        if (sorted_arrays == NULL || cursors == NULL) {
            ptn_abort_out_of_memory();
        }
        for (size_t i = 0; i < array_count; i++) {
            sorted_arrays[i] = ptn_array_value_callback_sorted_snapshot(
                runtime,
                function_name,
                arrays[i],
                value_callback,
                line
            );
        }
    }
    if (source->len != 0) {
        keep = calloc(source->len, sizeof(unsigned char));
        if (keep == NULL) {
            ptn_abort_out_of_memory();
        }
    }

    for (size_t i = 0; i < sorted_source->len; i++) {
        PtnArrayEntry *entry = &sorted_source->entries[i];
        size_t matched_arrays = 0;
        for (size_t array_index = 0; array_index < array_count; array_index++) {
            int matched = ptn_array_sorted_value_callback_contains(
                runtime,
                sorted_arrays[array_index],
                entry->value,
                value_callback,
                &cursors[array_index],
                line
            );
            if (keep_matches && !matched) {
                matched_arrays = 0;
                break;
            }
            if (matched) {
                matched_arrays++;
                if (!keep_matches) {
                    break;
                }
            }
        }
        int keep_entry = keep_matches ? matched_arrays == array_count : matched_arrays == 0;
        if (keep_entry) {
            size_t original_index = ptn_array_index_for_existing_key(source, entry->key);
            if (original_index < source->len) {
                keep[original_index] = 1;
            }
        }
    }

    for (size_t i = 0; i < source->len; i++) {
        if (!keep[i]) {
            continue;
        }
        PtnArrayEntry *entry = &source->entries[i];
        ptn_array_set_entry(
            result.as.array,
            ptn_array_key_clone(entry->key),
            ptn_value_clone(ptn_array_reindexing_internal_value(entry->value))
        );
    }

    free(keep);
    for (size_t i = 0; i < array_count; i++) {
        ptn_array_free(sorted_arrays[i]);
    }
    free(sorted_arrays);
    free(cursors);
    ptn_array_free(sorted_source);
    return result;
}

