static size_t ptn_sprintf_normalize_exponent(char *formatted, char conversion) {
    for (char *cursor = formatted; *cursor != '\0'; cursor++) {
        if (*cursor != 'e' && *cursor != 'E') {
            continue;
        }
        *cursor = (conversion == 'E' || conversion == 'G' || conversion == 'H') ? 'E' : 'e';
        cursor++;
        if (*cursor == '+' || *cursor == '-') {
            cursor++;
        }
        size_t removed = 0;
        while (*cursor == '0' && isdigit((unsigned char)cursor[1])) {
            memmove(cursor, cursor + 1, strlen(cursor));
            removed++;
        }
        return removed;
    }
    return 0;
}

static size_t ptn_sprintf_ensure_zero_precision_g_decimal(char **formatted, char conversion) {
    if (conversion != 'g' && conversion != 'G') {
        return 0;
    }
    char *exponent = strchr(*formatted, conversion == 'G' ? 'E' : 'e');
    if (exponent == NULL) {
        exponent = strchr(*formatted, conversion == 'G' ? 'e' : 'E');
    }
    if (exponent == NULL) {
        return 0;
    }
    for (char *cursor = *formatted; cursor < exponent; cursor++) {
        if (*cursor == '.') {
            return 0;
        }
    }
    size_t len = strlen(*formatted);
    size_t exponent_offset = (size_t)(exponent - *formatted);
    char *resized = realloc(*formatted, len + 3);
    if (resized == NULL) {
        ptn_abort_out_of_memory();
    }
    memmove(resized + exponent_offset + 2, resized + exponent_offset, len - exponent_offset + 1);
    resized[exponent_offset] = '.';
    resized[exponent_offset + 1] = '0';
    *formatted = resized;
    return 2;
}

static void ptn_sprintf_append_manual_padding(
    PtnStringBuffer *buffer,
    const char *formatted,
    size_t len,
    const PtnSprintfSpec *spec,
    char pad,
    int left_adjust
) {
    size_t width = spec->has_width && spec->width > 0 ? (size_t)spec->width : 0;
    size_t padding = width > len ? width - len : 0;
    if (!left_adjust) {
        ptn_sprintf_append_repeated(buffer, pad, padding);
    }
    ptn_string_buffer_append_len(buffer, formatted, len);
    if (left_adjust) {
        ptn_sprintf_append_repeated(buffer, pad, padding);
    }
}

static void ptn_sprintf_warn_object_numeric(PtnRuntime *runtime, PtnValue value, const char *target_type, size_t line) {
    value = ptn_value_deref(value);
    const char *class_name = NULL;
    if (value.type == PTN_OBJECT) {
        class_name = value.as.object->class_name;
    } else if (value.type == PTN_EXCEPTION) {
        class_name = value.as.exception->class_name;
    }
    if (class_name == NULL) {
        return;
    }

    char message[256];
    int written = snprintf(
        message,
        sizeof(message),
        "Object of class %s could not be converted to %s",
        class_name,
        target_type
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_spaced_warning(&runtime->diagnostics, message, line);
}

static int64_t ptn_sprintf_value_to_integer(PtnRuntime *runtime, PtnValue value, size_t line) {
    value = ptn_value_deref(value);
    int64_t integer = 0;
    if (ptn_fast_integer_value(value, &integer)) {
        return integer;
    }
    if (value.type == PTN_FLOAT) {
        return (int64_t)value.as.floating;
    }
    ptn_sprintf_warn_object_numeric(runtime, value, "int", line);
    return ptn_number_to_integer(ptn_to_number(value));
}

static void ptn_sprintf_warn_float_int_cast(PtnRuntime *runtime, double floating, size_t line) {
    char value_text[PTN_FLOAT_FORMAT_BUFFER_SIZE];
    ptn_format_var_dump_float(
        floating,
        ptn_runtime_serialize_precision(runtime),
        value_text,
        sizeof(value_text)
    );

    char message[PTN_FLOAT_FORMAT_BUFFER_SIZE + 96];
    int written = snprintf(
        message,
        sizeof(message),
        "The float %s is not representable as an int, cast occurred",
        value_text
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_spaced_warning(&runtime->diagnostics, message, line);
}

static uint64_t ptn_sprintf_float_to_unsigned(double floating) {
    if (!isfinite(floating)) {
        return 0;
    }

    const double modulus = 18446744073709551616.0;
    double wrapped = fmod(floating, modulus);
    if (wrapped < 0) {
        wrapped += modulus;
    }
    if (wrapped >= modulus) {
        wrapped = 0;
    }
    return (uint64_t)wrapped;
}

static uint64_t ptn_sprintf_value_to_unsigned(PtnRuntime *runtime, PtnValue value, size_t line) {
    value = ptn_value_deref(value);
    int64_t integer = 0;
    if (ptn_fast_integer_value(value, &integer)) {
        return (uint64_t)integer;
    }
    if (value.type == PTN_FLOAT) {
        const double signed_int_min = -9223372036854775808.0;
        const double signed_int_limit = 9223372036854775808.0;
        if (value.as.floating < signed_int_min || value.as.floating >= signed_int_limit) {
            ptn_sprintf_warn_float_int_cast(runtime, value.as.floating, line);
            return ptn_sprintf_float_to_unsigned(value.as.floating);
        }
        return (uint64_t)((int64_t)value.as.floating);
    }
    return (uint64_t)ptn_sprintf_value_to_integer(runtime, value, line);
}

static double ptn_sprintf_value_to_double(PtnRuntime *runtime, PtnValue value, size_t line) {
    ptn_sprintf_warn_object_numeric(runtime, value, "float", line);
    return ptn_value_to_double(value);
}

static void ptn_sprintf_append_string(PtnStringBuffer *buffer, PtnStringOperand string, const PtnSprintfSpec *spec) {
    size_t len = string.len;
    if (spec->has_precision && spec->precision >= 0 && (size_t)spec->precision < len) {
        len = (size_t)spec->precision;
    }
    size_t width = spec->has_width && spec->width > 0 ? (size_t)spec->width : 0;
    size_t padding = width > len ? width - len : 0;
    char pad = spec->pad_char != '\0' ? spec->pad_char : (spec->zero_pad ? '0' : ' ');
    if (!spec->left_adjust) {
        ptn_sprintf_append_repeated(buffer, pad, padding);
    }
    ptn_string_buffer_append_len(buffer, string.data, len);
    if (spec->left_adjust) {
        ptn_sprintf_append_repeated(buffer, ' ', padding);
    }
}

static void ptn_sprintf_append_char(PtnStringBuffer *buffer, int64_t value, const PtnSprintfSpec *spec) {
    (void)spec;
    ptn_string_buffer_append_char(buffer, (char)((unsigned char)value));
}

static void ptn_sprintf_append_binary(PtnStringBuffer *buffer, uint64_t value, const PtnSprintfSpec *spec) {
    char digits[65];
    size_t len = 0;
    if (value == 0) {
        digits[len++] = '0';
    } else {
        while (value != 0) {
            digits[len++] = (value & 1) ? '1' : '0';
            value >>= 1;
        }
        for (size_t i = 0; i < len / 2; i++) {
            char tmp = digits[i];
            digits[i] = digits[len - 1 - i];
            digits[len - 1 - i] = tmp;
        }
    }

    size_t precision_padding = 0;
    size_t value_len = len + precision_padding;
    size_t width = spec->has_width && spec->width > 0 ? (size_t)spec->width : 0;
    size_t width_padding = width > value_len ? width - value_len : 0;
    char pad = spec->pad_char != '\0' ? spec->pad_char : (spec->zero_pad && !spec->left_adjust ? '0' : ' ');
    if (!spec->left_adjust) {
        ptn_sprintf_append_repeated(buffer, pad, width_padding);
    }
    ptn_sprintf_append_repeated(buffer, '0', precision_padding);
    ptn_string_buffer_append_len(buffer, digits, len);
    if (spec->left_adjust) {
        ptn_sprintf_append_repeated(buffer, ' ', width_padding);
    }
}

static int ptn_sprintf_unsigned_precision_suppresses_digits(char conversion, const PtnSprintfSpec *spec) {
    return spec->has_precision && (conversion == 'o' || conversion == 'x' || conversion == 'X');
}

static void ptn_sprintf_append_suppressed_unsigned(PtnStringBuffer *buffer, const PtnSprintfSpec *spec) {
    size_t width = spec->has_width && spec->width > 0 ? (size_t)spec->width : 0;
    char pad = spec->pad_char != '\0' ? spec->pad_char : (spec->zero_pad && !spec->left_adjust ? '0' : ' ');
    ptn_sprintf_append_repeated(buffer, pad, width);
}

static void ptn_sprintf_throw_unknown_specifier(PtnRuntime *runtime, char specifier) {
    char message[96];
    int written = snprintf(message, sizeof(message), "Unknown format specifier \"%c\"", specifier);
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "ValueError", message);
}

static void ptn_sprintf_throw_argument_count(PtnRuntime *runtime, size_t required, size_t given, size_t line) {
    char message[96];
    int written = snprintf(message, sizeof(message), "%zu arguments are required, %zu given", required, given);
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception_at(runtime, "ArgumentCountError", message, runtime->source_path, line);
}

static void ptn_sprintf_cap_float_precision(PtnRuntime *runtime, const char *function_name, PtnSprintfSpec *spec, size_t line) {
    const int max_precision = 53;
    if (!spec->has_precision || spec->precision <= max_precision) {
        return;
    }
    char message[128];
    int written = snprintf(
        message,
        sizeof(message),
        "%s(): Requested precision of %d digits was truncated to PHP maximum of %d digits",
        function_name,
        spec->precision,
        max_precision
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    if (ptn_diagnostics_should_emit(&runtime->diagnostics, PTN_E_NOTICE)) {
        fputc('\n', stdout);
    }
    ptn_emit_notice(&runtime->diagnostics, message, line);
    spec->precision = max_precision;
}

static PtnValue ptn_internal_sprintf_named_mode(
    PtnRuntime *runtime,
    const char *function_name,
    size_t argc,
    const PtnValue *args,
    size_t line,
    int legacy_stream_resource_text
) {
    PtnStringOperand format = ptn_internal_expect_string_arg(runtime, function_name, 1, "format", args[0], line);
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    size_t arg_index = 1;
    size_t required_arg_count = ptn_sprintf_required_argument_count(format);

    for (size_t i = 0; i < format.len; i++) {
        char byte = format.data[i];
        if (byte != '%') {
            ptn_string_buffer_append_char(&output, byte);
            continue;
        }
        i++;
        PtnSprintfSpec spec = {0};
        size_t selected_arg_index = 0;
        int has_positional_arg = 0;
        if (i < format.len && format.data[i] == '$') {
            ptn_string_operand_free(format);
            free(output.data);
            ptn_throw_exception(
                runtime,
                "ValueError",
                "Argument number specifier must be greater than zero and less than 2147483647"
            );
            return ptn_null();
        }
        size_t positional_scan = i;
        if (positional_scan < format.len && isdigit((unsigned char)format.data[positional_scan])) {
            int position = 0;
            int position_overflow = 0;
            while (positional_scan < format.len && isdigit((unsigned char)format.data[positional_scan])) {
                int digit = format.data[positional_scan] - '0';
                if (position > (INT_MAX - digit) / 10) {
                    position_overflow = 1;
                } else if (!position_overflow) {
                    position = position * 10 + digit;
                }
                positional_scan++;
            }
            if (positional_scan < format.len && format.data[positional_scan] == '$') {
                if (position_overflow) {
                    ptn_string_operand_free(format);
                    free(output.data);
                    ptn_throw_exception(
                        runtime,
                        "ValueError",
                        "Argument number specifier must be greater than zero and less than 2147483647"
                    );
                    return ptn_null();
                }
                if (position <= 0) {
                    ptn_string_operand_free(format);
                    free(output.data);
                    ptn_throw_exception(runtime, "ValueError", "Argument number specifier must be greater than zero");
                    return ptn_null();
                }
                selected_arg_index = (size_t)position;
                has_positional_arg = 1;
                i = positional_scan + 1;
            }
        }
        while (i < format.len) {
            switch (format.data[i]) {
                case '-':
                    spec.left_adjust = 1;
                    i++;
                    continue;
                case '+':
                    spec.show_sign = 1;
                    i++;
                    continue;
                case ' ':
                    spec.ignored_space = 1;
                    i++;
                    continue;
                case '0':
                    spec.zero_pad = 1;
                    i++;
                    continue;
                case '#':
                    spec.alternate = 1;
                    i++;
                    continue;
                case '\'':
                    if (i + 1 >= format.len) {
                        ptn_string_operand_free(format);
                        free(output.data);
                        ptn_throw_exception(runtime, "ValueError", "Missing padding character");
                    }
                    spec.pad_char = format.data[i + 1];
                    i += 2;
                    continue;
                default:
                    break;
            }
            break;
        }

        if (i < format.len && isdigit((unsigned char)format.data[i])) {
            spec.has_width = 1;
            spec.width = ptn_sprintf_parse_bounded_decimal(runtime, format.data, format.len, &i, "Width", 0);
            if (runtime->exceptions->active_exception != NULL) {
                ptn_string_operand_free(format);
                free(output.data);
                return ptn_null();
            }
        } else if (i < format.len && format.data[i] == '*') {
            size_t width_arg_index = ptn_sprintf_star_argument_index(format.data, format.len, &i, &arg_index);
            if (width_arg_index >= argc) {
                ptn_string_operand_free(format);
                free(output.data);
                size_t required = required_arg_count > width_arg_index + 1 ? required_arg_count : width_arg_index + 1;
                ptn_sprintf_throw_argument_count(runtime, required, argc, line);
                return ptn_null();
            }
            int64_t width = 0;
            if (!ptn_sprintf_star_integer(runtime, args[width_arg_index], "Width", 0, &width)) {
                ptn_string_operand_free(format);
                free(output.data);
                return ptn_null();
            }
            spec.has_width = 1;
            spec.width = (int)width;
        }
        if (i < format.len && format.data[i] == '.') {
            i++;
            spec.has_precision = 1;
            if (i < format.len && format.data[i] == '*') {
                size_t precision_arg_index = ptn_sprintf_star_argument_index(format.data, format.len, &i, &arg_index);
                if (precision_arg_index >= argc) {
                    ptn_string_operand_free(format);
                    free(output.data);
                    size_t required = required_arg_count > precision_arg_index + 1 ? required_arg_count : precision_arg_index + 1;
                    ptn_sprintf_throw_argument_count(runtime, required, argc, line);
                    return ptn_null();
                }
                int64_t precision = 0;
                if (!ptn_sprintf_star_integer(runtime, args[precision_arg_index], "Precision", -1, &precision)) {
                    ptn_string_operand_free(format);
                    free(output.data);
                    return ptn_null();
                }
                spec.precision = (int)precision;
            } else {
                spec.precision = ptn_sprintf_parse_bounded_decimal(runtime, format.data, format.len, &i, "Precision", 0);
                if (runtime->exceptions->active_exception != NULL) {
                    ptn_string_operand_free(format);
                    free(output.data);
                    return ptn_null();
                }
            }
        }
        while (i < format.len && strchr("lLjzt", format.data[i]) != NULL) {
            i++;
        }
        if (i >= format.len) {
            ptn_string_operand_free(format);
            free(output.data);
            ptn_throw_exception(runtime, "ValueError", "Missing format specifier at end of string");
        }

        char conversion = format.data[i];
        if (
            spec.has_precision &&
            spec.precision == -1 &&
            conversion != 'g' &&
            conversion != 'G' &&
            conversion != 'h' &&
            conversion != 'H'
        ) {
            ptn_string_operand_free(format);
            free(output.data);
            ptn_throw_exception(runtime, "ValueError", "Precision -1 is only supported for %g, %G, %h and %H");
            return ptn_null();
        }
        if (conversion == '%' && !ptn_sprintf_percent_consumes_argument(&spec, has_positional_arg)) {
            ptn_string_buffer_append_char(&output, '%');
            continue;
        }
        if (!has_positional_arg) {
            selected_arg_index = arg_index++;
        }
        if (selected_arg_index >= argc) {
            ptn_string_operand_free(format);
            free(output.data);
            size_t required = required_arg_count > selected_arg_index + 1 ? required_arg_count : selected_arg_index + 1;
            ptn_sprintf_throw_argument_count(runtime, required, argc, line);
            return ptn_null();
        }
        PtnValue arg = args[selected_arg_index];

        if (conversion == '%') {
            ptn_string_buffer_append_char(&output, '%');
            continue;
        }

        switch (conversion) {
            case 's': {
                PtnValue value = ptn_value_deref(arg);
                if (value.type == PTN_ARRAY) {
                    ptn_emit_spaced_warning(&runtime->diagnostics, "Array to string conversion", line);
                }
                PtnStringOperand string = legacy_stream_resource_text && value.type == PTN_RESOURCE
                    ? ptn_string_operand_borrowed("Resource")
                    : ptn_value_to_string_operand_with_runtime_skipping_current_trace_frame(runtime, value, line);
                ptn_sprintf_append_string(&output, string, &spec);
                ptn_string_operand_free(string);
                break;
            }
            case 'c':
                ptn_sprintf_append_char(&output, ptn_sprintf_value_to_integer(runtime, arg, line), &spec);
                break;
            case 'b':
                ptn_sprintf_append_binary(&output, (uint64_t)ptn_sprintf_value_to_integer(runtime, arg, line), &spec);
                break;
            case 'd':
            case 'i': {
                int manual_padding = spec.pad_char != '\0';
                PtnSprintfSpec effective = spec;
                if (manual_padding) {
                    effective.has_width = 0;
                    effective.left_adjust = 0;
                    effective.zero_pad = 0;
                }
                char c_format[64];
                ptn_sprintf_build_numeric_format(
                    c_format,
                    sizeof(c_format),
                    &effective,
                    conversion,
                    1,
                    1,
                    0
                );
                size_t formatted_len = 0;
                char *formatted = ptn_sprintf_format_snprintf_signed(
                    c_format,
                    (long long)ptn_sprintf_value_to_integer(runtime, arg, line),
                    &formatted_len
                );
                if (manual_padding) {
                    ptn_sprintf_append_manual_padding(
                        &output,
                        formatted,
                        formatted_len,
                        &spec,
                        spec.pad_char,
                        spec.left_adjust
                    );
                } else {
                    ptn_string_buffer_append_len(&output, formatted, formatted_len);
                }
                free(formatted);
                break;
            }
            case 'u':
            case 'o':
            case 'x':
            case 'X': {
                if (ptn_sprintf_unsigned_precision_suppresses_digits(conversion, &spec)) {
                    ptn_sprintf_append_suppressed_unsigned(&output, &spec);
                    break;
                }
                int manual_padding = spec.pad_char != '\0';
                PtnSprintfSpec effective = spec;
                if (manual_padding) {
                    effective.has_width = 0;
                    effective.left_adjust = 0;
                    effective.zero_pad = 0;
                }
                char c_format[64];
                ptn_sprintf_build_numeric_format(
                    c_format,
                    sizeof(c_format),
                    &effective,
                    conversion,
                    1,
                    1,
                    0
                );
                size_t formatted_len = 0;
                char *formatted = ptn_sprintf_format_snprintf_unsigned(
                    c_format,
                    (unsigned long long)ptn_sprintf_value_to_unsigned(runtime, arg, line),
                    &formatted_len
                );
                if (manual_padding) {
                    ptn_sprintf_append_manual_padding(
                        &output,
                        formatted,
                        formatted_len,
                        &spec,
                        spec.pad_char,
                        spec.left_adjust
                    );
                } else {
                    ptn_string_buffer_append_len(&output, formatted, formatted_len);
                }
                free(formatted);
                break;
            }
            case 'f':
            case 'F':
            case 'e':
            case 'E':
            case 'g':
            case 'G':
            case 'h':
            case 'H': {
                int manual_padding = spec.pad_char != '\0' || (spec.left_adjust && spec.zero_pad && spec.has_width);
                PtnSprintfSpec effective = spec;
                ptn_sprintf_cap_float_precision(runtime, function_name, &effective, line);
                char c_conversion = conversion == 'h' ? 'g' : (conversion == 'H' ? 'G' : conversion);
                if (effective.has_precision && effective.precision == -1) {
                    effective.precision = 17;
                }
                if (manual_padding) {
                    effective.has_width = 0;
                    effective.left_adjust = 0;
                    effective.zero_pad = 0;
                }
                char c_format[64];
                ptn_sprintf_build_numeric_format(
                    c_format,
                    sizeof(c_format),
                    &effective,
                    c_conversion,
                    0,
                    1,
                    1
                );
                size_t formatted_len = 0;
                char *formatted = ptn_sprintf_format_snprintf_double(
                    c_format,
                    ptn_sprintf_value_to_double(runtime, arg, line),
                    &formatted_len
                );
                if (spec.has_precision && spec.precision == 0) {
                    formatted_len += ptn_sprintf_ensure_zero_precision_g_decimal(&formatted, conversion);
                }
                if (conversion == 'e' || conversion == 'E' || conversion == 'g' || conversion == 'G' || conversion == 'h' || conversion == 'H') {
                    size_t original_len = formatted_len;
                    size_t removed = ptn_sprintf_normalize_exponent(formatted, conversion);
                    formatted_len = strlen(formatted);
                    if (
                        removed != 0 &&
                        !manual_padding &&
                        spec.has_width &&
                        spec.width > 0 &&
                        (size_t)spec.width >= original_len &&
                        original_len > formatted_len
                    ) {
                        char *padded = malloc(original_len + 1);
                        if (padded == NULL) {
                            ptn_abort_out_of_memory();
                        }
                        size_t padding = original_len - formatted_len;
                        if (spec.left_adjust) {
                            memcpy(padded, formatted, formatted_len);
                            memset(padded + formatted_len, ' ', padding);
                        } else {
                            memset(padded, ' ', padding);
                            memcpy(padded + padding, formatted, formatted_len);
                        }
                        padded[original_len] = '\0';
                        free(formatted);
                        formatted = padded;
                        formatted_len = original_len;
                    }
                }
                if (manual_padding) {
                    ptn_sprintf_append_manual_padding(
                        &output,
                        formatted,
                        formatted_len,
                        &spec,
                        spec.pad_char != '\0' ? spec.pad_char : '0',
                        spec.left_adjust
                    );
                } else {
                    ptn_string_buffer_append_len(&output, formatted, formatted_len);
                }
                free(formatted);
                break;
            }
            default:
                ptn_string_operand_free(format);
                free(output.data);
                ptn_sprintf_throw_unknown_specifier(runtime, conversion);
        }
    }

    ptn_string_operand_free(format);
    return ptn_owned_string_len(output.data, output.len);
}

static PtnValue ptn_internal_sprintf_named(PtnRuntime *runtime, const char *function_name, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_sprintf_named_mode(runtime, function_name, argc, args, line, 0);
}

static PtnValue ptn_internal_sprintf(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_sprintf_named(runtime, "sprintf", argc, args, line);
}

static PtnValue ptn_internal_printf(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnValue formatted = ptn_internal_sprintf_named(runtime, "printf", argc, args, line);
    if (ptn_value_deref(formatted).type != PTN_STRING) {
        return formatted;
    }
    PtnValue string_value = ptn_value_deref(formatted);
    ptn_output_write(runtime, (const char *)string_value.as.string.data, string_value.as.string.len);
    if (string_value.as.string.len > (size_t)INT64_MAX) {
        ptn_value_drop(&formatted);
        ptn_abort_out_of_memory();
    }
    int64_t len = (int64_t)string_value.as.string.len;
    ptn_value_drop(&formatted);
    return ptn_int(len);
}

static int ptn_stream_mode_is_append(PtnResource *resource);
static size_t ptn_stream_write_filtered(
    PtnRuntime *runtime,
    const char *function_name,
    PtnResource *resource,
    const char *data,
    size_t len,
    size_t line
);

static PtnValue ptn_internal_write_formatted_stream(
    PtnRuntime *runtime,
    const char *function_name,
    PtnValue stream_value,
    PtnValue formatted,
    size_t line
) {
    PtnValue stream = ptn_value_deref(stream_value);
    if (stream.type != PTN_RESOURCE) {
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "%s(): Argument #1 ($stream) must be of type resource, %s given",
            function_name,
            ptn_offset_container_type_name(stream)
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_value_drop(&formatted);
        ptn_throw_exception(runtime, "TypeError", message);
        return ptn_null();
    }
    if (!ptn_stream_resource_is_open(stream.as.resource)) {
        ptn_value_drop(&formatted);
        char message[96];
        int written = snprintf(
            message,
            sizeof(message),
            "%s(): supplied resource is not a valid stream resource",
            function_name
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "TypeError", message);
        return ptn_null();
    }

    PtnValue string_value = ptn_value_deref(formatted);
    if (string_value.type != PTN_STRING) {
        return formatted;
    }
    int64_t append_position = -1;
    if (ptn_stream_mode_is_append(stream.as.resource)) {
        append_position = ptn_stream_tell(stream.as.resource);
    }
    size_t written = ptn_stream_write_filtered(
        runtime,
        function_name,
        stream.as.resource,
        (const char *)string_value.as.string.data,
        string_value.as.string.len,
        line
    );
    if (written != string_value.as.string.len) {
        ptn_value_drop(&formatted);
        ptn_emit_warning(&runtime->diagnostics, "fprintf(): failed to write formatted stream output", line);
        return ptn_bool(0);
    }
    if (string_value.as.string.len > (size_t)INT64_MAX) {
        ptn_value_drop(&formatted);
        ptn_abort_out_of_memory();
    }
    if (append_position >= 0) {
        if (append_position > INT64_MAX - (int64_t)written) {
            ptn_value_drop(&formatted);
            ptn_abort_out_of_memory();
        }
        int64_t logical_position = append_position + (int64_t)written;
        if (ptn_stream_tell(stream.as.resource) != logical_position) {
            (void)ptn_stream_seek(stream.as.resource, logical_position, SEEK_SET);
        }
    }
    int64_t len = (int64_t)string_value.as.string.len;
    ptn_value_drop(&formatted);
    return ptn_int(len);
}

static PtnValue ptn_internal_fprintf(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnValue formatted = ptn_internal_sprintf_named_mode(runtime, "fprintf", argc - 1, args + 1, line, 1);
    return ptn_internal_write_formatted_stream(runtime, "fprintf", args[0], formatted, line);
}

static PtnValue ptn_internal_vsprintf_named_mode(
    PtnRuntime *runtime,
    const char *function_name,
    PtnValue format_value,
    PtnValue values_value,
    size_t line,
    int legacy_stream_resource_text
) {
    size_t format_position = strcmp(function_name, "vfprintf") == 0 ? 2 : 1;
    size_t values_position = strcmp(function_name, "vfprintf") == 0 ? 3 : 2;
    PtnStringOperand checked_format =
        ptn_internal_expect_string_arg(runtime, function_name, format_position, "format", format_value, line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(checked_format);
        return ptn_null();
    }
    ptn_string_operand_free(checked_format);

    values_value = ptn_value_deref(values_value);
    if (values_value.type != PTN_ARRAY) {
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "%s(): Argument #%zu ($values) must be of type array, %s given",
            function_name,
            values_position,
            ptn_internal_array_arg_type_name(values_value)
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "TypeError", message);
        return ptn_null();
    }
    PtnArray *values = values_value.as.array;
    if (values->len > SIZE_MAX - 1) {
        ptn_abort_out_of_memory();
    }
    PtnValue *expanded = malloc((values->len + 1) * sizeof(PtnValue));
    if (expanded == NULL) {
        ptn_abort_out_of_memory();
    }
    expanded[0] = format_value;
    for (size_t i = 0; i < values->len; i++) {
        expanded[i + 1] = values->entries[i].value;
    }
    PtnValue result = ptn_internal_sprintf_named_mode(
        runtime,
        function_name,
        values->len + 1,
        expanded,
        line,
        legacy_stream_resource_text
    );
    free(expanded);
    return result;
}

static PtnValue ptn_internal_vsprintf_named(
    PtnRuntime *runtime,
    const char *function_name,
    PtnValue format_value,
    PtnValue values_value,
    size_t line
) {
    return ptn_internal_vsprintf_named_mode(runtime, function_name, format_value, values_value, line, 0);
}

static PtnValue ptn_internal_vsprintf(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    return ptn_internal_vsprintf_named(runtime, "vsprintf", args[0], args[1], line);
}

static PtnValue ptn_internal_vprintf(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnValue formatted = ptn_internal_vsprintf_named(runtime, "vprintf", args[0], args[1], line);
    if (ptn_value_deref(formatted).type != PTN_STRING) {
        return formatted;
    }
    PtnValue string_value = ptn_value_deref(formatted);
    ptn_output_write(runtime, (const char *)string_value.as.string.data, string_value.as.string.len);
    if (string_value.as.string.len > (size_t)INT64_MAX) {
        ptn_value_drop(&formatted);
        ptn_abort_out_of_memory();
    }
    int64_t len = (int64_t)string_value.as.string.len;
    ptn_value_drop(&formatted);
    return ptn_int(len);
}

static PtnValue ptn_internal_vfprintf(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnValue formatted = ptn_internal_vsprintf_named_mode(runtime, "vfprintf", args[1], args[2], line, 1);
    return ptn_internal_write_formatted_stream(runtime, "vfprintf", args[0], formatted, line);
}

typedef struct {
    char conversion;
    int suppress_assignment;
    int positional;
    size_t target_index;
    int has_width;
    size_t width;
    int scanset_negated;
    unsigned char scanset[256];
} PtnScanfSpec;

typedef struct {
    size_t result_slots;
    size_t assigned_slots;
    int has_first_conversion;
    char first_conversion;
} PtnScanfFormatInfo;

static void ptn_scanf_throw_bad_conversion(PtnRuntime *runtime, char conversion) {
    if (conversion == '\0') {
        ptn_throw_exception(runtime, "ValueError", "Bad scan conversion character \"");
        return;
    }
    char message[64];
    int written = snprintf(message, sizeof(message), "Bad scan conversion character \"%c\"", conversion);
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "ValueError", message);
}

static int ptn_scanf_parse_unsigned_decimal(
    PtnStringOperand format,
    size_t *offset,
    size_t *value,
    int *overflow
) {
    size_t parsed = 0;
    int saw_digit = 0;
    *overflow = 0;
    while (*offset < format.len && isdigit((unsigned char)format.data[*offset])) {
        saw_digit = 1;
        size_t digit = (size_t)(format.data[*offset] - '0');
        if (parsed > (SIZE_MAX - digit) / 10) {
            *overflow = 1;
        } else if (!*overflow) {
            parsed = parsed * 10 + digit;
        }
        (*offset)++;
    }
    *value = parsed;
    return saw_digit;
}

static int ptn_scanf_set_contains(const unsigned char set[256], unsigned char byte) {
    return set[byte] != 0;
}

static int ptn_scanf_parse_scanset(PtnStringOperand format, size_t *offset, PtnScanfSpec *spec, char *bad_conversion) {
    memset(spec->scanset, 0, sizeof(spec->scanset));
    spec->conversion = '[';
    spec->scanset_negated = 0;
    (*offset)++;
    if (*offset < format.len && format.data[*offset] == '^') {
        spec->scanset_negated = 1;
        (*offset)++;
    }
    int saw_member = 0;
    unsigned char previous = 0;
    int has_previous = 0;
    if (*offset < format.len && format.data[*offset] == ']') {
        spec->scanset[(unsigned char)']'] = 1;
        previous = (unsigned char)']';
        has_previous = 1;
        saw_member = 1;
        (*offset)++;
    }
    while (*offset < format.len && format.data[*offset] != ']') {
        unsigned char current = (unsigned char)format.data[*offset];
        if (
            current == '-'
            && has_previous
            && *offset + 1 < format.len
            && format.data[*offset + 1] != ']'
        ) {
            unsigned char end = (unsigned char)format.data[*offset + 1];
            if (previous <= end) {
                for (unsigned int byte = previous; byte <= end; byte++) {
                    spec->scanset[byte] = 1;
                }
            } else {
                for (unsigned int byte = end; byte <= previous; byte++) {
                    spec->scanset[byte] = 1;
                }
            }
            previous = end;
            has_previous = 1;
            saw_member = 1;
            *offset += 2;
            continue;
        }
        spec->scanset[current] = 1;
        previous = current;
        has_previous = 1;
        saw_member = 1;
        (*offset)++;
    }
    if (*offset >= format.len || !saw_member) {
        *bad_conversion = '[';
        return 0;
    }
    return 1;
}

static int ptn_scanf_parse_spec(
    PtnStringOperand format,
    size_t *offset,
    size_t *next_target,
    PtnScanfSpec *spec,
    char *bad_conversion,
    int *argument_index_out_of_range
) {
    memset(spec, 0, sizeof(*spec));
    *bad_conversion = '\0';
    *argument_index_out_of_range = 0;
    if (*offset >= format.len) {
        return 0;
    }

    if (format.data[*offset] == '*') {
        spec->suppress_assignment = 1;
        (*offset)++;
    }

    size_t digits_start = *offset;
    size_t number = 0;
    int overflow = 0;
    int has_digits = ptn_scanf_parse_unsigned_decimal(format, offset, &number, &overflow);
    if (has_digits && *offset < format.len && format.data[*offset] == '$') {
        if (number == 0 || overflow || number > INT_MAX) {
            *argument_index_out_of_range = 1;
            return 0;
        }
        spec->positional = 1;
        spec->target_index = number - 1;
        (*offset)++;
    } else if (has_digits) {
        spec->has_width = 1;
        spec->width = overflow ? SIZE_MAX : number;
        if (spec->width == 0) {
            spec->width = SIZE_MAX;
        }
    }

    while (*offset < format.len && strchr("hlLjzt", format.data[*offset]) != NULL) {
        (*offset)++;
    }
    if (*offset >= format.len) {
        return 0;
    }

    if (format.data[*offset] == '[') {
        if (!ptn_scanf_parse_scanset(format, offset, spec, bad_conversion)) {
            return 0;
        }
    } else {
        spec->conversion = format.data[*offset];
        if (strchr("scduxXiofFeEgGn", spec->conversion) == NULL) {
            *bad_conversion = spec->conversion;
            return 0;
        }
    }

    if (!spec->suppress_assignment) {
        if (!spec->positional) {
            spec->target_index = (*next_target)++;
        }
    } else {
        spec->target_index = SIZE_MAX;
    }
    (void)digits_start;
    return 1;
}

static void ptn_scanf_format_info_destroy_seen(unsigned char *seen) {
    if (seen != NULL) {
        free(seen);
    }
}

static int ptn_scanf_format_info(
    PtnRuntime *runtime,
    const char *function_name,
    PtnStringOperand format,
    size_t output_count,
    int exact_output_count,
    size_t line,
    PtnScanfFormatInfo *info
) {
    info->result_slots = 0;
    info->assigned_slots = 0;
    info->has_first_conversion = 0;
    info->first_conversion = '\0';
    size_t next_target = 0;
    unsigned char *seen = NULL;
    size_t seen_capacity = 0;

    for (size_t fi = 0; fi < format.len; fi++) {
        if (format.data[fi] != '%') {
            continue;
        }
        fi++;
        if (fi < format.len && format.data[fi] == '%') {
            continue;
        }

        PtnScanfSpec spec;
        char bad_conversion = '\0';
        int argument_index_out_of_range = 0;
        if (!ptn_scanf_parse_spec(format, &fi, &next_target, &spec, &bad_conversion, &argument_index_out_of_range)) {
            ptn_scanf_format_info_destroy_seen(seen);
            if (argument_index_out_of_range) {
                ptn_throw_exception(runtime, "ValueError", "\"%n$\" argument index out of range");
            } else {
                ptn_scanf_throw_bad_conversion(runtime, bad_conversion);
            }
            (void)line;
            return 0;
        }
        if (!info->has_first_conversion) {
            info->has_first_conversion = 1;
            info->first_conversion = spec.conversion;
        }
        if (spec.suppress_assignment) {
            continue;
        }
        if (output_count != 0 && spec.positional && spec.target_index >= output_count) {
            ptn_scanf_format_info_destroy_seen(seen);
            ptn_throw_exception(runtime, "ValueError", "\"%n$\" argument index out of range");
            return 0;
        }
        if (spec.target_index >= seen_capacity) {
            size_t new_capacity = seen_capacity == 0 ? 8 : seen_capacity;
            while (new_capacity <= spec.target_index) {
                if (new_capacity > SIZE_MAX / 2) {
                    ptn_abort_out_of_memory();
                }
                new_capacity *= 2;
            }
            unsigned char *new_seen = realloc(seen, new_capacity);
            if (new_seen == NULL) {
                ptn_abort_out_of_memory();
            }
            memset(new_seen + seen_capacity, 0, new_capacity - seen_capacity);
            seen = new_seen;
            seen_capacity = new_capacity;
        }
        if (seen[spec.target_index]) {
            ptn_scanf_format_info_destroy_seen(seen);
            ptn_throw_exception(runtime, "ValueError", "Variable is assigned by multiple \"%n$\" conversion specifiers");
            return 0;
        }
        seen[spec.target_index] = 1;
        info->assigned_slots++;
        if (spec.target_index + 1 > info->result_slots) {
            info->result_slots = spec.target_index + 1;
        }
    }

    if (output_count != 0) {
        if (output_count > info->assigned_slots) {
            ptn_scanf_format_info_destroy_seen(seen);
            ptn_throw_exception(runtime, "ValueError", "Variable is not assigned by any conversion specifiers");
            return 0;
        }
        if (exact_output_count && output_count < info->assigned_slots) {
            ptn_scanf_format_info_destroy_seen(seen);
            ptn_throw_exception(runtime, "ValueError", "Different numbers of variable names and field specifiers");
            return 0;
        }
        for (size_t i = 0; i < output_count; i++) {
            if (i >= seen_capacity || !seen[i]) {
                ptn_scanf_format_info_destroy_seen(seen);
                ptn_throw_exception(runtime, "ValueError", "Variable is not assigned by any conversion specifiers");
                return 0;
            }
        }
    }

    ptn_scanf_format_info_destroy_seen(seen);
    (void)function_name;
    return 1;
}

static size_t ptn_scanf_conversion_limit(PtnScanfSpec spec, size_t available) {
    if (!spec.has_width || spec.width > available) {
        return available;
    }
    return spec.width;
}

static int ptn_scanf_match_integer(
    const char *input,
    size_t input_len,
    size_t *offset,
    int base,
    PtnValue *parsed
) {
    size_t available = input_len - *offset;
    char *copy = ptn_duplicate_string_len(input + *offset, available);
    char *end = copy;
    errno = 0;
    long long integer = strtoll(copy, &end, base);
    if (end == copy) {
        free(copy);
        return 0;
    }
    *parsed = ptn_int((int64_t)integer);
    *offset += (size_t)(end - copy);
    free(copy);
    return 1;
}

static int ptn_scanf_match_unsigned(
    const char *input,
    size_t input_len,
    size_t *offset,
    PtnValue *parsed
) {
    size_t available = input_len - *offset;
    char *copy = ptn_duplicate_string_len(input + *offset, available);
    char *end = copy;
    errno = 0;
    unsigned long long integer = strtoull(copy, &end, 10);
    if (end == copy) {
        free(copy);
        return 0;
    }
    if (integer <= (unsigned long long)INT64_MAX) {
        *parsed = ptn_int((int64_t)integer);
    } else {
        char buffer[32];
        int written = snprintf(buffer, sizeof(buffer), "%llu", integer);
        if (written < 0 || (size_t)written >= sizeof(buffer)) {
            ptn_abort_out_of_memory();
        }
        *parsed = ptn_owned_string_len(ptn_duplicate_string_len(buffer, (size_t)written), (size_t)written);
    }
    *offset += (size_t)(end - copy);
    free(copy);
    return 1;
}

static int ptn_scanf_match_float(
    const char *input,
    size_t input_len,
    size_t *offset,
    PtnValue *parsed
) {
    size_t available = input_len - *offset;
    char *copy = ptn_duplicate_string_len(input + *offset, available);
    char *end = copy;
    errno = 0;
    double floating = strtod(copy, &end);
    if (end == copy) {
        free(copy);
        return 0;
    }
    *parsed = ptn_float(floating);
    *offset += (size_t)(end - copy);
    free(copy);
    return 1;
}

static int ptn_scanf_match_value(
    PtnScanfSpec spec,
    const char *input,
    size_t input_len,
    size_t *offset,
    PtnValue *parsed
) {
    *parsed = ptn_null();
    size_t available = input_len - *offset;
    if (spec.conversion == 'n') {
        if (*offset > (size_t)INT64_MAX) {
            *parsed = ptn_int(INT64_MAX);
        } else {
            *parsed = ptn_int((int64_t)*offset);
        }
        return 1;
    }
    if (spec.conversion != 'c' && spec.conversion != '[') {
        while (*offset < input_len && isspace((unsigned char)input[*offset])) {
            (*offset)++;
        }
        available = input_len - *offset;
    }
    if (available == 0) {
        return 0;
    }
    size_t limit = ptn_scanf_conversion_limit(spec, available);
    if (limit == 0) {
        limit = available;
    }

    if (spec.conversion == 's') {
        size_t start = *offset;
        size_t consumed = 0;
        while (
            *offset < input_len
            && consumed < limit
            && input[*offset] != '\0'
            && !isspace((unsigned char)input[*offset])
        ) {
            (*offset)++;
            consumed++;
        }
        if (*offset == start) {
            return 0;
        }
        *parsed = ptn_owned_string_len(ptn_duplicate_string_len(input + start, *offset - start), *offset - start);
        return 1;
    }
    if (spec.conversion == 'c') {
        if (input[*offset] == '\0') {
            return 0;
        }
        size_t width = spec.has_width ? spec.width : 1;
        if (width == 0) {
            width = 1;
        }
        size_t field_available = 0;
        while (
            field_available < available
            && !isspace((unsigned char)input[*offset + field_available])
        ) {
            field_available++;
        }
        if (field_available == 0) {
            *parsed = ptn_owned_string_len(ptn_duplicate_string_len("", 0), 0);
            return 1;
        }
        if (width > field_available) {
            width = field_available;
        }
        *parsed = ptn_owned_string_len(ptn_duplicate_string_len(input + *offset, width), width);
        *offset += width;
        return width != 0;
    }
    if (spec.conversion == '[') {
        size_t start = *offset;
        size_t consumed = 0;
        while (*offset < input_len && consumed < limit) {
            unsigned char byte = (unsigned char)input[*offset];
            if (byte == '\0') {
                break;
            }
            int in_set = ptn_scanf_set_contains(spec.scanset, byte);
            if ((in_set && spec.scanset_negated) || (!in_set && !spec.scanset_negated)) {
                break;
            }
            (*offset)++;
            consumed++;
        }
        if (*offset == start) {
            return 0;
        }
        *parsed = ptn_owned_string_len(ptn_duplicate_string_len(input + start, *offset - start), *offset - start);
        return 1;
    }

    size_t original_len = input_len;
    if (spec.has_width && spec.width < available) {
        input_len = *offset + spec.width;
    }
    int matched = 0;
    if (spec.conversion == 'd') {
        matched = ptn_scanf_match_integer(input, input_len, offset, 10, parsed);
    } else if (spec.conversion == 'i') {
        matched = ptn_scanf_match_integer(input, input_len, offset, 0, parsed);
    } else if (spec.conversion == 'o') {
        matched = ptn_scanf_match_integer(input, input_len, offset, 8, parsed);
    } else if (spec.conversion == 'x' || spec.conversion == 'X') {
        matched = ptn_scanf_match_integer(input, input_len, offset, 16, parsed);
    } else if (spec.conversion == 'u') {
        matched = ptn_scanf_match_unsigned(input, input_len, offset, parsed);
    } else if (
        spec.conversion == 'f'
        || spec.conversion == 'F'
        || spec.conversion == 'e'
        || spec.conversion == 'E'
        || spec.conversion == 'g'
        || spec.conversion == 'G'
    ) {
        matched = ptn_scanf_match_float(input, input_len, offset, parsed);
    }
    (void)original_len;
    return matched;
}

static int ptn_scanf_input_is_blank(const char *input_data, size_t input_len) {
    for (size_t i = 0; i < input_len; i++) {
        if (!isspace((unsigned char)input_data[i])) {
            return 0;
        }
    }
    return 1;
}

static int ptn_scanf_conversion_skips_whitespace(char conversion) {
    return conversion != '\0' && conversion != '[' && conversion != 'c' && conversion != 'n';
}

static int ptn_scanf_input_at_nul(const char *input_data, size_t input_len, size_t offset) {
    return offset < input_len && input_data[offset] == '\0';
}

static PtnValue ptn_scanf_execute(
    PtnRuntime *runtime,
    const char *function_name,
    const char *input_data,
    size_t input_len,
    PtnStringOperand format,
    size_t output_count,
    const PtnValue *output_args,
    int exact_output_count,
    int null_on_zero_array_assignments,
    size_t line
) {
    PtnScanfFormatInfo info;
    if (!ptn_scanf_format_info(runtime, function_name, format, output_count, exact_output_count, line, &info)) {
        return ptn_null();
    }

    PtnValue *values = NULL;
    unsigned char *filled = NULL;
    if (info.result_slots != 0) {
        values = calloc(info.result_slots, sizeof(PtnValue));
        filled = calloc(info.result_slots, sizeof(unsigned char));
        if (values == NULL || filled == NULL) {
            ptn_abort_out_of_memory();
        }
        for (size_t i = 0; i < info.result_slots; i++) {
            values[i] = ptn_null();
        }
    }

    size_t next_target = 0;
    size_t assigned = 0;
    size_t in = 0;
    int attempted_conversion = 0;
    for (size_t fi = 0; fi < format.len; fi++) {
        unsigned char fbyte = (unsigned char)format.data[fi];
        if (isspace(fbyte)) {
            while (fi + 1 < format.len && isspace((unsigned char)format.data[fi + 1])) {
                fi++;
            }
            while (in < input_len && isspace((unsigned char)input_data[in])) {
                in++;
            }
            continue;
        }
        if (format.data[fi] != '%') {
            if (in >= input_len || input_data[in] != format.data[fi]) {
                break;
            }
            in++;
            continue;
        }

        fi++;
        if (fi < format.len && format.data[fi] == '%') {
            if (in >= input_len || input_data[in] != '%') {
                break;
            }
            in++;
            continue;
        }

        PtnScanfSpec spec;
        char bad_conversion = '\0';
        int argument_index_out_of_range = 0;
        if (!ptn_scanf_parse_spec(format, &fi, &next_target, &spec, &bad_conversion, &argument_index_out_of_range)) {
            break;
        }

        PtnValue parsed = ptn_null();
        size_t before = in;
        attempted_conversion = 1;
        int matched = ptn_scanf_match_value(spec, input_data, input_len, &in, &parsed);
        if (!matched) {
            in = before;
            break;
        }
        if (spec.suppress_assignment) {
            ptn_value_destroy(&parsed);
            continue;
        }
        if (spec.target_index < info.result_slots) {
            ptn_value_destroy(&values[spec.target_index]);
            values[spec.target_index] = parsed;
            filled[spec.target_index] = 1;
            assigned++;
        } else {
            ptn_value_destroy(&parsed);
        }
    }

    PtnValue result;
    if (output_count == 0) {
        int input_is_blank = ptn_scanf_input_is_blank(input_data, input_len);
        if (
            null_on_zero_array_assignments
            && assigned == 0
            && (
                ptn_scanf_input_at_nul(input_data, input_len, in)
                || (
                    attempted_conversion
                    &&
                    input_is_blank
                    && (
                        ptn_scanf_conversion_skips_whitespace(info.first_conversion)
                        || in >= input_len
                    )
                )
            )
        ) {
            for (size_t i = 0; i < info.result_slots; i++) {
                ptn_value_destroy(&values[i]);
            }
            result = ptn_null();
        } else {
            result = ptn_array_from_literal_entries(0, NULL);
            for (size_t i = 0; i < info.result_slots; i++) {
                ptn_array_set_entry(result.as.array, ptn_array_int_key((int64_t)i), values[i]);
            }
        }
    } else {
        for (size_t i = 0; i < output_count; i++) {
            if (i < info.result_slots && filled[i] && output_args[i].type == PTN_REFERENCE) {
                ptn_reference_assign(runtime, output_args[i].as.reference, values[i]);
            }
        }
        for (size_t i = 0; i < info.result_slots; i++) {
            ptn_value_destroy(&values[i]);
        }
        result = ptn_int((int64_t)assigned);
    }
    free(values);
    free(filled);
    return result;
}

static PtnValue ptn_internal_sscanf(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "sscanf", 1, "string", args[0], line);
    PtnStringOperand format = ptn_internal_expect_string_arg(runtime, "sscanf", 2, "format", args[1], line);
    PtnValue result = ptn_scanf_execute(
        runtime,
        "sscanf",
        input.data,
        input.len,
        format,
        argc > 2 ? argc - 2 : 0,
        argc > 2 ? args + 2 : NULL,
        0,
        0,
        line
    );
    ptn_string_operand_free(input);
    ptn_string_operand_free(format);
    return result;
}

static char *ptn_rot13_string(const char *string, size_t len) {
    char *rotated = malloc(len + 1);
    if (rotated == NULL) {
        ptn_abort_out_of_memory();
    }

    for (size_t i = 0; i < len; i++) {
        unsigned char byte = (unsigned char)string[i];
        if (byte >= 'a' && byte <= 'z') {
            rotated[i] = (char)('a' + ((byte - 'a' + 13) % 26));
        } else if (byte >= 'A' && byte <= 'Z') {
            rotated[i] = (char)('A' + ((byte - 'A' + 13) % 26));
        } else {
            rotated[i] = (char)byte;
        }
    }
    rotated[len] = '\0';
    return rotated;
}

