static PtnValue ptn_internal_chmod(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand path_operand = ptn_value_to_string_operand(args[0]);
    char *path = ptn_path_operand_to_c_string(path_operand);
    ptn_string_operand_free(path_operand);
    if (path == NULL) {
        ptn_emit_warning(&runtime->diagnostics, "chmod(): Filename contains null byte", line);
        return ptn_bool(0);
    }

    int64_t permissions = ptn_internal_expect_integer_arg(runtime, "chmod", 2, "permissions", args[1], line);
    if (runtime->exceptions->active_exception != NULL) {
        free(path);
        return ptn_bool(0);
    }
    PtnValue metadata_result;
    if (ptn_try_user_stream_metadata(runtime, path, 6, ptn_int(permissions), line, &metadata_result)) {
        free(path);
        return metadata_result;
    }
    if (strncmp(path, "phar://", 7) == 0) {
        int ok = ptn_phar_uri_chmod(path, permissions);
        free(path);
        return ptn_bool(ok);
    }
#if defined(_WIN32)
    int ok = _chmod(path, (int)permissions) == 0;
#else
    int ok = chmod(path, (mode_t)permissions) == 0;
#endif
    if (ok) {
        free(path);
        return ptn_bool(1);
    }

    ptn_emit_function_warning(runtime, "chmod", strerror(errno), line);
    free(path);
    return ptn_bool(0);
}

#if !defined(_WIN32)
static int ptn_internal_chown_uid_arg(PtnRuntime *runtime, PtnValue value, size_t line, uid_t *uid_out) {
    value = ptn_value_deref(value);
    if (value.type == PTN_INT) {
        *uid_out = (uid_t)value.as.integer;
        return 1;
    }

    PtnStringOperand name_operand =
        ptn_internal_expect_string_arg(runtime, "chown", 2, "user", value, line);
    if (runtime->exceptions->active_exception != NULL) {
        return 0;
    }
    char *name = ptn_path_operand_to_c_string(name_operand);
    ptn_string_operand_free(name_operand);
    if (name == NULL) {
        ptn_emit_function_warning(runtime, "chown", "Unable to find uid for ", line);
        return 0;
    }
    struct passwd *entry = getpwnam(name);
    if (entry == NULL) {
        size_t name_len = strlen(name);
        int needed = snprintf(NULL, 0, "Unable to find uid for %s", name);
        if (needed < 0 || name_len > (size_t)INT_MAX) {
            free(name);
            ptn_abort_out_of_memory();
        }
        char *message = malloc((size_t)needed + 1);
        if (message == NULL) {
            free(name);
            ptn_abort_out_of_memory();
        }
        int written = snprintf(message, (size_t)needed + 1, "Unable to find uid for %s", name);
        if (written < 0 || written != needed) {
            free(message);
            free(name);
            ptn_abort_out_of_memory();
        }
        ptn_emit_function_warning(runtime, "chown", message, line);
        free(message);
        free(name);
        return 0;
    }
    *uid_out = entry->pw_uid;
    free(name);
    return 1;
}

static int ptn_internal_chgrp_gid_arg(PtnRuntime *runtime, PtnValue value, size_t line, gid_t *gid_out) {
    value = ptn_value_deref(value);
    if (value.type == PTN_INT) {
        *gid_out = (gid_t)value.as.integer;
        return 1;
    }

    PtnStringOperand name_operand =
        ptn_internal_expect_string_arg(runtime, "chgrp", 2, "group", value, line);
    if (runtime->exceptions->active_exception != NULL) {
        return 0;
    }
    char *name = ptn_path_operand_to_c_string(name_operand);
    ptn_string_operand_free(name_operand);
    if (name == NULL) {
        ptn_emit_function_warning(runtime, "chgrp", "Unable to find gid for ", line);
        return 0;
    }
    struct group *entry = getgrnam(name);
    if (entry == NULL) {
        size_t name_len = strlen(name);
        int needed = snprintf(NULL, 0, "Unable to find gid for %s", name);
        if (needed < 0 || name_len > (size_t)INT_MAX) {
            free(name);
            ptn_abort_out_of_memory();
        }
        char *message = malloc((size_t)needed + 1);
        if (message == NULL) {
            free(name);
            ptn_abort_out_of_memory();
        }
        int written = snprintf(message, (size_t)needed + 1, "Unable to find gid for %s", name);
        if (written < 0 || written != needed) {
            free(message);
            free(name);
            ptn_abort_out_of_memory();
        }
        ptn_emit_function_warning(runtime, "chgrp", message, line);
        free(message);
        free(name);
        return 0;
    }
    *gid_out = entry->gr_gid;
    free(name);
    return 1;
}
#endif

static PtnValue ptn_internal_chown(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand path_operand = ptn_value_to_string_operand(args[0]);
    char *path = ptn_path_operand_to_c_string(path_operand);
    ptn_string_operand_free(path_operand);
    if (path == NULL) {
        ptn_emit_warning(&runtime->diagnostics, "chown(): Filename contains null byte", line);
        return ptn_bool(0);
    }

    if (ptn_user_stream_wrapper_find_path(path) != NULL) {
        PtnValue owner_value = ptn_value_deref(args[1]);
        PtnStringOperand owner_string = ptn_value_to_string_operand(args[1]);
        PtnValue owner_metadata = ptn_owned_string_len(
            ptn_duplicate_string_len(owner_string.data, owner_string.len),
            owner_string.len
        );
        ptn_string_operand_free(owner_string);
        PtnValue metadata_result;
        (void)ptn_try_user_stream_metadata(
            runtime,
            path,
            owner_value.type == PTN_INT ? 3 : 2,
            owner_value.type == PTN_INT ? args[1] : owner_metadata,
            line,
            &metadata_result
        );
        ptn_value_destroy(&owner_metadata);
        free(path);
        return metadata_result;
    }

#if defined(_WIN32)
    ptn_emit_function_warning(runtime, "chown", "Operation not supported", line);
    free(path);
    return ptn_bool(0);
#else
    uid_t uid = (uid_t)-1;
    if (!ptn_internal_chown_uid_arg(runtime, args[1], line, &uid)) {
        free(path);
        return ptn_bool(0);
    }
    if (chown(path, uid, (gid_t)-1) == 0) {
        free(path);
        return ptn_bool(1);
    }
    ptn_emit_function_warning(runtime, "chown", strerror(errno), line);
    free(path);
    return ptn_bool(0);
#endif
}

