static PtnValue ptn_internal_intltz_get_region(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand timezone_id =
        ptn_internal_expect_string_arg(runtime, "IntlTimeZone::getRegion", 1, "timezoneId", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(timezone_id);
        return ptn_null();
    }
    if (!ptn_intl_utf8_is_valid(timezone_id.data, timezone_id.len)) {
        ptn_string_operand_free(timezone_id);
        ptn_intl_set_error_message(
            runtime,
            "IntlTimeZone::getRegion(): could not convert time zone id to UTF-16: U_INVALID_CHAR_FOUND"
        );
        return ptn_bool(0);
    }
    const char *region = NULL;
    if (ptn_intl_ascii_case_equal_literal(timezone_id, "Europe/Lisbon") ||
        ptn_intl_ascii_case_equal_literal(timezone_id, "Portugal")) {
        region = "PT";
    } else if (ptn_intl_ascii_case_equal_literal(timezone_id, "UTC") ||
        ptn_intl_ascii_case_equal_literal(timezone_id, "GMT") ||
        ptn_intl_ascii_case_equal_literal(timezone_id, "Etc/UTC")) {
        region = "001";
    } else if (ptn_intl_ascii_case_equal_literal(timezone_id, "America/New_York")) {
        region = "US";
    } else if (ptn_intl_ascii_case_equal_literal(timezone_id, "Europe/Berlin")) {
        region = "DE";
    }
    ptn_string_operand_free(timezone_id);
    if (region != NULL) {
        ptn_intl_set_error_message(runtime, "U_ZERO_ERROR");
        return ptn_string(region);
    }
    ptn_intl_set_error_message(
        runtime,
        "IntlTimeZone::getRegion(): error obtaining region: U_ILLEGAL_ARGUMENT_ERROR"
    );
    return ptn_bool(0);
}

static PtnValue ptn_internal_intltz_get_windows_id(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand id = ptn_internal_expect_string_arg(runtime, "IntlTimeZone::getWindowsID", 1, "timezoneId", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    const char *result = NULL;
    if (ptn_string_operand_ascii_case_equal(id, "America/Bogota")) result = "SA Pacific Standard Time";
    else if (ptn_string_operand_ascii_case_equal(id, "America/Havana")) result = "Cuba Standard Time";
    else if (ptn_string_operand_ascii_case_equal(id, "America/Indiana/Knox")) result = "Central Standard Time";
    else if (ptn_string_operand_ascii_case_equal(id, "America/Los_Angeles")) result = "Pacific Standard Time";
    else if (ptn_string_operand_ascii_case_equal(id, "Africa/Casablanca")) result = "Morocco Standard Time";
    else if (ptn_string_operand_ascii_case_equal(id, "Asia/Singapore")) result = "Singapore Standard Time";
    else if (ptn_string_operand_ascii_case_equal(id, "Australia/Perth")) result = "W. Australia Standard Time";
    else if (ptn_string_operand_ascii_case_equal(id, "Europe/London")) result = "GMT Standard Time";
    else if (ptn_string_operand_ascii_case_equal(id, "Europe/Istanbul")) result = "Turkey Standard Time";
    ptn_string_operand_free(id);
    if (result == NULL) {
        ptn_intl_set_error_message(runtime, "IntlTimeZone::getWindowsID(): unknown system timezone: U_ILLEGAL_ARGUMENT_ERROR");
        return ptn_bool(0);
    }
    ptn_intl_set_error_message(runtime, "U_ZERO_ERROR");
    return ptn_string(result);
}

static PtnValue ptn_internal_intltz_get_id_for_windows_id(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand id = ptn_internal_expect_string_arg(runtime, "IntlTimeZone::getIDForWindowsID", 1, "timezoneId", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    PtnStringOperand region = { NULL, 0, 0 };
    int has_region = 0;
    if (argc >= 2 && ptn_value_deref(args[1]).type != PTN_NULL) {
        region = ptn_internal_expect_string_arg(runtime, "IntlTimeZone::getIDForWindowsID", 2, "region", args[1], line);
        if (runtime->exceptions->active_exception != NULL) {
            ptn_string_operand_free(id);
            return ptn_null();
        }
        has_region = 1;
    }

    const char *result = NULL;
    if (ptn_string_operand_ascii_case_equal(id, "India Standard Time")) {
        result = "Asia/Calcutta";
    } else if (ptn_string_operand_ascii_case_equal(id, "Pacific Standard Time")) {
        if (has_region && ptn_string_operand_ascii_case_equal(region, "CA")) {
            result = "America/Vancouver";
        } else if (has_region && ptn_string_operand_ascii_case_equal(region, "ZZ")) {
            result = "PST8PDT";
        } else {
            result = "America/Los_Angeles";
        }
    } else if (ptn_string_operand_ascii_case_equal(id, "Romance Standard Time")) {
        if (has_region && ptn_string_operand_ascii_case_equal(region, "BE")) {
            result = "Europe/Brussels";
        } else if (has_region && ptn_string_operand_ascii_case_equal(region, "DK")) {
            result = "Europe/Copenhagen";
        } else if (has_region && ptn_string_operand_ascii_case_equal(region, "ES")) {
            result = "Europe/Madrid";
        } else {
            result = "Europe/Paris";
        }
    }
    ptn_string_operand_free(id);
    if (has_region) {
        ptn_string_operand_free(region);
    }
    if (result == NULL) {
        ptn_intl_set_error_message(runtime, "IntlTimeZone::getIDForWindowsID(): unknown windows timezone: U_ILLEGAL_ARGUMENT_ERROR");
        return ptn_bool(0);
    }
    ptn_intl_set_error_message(runtime, "U_ZERO_ERROR");
    return ptn_string(result);
}

static PtnValue ptn_internal_intltz_create_timezone_id_enumeration(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)line;
    if (argc >= 3) {
        int64_t raw_offset = ptn_value_to_integer(args[2]);
        if (raw_offset < INT32_MIN || raw_offset > INT32_MAX) {
            ptn_throw_exception(runtime, "ValueError", "IntlTimeZone::createTimeZoneIDEnumeration(): Argument #3 ($rawOffset) must be between -2147483648 and 2147483647");
            return ptn_null();
        }
    }
    return ptn_intl_iterator_from_count(runtime, 350);
}

