static void ptn_mb_windows1254_init_encode_table(void) {
    if (PTN_MB_WINDOWS_1254_ENCODE_TABLE_INITIALIZED) {
        return;
    }
    memset(PTN_MB_WINDOWS_1254_ENCODE_TABLE, 0xff, sizeof(PTN_MB_WINDOWS_1254_ENCODE_TABLE));
    for (unsigned int byte = 0; byte <= 0xff; byte++) {
        uint16_t unicode = PTN_MB_WINDOWS_1254_DECODE_TABLE[byte];
        if (unicode != 0xffff) {
            PTN_MB_WINDOWS_1254_ENCODE_TABLE[unicode] = (unsigned char)byte;
        }
    }
    PTN_MB_WINDOWS_1254_ENCODE_TABLE_INITIALIZED = 1;
}

static int ptn_mb_single_byte_override_table_parts(
    const char *encoding,
    const uint16_t **decode_table,
    unsigned char **encode_table,
    int **initialized
) {
    if (encoding == NULL) {
        return 0;
    }
    if (ptn_ascii_case_equal(encoding, "CP850")) {
        if (decode_table != NULL) {
            *decode_table = PTN_MB_CP850_DECODE_TABLE;
        }
        if (encode_table != NULL) {
            *encode_table = PTN_MB_CP850_ENCODE_TABLE;
        }
        if (initialized != NULL) {
            *initialized = &PTN_MB_CP850_ENCODE_TABLE_INITIALIZED;
        }
        return 1;
    }
    if (ptn_ascii_case_equal(encoding, "CP866")) {
        if (decode_table != NULL) {
            *decode_table = PTN_MB_CP866_DECODE_TABLE;
        }
        if (encode_table != NULL) {
            *encode_table = PTN_MB_CP866_ENCODE_TABLE;
        }
        if (initialized != NULL) {
            *initialized = &PTN_MB_CP866_ENCODE_TABLE_INITIALIZED;
        }
        return 1;
    }
    if (ptn_ascii_case_equal(encoding, "KOI8-R")) {
        if (decode_table != NULL) {
            *decode_table = PTN_MB_KOI8_R_DECODE_TABLE;
        }
        if (encode_table != NULL) {
            *encode_table = PTN_MB_KOI8_R_ENCODE_TABLE;
        }
        if (initialized != NULL) {
            *initialized = &PTN_MB_KOI8_R_ENCODE_TABLE_INITIALIZED;
        }
        return 1;
    }
    if (ptn_ascii_case_equal(encoding, "KOI8-U")) {
        if (decode_table != NULL) {
            *decode_table = PTN_MB_KOI8_U_DECODE_TABLE;
        }
        if (encode_table != NULL) {
            *encode_table = PTN_MB_KOI8_U_ENCODE_TABLE;
        }
        if (initialized != NULL) {
            *initialized = &PTN_MB_KOI8_U_ENCODE_TABLE_INITIALIZED;
        }
        return 1;
    }
    if (ptn_ascii_case_equal(encoding, "ARMSCII-8")) {
        if (decode_table != NULL) {
            *decode_table = PTN_MB_ARMSCII_8_DECODE_TABLE;
        }
        if (encode_table != NULL) {
            *encode_table = PTN_MB_ARMSCII_8_ENCODE_TABLE;
        }
        if (initialized != NULL) {
            *initialized = &PTN_MB_ARMSCII_8_ENCODE_TABLE_INITIALIZED;
        }
        return 1;
    }
    return 0;
}

