static uint16_t ptn_mb_code16_table_read(const unsigned char *table, size_t offset) {
    return (uint16_t)(((uint16_t)table[offset] << 8) | (uint16_t)table[offset + 1]);
}

static int ptn_mb_code16_lookup_encoded(const unsigned char *table, size_t table_len, uint16_t encoded, uint16_t *unicode) {
    for (size_t i = 0; i + 3 < table_len; i += 4) {
        if (ptn_mb_code16_table_read(table, i) == encoded) {
            if (unicode != NULL) {
                *unicode = ptn_mb_code16_table_read(table, i + 2);
            }
            return 1;
        }
    }
    return 0;
}

static int ptn_mb_code16_lookup_unicode(const unsigned char *table, size_t table_len, uint16_t unicode, uint16_t *encoded) {
    for (size_t i = 0; i + 3 < table_len; i += 4) {
        if (ptn_mb_code16_table_read(table, i + 2) == unicode) {
            if (encoded != NULL) {
                *encoded = ptn_mb_code16_table_read(table, i);
            }
            return 1;
        }
    }
    return 0;
}

static int ptn_mb_iconv_one_to_utf16be(const char *input, size_t input_len, const char *from_iconv, uint16_t *unicode);

static void ptn_mb_cp936_init_encode_table(void) {
    if (PTN_MB_CP936_ENCODE_TABLE_INITIALIZED) {
        return;
    }
    memset(PTN_MB_CP936_ENCODE_TABLE, 0xff, sizeof(PTN_MB_CP936_ENCODE_TABLE));
    for (uint16_t byte = 0; byte <= 0x7f; byte++) {
        PTN_MB_CP936_ENCODE_TABLE[byte] = byte;
    }
    for (unsigned int lead = 0x81; lead <= 0xfe; lead++) {
        for (unsigned int trail = 0; trail <= 0xff; trail++) {
            uint16_t encoded = (uint16_t)((lead << 8) | trail);
            if (ptn_mb_code16_lookup_encoded(
                    PTN_MB_CP936_DECODE_OVERRIDES,
                    sizeof(PTN_MB_CP936_DECODE_OVERRIDES),
                    encoded,
                    NULL
                )) {
                continue;
            }
            char bytes[2] = { (char)lead, (char)trail };
            uint16_t unicode = 0;
            if (ptn_mb_iconv_one_to_utf16be(bytes, sizeof(bytes), "GB18030", &unicode)) {
                PTN_MB_CP936_ENCODE_TABLE[unicode] = encoded;
            }
        }
    }
    for (size_t i = 0; i + 3 < sizeof(PTN_MB_CP936_ENCODE_OVERRIDES); i += 4) {
        uint16_t encoded = ptn_mb_code16_table_read(PTN_MB_CP936_ENCODE_OVERRIDES, i);
        uint16_t unicode = ptn_mb_code16_table_read(PTN_MB_CP936_ENCODE_OVERRIDES, i + 2);
        PTN_MB_CP936_ENCODE_TABLE[unicode] = encoded;
    }
    PTN_MB_CP936_ENCODE_TABLE_INITIALIZED = 1;
}

static int ptn_mb_encoding_is_cp936_table(const char *encoding) {
    return encoding != NULL && ptn_ascii_case_equal(encoding, "CP936");
}

static int ptn_mb_encoding_is_euctw_table(const char *encoding) {
    return encoding != NULL && ptn_ascii_case_equal(encoding, "EUC-TW");
}

static int ptn_mb_encoding_is_single_byte_override_table(const char *encoding) {
    return ptn_mb_single_byte_override_table_parts(encoding, NULL, NULL, NULL);
}

static int ptn_mb_encoding_is_windows1252_table(const char *encoding) {
    return encoding != NULL &&
        (ptn_ascii_case_equal(encoding, "Windows-1252") || ptn_ascii_case_equal(encoding, "CP1252"));
}

static int ptn_mb_encoding_is_windows1254_table(const char *encoding) {
    return encoding != NULL &&
        (ptn_ascii_case_equal(encoding, "Windows-1254") || ptn_ascii_case_equal(encoding, "CP1254"));
}

static int ptn_mb_encoding_is_table(const char *encoding) {
    return ptn_mb_encoding_is_cp936_table(encoding) ||
        ptn_mb_encoding_is_euctw_table(encoding) ||
        ptn_mb_encoding_is_single_byte_override_table(encoding) ||
        ptn_mb_encoding_is_windows1252_table(encoding) ||
        ptn_mb_encoding_is_windows1254_table(encoding);
}

static void ptn_mb_append_utf16be_code_unit(PtnStringBuffer *buffer, uint16_t cp) {
    char bytes[2];
    bytes[0] = (char)(cp >> 8);
    bytes[1] = (char)(cp & 0xff);
    ptn_string_buffer_append_len(buffer, bytes, sizeof(bytes));
}

static void ptn_mb_append_encoded16(PtnStringBuffer *buffer, uint16_t encoded) {
    if (encoded <= 0xff) {
        ptn_string_buffer_append_char(buffer, (char)encoded);
        return;
    }
    char bytes[2];
    bytes[0] = (char)(encoded >> 8);
    bytes[1] = (char)(encoded & 0xff);
    ptn_string_buffer_append_len(buffer, bytes, sizeof(bytes));
}

static void ptn_mb_append_table_replacement(
    PtnStringBuffer *buffer,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars
) {
    if (illegal_chars != NULL) {
        (*illegal_chars)++;
    }
    if (replacement_len > 0) {
        ptn_string_buffer_append_len(buffer, replacement, replacement_len);
    }
}

static void ptn_mb_single_byte_override_init_encode_table(
    const uint16_t decode_table[256],
    unsigned char encode_table[65536],
    int *initialized
) {
    if (*initialized) {
        return;
    }
    memset(encode_table, 0xff, 65536);
    for (unsigned int byte = 0; byte <= 0xff; byte++) {
        uint16_t unicode = decode_table[byte];
        if (unicode != 0xffff) {
            encode_table[unicode] = (unsigned char)byte;
        }
    }
    *initialized = 1;
}

static int ptn_mb_single_byte_override_decode_byte(const char *encoding, unsigned char byte, uint16_t *unicode) {
    const uint16_t *decode_table = NULL;
    if (!ptn_mb_single_byte_override_table_parts(encoding, &decode_table, NULL, NULL)) {
        return 0;
    }
    uint16_t mapped = decode_table[byte];
    if (mapped == 0xffff) {
        return 0;
    }
    if (unicode != NULL) {
        *unicode = mapped;
    }
    return 1;
}

static int ptn_mb_single_byte_override_encode_code_unit(
    const char *encoding,
    uint16_t unicode,
    char out[8],
    size_t *out_len
) {
    const uint16_t *decode_table = NULL;
    unsigned char *encode_table = NULL;
    int *initialized = NULL;
    if (!ptn_mb_single_byte_override_table_parts(encoding, &decode_table, &encode_table, &initialized)) {
        return 0;
    }
    ptn_mb_single_byte_override_init_encode_table(decode_table, encode_table, initialized);
    unsigned char byte = encode_table[unicode];
    if (byte != 0xff || (decode_table[0xff] != 0xffff && unicode == decode_table[0xff])) {
        out[0] = (char)byte;
        *out_len = 1;
        return 1;
    }
    return 0;
}

static int ptn_mb_windows1252_decode_byte(unsigned char byte, uint16_t *unicode) {
    if (unicode != NULL) {
        *unicode = PTN_MB_WINDOWS_1252_DECODE_TABLE[byte];
    }
    return 1;
}

static int ptn_mb_windows1252_encode_code_unit(uint16_t unicode, char out[8], size_t *out_len) {
    ptn_mb_windows1252_init_encode_table();
    unsigned char byte = PTN_MB_WINDOWS_1252_ENCODE_TABLE[unicode];
    if (byte != 0xff || unicode == 0x00ff) {
        out[0] = (char)byte;
        *out_len = 1;
        return 1;
    }
    return 0;
}

static int ptn_mb_windows1254_decode_byte(unsigned char byte, uint16_t *unicode) {
    uint16_t mapped = PTN_MB_WINDOWS_1254_DECODE_TABLE[byte];
    if (mapped == 0xffff) {
        return 0;
    }
    if (unicode != NULL) {
        *unicode = mapped;
    }
    return 1;
}

static int ptn_mb_windows1254_encode_code_unit(uint16_t unicode, char out[8], size_t *out_len) {
    ptn_mb_windows1254_init_encode_table();
    unsigned char byte = PTN_MB_WINDOWS_1254_ENCODE_TABLE[unicode];
    if (byte != 0xff || unicode == 0x00ff) {
        out[0] = (char)byte;
        *out_len = 1;
        return 1;
    }
    return 0;
}

#if !defined(_WIN32)
static iconv_t ptn_mb_cached_iconv_open(const char *to_iconv, const char *from_iconv, int *cached) {
    enum { PTN_MB_ICONV_CACHE_CAPACITY = 32 };
    typedef struct {
        char *to_iconv;
        char *from_iconv;
        iconv_t cd;
    } PtnMbIconvCacheEntry;
    static PtnMbIconvCacheEntry entries[PTN_MB_ICONV_CACHE_CAPACITY];
    static size_t next_slot = 0;

    for (size_t i = 0; i < PTN_MB_ICONV_CACHE_CAPACITY; i++) {
        if (entries[i].cd != (iconv_t)0 &&
            strcmp(entries[i].to_iconv, to_iconv) == 0 &&
            strcmp(entries[i].from_iconv, from_iconv) == 0) {
            *cached = 1;
            iconv(entries[i].cd, NULL, NULL, NULL, NULL);
            return entries[i].cd;
        }
    }

    iconv_t cd = iconv_open(to_iconv, from_iconv);
    if (cd == (iconv_t)-1) {
        *cached = 0;
        return cd;
    }

    size_t slot = next_slot++ % PTN_MB_ICONV_CACHE_CAPACITY;
    if (entries[slot].cd != (iconv_t)0) {
        iconv_close(entries[slot].cd);
        free(entries[slot].to_iconv);
        free(entries[slot].from_iconv);
    }
    entries[slot].to_iconv = ptn_duplicate_string(to_iconv);
    entries[slot].from_iconv = ptn_duplicate_string(from_iconv);
    entries[slot].cd = cd;
    *cached = 1;
    return cd;
}

static void ptn_mb_iconv_finish_one(iconv_t cd, int cached) {
    if (cached) {
        iconv(cd, NULL, NULL, NULL, NULL);
    } else {
        iconv_close(cd);
    }
}
#endif

typedef struct {
    uint64_t key;
    uint16_t unicode;
    unsigned char status;
} PtnMbOneToUtf16CacheEntry;

#define PTN_MB_ONE_TO_UTF16_CACHE_SIZE 65536u

static PtnMbOneToUtf16CacheEntry ptn_mb_one_to_utf16_cache[PTN_MB_ONE_TO_UTF16_CACHE_SIZE];

static uint64_t ptn_mb_one_to_utf16_cache_key(const char *input, size_t input_len, const char *from_iconv) {
    if (input_len == 0 || input_len > 4) {
        return 0;
    }
    uint64_t encoding_id = 0;
    if (ptn_ascii_case_equal(from_iconv, "EUC-TW")) {
        encoding_id = 1;
    } else if (ptn_ascii_case_equal(from_iconv, "GB18030")) {
        encoding_id = 2;
    } else {
        return 0;
    }
    uint64_t key = (encoding_id << 56) | ((uint64_t)input_len << 48);
    for (size_t i = 0; i < input_len; i++) {
        key |= (uint64_t)(unsigned char)input[i] << (40 - i * 8);
    }
    return key;
}

static size_t ptn_mb_one_to_utf16_cache_index(uint64_t key) {
    key ^= key >> 33;
    key *= UINT64_C(0xff51afd7ed558ccd);
    key ^= key >> 33;
    return (size_t)key & (PTN_MB_ONE_TO_UTF16_CACHE_SIZE - 1u);
}

static int ptn_mb_one_to_utf16_cache_lookup(uint64_t key, uint16_t *unicode) {
    size_t index = ptn_mb_one_to_utf16_cache_index(key);
    for (size_t probe = 0; probe < PTN_MB_ONE_TO_UTF16_CACHE_SIZE; probe++) {
        PtnMbOneToUtf16CacheEntry *entry = &ptn_mb_one_to_utf16_cache[(index + probe) & (PTN_MB_ONE_TO_UTF16_CACHE_SIZE - 1u)];
        if (entry->status == 0) {
            return -1;
        }
        if (entry->key == key) {
            if (entry->status == 2 && unicode != NULL) {
                *unicode = entry->unicode;
            }
            return entry->status == 2 ? 1 : 0;
        }
    }
    return -1;
}

static void ptn_mb_one_to_utf16_cache_store(uint64_t key, int ok, uint16_t unicode) {
    size_t index = ptn_mb_one_to_utf16_cache_index(key);
    for (size_t probe = 0; probe < PTN_MB_ONE_TO_UTF16_CACHE_SIZE; probe++) {
        PtnMbOneToUtf16CacheEntry *entry = &ptn_mb_one_to_utf16_cache[(index + probe) & (PTN_MB_ONE_TO_UTF16_CACHE_SIZE - 1u)];
        if (entry->status == 0 || entry->key == key) {
            entry->key = key;
            entry->unicode = unicode;
            entry->status = ok ? 2 : 1;
            return;
        }
    }
}

static int ptn_mb_iconv_one_to_utf16be_uncached(const char *input, size_t input_len, const char *from_iconv, uint16_t *unicode) {
#if defined(_WIN32)
    (void)input;
    (void)input_len;
    (void)from_iconv;
    (void)unicode;
    return 0;
#else
    int cached = 0;
    iconv_t cd = ptn_mb_cached_iconv_open("UTF-16BE", from_iconv, &cached);
    if (cd == (iconv_t)-1) {
        return 0;
    }
    iconv(cd, NULL, NULL, NULL, NULL);
    char *in_ptr = (char *)input;
    size_t in_left = input_len;
    char out_storage[8];
    char *out_ptr = out_storage;
    size_t out_left = sizeof(out_storage);
    size_t converted = iconv(cd, &in_ptr, &in_left, &out_ptr, &out_left);
    if (converted == (size_t)-1) {
        ptn_mb_iconv_finish_one(cd, cached);
        return 0;
    }
    converted = iconv(cd, NULL, NULL, &out_ptr, &out_left);
    if (converted == (size_t)-1) {
        ptn_mb_iconv_finish_one(cd, cached);
        return 0;
    }
    ptn_mb_iconv_finish_one(cd, cached);
    size_t used = sizeof(out_storage) - out_left;
    if (in_left != 0 || used != 2) {
        return 0;
    }
    *unicode = (uint16_t)(((unsigned char)out_storage[0] << 8) | (unsigned char)out_storage[1]);
    return 1;
#endif
}

static int ptn_mb_iconv_one_to_utf16be(const char *input, size_t input_len, const char *from_iconv, uint16_t *unicode) {
    uint64_t key = ptn_mb_one_to_utf16_cache_key(input, input_len, from_iconv);
    if (key != 0) {
        int cached = ptn_mb_one_to_utf16_cache_lookup(key, unicode);
        if (cached >= 0) {
            return cached;
        }
    }
    uint16_t decoded = 0;
    int ok = ptn_mb_iconv_one_to_utf16be_uncached(input, input_len, from_iconv, &decoded);
    if (key != 0) {
        ptn_mb_one_to_utf16_cache_store(key, ok, decoded);
    }
    if (ok && unicode != NULL) {
        *unicode = decoded;
    }
    return ok;
}

static int ptn_mb_iconv_utf16be_one_to_bytes(uint16_t unicode, const char *to_iconv, char out[8], size_t *out_len) {
#if defined(_WIN32)
    (void)unicode;
    (void)to_iconv;
    (void)out;
    (void)out_len;
    return 0;
#else
    int cached = 0;
    iconv_t cd = ptn_mb_cached_iconv_open(to_iconv, "UTF-16BE", &cached);
    if (cd == (iconv_t)-1) {
        return 0;
    }
    iconv(cd, NULL, NULL, NULL, NULL);
    char input[2];
    input[0] = (char)(unicode >> 8);
    input[1] = (char)(unicode & 0xff);
    char *in_ptr = input;
    size_t in_left = sizeof(input);
    char *out_ptr = out;
    size_t out_left = 8;
    size_t converted = iconv(cd, &in_ptr, &in_left, &out_ptr, &out_left);
    if (converted == (size_t)-1) {
        ptn_mb_iconv_finish_one(cd, cached);
        return 0;
    }
    converted = iconv(cd, NULL, NULL, &out_ptr, &out_left);
    if (converted == (size_t)-1) {
        ptn_mb_iconv_finish_one(cd, cached);
        return 0;
    }
    ptn_mb_iconv_finish_one(cd, cached);
    if (in_left != 0) {
        return 0;
    }
    *out_len = 8 - out_left;
    return *out_len > 0;
#endif
}

static int ptn_mb_euctw_cell_valid(const unsigned char *bits, unsigned char lead, unsigned char trail) {
    if (lead < 0xa1 || lead > 0xfe || trail < 0xa1 || trail > 0xfe) {
        return 0;
    }
    size_t index = (size_t)(lead - 0xa1) * 94u + (size_t)(trail - 0xa1);
    return (bits[index / 8u] & (unsigned char)(1u << (index % 8u))) != 0;
}

static int ptn_mb_euctw_cell_lead_valid(const unsigned char *bits, unsigned char lead) {
    if (lead < 0xa1 || lead > 0xfe) {
        return 0;
    }
    for (unsigned int trail = 0xa1; trail <= 0xfe; trail++) {
        if (ptn_mb_euctw_cell_valid(bits, lead, (unsigned char)trail)) {
            return 1;
        }
    }
    return 0;
}

static const unsigned char *ptn_mb_euctw_plane_bits(unsigned char plane) {
    if (plane == 0xa1) {
        return PTN_MB_EUCTW_PLANE_A1_BITS;
    }
    if (plane == 0xa2) {
        return PTN_MB_EUCTW_PLANE_A2_BITS;
    }
    if (plane == 0xae) {
        return PTN_MB_EUCTW_PLANE_AE_BITS;
    }
    return NULL;
}

static int ptn_mb_euctw_plane_ae_cell_valid(unsigned char lead, unsigned char trail) {
    return ptn_mb_euctw_cell_valid(PTN_MB_EUCTW_PLANE_AE_BITS, lead, trail);
}

static int ptn_mb_euctw_exception_by_tail(uint16_t tail, uint16_t *unicode) {
    return ptn_mb_code16_lookup_encoded(
        PTN_MB_EUCTW_PLANE_AE_EXCEPTIONS,
        sizeof(PTN_MB_EUCTW_PLANE_AE_EXCEPTIONS),
        tail,
        unicode
    );
}

static int ptn_mb_euctw_exception_by_unicode(uint16_t unicode, uint16_t *tail) {
    return ptn_mb_code16_lookup_unicode(
        PTN_MB_EUCTW_PLANE_AE_EXCEPTIONS,
        sizeof(PTN_MB_EUCTW_PLANE_AE_EXCEPTIONS),
        unicode,
        tail
    );
}

static int ptn_mb_euctw_unicode_may_encode(uint16_t unicode) {
    unsigned int page = (unsigned int)(unicode >> 8);
    return (PTN_MB_EUCTW_UNICODE_PAGE_BITS[page / 8u] & (unsigned char)(1u << (page % 8u))) != 0;
}

static char *ptn_mb_cp936_to_utf16be_alloc_options(
    const char *input,
    size_t input_len,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars,
    size_t *output_len
) {
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    size_t i = 0;
    while (i < input_len) {
        unsigned char b0 = (unsigned char)input[i];
        if (b0 <= 0x7f) {
            ptn_mb_append_utf16be_code_unit(&output, (uint16_t)b0);
            i++;
            continue;
        }
        size_t seq_len = 1;
        uint16_t encoded = (uint16_t)b0;
        if (b0 != 0x80 && b0 != 0xff) {
            if (i + 1 >= input_len) {
                ptn_mb_append_table_replacement(&output, replacement, replacement_len, illegal_chars);
                break;
            }
            seq_len = 2;
            encoded = (uint16_t)(((uint16_t)b0 << 8) | (unsigned char)input[i + 1]);
        }
        uint16_t unicode = 0;
        if (ptn_mb_code16_lookup_encoded(
                PTN_MB_CP936_DECODE_OVERRIDES,
                sizeof(PTN_MB_CP936_DECODE_OVERRIDES),
                encoded,
                &unicode
            ) ||
            ptn_mb_iconv_one_to_utf16be(input + i, seq_len, "GB18030", &unicode)) {
            ptn_mb_append_utf16be_code_unit(&output, unicode);
        } else {
            ptn_mb_append_table_replacement(&output, replacement, replacement_len, illegal_chars);
        }
        i += seq_len;
    }
    *output_len = output.len;
    return output.data;
}

static char *ptn_mb_windows1252_to_utf16be_alloc_options(
    const char *input,
    size_t input_len,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars,
    size_t *output_len
) {
    (void)replacement;
    (void)replacement_len;
    (void)illegal_chars;
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    for (size_t i = 0; i < input_len; i++) {
        uint16_t unicode = 0;
        ptn_mb_windows1252_decode_byte((unsigned char)input[i], &unicode);
        ptn_mb_append_utf16be_code_unit(&output, unicode);
    }
    *output_len = output.len;
    return output.data == NULL ? ptn_duplicate_string_len("", 0) : output.data;
}

static int ptn_mb_windows1252_validate_bytes(const char *input, size_t input_len) {
    (void)input;
    (void)input_len;
    return 1;
}

