static char *ptn_mb_euctw_to_utf16be_alloc_options(
    const char *input,
    size_t input_len,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars,
    size_t *output_len
) {
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    size_t i = 0;
    while (i < input_len) {
        unsigned char b0 = (unsigned char)input[i];
        if (b0 <= 0x7f) {
            ptn_mb_append_utf16be_code_unit(&output, (uint16_t)b0);
            i++;
            continue;
        }
        uint16_t unicode = 0;
        int ok = 0;
        size_t seq_len = 1;
        if (b0 == 0x8e) {
            if (i + 1 < input_len) {
                unsigned char plane = (unsigned char)input[i + 1];
                const unsigned char *plane_bits = ptn_mb_euctw_plane_bits(plane);
                if (plane_bits == NULL) {
                    seq_len = 2;
                } else if (i + 2 >= input_len) {
                    seq_len = input_len - i;
                } else {
                    unsigned char lead = (unsigned char)input[i + 2];
                    if (!ptn_mb_euctw_cell_lead_valid(plane_bits, lead)) {
                        seq_len = 3;
                    } else {
                        seq_len = input_len - i >= 4 ? 4 : input_len - i;
                        if (seq_len == 4) {
                            unsigned char trail = (unsigned char)input[i + 3];
                            if (ptn_mb_euctw_cell_valid(plane_bits, lead, trail)) {
                                if (plane == 0xae) {
                                    uint16_t tail = (uint16_t)(((uint16_t)lead << 8) | trail);
                                    if (ptn_mb_euctw_exception_by_tail(tail, &unicode)) {
                                        ok = 1;
                                    } else {
                                        char translated[4] = { (char)0x8e, (char)0xa3, (char)lead, (char)trail };
                                        ok = ptn_mb_iconv_one_to_utf16be(translated, sizeof(translated), "EUC-TW", &unicode);
                                    }
                                } else {
                                    ok = ptn_mb_iconv_one_to_utf16be(input + i, seq_len, "EUC-TW", &unicode);
                                }
                            }
                        }
                    }
                }
            }
        } else if (ptn_mb_euctw_cell_lead_valid(PTN_MB_EUCTW_2BYTE_BITS, b0)) {
            if (i + 1 >= input_len) {
                seq_len = input_len - i;
            } else {
                seq_len = 2;
                ok = ptn_mb_iconv_one_to_utf16be(input + i, seq_len, "EUC-TW", &unicode);
            }
        }
        if (ok) {
            ptn_mb_append_utf16be_code_unit(&output, unicode);
        } else {
            ptn_mb_append_table_replacement(&output, replacement, replacement_len, illegal_chars);
        }
        i += seq_len;
    }
    *output_len = output.len;
    return output.data;
}

static int ptn_mb_cp936_validate_bytes(const char *input, size_t input_len) {
    size_t i = 0;
    while (i < input_len) {
        unsigned char b0 = (unsigned char)input[i];
        if (b0 <= 0x7f) {
            i++;
            continue;
        }
        size_t seq_len = 1;
        uint16_t encoded = (uint16_t)b0;
        if (b0 != 0x80 && b0 != 0xff) {
            if (i + 1 >= input_len) {
                return 0;
            }
            seq_len = 2;
            encoded = (uint16_t)(((uint16_t)b0 << 8) | (unsigned char)input[i + 1]);
        }
        uint16_t unicode = 0;
        if (!ptn_mb_code16_lookup_encoded(
                PTN_MB_CP936_DECODE_OVERRIDES,
                sizeof(PTN_MB_CP936_DECODE_OVERRIDES),
                encoded,
                &unicode
            ) &&
            !ptn_mb_iconv_one_to_utf16be(input + i, seq_len, "GB18030", &unicode)) {
            return 0;
        }
        i += seq_len;
    }
    return 1;
}

static int ptn_mb_euctw_validate_bytes(const char *input, size_t input_len) {
    size_t i = 0;
    while (i < input_len) {
        unsigned char b0 = (unsigned char)input[i];
        if (b0 <= 0x7f) {
            i++;
            continue;
        }
        uint16_t unicode = 0;
        if (b0 == 0x8e) {
            if (i + 3 >= input_len) {
                return 0;
            }
            unsigned char plane = (unsigned char)input[i + 1];
            const unsigned char *plane_bits = ptn_mb_euctw_plane_bits(plane);
            if (plane_bits == NULL) {
                return 0;
            }
            unsigned char lead = (unsigned char)input[i + 2];
            unsigned char trail = (unsigned char)input[i + 3];
            if (!ptn_mb_euctw_cell_valid(plane_bits, lead, trail)) {
                return 0;
            }
            if (plane == 0xae) {
                uint16_t tail = (uint16_t)(((uint16_t)lead << 8) | trail);
                if (!ptn_mb_euctw_exception_by_tail(tail, &unicode)) {
                    char translated[4] = { (char)0x8e, (char)0xa3, (char)lead, (char)trail };
                    if (!ptn_mb_iconv_one_to_utf16be(translated, sizeof(translated), "EUC-TW", &unicode)) {
                        return 0;
                    }
                }
            } else if (!ptn_mb_iconv_one_to_utf16be(input + i, 4, "EUC-TW", &unicode)) {
                return 0;
            }
            i += 4;
            continue;
        }
        if (!ptn_mb_euctw_cell_lead_valid(PTN_MB_EUCTW_2BYTE_BITS, b0) || i + 1 >= input_len) {
            return 0;
        }
        if (!ptn_mb_iconv_one_to_utf16be(input + i, 2, "EUC-TW", &unicode)) {
            return 0;
        }
        i += 2;
    }
    return 1;
}

static int ptn_mb_cp936_encode_code_unit(uint16_t unicode, char out[8], size_t *out_len) {
    ptn_mb_cp936_init_encode_table();
    uint16_t encoded = PTN_MB_CP936_ENCODE_TABLE[unicode];
    if (encoded == 0xffff) {
        return 0;
    }
    if (encoded <= 0xff) {
        out[0] = (char)encoded;
        *out_len = 1;
    } else {
        out[0] = (char)(encoded >> 8);
        out[1] = (char)(encoded & 0xff);
        *out_len = 2;
    }
    return 1;
}

static int ptn_mb_euctw_encode_code_unit_uncached(uint16_t unicode, char out[8], size_t *out_len) {
    uint16_t tail = 0;
    if (ptn_mb_euctw_exception_by_unicode(unicode, &tail)) {
        out[0] = (char)0x8e;
        out[1] = (char)0xae;
        out[2] = (char)(tail >> 8);
        out[3] = (char)(tail & 0xff);
        *out_len = 4;
        return 1;
    }
    if (!ptn_mb_euctw_unicode_may_encode(unicode)) {
        return 0;
    }
    if (!ptn_mb_iconv_utf16be_one_to_bytes(unicode, "EUC-TW", out, out_len)) {
        return 0;
    }
    if (*out_len == 1) {
        return (unsigned char)out[0] <= 0x7f && unicode == (uint16_t)(unsigned char)out[0];
    }
    if (*out_len == 2) {
        unsigned char lead = (unsigned char)out[0];
        unsigned char trail = (unsigned char)out[1];
        uint16_t decoded = 0;
        return ptn_mb_euctw_cell_valid(PTN_MB_EUCTW_2BYTE_BITS, lead, trail) &&
            ptn_mb_iconv_one_to_utf16be(out, *out_len, "EUC-TW", &decoded) &&
            decoded == unicode;
    }
    if (*out_len == 4 && (unsigned char)out[0] == 0x8e) {
        unsigned char plane = (unsigned char)out[1];
        unsigned char lead = (unsigned char)out[2];
        unsigned char trail = (unsigned char)out[3];
        if (plane == 0xa3 && ptn_mb_euctw_plane_ae_cell_valid(lead, trail)) {
            out[1] = (char)0xae;
            return 1;
        }
        const unsigned char *plane_bits = ptn_mb_euctw_plane_bits(plane);
        if (plane_bits != NULL && plane != 0xae && ptn_mb_euctw_cell_valid(plane_bits, lead, trail)) {
            uint16_t decoded = 0;
            return ptn_mb_iconv_one_to_utf16be(out, *out_len, "EUC-TW", &decoded) && decoded == unicode;
        }
    }
    return 0;
}

typedef struct {
    unsigned char status;
    unsigned char len;
    char bytes[8];
} PtnMbEncodeCodeUnitCacheEntry;

static int ptn_mb_euctw_encode_code_unit(uint16_t unicode, char out[8], size_t *out_len) {
    static PtnMbEncodeCodeUnitCacheEntry cache[65536];
    PtnMbEncodeCodeUnitCacheEntry *entry = &cache[unicode];
    if (entry->status != 0) {
        if (entry->status == 2) {
            memcpy(out, entry->bytes, entry->len);
            *out_len = entry->len;
            return 1;
        }
        return 0;
    }

    char encoded[8];
    size_t encoded_len = 0;
    int ok = ptn_mb_euctw_encode_code_unit_uncached(unicode, encoded, &encoded_len);
    entry->status = ok ? 2 : 1;
    entry->len = ok ? (unsigned char)encoded_len : 0;
    if (ok) {
        memcpy(entry->bytes, encoded, encoded_len);
        memcpy(out, encoded, encoded_len);
        *out_len = encoded_len;
        return 1;
    }
    return 0;
}

static size_t ptn_mb_euctw_invalid_input_skip(const char *input, size_t input_len) {
    if (input_len == 0) {
        return 0;
    }
    unsigned char b0 = (unsigned char)input[0];
    if (b0 == 0x8e) {
        if (input_len < 2) {
            return input_len;
        }
        const unsigned char *plane_bits = ptn_mb_euctw_plane_bits((unsigned char)input[1]);
        if (plane_bits == NULL) {
            return 2;
        }
        if (input_len < 3) {
            return input_len;
        }
        if (!ptn_mb_euctw_cell_lead_valid(plane_bits, (unsigned char)input[2])) {
            return 3;
        }
        return input_len < 4 ? input_len : 4;
    }
    if (ptn_mb_euctw_cell_lead_valid(PTN_MB_EUCTW_2BYTE_BITS, b0)) {
        return input_len < 2 ? input_len : 2;
    }
    return 1;
}

static void ptn_mb_euctw_decode_chunk_append(
    PtnStringBuffer *buffer,
    const char *input,
    size_t input_len,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars
) {
    if (input_len == 0) {
        return;
    }
#if defined(_WIN32)
    ptn_string_buffer_append_len(buffer, input, input_len);
#else
    int cached = 0;
    iconv_t cd = ptn_mb_cached_iconv_open("UTF-16BE", "EUC-TW", &cached);
    if (cd == (iconv_t)-1) {
        ptn_string_buffer_append_len(buffer, input, input_len);
        return;
    }
    size_t out_cap = input_len < 32 ? 128 : input_len * 4 + 32;
    char *output = malloc(out_cap);
    if (output == NULL) {
        ptn_mb_iconv_finish_one(cd, cached);
        ptn_abort_out_of_memory();
    }
    char *in_ptr = (char *)input;
    size_t in_left = input_len;
    char *out_ptr = output;
    size_t out_left = out_cap - 1;
    while (in_left > 0) {
        size_t converted = iconv(cd, &in_ptr, &in_left, &out_ptr, &out_left);
        if (converted != (size_t)-1) {
            continue;
        }
        if (errno == E2BIG) {
            ptn_mb_iconv_ensure_output_capacity(&output, &out_cap, &out_ptr, &out_left, out_left + 1);
            continue;
        }
        if (illegal_chars != NULL) {
            (*illegal_chars)++;
        }
        if (replacement_len > 0) {
            ptn_mb_iconv_ensure_output_capacity(&output, &out_cap, &out_ptr, &out_left, replacement_len);
            memcpy(out_ptr, replacement, replacement_len);
            out_ptr += replacement_len;
            out_left -= replacement_len;
        }
        size_t skip = ptn_mb_euctw_invalid_input_skip(in_ptr, in_left);
        if (skip == 0) {
            skip = 1;
        }
        in_ptr += skip;
        in_left -= skip;
        iconv(cd, NULL, NULL, NULL, NULL);
    }
    for (;;) {
        size_t converted = iconv(cd, NULL, NULL, &out_ptr, &out_left);
        if (converted != (size_t)-1) {
            break;
        }
        if (errno != E2BIG) {
            break;
        }
        ptn_mb_iconv_ensure_output_capacity(&output, &out_cap, &out_ptr, &out_left, out_left + 1);
    }
    ptn_string_buffer_append_len(buffer, output, (size_t)(out_ptr - output));
    free(output);
    ptn_mb_iconv_finish_one(cd, cached);
#endif
}

static char *ptn_mb_euctw_to_utf16be_bulk_alloc_options(
    const char *input,
    size_t input_len,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars,
    size_t *output_len
) {
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    PtnStringBuffer chunk;
    ptn_string_buffer_init(&chunk);
    size_t i = 0;
    while (i < input_len) {
        if (i + 3 < input_len &&
            (unsigned char)input[i] == 0x8e &&
            (unsigned char)input[i + 1] == 0xae) {
            unsigned char lead = (unsigned char)input[i + 2];
            unsigned char trail = (unsigned char)input[i + 3];
            uint16_t tail = (uint16_t)(((uint16_t)lead << 8) | trail);
            uint16_t unicode = 0;
            if (ptn_mb_euctw_exception_by_tail(tail, &unicode)) {
                ptn_mb_euctw_decode_chunk_append(&output, chunk.data, chunk.len, replacement, replacement_len, illegal_chars);
                chunk.len = 0;
                if (chunk.data != NULL) {
                    chunk.data[0] = '\0';
                }
                ptn_mb_append_utf16be_code_unit(&output, unicode);
            } else if (ptn_mb_euctw_plane_ae_cell_valid(lead, trail)) {
                char translated[4] = { (char)0x8e, (char)0xa3, (char)lead, (char)trail };
                ptn_string_buffer_append_len(&chunk, translated, sizeof(translated));
            } else {
                size_t skip = ptn_mb_euctw_invalid_input_skip(input + i, input_len - i);
                if (skip == 0) {
                    skip = 1;
                }
                ptn_string_buffer_append_len(&chunk, input + i, skip);
                i += skip;
                continue;
            }
            i += 4;
            continue;
        }
        ptn_string_buffer_append_char(&chunk, input[i]);
        i++;
    }
    ptn_mb_euctw_decode_chunk_append(&output, chunk.data, chunk.len, replacement, replacement_len, illegal_chars);
    free(chunk.data);
    *output_len = output.len;
    return output.data;
}

static char *ptn_mb_table_decode_convert_alloc_options(
    const char *input,
    size_t input_len,
    const char *from_encoding,
    const char *to_encoding,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars,
    size_t *output_len
) {
    size_t replacement_utf16_len = 0;
    char *replacement_utf16 = ptn_mb_substitute_bytes_for_encoding_alloc("UTF-16BE", &replacement_utf16_len);
    size_t utf16_len = 0;
    char *utf16 = NULL;
    if (ptn_mb_encoding_is_cp936_table(from_encoding)) {
        utf16 = ptn_mb_cp936_to_utf16be_alloc_options(input, input_len, replacement_utf16, replacement_utf16_len, illegal_chars, &utf16_len);
    } else if (ptn_mb_encoding_is_single_byte_override_table(from_encoding)) {
        utf16 = ptn_mb_single_byte_override_to_utf16be_alloc_options(
            input,
            input_len,
            from_encoding,
            replacement_utf16,
            replacement_utf16_len,
            illegal_chars,
            &utf16_len
        );
    } else if (ptn_mb_encoding_is_windows1252_table(from_encoding)) {
        utf16 = ptn_mb_windows1252_to_utf16be_alloc_options(input, input_len, replacement_utf16, replacement_utf16_len, illegal_chars, &utf16_len);
    } else if (ptn_mb_encoding_is_windows1254_table(from_encoding)) {
        utf16 = ptn_mb_windows1254_to_utf16be_alloc_options(input, input_len, replacement_utf16, replacement_utf16_len, illegal_chars, &utf16_len);
    } else {
        utf16 = ptn_mb_euctw_to_utf16be_bulk_alloc_options(input, input_len, replacement_utf16, replacement_utf16_len, illegal_chars, &utf16_len);
    }
    free(replacement_utf16);
    if (ptn_ascii_case_equal(to_encoding, "UTF-16BE")) {
        *output_len = utf16_len;
        return utf16;
    }
    char *converted = ptn_mb_iconv_convert_alloc_options(
        utf16,
        utf16_len,
        "UTF-16BE",
        to_encoding,
        replacement,
        replacement_len,
        illegal_chars,
        output_len
    );
    free(utf16);
    return converted;
}

static char *ptn_mb_table_encode_convert_alloc_options(
    const char *input,
    size_t input_len,
    const char *from_encoding,
    const char *to_encoding,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars,
    size_t *output_len
) {
    size_t replacement_utf16_len = 0;
    char *replacement_utf16 = ptn_mb_substitute_bytes_for_encoding_alloc("UTF-16BE", &replacement_utf16_len);
    size_t utf16_len = 0;
    char *utf16 = ptn_ascii_case_equal(from_encoding, "UTF-16BE")
        ? ptn_duplicate_string_len(input, input_len)
        : ptn_mb_iconv_convert_alloc_options(
            input,
            input_len,
            from_encoding,
            "UTF-16BE",
            replacement_utf16,
            replacement_utf16_len,
            illegal_chars,
            &utf16_len
        );
    if (ptn_ascii_case_equal(from_encoding, "UTF-16BE")) {
        utf16_len = input_len;
    }
    free(replacement_utf16);

    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    size_t offset = 0;
    while (offset + 1 < utf16_len) {
        uint16_t unicode = (uint16_t)(((uint16_t)(unsigned char)utf16[offset] << 8) | (unsigned char)utf16[offset + 1]);
        char encoded[8];
        size_t encoded_len = 0;
        int ok = 0;
        if (unicode < 0xd800 || unicode > 0xdfff) {
            if (ptn_mb_encoding_is_cp936_table(to_encoding)) {
                ok = ptn_mb_cp936_encode_code_unit(unicode, encoded, &encoded_len);
            } else if (ptn_mb_encoding_is_single_byte_override_table(to_encoding)) {
                ok = ptn_mb_single_byte_override_encode_code_unit(to_encoding, unicode, encoded, &encoded_len);
            } else if (ptn_mb_encoding_is_windows1252_table(to_encoding)) {
                ok = ptn_mb_windows1252_encode_code_unit(unicode, encoded, &encoded_len);
            } else if (ptn_mb_encoding_is_windows1254_table(to_encoding)) {
                ok = ptn_mb_windows1254_encode_code_unit(unicode, encoded, &encoded_len);
            } else {
                ok = ptn_mb_euctw_encode_code_unit(unicode, encoded, &encoded_len);
            }
        }
        if (ok) {
            ptn_string_buffer_append_len(&output, encoded, encoded_len);
        } else {
            ptn_mb_append_table_replacement(&output, replacement, replacement_len, illegal_chars);
        }
        offset += 2;
    }
    if (offset < utf16_len) {
        ptn_mb_append_table_replacement(&output, replacement, replacement_len, illegal_chars);
    }
    free(utf16);
    *output_len = output.len;
    return output.data;
}

static uint16_t ptn_mb_read_utf16_code_unit(const char *input, int little_endian) {
    unsigned char b0 = (unsigned char)input[0];
    unsigned char b1 = (unsigned char)input[1];
    if (little_endian) {
        return (uint16_t)(((uint16_t)b1 << 8) | b0);
    }
    return (uint16_t)(((uint16_t)b0 << 8) | b1);
}

static int ptn_mb_decode_utf16_source_codepoint(
    const char *input,
    size_t input_len,
    int little_endian,
    uint32_t *cp,
    size_t *skip
) {
    if (input_len < 2) {
        return 0;
    }
    uint16_t first = ptn_mb_read_utf16_code_unit(input, little_endian);
    if (first >= 0xd800 && first <= 0xdbff) {
        if (input_len < 4) {
            return 0;
        }
        uint16_t second = ptn_mb_read_utf16_code_unit(input + 2, little_endian);
        if (second < 0xdc00 || second > 0xdfff) {
            return 0;
        }
        *cp = 0x10000 + ((((uint32_t)first - 0xd800) << 10) | ((uint32_t)second - 0xdc00));
        *skip = 4;
        return 1;
    }
    if (first >= 0xdc00 && first <= 0xdfff) {
        return 0;
    }
    *cp = first;
    *skip = 2;
    return 1;
}

static int ptn_mb_decode_source_codepoint_for_substitution(
    const char *encoding,
    const char *input,
    size_t input_len,
    uint32_t *cp,
    size_t *skip
) {
    if (encoding == NULL) {
        return 0;
    }
    size_t valid_sequence_len = 0;
    if (ptn_mb_encoding_is_utf8(encoding) &&
        ptn_mb_utf8_valid_sequence_len_at(input, input_len, 0, &valid_sequence_len)) {
        size_t cp_offset = 0;
        uint32_t decoded = 0;
        if (ptn_mb_utf8_decode_one(input, input_len, &cp_offset, &decoded)) {
            *cp = decoded;
            *skip = valid_sequence_len;
            return 1;
        }
    }
    if (ptn_ascii_case_equal(encoding, "UTF-16BE") ||
        ptn_ascii_case_equal(encoding, "UCS-2BE") ||
        ptn_ascii_case_equal(encoding, "byte2be")) {
        return ptn_mb_decode_utf16_source_codepoint(input, input_len, 0, cp, skip);
    }
    if (ptn_ascii_case_equal(encoding, "UTF-16LE") ||
        ptn_ascii_case_equal(encoding, "UCS-2LE") ||
        ptn_ascii_case_equal(encoding, "byte2le")) {
        return ptn_mb_decode_utf16_source_codepoint(input, input_len, 1, cp, skip);
    }
    return 0;
}


static char *ptn_mb_iconv_convert_alloc_options(
    const char *input,
    size_t input_len,
    const char *from_encoding,
    const char *to_encoding,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars,
    size_t *output_len
) {
    const char *from_iconv = ptn_mb_iconv_encoding_name(from_encoding);
    const char *to_iconv = ptn_mb_iconv_encoding_name(to_encoding);
    if (ptn_mb_encoding_is_jis_family(from_encoding) || ptn_mb_encoding_is_jis_family(to_encoding)) {
        return ptn_mb_jis_convert_alloc_options(
            input,
            input_len,
            from_encoding,
            to_encoding,
            replacement,
            replacement_len,
            illegal_chars,
            output_len
        );
    }
    if (ptn_ascii_case_equal(from_encoding, "UTF7-IMAP")) {
        size_t utf8_len = 0;
        const char *utf7_replacement = replacement;
        size_t utf7_replacement_len = replacement_len;
        char *utf8_replacement = NULL;
        if (!ptn_mb_encoding_is_utf8(to_encoding)) {
            utf8_replacement = ptn_mb_substitute_bytes_for_encoding_alloc("UTF-8", &utf7_replacement_len);
            utf7_replacement = utf8_replacement;
        }
        char *utf8 = ptn_mb_utf7imap_to_utf8_alloc_options(
            input,
            input_len,
            utf7_replacement,
            utf7_replacement_len,
            illegal_chars,
            &utf8_len
        );
        if (ptn_mb_encoding_is_utf8(to_encoding)) {
            *output_len = utf8_len;
            return utf8;
        }
        char *converted = ptn_mb_iconv_convert_alloc_options(
            utf8,
            utf8_len,
            "UTF-8",
            to_encoding,
            replacement,
            replacement_len,
            illegal_chars,
            output_len
        );
        free(utf8_replacement);
        free(utf8);
        return converted;
    }
    if (ptn_mb_encoding_is_utf8_mobile(from_encoding) || ptn_mb_encoding_is_utf8_mobile(to_encoding)) {
        return ptn_mb_utf8_mobile_convert_alloc_options(
            input,
            input_len,
            from_encoding,
            to_encoding,
            replacement,
            replacement_len,
            illegal_chars,
            output_len
        );
    }
    if (ptn_ascii_case_equal(to_encoding, "HZ")) {
        size_t utf8_len = 0;
        char *utf8 = NULL;
        if (ptn_mb_encoding_is_utf8(from_encoding) ||
            ptn_mb_encoding_is_raw(from_encoding) ||
            ptn_ascii_case_equal(from_encoding, "ASCII")) {
            utf8_len = input_len;
            utf8 = ptn_duplicate_string_len(input, input_len);
        } else {
            utf8 = ptn_mb_iconv_convert_alloc_options(
                input,
                input_len,
                from_encoding,
                "UTF-8",
                replacement,
                replacement_len,
                illegal_chars,
                &utf8_len
            );
        }
        char *hz = ptn_mb_utf8_to_hz_alloc_options(
            utf8,
            utf8_len,
            replacement,
            replacement_len,
            illegal_chars,
            output_len
        );
        free(utf8);
        return hz;
    }
    if (from_iconv == NULL || to_iconv == NULL || ptn_ascii_case_equal(from_iconv, to_iconv)) {
        *output_len = input_len;
        return ptn_duplicate_string_len(input, input_len);
    }
    if (ptn_mb_encoding_is_table(from_encoding)) {
        return ptn_mb_table_decode_convert_alloc_options(
            input,
            input_len,
            from_encoding,
            to_encoding,
            replacement,
            replacement_len,
            illegal_chars,
            output_len
        );
    }
    if (ptn_mb_encoding_is_table(to_encoding)) {
        return ptn_mb_table_encode_convert_alloc_options(
            input,
            input_len,
            from_encoding,
            to_encoding,
            replacement,
            replacement_len,
            illegal_chars,
            output_len
        );
    }
#if defined(_WIN32)
    *output_len = input_len;
    return ptn_duplicate_string_len(input, input_len);
#else
    int cached = 0;
    iconv_t cd = ptn_mb_cached_iconv_open(to_iconv, from_iconv, &cached);
    if (cd == (iconv_t)-1) {
        *output_len = input_len;
        return ptn_duplicate_string_len(input, input_len);
    }
    size_t out_cap = input_len < 32 ? 128 : input_len * 4 + 32;
    char *output = malloc(out_cap);
    if (output == NULL) {
        ptn_mb_iconv_finish_one(cd, cached);
        ptn_abort_out_of_memory();
    }
    char *in_ptr = (char *)input;
    size_t in_left = input_len;
    char *out_ptr = output;
    size_t out_left = out_cap - 1;
    while (in_left > 0) {
        size_t converted = iconv(cd, &in_ptr, &in_left, &out_ptr, &out_left);
        if (converted != (size_t)-1) {
            continue;
        }
        if (errno == E2BIG) {
            ptn_mb_iconv_ensure_output_capacity(&output, &out_cap, &out_ptr, &out_left, out_left + 1);
            continue;
        }
        if (illegal_chars != NULL) {
            (*illegal_chars)++;
        }
        char *dynamic_replacement = NULL;
        const char *append_replacement = replacement;
        size_t append_replacement_len = replacement_len;
        size_t skip = ptn_mb_invalid_input_skip(from_encoding, input, in_ptr, in_left, errno == EINVAL);
        uint32_t source_cp = 0;
        size_t source_skip = 0;
        if (ptn_mb_decode_source_codepoint_for_substitution(from_encoding, in_ptr, in_left, &source_cp, &source_skip)) {
            dynamic_replacement = ptn_mb_substitute_bytes_for_codepoint_alloc(to_encoding, source_cp, &append_replacement_len);
            append_replacement = dynamic_replacement;
            skip = source_skip;
        }
        if (append_replacement_len > 0) {
            ptn_mb_iconv_ensure_output_capacity(&output, &out_cap, &out_ptr, &out_left, append_replacement_len);
            memcpy(out_ptr, append_replacement, append_replacement_len);
            out_ptr += append_replacement_len;
            out_left -= append_replacement_len;
        }
        free(dynamic_replacement);
        in_ptr += skip;
        in_left -= skip;
    }
    for (;;) {
        size_t converted = iconv(cd, NULL, NULL, &out_ptr, &out_left);
        if (converted != (size_t)-1) {
            break;
        }
        if (errno != E2BIG) {
            break;
        }
        size_t used = (size_t)(out_ptr - output);
        if (out_cap > SIZE_MAX / 2) {
            ptn_mb_iconv_finish_one(cd, cached);
            free(output);
            ptn_abort_out_of_memory();
        }
        out_cap *= 2;
        char *grown = realloc(output, out_cap);
        if (grown == NULL) {
            ptn_mb_iconv_finish_one(cd, cached);
            free(output);
            ptn_abort_out_of_memory();
        }
        output = grown;
        out_ptr = output + used;
        out_left = out_cap - used - 1;
    }
    *out_ptr = '\0';
    *output_len = (size_t)(out_ptr - output);
    ptn_mb_iconv_finish_one(cd, cached);
    return output;
#endif
}

static uint32_t ptn_mb_substitute_character_codepoint_current(void) {
    const char *value = ptn_mb_current_substitute_character();
    char *end = NULL;
    long parsed = strtol(value, &end, 10);
    if (end != value && end != NULL && *end == '\0' && parsed >= 0 && parsed <= 0x10ffff &&
        !(parsed >= 0xd800 && parsed <= 0xdfff)) {
        return (uint32_t)parsed;
    }
    return ptn_mb_substitute_character_codepoint;
}

static char *ptn_mb_substitute_bytes_for_encoding_alloc(const char *to_encoding, size_t *replacement_len) {
    const char *mode = ptn_mb_current_substitute_character();
    uint32_t cp = ptn_mb_substitute_character_codepoint_current();
    if (cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) {
        cp = 0x3f;
    }

    static char *cached_encoding = NULL;
    static char *cached_mode = NULL;
    static char *cached_bytes = NULL;
    static size_t cached_len = 0;
    static uint32_t cached_cp = 0;
    if (cached_encoding != NULL &&
        cached_mode != NULL &&
        cached_bytes != NULL &&
        cached_cp == cp &&
        strcmp(cached_encoding, to_encoding) == 0 &&
        strcmp(cached_mode, mode) == 0) {
        *replacement_len = cached_len;
        return ptn_duplicate_string_len(cached_bytes, cached_len);
    }

    char *replacement = NULL;
    if (ptn_ascii_case_equal(mode, "none")) {
        *replacement_len = 0;
        replacement = ptn_duplicate_string_len("", 0);
    } else {
        char utf8[4];
        size_t utf8_len = ptn_mb_codepoint_to_utf8(cp, utf8);
        int64_t illegal_delta = 0;
        replacement = ptn_mb_iconv_convert_alloc_options(
            utf8,
            utf8_len,
            "UTF-8",
            to_encoding,
            "?",
            1,
            &illegal_delta,
            replacement_len
        );
        if (illegal_delta > 0) {
            free(replacement);
            *replacement_len = 1;
            replacement = ptn_duplicate_string_len("?", 1);
        }
    }

    free(cached_encoding);
    free(cached_mode);
    free(cached_bytes);
    cached_encoding = ptn_duplicate_string(to_encoding);
    cached_mode = ptn_duplicate_string(mode);
    cached_bytes = ptn_duplicate_string_len(replacement, *replacement_len);
    cached_len = *replacement_len;
    cached_cp = cp;
    return replacement;
}

static char *ptn_mb_substitute_bytes_for_codepoint_alloc(const char *to_encoding, uint32_t source_cp, size_t *replacement_len) {
    const char *mode = ptn_mb_current_substitute_character();
    if (ptn_ascii_case_equal(mode, "long")) {
        return ptn_mb_substitute_text_alloc("U+%X", source_cp, replacement_len);
    }
    if (ptn_ascii_case_equal(mode, "entity")) {
        return ptn_mb_substitute_text_alloc("&#x%X;", source_cp, replacement_len);
    }
    return ptn_mb_substitute_bytes_for_encoding_alloc(to_encoding, replacement_len);
}

static void ptn_mb_hz_close_shift(PtnStringBuffer *output, int *gb_mode) {
    if (*gb_mode) {
        ptn_string_buffer_append(output, "~}");
        *gb_mode = 0;
    }
}

static void ptn_mb_hz_append_ascii(PtnStringBuffer *output, unsigned char byte, int *gb_mode) {
    ptn_mb_hz_close_shift(output, gb_mode);
    if (byte == '~') {
        ptn_string_buffer_append(output, "~~");
    } else {
        ptn_string_buffer_append_char(output, (char)byte);
    }
}

static void ptn_mb_hz_append_replacement(PtnStringBuffer *output, uint32_t cp, int has_cp, int *gb_mode) {
    ptn_mb_hz_close_shift(output, gb_mode);
    size_t replacement_len = 0;
    char *replacement = has_cp
        ? ptn_mb_substitute_bytes_for_codepoint_alloc("ASCII", cp, &replacement_len)
        : ptn_mb_substitute_bytes_for_encoding_alloc("ASCII", &replacement_len);
    ptn_string_buffer_append_len(output, replacement, replacement_len);
    free(replacement);
}

static char *ptn_mb_utf8_to_hz_alloc_options(
    const char *input,
    size_t input_len,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars,
    size_t *output_len
) {
    (void)replacement;
    (void)replacement_len;
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    int gb_mode = 0;
    size_t offset = 0;
    while (offset < input_len) {
        size_t before = offset;
        uint32_t cp = 0;
        if (!ptn_mb_utf8_decode_one(input, input_len, &offset, &cp)) {
            if (illegal_chars != NULL) {
                (*illegal_chars)++;
            }
            ptn_mb_hz_append_replacement(&output, 0, 0, &gb_mode);
            offset = before + 1;
            continue;
        }
        if (cp < 0x80) {
            ptn_mb_hz_append_ascii(&output, (unsigned char)cp, &gb_mode);
            continue;
        }
        size_t gb_len = 0;
        int64_t local_illegal = 0;
        char *gb = ptn_mb_iconv_convert_alloc_options(
            input + before,
            offset - before,
            "UTF-8",
            "GB2312",
            "",
            0,
            &local_illegal,
            &gb_len
        );
        if (local_illegal == 0 && gb_len == 2 &&
            (unsigned char)gb[0] >= 0xa1 && (unsigned char)gb[1] >= 0xa1) {
            if (!gb_mode) {
                ptn_string_buffer_append(&output, "~{");
                gb_mode = 1;
            }
            ptn_string_buffer_append_char(&output, (char)((unsigned char)gb[0] & 0x7f));
            ptn_string_buffer_append_char(&output, (char)((unsigned char)gb[1] & 0x7f));
        } else {
            if (illegal_chars != NULL) {
                (*illegal_chars)++;
            }
            ptn_mb_hz_append_replacement(&output, cp, 1, &gb_mode);
        }
        free(gb);
    }
    ptn_mb_hz_close_shift(&output, &gb_mode);
    *output_len = output.len;
    return output.data == NULL ? ptn_duplicate_string_len("", 0) : output.data;
}

static char *ptn_mb_iconv_convert_alloc(
    const char *input,
    size_t input_len,
    const char *from_encoding,
    const char *to_encoding,
    size_t *output_len
) {
    return ptn_mb_iconv_convert_alloc_options(input, input_len, from_encoding, to_encoding, "?", 1, NULL, output_len);
}

static uint32_t ptn_mb_substitute_character_codepoint_current(void);

static int ptn_mb_encoding_is_ucs4_family(const char *encoding) {
    return ptn_ascii_case_equal(encoding, "UCS-4") ||
        ptn_ascii_case_equal(encoding, "UCS-4BE") ||
        ptn_ascii_case_equal(encoding, "UCS-4LE") ||
        ptn_ascii_case_equal(encoding, "UTF-32") ||
        ptn_ascii_case_equal(encoding, "UTF-32BE") ||
        ptn_ascii_case_equal(encoding, "UTF-32LE") ||
        ptn_ascii_case_equal(encoding, "byte4be") ||
        ptn_ascii_case_equal(encoding, "byte4le");
}

static char *ptn_mb_substitute_utf8_bytes_alloc(size_t *replacement_len) {
    const char *mode = ptn_mb_current_substitute_character();
    if (ptn_ascii_case_equal(mode, "none")) {
        *replacement_len = 0;
        return ptn_duplicate_string_len("", 0);
    }
    uint32_t cp = ptn_mb_substitute_character_codepoint_current();
    if (cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) {
        cp = 0x3f;
    }
    char utf8[4];
    *replacement_len = ptn_mb_codepoint_to_utf8(cp, utf8);
    return ptn_duplicate_string_len(utf8, *replacement_len);
}

static void ptn_mb_append_utf8_substitute(PtnStringBuffer *buffer) {
    size_t replacement_len = 0;
    char *replacement = ptn_mb_substitute_utf8_bytes_alloc(&replacement_len);
    if (replacement_len > 0) {
        ptn_string_buffer_append_len(buffer, replacement, replacement_len);
    }
    free(replacement);
}

static void ptn_mb_append_invalid_ucs4_marker(PtnStringBuffer *buffer, uint32_t codepoint, int has_codepoint) {
    const char *mode = ptn_mb_current_substitute_character();
    if (has_codepoint && ptn_ascii_case_equal(mode, "long")) {
        char marker[16];
        int written = snprintf(marker, sizeof(marker), "U+%X", codepoint);
        if (written < 0 || (size_t)written >= sizeof(marker)) {
            ptn_abort_out_of_memory();
        }
        ptn_string_buffer_append_len(buffer, marker, (size_t)written);
        return;
    }
    ptn_mb_append_utf8_substitute(buffer);
}

static int ptn_mb_ucs4_endian_and_offset(const char *input, size_t input_len, const char *encoding, int *little_out, size_t *offset_out) {
    int little = ptn_ascii_case_equal(encoding, "UCS-4LE") ||
        ptn_ascii_case_equal(encoding, "UTF-32LE") ||
        ptn_ascii_case_equal(encoding, "byte4le");
    size_t offset = 0;
    if (ptn_ascii_case_equal(encoding, "UCS-4") || ptn_ascii_case_equal(encoding, "UTF-32")) {
        little = 0;
        if (input_len >= 4 &&
            (unsigned char)input[0] == 0xff &&
            (unsigned char)input[1] == 0xfe &&
            (unsigned char)input[2] == 0x00 &&
            (unsigned char)input[3] == 0x00) {
            little = 1;
            offset = 4;
        } else if (input_len >= 4 &&
            (unsigned char)input[0] == 0x00 &&
            (unsigned char)input[1] == 0x00 &&
            (unsigned char)input[2] == 0xfe &&
            (unsigned char)input[3] == 0xff) {
            little = 0;
            offset = 4;
        }
    }
    *little_out = little;
    *offset_out = offset;
    return 1;
}

static uint32_t ptn_mb_ucs4_read_codepoint(const char *data, int little) {
    const unsigned char *bytes = (const unsigned char *)data;
    if (little) {
        return ((uint32_t)bytes[3] << 24) |
            ((uint32_t)bytes[2] << 16) |
            ((uint32_t)bytes[1] << 8) |
            (uint32_t)bytes[0];
    }
    return ((uint32_t)bytes[0] << 24) |
        ((uint32_t)bytes[1] << 16) |
        ((uint32_t)bytes[2] << 8) |
        (uint32_t)bytes[3];
}

static int ptn_mb_ucs4_codepoint_valid(uint32_t codepoint) {
    return codepoint <= 0x10ffff && !(codepoint >= 0xd800 && codepoint <= 0xdfff);
}

static int ptn_mb_ucs4_validate_bytes(const char *input, size_t input_len, const char *encoding) {
    int little = 0;
    size_t offset = 0;
    ptn_mb_ucs4_endian_and_offset(input, input_len, encoding, &little, &offset);
    if ((input_len - offset) % 4 != 0) {
        return 0;
    }
    while (offset < input_len) {
        uint32_t codepoint = ptn_mb_ucs4_read_codepoint(input + offset, little);
        if (!ptn_mb_ucs4_codepoint_valid(codepoint)) {
            return 0;
        }
        offset += 4;
    }
    return 1;
}

static char *ptn_mb_ucs4_to_utf8_alloc(
    const char *input,
    size_t input_len,
    const char *encoding,
    int64_t *illegal_chars,
    size_t *output_len
) {
    int little = 0;
    size_t offset = 0;
    ptn_mb_ucs4_endian_and_offset(input, input_len, encoding, &little, &offset);
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    while (offset < input_len) {
        if (input_len - offset < 4) {
            if (illegal_chars != NULL) {
                (*illegal_chars)++;
            }
            ptn_mb_append_invalid_ucs4_marker(&output, 0, 0);
            break;
        }
        uint32_t codepoint = ptn_mb_ucs4_read_codepoint(input + offset, little);
        if (!ptn_mb_ucs4_codepoint_valid(codepoint)) {
            if (illegal_chars != NULL) {
                (*illegal_chars)++;
            }
            ptn_mb_append_invalid_ucs4_marker(&output, codepoint, 1);
            offset += 4;
            continue;
        }
        char encoded[4];
        size_t encoded_len = ptn_mb_codepoint_to_utf8(codepoint, encoded);
        ptn_string_buffer_append_len(&output, encoded, encoded_len);
        offset += 4;
    }
    *output_len = output.len;
    if (output.data == NULL) {
        return ptn_duplicate_string_len("", 0);
    }
    return output.data;
}

static int ptn_mb_utf8_is_continuation(unsigned char byte) {
    return (byte & 0xc0) == 0x80;
}

static int ptn_mb_utf8_second_byte_valid(unsigned char lead, unsigned char byte) {
    if (lead == 0xe0) {
        return byte >= 0xa0 && byte <= 0xbf;
    }
    if (lead >= 0xe1 && lead <= 0xec) {
        return ptn_mb_utf8_is_continuation(byte);
    }
    if (lead == 0xed) {
        return byte >= 0x80 && byte <= 0x9f;
    }
    if (lead >= 0xee && lead <= 0xef) {
        return ptn_mb_utf8_is_continuation(byte);
    }
    if (lead == 0xf0) {
        return byte >= 0x90 && byte <= 0xbf;
    }
    if (lead >= 0xf1 && lead <= 0xf3) {
        return ptn_mb_utf8_is_continuation(byte);
    }
    if (lead == 0xf4) {
        return byte >= 0x80 && byte <= 0x8f;
    }
    return 0;
}

static int ptn_mb_utf8_valid_sequence_len_at(const char *data, size_t len, size_t offset, size_t *sequence_len) {
    unsigned char lead = (unsigned char)data[offset];
    if (lead < 0x80) {
        *sequence_len = 1;
        return 1;
    }
    if (lead >= 0xc2 && lead <= 0xdf) {
        if (offset + 1 < len && ptn_mb_utf8_is_continuation((unsigned char)data[offset + 1])) {
            *sequence_len = 2;
            return 1;
        }
        return 0;
    }
    if (lead >= 0xe0 && lead <= 0xef) {
        if (offset + 2 < len &&
            ptn_mb_utf8_second_byte_valid(lead, (unsigned char)data[offset + 1]) &&
            ptn_mb_utf8_is_continuation((unsigned char)data[offset + 2])) {
            *sequence_len = 3;
            return 1;
        }
        return 0;
    }
    if (lead >= 0xf0 && lead <= 0xf4) {
        if (offset + 3 < len &&
            ptn_mb_utf8_second_byte_valid(lead, (unsigned char)data[offset + 1]) &&
            ptn_mb_utf8_is_continuation((unsigned char)data[offset + 2]) &&
            ptn_mb_utf8_is_continuation((unsigned char)data[offset + 3])) {
            *sequence_len = 4;
            return 1;
        }
        return 0;
    }
    return 0;
}

static size_t ptn_mb_utf8_invalid_sequence_len_at(const char *data, size_t len, size_t offset) {
    unsigned char lead = (unsigned char)data[offset];
    if (lead < 0x80) {
        return 0;
    }
    if (lead >= 0xc2 && lead <= 0xdf) {
        return 1;
    }
    if (lead >= 0xe0 && lead <= 0xef) {
        if (offset + 1 >= len || !ptn_mb_utf8_second_byte_valid(lead, (unsigned char)data[offset + 1])) {
            return 1;
        }
        if (offset + 2 >= len || !ptn_mb_utf8_is_continuation((unsigned char)data[offset + 2])) {
            return 2;
        }
        return 1;
    }
    if (lead >= 0xf0 && lead <= 0xf4) {
        if (offset + 1 >= len || !ptn_mb_utf8_second_byte_valid(lead, (unsigned char)data[offset + 1])) {
            return 1;
        }
        if (offset + 2 >= len || !ptn_mb_utf8_is_continuation((unsigned char)data[offset + 2])) {
            return 2;
        }
        if (offset + 3 >= len || !ptn_mb_utf8_is_continuation((unsigned char)data[offset + 3])) {
            return 3;
        }
        return 1;
    }
    return 1;
}

static char *ptn_mb_utf8_replace_invalid_alloc(
    const char *input,
    size_t input_len,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars,
    size_t *output_len
) {
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    size_t offset = 0;
    while (offset < input_len) {
        size_t sequence_len = 0;
        if (ptn_mb_utf8_valid_sequence_len_at(input, input_len, offset, &sequence_len)) {
            ptn_string_buffer_append_len(&output, input + offset, sequence_len);
            offset += sequence_len;
            continue;
        }
        size_t invalid_len = ptn_mb_utf8_invalid_sequence_len_at(input, input_len, offset);
        if (invalid_len == 0) {
            invalid_len = 1;
        }
        if (illegal_chars != NULL) {
            (*illegal_chars)++;
        }
        if (replacement_len > 0) {
            ptn_string_buffer_append_len(&output, replacement, replacement_len);
        }
        offset += invalid_len;
    }
    *output_len = output.len;
    if (output.data == NULL) {
        return ptn_duplicate_string_len("", 0);
    }
    return output.data;
}

static char *ptn_mb_iconv_convert_alloc_counting(
    const char *input,
    size_t input_len,
    const char *from_encoding,
    const char *to_encoding,
    size_t *output_len
) {
    size_t replacement_len = 0;
    char *replacement = ptn_mb_substitute_bytes_for_encoding_alloc(to_encoding, &replacement_len);
    int64_t illegal_delta = 0;
    if (ptn_mb_encoding_is_ucs4_family(from_encoding)) {
        size_t utf8_len = 0;
        char *utf8 = ptn_mb_ucs4_to_utf8_alloc(input, input_len, from_encoding, &illegal_delta, &utf8_len);
        char *result = NULL;
        if (ptn_mb_encoding_is_utf8(to_encoding)) {
            result = utf8;
            *output_len = utf8_len;
        } else {
            int64_t target_illegal_delta = 0;
            result = ptn_mb_iconv_convert_alloc_options(
                utf8,
                utf8_len,
                "UTF-8",
                to_encoding,
                replacement,
                replacement_len,
                &target_illegal_delta,
                output_len
            );
            illegal_delta += target_illegal_delta;
            free(utf8);
        }
        free(replacement);
        ptn_mb_illegal_chars += illegal_delta;
        return result;
    }
    if (ptn_mb_encoding_is_utf8(from_encoding) && ptn_mb_encoding_is_utf8(to_encoding)) {
        char *result = ptn_mb_utf8_replace_invalid_alloc(
            input,
            input_len,
            replacement,
            replacement_len,
            &illegal_delta,
            output_len
        );
        free(replacement);
        ptn_mb_illegal_chars += illegal_delta;
        return result;
    }
    char *result = ptn_mb_iconv_convert_alloc_options(
        input,
        input_len,
        from_encoding,
        to_encoding,
        replacement,
        replacement_len,
        &illegal_delta,
        output_len
    );
    free(replacement);
    ptn_mb_illegal_chars += illegal_delta;
    return result;
}

static char *ptn_mb_hz_to_utf8_alloc(const char *input, size_t input_len, size_t *output_len) {
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    int gb_mode = 0;
    for (size_t i = 0; i < input_len;) {
        unsigned char byte = (unsigned char)input[i];
        if (!gb_mode) {
            if (byte == '~' && i + 1 < input_len) {
                unsigned char next = (unsigned char)input[i + 1];
                if (next == '{') {
                    gb_mode = 1;
                    i += 2;
                    continue;
                }
                if (next == '}') {
                    i += 2;
                    continue;
                }
                if (next == '~') {
                    ptn_string_buffer_append_char(&output, '~');
                    i += 2;
                    continue;
                }
                if (next == '\n') {
                    i += 2;
                    continue;
                }
            }
            ptn_string_buffer_append_char(&output, (char)byte);
            i++;
            continue;
        }
        if (byte == '~' && i + 1 < input_len && input[i + 1] == '}') {
            gb_mode = 0;
            i += 2;
            continue;
        }
        if (i + 1 >= input_len) {
            ptn_mb_append_utf8_substitute(&output);
            ptn_mb_illegal_chars++;
            break;
        }
        char gb_pair[2] = {
            (char)((unsigned char)input[i] | 0x80),
            (char)((unsigned char)input[i + 1] | 0x80)
        };
        size_t chunk_len = 0;
        int64_t illegal_delta = 0;
        char *chunk = ptn_mb_iconv_convert_alloc_options(
            gb_pair,
            sizeof(gb_pair),
            "GB2312",
            "UTF-8",
            "?",
            1,
            &illegal_delta,
            &chunk_len
        );
        ptn_mb_illegal_chars += illegal_delta;
        ptn_string_buffer_append_len(&output, chunk, chunk_len);
        free(chunk);
        i += 2;
    }
    *output_len = output.len;
    return output.data == NULL ? ptn_duplicate_string_len("", 0) : output.data;
}

static int ptn_mb_utf8_decode_one(const char *data, size_t len, size_t *offset, uint32_t *codepoint) {
    if (*offset >= len) {
        return 0;
    }
    unsigned char b0 = (unsigned char)data[*offset];
    if (b0 < 0x80) {
        *codepoint = b0;
        (*offset)++;
        return 1;
    }
    size_t need = 0;
    uint32_t cp = 0;
    uint32_t min = 0;
    if ((b0 & 0xe0) == 0xc0) {
        need = 2;
        cp = b0 & 0x1f;
        min = 0x80;
    } else if ((b0 & 0xf0) == 0xe0) {
        need = 3;
        cp = b0 & 0x0f;
        min = 0x800;
    } else if ((b0 & 0xf8) == 0xf0) {
        need = 4;
        cp = b0 & 0x07;
        min = 0x10000;
    } else {
        *codepoint = 0xfffd;
        (*offset)++;
        return 1;
    }
    if (*offset + need > len) {
        *codepoint = 0xfffd;
        (*offset)++;
        return 1;
    }
    for (size_t i = 1; i < need; i++) {
        unsigned char bx = (unsigned char)data[*offset + i];
        if ((bx & 0xc0) != 0x80) {
            *codepoint = 0xfffd;
            (*offset)++;
            return 1;
        }
        cp = (cp << 6) | (uint32_t)(bx & 0x3f);
    }
    if (cp < min || cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) {
        *codepoint = 0xfffd;
        (*offset)++;
        return 1;
    }
    *codepoint = cp;
    *offset += need;
    return 1;
}

static int ptn_mb_encoding_is_utf8_mobile(const char *encoding) {
    return encoding != NULL &&
        (ptn_ascii_case_equal(encoding, "UTF-8-Mobile#DOCOMO") ||
         ptn_ascii_case_equal(encoding, "UTF-8-Mobile#KDDI-A") ||
         ptn_ascii_case_equal(encoding, "UTF-8-Mobile#KDDI-B") ||
         ptn_ascii_case_equal(encoding, "UTF-8-Mobile#SOFTBANK"));
}

static int ptn_mb_utf8_mobile_tables(
    const char *encoding,
    const PtnMbUtf8MobileMapEntry **map,
    size_t *map_len,
    const uint32_t **bad,
    size_t *bad_len
) {
    if (ptn_ascii_case_equal(encoding, "UTF-8-Mobile#DOCOMO")) {
        *map = PTN_MB_UTF8_MOBILE_DOCOMO_MAP;
        *map_len = sizeof(PTN_MB_UTF8_MOBILE_DOCOMO_MAP) / sizeof(PTN_MB_UTF8_MOBILE_DOCOMO_MAP[0]);
        *bad = PTN_MB_UTF8_MOBILE_DOCOMO_BAD;
        *bad_len = sizeof(PTN_MB_UTF8_MOBILE_DOCOMO_BAD) / sizeof(PTN_MB_UTF8_MOBILE_DOCOMO_BAD[0]);
        return 1;
    }
    if (ptn_ascii_case_equal(encoding, "UTF-8-Mobile#KDDI-A")) {
        *map = PTN_MB_UTF8_MOBILE_KDDI_A_MAP;
        *map_len = sizeof(PTN_MB_UTF8_MOBILE_KDDI_A_MAP) / sizeof(PTN_MB_UTF8_MOBILE_KDDI_A_MAP[0]);
        *bad = PTN_MB_UTF8_MOBILE_KDDI_A_BAD;
        *bad_len = sizeof(PTN_MB_UTF8_MOBILE_KDDI_A_BAD) / sizeof(PTN_MB_UTF8_MOBILE_KDDI_A_BAD[0]);
        return 1;
    }
    if (ptn_ascii_case_equal(encoding, "UTF-8-Mobile#KDDI-B")) {
        *map = PTN_MB_UTF8_MOBILE_KDDI_B_MAP;
        *map_len = sizeof(PTN_MB_UTF8_MOBILE_KDDI_B_MAP) / sizeof(PTN_MB_UTF8_MOBILE_KDDI_B_MAP[0]);
        *bad = PTN_MB_UTF8_MOBILE_KDDI_B_BAD;
        *bad_len = sizeof(PTN_MB_UTF8_MOBILE_KDDI_B_BAD) / sizeof(PTN_MB_UTF8_MOBILE_KDDI_B_BAD[0]);
        return 1;
    }
    if (ptn_ascii_case_equal(encoding, "UTF-8-Mobile#SOFTBANK")) {
        *map = PTN_MB_UTF8_MOBILE_SOFTBANK_MAP;
        *map_len = sizeof(PTN_MB_UTF8_MOBILE_SOFTBANK_MAP) / sizeof(PTN_MB_UTF8_MOBILE_SOFTBANK_MAP[0]);
        *bad = PTN_MB_UTF8_MOBILE_SOFTBANK_BAD;
        *bad_len = sizeof(PTN_MB_UTF8_MOBILE_SOFTBANK_BAD) / sizeof(PTN_MB_UTF8_MOBILE_SOFTBANK_BAD[0]);
        return 1;
    }
    *map = NULL;
    *map_len = 0;
    *bad = NULL;
    *bad_len = 0;
    return 0;
}

static int ptn_mb_utf8_mobile_lookup_from_mobile(const char *encoding, uint32_t mobile, uint32_t *unicode) {
    const PtnMbUtf8MobileMapEntry *map = NULL;
    const uint32_t *bad = NULL;
    size_t map_len = 0;
    size_t bad_len = 0;
    (void)bad;
    (void)bad_len;
    if (!ptn_mb_utf8_mobile_tables(encoding, &map, &map_len, &bad, &bad_len)) {
        return 0;
    }
    for (size_t i = 0; i < map_len; i++) {
        if (map[i].mobile == mobile) {
            *unicode = map[i].unicode;
            return 1;
        }
    }
    return 0;
}

static int ptn_mb_utf8_mobile_lookup_to_mobile(const char *encoding, uint32_t unicode, uint32_t *mobile) {
    const PtnMbUtf8MobileMapEntry *map = NULL;
    const uint32_t *bad = NULL;
    size_t map_len = 0;
    size_t bad_len = 0;
    (void)bad;
    (void)bad_len;
    if (!ptn_mb_utf8_mobile_tables(encoding, &map, &map_len, &bad, &bad_len)) {
        return 0;
    }
    for (size_t i = 0; i < map_len; i++) {
        if (map[i].unicode == unicode) {
            *mobile = map[i].mobile;
            return 1;
        }
    }
    return 0;
}

static int ptn_mb_utf8_mobile_unicode_is_bad(const char *encoding, uint32_t unicode) {
    const PtnMbUtf8MobileMapEntry *map = NULL;
    const uint32_t *bad = NULL;
    size_t map_len = 0;
    size_t bad_len = 0;
    (void)map;
    (void)map_len;
    if (!ptn_mb_utf8_mobile_tables(encoding, &map, &map_len, &bad, &bad_len)) {
        return 0;
    }
    for (size_t i = 0; i < bad_len; i++) {
        if (bad[i] == unicode) {
            return 1;
        }
    }
    return 0;
}

static char *ptn_mb_utf8_mobile_from_variant_to_utf8_alloc_options(
    const char *input,
    size_t input_len,
    const char *from_encoding,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars,
    size_t *output_len
) {
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    size_t offset = 0;
    while (offset < input_len) {
        size_t sequence_len = 0;
        if (ptn_mb_utf8_valid_sequence_len_at(input, input_len, offset, &sequence_len)) {
            size_t decode_offset = offset;
            uint32_t cp = 0;
            ptn_mb_utf8_decode_one(input, input_len, &decode_offset, &cp);
            uint32_t mapped = 0;
            if (ptn_mb_utf8_mobile_lookup_from_mobile(from_encoding, cp, &mapped)) {
                cp = mapped;
            }
            ptn_mb_utf8_append_codepoint(&output, cp);
            offset += sequence_len;
            continue;
        }
        size_t invalid_len = ptn_mb_utf8_invalid_sequence_len_at(input, input_len, offset);
        if (invalid_len == 0) {
            invalid_len = 1;
        }
        if (illegal_chars != NULL) {
            (*illegal_chars)++;
        }
        if (replacement_len > 0) {
            ptn_string_buffer_append_len(&output, replacement, replacement_len);
        }
        offset += invalid_len;
    }
    *output_len = output.len;
    return output.data == NULL ? ptn_duplicate_string_len("", 0) : output.data;
}

static char *ptn_mb_utf8_mobile_from_utf8_to_variant_alloc_options(
    const char *input,
    size_t input_len,
    const char *to_encoding,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars,
    size_t *output_len
) {
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    size_t offset = 0;
    while (offset < input_len) {
        size_t sequence_len = 0;
        if (ptn_mb_utf8_valid_sequence_len_at(input, input_len, offset, &sequence_len)) {
            size_t decode_offset = offset;
            uint32_t cp = 0;
            ptn_mb_utf8_decode_one(input, input_len, &decode_offset, &cp);
            if (ptn_mb_utf8_mobile_unicode_is_bad(to_encoding, cp)) {
                if (illegal_chars != NULL) {
                    (*illegal_chars)++;
                }
                if (replacement_len > 0) {
                    ptn_string_buffer_append_len(&output, replacement, replacement_len);
                }
                offset += sequence_len;
                continue;
            }
            uint32_t mapped = 0;
            if (ptn_mb_utf8_mobile_lookup_to_mobile(to_encoding, cp, &mapped)) {
                cp = mapped;
            }
            ptn_mb_utf8_append_codepoint(&output, cp);
            offset += sequence_len;
            continue;
        }
        size_t invalid_len = ptn_mb_utf8_invalid_sequence_len_at(input, input_len, offset);
        if (invalid_len == 0) {
            invalid_len = 1;
        }
        if (illegal_chars != NULL) {
            (*illegal_chars)++;
        }
        if (replacement_len > 0) {
            ptn_string_buffer_append_len(&output, replacement, replacement_len);
        }
        offset += invalid_len;
    }
    *output_len = output.len;
    return output.data == NULL ? ptn_duplicate_string_len("", 0) : output.data;
}

static char *ptn_mb_utf8_mobile_convert_alloc_options(
    const char *input,
    size_t input_len,
    const char *from_encoding,
    const char *to_encoding,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars,
    size_t *output_len
) {
    char *utf8 = NULL;
    size_t utf8_len = 0;
    const char *source_replacement = replacement;
    size_t source_replacement_len = replacement_len;
    char *utf8_replacement = NULL;
    if (!ptn_mb_encoding_is_utf8(to_encoding)) {
        utf8_replacement = ptn_mb_substitute_bytes_for_encoding_alloc("UTF-8", &source_replacement_len);
        source_replacement = utf8_replacement;
    }
    if (ptn_mb_encoding_is_utf8_mobile(from_encoding)) {
        utf8 = ptn_mb_utf8_mobile_from_variant_to_utf8_alloc_options(
            input,
            input_len,
            from_encoding,
            source_replacement,
            source_replacement_len,
            illegal_chars,
            &utf8_len
        );
    } else if (ptn_mb_encoding_is_utf8(from_encoding)) {
        utf8 = ptn_mb_utf8_replace_invalid_alloc(
            input,
            input_len,
            source_replacement,
            source_replacement_len,
            illegal_chars,
            &utf8_len
        );
    } else {
        utf8 = ptn_mb_iconv_convert_alloc_options(
            input,
            input_len,
            from_encoding,
            "UTF-8",
            source_replacement,
            source_replacement_len,
            illegal_chars,
            &utf8_len
        );
    }

    if (ptn_mb_encoding_is_utf8_mobile(to_encoding)) {
        char *mobile = ptn_mb_utf8_mobile_from_utf8_to_variant_alloc_options(
            utf8,
            utf8_len,
            to_encoding,
            replacement,
            replacement_len,
            illegal_chars,
            output_len
        );
        free(utf8_replacement);
        free(utf8);
        return mobile;
    }
    if (ptn_mb_encoding_is_utf8(to_encoding)) {
        *output_len = utf8_len;
        return utf8;
    }
    char *converted = ptn_mb_iconv_convert_alloc_options(
        utf8,
        utf8_len,
        "UTF-8",
        to_encoding,
        replacement,
        replacement_len,
        illegal_chars,
        output_len
    );
    free(utf8_replacement);
    free(utf8);
    return converted;
}

static int ptn_mb_utf7imap_base64_value(unsigned char byte) {
    if (byte == ',') {
        return 63;
    }
    return ptn_base64_decode_value(byte);
}

static int ptn_mb_utf7imap_direct_byte_valid(unsigned char byte) {
    return byte >= 0x20 && byte <= 0x7e && byte != '&';
}

static void ptn_mb_append_utf7imap_replacement(
    PtnStringBuffer *output,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars
) {
    if (illegal_chars != NULL) {
        (*illegal_chars)++;
    }
    if (replacement_len > 0) {
        ptn_string_buffer_append_len(output, replacement, replacement_len);
    }
}

static char *ptn_mb_utf7imap_decode_base64_bytes_alloc(const char *data, size_t len, size_t *output_len, int *bad_padding) {
    *bad_padding = 0;
    if (len == 0 || len % 4 == 1) {
        *bad_padding = 1;
    }
    int *values = len == 0 ? NULL : malloc(len * sizeof(int));
    if (len != 0 && values == NULL) {
        ptn_abort_out_of_memory();
    }
    for (size_t i = 0; i < len; i++) {
        values[i] = ptn_mb_utf7imap_base64_value((unsigned char)data[i]);
    }
    size_t cap = len == 0 ? 1 : len;
    char *output = malloc(cap + 1);
    if (output == NULL) {
        free(values);
        ptn_abort_out_of_memory();
    }
    size_t out = 0;
    size_t i = 0;
    while (i + 4 <= len) {
        output[out++] = (char)((values[i] << 2) | (values[i + 1] >> 4));
        output[out++] = (char)(((values[i + 1] & 0x0f) << 4) | (values[i + 2] >> 2));
        output[out++] = (char)(((values[i + 2] & 0x03) << 6) | values[i + 3]);
        i += 4;
    }
    size_t remainder = len - i;
    if (remainder == 2) {
        if ((values[i + 1] & 0x0f) != 0) {
            *bad_padding = 1;
        }
        output[out++] = (char)((values[i] << 2) | (values[i + 1] >> 4));
    } else if (remainder == 3) {
        if ((values[i + 2] & 0x03) != 0) {
            *bad_padding = 1;
        }
        output[out++] = (char)((values[i] << 2) | (values[i + 1] >> 4));
        output[out++] = (char)(((values[i + 1] & 0x0f) << 4) | (values[i + 2] >> 2));
    }
    output[out] = '\0';
    free(values);
    *output_len = out;
    return output;
}

static int ptn_mb_utf7imap_append_utf16be_as_utf8(
    PtnStringBuffer *output,
    const char *data,
    size_t len,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars
) {
    int ok = 1;
    size_t offset = 0;
    while (offset < len) {
        if (offset + 1 >= len) {
            ptn_mb_append_utf7imap_replacement(output, replacement, replacement_len, illegal_chars);
            ok = 0;
            break;
        }
        uint16_t first = (uint16_t)(((uint16_t)(unsigned char)data[offset] << 8) | (unsigned char)data[offset + 1]);
        offset += 2;
        uint32_t cp = first;
        if (first >= 0xd800 && first <= 0xdbff) {
            if (offset + 1 >= len) {
                ptn_mb_append_utf7imap_replacement(output, replacement, replacement_len, illegal_chars);
                ok = 0;
                break;
            }
            uint16_t second = (uint16_t)(((uint16_t)(unsigned char)data[offset] << 8) | (unsigned char)data[offset + 1]);
            if (second < 0xdc00 || second > 0xdfff) {
                ptn_mb_append_utf7imap_replacement(output, replacement, replacement_len, illegal_chars);
                ok = 0;
                continue;
            }
            offset += 2;
            cp = 0x10000u + ((((uint32_t)first - 0xd800u) << 10) | ((uint32_t)second - 0xdc00u));
        } else if (first >= 0xdc00 && first <= 0xdfff) {
            ptn_mb_append_utf7imap_replacement(output, replacement, replacement_len, illegal_chars);
            ok = 0;
            continue;
        }
        if (ptn_mb_utf7imap_direct_byte_valid((unsigned char)cp) && cp <= 0x7f) {
            ptn_mb_append_utf7imap_replacement(output, replacement, replacement_len, illegal_chars);
            ok = 0;
            continue;
        }
        ptn_mb_utf8_append_codepoint(output, cp);
    }
    return ok;
}

static char *ptn_mb_utf7imap_to_utf8_alloc_options(
    const char *input,
    size_t input_len,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars,
    size_t *output_len
) {
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    size_t i = 0;
    while (i < input_len) {
        unsigned char byte = (unsigned char)input[i];
        if (ptn_mb_utf7imap_direct_byte_valid(byte)) {
            ptn_string_buffer_append_char(&output, (char)byte);
            i++;
            continue;
        }
        if (byte != '&') {
            ptn_mb_append_utf7imap_replacement(&output, replacement, replacement_len, illegal_chars);
            i++;
            continue;
        }
        if (i + 1 < input_len && input[i + 1] == '-') {
            ptn_string_buffer_append_char(&output, '&');
            i += 2;
            continue;
        }
        size_t section_start = i + 1;
        size_t cursor = section_start;
        while (cursor < input_len && input[cursor] != '-') {
            if (ptn_mb_utf7imap_base64_value((unsigned char)input[cursor]) < 0) {
                break;
            }
            cursor++;
        }
        if (cursor == section_start) {
            ptn_mb_append_utf7imap_replacement(&output, replacement, replacement_len, illegal_chars);
            if (cursor < input_len && input[cursor] == '-') {
                i = cursor + 1;
            } else if (cursor < input_len) {
                i = cursor + 1;
            } else {
                i = cursor;
            }
            continue;
        }
        if (cursor < input_len && input[cursor] != '-') {
            ptn_mb_append_utf7imap_replacement(&output, replacement, replacement_len, illegal_chars);
            i = cursor + 1;
            continue;
        }
        size_t decoded_len = 0;
        int bad_padding = 0;
        char *decoded = ptn_mb_utf7imap_decode_base64_bytes_alloc(
            input + section_start,
            cursor - section_start,
            &decoded_len,
            &bad_padding
        );
        int unicode_ok = ptn_mb_utf7imap_append_utf16be_as_utf8(
            &output,
            decoded,
            decoded_len,
            replacement,
            replacement_len,
            illegal_chars
        );
        int unterminated_partial = cursor >= input_len && ((cursor - section_start) % 4) != 0 && (decoded_len % 2) == 0;
        if ((bad_padding && unicode_ok) || unterminated_partial) {
            ptn_mb_append_utf7imap_replacement(&output, replacement, replacement_len, illegal_chars);
        }
        free(decoded);
        i = cursor < input_len && input[cursor] == '-' ? cursor + 1 : cursor;
    }
    *output_len = output.len;
    return output.data == NULL ? ptn_duplicate_string_len("", 0) : output.data;
}

static int ptn_mb_utf7imap_validate_bytes(const char *data, size_t len) {
    int64_t illegal_delta = 0;
    size_t utf8_len = 0;
    char *utf8 = ptn_mb_utf7imap_to_utf8_alloc_options(data, len, "", 0, &illegal_delta, &utf8_len);
    free(utf8);
    (void)utf8_len;
    return illegal_delta == 0;
}

static int ptn_mb_encoding_is_jis_family(const char *encoding) {
    return encoding != NULL &&
        (ptn_ascii_case_equal(encoding, "JIS") ||
         ptn_ascii_case_equal(encoding, "ISO-2022-JP"));
}

static void ptn_mb_jis_append_ascii_escape(PtnStringBuffer *output) {
    ptn_string_buffer_append_len(output, "\x1b(B", 3);
}

static char *ptn_mb_jis_normalize_to_iso2022jp2_alloc(const char *input, size_t input_len, size_t *output_len) {
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    int state = 0;
    size_t i = 0;
    while (i < input_len) {
        unsigned char byte = (unsigned char)input[i];
        if (byte == 0x1b) {
            if (i + 2 < input_len && input[i + 1] == '(') {
                unsigned char final = (unsigned char)input[i + 2];
                if (final == 'H') {
                    ptn_mb_jis_append_ascii_escape(&output);
                    state = 0;
                    i += 3;
                    continue;
                }
                if (final == 'B' || final == 'J' || final == 'I') {
                    ptn_string_buffer_append_len(&output, input + i, 3);
                    state = final == 'I' ? 1 : 0;
                    i += 3;
                    continue;
                }
            }
            if (i + 2 < input_len && input[i + 1] == '$') {
                unsigned char final = (unsigned char)input[i + 2];
                if (final == '@' || final == 'B') {
                    ptn_string_buffer_append_len(&output, input + i, 3);
                    state = 2;
                    i += 3;
                    continue;
                }
                if (final == '(' && i + 3 < input_len) {
                    unsigned char nested = (unsigned char)input[i + 3];
                    if (nested == '@' || nested == 'B') {
                        ptn_string_buffer_append_char(&output, '\x1b');
                        ptn_string_buffer_append_char(&output, '$');
                        ptn_string_buffer_append_char(&output, (char)nested);
                        state = 2;
                        i += 4;
                        continue;
                    }
                    if (nested == 'D') {
                        ptn_string_buffer_append_len(&output, input + i, 4);
                        state = 3;
                        i += 4;
                        continue;
                    }
                }
            }
        }
        if (state == 2 || state == 3) {
            ptn_string_buffer_append_char(&output, (char)byte);
            i++;
            continue;
        }
        if (byte >= 0xa1 && byte <= 0xdf) {
            ptn_string_buffer_append_len(&output, "\x1b(I", 3);
            ptn_string_buffer_append_char(&output, (char)(byte - 0x80));
            ptn_mb_jis_append_ascii_escape(&output);
            i++;
            continue;
        }
        if (byte == 0x0e) {
            ptn_string_buffer_append_len(&output, "\x1b(I", 3);
            i++;
            while (i < input_len) {
                unsigned char shifted = (unsigned char)input[i];
                if (shifted == 0x0f) {
                    i++;
                    break;
                }
                ptn_string_buffer_append_char(&output, (char)shifted);
                i++;
            }
            ptn_mb_jis_append_ascii_escape(&output);
            continue;
        }
        if (byte == 0x0f) {
            ptn_mb_jis_append_ascii_escape(&output);
            state = 0;
            i++;
            continue;
        }
        ptn_string_buffer_append_char(&output, (char)byte);
        i++;
    }
    *output_len = output.len;
    return output.data == NULL ? ptn_duplicate_string_len("", 0) : output.data;
}

static void ptn_mb_jis_append_state_escape(PtnStringBuffer *output, int state) {
    if (state == 1) {
        ptn_string_buffer_append_len(output, "\x1b(I", 3);
    } else if (state == 2) {
        ptn_string_buffer_append_len(output, "\x1b$B", 3);
    } else if (state == 3) {
        ptn_string_buffer_append_len(output, "\x1b$(D", 4);
    }
}

static void ptn_mb_jis_append_replacement_in_ascii(
    PtnStringBuffer *output,
    const char *replacement,
    size_t replacement_len,
    int state
) {
    if (replacement_len == 0) {
        return;
    }
    if (state != 0) {
        ptn_mb_jis_append_ascii_escape(output);
    }
    ptn_string_buffer_append_len(output, replacement, replacement_len);
    if (state != 0) {
        ptn_mb_jis_append_state_escape(output, state);
    }
}

static char *ptn_mb_jis_collapse_invalid_double_trails_alloc(
    const char *input,
    size_t input_len,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars,
    size_t *output_len
) {
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    int state = 0;
    size_t i = 0;
    while (i < input_len) {
        unsigned char byte = (unsigned char)input[i];
        if (byte == 0x1b) {
            if (i + 2 < input_len && input[i + 1] == '(') {
                unsigned char final = (unsigned char)input[i + 2];
                if (final == 'B' || final == 'H' || final == 'J') {
                    state = 0;
                } else if (final == 'I') {
                    state = 1;
                }
                ptn_string_buffer_append_len(&output, input + i, 3);
                i += 3;
                continue;
            }
            if (i + 2 < input_len && input[i + 1] == '$') {
                unsigned char final = (unsigned char)input[i + 2];
                if (final == '@' || final == 'B') {
                    state = 2;
                    ptn_string_buffer_append_len(&output, input + i, 3);
                    i += 3;
                    continue;
                }
                if (final == '(' && i + 3 < input_len) {
                    unsigned char nested = (unsigned char)input[i + 3];
                    if (nested == '@' || nested == 'B') {
                        state = 2;
                        ptn_string_buffer_append_len(&output, input + i, 4);
                        i += 4;
                        continue;
                    }
                    if (nested == 'D') {
                        state = 3;
                        ptn_string_buffer_append_len(&output, input + i, 4);
                        i += 4;
                        continue;
                    }
                }
            }
            if (illegal_chars != NULL) {
                (*illegal_chars)++;
            }
            ptn_mb_jis_append_replacement_in_ascii(&output, replacement, replacement_len, state);
            if (i + 2 == input_len && (input[i + 1] == '$' || input[i + 1] == '(')) {
                i += 2;
            } else {
                i++;
            }
            continue;
        }
        if (state == 2 || state == 3) {
            if (byte >= 0x21 && byte <= 0x7e) {
                if (i + 1 < input_len) {
                    unsigned char trail = (unsigned char)input[i + 1];
                    if (trail >= 0x21 && trail <= 0x7e) {
                        if (state == 3 && byte == 0x22 && trail == 0x37) {
                            ptn_mb_jis_append_replacement_in_ascii(&output, "~", 1, state);
                            i += 2;
                            continue;
                        }
                        ptn_string_buffer_append_len(&output, input + i, 2);
                        i += 2;
                        continue;
                    }
                    if (illegal_chars != NULL) {
                        (*illegal_chars)++;
                    }
                    ptn_mb_jis_append_replacement_in_ascii(&output, replacement, replacement_len, state);
                    i += 2;
                    continue;
                }
                if (illegal_chars != NULL) {
                    (*illegal_chars)++;
                }
                ptn_mb_jis_append_replacement_in_ascii(&output, replacement, replacement_len, state);
                i++;
                continue;
            }
            if (illegal_chars != NULL) {
                (*illegal_chars)++;
            }
            ptn_mb_jis_append_replacement_in_ascii(&output, replacement, replacement_len, state);
            i++;
            continue;
        }
        if (byte >= 0x80) {
            if (illegal_chars != NULL) {
                (*illegal_chars)++;
            }
            ptn_mb_jis_append_replacement_in_ascii(&output, replacement, replacement_len, state);
            i++;
            continue;
        }
        ptn_string_buffer_append_char(&output, (char)byte);
        i++;
    }
    *output_len = output.len;
    return output.data == NULL ? ptn_duplicate_string_len("", 0) : output.data;
}

static int ptn_mb_jis_utf8_encode_override_at(
    const char *input,
    size_t input_len,
    size_t offset,
    const char **encoded,
    size_t *encoded_len,
    size_t *skip
) {
    if (offset + 2 < input_len &&
        (unsigned char)input[offset] == 0xe2 &&
        (unsigned char)input[offset + 1] == 0x88 &&
        (unsigned char)input[offset + 2] == 0xa5) {
        *encoded = "\x1b$B!B\x1b(B";
        *encoded_len = 8;
        *skip = 3;
        return 1;
    }
    if (offset + 2 < input_len &&
        (unsigned char)input[offset] == 0xef &&
        (unsigned char)input[offset + 1] == 0xbc &&
        (unsigned char)input[offset + 2] == 0x8d) {
        *encoded = "\x1b$B!]\x1b(B";
        *encoded_len = 8;
        *skip = 3;
        return 1;
    }
    if (offset + 2 < input_len &&
        (unsigned char)input[offset] == 0xef &&
        (unsigned char)input[offset + 1] == 0xbf &&
        (unsigned char)input[offset + 2] == 0xa0) {
        *encoded = "\x1b$B!q\x1b(B";
        *encoded_len = 8;
        *skip = 3;
        return 1;
    }
    if (offset + 2 < input_len &&
        (unsigned char)input[offset] == 0xef &&
        (unsigned char)input[offset + 1] == 0xbf &&
        (unsigned char)input[offset + 2] == 0xa1) {
        *encoded = "\x1b$B!r\x1b(B";
        *encoded_len = 8;
        *skip = 3;
        return 1;
    }
    if (offset + 2 < input_len &&
        (unsigned char)input[offset] == 0xef &&
        (unsigned char)input[offset + 1] == 0xbf &&
        (unsigned char)input[offset + 2] == 0xa2) {
        *encoded = "\x1b$B\"L\x1b(B";
        *encoded_len = 8;
        *skip = 3;
        return 1;
    }
    return 0;
}

static void ptn_mb_jis_flush_utf8_chunk(
    PtnStringBuffer *output,
    const char *chunk,
    size_t chunk_len,
    const char *raw_target,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars
) {
    if (chunk_len == 0) {
        return;
    }
    size_t converted_len = 0;
    char *converted = ptn_mb_iconv_convert_alloc_options(
        chunk,
        chunk_len,
        "UTF-8",
        raw_target,
        replacement,
        replacement_len,
        illegal_chars,
        &converted_len
    );
    ptn_string_buffer_append_len(output, converted, converted_len);
    free(converted);
}

static char *ptn_mb_jis_encode_utf8_with_overrides_alloc(
    const char *input,
    size_t input_len,
    const char *raw_target,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars,
    size_t *output_len
) {
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    size_t chunk_start = 0;
    size_t offset = 0;
    while (offset < input_len) {
        const char *encoded = NULL;
        size_t encoded_len = 0;
        size_t skip = 0;
        if (ptn_mb_jis_utf8_encode_override_at(input, input_len, offset, &encoded, &encoded_len, &skip)) {
            ptn_mb_jis_flush_utf8_chunk(
                &output,
                input + chunk_start,
                offset - chunk_start,
                raw_target,
                replacement,
                replacement_len,
                illegal_chars
            );
            ptn_string_buffer_append_len(&output, encoded, encoded_len);
            offset += skip;
            chunk_start = offset;
            continue;
        }
        size_t sequence_len = 0;
        if (ptn_mb_utf8_valid_sequence_len_at(input, input_len, offset, &sequence_len)) {
            offset += sequence_len;
        } else {
            offset++;
        }
    }
    ptn_mb_jis_flush_utf8_chunk(
        &output,
        input + chunk_start,
        input_len - chunk_start,
        raw_target,
        replacement,
        replacement_len,
        illegal_chars
    );
    *output_len = output.len;
    return output.data == NULL ? ptn_duplicate_string_len("", 0) : output.data;
}

static int ptn_mb_jis_validate_bytes(const char *data, size_t len, const char *encoding) {
    int is_jis = ptn_ascii_case_equal(encoding, "JIS");
    int invalid = 0;
    int shift_out = 0;
    size_t i = 0;
    while (i < len) {
        unsigned char byte = (unsigned char)data[i];
        if (byte == 0x0e) {
            if (!is_jis) {
                invalid = 1;
            }
            shift_out = 1;
            i++;
            continue;
        }
        if (byte == 0x0f) {
            if (!is_jis || !shift_out) {
                invalid = 1;
            }
            shift_out = 0;
            i++;
            continue;
        }
        if (shift_out) {
            if (byte < 0x21 || byte > 0x5f) {
                invalid = 1;
            }
            i++;
            continue;
        }
        if (byte >= 0x80) {
            if (!is_jis || byte < 0xa1 || byte > 0xdf) {
                invalid = 1;
            }
            i++;
            continue;
        }
        if (byte != 0x1b) {
            i++;
            continue;
        }
        if (i + 1 >= len) {
            invalid = 1;
            break;
        }
        if (data[i + 1] == '(') {
            if (i + 2 >= len) {
                invalid = 1;
                break;
            }
            unsigned char final = (unsigned char)data[i + 2];
            if (final == 'B' || final == 'J') {
                i += 3;
                continue;
            }
            if (final == 'H' || final == 'I') {
                if (!is_jis) {
                    invalid = 1;
                }
                i += 3;
                continue;
            }
            invalid = 1;
            i++;
            continue;
        }
        if (data[i + 1] == '$') {
            if (i + 2 >= len) {
                invalid = 1;
                break;
            }
            unsigned char final = (unsigned char)data[i + 2];
            if (final == '@' || final == 'B') {
                i += 3;
                continue;
            }
            if (final == '(') {
                if (i + 3 >= len) {
                    invalid = 1;
                    break;
                }
                unsigned char nested = (unsigned char)data[i + 3];
                if (nested == '@' || nested == 'B' || nested == 'D') {
                    if (!is_jis) {
                        invalid = 1;
                    }
                    i += 4;
                    continue;
                }
            }
            invalid = 1;
            i++;
            continue;
        }
        invalid = 1;
        i++;
    }
    if (shift_out) {
        invalid = 1;
    }
    if (invalid) {
        return 0;
    }
    size_t normalized_len = 0;
    char *normalized = ptn_mb_jis_normalize_to_iso2022jp2_alloc(data, len, &normalized_len);
    int valid = ptn_mb_iconv_validate_bytes(normalized, normalized_len, "ISO-2022-JP-2");
    free(normalized);
    return valid;
}

static char *ptn_mb_iso2022jp_postprocess_alloc(char *input, size_t input_len, size_t *output_len) {
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    size_t i = 0;
    while (i < input_len) {
        if (i + 7 <= input_len && memcmp(input + i, "\x1b(J~\x1b(B", 7) == 0) {
            ptn_string_buffer_append_len(&output, "\x1b$B!1\x1b(B", 8);
            i += 7;
            continue;
        }
        ptn_string_buffer_append_char(&output, input[i]);
        i++;
    }
    free(input);
    *output_len = output.len;
    return output.data == NULL ? ptn_duplicate_string_len("", 0) : output.data;
}

static char *ptn_mb_jis_convert_alloc_options(
    const char *input,
    size_t input_len,
    const char *from_encoding,
    const char *to_encoding,
    const char *replacement,
    size_t replacement_len,
    int64_t *illegal_chars,
    size_t *output_len
) {
    char *utf8_replacement = NULL;
    size_t utf8_replacement_len = 0;
    char *utf8 = NULL;
    size_t utf8_len = 0;
    if (ptn_mb_encoding_is_jis_family(from_encoding)) {
        size_t normalized_len = 0;
        char *normalized = ptn_mb_jis_normalize_to_iso2022jp2_alloc(input, input_len, &normalized_len);
        size_t source_replacement_len = 0;
        char *source_replacement = ptn_mb_substitute_bytes_for_encoding_alloc("ISO-2022-JP-2", &source_replacement_len);
        size_t collapsed_len = 0;
        char *collapsed = ptn_mb_jis_collapse_invalid_double_trails_alloc(
            normalized,
            normalized_len,
            source_replacement,
            source_replacement_len,
            illegal_chars,
            &collapsed_len
        );
        utf8_replacement = ptn_mb_substitute_bytes_for_encoding_alloc("UTF-8", &utf8_replacement_len);
        utf8 = ptn_mb_iconv_convert_alloc_options(
            collapsed,
            collapsed_len,
            "ISO-2022-JP-2",
            "UTF-8",
            utf8_replacement,
            utf8_replacement_len,
            illegal_chars,
            &utf8_len
        );
        free(source_replacement);
        free(utf8_replacement);
        free(collapsed);
        free(normalized);
    } else if (ptn_mb_encoding_is_utf8(from_encoding)) {
        utf8_replacement = ptn_mb_substitute_bytes_for_encoding_alloc("UTF-8", &utf8_replacement_len);
        utf8 = ptn_mb_utf8_replace_invalid_alloc(
            input,
            input_len,
            utf8_replacement,
            utf8_replacement_len,
            illegal_chars,
            &utf8_len
        );
        free(utf8_replacement);
    } else {
        utf8_replacement = ptn_mb_substitute_bytes_for_encoding_alloc("UTF-8", &utf8_replacement_len);
        utf8 = ptn_mb_iconv_convert_alloc_options(
            input,
            input_len,
            from_encoding,
            "UTF-8",
            utf8_replacement,
            utf8_replacement_len,
            illegal_chars,
            &utf8_len
        );
        free(utf8_replacement);
    }

    if (ptn_mb_encoding_is_utf8(to_encoding)) {
        *output_len = utf8_len;
        return utf8;
    }
    if (!ptn_mb_encoding_is_jis_family(to_encoding)) {
        char *converted = ptn_mb_iconv_convert_alloc_options(
            utf8,
            utf8_len,
            "UTF-8",
            to_encoding,
            replacement,
            replacement_len,
            illegal_chars,
            output_len
        );
        free(utf8);
        return converted;
    }
    const char *raw_target = ptn_ascii_case_equal(to_encoding, "JIS") ? "ISO-2022-JP-2" : "ISO-2022-JP-MS";
    char *encoded = ptn_mb_jis_encode_utf8_with_overrides_alloc(
        utf8,
        utf8_len,
        raw_target,
        replacement,
        replacement_len,
        illegal_chars,
        output_len
    );
    free(utf8);
    if (ptn_ascii_case_equal(to_encoding, "ISO-2022-JP")) {
        encoded = ptn_mb_iso2022jp_postprocess_alloc(encoded, *output_len, output_len);
    }
    return encoded;
}

static int ptn_mb_utf8_is_valid(const char *data, size_t len) {
    size_t offset = 0;
    while (offset < len) {
        size_t before = offset;
        uint32_t cp = 0;
        ptn_mb_utf8_decode_one(data, len, &offset, &cp);
        if (cp == 0xfffd && offset == before + 1 && (unsigned char)data[before] >= 0x80) {
            return 0;
        }
    }
    return 1;
}

static int ptn_mb_ascii_is_valid(const char *data, size_t len) {
    for (size_t i = 0; i < len; i++) {
        if ((unsigned char)data[i] > 0x7f) {
            return 0;
        }
    }
    return 1;
}

static int ptn_mb_iconv_validate_bytes(const char *data, size_t len, const char *encoding) {
    if (ptn_ascii_case_equal(encoding, "UTF7-IMAP")) {
        return ptn_mb_utf7imap_validate_bytes(data, len);
    }
    if (ptn_mb_encoding_is_utf8_mobile(encoding)) {
        return ptn_mb_utf8_is_valid(data, len);
    }
    if (ptn_mb_encoding_is_jis_family(encoding)) {
        return ptn_mb_jis_validate_bytes(data, len, encoding);
    }
    if (ptn_mb_encoding_is_table(encoding)) {
        if (ptn_mb_encoding_is_cp936_table(encoding)) {
            return ptn_mb_cp936_validate_bytes(data, len);
        }
        if (ptn_mb_encoding_is_single_byte_override_table(encoding)) {
            return ptn_mb_single_byte_override_validate_bytes(data, len, encoding);
        }
        if (ptn_mb_encoding_is_windows1252_table(encoding)) {
            return ptn_mb_windows1252_validate_bytes(data, len);
        }
        if (ptn_mb_encoding_is_windows1254_table(encoding)) {
            return ptn_mb_windows1254_validate_bytes(data, len);
        }
        return ptn_mb_euctw_validate_bytes(data, len);
    }
    const char *iconv_name = ptn_mb_iconv_encoding_name(encoding);
    if (iconv_name == NULL) {
        return 1;
    }
#if defined(_WIN32)
    return 1;
#else
    iconv_t cd = iconv_open("UTF-8", iconv_name);
    if (cd == (iconv_t)-1) {
        return 1;
    }
    char *in_ptr = (char *)data;
    size_t in_left = len;
    char scratch[256];
    while (in_left > 0) {
        char *out_ptr = scratch;
        size_t out_left = sizeof(scratch);
        size_t converted = iconv(cd, &in_ptr, &in_left, &out_ptr, &out_left);
        if (converted != (size_t)-1 || errno == E2BIG) {
            continue;
        }
        iconv_close(cd);
        return 0;
    }
    for (;;) {
        char *out_ptr = scratch;
        size_t out_left = sizeof(scratch);
        size_t converted = iconv(cd, NULL, NULL, &out_ptr, &out_left);
        if (converted != (size_t)-1) {
            iconv_close(cd);
            return 1;
        }
        if (errno != E2BIG) {
            iconv_close(cd);
            return 0;
        }
    }
#endif
}

static int ptn_mb_check_encoding_string_bytes(const char *data, size_t len, const char *encoding) {
    if (ptn_mb_encoding_is_utf8(encoding)) {
        return ptn_mb_utf8_is_valid(data, len);
    }
    if (ptn_mb_encoding_is_jis_family(encoding)) {
        return ptn_mb_jis_validate_bytes(data, len, encoding);
    }
    if (ptn_ascii_case_equal(encoding, "ASCII") || ptn_ascii_case_equal(encoding, "7bit")) {
        return ptn_mb_ascii_is_valid(data, len);
    }
    if (ptn_ascii_case_equal(encoding, "8bit") || ptn_ascii_case_equal(encoding, "pass")) {
        return 1;
    }
    if (ptn_mb_encoding_is_ucs4_family(encoding)) {
        return ptn_mb_ucs4_validate_bytes(data, len, encoding);
    }
    return ptn_mb_iconv_validate_bytes(data, len, encoding);
}

typedef struct {
    PtnArray **items;
    size_t len;
    size_t capacity;
    int saw_circular;
} PtnMbCheckStack;

static void ptn_mb_check_stack_free(PtnMbCheckStack *stack) {
    free(stack->items);
    stack->items = NULL;
    stack->len = 0;
    stack->capacity = 0;
}

static int ptn_mb_check_stack_contains(PtnMbCheckStack *stack, PtnArray *array) {
    for (size_t i = 0; i < stack->len; i++) {
        if (stack->items[i] == array) {
            return 1;
        }
    }
    return 0;
}

static void ptn_mb_check_stack_push(PtnMbCheckStack *stack, PtnArray *array) {
    if (stack->len == stack->capacity) {
        size_t next_capacity = stack->capacity == 0 ? 8 : stack->capacity * 2;
        if (next_capacity < stack->capacity) {
            ptn_abort_out_of_memory();
        }
        PtnArray **grown = realloc(stack->items, next_capacity * sizeof(PtnArray *));
        if (grown == NULL) {
            ptn_abort_out_of_memory();
        }
        stack->items = grown;
        stack->capacity = next_capacity;
    }
    stack->items[stack->len++] = array;
}

static int ptn_mb_check_encoding_value(PtnValue value, const char *encoding, PtnMbCheckStack *stack) {
    PtnValue resolved = ptn_value_deref(value);
    if (resolved.type == PTN_STRING) {
        return ptn_mb_check_encoding_string_bytes((const char *)resolved.as.string.data, resolved.as.string.len, encoding);
    }
    if (resolved.type != PTN_ARRAY) {
        return 1;
    }
    PtnArray *array = resolved.as.array;
    if (ptn_mb_check_stack_contains(stack, array)) {
        stack->saw_circular = 1;
        return 0;
    }
    ptn_mb_check_stack_push(stack, array);
    for (size_t i = 0; i < array->len; i++) {
        PtnArrayEntry *entry = &array->entries[i];
        if (entry->key.type == PTN_ARRAY_KEY_STRING &&
            !ptn_mb_check_encoding_string_bytes(entry->key.as.string, entry->key.string_len, encoding)) {
            stack->len--;
            return 0;
        }
        if (!ptn_mb_check_encoding_value(entry->value, encoding, stack)) {
            stack->len--;
            return 0;
        }
    }
    stack->len--;
    return 1;
}

static int ptn_mb_value_has_recursive_array(PtnValue value, PtnMbCheckStack *stack) {
    PtnValue resolved = ptn_value_deref(value);
    if (resolved.type != PTN_ARRAY) {
        return 0;
    }
    PtnArray *array = resolved.as.array;
    if (ptn_mb_check_stack_contains(stack, array)) {
        stack->saw_circular = 1;
        return 1;
    }
    ptn_mb_check_stack_push(stack, array);
    for (size_t i = 0; i < array->len; i++) {
        if (ptn_mb_value_has_recursive_array(array->entries[i].value, stack)) {
            stack->len--;
            return 1;
        }
    }
    stack->len--;
    return 0;
}

static size_t ptn_mb_utf8_strlen(const char *data, size_t len) {
    size_t offset = 0;
    size_t count = 0;
    while (offset < len) {
        uint32_t cp = 0;
        if (!ptn_mb_utf8_decode_one(data, len, &offset, &cp)) {
            break;
        }
        count++;
    }
    return count;
}

static size_t ptn_mb_utf8_byte_offset_for_char(const char *data, size_t len, size_t char_index) {
    size_t offset = 0;
    size_t index = 0;
    while (offset < len && index < char_index) {
        uint32_t cp = 0;
        ptn_mb_utf8_decode_one(data, len, &offset, &cp);
        index++;
    }
    return offset;
}

static size_t ptn_mb_utf8_char_index_for_byte(const char *data, size_t len, size_t byte_offset) {
    size_t offset = 0;
    size_t index = 0;
    while (offset < len && offset < byte_offset) {
        uint32_t cp = 0;
        ptn_mb_utf8_decode_one(data, len, &offset, &cp);
        index++;
    }
    return index;
}

static size_t ptn_mb_utf8_split_next_span(const char *data, size_t len, size_t offset) {
    if (offset >= len) {
        return 0;
    }
    unsigned char b0 = (unsigned char)data[offset];
    if (b0 < 0x80) {
        return 1;
    }
    size_t need = 0;
    uint32_t cp = 0;
    uint32_t min = 0;
    if ((b0 & 0xe0) == 0xc0) {
        need = 2;
        cp = b0 & 0x1f;
        min = 0x80;
    } else if ((b0 & 0xf0) == 0xe0) {
        need = 3;
        cp = b0 & 0x0f;
        min = 0x800;
    } else if ((b0 & 0xf8) == 0xf0) {
        need = 4;
        cp = b0 & 0x07;
        min = 0x10000;
    } else {
        return 1;
    }
    if (offset + need > len) {
        return len - offset;
    }
    for (size_t i = 1; i < need; i++) {
        unsigned char bx = (unsigned char)data[offset + i];
        if ((bx & 0xc0) != 0x80) {
            return 1;
        }
        cp = (cp << 6) | (uint32_t)(bx & 0x3f);
    }
    if (cp < min || cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) {
        return 1;
    }
    return need;
}

static size_t ptn_mb_utf8_split_strlen(const char *data, size_t len) {
    size_t offset = 0;
    size_t count = 0;
    while (offset < len) {
        size_t span = ptn_mb_utf8_split_next_span(data, len, offset);
        if (span == 0) {
            break;
        }
        offset += span;
        count++;
    }
    return count;
}

static size_t ptn_mb_utf8_split_byte_offset_for_char(const char *data, size_t len, size_t char_index) {
    size_t offset = 0;
    size_t index = 0;
    while (offset < len && index < char_index) {
        size_t span = ptn_mb_utf8_split_next_span(data, len, offset);
        if (span == 0) {
            break;
        }
        offset += span;
        index++;
    }
    return offset;
}

static void ptn_mb_utf8_append_codepoint(PtnStringBuffer *buffer, uint32_t cp) {
    if (cp <= 0x7f) {
        ptn_string_buffer_append_char(buffer, (char)cp);
    } else if (cp <= 0x7ff) {
        ptn_string_buffer_append_char(buffer, (char)(0xc0 | (cp >> 6)));
        ptn_string_buffer_append_char(buffer, (char)(0x80 | (cp & 0x3f)));
    } else if (cp <= 0xffff) {
        ptn_string_buffer_append_char(buffer, (char)(0xe0 | (cp >> 12)));
        ptn_string_buffer_append_char(buffer, (char)(0x80 | ((cp >> 6) & 0x3f)));
        ptn_string_buffer_append_char(buffer, (char)(0x80 | (cp & 0x3f)));
    } else {
        ptn_string_buffer_append_char(buffer, (char)(0xf0 | (cp >> 18)));
        ptn_string_buffer_append_char(buffer, (char)(0x80 | ((cp >> 12) & 0x3f)));
        ptn_string_buffer_append_char(buffer, (char)(0x80 | ((cp >> 6) & 0x3f)));
        ptn_string_buffer_append_char(buffer, (char)(0x80 | (cp & 0x3f)));
    }
}

static int ptn_mb_jis_no_escape_fast_path_safe(PtnStringOperand input) {
    int kana_mode = 0;
    for (size_t i = 0; i < input.len; i++) {
        unsigned char byte = (unsigned char)input.data[i];
        if (byte == 0x0e) {
            kana_mode = 1;
            continue;
        }
        if (byte == 0x0f) {
            kana_mode = 0;
            continue;
        }
        if (kana_mode) {
            if (byte < 0x21 || byte > 0x5f) {
                return 0;
            }
            continue;
        }
        if (byte < 0x80 || (byte >= 0xa1 && byte <= 0xdf)) {
            continue;
        }
        return 0;
    }
    return !kana_mode;
}

static char *ptn_mb_operand_to_utf8(PtnStringOperand input, const char *encoding, size_t *utf8_len) {
    if (ptn_mb_encoding_is_utf8(encoding) || ptn_mb_encoding_is_raw(encoding) || ptn_ascii_case_equal(encoding, "ASCII")) {
        *utf8_len = input.len;
        return ptn_duplicate_string_len(input.data, input.len);
    }
    if (ptn_ascii_case_equal(encoding, "HZ")) {
        return ptn_mb_hz_to_utf8_alloc(input.data, input.len, utf8_len);
    }
    if (ptn_ascii_case_equal(encoding, "JIS") &&
        memchr(input.data, 0x1b, input.len) == NULL &&
        ptn_mb_jis_no_escape_fast_path_safe(input)) {
        PtnStringBuffer output;
        ptn_string_buffer_init(&output);
        int kana_mode = 0;
        for (size_t i = 0; i < input.len; i++) {
            unsigned char byte = (unsigned char)input.data[i];
            if (byte == 0x0e) {
                kana_mode = 1;
                continue;
            }
            if (byte == 0x0f) {
                kana_mode = 0;
                continue;
            }
            if ((kana_mode && byte >= 0x21 && byte <= 0x5f) || (byte >= 0xa1 && byte <= 0xdf)) {
                uint32_t cp = 0xff61u + (uint32_t)(byte >= 0xa1 ? byte - 0xa1 : byte - 0x21);
                ptn_mb_utf8_append_codepoint(&output, cp);
                continue;
            }
            ptn_string_buffer_append_char(&output, (char)byte);
        }
        *utf8_len = output.len;
        return output.data == NULL ? ptn_duplicate_string_len("", 0) : output.data;
    }
    return ptn_mb_iconv_convert_alloc(input.data, input.len, encoding, "UTF-8", utf8_len);
}

static char *ptn_mb_utf8_to_encoding(const char *input, size_t input_len, const char *encoding, size_t *output_len) {
    if (ptn_mb_encoding_is_utf8(encoding) || ptn_mb_encoding_is_raw(encoding) || ptn_ascii_case_equal(encoding, "ASCII")) {
        *output_len = input_len;
        return ptn_duplicate_string_len(input, input_len);
    }
    return ptn_mb_iconv_convert_alloc(input, input_len, "UTF-8", encoding, output_len);
}

static PtnValue ptn_mb_string_from_utf8(char *utf8, size_t utf8_len, const char *encoding) {
    size_t output_len = 0;
    char *output = ptn_mb_utf8_to_encoding(utf8, utf8_len, encoding, &output_len);
    free(utf8);
    return ptn_owned_string_len(output, output_len);
}

static uint32_t ptn_mb_case_map_codepoint(uint32_t cp, int uppercase) {
    if (uppercase) {
        if (cp >= 'a' && cp <= 'z') {
            return cp - 32;
        }
        if ((cp >= 0x00e0 && cp <= 0x00f6) || (cp >= 0x00f8 && cp <= 0x00fe)) {
            return cp - 32;
        }
        if (cp >= 0x03b1 && cp <= 0x03c1) {
            return cp - 32;
        }
        if (cp >= 0x03c3 && cp <= 0x03cb) {
            return cp - 32;
        }
        if (cp >= 0x0430 && cp <= 0x044f) {
            return cp - 32;
        }
        if (cp >= 0x0501 && cp <= 0x052f && (cp & 1u)) {
            return cp - 1;
        }
        if (cp >= 0x2c30 && cp <= 0x2c5e) {
            return cp - 0x30;
        }
        if (cp >= 0x10428 && cp <= 0x1044f) {
            return cp - 0x28;
        }
        if (cp >= 0xff41 && cp <= 0xff5a) {
            return cp - 32;
        }
        if (cp >= 0x10428 && cp <= 0x1044f) {
            return cp - 0x28;
        }
        if (cp >= 0x2c30 && cp <= 0x2c5f) {
            return cp - 0x30;
        }
        if (cp >= 0x0501 && cp <= 0x052f && (cp & 1u) == 1u) {
            return cp - 1;
        }
    } else {
        if (cp >= 'A' && cp <= 'Z') {
            return cp + 32;
        }
        if (cp == 0x012c) {
            return 0x012d;
        }
        if ((cp >= 0x00c0 && cp <= 0x00d6) || (cp >= 0x00d8 && cp <= 0x00de)) {
            return cp + 32;
        }
        if (cp >= 0x0391 && cp <= 0x03a1) {
            return cp + 32;
        }
        if (cp >= 0x03a3 && cp <= 0x03ab) {
            return cp + 32;
        }
        if (cp >= 0x0410 && cp <= 0x042f) {
            return cp + 32;
        }
        if (cp >= 0x0500 && cp <= 0x052e && !(cp & 1u)) {
            return cp + 1;
        }
        if (cp >= 0x2c00 && cp <= 0x2c2e) {
            return cp + 0x30;
        }
        if (cp >= 0x10400 && cp <= 0x10427) {
            return cp + 0x28;
        }
        if (cp >= 0xff21 && cp <= 0xff3a) {
            return cp + 32;
        }
        if (cp >= 0x10400 && cp <= 0x10427) {
            return cp + 0x28;
        }
        if (cp >= 0x2c00 && cp <= 0x2c2f) {
            return cp + 0x30;
        }
        if (cp >= 0x0500 && cp <= 0x052e && (cp & 1u) == 0u) {
            return cp + 1;
        }
    }
    return cp;
}

static int ptn_mb_codepoint_is_case_ignorable(uint32_t cp) {
    return cp == '\'' ||
        cp == '.' ||
        cp == ':' ||
        cp == 0x00ad ||
        cp == 0x02bc ||
        cp == 0x2019;
}

static int ptn_mb_codepoint_is_cased(uint32_t cp) {
    return (cp >= 'A' && cp <= 'Z') ||
        (cp >= 'a' && cp <= 'z') ||
        cp == 0x00df ||
        cp == 0x0149 ||
        (cp >= 0x00c0 && cp <= 0x00d6) ||
        (cp >= 0x00d8 && cp <= 0x00f6) ||
        (cp >= 0x00f8 && cp <= 0x00ff) ||
        (cp >= 0x0100 && cp <= 0x017f) ||
        (cp >= 0x0391 && cp <= 0x03a1) ||
        (cp >= 0x03a3 && cp <= 0x03cb) ||
        (cp >= 0x03b1 && cp <= 0x03c1) ||
        cp == 0x03c2 ||
        (cp >= 0x0410 && cp <= 0x044f) ||
        (cp >= 0x0500 && cp <= 0x052f) ||
        (cp >= 0x2c00 && cp <= 0x2c5e) ||
        (cp >= 0x10400 && cp <= 0x1044f) ||
        (cp >= 0xff21 && cp <= 0xff3a) ||
        (cp >= 0xff41 && cp <= 0xff5a);
}

static int ptn_mb_has_cased_codepoint_after_ignorable(
    const char *input,
    size_t input_len,
    size_t offset
) {
    while (offset < input_len) {
        uint32_t cp = 0;
        if (!ptn_mb_utf8_decode_one(input, input_len, &offset, &cp)) {
            return 0;
        }
        if (ptn_mb_codepoint_is_case_ignorable(cp)) {
            continue;
        }
        return ptn_mb_codepoint_is_cased(cp);
    }
    return 0;
}

static int ptn_mb_title_is_word_codepoint(uint32_t cp) {
    if (cp <= 0x7f) {
        return isalnum((unsigned char)cp) != 0;
    }
    if (cp == 0x00a0 || cp == 0x1680 || cp == 0x2028 || cp == 0x2029 ||
        cp == 0x202f || cp == 0x205f || cp == 0x3000) {
        return 0;
    }
    if (cp >= 0x2000 && cp <= 0x200a) {
        return 0;
    }
    if (cp == 0x2018 || cp == 0x2019 || cp == 0x201c || cp == 0x201d) {
        return 0;
    }
    return 1;
}

static char *ptn_mb_utf8_case_alloc(const char *input, size_t input_len, int mode, size_t *output_len) {
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    size_t offset = 0;
    int title_next = 1;
    int title_in_word = 0;
    int previous_cased = 0;
    size_t ignorable_since_cased = 0;
    while (offset < input_len) {
        uint32_t cp = 0;
        ptn_mb_utf8_decode_one(input, input_len, &offset, &cp);
        uint32_t original_cp = cp;
        int final_sigma_context =
            (cp == 0x03a3 || cp == 0x03c3) &&
            previous_cased &&
            ignorable_since_cased <= 63 &&
            !ptn_mb_has_cased_codepoint_after_ignorable(input, input_len, offset);
        if (mode == PTN_MB_CASE_UPPER || mode == PTN_MB_CASE_UPPER_SIMPLE) {
            if (mode == PTN_MB_CASE_UPPER && cp == 0x00df) {
                ptn_string_buffer_append(&output, "SS");
                goto update_case_state;
            }
            cp = ptn_mb_case_map_codepoint(cp, 1);
        } else if (mode == PTN_MB_CASE_FOLD || mode == PTN_MB_CASE_FOLD_SIMPLE) {
            if (mode == PTN_MB_CASE_FOLD && cp == 0x00df) {
                ptn_string_buffer_append(&output, "ss");
                goto update_case_state;
            }
            cp = final_sigma_context ? 0x03c2 : ptn_mb_case_map_codepoint(cp, 0);
        } else if (mode == PTN_MB_CASE_TITLE || mode == PTN_MB_CASE_TITLE_SIMPLE) {
            if (mode == PTN_MB_CASE_TITLE && title_next && cp == 0x0149) {
                ptn_mb_utf8_append_codepoint(&output, 0x02bc);
                ptn_mb_utf8_append_codepoint(&output, 'N');
                goto update_case_state;
            } else if (title_next) {
                cp = ptn_mb_case_map_codepoint(cp, 1);
            } else {
                cp = final_sigma_context ? 0x03c2 : ptn_mb_case_map_codepoint(cp, 0);
            }
            if ((cp == '\'' || cp == 0x2019) && title_in_word) {
                title_next = 0;
            } else if (ptn_mb_title_is_word_codepoint(cp)) {
                title_next = 0;
                title_in_word = 1;
            } else {
                title_next = 1;
                title_in_word = 0;
            }
        } else {
            cp = final_sigma_context ? 0x03c2 : ptn_mb_case_map_codepoint(cp, 0);
        }
        ptn_mb_utf8_append_codepoint(&output, cp);
update_case_state:
        if (ptn_mb_codepoint_is_cased(original_cp)) {
            title_next = 0;
            previous_cased = 1;
            ignorable_since_cased = 0;
        } else if (ptn_mb_codepoint_is_case_ignorable(original_cp)) {
            if (previous_cased) {
                ignorable_since_cased++;
            }
        } else {
            title_next = 1;
            previous_cased = 0;
            ignorable_since_cased = 0;
        }
    }
    *output_len = output.len;
    return output.data;
}

static void ptn_mb_array_append_string(PtnValue array, int64_t *index, const char *value) {
    ptn_array_set_entry(array.as.array, ptn_array_int_key((*index)++), ptn_string(value));
}

static PtnValue ptn_mb_encoding_list_value(void) {
    static const char *const names[] = {
        "pass", "auto", "wchar", "byte2be", "byte2le", "byte4be", "byte4le",
        "BASE64", "UUENCODE", "HTML-ENTITIES", "Quoted-Printable", "7bit", "8bit",
        "UCS-4", "UCS-4BE", "UCS-4LE", "UCS-2", "UCS-2BE", "UCS-2LE",
        "UTF-32", "UTF-32BE", "UTF-32LE", "UTF-16", "UTF-16BE", "UTF-16LE",
        "UTF-8", "UTF-7", "ASCII", "EUC-JP", "SJIS", "eucJP-win",
        "EUC-JP-2004", "SJIS-Mobile#DOCOMO", "SJIS-Mobile#KDDI",
        "SJIS-Mobile#SOFTBANK", "SJIS-mac", "SJIS-2004", "CP932",
        "SJIS-win", "CP51932", "ISO-2022-JP",
        "ISO-8859-1", "ISO-8859-15", "Windows-1251", "Windows-1252",
        "Windows-1254", "ISO-8859-2", "ISO-8859-3", "ISO-8859-4",
        "ISO-8859-5", "ISO-8859-6", "ISO-8859-7", "ISO-8859-8",
        "ISO-8859-9", "ISO-8859-10", "ISO-8859-13", "ISO-8859-14",
        "ISO-8859-16", "KOI8-R", "KOI8-U", "BIG-5", "CP950", "EUC-KR",
        "UHC", "GB18030", "GB2312", "EUC-CN", "CP936", "EUC-TW", "CP866",
        "ArmSCII-8", "ISO-2022-JP-MS", "ISO-2022-JP-2004",
        "ISO-2022-JP-MOBILE#KDDI", "CP50220", "CP50221", "CP50222"
    };
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    for (size_t i = 0; i < sizeof(names) / sizeof(names[0]); i++) {
        ptn_array_set_entry(result.as.array, ptn_array_int_key((int64_t)i), ptn_string(names[i]));
    }
    return result;
}

static PtnValue ptn_internal_mb_list_encodings(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)argc;
    (void)args;
    (void)line;
    return ptn_mb_encoding_list_value();
}

static PtnValue ptn_internal_mb_encoding_aliases(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)line;
    const char *encoding = ptn_mb_encoding_from_value(runtime, "mb_encoding_aliases", 1, "encoding", args[0], line, NULL, 0);
    if (encoding == NULL) {
        return ptn_null();
    }
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    int64_t index = 0;
    if (ptn_ascii_case_equal(encoding, "UTF-8")) {
        ptn_mb_array_append_string(result, &index, "utf8");
    } else if (ptn_ascii_case_equal(encoding, "ASCII")) {
        ptn_mb_array_append_string(result, &index, "ANSI_X3.4-1968");
        ptn_mb_array_append_string(result, &index, "ANSI_X3.4-1986");
        ptn_mb_array_append_string(result, &index, "IBM-367");
        ptn_mb_array_append_string(result, &index, "IBM367");
        ptn_mb_array_append_string(result, &index, "ISO646-US");
        ptn_mb_array_append_string(result, &index, "ISO_646.irv:1991");
        ptn_mb_array_append_string(result, &index, "US-ASCII");
        ptn_mb_array_append_string(result, &index, "cp367");
        ptn_mb_array_append_string(result, &index, "csASCII");
        ptn_mb_array_append_string(result, &index, "iso-ir-6");
        ptn_mb_array_append_string(result, &index, "us");
    } else if (ptn_ascii_case_equal(encoding, "8bit")) {
        ptn_mb_array_append_string(result, &index, "binary");
    } else if (ptn_ascii_case_equal(encoding, "SJIS")) {
        ptn_mb_array_append_string(result, &index, "Shift_JIS");
        ptn_mb_array_append_string(result, &index, "CP932");
        ptn_mb_array_append_string(result, &index, "MS_Kanji");
    } else if (ptn_ascii_case_equal(encoding, "EUC-JP")) {
        ptn_mb_array_append_string(result, &index, "eucJP-win");
    } else if (ptn_ascii_case_equal(encoding, "ISO-2022-JP")) {
        ptn_mb_array_append_string(result, &index, "JIS");
    } else if (ptn_ascii_case_equal(encoding, "Quoted-Printable")) {
        ptn_mb_array_append_string(result, &index, "QPrint");
    }
    return result;
}

static PtnValue ptn_internal_mb_preferred_mime_name(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    const char *encoding = ptn_mb_encoding_from_value(runtime, "mb_preferred_mime_name", 1, "encoding", args[0], line, NULL, 0);
    if (encoding == NULL) {
        return ptn_null();
    }
    if (ptn_ascii_case_equal(encoding, "SJIS") ||
        ptn_ascii_case_equal(encoding, "SJIS-win") ||
        ptn_ascii_case_equal(encoding, "SJIS-2004") ||
        ptn_ascii_case_equal(encoding, "MacJapanese")) {
        return ptn_string("Shift_JIS");
    }
    if (ptn_ascii_case_equal(encoding, "eucJP-win") || ptn_ascii_case_equal(encoding, "EUC-JP-2004")) {
        return ptn_string("EUC-JP");
    }
    if (ptn_ascii_case_equal(encoding, "JIS") ||
        ptn_ascii_case_equal(encoding, "ISO-2022-JP-MS") ||
        ptn_ascii_case_equal(encoding, "ISO-2022-JP-2004") ||
        ptn_ascii_case_equal(encoding, "ISO-2022-JP-KDDI") ||
        ptn_ascii_case_equal(encoding, "CP50220") ||
        ptn_ascii_case_equal(encoding, "CP50221") ||
        ptn_ascii_case_equal(encoding, "CP50222")) {
        return ptn_string("ISO-2022-JP");
    }
    return ptn_string(encoding);
}

static PtnValue ptn_internal_mb_internal_encoding(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    if (argc == 0) {
        return ptn_owned_string(ptn_duplicate_string(ptn_mb_current_internal_encoding(runtime)));
    }
    const char *encoding = ptn_mb_encoding_from_value(runtime, "mb_internal_encoding", 1, "encoding", args[0], line, NULL, 0);
    if (encoding == NULL) {
        return ptn_bool(0);
    }
    ptn_mb_copy_state_string(ptn_mb_internal_encoding_name, sizeof(ptn_mb_internal_encoding_name), encoding);
    ptn_mb_internal_encoding_overridden = 1;
    return ptn_bool(1);
}

static PtnValue ptn_internal_mb_regex_encoding(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    ptn_mb_emit_regex_deprecation(runtime, "mb_regex_encoding", line);
    if (argc == 0) {
        return ptn_owned_string(ptn_duplicate_string(ptn_mb_current_regex_encoding(runtime)));
    }
    const char *encoding = ptn_mb_encoding_from_value(runtime, "mb_regex_encoding", 1, "encoding", args[0], line, NULL, 0);
    if (encoding == NULL) {
        return ptn_bool(0);
    }
    ptn_mb_copy_state_string(ptn_mb_regex_encoding_name, sizeof(ptn_mb_regex_encoding_name), encoding);
    return ptn_bool(1);
}

static PtnValue ptn_internal_mb_http_output(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    if (argc == 0) {
        return ptn_owned_string(ptn_duplicate_string(ptn_mb_current_http_output(runtime)));
    }
    const char *encoding = ptn_mb_encoding_from_value(runtime, "mb_http_output", 1, "encoding", args[0], line, NULL, 0);
    if (encoding == NULL) {
        return ptn_bool(0);
    }
    ptn_mb_copy_state_string(ptn_mb_http_output_name, sizeof(ptn_mb_http_output_name), encoding);
    return ptn_bool(1);
}

static PtnValue ptn_internal_mb_http_input(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    const char *input_encoding = ptn_mb_current_http_input(runtime);
    if (argc == 0) {
        return input_encoding == NULL ? ptn_bool(0) : ptn_owned_string(ptn_duplicate_string(input_encoding));
    }
    PtnStringOperand type = ptn_internal_expect_string_arg(runtime, "mb_http_input", 1, "type", args[0], line);
    if (type.len != 1) {
        ptn_string_operand_free(type);
        ptn_throw_exception(runtime, "ValueError", "mb_http_input(): Argument #1 ($type) must be one of \"G\", \"P\", \"C\", \"S\", \"I\", or \"L\"");
        return ptn_null();
    }
    unsigned char selector = (unsigned char)toupper((unsigned char)type.data[0]);
    ptn_string_operand_free(type);
    if (selector != 'G' && selector != 'P' && selector != 'C' && selector != 'S' && selector != 'I' && selector != 'L') {
        ptn_throw_exception(runtime, "ValueError", "mb_http_input(): Argument #1 ($type) must be one of \"G\", \"P\", \"C\", \"S\", \"I\", or \"L\"");
        return ptn_null();
    }
    if (input_encoding == NULL || selector == 'C' || selector == 'S') {
        return ptn_bool(0);
    }
    if (selector == 'I') {
        PtnValue result = ptn_array_from_literal_entries(0, NULL);
        ptn_array_set_entry(result.as.array, ptn_array_int_key(0), ptn_owned_string(ptn_duplicate_string(input_encoding)));
        return result;
    }
    return ptn_owned_string(ptn_duplicate_string(input_encoding));
}

static PtnValue ptn_internal_mb_language(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)line;
    if (argc == 0) {
        return ptn_owned_string(ptn_duplicate_string(ptn_mb_current_language()));
    }
    PtnStringOperand language = ptn_value_to_string_operand(args[0]);
    char *copy = ptn_duplicate_string_len(language.data, language.len);
    ptn_string_operand_free(language);
    ptn_mb_copy_state_string(ptn_mb_language_name, sizeof(ptn_mb_language_name), copy);
    free(copy);
    return ptn_bool(1);
}

static PtnValue ptn_internal_mb_substitute_character(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)line;
    if (argc == 0) {
        const char *value = ptn_mb_current_substitute_character();
        char *end = NULL;
        long parsed = strtol(value, &end, 10);
        if (end != value && end != NULL && *end == '\0') {
            return ptn_int(parsed);
        }
        return ptn_owned_string(ptn_duplicate_string(value));
    }
    PtnStringOperand value = ptn_value_to_string_operand(args[0]);
    char *copy = ptn_duplicate_string_len(value.data, value.len);
    ptn_string_operand_free(value);
    char *end = NULL;
    long parsed = strtol(copy, &end, 10);
    if (end != copy && end != NULL && *end == '\0' && parsed >= 0 && parsed <= 0x10ffff &&
        !(parsed >= 0xd800 && parsed <= 0xdfff)) {
        ptn_mb_substitute_character_codepoint = (uint32_t)parsed;
        ptn_mb_copy_state_string(ptn_mb_substitute_character_name, sizeof(ptn_mb_substitute_character_name), copy);
        free(copy);
        return ptn_bool(1);
    }
    if (ptn_ascii_case_equal(copy, "none")) {
        ptn_mb_copy_state_string(ptn_mb_substitute_character_name, sizeof(ptn_mb_substitute_character_name), "none");
        free(copy);
        return ptn_bool(1);
    }
    if (ptn_ascii_case_equal(copy, "long")) {
        ptn_mb_copy_state_string(ptn_mb_substitute_character_name, sizeof(ptn_mb_substitute_character_name), "long");
        free(copy);
        return ptn_bool(1);
    }
    if (ptn_ascii_case_equal(copy, "entity")) {
        ptn_mb_copy_state_string(ptn_mb_substitute_character_name, sizeof(ptn_mb_substitute_character_name), "entity");
        free(copy);
        return ptn_bool(1);
    }
    free(copy);
    ptn_throw_exception(
        runtime,
        "ValueError",
        "mb_substitute_character(): Argument #1 ($substitute_character) must be \"none\", \"long\", \"entity\" or a valid codepoint"
    );
    return ptn_null();
}

static PtnValue ptn_internal_mb_substitute_char(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_mb_substitute_character(runtime, argc, args, line);
}

static PtnValue ptn_internal_mb_detect_order(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    if (argc == 0) {
        PtnValue result = ptn_array_from_literal_entries(0, NULL);
        const char *order = ptn_mb_current_detect_order();
        size_t start = 0;
        int64_t index = 0;
        size_t len = strlen(order);
        while (start <= len) {
            size_t end = start;
            while (end < len && order[end] != ',') {
                end++;
            }
            while (start < end && isspace((unsigned char)order[start])) {
                start++;
            }
            while (end > start && isspace((unsigned char)order[end - 1])) {
                end--;
            }
            if (end > start) {
                char *item = ptn_duplicate_string_len(order + start, end - start);
                ptn_array_set_entry(result.as.array, ptn_array_int_key(index++), ptn_owned_string_len(item, end - start));
            }
            if (end >= len) {
                break;
            }
            start = end + 1;
        }
        return result;
    }
    PtnStringBuffer buffer;
    ptn_string_buffer_init(&buffer);
    if (!ptn_mb_detect_order_buffer_from_value(runtime, args[0], &buffer, line)) {
        free(buffer.data);
        return ptn_null();
    }
    ptn_mb_copy_state_string(ptn_mb_detect_order_name, sizeof(ptn_mb_detect_order_name), buffer.data);
    free(buffer.data);
    return ptn_bool(1);
}

static PtnValue ptn_mb_base64_encode_wrapped(PtnRuntime *runtime, PtnStringOperand input, size_t line) {
    PtnValue temp = ptn_owned_string_len(ptn_duplicate_string_len(input.data, input.len), input.len);
    PtnValue encoded = ptn_internal_base64_encode(runtime, 1, &temp, line);
    ptn_value_destroy(&temp);
    PtnStringOperand encoded_operand = ptn_value_to_string_operand(encoded);
    size_t breaks = encoded_operand.len == 0 ? 0 : (encoded_operand.len - 1) / 76;
    if (breaks > (SIZE_MAX - encoded_operand.len) / 2) {
        ptn_abort_out_of_memory();
    }
    size_t output_len = encoded_operand.len + breaks * 2;
    char *output = malloc(output_len + 1);
    if (output == NULL) {
        ptn_abort_out_of_memory();
    }
    size_t out = 0;
    for (size_t i = 0; i < encoded_operand.len; i += 76) {
        size_t chunk = encoded_operand.len - i > 76 ? 76 : encoded_operand.len - i;
        memcpy(output + out, encoded_operand.data + i, chunk);
        out += chunk;
        if (i + chunk < encoded_operand.len) {
            output[out++] = '\r';
            output[out++] = '\n';
        }
    }
    output[out] = '\0';
    ptn_string_operand_free(encoded_operand);
    ptn_value_destroy(&encoded);
    return ptn_owned_string_len(output, out);
}

static PtnValue ptn_mb_base64_or_qp_convert(
    PtnRuntime *runtime,
    const char *function_name,
    PtnStringOperand input,
    const char *encoding,
    size_t line
) {
    PtnValue result;
    if (ptn_ascii_case_equal(encoding, "BASE64")) {
        ptn_emit_deprecation(&runtime->diagnostics, "mb_convert_encoding(): Handling Base64 via mbstring is deprecated; use base64_encode/base64_decode instead", line);
        result = ptn_mb_base64_encode_wrapped(runtime, input, line);
    } else {
        PtnValue temp = ptn_owned_string_len(ptn_duplicate_string_len(input.data, input.len), input.len);
        ptn_emit_deprecation(&runtime->diagnostics, "mb_convert_encoding(): Handling QPrint via mbstring is deprecated; use quoted_printable_encode/quoted_printable_decode instead", line);
        result = ptn_internal_quoted_printable_encode(runtime, 1, &temp, line);
        ptn_value_destroy(&temp);
    }
    (void)function_name;
    return result;
}

static PtnValue ptn_mb_convert_string_operand(
    PtnRuntime *runtime,
    PtnStringOperand input,
    const char *to_encoding,
    const char *from_encoding,
    size_t line
) {
    if (ptn_ascii_case_equal(to_encoding, "BASE64") || ptn_ascii_case_equal(to_encoding, "Quoted-Printable")) {
        return ptn_mb_base64_or_qp_convert(runtime, "mb_convert_encoding", input, to_encoding, line);
    }
    if (ptn_ascii_case_equal(from_encoding, "BASE64")) {
        PtnValue temp = ptn_owned_string_len(ptn_duplicate_string_len(input.data, input.len), input.len);
        PtnValue decoded = ptn_internal_base64_decode(runtime, 1, &temp, line);
        ptn_value_destroy(&temp);
        if (ptn_value_deref(decoded).type == PTN_STRING) {
            PtnStringOperand decoded_operand = ptn_value_to_string_operand(decoded);
            size_t out_len = 0;
            char *out = ptn_mb_iconv_convert_alloc_counting(decoded_operand.data, decoded_operand.len, "UTF-8", to_encoding, &out_len);
            ptn_string_operand_free(decoded_operand);
            ptn_value_destroy(&decoded);
            return ptn_owned_string_len(out, out_len);
        }
        return decoded;
    }
    if (ptn_ascii_case_equal(from_encoding, "Quoted-Printable")) {
        ptn_emit_deprecation(&runtime->diagnostics, "mb_convert_encoding(): Handling QPrint via mbstring is deprecated; use quoted_printable_encode/quoted_printable_decode instead", line);
        size_t decoded_len = 0;
        char *decoded = ptn_quoted_printable_decode_string(input.data, input.len, &decoded_len);
        size_t out_len = 0;
        char *out = ptn_mb_iconv_convert_alloc_counting(decoded, decoded_len, "UTF-8", to_encoding, &out_len);
        free(decoded);
        return ptn_owned_string_len(out, out_len);
    }
    if (ptn_ascii_case_equal(to_encoding, "HTML-ENTITIES") || ptn_ascii_case_equal(from_encoding, "HTML-ENTITIES")) {
        ptn_emit_deprecation(&runtime->diagnostics, "mb_convert_encoding(): Handling HTML entities via mbstring is deprecated; use htmlspecialchars, htmlentities, or mb_encode_numericentity/mb_decode_numericentity instead", line);
    }
    if (ptn_ascii_case_equal(from_encoding, "HZ")) {
        size_t utf8_len = 0;
        char *utf8 = ptn_mb_hz_to_utf8_alloc(input.data, input.len, &utf8_len);
        if (ptn_mb_encoding_is_utf8(to_encoding)) {
            return ptn_owned_string_len(utf8, utf8_len);
        }
        size_t out_len = 0;
        char *out = ptn_mb_iconv_convert_alloc_counting(utf8, utf8_len, "UTF-8", to_encoding, &out_len);
        free(utf8);
        return ptn_owned_string_len(out, out_len);
    }
    if (ptn_ascii_case_equal(from_encoding, "JIS") &&
        memchr(input.data, 0x1b, input.len) == NULL &&
        ptn_mb_jis_no_escape_fast_path_safe(input)) {
        size_t utf8_len = 0;
        char *utf8 = ptn_mb_operand_to_utf8(input, from_encoding, &utf8_len);
        if (ptn_mb_encoding_is_utf8(to_encoding)) {
            return ptn_owned_string_len(utf8, utf8_len);
        }
        size_t out_len = 0;
        char *out = ptn_mb_iconv_convert_alloc_counting(utf8, utf8_len, "UTF-8", to_encoding, &out_len);
        free(utf8);
        return ptn_owned_string_len(out, out_len);
    }
    size_t output_len = 0;
    char *output = ptn_mb_iconv_convert_alloc_counting(input.data, input.len, from_encoding, to_encoding, &output_len);
    return ptn_owned_string_len(output, output_len);
}

static PtnValue ptn_mb_convert_encoding_value(
    PtnRuntime *runtime,
    PtnValue value,
    const char *to_encoding,
    const char *from_encoding_list,
    const char *from_encoding_fallback,
    size_t line,
    size_t depth,
    PtnMbCheckStack *stack
) {
    PtnValue resolved = ptn_value_deref(value);
    if (resolved.type == PTN_ARRAY) {
        PtnArray *array = resolved.as.array;
        if (ptn_mb_check_stack_contains(stack, array)) {
            stack->saw_circular = 1;
            return ptn_array_from_literal_entries(0, NULL);
        }
        PtnValue result = ptn_array_from_literal_entries(0, NULL);
        if (depth >= 16) {
            return result;
        }
        ptn_mb_check_stack_push(stack, array);
        for (size_t i = 0; i < array->len; i++) {
            PtnArrayEntry *entry = &array->entries[i];
            PtnValue converted = ptn_mb_convert_encoding_value(
                runtime,
                entry->value,
                to_encoding,
                from_encoding_list,
                from_encoding_fallback,
                line,
                depth + 1,
                stack
            );
            ptn_array_set_entry(result.as.array, ptn_array_key_clone(entry->key), converted);
        }
        stack->len--;
        return result;
    }
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "mb_convert_encoding", 1, "string", resolved, line);
    char *from_encoding = ptn_mb_detect_list_select_for_string_alloc(from_encoding_list, input, from_encoding_fallback);
    PtnValue result = ptn_mb_convert_string_operand(runtime, input, to_encoding, from_encoding, line);
    free(from_encoding);
    ptn_string_operand_free(input);
    return result;
}

static PtnValue ptn_internal_mb_convert_encoding(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    const char *to_encoding = ptn_mb_encoding_from_value(runtime, "mb_convert_encoding", 2, "to_encoding", args[1], line, NULL, 0);
    if (to_encoding == NULL) {
        return ptn_null();
    }
    const char *from_encoding_fallback = ptn_mb_current_internal_encoding(runtime);
    char *from_encoding_list = argc >= 3
        ? ptn_mb_encoding_detect_list_from_value_alloc(
            runtime,
            "mb_convert_encoding",
            3,
            "from_encoding",
            args[2],
            line,
            from_encoding_fallback
        )
        : ptn_duplicate_string(from_encoding_fallback);
    if (from_encoding_list == NULL) {
        return ptn_null();
    }
    PtnMbCheckStack stack = { NULL, 0, 0, 0 };
    PtnValue result = ptn_mb_convert_encoding_value(
        runtime,
        args[0],
        to_encoding,
        from_encoding_list,
        from_encoding_fallback,
        line,
        0,
        &stack
    );
    if (stack.saw_circular) {
        ptn_emit_warning(&runtime->diagnostics, "mb_convert_encoding(): Cannot convert recursively referenced values", line);
    }
    ptn_mb_check_stack_free(&stack);
    free(from_encoding_list);
    return result;
}

static PtnValue ptn_internal_mb_strlen(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "mb_strlen", 1, "string", args[0], line);
    const char *encoding = argc >= 2
        ? ptn_mb_encoding_from_value(runtime, "mb_strlen", 2, "encoding", args[1], line, ptn_mb_current_internal_encoding(runtime), 1)
        : ptn_mb_current_internal_encoding(runtime);
    if (encoding == NULL) {
        ptn_string_operand_free(input);
        return ptn_null();
    }
    size_t len = input.len;
    if (!ptn_mb_encoding_is_raw(encoding)) {
        size_t utf8_len = 0;
        char *utf8 = ptn_mb_operand_to_utf8(input, encoding, &utf8_len);
        len = ptn_mb_utf8_strlen(utf8, utf8_len);
        free(utf8);
    }
    ptn_string_operand_free(input);
    if (len > (size_t)INT64_MAX) {
        ptn_abort_out_of_memory();
    }
    return ptn_int((int64_t)len);
}

static PtnValue ptn_internal_mb_substr(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "mb_substr", 1, "string", args[0], line);
    int64_t raw_start = ptn_internal_expect_integer_arg(runtime, "mb_substr", 2, "start", args[1], line);
    if (raw_start == INT64_MIN) {
        ptn_string_operand_free(input);
        ptn_throw_exception(runtime, "ValueError", "mb_substr(): Argument #2 ($start) must be between -9223372036854775807 and 9223372036854775807");
        return ptn_null();
    }
    const char *encoding = argc >= 4
        ? ptn_mb_encoding_from_value(runtime, "mb_substr", 4, "encoding", args[3], line, ptn_mb_current_internal_encoding(runtime), 1)
        : ptn_mb_current_internal_encoding(runtime);
    if (encoding == NULL) {
        ptn_string_operand_free(input);
        return ptn_null();
    }
    size_t utf8_len = 0;
    char *utf8 = ptn_mb_encoding_is_raw(encoding)
        ? ptn_duplicate_string_len(input.data, input.len)
        : ptn_mb_operand_to_utf8(input, encoding, &utf8_len);
    if (ptn_mb_encoding_is_raw(encoding)) {
        utf8_len = input.len;
    }
    size_t char_count = ptn_mb_encoding_is_raw(encoding) ? utf8_len : ptn_mb_utf8_strlen(utf8, utf8_len);
    size_t start = 0;
    if (raw_start < 0) {
        uint64_t distance = raw_start == INT64_MIN ? ((uint64_t)INT64_MAX + 1) : (uint64_t)(-raw_start);
        start = distance > char_count ? 0 : char_count - (size_t)distance;
    } else {
        start = (uint64_t)raw_start > char_count ? char_count : (size_t)raw_start;
    }
    size_t end = char_count;
    if (argc >= 3 && ptn_value_deref(args[2]).type != PTN_NULL) {
        int64_t raw_length = ptn_internal_expect_integer_arg(runtime, "mb_substr", 3, "length", args[2], line);
        if (raw_length == INT64_MIN) {
            free(utf8);
            ptn_string_operand_free(input);
            ptn_throw_exception(runtime, "ValueError", "mb_substr(): Argument #3 ($length) must be between -9223372036854775807 and 9223372036854775807");
            return ptn_null();
        }
        if (raw_length >= 0) {
            uint64_t requested = (uint64_t)raw_length;
            end = requested > char_count - start ? char_count : start + (size_t)requested;
        } else {
            uint64_t trim = raw_length == INT64_MIN ? ((uint64_t)INT64_MAX + 1) : (uint64_t)(-raw_length);
            end = trim > char_count ? 0 : char_count - (size_t)trim;
            if (end < start) {
                end = start;
            }
        }
    }
    size_t byte_start = ptn_mb_encoding_is_raw(encoding) ? start : ptn_mb_utf8_byte_offset_for_char(utf8, utf8_len, start);
    size_t byte_end = ptn_mb_encoding_is_raw(encoding) ? end : ptn_mb_utf8_byte_offset_for_char(utf8, utf8_len, end);
    char *slice = ptn_duplicate_string_len(utf8 + byte_start, byte_end - byte_start);
    PtnValue result = ptn_mb_string_from_utf8(slice, byte_end - byte_start, encoding);
    free(utf8);
    ptn_string_operand_free(input);
    return result;
}

static PtnValue ptn_internal_mb_strcut(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "mb_strcut", 1, "string", args[0], line);
    int64_t raw_start = ptn_internal_expect_integer_arg(runtime, "mb_strcut", 2, "start", args[1], line);
    if (argc >= 4) {
        const char *encoding = ptn_mb_encoding_from_value(runtime, "mb_strcut", 4, "encoding", args[3], line, ptn_mb_current_internal_encoding(runtime), 1);
        if (encoding == NULL) {
            ptn_string_operand_free(input);
            return ptn_null();
        }
    }
    size_t start = raw_start < 0 ? 0 : ((uint64_t)raw_start > input.len ? input.len : (size_t)raw_start);
    size_t len = input.len - start;
    if (argc >= 3 && ptn_value_deref(args[2]).type != PTN_NULL) {
        int64_t raw_length = ptn_internal_expect_integer_arg(runtime, "mb_strcut", 3, "length", args[2], line);
        if (raw_length >= 0 && (uint64_t)raw_length < len) {
            len = (size_t)raw_length;
        }
    }
    char *slice = ptn_duplicate_string_len(input.data + start, len);
    ptn_string_operand_free(input);
    return ptn_owned_string_len(slice, len);
}

static PtnValue ptn_internal_mb_strpos_named(PtnRuntime *runtime, const char *function_name, size_t argc, const PtnValue *args, size_t line, int reverse, int case_insensitive) {
    PtnStringOperand haystack = ptn_internal_expect_string_arg(runtime, function_name, 1, "haystack", args[0], line);
    PtnStringOperand needle = ptn_internal_expect_string_arg(runtime, function_name, 2, "needle", args[1], line);
    int64_t raw_offset = argc >= 3 ? ptn_internal_expect_integer_arg(runtime, function_name, 3, "offset", args[2], line) : 0;
    const char *encoding = argc >= 4
        ? ptn_mb_encoding_from_value(runtime, function_name, 4, "encoding", args[3], line, ptn_mb_current_internal_encoding(runtime), 1)
        : ptn_mb_current_internal_encoding(runtime);
    if (encoding == NULL) {
        ptn_string_operand_free(haystack);
        ptn_string_operand_free(needle);
        return ptn_null();
    }
    size_t hay_utf8_len = 0;
    size_t needle_utf8_len = 0;
    char *hay_utf8 = ptn_mb_operand_to_utf8(haystack, encoding, &hay_utf8_len);
    char *needle_utf8 = ptn_mb_operand_to_utf8(needle, encoding, &needle_utf8_len);
    size_t hay_chars = ptn_mb_encoding_is_raw(encoding) ? hay_utf8_len : ptn_mb_utf8_strlen(hay_utf8, hay_utf8_len);
    size_t start_char = 0;
    if (raw_offset < 0) {
        uint64_t distance = raw_offset == INT64_MIN ? ((uint64_t)INT64_MAX + 1) : (uint64_t)(-raw_offset);
        if (distance > hay_chars) {
            free(hay_utf8);
            free(needle_utf8);
            ptn_string_operand_free(haystack);
            ptn_string_operand_free(needle);
            char message[128];
            int written = snprintf(
                message,
                sizeof(message),
                "%s(): Argument #3 ($offset) must be contained in argument #1 ($haystack)",
                function_name
            );
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_throw_exception(runtime, "ValueError", message);
            return ptn_null();
        }
        start_char = hay_chars - (size_t)distance;
    } else {
        if ((uint64_t)raw_offset > hay_chars) {
            free(hay_utf8);
            free(needle_utf8);
            ptn_string_operand_free(haystack);
            ptn_string_operand_free(needle);
            char message[128];
            int written = snprintf(
                message,
                sizeof(message),
                "%s(): Argument #3 ($offset) must be contained in argument #1 ($haystack)",
                function_name
            );
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_throw_exception(runtime, "ValueError", message);
            return ptn_null();
        }
        start_char = (size_t)raw_offset;
    }
    size_t start_byte = ptn_mb_encoding_is_raw(encoding) ? start_char : ptn_mb_utf8_byte_offset_for_char(hay_utf8, hay_utf8_len, start_char);
    char *search_hay = hay_utf8;
    char *search_needle = needle_utf8;
    size_t search_hay_len = hay_utf8_len;
    size_t search_needle_len = needle_utf8_len;
    if (case_insensitive) {
        search_hay = ptn_mb_utf8_case_alloc(hay_utf8, hay_utf8_len, PTN_MB_CASE_LOWER, &search_hay_len);
        search_needle = ptn_mb_utf8_case_alloc(needle_utf8, needle_utf8_len, PTN_MB_CASE_LOWER, &search_needle_len);
    }
    size_t reverse_start = 0;
    size_t reverse_max_start = search_hay_len;
    if (reverse) {
        if (raw_offset >= 0) {
            reverse_start = start_byte;
        } else {
            reverse_max_start = start_byte;
        }
    }
    size_t match = reverse
        ? ptn_rfind_bytes_between(search_hay, search_hay_len, search_needle, search_needle_len, reverse_start, reverse_max_start, 0)
        : ptn_find_bytes_from(search_hay, search_hay_len, search_needle, search_needle_len, start_byte, 0);
    if (case_insensitive) {
        free(search_hay);
        free(search_needle);
    }
    free(needle_utf8);
    ptn_string_operand_free(haystack);
    ptn_string_operand_free(needle);
    if (match == SIZE_MAX) {
        free(hay_utf8);
        return ptn_bool(0);
    }
    size_t char_index = ptn_mb_encoding_is_raw(encoding) ? match : ptn_mb_utf8_char_index_for_byte(hay_utf8, hay_utf8_len, match);
    free(hay_utf8);
    return ptn_int((int64_t)char_index);
}

