static PtnValue ptn_internal_mb_ereg_replace_callback(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    ptn_mb_emit_regex_deprecation(runtime, "mb_ereg_replace_callback", line);
    PtnStringOperand pattern = ptn_internal_expect_string_arg(runtime, "mb_ereg_replace_callback", 1, "pattern", args[0], line);
    PtnValue callback = ptn_internal_expect_callback_arg(runtime, "mb_ereg_replace_callback", 2, "callback", args[1]);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(pattern);
        ptn_value_destroy(&callback);
        return ptn_null();
    }
    PtnStringOperand subject = ptn_internal_expect_string_arg(runtime, "mb_ereg_replace_callback", 3, "string", args[2], line);
    const char *extra_options = NULL;
    char *extra_options_copy = NULL;
    if (argc >= 4) {
        PtnStringOperand options = ptn_value_to_string_operand(args[3]);
        extra_options_copy = ptn_duplicate_string_len(options.data, options.len);
        ptn_string_operand_free(options);
        extra_options = extra_options_copy;
    }
    PtnValue result = ptn_mb_ereg_replace_impl(
        runtime,
        "mb_ereg_replace_callback",
        pattern,
        ptn_string_operand_borrowed(""),
        callback,
        1,
        subject,
        extra_options,
        line,
        0
    );
    free(extra_options_copy);
    ptn_value_destroy(&callback);
    ptn_string_operand_free(pattern);
    ptn_string_operand_free(subject);
    return result;
}

static PtnValue ptn_internal_mb_split(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand pattern = ptn_internal_expect_string_arg(runtime, "mb_split", 1, "pattern", args[0], line);
    PtnStringOperand subject = ptn_internal_expect_string_arg(runtime, "mb_split", 2, "string", args[1], line);
    int64_t limit = argc >= 3 ? ptn_internal_expect_integer_arg(runtime, "mb_split", 3, "limit", args[2], line) : -1;
    ptn_mb_emit_regex_deprecation(runtime, "mb_split", line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(pattern);
        ptn_string_operand_free(subject);
        return ptn_null();
    }
    if (ptn_mb_regex_uses_utf8(runtime) && !ptn_mb_utf8_is_valid(subject.data, subject.len)) {
        ptn_string_operand_free(pattern);
        ptn_string_operand_free(subject);
        return ptn_bool(0);
    }
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    if (pattern.len == 0) {
        ptn_array_set_entry(result.as.array, ptn_array_int_key(0), ptn_owned_string_len(ptn_duplicate_string_len(subject.data, subject.len), subject.len));
        ptn_string_operand_free(pattern);
        ptn_string_operand_free(subject);
        return result;
    }

    PtnPregProgram program;
    if (!ptn_mb_compile_regex_program(runtime, "mb_split", pattern, 0, NULL, &program, line)) {
        ptn_value_destroy(&result);
        ptn_string_operand_free(pattern);
        ptn_string_operand_free(subject);
        return ptn_bool(0);
    }
    PtnMbRegexSubject prepared_subject;
    ptn_mb_regex_subject_prepare(subject, ptn_mb_current_regex_encoding(runtime), &prepared_subject);
    PtnPregMatch *matches = calloc(program.match_count, sizeof(PtnPregMatch));
    if (matches == NULL) {
        ptn_preg_program_free(&program);
        ptn_mb_regex_subject_free(runtime, &prepared_subject);
        ptn_string_operand_free(pattern);
        ptn_string_operand_free(subject);
        ptn_abort_out_of_memory();
    }

    size_t cursor = 0;
    size_t search_offset = 0;
    int64_t index = 0;
    while ((limit < 0 || (limit > 1 && index < limit - 1)) && search_offset <= prepared_subject.subject_len) {
        int match_result = ptn_preg_program_match(runtime, &program, prepared_subject.subject, prepared_subject.subject_len, search_offset, 0, matches);
        if (match_result <= 0) {
            break;
        }
        size_t match_start = matches[0].start;
        size_t match_end = matches[0].end;
        ptn_mb_regex_translate_matches_to_source(&prepared_subject, matches, program.match_count);
        size_t start = matches[0].start;
        size_t end = matches[0].end;
        if (start > subject.len || end > subject.len || end < start) {
            break;
        }
        int skip_empty_piece = start == cursor && end == cursor;
        if (!skip_empty_piece) {
            ptn_array_set_entry(
                result.as.array,
                ptn_array_int_key(index++),
                ptn_owned_string_len(ptn_duplicate_string_len(subject.data + cursor, start - cursor), start - cursor)
            );
        }
        cursor = end;
        if (match_end == match_start) {
            if (match_end >= prepared_subject.subject_len) {
                break;
            }
            search_offset = ptn_preg_next_start_offset(prepared_subject.subject, prepared_subject.subject_len, match_end, program.utf_mode);
        } else {
            search_offset = match_end;
        }
    }
    ptn_array_set_entry(
        result.as.array,
        ptn_array_int_key(index),
        ptn_owned_string_len(ptn_duplicate_string_len(subject.data + cursor, subject.len - cursor), subject.len - cursor)
    );
    ptn_preg_matches_free(matches, program.match_count);
    ptn_preg_program_free(&program);
    ptn_mb_regex_subject_free(runtime, &prepared_subject);
    ptn_string_operand_free(pattern);
    ptn_string_operand_free(subject);
    return result;
}

static PtnValue ptn_internal_mb_ereg_search_init(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    ptn_mb_emit_regex_deprecation(runtime, "mb_ereg_search_init", line);
    PtnStringOperand subject = ptn_value_to_string_operand(args[0]);
    if (ptn_mb_regex_uses_utf8(runtime) && !ptn_mb_utf8_is_valid(subject.data, subject.len)) {
        ptn_preg_free_subject_copy(runtime, ptn_mb_ereg_search_subject, ptn_mb_ereg_search_subject_len);
        ptn_mb_ereg_search_subject = NULL;
        ptn_mb_ereg_search_subject_len = 0;
        free(ptn_mb_ereg_search_pattern);
        ptn_mb_ereg_search_pattern = NULL;
        ptn_mb_clear_last_regs();
        ptn_string_operand_free(subject);
        return ptn_bool(0);
    }
    ptn_preg_free_subject_copy(runtime, ptn_mb_ereg_search_subject, ptn_mb_ereg_search_subject_len);
    ptn_mb_ereg_search_subject = ptn_duplicate_string_len(subject.data, subject.len);
    ptn_mb_ereg_search_subject_len = subject.len;
    ptn_string_operand_free(subject);
    if (argc >= 2) {
        PtnStringOperand pattern = ptn_value_to_string_operand(args[1]);
        if (pattern.len == 0) {
            ptn_string_operand_free(pattern);
            ptn_throw_exception(runtime, "ValueError", "mb_ereg_search_init(): Argument #2 ($pattern) must not be empty");
            return ptn_null();
        }
        free(ptn_mb_ereg_search_pattern);
        ptn_mb_ereg_search_pattern = ptn_duplicate_string_len(pattern.data, pattern.len);
        ptn_string_operand_free(pattern);
    }
    if (argc >= 3) {
        PtnStringOperand options = ptn_value_to_string_operand(args[2]);
        char *copy = ptn_duplicate_string_len(options.data, options.len);
        ptn_string_operand_free(options);
        ptn_mb_copy_state_string(ptn_mb_ereg_search_options_name, sizeof(ptn_mb_ereg_search_options_name), copy);
        free(copy);
    } else {
        ptn_mb_copy_state_string(ptn_mb_ereg_search_options_name, sizeof(ptn_mb_ereg_search_options_name), "");
    }
    ptn_mb_ereg_search_pos = 0;
    return ptn_bool(1);
}

static PtnValue ptn_internal_mb_ereg_search_getpos(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    ptn_mb_emit_regex_deprecation(runtime, "mb_ereg_search_getpos", line);
    return ptn_int((int64_t)ptn_mb_ereg_search_pos);
}

static PtnValue ptn_internal_mb_ereg_search_setpos(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    ptn_mb_emit_regex_deprecation(runtime, "mb_ereg_search_setpos", line);
    int64_t pos = ptn_value_to_integer(args[0]);
    if (ptn_mb_ereg_search_subject == NULL) {
        if (pos < 0) {
            ptn_throw_exception(runtime, "ValueError", "mb_ereg_search_setpos(): Argument #1 ($offset) is out of range");
            return ptn_null();
        }
        ptn_mb_ereg_search_pos = (size_t)pos;
        return ptn_bool(1);
    }
    int64_t subject_len = (int64_t)ptn_mb_ereg_search_subject_len;
    int64_t resolved = pos < 0 ? subject_len + pos : pos;
    if (resolved < 0 || resolved > subject_len) {
        ptn_throw_exception(runtime, "ValueError", "mb_ereg_search_setpos(): Argument #1 ($offset) is out of range");
        return ptn_null();
    }
    ptn_mb_ereg_search_pos = (size_t)resolved;
    return ptn_bool(1);
}

static PtnValue ptn_mb_ereg_search_pos_impl(PtnRuntime *runtime, const char *function_name, size_t argc, const PtnValue *args, size_t line, int throw_no_pattern) {
    const char *pattern = NULL;
    if (argc >= 1) {
        PtnStringOperand operand = ptn_value_to_string_operand(args[0]);
        free(ptn_mb_ereg_search_pattern);
        ptn_mb_ereg_search_pattern = ptn_duplicate_string_len(operand.data, operand.len);
        ptn_string_operand_free(operand);
    }
    if (argc >= 2) {
        PtnStringOperand options = ptn_value_to_string_operand(args[1]);
        char *copy = ptn_duplicate_string_len(options.data, options.len);
        ptn_string_operand_free(options);
        ptn_mb_copy_state_string(ptn_mb_ereg_search_options_name, sizeof(ptn_mb_ereg_search_options_name), copy);
        free(copy);
    }
    pattern = ptn_mb_ereg_search_pattern;
    if (pattern == NULL || ptn_mb_ereg_search_subject == NULL) {
        if (throw_no_pattern && pattern == NULL) {
            ptn_throw_exception(runtime, "Error", "No pattern was provided");
            return ptn_null();
        }
        return ptn_bool(0);
    }

    PtnStringOperand pattern_operand = ptn_string_operand_borrowed(pattern);
    PtnPregProgram program;
    if (!ptn_mb_compile_regex_program(runtime, function_name, pattern_operand, 0, ptn_mb_ereg_search_options_name, &program, line)) {
        ptn_mb_clear_last_regs();
        return ptn_bool(0);
    }
    PtnStringOperand search_subject_operand = ptn_string_operand_borrowed_len(
        ptn_mb_ereg_search_subject,
        ptn_mb_ereg_search_subject_len
    );
    PtnMbRegexSubject prepared_subject;
    ptn_mb_regex_subject_prepare(search_subject_operand, ptn_mb_current_regex_encoding(runtime), &prepared_subject);
    PtnPregMatch *matches = calloc(program.match_count, sizeof(PtnPregMatch));
    if (matches == NULL) {
        ptn_mb_regex_subject_free(runtime, &prepared_subject);
        ptn_preg_program_free(&program);
        ptn_abort_out_of_memory();
    }

    size_t match_offset = ptn_mb_regex_source_to_match_offset(&prepared_subject, ptn_mb_ereg_search_pos);
    int match_result = ptn_preg_program_match(
        runtime,
        &program,
        prepared_subject.subject,
        prepared_subject.subject_len,
        match_offset,
        0,
        matches
    );
    if (match_result <= 0) {
        ptn_preg_matches_free(matches, program.match_count);
        ptn_mb_regex_subject_free(runtime, &prepared_subject);
        ptn_preg_program_free(&program);
        return ptn_bool(0);
    }
    ptn_mb_regex_translate_matches_to_source(&prepared_subject, matches, program.match_count);
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    size_t start = matches[0].start;
    size_t len = matches[0].end - matches[0].start;
    ptn_array_set_entry(result.as.array, ptn_array_int_key(0), ptn_int((int64_t)start));
    ptn_array_set_entry(result.as.array, ptn_array_int_key(1), ptn_int((int64_t)len));
    ptn_mb_ereg_search_pos = matches[0].end;

    PtnValue regs = ptn_mb_regex_regs_value(
        ptn_mb_ereg_search_subject,
        matches,
        program.captures,
        program.capture_count
    );
    ptn_mb_store_last_regs(regs);
    ptn_value_destroy(&regs);
    ptn_preg_matches_free(matches, program.match_count);
    ptn_mb_regex_subject_free(runtime, &prepared_subject);
    ptn_preg_program_free(&program);
    return result;
}

