static PtnValue ptn_internal_mb_get_info(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)line;
    if (argc >= 1) {
        PtnStringOperand key = ptn_value_to_string_operand(args[0]);
        PtnValue value = ptn_bool(0);
        if (ptn_string_operand_ascii_case_equal(key, "internal_encoding")) {
            value = ptn_owned_string(ptn_duplicate_string(ptn_mb_current_internal_encoding(runtime)));
        } else if (ptn_string_operand_ascii_case_equal(key, "http_output")) {
            value = ptn_owned_string(ptn_duplicate_string(ptn_mb_current_http_output(runtime)));
        } else if (ptn_string_operand_ascii_case_equal(key, "http_input")) {
            value = ptn_string("pass");
        } else if (ptn_string_operand_ascii_case_equal(key, "func_overload")) {
            value = ptn_int(0);
        } else if (ptn_string_operand_ascii_case_equal(key, "func_overload_list")) {
            value = ptn_string("no overload");
        } else if (ptn_string_operand_ascii_case_equal(key, "mail_charset")) {
            value = ptn_owned_string(ptn_duplicate_string(ptn_mb_current_internal_encoding(runtime)));
        } else if (ptn_string_operand_ascii_case_equal(key, "mail_header_encoding") ||
                   ptn_string_operand_ascii_case_equal(key, "mail_body_encoding")) {
            value = ptn_string("BASE64");
        } else if (ptn_string_operand_ascii_case_equal(key, "illegal_chars")) {
            value = ptn_int(ptn_mb_illegal_chars);
        } else if (ptn_string_operand_ascii_case_equal(key, "encoding_translation")) {
            value = ptn_string("Off");
        } else if (ptn_string_operand_ascii_case_equal(key, "language")) {
            value = ptn_owned_string(ptn_duplicate_string(ptn_mb_current_language()));
        } else if (ptn_string_operand_ascii_case_equal(key, "detect_order")) {
            value = ptn_owned_string(ptn_duplicate_string(ptn_mb_current_detect_order()));
        } else if (ptn_string_operand_ascii_case_equal(key, "substitute_character")) {
            value = ptn_owned_string(ptn_duplicate_string(ptn_mb_current_substitute_character()));
        }
        ptn_string_operand_free(key);
        return value;
    }

    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    ptn_array_set_entry(result.as.array, ptn_array_string_key("internal_encoding"), ptn_owned_string(ptn_duplicate_string(ptn_mb_current_internal_encoding(runtime))));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("http_output"), ptn_owned_string(ptn_duplicate_string(ptn_mb_current_http_output(runtime))));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("http_input"), ptn_string("pass"));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("func_overload"), ptn_int(0));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("func_overload_list"), ptn_string("no overload"));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("mail_charset"), ptn_owned_string(ptn_duplicate_string(ptn_mb_current_internal_encoding(runtime))));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("mail_header_encoding"), ptn_string("BASE64"));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("mail_body_encoding"), ptn_string("BASE64"));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("illegal_chars"), ptn_int(ptn_mb_illegal_chars));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("encoding_translation"), ptn_string("Off"));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("language"), ptn_owned_string(ptn_duplicate_string(ptn_mb_current_language())));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("detect_order"), ptn_owned_string(ptn_duplicate_string(ptn_mb_current_detect_order())));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("substitute_character"), ptn_owned_string(ptn_duplicate_string(ptn_mb_current_substitute_character())));
    return result;
}

typedef struct {
    const char *from_encoding;
    const char *to_encoding;
} PtnMbParseStrConversionContext;

static char *ptn_mb_parse_str_convert_decoded_component(
    PtnRuntime *runtime,
    const char *data,
    size_t len,
    void *context,
    size_t *output_len_out
) {
    (void)runtime;
    PtnMbParseStrConversionContext *conversion = (PtnMbParseStrConversionContext *)context;
    char *output = ptn_mb_iconv_convert_alloc_counting(
        data,
        len,
        conversion->from_encoding,
        conversion->to_encoding,
        output_len_out
    );
    return output;
}

static char *ptn_mb_parse_str_http_input_list_alloc(PtnRuntime *runtime, size_t line) {
    const char *fallback = ptn_mb_current_internal_encoding(runtime);
    const char *configured = getenv("PTN_MBSTRING_HTTP_INPUT");
    if (configured == NULL || configured[0] == '\0') {
        configured = ptn_mb_current_http_input(runtime);
    }
    PtnValue value = ptn_owned_string(ptn_duplicate_string(configured));
    char *list = ptn_mb_encoding_detect_list_from_value_alloc(
        runtime,
        "mb_parse_str",
        1,
        "string",
        value,
        line,
        fallback
    );
    ptn_value_destroy(&value);
    return list;
}

static PtnValue ptn_internal_mb_parse_str(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    if (argc < 2) {
        return ptn_bool(0);
    }
    PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "mb_parse_str", 1, "string", args[0], line);
    if (memchr(string.data, '\0', string.len) != NULL) {
        ptn_string_operand_free(string);
        ptn_throw_exception(runtime, "ValueError", "mb_parse_str(): Argument #1 ($string) must not contain any null bytes");
        return ptn_null();
    }

    char *from_encoding_list = ptn_mb_parse_str_http_input_list_alloc(runtime, line);
    if (from_encoding_list == NULL) {
        ptn_string_operand_free(string);
        return ptn_null();
    }
    char *from_encoding = ptn_mb_detect_list_select_for_string_alloc(
        from_encoding_list,
        string,
        ptn_mb_current_internal_encoding(runtime)
    );
    PtnMbParseStrConversionContext conversion = {
        from_encoding,
        ptn_mb_current_internal_encoding(runtime),
    };
    PtnValue result = ptn_parse_str_to_array_with_converter(
        runtime,
        string.data,
        string.len,
        ptn_runtime_arg_separator_input(runtime),
        ptn_mb_parse_str_convert_decoded_component,
        &conversion
    );
    free(from_encoding);
    free(from_encoding_list);
    if (args[1].type == PTN_REFERENCE) {
        ptn_reference_assign(runtime, args[1].as.reference, result);
    } else {
        ptn_value_drop(&result);
    }
    ptn_string_operand_free(string);
    return ptn_bool(1);
}

static PtnValue ptn_internal_mb_output_handler(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)line;
    if (argc == 0) {
        return ptn_string("");
    }
    PtnStringOperand input = ptn_value_to_string_operand(args[0]);
    const char *from_encoding = ptn_mb_current_internal_encoding(runtime);
    const char *to_encoding = ptn_mb_current_http_output(runtime);
    size_t len = 0;
    char *converted = ptn_mb_iconv_convert_alloc_counting(
        input.data,
        input.len,
        from_encoding,
        to_encoding,
        &len
    );
    ptn_string_operand_free(input);
    return ptn_owned_string_len(converted, len);
}

static int ptn_mb_operand_contains_nul(PtnStringOperand operand) {
    return memchr(operand.data, '\0', operand.len) != NULL;
}

static int ptn_mb_send_mail_reject_nul(
    PtnRuntime *runtime,
    size_t position,
    const char *argument_name,
    PtnStringOperand operand
) {
    if (!ptn_mb_operand_contains_nul(operand)) {
        return 1;
    }
    char message[128];
    int written = snprintf(
        message,
        sizeof(message),
        "mb_send_mail(): Argument #%zu ($%s) must not contain any null bytes",
        position,
        argument_name
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "ValueError", message);
    return 0;
}

static char *ptn_mb_send_mail_path_from_ini_alloc(void) {
    const char *setting = getenv("PTN_SENDMAIL_PATH");
    if (setting == NULL) {
        return NULL;
    }
    const char *marker = strstr(setting, "{MAIL:");
    if (marker == NULL) {
        return NULL;
    }
    const char *start = marker + strlen("{MAIL:");
    const char *end = strchr(start, '}');
    if (end == NULL || end <= start) {
        return NULL;
    }
    return ptn_duplicate_string_len(start, (size_t)(end - start));
}

static char *ptn_mb_send_mail_path_from_tee_alloc(void) {
    const char *setting = getenv("PTN_SENDMAIL_PATH");
    if (setting == NULL) {
        return NULL;
    }
    while (isspace((unsigned char)*setting)) {
        setting++;
    }
    if (strncmp(setting, "tee", 3) != 0 || (setting[3] != '\0' && !isspace((unsigned char)setting[3]))) {
        return NULL;
    }
    const char *start = setting + 3;
    while (isspace((unsigned char)*start)) {
        start++;
    }
    if (*start == '\0') {
        return NULL;
    }
    const char *end = start;
    while (*end != '\0' && !isspace((unsigned char)*end)) {
        end++;
    }
    return end > start ? ptn_duplicate_string_len(start, (size_t)(end - start)) : NULL;
}

static int ptn_ascii_contains_case_insensitive(const char *data, size_t len, const char *needle) {
    size_t needle_len = strlen(needle);
    if (needle_len == 0 || needle_len > len) {
        return 0;
    }
    for (size_t i = 0; i + needle_len <= len; i++) {
        size_t j = 0;
        while (j < needle_len &&
               tolower((unsigned char)data[i + j]) == tolower((unsigned char)needle[j])) {
            j++;
        }
        if (j == needle_len) {
            return 1;
        }
    }
    return 0;
}

static void ptn_mb_send_mail_append_header_block(PtnStringBuffer *message, PtnStringOperand headers) {
    if (headers.len == 0) {
        return;
    }
    ptn_string_buffer_append_len(message, headers.data, headers.len);
    if (headers.data[headers.len - 1] != '\n') {
        ptn_string_buffer_append_char(message, '\n');
    }
}

static PtnValue ptn_internal_mb_send_mail(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand to = ptn_internal_expect_string_arg(runtime, "mb_send_mail", 1, "to", args[0], line);
    PtnStringOperand subject = ptn_internal_expect_string_arg(runtime, "mb_send_mail", 2, "subject", args[1], line);
    PtnStringOperand body = ptn_internal_expect_string_arg(runtime, "mb_send_mail", 3, "message", args[2], line);
    PtnStringOperand headers = argc >= 4
        ? ptn_internal_expect_string_arg(runtime, "mb_send_mail", 4, "additional_headers", args[3], line)
        : ptn_string_operand_borrowed("");
    PtnStringOperand params = argc >= 5
        ? ptn_internal_expect_string_arg(runtime, "mb_send_mail", 5, "additional_params", args[4], line)
        : ptn_string_operand_borrowed("");
    if (runtime->exceptions->active_exception != NULL ||
        !ptn_mb_send_mail_reject_nul(runtime, 1, "to", to) ||
        !ptn_mb_send_mail_reject_nul(runtime, 2, "subject", subject) ||
        !ptn_mb_send_mail_reject_nul(runtime, 3, "message", body) ||
        !ptn_mb_send_mail_reject_nul(runtime, 4, "additional_headers", headers) ||
        !ptn_mb_send_mail_reject_nul(runtime, 5, "additional_params", params)) {
        ptn_string_operand_free(to);
        ptn_string_operand_free(subject);
        ptn_string_operand_free(body);
        ptn_string_operand_free(headers);
        ptn_string_operand_free(params);
        return ptn_null();
    }

    char *mail_path = ptn_mb_send_mail_path_from_ini_alloc();
    if (mail_path == NULL) {
        mail_path = ptn_mb_send_mail_path_from_tee_alloc();
    }
    if (mail_path == NULL) {
        ptn_string_operand_free(to);
        ptn_string_operand_free(subject);
        ptn_string_operand_free(body);
        ptn_string_operand_free(headers);
        ptn_string_operand_free(params);
        return ptn_bool(0);
    }

    PtnValue body_value = ptn_owned_string_len(ptn_duplicate_string_len(body.data, body.len), body.len);
    PtnValue encoded_body_value = ptn_internal_base64_encode(runtime, 1, &body_value, line);
    PtnStringOperand encoded_body = ptn_value_to_string_operand(encoded_body_value);
    PtnStringBuffer message;
    ptn_string_buffer_init(&message);
    ptn_string_buffer_append(&message, "To: ");
    ptn_string_buffer_append_len(&message, to.data, to.len);
    ptn_string_buffer_append_char(&message, '\n');
    ptn_string_buffer_append(&message, "Subject: ");
    ptn_string_buffer_append_len(&message, subject.data, subject.len);
    ptn_string_buffer_append_char(&message, '\n');
    ptn_mb_send_mail_append_header_block(&message, headers);
    if (!ptn_ascii_contains_case_insensitive(headers.data, headers.len, "mime-version:")) {
        ptn_string_buffer_append(&message, "MIME-Version: 1.0\n");
    }
    ptn_string_buffer_append(&message, "Content-Type: text/plain; charset=");
    ptn_string_buffer_append(&message, ptn_mb_current_internal_encoding(runtime));
    ptn_string_buffer_append(&message, "\nContent-Transfer-Encoding: BASE64\n\n");
    ptn_string_buffer_append_len(&message, encoded_body.data, encoded_body.len);
    ptn_string_buffer_append_char(&message, '\n');

    FILE *mail_file = fopen(mail_path, "wb");
    int ok = 0;
    if (mail_file != NULL) {
        ok = fwrite(message.data, 1, message.len, mail_file) == message.len;
        ok = fclose(mail_file) == 0 && ok;
    }

    free(mail_path);
    free(message.data);
    ptn_string_operand_free(encoded_body);
    ptn_value_destroy(&encoded_body_value);
    ptn_value_destroy(&body_value);
    ptn_string_operand_free(to);
    ptn_string_operand_free(subject);
    ptn_string_operand_free(body);
    ptn_string_operand_free(headers);
    ptn_string_operand_free(params);
    return ptn_bool(ok);
}

static char *ptn_mb_mime_fold_ascii_alloc(
    PtnStringOperand input,
    PtnStringOperand linefeed,
    size_t indent,
    size_t *output_len
) {
    const size_t limit = 74;
    size_t prefix = indent > limit ? limit : indent;
    if (input.len <= limit - prefix) {
        *output_len = input.len;
        return ptn_duplicate_string_len(input.data, input.len);
    }
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    size_t start = 0;
    while (start < input.len) {
        size_t available = limit > prefix ? limit - prefix : limit;
        if (input.len - start <= available) {
            ptn_string_buffer_append_len(&output, input.data + start, input.len - start);
            break;
        }
        size_t hard_end = start + available;
        size_t split = hard_end;
        for (size_t i = hard_end; i > start; i--) {
            if (input.data[i - 1] == ' ') {
                split = i - 1;
                break;
            }
        }
        if (split == start) {
            split = hard_end;
        }
        ptn_string_buffer_append_len(&output, input.data + start, split - start);
        ptn_string_buffer_append_len(&output, linefeed.data, linefeed.len);
        ptn_string_buffer_append_char(&output, ' ');
        start = split < input.len && input.data[split] == ' ' ? split + 1 : split;
        prefix = 1;
    }
    *output_len = output.len;
    return output.data == NULL ? ptn_duplicate_string_len("", 0) : output.data;
}

static PtnValue ptn_internal_mb_encode_mimeheader(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "mb_encode_mimeheader", 1, "string", args[0], line);
    const char *charset = argc >= 2
        ? ptn_mb_encoding_from_value(runtime, "mb_encode_mimeheader", 2, "charset", args[1], line, ptn_mb_current_internal_encoding(runtime), 1)
        : ptn_mb_current_internal_encoding(runtime);
    if (charset == NULL) {
        ptn_string_operand_free(input);
        return ptn_null();
    }
    if (ptn_ascii_case_equal(charset, "UTF7-IMAP")) {
        ptn_string_operand_free(input);
        ptn_throw_exception(runtime, "ValueError", "mb_encode_mimeheader(): Argument #2 ($charset) \"UTF7-IMAP\" cannot be used for MIME header encoding");
        return ptn_null();
    }
    PtnStringOperand transfer = argc >= 3
        ? ptn_internal_expect_string_arg(runtime, "mb_encode_mimeheader", 3, "transfer_encoding", args[2], line)
        : ptn_string_operand_borrowed("B");
    PtnStringOperand linefeed = argc >= 4
        ? ptn_internal_expect_string_arg(runtime, "mb_encode_mimeheader", 4, "newline", args[3], line)
        : ptn_string_operand_borrowed("\r\n");
    int64_t indent_arg = argc >= 5
        ? ptn_internal_expect_integer_arg(runtime, "mb_encode_mimeheader", 5, "indent", args[4], line)
        : 0;
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(input);
        ptn_string_operand_free(transfer);
        ptn_string_operand_free(linefeed);
        return ptn_null();
    }
    int ascii_only = 1;
    for (size_t i = 0; i < input.len; i++) {
        if ((unsigned char)input.data[i] >= 0x80) {
            ascii_only = 0;
            break;
        }
    }
    if (ascii_only) {
        size_t len = 0;
        char *copy = ptn_mb_mime_fold_ascii_alloc(input, linefeed, indent_arg < 0 ? 0 : (size_t)indent_arg, &len);
        ptn_string_operand_free(input);
        ptn_string_operand_free(transfer);
        ptn_string_operand_free(linefeed);
        return ptn_owned_string_len(copy, len);
    }
    PtnValue temp = ptn_owned_string_len(ptn_duplicate_string_len(input.data, input.len), input.len);
    PtnValue encoded = ptn_internal_base64_encode(runtime, 1, &temp, line);
    PtnStringOperand encoded_string = ptn_value_to_string_operand(encoded);
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    ptn_string_buffer_append(&output, "=?");
    ptn_string_buffer_append(&output, charset);
    ptn_string_buffer_append(&output, "?B?");
    ptn_string_buffer_append_len(&output, encoded_string.data, encoded_string.len);
    ptn_string_buffer_append(&output, "?=");
    ptn_string_operand_free(encoded_string);
    ptn_value_destroy(&encoded);
    ptn_value_destroy(&temp);
    ptn_string_operand_free(input);
    ptn_string_operand_free(transfer);
    ptn_string_operand_free(linefeed);
    return ptn_owned_string_len(output.data, output.len);
}

static int ptn_mb_mime_token_char(unsigned char byte) {
    return byte > 0x20 && byte != '?' && byte != '=';
}

static void ptn_mb_mime_decode_q_text(
    PtnStringBuffer *output,
    const char *data,
    size_t len
) {
    for (size_t i = 0; i < len; i++) {
        unsigned char byte = (unsigned char)data[i];
        if (byte == '_') {
            ptn_string_buffer_append_char(output, ' ');
            continue;
        }
        if (byte == '=' && i + 2 < len) {
            int high = ptn_hex_nibble((unsigned char)data[i + 1]);
            int low = ptn_hex_nibble((unsigned char)data[i + 2]);
            if (high >= 0 && low >= 0) {
                ptn_string_buffer_append_char(output, (char)((high << 4) | low));
                i += 2;
                continue;
            }
        }
        ptn_string_buffer_append_char(output, (char)byte);
    }
}

static void ptn_mb_mime_decode_b_text(
    PtnRuntime *runtime,
    PtnStringBuffer *output,
    const char *data,
    size_t len,
    size_t line
) {
    PtnValue encoded = ptn_owned_string_len(ptn_duplicate_string_len(data, len), len);
    PtnValue decoded = ptn_internal_base64_decode(runtime, 1, &encoded, line);
    ptn_value_destroy(&encoded);
    PtnValue resolved = ptn_value_deref(decoded);
    if (resolved.type == PTN_STRING) {
        ptn_string_buffer_append_len(
            output,
            (const char *)resolved.as.string.data,
            resolved.as.string.len
        );
    }
    ptn_value_destroy(&decoded);
}

static void ptn_mb_mime_append_decoded_word(
    PtnRuntime *runtime,
    PtnStringBuffer *output,
    const char *charset,
    size_t charset_len,
    unsigned char transfer_encoding,
    const char *encoded_text,
    size_t encoded_text_len,
    size_t line
) {
    PtnStringBuffer decoded;
    ptn_string_buffer_init(&decoded);
    if (transfer_encoding == 'q' || transfer_encoding == 'Q') {
        ptn_mb_mime_decode_q_text(&decoded, encoded_text, encoded_text_len);
    } else {
        ptn_mb_mime_decode_b_text(runtime, &decoded, encoded_text, encoded_text_len, line);
    }

    PtnStringOperand charset_operand = {
        .data = charset,
        .len = charset_len,
        .owned = NULL
    };
    const char *canonical = ptn_mb_canonical_encoding_name(charset_operand);
    if (canonical == NULL) {
        ptn_string_buffer_append_len(output, decoded.data, decoded.len);
        free(decoded.data);
        return;
    }

    size_t converted_len = 0;
    char *converted = ptn_mb_iconv_convert_alloc(
        decoded.data,
        decoded.len,
        canonical,
        ptn_mb_current_internal_encoding(runtime),
        &converted_len
    );
    ptn_string_buffer_append_len(output, converted, converted_len);
    free(converted);
    free(decoded.data);
}

static PtnValue ptn_internal_mb_decode_mimeheader(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "mb_decode_mimeheader", 1, "string", args[0], line);
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    size_t i = 0;
    while (i < input.len) {
        if (i + 4 >= input.len || input.data[i] != '=' || input.data[i + 1] != '?') {
            ptn_string_buffer_append_char(&output, input.data[i++]);
            continue;
        }

        size_t charset_start = i + 2;
        size_t charset_end = charset_start;
        while (charset_end < input.len && ptn_mb_mime_token_char((unsigned char)input.data[charset_end])) {
            charset_end++;
        }
        if (charset_end == charset_start || charset_end + 2 >= input.len || input.data[charset_end] != '?') {
            ptn_string_buffer_append_char(&output, input.data[i++]);
            continue;
        }

        unsigned char transfer_encoding = (unsigned char)input.data[charset_end + 1];
        if ((transfer_encoding != 'q' && transfer_encoding != 'Q' && transfer_encoding != 'b' && transfer_encoding != 'B') ||
            input.data[charset_end + 2] != '?') {
            ptn_string_buffer_append_char(&output, input.data[i++]);
            continue;
        }

        size_t text_start = charset_end + 3;
        size_t text_end = text_start;
        int found_end = 0;
        while (text_end + 1 < input.len) {
            if (input.data[text_end] == '?' && input.data[text_end + 1] == '=') {
                found_end = 1;
                break;
            }
            text_end++;
        }
        if (!found_end) {
            ptn_string_buffer_append_char(&output, input.data[i++]);
            continue;
        }

        ptn_mb_mime_append_decoded_word(
            runtime,
            &output,
            input.data + charset_start,
            charset_end - charset_start,
            transfer_encoding,
            input.data + text_start,
            text_end - text_start,
            line
        );
        i = text_end + 2;
    }
    ptn_string_operand_free(input);
    return ptn_owned_string_len(output.data, output.len);
}

static void ptn_iconv_mime_emit_encoding_length_warning(
    PtnRuntime *runtime,
    const char *function_name,
    size_t line
) {
    char message[128];
    int written = snprintf(
        message,
        sizeof(message),
        "%s(): Encoding parameter exceeds the maximum allowed length of 64 characters",
        function_name
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_warning(&runtime->diagnostics, message, line);
}

static char *ptn_iconv_mime_target_encoding_alloc(
    PtnRuntime *runtime,
    const char *function_name,
    size_t position,
    const char *argument_name,
    const PtnValue *value,
    size_t line,
    int *ok
) {
    *ok = 1;
    if (value == NULL || ptn_value_deref(*value).type == PTN_NULL) {
        return ptn_duplicate_string(ptn_iconv_effective_internal_encoding(runtime));
    }
    PtnStringOperand encoding =
        ptn_internal_expect_string_arg(runtime, function_name, position, argument_name, *value, line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(encoding);
        *ok = 0;
        return NULL;
    }
    if (encoding.len > 64) {
        ptn_iconv_mime_emit_encoding_length_warning(runtime, function_name, line);
        ptn_string_operand_free(encoding);
        *ok = 0;
        return NULL;
    }
    char *target = ptn_duplicate_string_len(encoding.data, encoding.len);
    ptn_string_operand_free(encoding);
    return target;
}

static int ptn_iconv_mime_parse_encoded_word(
    const char *data,
    size_t len,
    size_t offset,
    size_t *charset_start,
    size_t *charset_len,
    unsigned char *transfer_encoding,
    size_t *text_start,
    size_t *text_len,
    size_t *end_offset
) {
    if (offset + 4 >= len || data[offset] != '=' || data[offset + 1] != '?') {
        return 0;
    }
    size_t cursor = offset + 2;
    size_t charset_end = cursor;
    while (charset_end < len && ptn_mb_mime_token_char((unsigned char)data[charset_end])) {
        charset_end++;
    }
    if (charset_end == cursor || charset_end + 2 >= len || data[charset_end] != '?') {
        return 0;
    }
    unsigned char encoding = (unsigned char)data[charset_end + 1];
    if ((encoding != 'q' && encoding != 'Q' && encoding != 'b' && encoding != 'B') ||
        data[charset_end + 2] != '?') {
        return 0;
    }
    size_t body_start = charset_end + 3;
    size_t body_end = body_start;
    while (body_end + 1 < len) {
        if (data[body_end] == '?' && data[body_end + 1] == '=') {
            *charset_start = cursor;
            *charset_len = charset_end - cursor;
            *transfer_encoding = encoding;
            *text_start = body_start;
            *text_len = body_end - body_start;
            *end_offset = body_end + 2;
            return 1;
        }
        body_end++;
    }
    return 0;
}

static char *ptn_iconv_mime_charset_alloc(const char *charset, size_t charset_len) {
    size_t base_len = charset_len;
    for (size_t i = 0; i < charset_len; i++) {
        if (charset[i] == '*') {
            base_len = i;
            break;
        }
    }
    PtnStringOperand operand = ptn_string_operand_borrowed_len(charset, base_len);
    char *resolved = ptn_iconv_resolve_encoding_alloc(operand);
    if (resolved != NULL) {
        return resolved;
    }
    return ptn_duplicate_string_len(charset, base_len);
}

enum {
    PTN_ICONV_MIME_WORD_APPENDED = 1,
    PTN_ICONV_MIME_WORD_SKIPPED = 2,
    PTN_ICONV_MIME_WORD_FAILED = 0
};

static int ptn_iconv_mime_append_decoded_word(
    PtnRuntime *runtime,
    PtnStringBuffer *output,
    const char *function_name,
    const char *target_encoding,
    const char *charset,
    size_t charset_len,
    unsigned char transfer_encoding,
    const char *encoded_text,
    size_t encoded_text_len,
    int continue_on_error,
    size_t line
) {
    PtnStringBuffer decoded;
    ptn_string_buffer_init(&decoded);
    if (transfer_encoding == 'q' || transfer_encoding == 'Q') {
        ptn_mb_mime_decode_q_text(&decoded, encoded_text, encoded_text_len);
    } else {
        ptn_mb_mime_decode_b_text(runtime, &decoded, encoded_text, encoded_text_len, line);
    }

    char *source_encoding = ptn_iconv_mime_charset_alloc(charset, charset_len);
    size_t converted_len = 0;
    int status = PTN_ICONV_CONVERT_OK;
    char *converted = ptn_iconv_convert_alloc(
        decoded.data,
        decoded.len,
        source_encoding,
        target_encoding,
        &status,
        &converted_len
    );
    if (converted == NULL) {
        if (!continue_on_error) {
            char message[128];
            int written = snprintf(
                message,
                sizeof(message),
                "%s(): Detected an illegal character in input string",
                function_name
            );
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_iconv_emit_conversion_notice(runtime, message, line);
        }
        free(source_encoding);
        free(decoded.data);
        return continue_on_error ? PTN_ICONV_MIME_WORD_SKIPPED : PTN_ICONV_MIME_WORD_FAILED;
    }
    ptn_string_buffer_append_len(output, converted, converted_len);
    free(converted);
    free(source_encoding);
    free(decoded.data);
    return PTN_ICONV_MIME_WORD_APPENDED;
}

static int ptn_iconv_mime_decode_operand(
    PtnRuntime *runtime,
    const char *function_name,
    PtnStringOperand input,
    int64_t mode,
    const char *target_encoding,
    size_t line,
    PtnStringBuffer *output
) {
    int strict = (mode & PTN_ICONV_MIME_DECODE_STRICT) != 0;
    int continue_on_error = (mode & PTN_ICONV_MIME_DECODE_CONTINUE_ON_ERROR) != 0;
    size_t i = 0;
    while (i < input.len) {
        size_t charset_start = 0;
        size_t charset_len = 0;
        size_t text_start = 0;
        size_t text_len = 0;
        size_t end_offset = 0;
        unsigned char transfer_encoding = 0;
        int valid_word = ptn_iconv_mime_parse_encoded_word(
            input.data,
            input.len,
            i,
            &charset_start,
            &charset_len,
            &transfer_encoding,
            &text_start,
            &text_len,
            &end_offset
        );
        if (!valid_word) {
            if ((unsigned char)input.data[i] >= 0x80) {
                if (continue_on_error) {
                    i++;
                    continue;
                }
                char message[128];
                int written = snprintf(
                    message,
                    sizeof(message),
                    "%s(): Detected an illegal character in input string",
                    function_name
                );
                if (written < 0 || (size_t)written >= sizeof(message)) {
                    ptn_abort_out_of_memory();
                }
                ptn_iconv_emit_conversion_notice(runtime, message, line);
                return 0;
            }
            int has_encoded_word_terminator = 0;
            if (i + 1 < input.len && input.data[i] == '=' && input.data[i + 1] == '?') {
                for (size_t scan = i + 2; scan + 1 < input.len; scan++) {
                    if (input.data[scan] == '?' && input.data[scan + 1] == '=') {
                        has_encoded_word_terminator = 1;
                        break;
                    }
                }
            }
            if (i + 1 < input.len && input.data[i] == '=' && input.data[i + 1] == '?' && !continue_on_error && has_encoded_word_terminator) {
                char message[96];
                int written = snprintf(message, sizeof(message), "%s(): Malformed string", function_name);
                if (written < 0 || (size_t)written >= sizeof(message)) {
                    ptn_abort_out_of_memory();
                }
                ptn_emit_warning(&runtime->diagnostics, message, line);
                return 0;
            }
            ptn_string_buffer_append_char(output, input.data[i++]);
            continue;
        }

        if (strict && end_offset + 1 < input.len && input.data[end_offset] == '=' && input.data[end_offset + 1] == '?') {
            output->len = 0;
            if (output->data != NULL) {
                output->data[0] = '\0';
            }
            ptn_string_buffer_append_len(output, input.data, input.len);
            return 1;
        }

        int word_result = ptn_iconv_mime_append_decoded_word(
            runtime,
            output,
            function_name,
            target_encoding,
            input.data + charset_start,
            charset_len,
            transfer_encoding,
            input.data + text_start,
            text_len,
            continue_on_error,
            line
        );
        if (word_result == PTN_ICONV_MIME_WORD_FAILED) {
            return 0;
        }
        i = end_offset;

        size_t whitespace_start = i;
        while (i < input.len) {
            unsigned char byte = (unsigned char)input.data[i];
            if (byte != ' ' && byte != '\t' && byte != '\r' && byte != '\n') {
                break;
            }
            i++;
        }
        if (i > whitespace_start) {
            size_t next_charset_start = 0;
            size_t next_charset_len = 0;
            size_t next_text_start = 0;
            size_t next_text_len = 0;
            size_t next_end_offset = 0;
            unsigned char next_transfer_encoding = 0;
            if (!ptn_iconv_mime_parse_encoded_word(
                    input.data,
                    input.len,
                    i,
                    &next_charset_start,
                    &next_charset_len,
                    &next_transfer_encoding,
                    &next_text_start,
                    &next_text_len,
                    &next_end_offset
                )) {
                if (word_result != PTN_ICONV_MIME_WORD_SKIPPED) {
                    ptn_string_buffer_append_len(output, input.data + whitespace_start, i - whitespace_start);
                }
            }
        }
    }
    return 1;
}

static PtnValue ptn_internal_iconv_mime_decode(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "iconv_mime_decode", 1, "string", args[0], line);
    int64_t mode = argc >= 2 ? ptn_value_to_integer(args[1]) : 0;
    int ok = 1;
    char *target_encoding = ptn_iconv_mime_target_encoding_alloc(
        runtime,
        "iconv_mime_decode",
        3,
        "encoding",
        argc >= 3 ? &args[2] : NULL,
        line,
        &ok
    );
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(input);
        free(target_encoding);
        return ptn_null();
    }
    if (!ok) {
        ptn_string_operand_free(input);
        free(target_encoding);
        return ptn_bool(0);
    }
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    int decoded = ptn_iconv_mime_decode_operand(
        runtime,
        "iconv_mime_decode",
        input,
        mode,
        target_encoding,
        line,
        &output
    );
    ptn_string_operand_free(input);
    free(target_encoding);
    if (!decoded) {
        free(output.data);
        return ptn_bool(0);
    }
    return ptn_owned_string_len(output.data, output.len);
}

static void ptn_iconv_mime_headers_store_value(
    PtnValue result,
    const char *name,
    size_t name_len,
    PtnValue value
) {
    PtnArrayKey key = ptn_array_string_key_len(name, name_len);
    PtnArrayEntry *entry = ptn_array_entry_for_key(result.as.array, key);
    if (entry == NULL) {
        ptn_array_set_entry(result.as.array, key, value);
        return;
    }
    ptn_array_key_free(key);
    PtnValue current = ptn_value_deref(entry->value);
    if (current.type == PTN_ARRAY) {
        int64_t index = (int64_t)current.as.array->len;
        ptn_array_set_entry(current.as.array, ptn_array_int_key(index), value);
        return;
    }
    PtnValue list = ptn_array_from_literal_entries(0, NULL);
    ptn_array_set_entry(list.as.array, ptn_array_int_key(0), ptn_value_clone_deref(entry->value));
    ptn_array_set_entry(list.as.array, ptn_array_int_key(1), value);
    ptn_value_destroy(&entry->value);
    entry->value = list;
}

static void ptn_iconv_mime_decode_header_line(
    PtnRuntime *runtime,
    PtnValue result,
    PtnStringOperand header,
    const char *target_encoding,
    int64_t mode,
    size_t line
) {
    size_t colon = 0;
    while (colon < header.len && header.data[colon] != ':') {
        colon++;
    }
    if (colon == 0 || colon >= header.len) {
        return;
    }
    size_t value_start = colon + 1;
    while (value_start < header.len && (header.data[value_start] == ' ' || header.data[value_start] == '\t')) {
        value_start++;
    }
    PtnStringOperand value = ptn_string_operand_borrowed_len(
        header.data + value_start,
        header.len - value_start
    );
    PtnStringBuffer decoded;
    ptn_string_buffer_init(&decoded);
    if (!ptn_iconv_mime_decode_operand(
            runtime,
            "iconv_mime_decode_headers",
            value,
            mode,
            target_encoding,
            line,
            &decoded
        )) {
        free(decoded.data);
        return;
    }
    ptn_iconv_mime_headers_store_value(
        result,
        header.data,
        colon,
        ptn_owned_string_len(decoded.data, decoded.len)
    );
}

static PtnValue ptn_internal_iconv_mime_decode_headers(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "iconv_mime_decode_headers", 1, "headers", args[0], line);
    int64_t mode = argc >= 2 ? ptn_value_to_integer(args[1]) : 0;
    int ok = 1;
    char *target_encoding = ptn_iconv_mime_target_encoding_alloc(
        runtime,
        "iconv_mime_decode_headers",
        3,
        "encoding",
        argc >= 3 ? &args[2] : NULL,
        line,
        &ok
    );
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(input);
        free(target_encoding);
        return ptn_null();
    }
    if (!ok) {
        ptn_string_operand_free(input);
        free(target_encoding);
        return ptn_bool(0);
    }

    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    PtnStringBuffer current;
    ptn_string_buffer_init(&current);
    size_t start = 0;
    while (start <= input.len) {
        size_t end = start;
        while (end < input.len && input.data[end] != '\n' && input.data[end] != '\r') {
            end++;
        }
        size_t next = end;
        if (next < input.len && input.data[next] == '\r') {
            next++;
        }
        if (next < input.len && input.data[next] == '\n') {
            next++;
        }
        if (end > start) {
            int continuation = input.data[start] == ' ' || input.data[start] == '\t';
            if (continuation && current.len > 0) {
                ptn_string_buffer_append_char(&current, ' ');
                size_t continuation_start = start;
                while (continuation_start < end &&
                       (input.data[continuation_start] == ' ' || input.data[continuation_start] == '\t')) {
                    continuation_start++;
                }
                ptn_string_buffer_append_len(&current, input.data + continuation_start, end - continuation_start);
            } else {
                if (current.len > 0) {
                    PtnStringOperand header = ptn_string_operand_borrowed_len(current.data, current.len);
                    ptn_iconv_mime_decode_header_line(runtime, result, header, target_encoding, mode, line);
                    current.len = 0;
                    current.data[0] = '\0';
                }
                ptn_string_buffer_append_len(&current, input.data + start, end - start);
            }
        }
        if (next >= input.len) {
            break;
        }
        start = next;
    }
    if (current.len > 0) {
        PtnStringOperand header = ptn_string_operand_borrowed_len(current.data, current.len);
        ptn_iconv_mime_decode_header_line(runtime, result, header, target_encoding, mode, line);
    }
    free(current.data);
    ptn_string_operand_free(input);
    free(target_encoding);
    return result;
}

static size_t ptn_iconv_mime_q_encoded_byte_len(unsigned char byte) {
    if (byte >= 33 && byte <= 126 && byte != '=' && byte != '?' && byte != '_') {
        return 1;
    }
    return 3;
}

static size_t ptn_iconv_mime_q_encoded_unit_len(const char *data, size_t len) {
    size_t encoded_len = 0;
    for (size_t i = 0; i < len; i++) {
        encoded_len += ptn_iconv_mime_q_encoded_byte_len((unsigned char)data[i]);
    }
    return encoded_len;
}

static void ptn_iconv_mime_append_q_encoded(PtnStringBuffer *output, const char *data, size_t len) {
    static const char hex[] = "0123456789ABCDEF";
    for (size_t i = 0; i < len; i++) {
        unsigned char byte = (unsigned char)data[i];
        if (byte >= 33 && byte <= 126 && byte != '=' && byte != '?' && byte != '_') {
            ptn_string_buffer_append_char(output, (char)byte);
        } else {
            char encoded[3] = { '=', hex[(byte >> 4) & 0x0f], hex[byte & 0x0f] };
            ptn_string_buffer_append_len(output, encoded, sizeof(encoded));
        }
    }
}

static size_t ptn_iconv_mime_q_source_unit_len(const char *data, size_t len, size_t offset) {
    size_t sequence_len = 0;
    if (ptn_mb_utf8_valid_sequence_len_at(data, len, offset, &sequence_len) && sequence_len > 0) {
        return sequence_len;
    }
    return 1;
}

static void ptn_iconv_mime_append_encoded_word_prefix(
    PtnStringBuffer *output,
    const char *output_charset,
    char scheme
) {
    ptn_string_buffer_append(output, "=?");
    ptn_string_buffer_append(output, output_charset);
    ptn_string_buffer_append_char(output, '?');
    ptn_string_buffer_append_char(output, scheme);
    ptn_string_buffer_append_char(output, '?');
}

static void ptn_iconv_mime_append_encoded_words(
    PtnRuntime *runtime,
    PtnStringBuffer *output,
    const char *field_name,
    size_t field_name_len,
    const char *output_charset,
    char scheme,
    const char *converted,
    size_t converted_len,
    int64_t line_length,
    PtnStringOperand line_break,
    size_t line
) {
    size_t prefix_len = field_name_len + 2;
    size_t word_prefix_len = 2 + strlen(output_charset) + 3;
    size_t word_suffix_len = 2;
    size_t limit = line_length > 0 ? (size_t)line_length : 76u;
    size_t offset = 0;
    int first_line = 1;

    while (first_line || offset < converted_len) {
        size_t line_prefix_len = first_line ? prefix_len : 1u;
        if (!first_line) {
            ptn_string_buffer_append_len(output, line_break.data, line_break.len);
            ptn_string_buffer_append_char(output, ' ');
        }
        if (first_line) {
            ptn_string_buffer_append_len(output, field_name, field_name_len);
            ptn_string_buffer_append(output, ": ");
        }
        ptn_iconv_mime_append_encoded_word_prefix(output, output_charset, scheme);

        size_t available = SIZE_MAX;
        if (limit > line_prefix_len + word_prefix_len + word_suffix_len) {
            available = limit - line_prefix_len - word_prefix_len - word_suffix_len;
        }
        if (available == 0) {
            available = SIZE_MAX;
        }

        size_t chunk_start = offset;
        size_t chunk_encoded_len = 0;
        while (offset < converted_len) {
            size_t unit_len = scheme == 'Q'
                ? ptn_iconv_mime_q_source_unit_len(converted, converted_len, offset)
                : 1u;
            size_t unit_encoded_len = scheme == 'Q'
                ? ptn_iconv_mime_q_encoded_unit_len(converted + offset, unit_len)
                : 4u * ((unit_len + 2u) / 3u);
            if (offset > chunk_start && chunk_encoded_len + unit_encoded_len > available) {
                break;
            }
            offset += unit_len;
            chunk_encoded_len += unit_encoded_len;
            if (chunk_encoded_len >= available) {
                break;
            }
        }

        if (scheme == 'Q') {
            ptn_iconv_mime_append_q_encoded(output, converted + chunk_start, offset - chunk_start);
        } else {
            PtnValue temp = ptn_owned_string_len(
                ptn_duplicate_string_len(converted + chunk_start, offset - chunk_start),
                offset - chunk_start
            );
            PtnValue encoded = ptn_internal_base64_encode(runtime, 1, &temp, line);
            PtnStringOperand encoded_string = ptn_value_to_string_operand(encoded);
            ptn_string_buffer_append_len(output, encoded_string.data, encoded_string.len);
            ptn_string_operand_free(encoded_string);
            ptn_value_destroy(&encoded);
            ptn_value_destroy(&temp);
        }
        ptn_string_buffer_append(output, "?=");
        first_line = 0;
    }
}

static PtnValue ptn_internal_iconv_mime_encode(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand field_name =
        ptn_internal_expect_string_arg(runtime, "iconv_mime_encode", 1, "field_name", args[0], line);
    PtnStringOperand field_value =
        ptn_internal_expect_string_arg(runtime, "iconv_mime_encode", 2, "field_value", args[1], line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(field_name);
        ptn_string_operand_free(field_value);
        return ptn_null();
    }

    char *input_charset = ptn_duplicate_string(ptn_iconv_effective_internal_encoding(runtime));
    char *output_charset = ptn_duplicate_string(ptn_iconv_effective_internal_encoding(runtime));
    int64_t line_length = 76;
    PtnStringOperand line_break = ptn_string_operand_borrowed_len("\n", 1);
    char scheme = 'B';
    if (argc >= 3) {
        PtnValue preferences = ptn_value_deref(args[2]);
        if (preferences.type == PTN_ARRAY) {
            for (size_t i = 0; i < preferences.as.array->len; i++) {
                PtnArrayEntry *entry = &preferences.as.array->entries[i];
                if (entry->key.type != PTN_ARRAY_KEY_STRING) {
                    continue;
                }
                PtnStringOperand preference_key =
                    ptn_string_operand_borrowed_len(entry->key.as.string, entry->key.string_len);
                int charset_preference =
                    ptn_string_operand_ascii_case_equal(preference_key, "input-charset") ||
                    ptn_string_operand_ascii_case_equal(preference_key, "output-charset");
                if (charset_preference) {
                    PtnStringOperand charset = ptn_value_to_string_operand(entry->value);
                    if (charset.len > 64) {
                        ptn_iconv_mime_emit_encoding_length_warning(runtime, "iconv_mime_encode", line);
                        ptn_string_operand_free(charset);
                        free(input_charset);
                        free(output_charset);
                        ptn_string_operand_free(field_name);
                        ptn_string_operand_free(field_value);
                        return ptn_bool(0);
                    }
                    char *copy = ptn_duplicate_string_len(charset.data, charset.len);
                    if (ptn_string_operand_ascii_case_equal(preference_key, "input-charset")) {
                        free(input_charset);
                        input_charset = copy;
                    } else {
                        free(output_charset);
                        output_charset = copy;
                    }
                    ptn_string_operand_free(charset);
                    continue;
                }
                if (ptn_string_operand_ascii_case_equal(preference_key, "scheme")) {
                    PtnStringOperand value = ptn_value_to_string_operand(entry->value);
                    if (value.len > 0 && (value.data[0] == 'q' || value.data[0] == 'Q')) {
                        scheme = 'Q';
                    } else {
                        scheme = 'B';
                    }
                    ptn_string_operand_free(value);
                    continue;
                }
                if (ptn_string_operand_ascii_case_equal(preference_key, "line-length")) {
                    line_length = ptn_value_to_integer(entry->value);
                    continue;
                }
                if (ptn_string_operand_ascii_case_equal(preference_key, "line-break-chars")) {
                    PtnStringOperand value = ptn_value_to_string_operand(entry->value);
                    if (line_break.owned != NULL) {
                        ptn_string_operand_free(line_break);
                    }
                    line_break = value;
                }
            }
        }
    }

    size_t converted_len = 0;
    int status = PTN_ICONV_CONVERT_OK;
    char *converted = ptn_iconv_convert_alloc(
        field_value.data,
        field_value.len,
        input_charset,
        output_charset,
        &status,
        &converted_len
    );
    if (converted == NULL) {
        ptn_iconv_emit_conversion_notice(
            runtime,
            status == PTN_ICONV_CONVERT_INCOMPLETE
                ? "iconv_mime_encode(): Detected an incomplete multibyte character in input string"
                : "iconv_mime_encode(): Detected an illegal character in input string",
            line
        );
        free(input_charset);
        free(output_charset);
        if (line_break.owned != NULL) {
            ptn_string_operand_free(line_break);
        }
        ptn_string_operand_free(field_name);
        ptn_string_operand_free(field_value);
        return ptn_bool(0);
    }
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    ptn_iconv_mime_append_encoded_words(
        runtime,
        &output,
        field_name.data,
        field_name.len,
        output_charset,
        scheme,
        converted,
        converted_len,
        line_length,
        line_break,
        line
    );
    free(converted);
    free(input_charset);
    free(output_charset);
    if (line_break.owned != NULL) {
        ptn_string_operand_free(line_break);
    }
    ptn_string_operand_free(field_name);
    ptn_string_operand_free(field_value);
    return ptn_owned_string_len(output.data, output.len);
}

static int ptn_mb_numeric_entity_map_apply(PtnValue map_value, uint32_t cp, uint64_t *mapped_out) {
    PtnValue resolved = ptn_value_deref(map_value);
    if (resolved.type != PTN_ARRAY) {
        *mapped_out = cp;
        return 1;
    }
    for (size_t i = 0; i + 3 < resolved.as.array->len; i += 4) {
        uint64_t start = (uint64_t)ptn_value_to_integer(resolved.as.array->entries[i].value);
        uint64_t end = (uint64_t)ptn_value_to_integer(resolved.as.array->entries[i + 1].value);
        uint64_t offset = (uint64_t)ptn_value_to_integer(resolved.as.array->entries[i + 2].value);
        uint64_t mask = (uint64_t)ptn_value_to_integer(resolved.as.array->entries[i + 3].value);
        uint64_t codepoint = (uint64_t)cp;
        if (codepoint >= start && codepoint <= end) {
            *mapped_out = (codepoint + offset) & mask;
            return 1;
        }
    }
    return 0;
}

static int ptn_mb_numeric_entity_map_allows(PtnValue map_value, uint32_t cp) {
    uint64_t mapped = 0;
    return ptn_mb_numeric_entity_map_apply(map_value, cp, &mapped);
}

static int ptn_mb_numeric_entity_map_validate(PtnRuntime *runtime, const char *function_name, PtnValue map_value) {
    PtnValue resolved = ptn_value_deref(map_value);
    if (resolved.type != PTN_ARRAY) {
        return 1;
    }
    if (resolved.as.array->len % 4 != 0) {
        char message[128];
        int written = snprintf(
            message,
            sizeof(message),
            "%s(): Argument #2 ($map) must have a multiple of 4 elements",
            function_name
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "ValueError", message);
        return 0;
    }
    for (size_t i = 0; i < resolved.as.array->len; i++) {
        if (ptn_value_deref(resolved.as.array->entries[i].value).type != PTN_INT) {
            char message[128];
            int written = snprintf(
                message,
                sizeof(message),
                "%s(): Argument #2 ($map) must only be composed of values of type int",
                function_name
            );
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_throw_exception(runtime, "ValueError", message);
            return 0;
        }
    }
    return 1;
}

static PtnValue ptn_internal_mb_encode_numericentity(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "mb_encode_numericentity", 1, "string", args[0], line);
    if (!ptn_mb_numeric_entity_map_validate(runtime, "mb_encode_numericentity", args[1])) {
        ptn_string_operand_free(input);
        return ptn_null();
    }
    const char *encoding = argc >= 3
        ? ptn_mb_encoding_from_value(runtime, "mb_encode_numericentity", 3, "encoding", args[2], line, ptn_mb_current_internal_encoding(runtime), 1)
        : ptn_mb_current_internal_encoding(runtime);
    int hex = argc >= 4 && ptn_is_truthy(args[3]);
    size_t utf8_len = 0;
    char *utf8 = encoding == NULL ? ptn_duplicate_string_len(input.data, input.len) : ptn_mb_operand_to_utf8(input, encoding, &utf8_len);
    if (encoding == NULL) {
        utf8_len = input.len;
    }
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    size_t offset = 0;
    while (offset < utf8_len) {
        size_t before = offset;
        uint32_t cp = 0;
        if (ptn_ascii_case_equal(encoding, "ASCII") && (unsigned char)utf8[offset] > 0x7f) {
            cp = UINT32_MAX;
            offset++;
        } else {
            ptn_mb_utf8_decode_one(utf8, utf8_len, &offset, &cp);
        }
        uint64_t mapped = 0;
        if (ptn_mb_numeric_entity_map_apply(args[1], cp, &mapped)) {
            if (hex) {
                ptn_string_buffer_append_format(&output, "&#x%llX;", (unsigned long long)mapped);
            } else {
                ptn_string_buffer_append_format(&output, "&#%llu;", (unsigned long long)mapped);
            }
        } else {
            ptn_string_buffer_append_len(&output, utf8 + before, offset - before);
        }
    }
    free(utf8);
    ptn_string_operand_free(input);
    return ptn_owned_string_len(output.data, output.len);
}

static PtnValue ptn_internal_mb_decode_numericentity(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "mb_decode_numericentity", 1, "string", args[0], line);
    if (!ptn_mb_numeric_entity_map_validate(runtime, "mb_decode_numericentity", args[1])) {
        ptn_string_operand_free(input);
        return ptn_null();
    }
    const char *encoding = argc >= 3
        ? ptn_mb_encoding_from_value(runtime, "mb_decode_numericentity", 3, "encoding", args[2], line, ptn_mb_current_internal_encoding(runtime), 1)
        : ptn_mb_current_internal_encoding(runtime);
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    for (size_t i = 0; i < input.len; i++) {
        if (input.data[i] == '&' && i + 3 < input.len && input.data[i + 1] == '#') {
            size_t cursor = i + 2;
            int hex = 0;
            if (cursor < input.len && (input.data[cursor] == 'x' || input.data[cursor] == 'X')) {
                hex = 1;
                cursor++;
            }
            uint32_t cp = 0;
            size_t digit_start = cursor;
            while (cursor < input.len && input.data[cursor] != ';') {
                int digit = hex ? ptn_hex_nibble((unsigned char)input.data[cursor]) :
                    (isdigit((unsigned char)input.data[cursor]) ? input.data[cursor] - '0' : -1);
                if (digit < 0) {
                    break;
                }
                cp = (uint32_t)(cp * (hex ? 16 : 10) + (uint32_t)digit);
                cursor++;
            }
            int has_semicolon = cursor < input.len && input.data[cursor] == ';';
            if (cursor > digit_start && ptn_mb_numeric_entity_map_allows(args[1], cp)) {
                ptn_mb_utf8_append_codepoint(&output, cp);
                i = has_semicolon ? cursor : cursor - 1;
                continue;
            }
        }
        ptn_string_buffer_append_char(&output, input.data[i]);
    }
    ptn_string_operand_free(input);
    return ptn_mb_string_from_utf8(output.data, output.len, encoding == NULL ? "UTF-8" : encoding);
}

static int ptn_mb_convert_variables_value(
    PtnRuntime *runtime,
    PtnValue *slot,
    const char *to_encoding,
    const char *from_encoding,
    size_t line,
    PtnMbCheckStack *stack
) {
    if (slot->type == PTN_REFERENCE) {
        return ptn_mb_convert_variables_value(
            runtime,
            &slot->as.reference->value,
            to_encoding,
            from_encoding,
            line,
            stack
        );
    }

    if (slot->type == PTN_ARRAY) {
        PtnArray *array = ptn_array_detach_value(slot);
        if (ptn_mb_check_stack_contains(stack, array)) {
            stack->saw_circular = 1;
            return 0;
        }
        ptn_mb_check_stack_push(stack, array);
        for (size_t i = 0; i < array->len; i++) {
            if (!ptn_mb_convert_variables_value(
                    runtime,
                    &array->entries[i].value,
                    to_encoding,
                    from_encoding,
                    line,
                    stack
                )) {
                stack->len--;
                return 0;
            }
        }
        stack->len--;
        return 1;
    }

    if (slot->type != PTN_STRING) {
        return 1;
    }

    size_t out_len = 0;
    char *out = ptn_mb_iconv_convert_alloc(
        (const char *)slot->as.string.data,
        slot->as.string.len,
        from_encoding,
        to_encoding,
        &out_len
    );
    PtnValue assigned = ptn_owned_string_len(out, out_len);
    ptn_value_destroy(slot);
    *slot = assigned;
    return 1;
}

static PtnValue ptn_internal_mb_convert_variables(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    const char *to_encoding = ptn_mb_encoding_from_value(runtime, "mb_convert_variables", 1, "to_encoding", args[0], line, NULL, 0);
    const char *from_encoding = argc >= 2
        ? ptn_mb_encoding_list_first_from_value(runtime, "mb_convert_variables", 2, "from_encoding", args[1], line, ptn_mb_current_internal_encoding(runtime))
        : ptn_mb_current_internal_encoding(runtime);
    if (to_encoding == NULL || from_encoding == NULL) {
        return ptn_bool(0);
    }
    PtnMbCheckStack recursion_stack = { NULL, 0, 0, 0 };
    for (size_t i = 2; i < argc; i++) {
        if (ptn_mb_value_has_recursive_array(args[i], &recursion_stack)) {
            ptn_emit_warning(&runtime->diagnostics, "mb_convert_variables(): Cannot convert recursively referenced values", line);
            ptn_mb_check_stack_free(&recursion_stack);
            return ptn_bool(0);
        }
    }
    ptn_mb_check_stack_free(&recursion_stack);
    for (size_t i = 2; i < argc; i++) {
        if (args[i].type != PTN_REFERENCE) {
            continue;
        }
        PtnValue current = ptn_value_deref(args[i]);
        PtnValue assigned;
        if (current.type == PTN_STRING) {
            size_t out_len = 0;
            char *out = ptn_mb_iconv_convert_alloc((const char *)current.as.string.data, current.as.string.len, from_encoding, to_encoding, &out_len);
            assigned = ptn_owned_string_len(out, out_len);
        } else if (current.type == PTN_ARRAY) {
            PtnMbCheckStack convert_stack = { NULL, 0, 0, 0 };
            assigned = ptn_mb_convert_encoding_value(
                runtime,
                current,
                to_encoding,
                from_encoding,
                ptn_mb_current_internal_encoding(runtime),
                line,
                0,
                &convert_stack
            );
            ptn_mb_check_stack_free(&convert_stack);
        } else {
            continue;
        }
        ptn_reference_assign(runtime, args[i].as.reference, assigned);
        ptn_value_destroy(&assigned);
    }
    return ptn_string(from_encoding);
}

static int ptn_ascii_is_letter(unsigned char byte) {
    return (byte >= 'A' && byte <= 'Z') || (byte >= 'a' && byte <= 'z');
}

static unsigned char ptn_ascii_upper(unsigned char byte) {
    if (byte >= 'a' && byte <= 'z') {
        return (unsigned char)(byte - ('a' - 'A'));
    }
    return byte;
}

static char ptn_soundex_code(unsigned char byte) {
    switch (ptn_ascii_upper(byte)) {
        case 'B':
        case 'F':
        case 'P':
        case 'V':
            return '1';
        case 'C':
        case 'G':
        case 'J':
        case 'K':
        case 'Q':
        case 'S':
        case 'X':
        case 'Z':
            return '2';
        case 'D':
        case 'T':
            return '3';
        case 'L':
            return '4';
        case 'M':
        case 'N':
            return '5';
        case 'R':
            return '6';
        default:
            return '\0';
    }
}

static int ptn_soundex_resets_previous(unsigned char byte) {
    switch (ptn_ascii_upper(byte)) {
        case 'A':
        case 'E':
        case 'I':
        case 'O':
        case 'U':
        case 'Y':
        case 'H':
        case 'W':
            return 1;
        default:
            return 0;
    }
}

static PtnValue ptn_internal_soundex(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "soundex", 1, "string", args[0], line);
    char *result = malloc(5);
    if (result == NULL) {
        ptn_abort_out_of_memory();
    }
    result[0] = '0';
    result[1] = '0';
    result[2] = '0';
    result[3] = '0';
    result[4] = '\0';

    size_t first = 0;
    while (first < string.len && !ptn_ascii_is_letter((unsigned char)string.data[first])) {
        first++;
    }
    if (first == string.len) {
        ptn_string_operand_free(string);
        return ptn_owned_string_len(result, 4);
    }

    result[0] = (char)ptn_ascii_upper((unsigned char)string.data[first]);
    char previous = ptn_soundex_code((unsigned char)string.data[first]);
    size_t output_len = 1;
    for (size_t i = first + 1; i < string.len && output_len < 4; i++) {
        unsigned char byte = (unsigned char)string.data[i];
        char code = ptn_soundex_code(byte);
        if (code == '\0') {
            if (ptn_soundex_resets_previous(byte)) {
                previous = '\0';
            }
            continue;
        }
        if (code != previous) {
            result[output_len++] = code;
        }
        previous = code;
    }

    ptn_string_operand_free(string);
    return ptn_owned_string_len(result, 4);
}

static void ptn_utf8_emit_deprecation(PtnRuntime *runtime, const char *function_name, size_t line) {
    char message[128];
    int written = snprintf(
        message,
        sizeof(message),
        "Function %s() is deprecated since 8.2, visit the php.net documentation for various alternatives",
        function_name
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_deprecation(&runtime->diagnostics, message, line);
}

static PtnValue ptn_internal_utf8_encode(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    ptn_utf8_emit_deprecation(runtime, "utf8_encode", line);
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "utf8_encode", 1, "string", args[0], line);
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    for (size_t i = 0; i < input.len; i++) {
        unsigned char byte = (unsigned char)input.data[i];
        if (byte < 0x80) {
            ptn_string_buffer_append_char(&output, (char)byte);
        } else {
            ptn_string_buffer_append_char(&output, (char)(0xc0 | (byte >> 6)));
            ptn_string_buffer_append_char(&output, (char)(0x80 | (byte & 0x3f)));
        }
    }
    ptn_string_operand_free(input);
    return ptn_owned_string_len(output.data, output.len);
}

static int ptn_utf8_decode_continuation(unsigned char byte) {
    return (byte & 0xc0) == 0x80;
}

static PtnValue ptn_internal_utf8_decode(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    ptn_utf8_emit_deprecation(runtime, "utf8_decode", line);
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "utf8_decode", 1, "string", args[0], line);
    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    for (size_t i = 0; i < input.len;) {
        unsigned char byte = (unsigned char)input.data[i];
        if (byte < 0x80) {
            ptn_string_buffer_append_char(&output, (char)byte);
            i++;
            continue;
        }

        size_t needed = 0;
        uint32_t codepoint = 0;
        uint32_t minimum = 0;
        if (byte >= 0xc2 && byte <= 0xdf) {
            needed = 1;
            codepoint = (uint32_t)(byte & 0x1f);
            minimum = 0x80;
        } else if (byte >= 0xe0 && byte <= 0xef) {
            needed = 2;
            codepoint = (uint32_t)(byte & 0x0f);
            minimum = 0x800;
        } else if (byte >= 0xf0 && byte <= 0xf4) {
            needed = 3;
            codepoint = (uint32_t)(byte & 0x07);
            minimum = 0x10000;
        } else {
            ptn_string_buffer_append_char(&output, '?');
            i++;
            continue;
        }

        size_t j = 0;
        int valid = 1;
        for (; j < needed; j++) {
            if (i + 1 + j >= input.len || !ptn_utf8_decode_continuation((unsigned char)input.data[i + 1 + j])) {
                valid = 0;
                break;
            }
            codepoint = (codepoint << 6) | (uint32_t)(input.data[i + 1 + j] & 0x3f);
        }
        if (!valid) {
            ptn_string_buffer_append_char(&output, '?');
            i += 1 + j;
            continue;
        }
        if (
            codepoint < minimum ||
            codepoint > 0x10ffff ||
            (codepoint >= 0xd800 && codepoint <= 0xdfff) ||
            codepoint > 0xff
        ) {
            ptn_string_buffer_append_char(&output, '?');
        } else {
            ptn_string_buffer_append_char(&output, (char)(unsigned char)codepoint);
        }
        i += needed + 1;
    }
    ptn_string_operand_free(input);
    return ptn_owned_string_len(output.data, output.len);
}

static int ptn_string_is_ascii_alnum(PtnStringOperand string) {
    for (size_t i = 0; i < string.len; i++) {
        unsigned char byte = (unsigned char)string.data[i];
        if (!((byte >= '0' && byte <= '9') ||
              (byte >= 'A' && byte <= 'Z') ||
              (byte >= 'a' && byte <= 'z'))) {
            return 0;
        }
    }
    return 1;
}

static void ptn_throw_string_incdec_empty(PtnRuntime *runtime, const char *function_name) {
    char message[96];
    int written = snprintf(
        message,
        sizeof(message),
        "%s(): Argument #1 ($string) must not be empty",
        function_name
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "ValueError", message);
}

static void ptn_throw_string_incdec_invalid(PtnRuntime *runtime, const char *function_name) {
    char message[128];
    int written = snprintf(
        message,
        sizeof(message),
        "%s(): Argument #1 ($string) must be composed only of alphanumeric ASCII characters",
        function_name
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "ValueError", message);
}

static void ptn_throw_string_decrement_range(PtnRuntime *runtime, PtnStringOperand string) {
    int needed = snprintf(
        NULL,
        0,
        "str_decrement(): Argument #1 ($string) \"%.*s\" is out of decrement range",
        (int)string.len,
        string.data
    );
    if (needed < 0) {
        ptn_abort_out_of_memory();
    }
    char *message = malloc((size_t)needed + 1);
    if (message == NULL) {
        ptn_abort_out_of_memory();
    }
    snprintf(
        message,
        (size_t)needed + 1,
        "str_decrement(): Argument #1 ($string) \"%.*s\" is out of decrement range",
        (int)string.len,
        string.data
    );
    ptn_throw_exception_owned_message(runtime, "ValueError", message);
}

static PtnValue ptn_internal_str_increment(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "str_increment", 1, "string", args[0], line);
    if (string.len == 0) {
        ptn_throw_string_incdec_empty(runtime, "str_increment");
        ptn_string_operand_free(string);
        return ptn_null();
    }
    if (!ptn_string_is_ascii_alnum(string)) {
        ptn_throw_string_incdec_invalid(runtime, "str_increment");
        ptn_string_operand_free(string);
        return ptn_null();
    }

    char *result = ptn_duplicate_string_len(string.data, string.len);
    size_t position = string.len - 1;
    int carry = 0;
    do {
        char byte = result[position];
        if (byte != 'z' && byte != 'Z' && byte != '9') {
            result[position]++;
            carry = 0;
        } else {
            carry = 1;
            if (byte == '9') {
                result[position] = '0';
            } else {
                result[position] = (char)(byte - 25);
            }
        }
    } while (carry && position-- > 0);

    if (carry) {
        char *expanded = malloc(string.len + 2);
        if (expanded == NULL) {
            ptn_abort_out_of_memory();
        }
        memcpy(expanded + 1, result, string.len);
        expanded[string.len + 1] = '\0';
        expanded[0] = result[0] == '0' ? '1' : result[0];
        free(result);
        ptn_string_operand_free(string);
        return ptn_owned_string_len(expanded, string.len + 1);
    }

    ptn_string_operand_free(string);
    return ptn_owned_string_len(result, strlen(result));
}

static PtnValue ptn_internal_str_decrement(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "str_decrement", 1, "string", args[0], line);
    if (string.len == 0) {
        ptn_throw_string_incdec_empty(runtime, "str_decrement");
        ptn_string_operand_free(string);
        return ptn_null();
    }
    if (!ptn_string_is_ascii_alnum(string)) {
        ptn_throw_string_incdec_invalid(runtime, "str_decrement");
        ptn_string_operand_free(string);
        return ptn_null();
    }
    if (string.data[0] == '0') {
        ptn_throw_string_decrement_range(runtime, string);
        ptn_string_operand_free(string);
        return ptn_null();
    }

    char *result = ptn_duplicate_string_len(string.data, string.len);
    size_t position = string.len - 1;
    int carry = 0;
    do {
        char byte = result[position];
        if (byte != 'a' && byte != 'A' && byte != '0') {
            result[position]--;
            carry = 0;
        } else {
            carry = 1;
            if (byte == '0') {
                result[position] = '9';
            } else {
                result[position] = (char)(byte + 25);
            }
        }
    } while (carry && position-- > 0);

    if (carry || (result[0] == '0' && string.len > 1)) {
        if (string.len == 1) {
            free(result);
            ptn_throw_string_decrement_range(runtime, string);
            ptn_string_operand_free(string);
            return ptn_null();
        }
        char *trimmed = malloc(string.len);
        if (trimmed == NULL) {
            ptn_abort_out_of_memory();
        }
        memcpy(trimmed, result + 1, string.len - 1);
        trimmed[string.len - 1] = '\0';
        free(result);
        ptn_string_operand_free(string);
        return ptn_owned_string_len(trimmed, string.len - 1);
    }

    ptn_string_operand_free(string);
    return ptn_owned_string_len(result, strlen(result));
}

static int ptn_metaphone_code(unsigned char byte) {
    switch ((unsigned char)toupper(byte)) {
        case 'A':
        case 'O':
        case 'U':
            return 1;
        case 'E':
        case 'I':
            return 9;
        case 'F':
        case 'J':
        case 'L':
        case 'M':
        case 'N':
        case 'R':
            return 2;
        case 'C':
        case 'G':
        case 'P':
        case 'S':
        case 'T':
            return 4;
        case 'Y':
            return 8;
        case 'B':
        case 'D':
        case 'H':
            return 16;
        default:
            return 0;
    }
}

static int ptn_metaphone_is_vowel(char byte) {
    return (ptn_metaphone_code((unsigned char)byte) & 1) != 0;
}

static int ptn_metaphone_affects_h(char byte) {
    return (ptn_metaphone_code((unsigned char)byte) & 4) != 0;
}

static int ptn_metaphone_makes_soft(char byte) {
    return (ptn_metaphone_code((unsigned char)byte) & 8) != 0;
}

static int ptn_metaphone_no_gh_to_f(char byte) {
    return (ptn_metaphone_code((unsigned char)byte) & 16) != 0;
}

static char ptn_metaphone_read(const char *word, size_t len, size_t index) {
    if (index >= len) {
        return '\0';
    }
    return (char)toupper((unsigned char)word[index]);
}

static int ptn_metaphone_append(char **buffer, size_t *len, size_t *capacity, char byte) {
    if (*len + 1 >= *capacity) {
        size_t new_capacity = *capacity == 0 ? 16 : *capacity * 2;
        char *grown = realloc(*buffer, new_capacity);
        if (grown == NULL) {
            ptn_abort_out_of_memory();
        }
        *buffer = grown;
        *capacity = new_capacity;
    }
    (*buffer)[(*len)++] = byte;
    (*buffer)[*len] = '\0';
    return 1;
}

static char *ptn_metaphone_string(const char *word, size_t word_len, int64_t max_phonemes, size_t *output_len_out) {
    size_t w_idx = 0;
    size_t p_idx = 0;
    size_t capacity = max_phonemes > 0 && max_phonemes < 1024 ? (size_t)max_phonemes + 3 : word_len * 2 + 3;
    if (capacity < 16) {
        capacity = 16;
    }
    char *output = calloc(capacity, 1);
    if (output == NULL) {
        ptn_abort_out_of_memory();
    }

    char curr_letter = '\0';
    while (w_idx < word_len) {
        curr_letter = word[w_idx];
        if (isalpha((unsigned char)curr_letter)) {
            break;
        }
        w_idx++;
    }
    if (w_idx >= word_len) {
        *output_len_out = 0;
        return output;
    }

    curr_letter = ptn_metaphone_read(word, word_len, w_idx);
    switch (curr_letter) {
        case 'A':
            if (ptn_metaphone_read(word, word_len, w_idx + 1) == 'E') {
                ptn_metaphone_append(&output, &p_idx, &capacity, 'E');
                w_idx += 2;
            } else {
                ptn_metaphone_append(&output, &p_idx, &capacity, 'A');
                w_idx++;
            }
            break;
        case 'G':
        case 'K':
        case 'P':
            if (ptn_metaphone_read(word, word_len, w_idx + 1) == 'N') {
                ptn_metaphone_append(&output, &p_idx, &capacity, 'N');
                w_idx += 2;
            }
            break;
        case 'W': {
            char next = ptn_metaphone_read(word, word_len, w_idx + 1);
            if (next == 'R') {
                ptn_metaphone_append(&output, &p_idx, &capacity, 'R');
                w_idx += 2;
            } else if (next == 'H' || ptn_metaphone_is_vowel(next)) {
                ptn_metaphone_append(&output, &p_idx, &capacity, 'W');
                w_idx += 2;
            }
            break;
        }
        case 'X':
            ptn_metaphone_append(&output, &p_idx, &capacity, 'S');
            w_idx++;
            break;
        case 'E':
        case 'I':
        case 'O':
        case 'U':
            ptn_metaphone_append(&output, &p_idx, &capacity, curr_letter);
            w_idx++;
            break;
        default:
            break;
    }

    for (; w_idx < word_len && (max_phonemes == 0 || p_idx < (size_t)max_phonemes); w_idx++) {
        curr_letter = word[w_idx];
        if (!isalpha((unsigned char)curr_letter)) {
            continue;
        }
        curr_letter = ptn_metaphone_read(word, word_len, w_idx);
        char prev_letter = w_idx > 0 ? ptn_metaphone_read(word, word_len, w_idx - 1) : '\0';
        if (curr_letter == prev_letter && curr_letter != 'C') {
            continue;
        }

        size_t skip = 0;
        switch (curr_letter) {
            case 'B':
                if (prev_letter != 'M') {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'B');
                }
                break;
            case 'C': {
                char next = ptn_metaphone_read(word, word_len, w_idx + 1);
                if (ptn_metaphone_makes_soft(next)) {
                    if (next == 'I' && ptn_metaphone_read(word, word_len, w_idx + 2) == 'A') {
                        ptn_metaphone_append(&output, &p_idx, &capacity, 'X');
                    } else if (prev_letter != 'S') {
                        ptn_metaphone_append(&output, &p_idx, &capacity, 'S');
                    }
                } else if (next == 'H') {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'X');
                    skip++;
                } else {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'K');
                }
                break;
            }
            case 'D':
                if (ptn_metaphone_read(word, word_len, w_idx + 1) == 'G' &&
                    ptn_metaphone_makes_soft(ptn_metaphone_read(word, word_len, w_idx + 2))) {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'J');
                    skip++;
                } else {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'T');
                }
                break;
            case 'G': {
                char next = ptn_metaphone_read(word, word_len, w_idx + 1);
                if (next == 'H') {
                    char look3 = w_idx >= 3 ? ptn_metaphone_read(word, word_len, w_idx - 3) : '\0';
                    char look4 = w_idx >= 4 ? ptn_metaphone_read(word, word_len, w_idx - 4) : '\0';
                    if (!ptn_metaphone_no_gh_to_f(look3) && look4 != 'H') {
                        ptn_metaphone_append(&output, &p_idx, &capacity, 'F');
                        skip++;
                    }
                } else if (next == 'N') {
                    char after = ptn_metaphone_read(word, word_len, w_idx + 2);
                    if (!(after == '\0' || !isalpha((unsigned char)after) ||
                          (after == 'E' && ptn_metaphone_read(word, word_len, w_idx + 3) == 'D'))) {
                        ptn_metaphone_append(&output, &p_idx, &capacity, 'K');
                    }
                } else if (ptn_metaphone_makes_soft(next) && prev_letter != 'G') {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'J');
                } else {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'K');
                }
                break;
            }
            case 'H':
                if (ptn_metaphone_is_vowel(ptn_metaphone_read(word, word_len, w_idx + 1)) &&
                    !ptn_metaphone_affects_h(prev_letter)) {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'H');
                }
                break;
            case 'K':
                if (prev_letter != 'C') {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'K');
                }
                break;
            case 'P':
                ptn_metaphone_append(
                    &output,
                    &p_idx,
                    &capacity,
                    ptn_metaphone_read(word, word_len, w_idx + 1) == 'H' ? 'F' : 'P'
                );
                break;
            case 'Q':
                ptn_metaphone_append(&output, &p_idx, &capacity, 'K');
                break;
            case 'S': {
                char next = ptn_metaphone_read(word, word_len, w_idx + 1);
                char after = ptn_metaphone_read(word, word_len, w_idx + 2);
                if (next == 'I' && (after == 'O' || after == 'A')) {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'X');
                } else if (next == 'H') {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'X');
                    skip++;
                } else {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'S');
                }
                break;
            }
            case 'T': {
                char next = ptn_metaphone_read(word, word_len, w_idx + 1);
                char after = ptn_metaphone_read(word, word_len, w_idx + 2);
                if (next == 'I' && (after == 'O' || after == 'A')) {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'X');
                } else if (next == 'H') {
                    ptn_metaphone_append(&output, &p_idx, &capacity, '0');
                    skip++;
                } else if (!(next == 'C' && after == 'H')) {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'T');
                }
                break;
            }
            case 'V':
                ptn_metaphone_append(&output, &p_idx, &capacity, 'F');
                break;
            case 'W':
                if (ptn_metaphone_is_vowel(ptn_metaphone_read(word, word_len, w_idx + 1))) {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'W');
                }
                break;
            case 'X':
                ptn_metaphone_append(&output, &p_idx, &capacity, 'K');
                ptn_metaphone_append(&output, &p_idx, &capacity, 'S');
                break;
            case 'Y':
                if (ptn_metaphone_is_vowel(ptn_metaphone_read(word, word_len, w_idx + 1))) {
                    ptn_metaphone_append(&output, &p_idx, &capacity, 'Y');
                }
                break;
            case 'Z':
                ptn_metaphone_append(&output, &p_idx, &capacity, 'S');
                break;
            case 'F':
            case 'J':
            case 'L':
            case 'M':
            case 'N':
            case 'R':
                ptn_metaphone_append(&output, &p_idx, &capacity, curr_letter);
                break;
            default:
                break;
        }
        w_idx += skip;
    }

    output[p_idx] = '\0';
    *output_len_out = p_idx;
    return output;
}

static PtnValue ptn_internal_metaphone(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "metaphone", 1, "string", args[0], line);
    int64_t max_phonemes = 0;
    if (argc >= 2) {
        max_phonemes = ptn_internal_expect_integer_arg(runtime, "metaphone", 2, "max_phonemes", args[1], line);
        if (max_phonemes < 0) {
            ptn_throw_exception(
                runtime,
                "ValueError",
                "metaphone(): Argument #2 ($max_phonemes) must be greater than or equal to 0"
            );
            ptn_string_operand_free(string);
            return ptn_null();
        }
    }

    size_t output_len = 0;
    char *output = ptn_metaphone_string(string.data, string.len, max_phonemes, &output_len);
    ptn_string_operand_free(string);
    return ptn_owned_string_len(output, output_len);
}

static int ptn_hebrev_is_hebrew(unsigned char byte) {
    return byte >= 224 && byte <= 250;
}

static int ptn_hebrev_is_blank(unsigned char byte) {
    return byte == ' ' || byte == '\t';
}

static int ptn_hebrev_is_newline(unsigned char byte) {
    return byte == '\n' || byte == '\r';
}

static char ptn_hebrev_flip_punctuation(char byte) {
    switch (byte) {
        case '(':
            return ')';
        case ')':
            return '(';
        case '[':
            return ']';
        case ']':
            return '[';
        case '{':
            return '}';
        case '}':
            return '{';
        case '<':
            return '>';
        case '>':
            return '<';
        case '\\':
            return '/';
        case '/':
            return '\\';
        default:
            return byte;
    }
}

static char *ptn_hebrev_string(const char *input, size_t len, int64_t max_chars, size_t *output_len_out) {
    char *hebrew = malloc(len + 1);
    char *broken = malloc(len + 1);
    if (hebrew == NULL || broken == NULL) {
        ptn_abort_out_of_memory();
    }

    size_t block_start = 0;
    size_t block_end = 0;
    size_t block_type = ptn_hebrev_is_hebrew((unsigned char)input[0]) ? 2 : 1;
    size_t target = len;
    hebrew[target] = '\0';

    while (1) {
        if (block_type == 2) {
            while (block_end < len - 1) {
                unsigned char next = (unsigned char)input[block_end + 1];
                if (!(ptn_hebrev_is_hebrew(next) || ptn_hebrev_is_blank(next) || ispunct(next) || next == '\n')) {
                    break;
                }
                block_end++;
            }
            for (size_t i = block_start; i <= block_end; i++) {
                hebrew[--target] = ptn_hebrev_flip_punctuation(input[i]);
            }
            block_type = 1;
        } else {
            while (block_end < len - 1) {
                unsigned char next = (unsigned char)input[block_end + 1];
                if (ptn_hebrev_is_hebrew(next) || next == '\n') {
                    break;
                }
                block_end++;
            }
            while ((ptn_hebrev_is_blank((unsigned char)input[block_end]) ||
                    ispunct((unsigned char)input[block_end])) &&
                   input[block_end] != '/' &&
                   input[block_end] != '-' &&
                   block_end > block_start) {
                block_end--;
            }
            size_t i = block_end + 1;
            while (i > block_start) {
                i--;
                hebrew[--target] = input[i];
            }
            block_type = 2;
        }
        block_start = block_end + 1;
        if (block_end >= len - 1) {
            break;
        }
        block_end = block_start;
    }

    size_t begin = len - 1;
    size_t end = len - 1;
    size_t out = 0;
    while (1) {
        int64_t char_count = 0;
        while ((max_chars == 0 || (max_chars > 0 && char_count < max_chars)) && begin > 0) {
            char_count++;
            begin--;
            if (ptn_hebrev_is_newline((unsigned char)hebrew[begin])) {
                while (begin > 0 && ptn_hebrev_is_newline((unsigned char)hebrew[begin - 1])) {
                    begin--;
                    char_count++;
                }
                break;
            }
        }
        if (max_chars >= 0 && char_count == max_chars) {
            int64_t new_char_count = char_count;
            size_t new_begin = begin;
            while (new_char_count > 0) {
                if (ptn_hebrev_is_blank((unsigned char)hebrew[new_begin]) ||
                    ptn_hebrev_is_newline((unsigned char)hebrew[new_begin])) {
                    break;
                }
                new_begin++;
                new_char_count--;
            }
            if (new_char_count > 0) {
                begin = new_begin;
            }
        }

        size_t orig_begin = begin;
        if (ptn_hebrev_is_blank((unsigned char)hebrew[begin])) {
            hebrew[begin] = '\n';
        }
        while (begin <= end && ptn_hebrev_is_newline((unsigned char)hebrew[begin])) {
            begin++;
        }
        for (size_t i = begin; i <= end; i++) {
            broken[out++] = hebrew[i];
        }
        for (size_t i = orig_begin; i <= end && ptn_hebrev_is_newline((unsigned char)hebrew[i]); i++) {
            broken[out++] = hebrew[i];
        }

        begin = orig_begin;
        if (begin == 0) {
            broken[out] = '\0';
            break;
        }
        begin--;
        end = begin;
    }

    free(hebrew);
    *output_len_out = out;
    return broken;
}

static PtnValue ptn_internal_hebrev(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand string = ptn_internal_expect_string_arg(runtime, "hebrev", 1, "string", args[0], line);
    if (string.len == 0) {
        ptn_string_operand_free(string);
        return ptn_string("");
    }
    int64_t max_chars = argc >= 2
        ? ptn_internal_expect_integer_arg(runtime, "hebrev", 2, "max_chars", args[1], line)
        : 0;
    size_t output_len = 0;
    char *output = ptn_hebrev_string(string.data, string.len, max_chars, &output_len);
    ptn_string_operand_free(string);
    return ptn_owned_string_len(output, output_len);
}

static PtnValue ptn_internal_set_time_limit(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)argc;
    (void)line;
    (void)ptn_value_to_integer(args[0]);
    return ptn_bool(1);
}

static PtnValue ptn_internal_sleep(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    int64_t seconds = ptn_internal_expect_integer_arg(runtime, "sleep", 1, "seconds", args[0], line);
    if (seconds < 0) {
        ptn_throw_exception(runtime, "ValueError", "sleep(): Argument #1 ($seconds) must be greater than or equal to 0");
        return ptn_null();
    }
    while (seconds > 0) {
        unsigned int chunk = seconds > (int64_t)UINT_MAX ? UINT_MAX : (unsigned int)seconds;
        unsigned int remaining = sleep(chunk);
        if (remaining != 0) {
            return ptn_int((int64_t)remaining + (seconds - (int64_t)chunk));
        }
        seconds -= (int64_t)chunk;
    }
    return ptn_int(0);
}

static PtnValue ptn_internal_usleep(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    int64_t microseconds = ptn_internal_expect_integer_arg(runtime, "usleep", 1, "microseconds", args[0], line);
    if (microseconds < 0) {
        ptn_throw_exception(runtime, "ValueError", "usleep(): Argument #1 ($microseconds) must be greater than or equal to 0");
        return ptn_null();
    }
    if (microseconds > 0) {
        struct timespec requested;
        requested.tv_sec = (time_t)(microseconds / 1000000);
        requested.tv_nsec = (long)((microseconds % 1000000) * 1000);
        while (nanosleep(&requested, &requested) != 0) {
            if (errno != EINTR) {
                break;
            }
        }
    }
    return ptn_null();
}

static int64_t ptn_synthetic_memory_peak_usage = 1048576;

static PtnValue ptn_internal_memory_get_usage(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)line;
    if (argc >= 1) {
        (void)ptn_is_truthy(args[0]);
    }
    return ptn_int(1048576);
}

static PtnValue ptn_internal_memory_get_peak_usage(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)line;
    if (argc >= 1) {
        (void)ptn_is_truthy(args[0]);
    }
    if (ptn_synthetic_memory_peak_usage <= INT64_MAX - 1024) {
        ptn_synthetic_memory_peak_usage += 1024;
    }
    return ptn_int(ptn_synthetic_memory_peak_usage);
}

static PtnValue ptn_internal_memory_reset_peak_usage(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)argc;
    (void)args;
    (void)line;
    ptn_synthetic_memory_peak_usage = 1048576;
    return ptn_null();
}

typedef struct {
    PtnValue *items;
    size_t len;
    size_t capacity;
} PtnGcMarkStack;

/* Avoid native stack exhaustion while broad GC collection remains bounded. */
#define PTN_GC_LARGE_OBJECT_SWEEP_LIMIT 65536

static void ptn_gc_mark_stack_push(PtnGcMarkStack *stack, PtnValue value) {
    if (stack == NULL) {
        return;
    }
    if (stack->len == stack->capacity) {
        size_t new_capacity = stack->capacity == 0 ? 64 : stack->capacity * 2;
        if (new_capacity < stack->capacity || new_capacity > SIZE_MAX / sizeof(PtnValue)) {
            ptn_abort_out_of_memory();
        }
        PtnValue *new_items = realloc(stack->items, new_capacity * sizeof(PtnValue));
        if (new_items == NULL) {
            ptn_abort_out_of_memory();
        }
        stack->items = new_items;
        stack->capacity = new_capacity;
    }
    stack->items[stack->len++] = value;
}

static void ptn_gc_mark_symbol_table(PtnGcMarkStack *stack, PtnSymbolTable *symbols) {
    if (symbols == NULL) {
        return;
    }
    for (size_t i = 0; i < symbols->len; i++) {
        ptn_gc_mark_stack_push(stack, symbols->items[i].value);
    }
}

static void ptn_gc_mark_runtime_frame_roots(PtnGcMarkStack *stack, PtnRuntime *runtime) {
    if (stack == NULL || runtime == NULL) {
        return;
    }
    ptn_gc_mark_symbol_table(stack, &runtime->symbols);
    if (runtime->call_frame != NULL) {
        for (size_t i = 0; i < runtime->call_frame->argc; i++) {
            ptn_gc_mark_stack_push(stack, runtime->call_frame->args[i]);
        }
        if (runtime->call_frame->has_current_closure) {
            ptn_gc_mark_stack_push(stack, runtime->call_frame->current_closure);
        }
    }
    for (size_t i = 0; i < runtime->temporary_roots_len; i++) {
        ptn_gc_mark_stack_push(stack, runtime->temporary_roots[i]);
    }
}

static void ptn_gc_mark_trace_frame_runtime_roots(PtnGcMarkStack *stack, PtnTraceFrame *frame) {
    for (PtnTraceFrame *cursor = frame; cursor != NULL; cursor = cursor->previous) {
        if (cursor->has_receiver) {
            ptn_gc_mark_stack_push(stack, cursor->receiver);
        }
        for (size_t i = 0; i < cursor->argc; i++) {
            ptn_gc_mark_stack_push(stack, cursor->args[i]);
        }
        ptn_gc_mark_runtime_frame_roots(stack, cursor->runtime);
    }
}

static void ptn_gc_mark_static_locals(PtnGcMarkStack *stack, PtnRuntime *root) {
    if (root == NULL) {
        return;
    }
    for (size_t i = 0; i < root->static_local_slots_len; i++) {
        PtnReference *reference = root->static_local_slots[i].reference;
        if (reference != NULL) {
            ptn_gc_mark_stack_push(stack, ptn_reference_value(reference));
        }
    }
}

static PtnValue ptn_gc_borrowed_array_value(PtnArray *array) {
    PtnValue value = ptn_null();
    value.type = PTN_ARRAY;
    value.owned = 0;
    value.as.array = array;
    return value;
}

static size_t ptn_runtime_next_gc_mark_epoch(PtnRuntime *root) {
    if (root == NULL) {
        return 0;
    }
    if (root->gc_mark_epoch == SIZE_MAX) {
        root->gc_mark_epoch = 0;
    }
    root->gc_mark_epoch++;
    if (root->gc_mark_epoch == 0) {
        root->gc_mark_epoch = 1;
    }
    return root->gc_mark_epoch;
}

static void ptn_gc_mark_weak_map_values(PtnGcMarkStack *stack, PtnObject *object);

static int ptn_gc_object_has_array_backed_native_storage(PtnObject *object) {
    return object != NULL &&
        (
            ptn_declared_class_is_same_or_descendant(object->class_name, "ArrayIterator") ||
            ptn_declared_class_is_same_or_descendant(object->class_name, "RecursiveArrayIterator") ||
            ptn_declared_class_is_same_or_descendant(object->class_name, "ArrayObject") ||
            ptn_declared_class_is_same_or_descendant(object->class_name, "SplFixedArray")
        );
}

static void ptn_gc_mark_object_native_values(PtnGcMarkStack *stack, PtnObject *object) {
    if (stack == NULL || object == NULL || object->native_data == NULL) {
        return;
    }
    if (ptn_internal_class_name_is_fiber(object->class_name)) {
        PtnFiberData *data = (PtnFiberData *)object->native_data;
        ptn_gc_mark_stack_push(stack, data->callback);
        ptn_gc_mark_stack_push(stack, data->return_value);
        ptn_gc_mark_stack_push(stack, data->suspension_trace);
        ptn_gc_mark_stack_push(stack, data->suspend_value);
        ptn_gc_mark_stack_push(stack, data->resume_value);
        for (size_t i = 0; i < data->entry_argc; i++) {
            ptn_gc_mark_stack_push(stack, data->entry_args[i]);
        }
#if !defined(_WIN32)
        ptn_gc_mark_trace_frame_runtime_roots(stack, data->suspended_trace_frame);
#endif
        return;
    }
    if (ptn_declared_class_is_same_or_descendant(object->class_name, "ArrayIterator") ||
        ptn_declared_class_is_same_or_descendant(object->class_name, "RecursiveArrayIterator")) {
        PtnArrayIteratorData *data = (PtnArrayIteratorData *)object->native_data;
        ptn_gc_mark_stack_push(stack, data->storage);
        return;
    }
    if (ptn_declared_class_is_same_or_descendant(object->class_name, "ArrayObject")) {
        PtnArrayObjectData *data = (PtnArrayObjectData *)object->native_data;
        ptn_gc_mark_stack_push(stack, data->storage);
        return;
    }
    if (ptn_declared_class_is_same_or_descendant(object->class_name, "SplFixedArray")) {
        PtnSplFixedArrayData *data = (PtnSplFixedArrayData *)object->native_data;
        ptn_gc_mark_stack_push(stack, data->storage);
    }
}

static void ptn_gc_mark_reachable_values(PtnGcMarkStack *stack, size_t epoch) {
    if (stack == NULL || epoch == 0) {
        return;
    }
    while (stack->len > 0) {
        PtnValue value = stack->items[stack->len - 1];
        stack->len--;
        if (value.type == PTN_REFERENCE) {
            PtnReference *reference = value.as.reference;
            if (reference == NULL || reference->gc_mark_epoch == epoch) {
                continue;
            }
            reference->gc_mark_epoch = epoch;
            ptn_gc_mark_stack_push(stack, reference->value);
            continue;
        }
        if (value.type == PTN_ARRAY) {
            PtnArray *array = value.as.array;
            if (array == NULL || array->gc_mark_epoch == epoch) {
                continue;
            }
            array->gc_mark_epoch = epoch;
            for (size_t i = 0; i < array->len; i++) {
                ptn_gc_mark_stack_push(stack, array->entries[i].value);
            }
            continue;
        }
        if (value.type == PTN_OBJECT) {
            PtnObject *object = value.as.object;
            if (object == NULL || object->gc_mark_epoch == epoch) {
                continue;
            }
            object->gc_mark_epoch = epoch;
            ptn_gc_mark_stack_push(stack, ptn_gc_borrowed_array_value(object->properties));
            ptn_gc_mark_stack_push(stack, object->lazy_initializer);
            ptn_gc_mark_stack_push(stack, object->lazy_proxy_instance);
            ptn_gc_mark_weak_map_values(stack, object);
            ptn_gc_mark_object_native_values(stack, object);
            continue;
        }
        if (value.type == PTN_CLOSURE) {
            PtnClosure *closure = value.as.closure;
            if (closure == NULL || closure->gc_mark_epoch == epoch) {
                continue;
            }
            closure->gc_mark_epoch = epoch;
            ptn_gc_mark_symbol_table(stack, &closure->captures);
            if (closure->has_wrapped_callable) {
                ptn_gc_mark_stack_push(stack, closure->wrapped_callable);
            }
        }
    }
}

static int ptn_gc_object_has_opaque_native_data(PtnObject *object) {
    if (object == NULL || object->native_data == NULL) {
        return 0;
    }
    if (ptn_internal_class_name_is_fiber(object->class_name)) {
        return 0;
    }
    if (ptn_gc_object_has_array_backed_native_storage(object)) {
        return 0;
    }
    return object->native_data_free != ptn_spl_object_storage_data_free;
}

static size_t ptn_gc_count_unreachable_contained_values_in_value(
    PtnValue value,
    size_t root_epoch,
    size_t counted_epoch,
    size_t depth
);
static size_t ptn_gc_count_unreachable_contained_values_in_value_ex(
    PtnValue value,
    size_t root_epoch,
    size_t counted_epoch,
    size_t depth,
    size_t skip_array_count_depth
);
static size_t ptn_gc_count_unreachable_contained_values_in_object_properties(
    PtnObject *object,
    size_t root_epoch,
    size_t counted_epoch
);
static size_t ptn_gc_count_unreachable_contained_values_in_object_native_values(
    PtnObject *object,
    size_t root_epoch,
    size_t counted_epoch,
    size_t depth
);

static size_t ptn_gc_count_unreachable_contained_values_in_symbol_table(
    PtnSymbolTable *symbols,
    size_t root_epoch,
    size_t counted_epoch,
    size_t depth
) {
    if (symbols == NULL || root_epoch == 0 || counted_epoch == 0 || depth > 1024) {
        return 0;
    }
    size_t count = 0;
    for (size_t i = 0; i < symbols->len; i++) {
        size_t nested = ptn_gc_count_unreachable_contained_values_in_value(
            symbols->items[i].value,
            root_epoch,
            counted_epoch,
            depth + 1
        );
        if (count > SIZE_MAX - nested) {
            ptn_abort_out_of_memory();
        }
        count += nested;
    }
    return count;
}

static size_t ptn_gc_count_unreachable_contained_values_in_value_ex(
    PtnValue value,
    size_t root_epoch,
    size_t counted_epoch,
    size_t depth,
    size_t skip_array_count_depth
) {
    if (root_epoch == 0 || counted_epoch == 0 || depth > 1024) {
        return 0;
    }
    if (value.type == PTN_REFERENCE) {
        PtnReference *reference = value.as.reference;
        if (
            reference == NULL ||
            reference->gc_mark_epoch == root_epoch ||
            reference->gc_mark_epoch == counted_epoch
        ) {
            return 0;
        }
        int consumes_pending_array_cycle =
            reference->value.type == PTN_ARRAY &&
            reference->value.as.array != NULL &&
            ptn_array_count_reference(reference->value.as.array, reference, 0) > 0;
        reference->gc_mark_epoch = counted_epoch;
        size_t nested = ptn_gc_count_unreachable_contained_values_in_value_ex(
            reference->value,
            root_epoch,
            counted_epoch,
            depth + 1,
            skip_array_count_depth
        );
        if (consumes_pending_array_cycle && ptn_pending_array_cycle_collections > 0) {
            ptn_pending_array_cycle_collections--;
        }
        return nested;
    }
    if (value.type == PTN_ARRAY) {
        PtnArray *array = value.as.array;
        if (
            array == NULL ||
            array->gc_mark_epoch == root_epoch ||
            array->gc_mark_epoch == counted_epoch
        ) {
            return 0;
        }
        array->gc_mark_epoch = counted_epoch;

        size_t nested_skip_array_count_depth =
            skip_array_count_depth == 0 ? 0 : skip_array_count_depth - 1;
        size_t count = skip_array_count_depth == 0 ? 1 : 0;
        for (size_t i = 0; i < array->len; i++) {
            size_t nested = ptn_gc_count_unreachable_contained_values_in_value_ex(
                array->entries[i].value,
                root_epoch,
                counted_epoch,
                depth + 1,
                nested_skip_array_count_depth
            );
            if (count > SIZE_MAX - nested) {
                ptn_abort_out_of_memory();
            }
            count += nested;
        }
        return count;
    }
    if (value.type == PTN_OBJECT) {
        PtnObject *object = value.as.object;
        if (
            object == NULL ||
            object->refcount == 0 ||
            ptn_gc_object_has_opaque_native_data(object) ||
            object->gc_mark_epoch == root_epoch ||
            object->gc_mark_epoch == counted_epoch
        ) {
            return 0;
        }
        object->gc_mark_epoch = counted_epoch;
        size_t count = 1;
        size_t properties = ptn_gc_count_unreachable_contained_values_in_object_properties(
            object,
            root_epoch,
            counted_epoch
        );
        if (count > SIZE_MAX - properties) {
            ptn_abort_out_of_memory();
        }
        count += properties;
        size_t native_values = ptn_gc_count_unreachable_contained_values_in_object_native_values(
            object,
            root_epoch,
            counted_epoch,
            depth + 1
        );
        if (count > SIZE_MAX - native_values) {
            ptn_abort_out_of_memory();
        }
        return count + native_values;
    }
    if (value.type != PTN_CLOSURE || value.as.closure == NULL) {
        return 0;
    }

    PtnClosure *closure = value.as.closure;
    if (
        closure->gc_mark_epoch == root_epoch ||
        closure->gc_mark_epoch == counted_epoch
    ) {
        return 0;
    }
    closure->gc_mark_epoch = counted_epoch;

    size_t count = 1;
    size_t captures = ptn_gc_count_unreachable_contained_values_in_symbol_table(
        &closure->captures,
        root_epoch,
        counted_epoch,
        depth + 1
    );
    if (count > SIZE_MAX - captures) {
        ptn_abort_out_of_memory();
    }
    count += captures;
    if (closure->has_wrapped_callable) {
        size_t wrapped = ptn_gc_count_unreachable_contained_values_in_value_ex(
            closure->wrapped_callable,
            root_epoch,
            counted_epoch,
            depth + 1,
            skip_array_count_depth
        );
        if (count > SIZE_MAX - wrapped) {
            ptn_abort_out_of_memory();
        }
        count += wrapped;
    }
    return count;
}

static size_t ptn_gc_count_unreachable_contained_values_in_value(
    PtnValue value,
    size_t root_epoch,
    size_t counted_epoch,
    size_t depth
) {
    return ptn_gc_count_unreachable_contained_values_in_value_ex(
        value,
        root_epoch,
        counted_epoch,
        depth,
        0
    );
}

static size_t ptn_gc_count_unreachable_contained_values_in_object_properties(
    PtnObject *object,
    size_t root_epoch,
    size_t counted_epoch
) {
    if (object == NULL || object->properties == NULL) {
        return 0;
    }
    size_t count = 0;
    for (size_t i = 0; i < object->properties->len; i++) {
        PtnArrayEntry *entry = &object->properties->entries[i];
        const PtnObjectPropertyMetadata *metadata = entry->key.type == PTN_ARRAY_KEY_STRING
            ? ptn_object_property_metadata(object, entry->key.as.string)
            : NULL;
        size_t skip_array_count_depth =
            ptn_object_metadata_is_spl_object_storage_storage(metadata) ? 2 : 0;
        size_t nested = ptn_gc_count_unreachable_contained_values_in_value_ex(
            entry->value,
            root_epoch,
            counted_epoch,
            0,
            skip_array_count_depth
        );
        if (count > SIZE_MAX - nested) {
            ptn_abort_out_of_memory();
        }
        count += nested;
    }
    return count;
}

static size_t ptn_gc_count_unreachable_contained_values_in_object_native_values(
    PtnObject *object,
    size_t root_epoch,
    size_t counted_epoch,
    size_t depth
) {
    if (object == NULL || object->native_data == NULL || depth > 1024) {
        return 0;
    }
    PtnValue values[6] = { ptn_null(), ptn_null(), ptn_null(), ptn_null(), ptn_null(), ptn_null() };
    size_t values_len = 0;
    if (ptn_internal_class_name_is_fiber(object->class_name)) {
        PtnFiberData *data = (PtnFiberData *)object->native_data;
        values[values_len++] = data->callback;
        values[values_len++] = data->return_value;
        values[values_len++] = data->suspension_trace;
        values[values_len++] = data->suspend_value;
        values[values_len++] = data->resume_value;
    } else if (
        ptn_declared_class_is_same_or_descendant(object->class_name, "ArrayIterator") ||
        ptn_declared_class_is_same_or_descendant(object->class_name, "RecursiveArrayIterator")
    ) {
        PtnArrayIteratorData *data = (PtnArrayIteratorData *)object->native_data;
        values[values_len++] = data->storage;
    } else if (ptn_declared_class_is_same_or_descendant(object->class_name, "ArrayObject")) {
        PtnArrayObjectData *data = (PtnArrayObjectData *)object->native_data;
        values[values_len++] = data->storage;
    } else if (ptn_declared_class_is_same_or_descendant(object->class_name, "SplFixedArray")) {
        PtnSplFixedArrayData *data = (PtnSplFixedArrayData *)object->native_data;
        values[values_len++] = data->storage;
    } else {
        return 0;
    }
    size_t count = 0;
    for (size_t i = 0; i < values_len; i++) {
        size_t nested = ptn_gc_count_unreachable_contained_values_in_value_ex(
            values[i],
            root_epoch,
            counted_epoch,
            depth + 1,
            0
        );
        if (count > SIZE_MAX - nested) {
            ptn_abort_out_of_memory();
        }
        count += nested;
    }
    if (ptn_internal_class_name_is_fiber(object->class_name)) {
        PtnFiberData *data = (PtnFiberData *)object->native_data;
        for (size_t i = 0; i < data->entry_argc; i++) {
            size_t nested = ptn_gc_count_unreachable_contained_values_in_value_ex(
                data->entry_args[i],
                root_epoch,
                counted_epoch,
                depth + 1,
                0
            );
            if (count > SIZE_MAX - nested) {
                ptn_abort_out_of_memory();
            }
            count += nested;
        }
    }
    return count;
}

typedef struct {
    PtnObject **objects;
    size_t len;
    size_t capacity;
    int cyclic;
} PtnGcObjectComponent;

typedef struct {
    PtnGcObjectComponent *items;
    size_t len;
    size_t capacity;
} PtnGcObjectComponents;

static PtnGcObjectComponent *ptn_gc_object_components_push(PtnGcObjectComponents *components) {
    if (components == NULL) {
        return NULL;
    }
    if (components->len == components->capacity) {
        size_t new_capacity = components->capacity == 0 ? 4 : components->capacity * 2;
        if (new_capacity < components->capacity ||
            new_capacity > SIZE_MAX / sizeof(PtnGcObjectComponent)) {
            ptn_abort_out_of_memory();
        }
        PtnGcObjectComponent *new_items = realloc(
            components->items,
            new_capacity * sizeof(PtnGcObjectComponent)
        );
        if (new_items == NULL) {
            ptn_abort_out_of_memory();
        }
        components->items = new_items;
        components->capacity = new_capacity;
    }
    PtnGcObjectComponent *component = &components->items[components->len++];
    component->objects = NULL;
    component->len = 0;
    component->capacity = 0;
    component->cyclic = 0;
    return component;
}

static void ptn_gc_object_component_push(PtnGcObjectComponent *component, PtnObject *object) {
    if (component == NULL || object == NULL) {
        return;
    }
    if (component->len == component->capacity) {
        size_t new_capacity = component->capacity == 0 ? 4 : component->capacity * 2;
        if (new_capacity < component->capacity ||
            new_capacity > SIZE_MAX / sizeof(PtnObject *)) {
            ptn_abort_out_of_memory();
        }
        PtnObject **new_objects = realloc(
            component->objects,
            new_capacity * sizeof(PtnObject *)
        );
        if (new_objects == NULL) {
            ptn_abort_out_of_memory();
        }
        component->objects = new_objects;
        component->capacity = new_capacity;
    }
    ptn_object_retain(object);
    component->objects[component->len++] = object;
}

static void ptn_gc_object_components_release(PtnGcObjectComponents *components) {
    if (components == NULL) {
        return;
    }
    for (size_t i = 0; i < components->len; i++) {
        PtnGcObjectComponent *component = &components->items[i];
        for (size_t j = 0; j < component->len; j++) {
            ptn_object_release(component->objects[j]);
        }
        free(component->objects);
        component->objects = NULL;
        component->len = 0;
        component->capacity = 0;
    }
    free(components->items);
    components->items = NULL;
    components->len = 0;
    components->capacity = 0;
}

static void ptn_gc_mark_unreachable_destructor_component_value(
    PtnGcObjectComponent *component,
    PtnValue value,
    size_t root_epoch,
    size_t component_epoch,
    size_t depth
);

static void ptn_gc_mark_unreachable_destructor_component_array(
    PtnGcObjectComponent *component,
    PtnArray *array,
    size_t root_epoch,
    size_t component_epoch,
    size_t depth
) {
    if (
        array == NULL ||
        depth > 1024 ||
        array->gc_mark_epoch == root_epoch ||
        array->gc_mark_epoch == component_epoch
    ) {
        return;
    }
    array->gc_mark_epoch = component_epoch;
    for (size_t i = 0; i < array->len; i++) {
        ptn_gc_mark_unreachable_destructor_component_value(
            component,
            array->entries[i].value,
            root_epoch,
            component_epoch,
            depth + 1
        );
    }
}

static void ptn_gc_mark_unreachable_destructor_component_symbol_table(
    PtnGcObjectComponent *component,
    PtnSymbolTable *symbols,
    size_t root_epoch,
    size_t component_epoch,
    size_t depth
) {
    if (symbols == NULL || depth > 1024) {
        return;
    }
    for (size_t i = 0; i < symbols->len; i++) {
        ptn_gc_mark_unreachable_destructor_component_value(
            component,
            symbols->items[i].value,
            root_epoch,
            component_epoch,
            depth + 1
        );
    }
}

static void ptn_gc_mark_unreachable_destructor_component_object_native_values(
    PtnGcObjectComponent *component,
    PtnObject *object,
    size_t root_epoch,
    size_t component_epoch,
    size_t depth
) {
    if (object == NULL || object->native_data == NULL || depth > 1024) {
        return;
    }
    PtnValue values[3] = { ptn_null(), ptn_null(), ptn_null() };
    size_t values_len = 0;
    if (ptn_internal_class_name_is_fiber(object->class_name)) {
        PtnFiberData *data = (PtnFiberData *)object->native_data;
        values[values_len++] = data->callback;
        values[values_len++] = data->return_value;
        values[values_len++] = data->suspension_trace;
    } else if (
        ptn_declared_class_is_same_or_descendant(object->class_name, "ArrayIterator") ||
        ptn_declared_class_is_same_or_descendant(object->class_name, "RecursiveArrayIterator")
    ) {
        PtnArrayIteratorData *data = (PtnArrayIteratorData *)object->native_data;
        values[values_len++] = data->storage;
    } else if (ptn_declared_class_is_same_or_descendant(object->class_name, "ArrayObject")) {
        PtnArrayObjectData *data = (PtnArrayObjectData *)object->native_data;
        values[values_len++] = data->storage;
    } else if (ptn_declared_class_is_same_or_descendant(object->class_name, "SplFixedArray")) {
        PtnSplFixedArrayData *data = (PtnSplFixedArrayData *)object->native_data;
        values[values_len++] = data->storage;
    } else {
        return;
    }
    for (size_t i = 0; i < values_len; i++) {
        ptn_gc_mark_unreachable_destructor_component_value(
            component,
            values[i],
            root_epoch,
            component_epoch,
            depth + 1
        );
    }
}

static void ptn_gc_mark_unreachable_destructor_component_object(
    PtnGcObjectComponent *component,
    PtnObject *object,
    size_t root_epoch,
    size_t component_epoch,
    size_t depth
) {
    if (
        object == NULL ||
        depth > 1024 ||
        ptn_gc_object_has_opaque_native_data(object) ||
        object->gc_mark_epoch == root_epoch
    ) {
        return;
    }
    if (object->gc_mark_epoch == component_epoch) {
        if (component != NULL) {
            component->cyclic = 1;
        }
        return;
    }
    object->gc_mark_epoch = component_epoch;
    if (ptn_object_has_pending_declared_destructor(object)) {
        ptn_gc_object_component_push(component, object);
    }
    ptn_gc_mark_unreachable_destructor_component_value(
        component,
        ptn_gc_borrowed_array_value(object->properties),
        root_epoch,
        component_epoch,
        depth + 1
    );
    ptn_gc_mark_unreachable_destructor_component_value(
        component,
        object->lazy_initializer,
        root_epoch,
        component_epoch,
        depth + 1
    );
    ptn_gc_mark_unreachable_destructor_component_value(
        component,
        object->lazy_proxy_instance,
        root_epoch,
        component_epoch,
        depth + 1
    );
    ptn_gc_mark_unreachable_destructor_component_object_native_values(
        component,
        object,
        root_epoch,
        component_epoch,
        depth + 1
    );
}

static void ptn_gc_mark_unreachable_destructor_component_value(
    PtnGcObjectComponent *component,
    PtnValue value,
    size_t root_epoch,
    size_t component_epoch,
    size_t depth
) {
    if (depth > 1024) {
        return;
    }
    if (value.type == PTN_REFERENCE) {
        PtnReference *reference = value.as.reference;
        if (
            reference == NULL ||
            reference->gc_mark_epoch == root_epoch ||
            reference->gc_mark_epoch == component_epoch
        ) {
            return;
        }
        reference->gc_mark_epoch = component_epoch;
        ptn_gc_mark_unreachable_destructor_component_value(
            component,
            reference->value,
            root_epoch,
            component_epoch,
            depth + 1
        );
        return;
    }
    value = ptn_value_deref(value);
    if (value.type == PTN_ARRAY) {
        ptn_gc_mark_unreachable_destructor_component_array(
            component,
            value.as.array,
            root_epoch,
            component_epoch,
            depth + 1
        );
        return;
    }
    if (value.type == PTN_OBJECT) {
        ptn_gc_mark_unreachable_destructor_component_object(
            component,
            value.as.object,
            root_epoch,
            component_epoch,
            depth + 1
        );
        return;
    }
    if (value.type != PTN_CLOSURE || value.as.closure == NULL) {
        return;
    }
    PtnClosure *closure = value.as.closure;
    if (
        closure->gc_mark_epoch == root_epoch ||
        closure->gc_mark_epoch == component_epoch
    ) {
        return;
    }
    closure->gc_mark_epoch = component_epoch;
    ptn_gc_mark_unreachable_destructor_component_symbol_table(
        component,
        &closure->captures,
        root_epoch,
        component_epoch,
        depth + 1
    );
    if (closure->has_wrapped_callable) {
        ptn_gc_mark_unreachable_destructor_component_value(
            component,
            closure->wrapped_callable,
            root_epoch,
            component_epoch,
            depth + 1
        );
    }
}

static size_t ptn_gc_collect_destructor_components(
    PtnRuntime *root,
    size_t root_epoch,
    PtnGcObjectComponents *components
) {
    if (root == NULL || components == NULL || root_epoch == 0) {
        return 0;
    }
    size_t component_epoch = ptn_runtime_next_gc_mark_epoch(root);
    size_t initial_live_objects_len = root->live_objects_len;
    for (size_t i = 0; i < initial_live_objects_len; i++) {
        PtnObject *object = root->live_objects[i];
        if (
            object == NULL ||
            object->refcount == 0 ||
            ptn_gc_object_has_opaque_native_data(object) ||
            object->gc_mark_epoch == root_epoch ||
            object->gc_mark_epoch == component_epoch ||
            !ptn_object_has_pending_declared_destructor(object)
        ) {
            continue;
        }
        PtnGcObjectComponent *component = ptn_gc_object_components_push(components);
        ptn_gc_mark_unreachable_destructor_component_object(
            component,
            object,
            root_epoch,
            component_epoch,
            0
        );
        if (component != NULL && component->len == 0 && components->len > 0) {
            components->len--;
            free(component->objects);
        }
    }
    return components->len == 0 ? 0 : component_epoch;
}

static int ptn_gc_destructor_component_still_unreachable(
    PtnGcObjectComponent *component,
    size_t post_destructor_epoch
) {
    if (component == NULL || post_destructor_epoch == 0) {
        return 0;
    }
    for (size_t i = 0; i < component->len; i++) {
        PtnObject *object = component->objects[i];
        if (
            object != NULL &&
            object->refcount > 0 &&
            !ptn_gc_object_has_opaque_native_data(object) &&
            object->gc_mark_epoch != post_destructor_epoch &&
            !ptn_object_has_pending_declared_destructor(object)
        ) {
            return 1;
        }
    }
    return 0;
}

static void ptn_gc_mark_destructor_component_contained_values(
    PtnGcObjectComponent *component,
    size_t counted_epoch
) {
    if (component == NULL || counted_epoch == 0) {
        return;
    }
    PtnGcMarkStack stack;
    stack.items = NULL;
    stack.len = 0;
    stack.capacity = 0;

    for (size_t i = 0; i < component->len; i++) {
        PtnObject *object = component->objects[i];
        if (
            object == NULL ||
            object->refcount == 0 ||
            ptn_gc_object_has_opaque_native_data(object) ||
            object->gc_mark_epoch != counted_epoch
        ) {
            continue;
        }
        ptn_gc_mark_stack_push(&stack, ptn_gc_borrowed_array_value(object->properties));
        ptn_gc_mark_stack_push(&stack, object->lazy_initializer);
        ptn_gc_mark_stack_push(&stack, object->lazy_proxy_instance);
        ptn_gc_mark_object_native_values(&stack, object);
    }

    ptn_gc_mark_reachable_values(&stack, counted_epoch);
    free(stack.items);
}

static size_t ptn_gc_count_destructor_components(
    PtnGcObjectComponents *components,
    size_t post_destructor_epoch,
    size_t counted_epoch
) {
    if (components == NULL || post_destructor_epoch == 0 || counted_epoch == 0) {
        return 0;
    }
    size_t collected = 0;
    for (size_t i = 0; i < components->len; i++) {
        PtnGcObjectComponent *component = &components->items[i];
        int still_unreachable =
            ptn_gc_destructor_component_still_unreachable(component, post_destructor_epoch);
        if (!still_unreachable) {
            continue;
        }
        for (size_t j = 0; j < component->len; j++) {
            PtnObject *object = component->objects[j];
            if (
                object != NULL &&
                object->refcount > 0 &&
                !ptn_gc_object_has_opaque_native_data(object) &&
                object->gc_mark_epoch != post_destructor_epoch
            ) {
                object->gc_mark_epoch = counted_epoch;
            }
        }
        ptn_gc_mark_destructor_component_contained_values(component, counted_epoch);
        if (!component->cyclic) {
            continue;
        }
        if (collected == SIZE_MAX) {
            ptn_abort_out_of_memory();
        }
        collected++;
    }
    return collected;
}

static size_t ptn_runtime_mark_gc_roots(PtnRuntime *runtime, PtnRuntime *root) {
    size_t epoch = ptn_runtime_next_gc_mark_epoch(root);
    PtnGcMarkStack stack;
    stack.items = NULL;
    stack.len = 0;
    stack.capacity = 0;

    ptn_gc_mark_symbol_table(&stack, &root->symbols);
    PtnSymbolTable *root_globals = ptn_runtime_global_symbol_table(root);
    if (root_globals != &root->symbols) {
        ptn_gc_mark_symbol_table(&stack, root_globals);
    }
    if (runtime != NULL && runtime != root) {
        ptn_gc_mark_symbol_table(&stack, &runtime->symbols);
        PtnSymbolTable *runtime_globals = ptn_runtime_global_symbol_table(runtime);
        if (runtime_globals != &runtime->symbols && runtime_globals != root_globals) {
            ptn_gc_mark_symbol_table(&stack, runtime_globals);
        }
    }
    PtnSymbolTable *static_properties = root->static_properties == NULL
        ? &root->owned_static_properties
        : root->static_properties;
    ptn_gc_mark_symbol_table(&stack, static_properties);
    ptn_gc_mark_static_locals(&stack, root);
    for (size_t i = 0; i < root->temporary_roots_len; i++) {
        ptn_gc_mark_stack_push(&stack, root->temporary_roots[i]);
    }
    for (size_t i = 0; i < root->live_arrays_len; i++) {
        PtnArray *array = root->live_arrays[i];
        if (array != NULL && array->iterator_refcount != 0) {
            ptn_gc_mark_stack_push(&stack, ptn_gc_borrowed_array_value(array));
        }
    }

    ptn_gc_mark_reachable_values(&stack, epoch);
    free(stack.items);
    return epoch;
}

static void ptn_gc_collected_object_push(
    PtnObject ***objects,
    size_t *len,
    size_t *capacity,
    PtnObject *object
) {
    if (objects == NULL || len == NULL || capacity == NULL || object == NULL) {
        return;
    }
    if (*len == *capacity) {
        size_t new_capacity = *capacity == 0 ? 8 : *capacity * 2;
        if (new_capacity < *capacity || new_capacity > SIZE_MAX / sizeof(PtnObject *)) {
            ptn_abort_out_of_memory();
        }
        PtnObject **new_objects = realloc(*objects, new_capacity * sizeof(PtnObject *));
        if (new_objects == NULL) {
            ptn_abort_out_of_memory();
        }
        *objects = new_objects;
        *capacity = new_capacity;
    }
    (*objects)[(*len)++] = object;
}

static int ptn_gc_collected_object_contains(PtnObject **objects, size_t len, PtnObject *object) {
    if (objects == NULL || object == NULL) {
        return 0;
    }
    for (size_t i = 0; i < len; i++) {
        if (objects[i] == object) {
            return 1;
        }
    }
    return 0;
}

static size_t ptn_gc_destructed_object_count(PtnObject *object) {
    if (
        object == NULL ||
        (
            object->destructor_called &&
            (object->properties == NULL || object->properties->len == 0)
        )
    ) {
        return 0;
    }
    return 1;
}

static size_t ptn_runtime_collect_unreachable_objects(
    PtnRuntime *runtime,
    size_t *destructor_component_epoch_out,
    size_t *counted_object_epoch_out
) {
    PtnRuntime *root = ptn_runtime_root(runtime);
    if (root == NULL) {
        root = runtime;
    }
    if (root == NULL) {
        return 0;
    }
    if (destructor_component_epoch_out != NULL) {
        *destructor_component_epoch_out = 0;
    }
    if (counted_object_epoch_out != NULL) {
        *counted_object_epoch_out = 0;
    }

    size_t epoch = ptn_runtime_mark_gc_roots(runtime, root);
    size_t collected = 0;
    PtnGcObjectComponents destructor_components = {0};
    size_t destructor_component_epoch =
        ptn_gc_collect_destructor_components(root, epoch, &destructor_components);
    if (destructor_component_epoch_out != NULL) {
        *destructor_component_epoch_out = destructor_component_epoch;
    }

    PtnObject **destructed_objects = NULL;
    size_t destructed_objects_len = 0;
    size_t destructed_objects_capacity = 0;

    size_t initial_live_objects_len = root->live_objects_len;
    for (size_t i = 0; i < initial_live_objects_len; i++) {
        PtnObject *object = root->live_objects[i];
        if (
            object == NULL ||
            object->refcount == 0 ||
            ptn_gc_object_has_opaque_native_data(object) ||
            object->gc_mark_epoch == epoch ||
            !ptn_object_has_pending_declared_destructor(object)
        ) {
            continue;
        }
        ptn_object_retain(object);
        ptn_gc_collected_object_push(
            &destructed_objects,
            &destructed_objects_len,
            &destructed_objects_capacity,
            object
        );
        ptn_object_run_destructor_ex(object, 1);
    }

    epoch = ptn_runtime_mark_gc_roots(runtime, root);
    size_t counted_destructor_epoch = ptn_runtime_next_gc_mark_epoch(root);
    collected = ptn_gc_count_destructor_components(
        &destructor_components,
        epoch,
        counted_destructor_epoch
    );

    for (size_t i = 0; i < destructed_objects_len; i++) {
        PtnObject *object = destructed_objects[i];
        ptn_object_release(object);
    }
    ptn_gc_object_components_release(&destructor_components);

    size_t counted_object_epoch = ptn_runtime_next_gc_mark_epoch(root);
    if (counted_object_epoch_out != NULL) {
        *counted_object_epoch_out = counted_object_epoch;
    }
    size_t index = root->live_objects_len;
    while (index > 0) {
        index--;
        PtnObject *object = root->live_objects[index];
        if (
            object != NULL &&
            object->refcount > 0 &&
            !ptn_gc_object_has_opaque_native_data(object) &&
            object->gc_mark_epoch != epoch &&
            object->gc_mark_epoch != counted_object_epoch &&
            !ptn_object_has_pending_declared_destructor(object)
        ) {
            int object_already_counted = object->gc_mark_epoch == counted_destructor_epoch;
            if (!object_already_counted) {
                object->gc_mark_epoch = counted_object_epoch;
            }
            size_t nested = object_already_counted
                ? 0
                : ptn_gc_count_unreachable_contained_values_in_object_properties(
                    object,
                    epoch,
                    counted_object_epoch
                );
            size_t object_count = object_already_counted
                ? 0
                : ptn_gc_destructed_object_count(object);
            if (collected > SIZE_MAX - object_count ||
                collected + object_count > SIZE_MAX - nested) {
                ptn_abort_out_of_memory();
            }
            collected += object_count + nested;
            ptn_runtime_remove_live_object_at(root, index);
            object->refcount = 1;
            ptn_object_release(object);
            if (index > root->live_objects_len) {
                index = root->live_objects_len;
            }
        }
    }
    free(destructed_objects);
    return collected;
}

static void ptn_runtime_clear_live_array_reference_slots(PtnRuntime *root, PtnReference *reference) {
    if (root == NULL || reference == NULL) {
        return;
    }
    for (size_t i = 0; i < root->live_arrays_len; i++) {
        PtnArray *array = root->live_arrays[i];
        if (array == NULL || array->destructing) {
            continue;
        }
        for (size_t j = 0; j < array->len; j++) {
            PtnValue *entry = &array->entries[j].value;
            if (entry->type == PTN_REFERENCE && entry->as.reference == reference) {
                *entry = ptn_null();
            }
        }
    }
}

static int ptn_runtime_array_is_object_property_storage(PtnRuntime *root, PtnArray *array) {
    if (root == NULL || array == NULL) {
        return 0;
    }
    for (size_t i = 0; i < root->live_objects_len; i++) {
        PtnObject *object = root->live_objects[i];
        if (object != NULL && object->properties == array) {
            return 1;
        }
    }
    return 0;
}

static size_t ptn_runtime_collect_unreachable_references_and_arrays(
    PtnRuntime *runtime,
    size_t excluded_epoch,
    size_t counted_epoch
) {
    PtnRuntime *root = ptn_runtime_root(runtime);
    if (root == NULL) {
        root = runtime;
    }
    if (root == NULL) {
        return 0;
    }

    size_t epoch = ptn_runtime_mark_gc_roots(runtime, root);
    size_t collected = 0;

    size_t reference_index = root->live_references_len;
    while (reference_index > 0) {
        reference_index--;
        PtnReference *reference = root->live_references[reference_index];
        if (
            reference == NULL ||
            reference->refcount == 0 ||
            reference->gc_collecting ||
            ptn_reference_is_protected_by_live_array_iterator(root, reference) ||
            reference->gc_mark_epoch == epoch
        ) {
            continue;
        }
        int already_counted = counted_epoch != 0 &&
            reference->gc_mark_epoch == counted_epoch;
        if (excluded_epoch != 0 && reference->gc_mark_epoch == excluded_epoch) {
            if (
                reference->value.type != PTN_ARRAY ||
                reference->value.as.array == NULL ||
                ptn_array_count_reference(reference->value.as.array, reference, 0) == 0
            ) {
                continue;
            }
        }
        if (
            reference->value.type == PTN_ARRAY &&
            ptn_array_contains_pending_destructor(reference->value.as.array, 0) &&
            (
                excluded_epoch == 0 ||
                reference->value.as.array == NULL ||
                reference->value.as.array->gc_mark_epoch != excluded_epoch
            )
        ) {
            continue;
        }
        ptn_runtime_clear_live_array_reference_slots(root, reference);
        ptn_runtime_remove_live_reference_at(root, reference_index);
        reference->lifecycle_runtime = NULL;
        reference->gc_collecting = 1;
        reference->refcount = 0;
        ptn_reference_destroy_storage(reference);
        if (collected == SIZE_MAX) {
            ptn_abort_out_of_memory();
        }
        if (!already_counted) {
            collected++;
        }
        if (reference_index > root->live_references_len) {
            reference_index = root->live_references_len;
        }
    }

    epoch = ptn_runtime_mark_gc_roots(runtime, root);
    size_t array_index = root->live_arrays_len;
    while (array_index > 0) {
        array_index--;
        PtnArray *array = root->live_arrays[array_index];
        if (
            array == NULL ||
            array->refcount == 0 ||
            array->destructing ||
            array->iterator_refcount != 0 ||
            (excluded_epoch != 0 && array->gc_mark_epoch == excluded_epoch) ||
            array->gc_mark_epoch == epoch
        ) {
            continue;
        }
        int already_counted = counted_epoch != 0 &&
            array->gc_mark_epoch == counted_epoch;
        if (ptn_runtime_array_is_object_property_storage(root, array)) {
            continue;
        }
        if (
            ptn_array_contains_pending_destructor(array, 0) &&
            (excluded_epoch == 0 || array->gc_mark_epoch != excluded_epoch)
        ) {
            continue;
        }
        ptn_runtime_remove_live_array_at(root, array_index);
        array->lifecycle_runtime = NULL;
        array->refcount = 1;
        ptn_array_free(array);
        if (collected == SIZE_MAX) {
            ptn_abort_out_of_memory();
        }
        if (!already_counted) {
            collected++;
        }
        if (array_index > root->live_arrays_len) {
            array_index = root->live_arrays_len;
        }
    }

    return collected;
}

static PtnValue ptn_internal_gc_collect_cycles(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnRuntime *root = ptn_runtime_root(runtime);
    if (root == NULL) {
        root = runtime;
    }
    if (root == NULL) {
        return ptn_int(0);
    }
    if (root->gc_running) {
        return ptn_int(0);
    }
    if (root->live_objects_len > PTN_GC_LARGE_OBJECT_SWEEP_LIMIT) {
        root->gc_roots = root->live_objects_len;
        return ptn_int(0);
    }
    root->gc_running = 1;
    if (ptn_gc_array_reference_auto_flushed()) {
        ptn_gc_drain_pending_destructor_array_cycles(runtime);
    }
    size_t destructor_component_epoch = 0;
    size_t counted_object_epoch = 0;
    size_t object_cycles = ptn_runtime_collect_unreachable_objects(
        runtime,
        &destructor_component_epoch,
        &counted_object_epoch
    );
    size_t reference_array_cycles = ptn_runtime_collect_unreachable_references_and_arrays(
        runtime,
        destructor_component_epoch,
        counted_object_epoch
    );
    size_t weak_map_cycles = ptn_runtime_collect_weak_map_cycles(runtime);
    /*
     * The object collector above already runs the Zend-style destructor rerun
     * for cycles exposed by destructors. A second broad unreferenced sweep here
     * would let objects created by that rerun join the same collection pass.
     */
    size_t array_cycles = ptn_pending_array_cycle_collections;
    ptn_pending_array_cycle_collections = 0;
    ptn_pending_array_cycle_auto_flushed = 0;
    int64_t collected = 0;
    if (weak_map_cycles > 0 || object_cycles > 0 || reference_array_cycles > 0 || array_cycles > 0) {
        if (object_cycles > SIZE_MAX - weak_map_cycles ||
            object_cycles + weak_map_cycles > SIZE_MAX - reference_array_cycles ||
            object_cycles + weak_map_cycles + reference_array_cycles > SIZE_MAX - array_cycles) {
            ptn_abort_out_of_memory();
        }
        size_t total_cycles = object_cycles + weak_map_cycles + reference_array_cycles + array_cycles;
        if (total_cycles > (size_t)INT64_MAX) {
            ptn_abort_out_of_memory();
        }
        collected = (int64_t)total_cycles;
    } else if (ptn_intl_cycle_collection_pending) {
        ptn_intl_cycle_collection_pending = 0;
        collected = 1;
    }
    if (collected > 0) {
        root->gc_runs++;
        root->gc_collected += (size_t)collected;
        root->gc_roots = 0;
    }
    root->gc_running = 0;
    if (root->exceptions->active_exception != NULL) {
        ptn_rethrow_exception(root);
    }
    return ptn_int(collected);
}

static PtnValue ptn_internal_gc_enabled(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnRuntime *root = ptn_runtime_root(runtime);
    if (root == NULL) {
        root = runtime;
    }
    return ptn_bool(root == NULL || root->gc_enabled);
}

static PtnValue ptn_internal_gc_enable(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnRuntime *root = ptn_runtime_root(runtime);
    if (root == NULL) {
        root = runtime;
    }
    if (root != NULL) {
        root->gc_enabled = 1;
    }
    return ptn_null();
}

static PtnValue ptn_internal_gc_disable(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnRuntime *root = ptn_runtime_root(runtime);
    if (root == NULL) {
        root = runtime;
    }
    if (root != NULL) {
        root->gc_enabled = 0;
    }
    return ptn_null();
}

static PtnValue ptn_internal_gc_status(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnRuntime *root = ptn_runtime_root(runtime);
    if (root == NULL) {
        root = runtime;
    }
    PtnValue status = ptn_array_from_literal_entries(0, NULL);
    ptn_array_set_entry(status.as.array, ptn_array_string_key("running"), ptn_bool(root->gc_running));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("protected"), ptn_bool(0));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("full"), ptn_bool(0));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("runs"), ptn_int((int64_t)root->gc_runs));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("collected"), ptn_int((int64_t)root->gc_collected));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("threshold"), ptn_int(10001));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("buffer_size"), ptn_int(16384));
    size_t roots = root->gc_roots;
    if (roots <= SIZE_MAX - ptn_pending_array_cycle_collections) {
        roots += ptn_pending_array_cycle_collections;
    }
    ptn_array_set_entry(status.as.array, ptn_array_string_key("roots"), ptn_int((int64_t)roots));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("application_time"), ptn_float(0.0));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("collector_time"), ptn_float(0.0));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("destructor_time"), ptn_float(0.0));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("free_time"), ptn_float(0.0));
    return status;
}

typedef struct {
    const char *data;
    size_t len;
} PtnIniText;

static PtnIniText ptn_ini_text(const char *data, size_t len) {
    PtnIniText text;
    text.data = data;
    text.len = len;
    return text;
}

static PtnIniText ptn_ini_trim_text(PtnIniText text) {
    while (text.len > 0 && isspace((unsigned char)text.data[0])) {
        text.data++;
        text.len--;
    }
    while (text.len > 0 && isspace((unsigned char)text.data[text.len - 1])) {
        text.len--;
    }
    return text;
}

static int ptn_ini_text_ascii_case_equal(PtnIniText text, const char *literal) {
    size_t literal_len = strlen(literal);
    if (text.len != literal_len) {
        return 0;
    }
    for (size_t i = 0; i < text.len; i++) {
        if (tolower((unsigned char)text.data[i]) != tolower((unsigned char)literal[i])) {
            return 0;
        }
    }
    return 1;
}

static char *ptn_ini_duplicate_text(PtnIniText text) {
    return ptn_duplicate_string_len(text.data, text.len);
}

static void ptn_ini_advance_newline(const char *data, size_t len, size_t *offset, size_t *line_no) {
    if (*offset >= len) {
        return;
    }
    if (data[*offset] == '\r' && *offset + 1 < len && data[*offset + 1] == '\n') {
        *offset += 2;
    } else {
        (*offset)++;
    }
    (*line_no)++;
}

static void ptn_ini_skip_to_next_line(const char *data, size_t len, size_t *offset, size_t *line_no) {
    while (*offset < len && data[*offset] != '\n' && data[*offset] != '\r') {
        (*offset)++;
    }
    if (*offset < len) {
        ptn_ini_advance_newline(data, len, offset, line_no);
    }
}

static void ptn_ini_emit_syntax_warning(
    PtnRuntime *runtime,
    const char *source_name,
    size_t source_line,
    size_t call_line,
    const char *detail
) {
    char message[512];
    int written = snprintf(
        message,
        sizeof(message),
        "syntax error, %s in %s on line %zu\n",
        detail,
        source_name == NULL ? "Unknown" : source_name,
        source_line
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_warning(&runtime->diagnostics, message, call_line);
}

static int ptn_ini_is_name_start(unsigned char byte) {
    return isalpha(byte) || byte == '_' || byte == '\\';
}

static int ptn_ini_is_name_byte(unsigned char byte) {
    return isalnum(byte) || byte == '_' || byte == '\\' || byte == ':' || byte == '.';
}

static int ptn_ini_string_is_integer_key(const char *data, size_t len, int64_t *out) {
    if (len == 0 || data[0] == '+') {
        return 0;
    }
    if (len == 2 && data[0] == '-' && data[1] == '0') {
        return 0;
    }
    size_t offset = data[0] == '-' ? 1 : 0;
    if (offset == len) {
        return 0;
    }
    if (data[offset] == '0' && offset + 1 < len) {
        return 0;
    }
    for (size_t i = offset; i < len; i++) {
        if (!isdigit((unsigned char)data[i])) {
            return 0;
        }
    }
    char *copy = ptn_duplicate_string_len(data, len);
    char *end = NULL;
    errno = 0;
    long long parsed = strtoll(copy, &end, 10);
    int ok = errno != ERANGE && end != copy && *end == '\0';
    if (ok) {
        *out = (int64_t)parsed;
    }
    free(copy);
    return ok;
}

static PtnArrayKey ptn_ini_array_key_from_string(const char *data, size_t len, int append_empty) {
    if (append_empty && len == 0) {
        return ptn_array_int_key(INT64_MIN);
    }
    int64_t integer = 0;
    if (ptn_ini_string_is_integer_key(data, len, &integer)) {
        return ptn_array_int_key(integer);
    }
    return ptn_array_string_key_len(data, len);
}

static void ptn_ini_set_array_value(PtnArray *target, const char *key, size_t key_len, PtnValue value) {
    PtnArrayKey array_key = ptn_ini_array_key_from_string(key, key_len, 0);
    ptn_array_set_entry(target, array_key, value);
}

static void ptn_ini_append_or_set_array_value(
    PtnArray *target,
    const char *key,
    size_t key_len,
    int append,
    PtnValue value
) {
    if (append || key_len == 0) {
        ptn_array_set_entry(target, ptn_array_int_key(target->next_auto_key), value);
        return;
    }
    ptn_ini_set_array_value(target, key, key_len, value);
}

static int ptn_ini_value_to_string_buffer(PtnRuntime *runtime, PtnValue value, PtnStringBuffer *buffer, size_t line) {
    PtnStringOperand operand = ptn_value_to_string_operand_with_runtime(runtime, value, line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(operand);
        return 0;
    }
    ptn_string_buffer_append_len(buffer, operand.data, operand.len);
    ptn_string_operand_free(operand);
    return 1;
}

static int ptn_ini_find_fallback_delimiter(PtnIniText text, size_t *delimiter_out) {
    size_t depth = 0;
    char quote = '\0';
    for (size_t i = 0; i + 1 < text.len; i++) {
        char c = text.data[i];
        if (quote != '\0') {
            if (c == '\\' && i + 1 < text.len) {
                i++;
                continue;
            }
            if (c == quote) {
                quote = '\0';
            }
            continue;
        }
        if (c == '"' || c == '\'') {
            quote = c;
            continue;
        }
        if (c == '$' && text.data[i + 1] == '{') {
            depth++;
            i++;
            continue;
        }
        if (c == '}' && depth > 0) {
            depth--;
            continue;
        }
        if (depth == 0 && c == ':' && text.data[i + 1] == '-') {
            *delimiter_out = i;
            return 1;
        }
    }
    return 0;
}

static int ptn_ini_expand_text(
    PtnRuntime *runtime,
    PtnIniText text,
    int scanner_mode,
    int substitute_constants,
    PtnStringBuffer *buffer,
    size_t line,
    int *syntax_ok
);

static int ptn_ini_expand_variable(
    PtnRuntime *runtime,
    PtnIniText text,
    int scanner_mode,
    int substitute_constants,
    PtnStringBuffer *buffer,
    size_t line,
    int *syntax_ok
) {
    size_t delimiter = 0;
    PtnIniText name = text;
    PtnIniText fallback = ptn_ini_text(NULL, 0);
    int has_fallback = ptn_ini_find_fallback_delimiter(text, &delimiter);
    if (has_fallback) {
        name = ptn_ini_text(text.data, delimiter);
        fallback = ptn_ini_text(text.data + delimiter + 2, text.len - delimiter - 2);
    }
    name = ptn_ini_trim_text(name);
    if (name.len == 0) {
        *syntax_ok = 0;
        return 0;
    }
    char *name_copy = ptn_ini_duplicate_text(name);
    const char *env = getenv(name_copy);
    if (env != NULL && env[0] != '\0') {
        ptn_string_buffer_append(buffer, env);
        free(name_copy);
        return 1;
    }
    PtnValue constant;
    if (ptn_runtime_constant_value(runtime, name_copy, &constant)) {
        int ok = ptn_ini_value_to_string_buffer(runtime, constant, buffer, line);
        free(name_copy);
        return ok;
    }
    free(name_copy);
    if (has_fallback) {
        return ptn_ini_expand_text(runtime, fallback, scanner_mode, substitute_constants, buffer, line, syntax_ok);
    }
    return 1;
}

static void ptn_ini_append_quoted_text(
    PtnRuntime *runtime,
    PtnIniText text,
    char quote,
    int scanner_mode,
    int substitute_constants,
    PtnStringBuffer *buffer,
    size_t line,
    int *syntax_ok
) {
    for (size_t i = 0; i < text.len; i++) {
        char c = text.data[i];
        if (quote == '"' && c == '\\' && i + 1 < text.len) {
            char next = text.data[++i];
            switch (next) {
                case 'n':
                    ptn_string_buffer_append_char(buffer, '\n');
                    break;
                case 'r':
                    ptn_string_buffer_append_char(buffer, '\r');
                    break;
                case 't':
                    ptn_string_buffer_append_char(buffer, '\t');
                    break;
                case '"':
                    ptn_string_buffer_append_char(buffer, '"');
                    break;
                case '\\':
                    ptn_string_buffer_append_char(buffer, '\\');
                    break;
                case '$':
                    ptn_string_buffer_append_char(buffer, '$');
                    break;
                default:
                    ptn_string_buffer_append_char(buffer, '\\');
                    ptn_string_buffer_append_char(buffer, next);
                    break;
            }
            continue;
        }
        if (quote == '"' && c == '$' && i + 1 < text.len && text.data[i + 1] == '{') {
            size_t start = i + 2;
            size_t depth = 1;
            i += 2;
            while (i < text.len && depth > 0) {
                if (text.data[i] == '$' && i + 1 < text.len && text.data[i + 1] == '{') {
                    depth++;
                    i += 2;
                    continue;
                }
                if (text.data[i] == '}') {
                    depth--;
                    if (depth == 0) {
                        break;
                    }
                }
                i++;
            }
            if (i >= text.len || depth != 0) {
                *syntax_ok = 0;
                return;
            }
            PtnIniText variable = ptn_ini_text(text.data + start, i - start);
            if (!ptn_ini_expand_variable(runtime, variable, scanner_mode, substitute_constants, buffer, line, syntax_ok)) {
                return;
            }
            continue;
        }
        ptn_string_buffer_append_char(buffer, c);
    }
}

static int ptn_ini_expand_text(
    PtnRuntime *runtime,
    PtnIniText text,
    int scanner_mode,
    int substitute_constants,
    PtnStringBuffer *buffer,
    size_t line,
    int *syntax_ok
) {
    int last_concat_token = 0;
    for (size_t i = 0; i < text.len; i++) {
        char c = text.data[i];
        if (c == '$' && i + 1 < text.len && text.data[i + 1] == '{') {
            size_t start = i + 2;
            size_t depth = 1;
            i += 2;
            while (i < text.len && depth > 0) {
                if (text.data[i] == '$' && i + 1 < text.len && text.data[i + 1] == '{') {
                    depth++;
                    i += 2;
                    continue;
                }
                if (text.data[i] == '}') {
                    depth--;
                    if (depth == 0) {
                        break;
                    }
                }
                i++;
            }
            if (i >= text.len || depth != 0) {
                *syntax_ok = 0;
                return 0;
            }
            PtnIniText variable = ptn_ini_text(text.data + start, i - start);
            if (!ptn_ini_expand_variable(runtime, variable, scanner_mode, substitute_constants, buffer, line, syntax_ok)) {
                return 0;
            }
            last_concat_token = 1;
            continue;
        }
        if (substitute_constants && isspace((unsigned char)c)) {
            size_t lookahead = i + 1;
            while (lookahead < text.len && isspace((unsigned char)text.data[lookahead])) {
                lookahead++;
            }
            if (last_concat_token &&
                lookahead < text.len &&
                (text.data[lookahead] == '"' ||
                 text.data[lookahead] == '\'' ||
                 ptn_ini_is_name_start((unsigned char)text.data[lookahead]))) {
                continue;
            }
        }
        if (substitute_constants && (c == '"' || c == '\'')) {
            size_t start = i + 1;
            size_t cursor = start;
            while (cursor < text.len && text.data[cursor] != c) {
                if (c == '"' && text.data[cursor] == '\\' && cursor + 1 < text.len) {
                    cursor += 2;
                } else {
                    cursor++;
                }
            }
            if (cursor >= text.len) {
                ptn_string_buffer_append_char(buffer, c);
                last_concat_token = 0;
                continue;
            }
            PtnIniText quoted = ptn_ini_text(text.data + start, cursor - start);
            ptn_ini_append_quoted_text(runtime, quoted, c, scanner_mode, 0, buffer, line, syntax_ok);
            if (!*syntax_ok) {
                return 0;
            }
            i = cursor;
            last_concat_token = 1;
            continue;
        }
        if (substitute_constants && scanner_mode != PTN_INI_SCANNER_RAW && ptn_ini_is_name_start((unsigned char)c)) {
            size_t start = i;
            i++;
            while (i < text.len && ptn_ini_is_name_byte((unsigned char)text.data[i])) {
                i++;
            }
            PtnIniText name = ptn_ini_text(text.data + start, i - start);
            char *name_copy = ptn_ini_duplicate_text(name);
            PtnValue constant;
            if (ptn_runtime_constant_value(runtime, name_copy, &constant)) {
                int ok = ptn_ini_value_to_string_buffer(runtime, constant, buffer, line);
                free(name_copy);
                if (!ok) {
                    return 0;
                }
                last_concat_token = 1;
            } else {
                ptn_string_buffer_append_len(buffer, name.data, name.len);
                free(name_copy);
                last_concat_token = 0;
            }
            i--;
            continue;
        }
        ptn_string_buffer_append_char(buffer, c);
        last_concat_token = 0;
    }
    return *syntax_ok;
}

static int ptn_ini_strip_outer_quotes(PtnIniText text, PtnIniText *inner_out, char *quote_out) {
    text = ptn_ini_trim_text(text);
    if (text.len < 2 || (text.data[0] != '"' && text.data[0] != '\'')) {
        return 0;
    }
    char quote = text.data[0];
    if (text.data[text.len - 1] != quote) {
        return 0;
    }
    *inner_out = ptn_ini_text(text.data + 1, text.len - 2);
    *quote_out = quote;
    return 1;
}

static int ptn_ini_parse_integer_literal(PtnIniText text, int64_t *out) {
    text = ptn_ini_trim_text(text);
    if (text.len == 0) {
        return 0;
    }
    char *copy = ptn_ini_duplicate_text(text);
    char *end = NULL;
    errno = 0;
    long long parsed = strtoll(copy, &end, 0);
    int ok = errno != ERANGE && end != copy && *end == '\0';
    if (ok) {
        *out = (int64_t)parsed;
    }
    free(copy);
    return ok;
}

static int ptn_ini_eval_int_atom(PtnRuntime *runtime, PtnIniText text, int64_t *out) {
    text = ptn_ini_trim_text(text);
    if (text.len == 0) {
        return 0;
    }
    int invert = 0;
    while (text.len > 0 && text.data[0] == '~') {
        invert = !invert;
        text.data++;
        text.len--;
        text = ptn_ini_trim_text(text);
    }
    int64_t value = 0;
    if (!ptn_ini_parse_integer_literal(text, &value)) {
        char *numeric_copy = ptn_ini_duplicate_text(text);
        char *numeric_end = NULL;
        errno = 0;
        double parsed_float = strtod(numeric_copy, &numeric_end);
        int parsed_float_ok = errno != ERANGE &&
            numeric_end != numeric_copy &&
            *numeric_end == '\0' &&
            strchr(numeric_copy, '.') != NULL;
        if (parsed_float_ok) {
            free(numeric_copy);
            value = (int64_t)parsed_float;
            *out = invert ? ~value : value;
            return 1;
        }
        free(numeric_copy);
        char *name = ptn_ini_duplicate_text(text);
        PtnValue constant;
        if (!ptn_runtime_constant_value(runtime, name, &constant)) {
            free(name);
            return 0;
        }
        PtnValue resolved = ptn_value_deref(constant);
        if (resolved.type == PTN_INT) {
            value = resolved.as.integer;
        } else if (resolved.type == PTN_BOOL) {
            value = resolved.as.boolean ? 1 : 0;
        } else {
            PtnStringOperand operand = ptn_value_to_string_operand(resolved);
            int ok = ptn_ini_parse_integer_literal(ptn_ini_text(operand.data, operand.len), &value);
            ptn_string_operand_free(operand);
            if (!ok) {
                free(name);
                return 0;
            }
        }
        free(name);
    }
    *out = invert ? ~value : value;
    return 1;
}

static int ptn_ini_eval_int_expression(PtnRuntime *runtime, PtnIniText text, int64_t *out) {
    int has_operator = 0;
    for (size_t i = 0; i < text.len; i++) {
        if (text.data[i] == '&' || text.data[i] == '|' || text.data[i] == '^' || text.data[i] == '~') {
            has_operator = 1;
            break;
        }
    }
    if (!has_operator) {
        char *numeric_copy = ptn_ini_duplicate_text(ptn_ini_trim_text(text));
        char *numeric_end = NULL;
        errno = 0;
        (void)strtod(numeric_copy, &numeric_end);
        int is_plain_float = errno != ERANGE &&
            numeric_end != numeric_copy &&
            *numeric_end == '\0' &&
            strchr(numeric_copy, '.') != NULL;
        free(numeric_copy);
        if (is_plain_float) {
            return 0;
        }
        return ptn_ini_eval_int_atom(runtime, text, out);
    }

    size_t start = 0;
    char pending = '\0';
    int have_value = 0;
    int64_t result = 0;
    for (size_t i = 0; i <= text.len; i++) {
        int at_operator = i < text.len && (text.data[i] == '&' || text.data[i] == '|' || text.data[i] == '^');
        if (i != text.len && !at_operator) {
            continue;
        }
        PtnIniText atom = ptn_ini_trim_text(ptn_ini_text(text.data + start, i - start));
        int64_t value = 0;
        if (!ptn_ini_eval_int_atom(runtime, atom, &value)) {
            return 0;
        }
        if (!have_value) {
            result = value;
            have_value = 1;
        } else if (pending == '&') {
            result &= value;
        } else if (pending == '|') {
            result |= value;
        } else if (pending == '^') {
            result ^= value;
        } else {
            return 0;
        }
        if (i < text.len) {
            pending = text.data[i];
            start = i + 1;
        }
    }
    if (!have_value) {
        return 0;
    }
    *out = result;
    return 1;
}

static int ptn_ini_text_is_plain_octal_or_hex_literal(PtnIniText text) {
    text = ptn_ini_trim_text(text);
    size_t offset = 0;
    if (offset < text.len && (text.data[offset] == '+' || text.data[offset] == '-')) {
        offset++;
    }
    if (offset + 1 >= text.len || text.data[offset] != '0') {
        return 0;
    }
    if (text.data[offset + 1] == 'x' || text.data[offset + 1] == 'X') {
        if (offset + 2 >= text.len) {
            return 0;
        }
        for (size_t i = offset + 2; i < text.len; i++) {
            if (!isxdigit((unsigned char)text.data[i])) {
                return 0;
            }
        }
        return 1;
    }
    if (!isdigit((unsigned char)text.data[offset + 1])) {
        return 0;
    }
    for (size_t i = offset + 1; i < text.len; i++) {
        if (text.data[i] < '0' || text.data[i] > '7') {
            return 0;
        }
    }
    return 1;
}

static int ptn_ini_parse_float_literal(PtnIniText text, double *out) {
    text = ptn_ini_trim_text(text);
    if (text.len == 0) {
        return 0;
    }
    char *copy = ptn_ini_duplicate_text(text);
    char *end = NULL;
    errno = 0;
    double parsed = strtod(copy, &end);
    int ok = errno != ERANGE && end != copy && *end == '\0' && strchr(copy, '.') != NULL;
    if (ok) {
        *out = parsed;
    }
    free(copy);
    return ok;
}

static PtnValue ptn_ini_string_value_from_buffer(PtnStringBuffer *buffer) {
    return ptn_owned_string_len(buffer->data, buffer->len);
}

static int ptn_ini_text_is_reserved_true(PtnIniText text) {
    return ptn_ini_text_ascii_case_equal(text, "yes") ||
        ptn_ini_text_ascii_case_equal(text, "on") ||
        ptn_ini_text_ascii_case_equal(text, "true");
}

static int ptn_ini_text_is_reserved_false_or_null(PtnIniText text) {
    return ptn_ini_text_ascii_case_equal(text, "no") ||
        ptn_ini_text_ascii_case_equal(text, "off") ||
        ptn_ini_text_ascii_case_equal(text, "false") ||
        ptn_ini_text_ascii_case_equal(text, "none") ||
        ptn_ini_text_ascii_case_equal(text, "null");
}

static PtnValue ptn_ini_normalized_string_value(
    PtnRuntime *runtime,
    PtnIniText text,
    int scanner_mode,
    size_t line,
    int *syntax_ok,
    int *quoted_out
) {
    PtnIniText inner;
    char quote = '\0';
    int quoted = ptn_ini_strip_outer_quotes(text, &inner, &quote);
    if (quoted_out != NULL) {
        *quoted_out = quoted;
    }
    if (quoted) {
        PtnStringBuffer buffer;
        ptn_string_buffer_init(&buffer);
        if (scanner_mode == PTN_INI_SCANNER_RAW) {
            ptn_string_buffer_append_len(&buffer, inner.data, inner.len);
        } else {
            ptn_ini_append_quoted_text(runtime, inner, quote, scanner_mode, 1, &buffer, line, syntax_ok);
            if (!*syntax_ok) {
                free(buffer.data);
                return ptn_bool(0);
            }
        }
        return ptn_ini_string_value_from_buffer(&buffer);
    }

    PtnIniText trimmed = ptn_ini_trim_text(text);
    if (scanner_mode == PTN_INI_SCANNER_RAW) {
        return ptn_owned_string_len(ptn_ini_duplicate_text(trimmed), trimmed.len);
    }

    if (scanner_mode == PTN_INI_SCANNER_NORMAL) {
        if (ptn_ini_text_is_reserved_true(trimmed)) {
            return ptn_string("1");
        }
        if (ptn_ini_text_is_reserved_false_or_null(trimmed)) {
            return ptn_string("");
        }
    }

    int64_t expression = 0;
    if (
        !(scanner_mode == PTN_INI_SCANNER_TYPED &&
            (ptn_ini_text_is_reserved_true(trimmed) || ptn_ini_text_is_reserved_false_or_null(trimmed))) &&
        (scanner_mode != PTN_INI_SCANNER_NORMAL || !ptn_ini_text_is_plain_octal_or_hex_literal(trimmed)) &&
        ptn_ini_eval_int_expression(runtime, trimmed, &expression)
    ) {
        char number[64];
        int written = snprintf(number, sizeof(number), "%lld", (long long)expression);
        if (written < 0 || (size_t)written >= sizeof(number)) {
            ptn_abort_out_of_memory();
        }
        return ptn_owned_string_len(ptn_duplicate_string_len(number, (size_t)written), (size_t)written);
    }

    if (scanner_mode == PTN_INI_SCANNER_TYPED &&
        (ptn_ini_text_is_reserved_true(trimmed) || ptn_ini_text_is_reserved_false_or_null(trimmed))) {
        return ptn_owned_string_len(ptn_ini_duplicate_text(trimmed), trimmed.len);
    }

    PtnStringBuffer buffer;
    ptn_string_buffer_init(&buffer);
    if (!ptn_ini_expand_text(runtime, text, scanner_mode, 1, &buffer, line, syntax_ok)) {
        free(buffer.data);
        return ptn_bool(0);
    }
    return ptn_ini_string_value_from_buffer(&buffer);
}

static PtnValue ptn_ini_parse_value(
    PtnRuntime *runtime,
    PtnIniText text,
    int scanner_mode,
    size_t line,
    int *syntax_ok
) {
    int quoted = 0;
    PtnValue normalized = ptn_ini_normalized_string_value(runtime, text, scanner_mode, line, syntax_ok, &quoted);
    if (!*syntax_ok || scanner_mode != PTN_INI_SCANNER_TYPED || quoted) {
        return normalized;
    }

    PtnStringOperand operand = ptn_value_to_string_operand(normalized);
    PtnIniText as_text = ptn_ini_text(operand.data, operand.len);
    if (ptn_ini_text_ascii_case_equal(as_text, "yes") ||
        ptn_ini_text_ascii_case_equal(as_text, "on") ||
        ptn_ini_text_ascii_case_equal(as_text, "true")) {
        ptn_string_operand_free(operand);
        return ptn_bool(1);
    }
    if (ptn_ini_text_ascii_case_equal(as_text, "no") ||
        ptn_ini_text_ascii_case_equal(as_text, "off") ||
        ptn_ini_text_ascii_case_equal(as_text, "false")) {
        ptn_string_operand_free(operand);
        return ptn_bool(0);
    }
    if (ptn_ini_text_ascii_case_equal(as_text, "none") ||
        ptn_ini_text_ascii_case_equal(as_text, "null")) {
        ptn_string_operand_free(operand);
        return ptn_null();
    }
    int64_t integer = 0;
    if (ptn_ini_eval_int_expression(runtime, as_text, &integer)) {
        ptn_string_operand_free(operand);
        return ptn_int(integer);
    }
    PtnIniText trimmed = ptn_ini_trim_text(as_text);
    size_t prefix_len = 0;
    if (trimmed.len >= 3) {
        if (trimmed.data[prefix_len] == '+' || trimmed.data[prefix_len] == '-') {
            prefix_len++;
        }
        size_t digit_start = prefix_len;
        while (prefix_len < trimmed.len && isdigit((unsigned char)trimmed.data[prefix_len])) {
            prefix_len++;
        }
        if (prefix_len > digit_start &&
            prefix_len + 1 < trimmed.len &&
            trimmed.data[prefix_len] == '|' &&
            trimmed.data[prefix_len + 1] == '>') {
            int64_t prefix = 0;
            if (ptn_ini_parse_integer_literal(ptn_ini_text(trimmed.data, prefix_len), &prefix)) {
                ptn_string_operand_free(operand);
                return ptn_int(prefix);
            }
        }
    }
    double floating = 0.0;
    if (ptn_ini_parse_float_literal(as_text, &floating)) {
        ptn_string_operand_free(operand);
        return ptn_float(floating);
    }
    ptn_string_operand_free(operand);
    return normalized;
}

static char *ptn_ini_normalized_key(
    PtnRuntime *runtime,
    PtnIniText text,
    int scanner_mode,
    size_t line,
    int *syntax_ok,
    size_t *len_out
) {
    PtnIniText inner;
    char quote = '\0';
    text = ptn_ini_trim_text(text);
    if (ptn_ini_strip_outer_quotes(text, &inner, &quote)) {
        PtnStringBuffer buffer;
        ptn_string_buffer_init(&buffer);
        if (scanner_mode == PTN_INI_SCANNER_RAW) {
            ptn_string_buffer_append_len(&buffer, inner.data, inner.len);
        } else {
            ptn_ini_append_quoted_text(runtime, inner, quote, scanner_mode, 0, &buffer, line, syntax_ok);
        }
        if (!*syntax_ok) {
            free(buffer.data);
            *len_out = 0;
            return NULL;
        }
        *len_out = buffer.len;
        return buffer.data;
    }

    PtnStringBuffer buffer;
    ptn_string_buffer_init(&buffer);
    if (!ptn_ini_expand_text(runtime, text, scanner_mode, 0, &buffer, line, syntax_ok)) {
        free(buffer.data);
        *len_out = 0;
        return NULL;
    }
    *len_out = buffer.len;
    return buffer.data;
}

static PtnArray *ptn_ini_section_array(
    PtnRuntime *runtime,
    PtnValue result,
    PtnIniText section_text,
    int scanner_mode,
    size_t line,
    int *syntax_ok
) {
    size_t section_len = 0;
    char *section = ptn_ini_normalized_key(runtime, section_text, scanner_mode, line, syntax_ok, &section_len);
    if (!*syntax_ok) {
        return NULL;
    }
    PtnArrayKey section_key = ptn_ini_array_key_from_string(section, section_len, 0);
    PtnArrayEntry *entry = ptn_array_entry_for_key(result.as.array, section_key);
    if (entry != NULL && ptn_value_deref(entry->value).type == PTN_ARRAY) {
        ptn_array_key_free(section_key);
        free(section);
        return ptn_value_deref(entry->value).as.array;
    }
    PtnValue array = ptn_array_from_literal_entries(0, NULL);
    ptn_array_set_entry(result.as.array, section_key, array);
    PtnArrayKey lookup_key = ptn_ini_array_key_from_string(section, section_len, 0);
    entry = ptn_array_entry_for_key(result.as.array, lookup_key);
    ptn_array_key_free(lookup_key);
    free(section);
    return entry == NULL ? NULL : ptn_value_deref(entry->value).as.array;
}

static void ptn_ini_store_entry(
    PtnRuntime *runtime,
    PtnArray *target,
    PtnIniText key_text,
    PtnValue value,
    int scanner_mode,
    size_t line,
    int *syntax_ok
) {
    key_text = ptn_ini_trim_text(key_text);
    const char *bracket = memchr(key_text.data, '[', key_text.len);
    if (bracket == NULL) {
        size_t key_len = 0;
        char *key = ptn_ini_normalized_key(runtime, key_text, scanner_mode, line, syntax_ok, &key_len);
        if (!*syntax_ok) {
            return;
        }
        ptn_ini_set_array_value(target, key, key_len, value);
        free(key);
        return;
    }

    const char *last_bracket = NULL;
    for (size_t i = key_text.len; i > 0; i--) {
        if (key_text.data[i - 1] == ']') {
            last_bracket = key_text.data + i - 1;
            break;
        }
    }
    if (last_bracket == NULL || last_bracket < bracket) {
        size_t key_len = 0;
        char *key = ptn_ini_normalized_key(runtime, key_text, scanner_mode, line, syntax_ok, &key_len);
        if (!*syntax_ok) {
            return;
        }
        ptn_ini_set_array_value(target, key, key_len, value);
        free(key);
        return;
    }

    PtnIniText base_text = ptn_ini_trim_text(ptn_ini_text(key_text.data, (size_t)(bracket - key_text.data)));
    size_t base_len = 0;
    char *base = ptn_ini_normalized_key(runtime, base_text, scanner_mode, line, syntax_ok, &base_len);
    if (!*syntax_ok) {
        return;
    }
    PtnArrayKey base_key = ptn_ini_array_key_from_string(base, base_len, 0);
    PtnArrayEntry *entry = ptn_array_entry_for_key(target, base_key);
    if (entry == NULL || ptn_value_deref(entry->value).type != PTN_ARRAY) {
        ptn_array_set_entry(target, base_key, ptn_array_from_literal_entries(0, NULL));
        PtnArrayKey lookup_key = ptn_ini_array_key_from_string(base, base_len, 0);
        entry = ptn_array_entry_for_key(target, lookup_key);
        ptn_array_key_free(lookup_key);
    } else {
        ptn_array_key_free(base_key);
    }
    free(base);
    if (entry == NULL) {
        return;
    }

    PtnIniText offset_text = ptn_ini_trim_text(ptn_ini_text(bracket + 1, (size_t)(last_bracket - bracket - 1)));
    size_t offset_len = 0;
    char *offset = ptn_ini_normalized_key(runtime, offset_text, scanner_mode, line, syntax_ok, &offset_len);
    if (!*syntax_ok) {
        return;
    }
    ptn_ini_append_or_set_array_value(ptn_value_deref(entry->value).as.array, offset, offset_len, offset_len == 0, value);
    free(offset);
}

static int ptn_ini_scan_value_end(
    const char *data,
    size_t len,
    size_t *offset,
    size_t *line_no,
    size_t *value_end_out,
    char *unmatched_quote_out,
    int scanner_mode
) {
    char quote = '\0';
    int quote_can_open = 1;
    while (*offset < len) {
        char c = data[*offset];
        if (quote != '\0') {
            if (c == '\\' && quote == '"' && *offset + 1 < len) {
                *offset += 2;
                continue;
            }
            if (c == quote) {
                quote = '\0';
                (*offset)++;
                quote_can_open = 0;
                continue;
            }
            if (c == '\n' || c == '\r') {
                ptn_ini_advance_newline(data, len, offset, line_no);
                continue;
            }
            (*offset)++;
            continue;
        }
        if (c == '\n' || c == '\r' || c == '\0') {
            break;
        }
        if (c == ';') {
            break;
        }
        if (c == '=') {
            return 0;
        }
        if ((c == '"' || c == '\'') && (scanner_mode != PTN_INI_SCANNER_RAW || quote_can_open)) {
            if (scanner_mode == PTN_INI_SCANNER_RAW) {
                int closes_on_this_line = 0;
                for (size_t look = *offset + 1; look < len; look++) {
                    if (data[look] == '\n' || data[look] == '\r') {
                        break;
                    }
                    if (data[look] == c) {
                        closes_on_this_line = 1;
                        break;
                    }
                }
                if (!closes_on_this_line) {
                    quote_can_open = 0;
                    (*offset)++;
                    continue;
                }
            }
            quote = c;
            (*offset)++;
            continue;
        }
        if (!isspace((unsigned char)c)) {
            quote_can_open = 0;
        }
        (*offset)++;
    }
    *value_end_out = *offset;
    *unmatched_quote_out = quote;
    return 1;
}

static const char *ptn_ini_syntax_detail_for_failed_value(PtnIniText text) {
    for (size_t i = 0; i + 1 < text.len; i++) {
        if (text.data[i] != '$' || text.data[i + 1] != '{') {
            continue;
        }
        size_t depth = 1;
        int saw_fallback = 0;
        i += 2;
        while (i < text.len && depth > 0) {
            if (text.data[i] == '$' && i + 1 < text.len && text.data[i + 1] == '{') {
                depth++;
                i += 2;
                continue;
            }
            if (depth == 1 && text.data[i] == ':' && i + 1 < text.len && text.data[i + 1] == '-') {
                saw_fallback = 1;
            }
            if (text.data[i] == '}') {
                depth--;
                if (depth == 0) {
                    break;
                }
            }
            i++;
        }
        if (depth != 0) {
            return saw_fallback
                ? "unexpected TC_FALLBACK, expecting TC_VARNAME"
                : "unexpected end of file, expecting TC_FALLBACK or '}'";
        }
    }
    return "unexpected end of file";
}

static const char *ptn_ini_syntax_detail_for_failed_section(PtnIniText text) {
    for (size_t i = 0; i + 1 < text.len; i++) {
        if (text.data[i] != '$' || text.data[i + 1] != '{') {
            continue;
        }
        size_t depth = 1;
        i += 2;
        while (i < text.len && depth > 0) {
            if (text.data[i] == '$' && i + 1 < text.len && text.data[i + 1] == '{') {
                depth++;
                i += 2;
                continue;
            }
            if (text.data[i] == '}') {
                depth--;
                if (depth == 0) {
                    break;
                }
            }
            i++;
        }
        if (depth != 0) {
            return "unexpected end of file, expecting '}'";
        }
    }
    return "unexpected end of section";
}

static PtnValue ptn_ini_parse_contents(
    PtnRuntime *runtime,
    const char *data,
    size_t len,
    int process_sections,
    int scanner_mode,
    const char *source_name,
    size_t call_line,
    int *ok_out
) {
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    PtnArray *target = result.as.array;
    size_t offset = 0;
    size_t line_no = 1;
    *ok_out = 1;

    while (offset < len) {
        while (offset < len && (data[offset] == '\n' || data[offset] == '\r')) {
            ptn_ini_advance_newline(data, len, &offset, &line_no);
        }
        while (offset < len && isspace((unsigned char)data[offset]) && data[offset] != '\n' && data[offset] != '\r') {
            offset++;
        }
        if (offset >= len) {
            break;
        }
        if (data[offset] == ';' || data[offset] == '#') {
            ptn_ini_skip_to_next_line(data, len, &offset, &line_no);
            continue;
        }

        size_t statement_line = line_no;
        if (data[offset] == '[') {
            size_t section_start = ++offset;
            while (offset < len && data[offset] != ']' && data[offset] != '\n' && data[offset] != '\r') {
                offset++;
            }
            if (offset >= len || data[offset] != ']') {
                PtnIniText section_text = ptn_ini_text(data + section_start, offset - section_start);
                ptn_ini_emit_syntax_warning(
                    runtime,
                    source_name,
                    statement_line,
                    call_line,
                    ptn_ini_syntax_detail_for_failed_section(section_text)
                );
                *ok_out = 0;
                ptn_value_destroy(&result);
                return ptn_bool(0);
            }
            PtnIniText section_text = ptn_ini_text(data + section_start, offset - section_start);
            offset++;
            if (process_sections) {
                target = ptn_ini_section_array(runtime, result, section_text, scanner_mode, call_line, ok_out);
                if (!*ok_out || target == NULL) {
                    ptn_value_destroy(&result);
                    return ptn_bool(0);
                }
            } else {
                target = result.as.array;
            }
            ptn_ini_skip_to_next_line(data, len, &offset, &line_no);
            continue;
        }

        size_t key_start = offset;
        while (offset < len && data[offset] != '=' && data[offset] != '\n' && data[offset] != '\r') {
            offset++;
        }
        if (offset >= len || data[offset] != '=') {
            ptn_ini_skip_to_next_line(data, len, &offset, &line_no);
            continue;
        }
        PtnIniText key_text = ptn_ini_text(data + key_start, offset - key_start);
        offset++;
        while (offset < len && isspace((unsigned char)data[offset]) && data[offset] != '\n' && data[offset] != '\r') {
            offset++;
        }
        size_t value_start = offset;
        size_t value_end = offset;
        char unmatched_quote = '\0';
        if (!ptn_ini_scan_value_end(data, len, &offset, &line_no, &value_end, &unmatched_quote, scanner_mode)) {
            ptn_ini_emit_syntax_warning(runtime, source_name, statement_line, call_line, "unexpected '='");
            *ok_out = 0;
            ptn_value_destroy(&result);
            return ptn_bool(0);
        }
        if (unmatched_quote != '\0') {
            const char *detail = unmatched_quote == '"'
                ? "unexpected end of file, expecting TC_DOLLAR_CURLY or TC_QUOTED_STRING or '\"'"
                : "unexpected end of file";
            ptn_ini_emit_syntax_warning(runtime, source_name, statement_line, call_line, detail);
            *ok_out = 0;
            ptn_value_destroy(&result);
            return ptn_bool(0);
        }

        PtnIniText raw_value_text = ptn_ini_text(data + value_start, value_end - value_start);
        int only_space_value = 1;
        for (size_t i = 0; i < raw_value_text.len; i++) {
            if (!isspace((unsigned char)raw_value_text.data[i])) {
                only_space_value = 0;
                break;
            }
        }
        PtnIniText value_text = only_space_value
            ? ptn_ini_text(raw_value_text.data, 0)
            : (value_end == len ? raw_value_text : ptn_ini_trim_text(raw_value_text));
        int syntax_ok = 1;
        PtnValue value = ptn_ini_parse_value(runtime, value_text, scanner_mode, call_line, &syntax_ok);
        if (!syntax_ok || runtime->exceptions->active_exception != NULL) {
            if (!syntax_ok) {
                ptn_ini_emit_syntax_warning(
                    runtime,
                    source_name,
                    statement_line,
                    call_line,
                    ptn_ini_syntax_detail_for_failed_value(value_text)
                );
            }
            *ok_out = 0;
            ptn_value_destroy(&result);
            return ptn_bool(0);
        }
        ptn_ini_store_entry(runtime, target, key_text, value, scanner_mode, call_line, &syntax_ok);
        if (!syntax_ok) {
            ptn_ini_emit_syntax_warning(runtime, source_name, statement_line, call_line, "unexpected end of file");
            *ok_out = 0;
            ptn_value_destroy(&result);
            return ptn_bool(0);
        }
        ptn_ini_skip_to_next_line(data, len, &offset, &line_no);
    }

    return result;
}

static int ptn_ini_scanner_mode_arg(PtnRuntime *runtime, const char *function_name, size_t argc, const PtnValue *args, size_t line) {
    int64_t scanner_mode = PTN_INI_SCANNER_NORMAL;
    if (argc >= 3) {
        scanner_mode = ptn_internal_expect_integer_arg(runtime, function_name, 3, "scanner_mode", args[2], line);
        if (runtime->exceptions->active_exception != NULL) {
            return PTN_INI_SCANNER_NORMAL;
        }
    }
    if (scanner_mode != PTN_INI_SCANNER_NORMAL &&
        scanner_mode != PTN_INI_SCANNER_RAW &&
        scanner_mode != PTN_INI_SCANNER_TYPED) {
        ptn_emit_warning(&runtime->diagnostics, "Invalid scanner mode", line);
        return -1;
    }
    return (int)scanner_mode;
}

static PtnValue ptn_internal_parse_ini_string(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input = ptn_internal_expect_string_arg(runtime, "parse_ini_string", 1, "ini_string", args[0], line);
    int process_sections = argc >= 2 && ptn_is_truthy(args[1]);
    int scanner_mode = ptn_ini_scanner_mode_arg(runtime, "parse_ini_string", argc, args, line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(input);
        return ptn_null();
    }
    if (scanner_mode < 0) {
        ptn_string_operand_free(input);
        return ptn_bool(0);
    }
    int ok = 1;
    PtnValue result = ptn_ini_parse_contents(
        runtime,
        input.data,
        input.len,
        process_sections,
        scanner_mode,
        "Unknown",
        line,
        &ok
    );
    ptn_string_operand_free(input);
    return result;
}

static PtnValue ptn_internal_parse_ini_file(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand filename = ptn_internal_expect_string_arg(runtime, "parse_ini_file", 1, "filename", args[0], line);
    char *path = ptn_duplicate_string_len(filename.data, filename.len);
    ptn_string_operand_free(filename);

    int process_sections = argc >= 2 && ptn_is_truthy(args[1]);
    unsigned char *data = NULL;
    size_t data_len = 0;
    char *opened_path = NULL;
    int read_result = ptn_read_file_bytes_with_search(runtime, "parse_ini_file", path, 1, &data, &data_len, &opened_path, line);
    if (read_result <= 0) {
        char detail[192];
        int needed = snprintf(detail, sizeof(detail), "Failed to open stream: %s", strerror(errno));
        if (needed < 0 || (size_t)needed >= sizeof(detail)) {
            ptn_abort_out_of_memory();
        }
        ptn_emit_file_warning(runtime, "parse_ini_file", path, detail, line);
        free(opened_path);
        free(path);
        free(data);
        return ptn_bool(0);
    }

    int scanner_mode = ptn_ini_scanner_mode_arg(runtime, "parse_ini_file", argc, args, line);
    if (runtime->exceptions->active_exception != NULL) {
        free(opened_path);
        free(path);
        free(data);
        return ptn_null();
    }
    if (scanner_mode < 0) {
        free(opened_path);
        free(path);
        free(data);
        return ptn_bool(0);
    }

    int ok = 1;
    PtnValue result = ptn_ini_parse_contents(
        runtime,
        (const char *)data,
        data_len,
        process_sections,
        scanner_mode,
        opened_path == NULL ? path : opened_path,
        line,
        &ok
    );
    free(opened_path);
    free(path);
    free(data);
    return result;
}

static double ptn_value_to_double(PtnValue value) {
    double fast_number = 0.0;
    if (ptn_fast_scalar_double(value, &fast_number)) {
        return fast_number;
    }

    PtnNumber number = ptn_to_number(value);
    return number.floating;
}

static const char *ptn_numeric_arg_type_name(PtnValue value) {
    value = ptn_value_deref(value);
    if (value.type == PTN_OBJECT) {
        return value.as.object->class_name;
    }
    if (value.type == PTN_EXCEPTION) {
        return value.as.exception->class_name;
    }
    if (value.type == PTN_CLOSURE) {
        return "Closure";
    }
    return ptn_offset_container_type_name(value);
}

static int ptn_numeric_arg_string_to_double(PtnString string, double *out) {
    const char *data = (const char *)string.data;
    const char *limit = data + string.len;
    const char *start = data;
    while (start < limit && isspace((unsigned char)*start)) {
        start++;
    }
    if (start >= limit) {
        return 0;
    }

    const char *cursor = start;
    if (*cursor == '+' || *cursor == '-') {
        cursor++;
        if (cursor >= limit) {
            return 0;
        }
    }
    if (cursor + 1 < limit && cursor[0] == '0' && (cursor[1] == 'x' || cursor[1] == 'X')) {
        return 0;
    }
    if (!isdigit((unsigned char)*cursor) && *cursor != '.') {
        return 0;
    }
    if (*cursor == '.' && (cursor + 1 >= limit || !isdigit((unsigned char)cursor[1]))) {
        return 0;
    }

    char *end = NULL;
    double number = strtod(start, &end);
    if (end == start) {
        return 0;
    }
    while (end < limit && isspace((unsigned char)*end)) {
        end++;
    }
    if (end != limit) {
        return 0;
    }

    *out = number;
    return 1;
}

static PtnNumber ptn_internal_expect_number_arg(
    PtnRuntime *runtime,
    const char *function_name,
    size_t position,
    const char *argument_name,
    const char *expected_type,
    PtnValue value,
    size_t line
) {
    value = ptn_value_deref(value);
    switch (value.type) {
        case PTN_NULL: {
            char message[192];
            int written = snprintf(
                message,
                sizeof(message),
                "%s(): Passing null to parameter #%zu ($%s) of type %s is deprecated",
                function_name,
                position,
                argument_name,
                expected_type
            );
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_emit_deprecation(&runtime->diagnostics, message, line);
            return ptn_number_int(0);
        }
        case PTN_BOOL:
            return ptn_number_int(value.as.boolean ? 1 : 0);
        case PTN_INT:
            return ptn_number_int(value.as.integer);
        case PTN_FLOAT:
            return ptn_number_float(value.as.floating);
        case PTN_STRING: {
            double number = 0.0;
            if (ptn_numeric_arg_string_to_double(value.as.string, &number)) {
                return ptn_string_to_number((const char *)value.as.string.data);
            }
            break;
        }
        case PTN_ARRAY:
        case PTN_OBJECT:
        case PTN_CLOSURE:
        case PTN_EXCEPTION:
        case PTN_RESOURCE:
        case PTN_REFERENCE:
            break;
    }

    char message[192];
    int written = snprintf(
        message,
        sizeof(message),
        "%s(): Argument #%zu ($%s) must be of type %s, %s given",
        function_name,
        position,
        argument_name,
        expected_type,
        ptn_numeric_arg_type_name(value)
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "TypeError", message);
    return ptn_number_int(0);
}

