static PtnValue ptn_internal_flush(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)argc;
    (void)args;
    (void)line;
    fflush(stdout);
    return ptn_null();
}

static PtnValue ptn_internal_exit(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)line;
    int status = 0;
    if (argc >= 1) {
        PtnValue value = ptn_value_deref(args[0]);
        if (value.type == PTN_STRING) {
            if (value.as.string.len != 0) {
                ptn_output_write(runtime, (const char *)value.as.string.data, value.as.string.len);
            }
        } else if (value.type == PTN_INT) {
            status = (int)value.as.integer;
        } else if (value.type == PTN_BOOL) {
            status = value.as.boolean ? 1 : 0;
        } else if (value.type == PTN_FLOAT) {
            status = (int)value.as.floating;
        }
    }
    ptn_output_buffer_flush_all(runtime);
    fflush(stdout);
    exit(status);
    return ptn_null();
}

static PtnValue ptn_internal_die(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_exit(runtime, argc, args, line);
}

static PtnValue ptn_internal_abs(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnNumber number = ptn_internal_expect_number_arg(
        runtime,
        "abs",
        1,
        "num",
        "int|float",
        args[0],
        line
    );
    if (number.type == PTN_NUMBER_FLOAT) {
        return ptn_float(fabs(number.floating));
    }
    if (number.integer == INT64_MIN) {
        return ptn_float(fabs((double)number.integer));
    }
    if (number.integer < 0) {
        return ptn_int(-number.integer);
    }
    return ptn_int(number.integer);
}

