static PtnValue ptn_internal_minmax(
    PtnRuntime *runtime,
    const char *function_name,
    size_t argc,
    const PtnValue *args,
    int want_max,
    size_t line
) {
    PtnValue first = ptn_value_deref(args[0]);
    if (argc == 1) {
        if (first.type != PTN_ARRAY) {
            const char *type_name = first.type == PTN_OBJECT && first.as.object != NULL
                ? first.as.object->class_name
                : ptn_offset_container_type_name(first);
            char message[192];
            int written = snprintf(
                message,
                sizeof(message),
                "%s(): Argument #1 ($value) must be of type array, %s given",
                function_name,
                type_name
            );
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_throw_exception(runtime, "TypeError", message);
            return ptn_null();
        }
        if (first.as.array->len == 0) {
            char message[128];
            int written = snprintf(
                message,
                sizeof(message),
                "%s(): Argument #1 ($value) must contain at least one element",
                function_name
            );
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_throw_exception(runtime, "ValueError", message);
            return ptn_null();
        }
        PtnValue best = ptn_value_clone_deref(first.as.array->entries[0].value);
        for (size_t i = 1; i < first.as.array->len; i++) {
            PtnValue candidate = ptn_value_deref(first.as.array->entries[i].value);
            int compared = ptn_compare_order(runtime, candidate, best, line);
            if ((want_max && compared == PTN_COMPARE_GREATER) ||
                (!want_max && compared == PTN_COMPARE_LESS)) {
                ptn_value_destroy(&best);
                best = ptn_value_clone_deref(candidate);
            }
        }
        return best;
    }

    PtnValue best = ptn_value_clone_deref(args[0]);
    for (size_t i = 1; i < argc; i++) {
        PtnValue candidate = ptn_value_deref(args[i]);
        int compared = ptn_compare_order(runtime, candidate, best, line);
        if ((want_max && compared == PTN_COMPARE_GREATER) ||
            (!want_max && compared == PTN_COMPARE_LESS)) {
            ptn_value_destroy(&best);
            best = ptn_value_clone_deref(candidate);
        }
    }
    return best;
}

static PtnValue ptn_internal_max(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_minmax(runtime, "max", argc, args, 1, line);
}

static PtnValue ptn_internal_min(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_minmax(runtime, "min", argc, args, 0, line);
}

static int ptn_clamp_value_is_nan(PtnValue value) {
    value = ptn_value_deref(value);
    return value.type == PTN_FLOAT && isnan(value.as.floating);
}

static PtnValue ptn_internal_clamp(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnValue value = ptn_value_deref(args[0]);
    PtnValue min = ptn_value_deref(args[1]);
    PtnValue max = ptn_value_deref(args[2]);
    if (ptn_clamp_value_is_nan(min)) {
        ptn_throw_exception(runtime, "ValueError", "clamp(): Argument #2 ($min) must not be NAN");
        return ptn_null();
    }
    if (ptn_clamp_value_is_nan(max)) {
        ptn_throw_exception(runtime, "ValueError", "clamp(): Argument #3 ($max) must not be NAN");
        return ptn_null();
    }

    int max_vs_min = ptn_compare_order(runtime, max, min, line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    if (max_vs_min == PTN_COMPARE_LESS) {
        ptn_throw_exception(
            runtime,
            "ValueError",
            "clamp(): Argument #2 ($min) must be smaller than or equal to argument #3 ($max)"
        );
        return ptn_null();
    }

    int max_vs_value = ptn_compare_order(runtime, max, value, line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    if (max_vs_value == PTN_COMPARE_LESS) {
        return ptn_value_clone_deref(max);
    }

    int value_vs_min = ptn_compare_order(runtime, value, min, line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    if (value_vs_min == PTN_COMPARE_LESS) {
        return ptn_value_clone_deref(min);
    }
    return ptn_value_clone_deref(value);
}

static PtnValue ptn_internal_fdiv(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    double dividend = ptn_internal_expect_float_arg(runtime, "fdiv", 1, "num1", args[0], line);
    double divisor = ptn_internal_expect_float_arg(runtime, "fdiv", 2, "num2", args[1], line);
    return ptn_float(dividend / divisor);
}

static PtnValue ptn_internal_intdiv(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    int64_t dividend = ptn_internal_expect_integer_arg(runtime, "intdiv", 1, "num1", args[0], line);
    int64_t divisor = ptn_internal_expect_integer_arg(runtime, "intdiv", 2, "num2", args[1], line);
    if (divisor == 0) {
        ptn_throw_exception(runtime, "DivisionByZeroError", "Division by zero");
        return ptn_null();
    }
    if (dividend == INT64_MIN && divisor == -1) {
        ptn_throw_exception(runtime, "ArithmeticError", "Division of PHP_INT_MIN by -1 is not an integer");
        return ptn_null();
    }
    return ptn_int(dividend / divisor);
}

