static PtnValue ptn_internal_openssl_spki_new(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    int owned = 0;
    EVP_PKEY *pkey = ptn_openssl_private_key_from_value(runtime, "openssl_spki_new", 1, "private_key", args[0], line, &owned);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    if (pkey == NULL) {
        return ptn_bool(0);
    }
    PtnStringOperand challenge = ptn_internal_expect_string_arg(runtime, "openssl_spki_new", 2, "challenge", args[1], line);
    if (runtime->exceptions->active_exception != NULL) {
        if (owned) {
            EVP_PKEY_free(pkey);
        }
        return ptn_null();
    }
    int64_t algorithm = argc >= 3
        ? ptn_internal_expect_integer_arg(runtime, "openssl_spki_new", 3, "digest_algo", args[2], line)
        : 1;
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(challenge);
        if (owned) {
            EVP_PKEY_free(pkey);
        }
        return ptn_null();
    }
    const EVP_MD *digest = ptn_openssl_digest_from_algorithm(algorithm);
    if (digest == NULL) {
        ptn_string_operand_free(challenge);
        if (owned) {
            EVP_PKEY_free(pkey);
        }
        return ptn_bool(0);
    }

    NETSCAPE_SPKI *spki = NETSCAPE_SPKI_new();
    if (spki == NULL ||
        ASN1_STRING_set(spki->spkac->challenge, challenge.data, (int)challenge.len) != 1 ||
        NETSCAPE_SPKI_set_pubkey(spki, pkey) != 1 ||
        NETSCAPE_SPKI_sign(spki, pkey, digest) <= 0) {
        if (spki != NULL) {
            NETSCAPE_SPKI_free(spki);
        }
        ptn_string_operand_free(challenge);
        if (owned) {
            EVP_PKEY_free(pkey);
        }
        ERR_clear_error();
        return ptn_bool(0);
    }
    char *encoded = NETSCAPE_SPKI_b64_encode(spki);
    NETSCAPE_SPKI_free(spki);
    ptn_string_operand_free(challenge);
    if (owned) {
        EVP_PKEY_free(pkey);
    }
    if (encoded == NULL) {
        ERR_clear_error();
        return ptn_bool(0);
    }
    size_t encoded_len = strlen(encoded);
    const char *prefix = "SPKAC=";
    size_t prefix_len = strlen(prefix);
    char *result = malloc(prefix_len + encoded_len + 1);
    if (result == NULL) {
        OPENSSL_free(encoded);
        ptn_abort_out_of_memory();
    }
    memcpy(result, prefix, prefix_len);
    memcpy(result + prefix_len, encoded, encoded_len + 1);
    OPENSSL_free(encoded);
    return ptn_owned_string_len(result, prefix_len + encoded_len);
}

static PtnValue ptn_internal_openssl_spki_verify(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand spkac_arg = ptn_internal_expect_string_arg(runtime, "openssl_spki_verify", 1, "spki", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    char *spkac = ptn_duplicate_string_len(spkac_arg.data, spkac_arg.len);
    NETSCAPE_SPKI *decoded = NETSCAPE_SPKI_b64_decode(spkac, (int)spkac_arg.len);
    free(spkac);
    ptn_string_operand_free(spkac_arg);
    if (decoded == NULL) {
        ERR_clear_error();
        ptn_emit_warning(&runtime->diagnostics, "openssl_spki_verify(): Unable to decode supplied SPKAC", line);
        return ptn_bool(0);
    }
    EVP_PKEY *pubkey = NETSCAPE_SPKI_get_pubkey(decoded);
    int verified = pubkey != NULL && NETSCAPE_SPKI_verify(decoded, pubkey) == 1;
    if (pubkey != NULL) {
        EVP_PKEY_free(pubkey);
    }
    NETSCAPE_SPKI_free(decoded);
    ERR_clear_error();
    return ptn_bool(verified);
}

static PtnValue ptn_internal_openssl_cms_encrypt(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input_operand = ptn_internal_expect_string_arg(runtime, "openssl_cms_encrypt", 1, "input_filename", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    PtnStringOperand output_operand = ptn_internal_expect_string_arg(runtime, "openssl_cms_encrypt", 2, "output_filename", args[1], line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(input_operand);
        return ptn_null();
    }
    char *input_path = ptn_openssl_path_from_operand(input_operand);
    char *output_path = ptn_openssl_path_from_operand(output_operand);
    ptn_string_operand_free(input_operand);
    ptn_string_operand_free(output_operand);
    if (input_path == NULL || output_path == NULL) {
        free(input_path);
        free(output_path);
        return ptn_bool(0);
    }

    int cert_owned = 0;
    X509 *cert = ptn_openssl_x509_from_value(runtime, "openssl_cms_encrypt", 3, "certificate", args[2], line, &cert_owned);
    if (runtime->exceptions->active_exception != NULL) {
        free(input_path);
        free(output_path);
        return ptn_null();
    }
    if (cert == NULL) {
        free(input_path);
        free(output_path);
        return ptn_bool(0);
    }
    int64_t flags = argc >= 5 ? ptn_internal_expect_integer_arg(runtime, "openssl_cms_encrypt", 5, "flags", args[4], line) : 0;
    int64_t encoding = argc >= 6 ? ptn_internal_expect_integer_arg(runtime, "openssl_cms_encrypt", 6, "encoding", args[5], line) : 1;
    if (runtime->exceptions->active_exception != NULL) {
        if (cert_owned) {
            X509_free(cert);
        }
        free(input_path);
        free(output_path);
        return ptn_null();
    }
    const EVP_CIPHER *cipher = EVP_des_ede3_cbc();
    if (argc >= 7 && ptn_value_deref(args[6]).type != PTN_NULL) {
        PtnStringOperand cipher_name = ptn_internal_expect_string_arg(runtime, "openssl_cms_encrypt", 7, "cipher_algo", args[6], line);
        if (runtime->exceptions->active_exception != NULL) {
            if (cert_owned) {
                X509_free(cert);
            }
            free(input_path);
            free(output_path);
            return ptn_null();
        }
        cipher = ptn_openssl_cipher_from_operand(cipher_name);
        ptn_string_operand_free(cipher_name);
    }
    if (cipher == NULL || encoding != 1) {
        ERR_clear_error();
        if (cert_owned) {
            X509_free(cert);
        }
        free(input_path);
        free(output_path);
        return ptn_bool(0);
    }

    BIO *input = BIO_new_file(input_path, "rb");
    BIO *output = NULL;
    CMS_ContentInfo *cms = NULL;
    STACK_OF(X509) *recipients = NULL;
    int ok = 0;
    if (input != NULL) {
        recipients = sk_X509_new_null();
        if (recipients != NULL && sk_X509_push(recipients, cert) == 1) {
            cms = CMS_encrypt(recipients, input, cipher, (unsigned int)flags);
            if (cms != NULL) {
                (void)BIO_reset(input);
                output = BIO_new_file(output_path, "wb");
                if (output != NULL) {
                    ok = SMIME_write_CMS(output, cms, input, (int)flags) == 1;
                }
            }
        }
    }
    if (output != NULL) {
        BIO_free(output);
    }
    if (cms != NULL) {
        CMS_ContentInfo_free(cms);
    }
    if (recipients != NULL) {
        sk_X509_free(recipients);
    }
    if (input != NULL) {
        BIO_free(input);
    }
    if (cert_owned) {
        X509_free(cert);
    }
    free(input_path);
    free(output_path);
    ERR_clear_error();
    return ptn_bool(ok);
}

static PtnValue ptn_internal_openssl_cms_sign(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input_operand = ptn_internal_expect_string_arg(runtime, "openssl_cms_sign", 1, "input_filename", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    PtnStringOperand output_operand = ptn_internal_expect_string_arg(runtime, "openssl_cms_sign", 2, "output_filename", args[1], line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(input_operand);
        return ptn_null();
    }
    int cert_owned = 0;
    X509 *cert = ptn_openssl_x509_from_value(runtime, "openssl_cms_sign", 3, "certificate", args[2], line, &cert_owned);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(input_operand);
        ptn_string_operand_free(output_operand);
        return ptn_null();
    }
    int pkey_owned = 0;
    EVP_PKEY *pkey = ptn_openssl_private_key_from_value(runtime, "openssl_cms_sign", 4, "private_key", args[3], line, &pkey_owned);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(input_operand);
        ptn_string_operand_free(output_operand);
        if (cert_owned) {
            X509_free(cert);
        }
        return ptn_null();
    }
    if (argc >= 5 && ptn_value_deref(args[4]).type != PTN_NULL) {
        PtnArray *headers = ptn_internal_expect_array_arg(runtime, "openssl_cms_sign", 5, "headers", args[4]);
        if (headers == NULL || runtime->exceptions->active_exception != NULL) {
            ptn_string_operand_free(input_operand);
            ptn_string_operand_free(output_operand);
            if (cert_owned) {
                X509_free(cert);
            }
            if (pkey_owned) {
                EVP_PKEY_free(pkey);
            }
            return ptn_null();
        }
    }
    int64_t flags = argc >= 6 ? ptn_internal_expect_integer_arg(runtime, "openssl_cms_sign", 6, "flags", args[5], line) : 0;
    int64_t encoding = argc >= 7 ? ptn_internal_expect_integer_arg(runtime, "openssl_cms_sign", 7, "encoding", args[6], line) : PTN_OPENSSL_ENCODING_SMIME;
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(input_operand);
        ptn_string_operand_free(output_operand);
        if (cert_owned) {
            X509_free(cert);
        }
        if (pkey_owned) {
            EVP_PKEY_free(pkey);
        }
        return ptn_null();
    }
    char *input_path = ptn_openssl_path_from_operand(input_operand);
    char *output_path = ptn_openssl_path_from_operand(output_operand);
    ptn_string_operand_free(input_operand);
    ptn_string_operand_free(output_operand);
    if (cert == NULL || pkey == NULL || input_path == NULL || output_path == NULL || encoding != PTN_OPENSSL_ENCODING_SMIME) {
        free(input_path);
        free(output_path);
        if (cert_owned) {
            X509_free(cert);
        }
        if (pkey_owned) {
            EVP_PKEY_free(pkey);
        }
        ERR_clear_error();
        return ptn_bool(0);
    }

    BIO *input = BIO_new_file(input_path, "rb");
    BIO *output = NULL;
    CMS_ContentInfo *cms = NULL;
    int ok = 0;
    if (input != NULL) {
        cms = CMS_sign(cert, pkey, NULL, input, (unsigned int)flags);
        if (cms != NULL) {
            (void)BIO_reset(input);
            output = BIO_new_file(output_path, "wb");
            if (output != NULL) {
                ok = SMIME_write_CMS(output, cms, input, (int)flags) == 1;
            }
        }
    }
    if (output != NULL) {
        BIO_free(output);
    }
    if (cms != NULL) {
        CMS_ContentInfo_free(cms);
    }
    if (input != NULL) {
        BIO_free(input);
    }
    if (cert_owned) {
        X509_free(cert);
    }
    if (pkey_owned) {
        EVP_PKEY_free(pkey);
    }
    free(input_path);
    free(output_path);
    ERR_clear_error();
    return ptn_bool(ok);
}

static int ptn_openssl_cms_write_signers(const char *path, CMS_ContentInfo *cms) {
    if (path == NULL) {
        return 1;
    }
    STACK_OF(X509) *signers = CMS_get0_signers(cms);
    BIO *output = BIO_new_file(path, "wb");
    int ok = signers != NULL && output != NULL;
    if (ok) {
        for (int i = 0; i < sk_X509_num(signers); i++) {
            if (PEM_write_bio_X509(output, sk_X509_value(signers, i)) != 1) {
                ok = 0;
                break;
            }
        }
    }
    if (output != NULL) {
        BIO_free(output);
    }
    if (signers != NULL) {
        sk_X509_free(signers);
    }
    return ok;
}

static PtnValue ptn_internal_openssl_cms_verify(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input_operand = ptn_internal_expect_string_arg(runtime, "openssl_cms_verify", 1, "input_filename", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    int64_t flags = argc >= 2 ? ptn_internal_expect_integer_arg(runtime, "openssl_cms_verify", 2, "flags", args[1], line) : 0;
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(input_operand);
        return ptn_null();
    }
    char *certs_path = NULL;
    if (argc >= 3 && ptn_value_deref(args[2]).type != PTN_NULL) {
        PtnStringOperand certs_operand = ptn_internal_expect_string_arg(runtime, "openssl_cms_verify", 3, "certificates", args[2], line);
        if (runtime->exceptions->active_exception != NULL) {
            ptn_string_operand_free(input_operand);
            return ptn_null();
        }
        certs_path = ptn_openssl_path_from_operand(certs_operand);
        ptn_string_operand_free(certs_operand);
    }
    if (argc >= 4 && ptn_value_deref(args[3]).type != PTN_NULL) {
        PtnArray *ca_info = ptn_internal_expect_array_arg(runtime, "openssl_cms_verify", 4, "ca_info", args[3]);
        if (ca_info == NULL || runtime->exceptions->active_exception != NULL) {
            ptn_string_operand_free(input_operand);
            free(certs_path);
            return ptn_null();
        }
        for (size_t i = 0; i < ca_info->len; i++) {
            PtnStringOperand entry = ptn_value_to_string_operand_with_runtime(runtime, ca_info->entries[i].value, line);
            if (runtime->exceptions->active_exception != NULL) {
                ptn_string_operand_free(entry);
                ptn_string_operand_free(input_operand);
                free(certs_path);
                return ptn_null();
            }
            ptn_string_operand_free(entry);
        }
    }
    if (argc >= 5 && ptn_value_deref(args[4]).type != PTN_NULL) {
        PtnStringOperand untrusted = ptn_internal_expect_string_arg(runtime, "openssl_cms_verify", 5, "untrusted_certificates_filename", args[4], line);
        if (runtime->exceptions->active_exception != NULL) {
            ptn_string_operand_free(input_operand);
            free(certs_path);
            return ptn_null();
        }
        ptn_string_operand_free(untrusted);
    }
    char *content_path = NULL;
    if (argc >= 6 && ptn_value_deref(args[5]).type != PTN_NULL) {
        PtnStringOperand content_operand = ptn_internal_expect_string_arg(runtime, "openssl_cms_verify", 6, "content", args[5], line);
        if (runtime->exceptions->active_exception != NULL) {
            ptn_string_operand_free(input_operand);
            free(certs_path);
            return ptn_null();
        }
        content_path = ptn_openssl_path_from_operand(content_operand);
        ptn_string_operand_free(content_operand);
    }
    char *pkcs_path = NULL;
    if (argc >= 7 && ptn_value_deref(args[6]).type != PTN_NULL) {
        PtnStringOperand pkcs_operand = ptn_internal_expect_string_arg(runtime, "openssl_cms_verify", 7, "pk7", args[6], line);
        if (runtime->exceptions->active_exception != NULL) {
            ptn_string_operand_free(input_operand);
            free(certs_path);
            free(content_path);
            return ptn_null();
        }
        pkcs_path = ptn_openssl_path_from_operand(pkcs_operand);
        ptn_string_operand_free(pkcs_operand);
    }
    int64_t encoding = argc >= 9 ? ptn_internal_expect_integer_arg(runtime, "openssl_cms_verify", 9, "encoding", args[8], line) : PTN_OPENSSL_ENCODING_SMIME;
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(input_operand);
        free(certs_path);
        free(content_path);
        free(pkcs_path);
        return ptn_null();
    }
    char *input_path = ptn_openssl_path_from_operand(input_operand);
    ptn_string_operand_free(input_operand);
    if (input_path == NULL || encoding != PTN_OPENSSL_ENCODING_SMIME) {
        free(input_path);
        free(certs_path);
        free(content_path);
        free(pkcs_path);
        return ptn_bool(0);
    }

    BIO *input = BIO_new_file(input_path, "rb");
    BIO *indata = NULL;
    CMS_ContentInfo *cms = input == NULL ? NULL : SMIME_read_CMS(input, &indata);
    BIO *content = NULL;
    int ok = 0;
    if (cms != NULL) {
        content = content_path != NULL ? BIO_new_file(content_path, "wb") : BIO_new(BIO_s_mem());
        ok = content != NULL && CMS_verify(cms, NULL, NULL, indata, content, (unsigned int)flags) == 1;
        if (ok && certs_path != NULL) {
            ok = ptn_openssl_cms_write_signers(certs_path, cms);
        }
        if (ok && pkcs_path != NULL) {
            BIO *pkcs_output = BIO_new_file(pkcs_path, "wb");
            ok = pkcs_output != NULL && PEM_write_bio_CMS_stream(pkcs_output, cms, NULL, 0) == 1;
            if (pkcs_output != NULL) {
                BIO_free(pkcs_output);
            }
        }
    }
    if (content != NULL) {
        BIO_free(content);
    }
    if (cms != NULL) {
        CMS_ContentInfo_free(cms);
    }
    if (indata != NULL) {
        BIO_free(indata);
    }
    if (input != NULL) {
        BIO_free(input);
    }
    free(input_path);
    free(certs_path);
    free(content_path);
    free(pkcs_path);
    ERR_clear_error();
    return ptn_bool(ok);
}

static PtnValue ptn_internal_openssl_cms_decrypt(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand input_operand = ptn_internal_expect_string_arg(runtime, "openssl_cms_decrypt", 1, "input_filename", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    PtnStringOperand output_operand = ptn_internal_expect_string_arg(runtime, "openssl_cms_decrypt", 2, "output_filename", args[1], line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(input_operand);
        return ptn_null();
    }
    char *input_path = ptn_openssl_path_from_operand(input_operand);
    char *output_path = ptn_openssl_path_from_operand(output_operand);
    ptn_string_operand_free(input_operand);
    ptn_string_operand_free(output_operand);
    if (input_path == NULL || output_path == NULL) {
        free(input_path);
        free(output_path);
        return ptn_bool(0);
    }
    int cert_owned = 0;
    int pkey_owned = 0;
    X509 *cert = argc >= 3 && ptn_value_deref(args[2]).type != PTN_NULL
        ? ptn_openssl_x509_from_value(runtime, "openssl_cms_decrypt", 3, "certificate", args[2], line, &cert_owned)
        : NULL;
    if (runtime->exceptions->active_exception != NULL) {
        free(input_path);
        free(output_path);
        return ptn_null();
    }
    EVP_PKEY *pkey = argc >= 4 && ptn_value_deref(args[3]).type != PTN_NULL
        ? ptn_openssl_private_key_from_value(runtime, "openssl_cms_decrypt", 4, "private_key", args[3], line, &pkey_owned)
        : NULL;
    if (runtime->exceptions->active_exception != NULL) {
        if (cert_owned) {
            X509_free(cert);
        }
        free(input_path);
        free(output_path);
        return ptn_null();
    }
    int64_t encoding = argc >= 5 ? ptn_internal_expect_integer_arg(runtime, "openssl_cms_decrypt", 5, "encoding", args[4], line) : 1;
    if (runtime->exceptions->active_exception != NULL) {
        if (cert_owned) {
            X509_free(cert);
        }
        if (pkey_owned) {
            EVP_PKEY_free(pkey);
        }
        free(input_path);
        free(output_path);
        return ptn_null();
    }
    if (cert == NULL || pkey == NULL || encoding != PTN_OPENSSL_ENCODING_SMIME) {
        if (cert == NULL) {
            ptn_emit_warning(
                &runtime->diagnostics,
                "openssl_cms_decrypt(): X.509 Certificate cannot be retrieved",
                line
            );
        }
        if (cert_owned) {
            X509_free(cert);
        }
        if (pkey_owned) {
            EVP_PKEY_free(pkey);
        }
        free(input_path);
        free(output_path);
        return ptn_bool(0);
    }

    BIO *input = BIO_new_file(input_path, "rb");
    BIO *indata = NULL;
    BIO *output = NULL;
    CMS_ContentInfo *cms = input == NULL ? NULL : SMIME_read_CMS(input, &indata);
    int ok = 0;
    if (cms != NULL) {
        output = BIO_new_file(output_path, "wb");
        if (output != NULL) {
            ok = CMS_decrypt(cms, pkey, cert, indata, output, 0) == 1;
        }
    }
    if (output != NULL) {
        BIO_free(output);
    }
    if (cms != NULL) {
        CMS_ContentInfo_free(cms);
    }
    if (indata != NULL) {
        BIO_free(indata);
    }
    if (input != NULL) {
        BIO_free(input);
    }
    if (cert_owned) {
        X509_free(cert);
    }
    if (pkey_owned) {
        EVP_PKEY_free(pkey);
    }
    free(input_path);
    free(output_path);
    ERR_clear_error();
    return ptn_bool(ok);
}
