static int ptn_current_script_stat(PtnRuntime *runtime, struct stat *info) {
    if (runtime == NULL || runtime->source_path == NULL || runtime->source_path[0] == '\0') {
        return 0;
    }
    return stat(runtime->source_path, info) == 0;
}

