        free(root->diagnostics.html_errors_ini_value);
        root->diagnostics.html_errors_ini_value = ptn_duplicate_string(next);
        root->diagnostics.html_errors = ptn_runtime_ini_bool(next, ptn_is_truthy(args[1]));
