static int ptn_constant_name_matches_any(
    const char *name,
    const char *const *names,
    size_t count
) {
    for (size_t i = 0; i < count; i++) {
        if (strcmp(name, names[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

