static const char *ptn_reflection_constant_extension_name(const char *name) {
    if (ptn_reflection_constant_is_bcmath(name)) {
        return "bcmath";
    }
    if (ptn_reflection_constant_is_calendar(name)) {
        return "calendar";
    }
    if (ptn_reflection_constant_is_json(name)) {
        return "json";
    }
    if (ptn_reflection_constant_is_pcre(name)) {
        return "pcre";
    }
    if (ptn_reflection_constant_is_filter(name)) {
        return "filter";
    }
    if (ptn_reflection_constant_is_libxml(name)) {
        return "libxml";
    }
    if (ptn_reflection_constant_is_zlib(name)) {
        return "zlib";
    }
    if (ptn_reflection_constant_is_xml(name)) {
        return "xml";
    }
    if (ptn_reflection_constant_is_mbstring(name)) {
        return "mbstring";
    }
    if (ptn_reflection_constant_is_standard(name)) {
        return "standard";
    }
    if (ptn_reflection_constant_is_sockets(name)) {
        return "sockets";
    }
    if (ptn_reflection_constant_is_curl(name)) {
        return "curl";
    }
    if (ptn_reflection_constant_is_soap(name)) {
        return "soap";
    }
    if (ptn_reflection_constant_is_session(name)) {
        return "session";
    }
    PtnValue value;
    if (ptn_builtin_constant_value(name, &value)) {
        ptn_value_destroy(&value);
        return "Core";
    }
    return NULL;
}

static const char *ptn_internal_constant_deprecated_since(const char *name) {
    name = ptn_symbol_name_without_leading_slash(name);
    if (ptn_ascii_case_equal(name, "E_STRICT")) {
        return "8.4";
    }
    if (ptn_ascii_case_equal(name, "DATE_RFC7231")) {
        return "8.5";
    }
    if (ptn_ascii_case_equal(name, "MT_RAND_PHP")) {
        return "8.3";
    }
    if (
        ptn_ascii_case_equal(name, "ASSERT_ACTIVE") ||
        ptn_ascii_case_equal(name, "ASSERT_CALLBACK") ||
        ptn_ascii_case_equal(name, "ASSERT_BAIL") ||
        ptn_ascii_case_equal(name, "ASSERT_WARNING") ||
        ptn_ascii_case_equal(name, "ASSERT_EXCEPTION")
    ) {
        return "8.3";
    }
    return NULL;
}

static const char *ptn_internal_constant_deprecated_message(const char *name) {
    name = ptn_symbol_name_without_leading_slash(name);
    if (ptn_ascii_case_equal(name, "E_STRICT")) {
        return "the error level was removed";
    }
    if (ptn_ascii_case_equal(name, "DATE_RFC7231")) {
        return "as this format ignores the associated timezone and always uses GMT";
    }
    if (ptn_ascii_case_equal(name, "MT_RAND_PHP")) {
        return "as it uses a biased non-standard variant of Mt19937";
    }
    if (
        ptn_ascii_case_equal(name, "ASSERT_ACTIVE") ||
        ptn_ascii_case_equal(name, "ASSERT_CALLBACK") ||
        ptn_ascii_case_equal(name, "ASSERT_BAIL") ||
        ptn_ascii_case_equal(name, "ASSERT_WARNING") ||
        ptn_ascii_case_equal(name, "ASSERT_EXCEPTION")
    ) {
        return "as assert_options() is deprecated";
    }
    return NULL;
}

static int ptn_internal_constant_is_deprecated(const char *name) {
    return ptn_internal_constant_deprecated_since(name) != NULL;
}

static PtnValue ptn_internal_get_defined_constants(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)line;
    PtnValue core = ptn_defined_constants_core_table();
    if (argc >= 1 && ptn_is_truthy(args[0])) {
        PtnValue categorized = ptn_array_from_literal_entries(0, NULL);
        ptn_array_set_entry(categorized.as.array, ptn_array_string_key("Core"), core);
        ptn_array_set_entry(categorized.as.array, ptn_array_string_key("libxml"), ptn_defined_constants_libxml_table());
        ptn_array_set_entry(categorized.as.array, ptn_array_string_key("zlib"), ptn_defined_constants_zlib_table());
        ptn_array_set_entry(categorized.as.array, ptn_array_string_key("xml"), ptn_defined_constants_xml_table());
        ptn_array_set_entry(categorized.as.array, ptn_array_string_key("bcmath"), ptn_defined_constants_bcmath_table());
        ptn_array_set_entry(categorized.as.array, ptn_array_string_key("calendar"), ptn_defined_constants_calendar_table());
        ptn_array_set_entry(categorized.as.array, ptn_array_string_key("json"), ptn_defined_constants_json_table());
        ptn_array_set_entry(categorized.as.array, ptn_array_string_key("filter"), ptn_defined_constants_filter_table());
        ptn_array_set_entry(categorized.as.array, ptn_array_string_key("mbstring"), ptn_defined_constants_mbstring_table());
        ptn_array_set_entry(categorized.as.array, ptn_array_string_key("openssl"), ptn_defined_constants_openssl_table());
        ptn_array_set_entry(categorized.as.array, ptn_array_string_key("pcre"), ptn_defined_constants_pcre_table());
        ptn_array_set_entry(categorized.as.array, ptn_array_string_key("session"), ptn_defined_constants_session_table());
        ptn_array_set_entry(categorized.as.array, ptn_array_string_key("sockets"), ptn_defined_constants_sockets_table());
        ptn_array_set_entry(categorized.as.array, ptn_array_string_key("curl"), ptn_defined_constants_curl_table());
        ptn_array_set_entry(categorized.as.array, ptn_array_string_key("soap"), ptn_defined_constants_soap_table());
        ptn_array_set_entry(categorized.as.array, ptn_array_string_key("standard"), ptn_defined_constants_standard_table());
        ptn_array_set_entry(categorized.as.array, ptn_array_string_key("user"), ptn_defined_constants_user_table(runtime));
        return categorized;
    }
    ptn_defined_constants_add_libxml(core);
    ptn_defined_constants_add_zlib(core);
    ptn_defined_constants_add_xml(core);
    ptn_defined_constants_add_bcmath(core);
    ptn_defined_constants_add_calendar(core);
    ptn_defined_constants_add_json(core);
    ptn_defined_constants_add_filter(core);
    ptn_defined_constants_add_mbstring(core);
    ptn_defined_constants_add_openssl(core);
    ptn_defined_constants_add_pcre(core);
    ptn_defined_constants_add_session(core);
    ptn_defined_constants_add_sockets(core);
    ptn_defined_constants_add_curl(core);
    ptn_defined_constants_add_soap(core);
    ptn_defined_constants_add_standard(core);
    ptn_defined_constants_add_user(runtime, core);
    return core;
}

static PtnValue ptn_internal_extension_loaded(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)argc;
    (void)line;
    PtnStringOperand extension = ptn_value_to_string_operand(args[0]);
    int loaded = ptn_is_modeled_extension_operand(extension);
    ptn_string_operand_free(extension);
    return ptn_bool(loaded);
}

typedef struct {
    PtnStringBuffer output;
    int exit_code;
} PtnShellCommandResult;

static FILE *ptn_platform_popen(const char *command, const char *mode) {
#if defined(_WIN32)
    return _popen(command, mode);
#else
    return popen(command, mode);
#endif
}

static int ptn_platform_pclose(FILE *stream) {
#if defined(_WIN32)
    return _pclose(stream);
#else
    return pclose(stream);
#endif
}

static int ptn_shell_status_code(int status) {
    if (status == -1) {
        return -1;
    }
#if !defined(_WIN32)
    if (WIFEXITED(status)) {
        return WEXITSTATUS(status);
    }
    if (WIFSIGNALED(status)) {
        return 128 + WTERMSIG(status);
    }
#endif
    return status;
}

static int ptn_shell_validate_command(
    PtnRuntime *runtime,
    const char *function_name,
    PtnStringOperand command
) {
    if (command.len == 0) {
        char message[96];
        int written = snprintf(
            message,
            sizeof(message),
            "%s(): Argument #1 ($command) cannot be empty",
            function_name
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "ValueError", message);
        return 0;
    }
    if (memchr(command.data, '\0', command.len) != NULL) {
        char message[112];
        int written = snprintf(
            message,
            sizeof(message),
            "%s(): Argument #1 ($command) must not contain any null bytes",
            function_name
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "ValueError", message);
        return 0;
    }
    return 1;
}

static int ptn_popen_mode_is_valid(const char *mode) {
    return strcmp(mode, "r") == 0 ||
        strcmp(mode, "rb") == 0 ||
        strcmp(mode, "w") == 0 ||
        strcmp(mode, "wb") == 0;
}

static void ptn_popen_throw_invalid_mode(PtnRuntime *runtime) {
    ptn_throw_exception(
        runtime,
        "ValueError",
        "popen(): Argument #2 ($mode) must be one of \"r\", \"rb\", \"w\", or \"wb\""
    );
}

static void ptn_popen_close_hook(PtnResource *resource, void *data) {
    (void)data;
    if (resource == NULL || resource->stream == NULL) {
        return;
    }
    FILE *stream = resource->stream;
    resource->stream = NULL;
    (void)ptn_platform_pclose(stream);
}

static int ptn_popen_close_resource(PtnResource *resource) {
    if (resource == NULL || resource->stream == NULL) {
        return -1;
    }
    FILE *stream = resource->stream;
    resource->stream = NULL;
    resource->close_hook = NULL;
    int status = ptn_platform_pclose(stream);
    ptn_resource_close(resource);
    return ptn_shell_status_code(status);
}

static PtnValue ptn_internal_popen(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand command = ptn_internal_expect_string_arg(runtime, "popen", 1, "command", args[0], line);
    PtnStringOperand mode_operand = ptn_internal_expect_string_arg(runtime, "popen", 2, "mode", args[1], line);
    char *mode = ptn_path_operand_to_c_string(mode_operand);
    ptn_string_operand_free(mode_operand);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(command);
        free(mode);
        return ptn_null();
    }
    if (mode == NULL) {
        ptn_string_operand_free(command);
        ptn_popen_throw_invalid_mode(runtime);
        return ptn_null();
    }
    if (!ptn_popen_mode_is_valid(mode)) {
        ptn_string_operand_free(command);
        free(mode);
        ptn_popen_throw_invalid_mode(runtime);
        return ptn_null();
    }
    if (!ptn_shell_validate_command(runtime, "popen", command)) {
        ptn_string_operand_free(command);
        free(mode);
        return ptn_null();
    }

    char *command_c = ptn_duplicate_string_len(command.data, command.len);
    ptn_string_operand_free(command);
    FILE *stream = ptn_platform_popen(command_c, mode);
    free(command_c);
    if (stream == NULL) {
        ptn_emit_warning(&runtime->diagnostics, "popen(): Unable to execute command", line);
        free(mode);
        return ptn_bool(0);
    }
    PtnResource *resource = ptn_resource_new_stream(stream, "php://stdio", mode);
    resource->stream_backend = PTN_STREAM_BACKEND_PIPE;
    resource->close_hook = ptn_popen_close_hook;
    PtnValue result = ptn_resource(resource);
    free(mode);
    return result;
}

static PtnValue ptn_internal_pclose(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnValue value = ptn_value_deref(args[0]);
    if (value.type != PTN_RESOURCE) {
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "pclose(): Argument #1 ($handle) must be of type resource, %s given",
            ptn_offset_container_type_name(value)
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "TypeError", message);
        return ptn_null();
    }
    if (!ptn_stream_resource_is_open(value.as.resource)) {
        ptn_throw_exception(
            runtime,
            "TypeError",
            "pclose(): Argument #1 ($handle) must be an open stream resource"
        );
        return ptn_null();
    }
    if (value.as.resource->stream_backend != PTN_STREAM_BACKEND_PIPE ||
        value.as.resource->close_hook != ptn_popen_close_hook) {
        ptn_emit_warning(&runtime->diagnostics, "pclose(): supplied resource is not a valid stream resource", line);
        return ptn_int(-1);
    }
    return ptn_int((int64_t)ptn_popen_close_resource(value.as.resource));
}

static int ptn_shell_run_command(
    PtnRuntime *runtime,
    const char *function_name,
    PtnStringOperand command,
    int emit_output,
    PtnShellCommandResult *result,
    size_t line
) {
    result->exit_code = -1;
    ptn_string_buffer_init(&result->output);
    if (!ptn_shell_validate_command(runtime, function_name, command)) {
        return 0;
    }

    char *command_c = ptn_duplicate_string_len(command.data, command.len);
    FILE *pipe = ptn_platform_popen(command_c, "r");
    free(command_c);
    if (pipe == NULL) {
        char message[128];
        int written = snprintf(message, sizeof(message), "%s(): Unable to execute command", function_name);
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_emit_warning(&runtime->diagnostics, message, line);
        return 0;
    }

    char chunk[4096];
    while (!feof(pipe)) {
        size_t read = fread(chunk, 1, sizeof(chunk), pipe);
        if (read != 0) {
            ptn_string_buffer_append_len(&result->output, chunk, read);
            if (emit_output) {
                ptn_output_write(runtime, chunk, read);
            }
        }
        if (ferror(pipe)) {
            break;
        }
    }

    int read_failed = ferror(pipe);
    int status = ptn_platform_pclose(pipe);
    result->exit_code = ptn_shell_status_code(status);
    if (read_failed) {
        char message[128];
        int written = snprintf(message, sizeof(message), "%s(): Failed reading command output", function_name);
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_emit_warning(&runtime->diagnostics, message, line);
        return 0;
    }
    return 1;
}

static PtnValue ptn_shell_last_line_value(PtnStringBuffer *output, int trim_trailing_whitespace) {
    size_t end = output->len;
    while (end > 0 && (output->data[end - 1] == '\n' || output->data[end - 1] == '\r')) {
        end--;
    }
    if (trim_trailing_whitespace) {
        while (end > 0 && isspace((unsigned char)output->data[end - 1])) {
            end--;
        }
    }
    size_t start = end;
    while (start > 0 && output->data[start - 1] != '\n' && output->data[start - 1] != '\r') {
        start--;
    }
    char *line = ptn_duplicate_string_len(output->data == NULL ? "" : output->data + start, end - start);
    return ptn_owned_string_len(line, end - start);
}

static void ptn_shell_copy_existing_output_array(PtnValue output_array, PtnValue *target) {
    output_array = ptn_value_deref(output_array);
    if (output_array.type != PTN_ARRAY) {
        return;
    }
    for (size_t i = 0; i < output_array.as.array->len; i++) {
        PtnArrayEntry *entry = &output_array.as.array->entries[i];
        ptn_array_set_entry(target->as.array, ptn_array_key_clone(entry->key), ptn_value_clone_deref(entry->value));
    }
}

static PtnValue ptn_shell_output_lines_array(PtnRuntime *runtime, PtnStringBuffer *output, PtnValue existing_output) {
    PtnValue existing = ptn_value_deref(existing_output);
    if (existing.type != PTN_NULL && existing.type != PTN_ARRAY) {
        ptn_throw_exception(runtime, "TypeError", "exec(): Argument #2 ($output) must be of type array, string given");
        return ptn_null();
    }

    PtnValue lines = ptn_array_from_literal_entries(0, NULL);
    ptn_shell_copy_existing_output_array(existing, &lines);
    size_t cursor = 0;
    while (cursor < output->len) {
        size_t line_start = cursor;
        while (cursor < output->len && output->data[cursor] != '\n') {
            cursor++;
        }
        size_t line_end = cursor;
        while (line_end > line_start && isspace((unsigned char)output->data[line_end - 1])) {
            line_end--;
        }
        char *line = ptn_duplicate_string_len(output->data + line_start, line_end - line_start);
        ptn_array_set_entry(
            lines.as.array,
            ptn_array_int_key(lines.as.array->next_auto_key),
            ptn_owned_string_len(line, line_end - line_start)
        );
        if (cursor < output->len && output->data[cursor] == '\n') {
            cursor++;
        }
    }
    return lines;
}

static PtnValue ptn_internal_exec(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand command = ptn_internal_expect_string_arg(runtime, "exec", 1, "command", args[0], line);
    PtnShellCommandResult command_result;
    int ok = ptn_shell_run_command(runtime, "exec", command, 0, &command_result, line);
    ptn_string_operand_free(command);
    if (!ok) {
        free(command_result.output.data);
        return ptn_bool(0);
    }

    PtnValue last_line = ptn_shell_last_line_value(&command_result.output, 1);
    if (argc >= 2 && args[1].type == PTN_REFERENCE) {
        PtnValue lines = ptn_shell_output_lines_array(runtime, &command_result.output, args[1].as.reference->value);
        if (runtime->exceptions->active_exception != NULL) {
            ptn_value_destroy(&last_line);
            free(command_result.output.data);
            return ptn_null();
        }
        ptn_reference_assign(runtime, args[1].as.reference, lines);
        ptn_value_destroy(&lines);
    }
    if (argc >= 3 && args[2].type == PTN_REFERENCE) {
        PtnValue status = ptn_int((int64_t)command_result.exit_code);
        ptn_reference_assign(runtime, args[2].as.reference, status);
    }
    free(command_result.output.data);
    return last_line;
}

static PtnValue ptn_internal_system(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand command = ptn_internal_expect_string_arg(runtime, "system", 1, "command", args[0], line);
    PtnShellCommandResult command_result;
    int ok = ptn_shell_run_command(runtime, "system", command, 1, &command_result, line);
    ptn_string_operand_free(command);
    if (!ok) {
        free(command_result.output.data);
        return ptn_bool(0);
    }

    if (argc >= 2 && args[1].type == PTN_REFERENCE) {
        PtnValue status = ptn_int((int64_t)command_result.exit_code);
        ptn_reference_assign(runtime, args[1].as.reference, status);
    }
    PtnValue last_line = ptn_shell_last_line_value(&command_result.output, 0);
    free(command_result.output.data);
    return last_line;
}

static PtnValue ptn_internal_passthru(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand command = ptn_internal_expect_string_arg(runtime, "passthru", 1, "command", args[0], line);
    PtnShellCommandResult command_result;
    int ok = ptn_shell_run_command(runtime, "passthru", command, 1, &command_result, line);
    ptn_string_operand_free(command);
    if (!ok) {
        free(command_result.output.data);
        return ptn_bool(0);
    }

    if (argc >= 2 && args[1].type == PTN_REFERENCE) {
        PtnValue status = ptn_int((int64_t)command_result.exit_code);
        ptn_reference_assign(runtime, args[1].as.reference, status);
    }
    free(command_result.output.data);
    return ptn_null();
}

static PtnValue ptn_internal_shell_exec(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand command = ptn_internal_expect_string_arg(runtime, "shell_exec", 1, "command", args[0], line);
    PtnShellCommandResult command_result;
    int ok = ptn_shell_run_command(runtime, "shell_exec", command, 0, &command_result, line);
    ptn_string_operand_free(command);
    if (!ok) {
        free(command_result.output.data);
        return ptn_bool(0);
    }
    if (command_result.output.len == 0) {
        free(command_result.output.data);
        return ptn_null();
    }
    return ptn_owned_string_len(command_result.output.data, command_result.output.len);
}

static PtnValue ptn_internal_backtick_exec(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    ptn_emit_deprecation(&runtime->diagnostics, "The backtick (`) operator is deprecated, use shell_exec() instead", line);
    return ptn_internal_shell_exec(runtime, argc, args, line);
}

typedef struct {
    pid_t pid;
    char *command;
    int closed;
    int has_status;
    int status;
    PtnResource **pipes;
    size_t pipe_count;
    size_t pipe_capacity;
} PtnProcessData;

typedef struct {
    int target_fd;
    int child_fd;
    int parent_fd;
    char parent_mode[3];
    int has_parent;
    int is_redirect;
    int redirect_fd;
} PtnProcessDescriptor;

typedef struct {
    PtnProcessDescriptor *items;
    size_t len;
    size_t capacity;
} PtnProcessDescriptorList;

static void ptn_process_descriptor_list_init(PtnProcessDescriptorList *list) {
    list->items = NULL;
    list->len = 0;
    list->capacity = 0;
}

static void ptn_process_descriptor_list_free(PtnProcessDescriptorList *list) {
    if (list == NULL) {
        return;
    }
    for (size_t i = 0; i < list->len; i++) {
        if (list->items[i].child_fd >= 0) {
            close(list->items[i].child_fd);
        }
        if (list->items[i].parent_fd >= 0) {
            close(list->items[i].parent_fd);
        }
    }
    free(list->items);
    list->items = NULL;
    list->len = 0;
    list->capacity = 0;
}

static PtnProcessDescriptor *ptn_process_descriptor_list_add(
    PtnProcessDescriptorList *list,
    int target_fd
) {
    if (list->len == list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 8 : list->capacity * 2;
        if (new_capacity < list->capacity ||
            new_capacity > SIZE_MAX / sizeof(PtnProcessDescriptor)) {
            ptn_abort_out_of_memory();
        }
        PtnProcessDescriptor *new_items =
            realloc(list->items, new_capacity * sizeof(PtnProcessDescriptor));
        if (new_items == NULL) {
            ptn_abort_out_of_memory();
        }
        list->items = new_items;
        list->capacity = new_capacity;
    }
    PtnProcessDescriptor *descriptor = &list->items[list->len++];
    descriptor->target_fd = target_fd;
    descriptor->child_fd = -1;
    descriptor->parent_fd = -1;
    descriptor->parent_mode[0] = '\0';
    descriptor->has_parent = 0;
    descriptor->is_redirect = 0;
    descriptor->redirect_fd = -1;
    return descriptor;
}

static PtnProcessDescriptor *ptn_process_descriptor_find(
    PtnProcessDescriptorList *list,
    int target_fd
) {
    for (size_t i = 0; i < list->len; i++) {
        if (list->items[i].target_fd == target_fd) {
            return &list->items[i];
        }
    }
    return NULL;
}

static int ptn_process_array_key_fd(PtnArrayKey key, int *fd_out) {
    int64_t fd = 0;
    if (key.type == PTN_ARRAY_KEY_INT) {
        fd = key.as.integer;
    } else {
        if (!ptn_string_is_integer_array_key_len(key.as.string, key.string_len, &fd)) {
            return 0;
        }
    }
    if (fd < 0 || fd > INT_MAX) {
        return 0;
    }
    *fd_out = (int)fd;
    return 1;
}

static int ptn_process_set_pipe_descriptor(
    PtnProcessDescriptor *descriptor,
    int child_reads,
    int socket_pair
) {
    int fds[2] = { -1, -1 };
    if (socket_pair) {
        if (socketpair(AF_UNIX, SOCK_STREAM, 0, fds) != 0) {
            return 0;
        }
        descriptor->child_fd = fds[0];
        descriptor->parent_fd = fds[1];
        descriptor->parent_mode[0] = 'r';
        descriptor->parent_mode[1] = '+';
        descriptor->parent_mode[2] = '\0';
    } else {
        if (pipe(fds) != 0) {
            return 0;
        }
        if (child_reads) {
            descriptor->child_fd = fds[0];
            descriptor->parent_fd = fds[1];
            descriptor->parent_mode[0] = 'w';
            descriptor->parent_mode[1] = '\0';
        } else {
            descriptor->child_fd = fds[1];
            descriptor->parent_fd = fds[0];
            descriptor->parent_mode[0] = 'r';
            descriptor->parent_mode[1] = '\0';
        }
    }
    descriptor->has_parent = 1;
    return 1;
}

static int ptn_process_open_null_descriptor(PtnProcessDescriptor *descriptor) {
    int flags = descriptor->target_fd == STDIN_FILENO ? O_RDONLY : O_WRONLY;
    int fd = open("/dev/null", flags);
    if (fd < 0 && flags == O_WRONLY) {
        fd = open("/dev/null", O_RDWR);
    }
    if (fd < 0) {
        return 0;
    }
    descriptor->child_fd = fd;
    return 1;
}

static int ptn_process_open_file_descriptor(
    PtnRuntime *runtime,
    PtnProcessDescriptor *descriptor,
    PtnValue path_value,
    PtnValue mode_value,
    size_t line
) {
    PtnStringOperand path_operand =
        ptn_internal_expect_string_arg(runtime, "proc_open", 2, "descriptor_spec", path_value, line);
    char *path = ptn_fopen_path_operand_to_c_string(path_operand);
    ptn_string_operand_free(path_operand);
    if (runtime->exceptions->active_exception != NULL) {
        free(path);
        return 0;
    }
    if (path == NULL) {
        ptn_emit_warning(&runtime->diagnostics, "proc_open(): Filename contains null byte", line);
        return 0;
    }

    PtnStringOperand mode_operand =
        ptn_internal_expect_string_arg(runtime, "proc_open", 2, "descriptor_spec", mode_value, line);
    char *mode = ptn_path_operand_to_c_string(mode_operand);
    ptn_string_operand_free(mode_operand);
    if (runtime->exceptions->active_exception != NULL) {
        free(path);
        free(mode);
        return 0;
    }
    if (mode == NULL) {
        ptn_emit_warning(&runtime->diagnostics, "proc_open(): file descriptor mode must not contain any null bytes", line);
        free(path);
        return 0;
    }

    char *c_mode = ptn_fopen_c_mode(mode);
    FILE *stream = fopen(path, c_mode);
    free(c_mode);
    free(mode);
    if (stream == NULL) {
        char detail[192];
        int written = snprintf(detail, sizeof(detail), "Failed to open stream: %s", strerror(errno));
        if (written < 0 || (size_t)written >= sizeof(detail)) {
            ptn_abort_out_of_memory();
        }
        ptn_emit_file_warning(runtime, "proc_open", path, detail, line);
        free(path);
        return 0;
    }
    int fd = dup(fileno(stream));
    fclose(stream);
    free(path);
    if (fd < 0) {
        return 0;
    }
    descriptor->child_fd = fd;
    return 1;
}

static int ptn_process_open_stream_descriptor(PtnProcessDescriptor *descriptor, PtnResource *resource) {
    if (resource == NULL || !ptn_stream_resource_is_open(resource) || resource->stream == NULL) {
        return 0;
    }
    (void)fflush(resource->stream);
    int fd = dup(fileno(resource->stream));
    if (fd < 0) {
        return 0;
    }
    descriptor->child_fd = fd;
    return 1;
}

static int ptn_process_descriptor_is_available(
    PtnProcessDescriptorList *list,
    int target_fd
) {
    if (target_fd >= 0 && target_fd <= STDERR_FILENO) {
        return 1;
    }
    return ptn_process_descriptor_find(list, target_fd) != NULL;
}

static int ptn_process_parse_descriptor_array(
    PtnRuntime *runtime,
    PtnProcessDescriptorList *list,
    PtnProcessDescriptor *descriptor,
    PtnArray *spec,
    size_t line
) {
    if (spec->len == 0) {
        ptn_emit_warning(&runtime->diagnostics, "proc_open():  is not a valid descriptor spec/mode", line);
        return 0;
    }

    PtnStringOperand kind_operand =
        ptn_value_to_string_operand_with_runtime(runtime, spec->entries[0].value, line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(kind_operand);
        return 0;
    }
    char *kind = ptn_duplicate_string_len(kind_operand.data, kind_operand.len);
    ptn_string_operand_free(kind_operand);

    if (ptn_ascii_case_equal(kind, "pipe")) {
        int child_reads = 1;
        if (spec->len >= 2) {
            PtnStringOperand mode =
                ptn_value_to_string_operand_with_runtime(runtime, spec->entries[1].value, line);
            if (runtime->exceptions->active_exception != NULL) {
                ptn_string_operand_free(mode);
                free(kind);
                return 0;
            }
            child_reads = memchr(mode.data, 'w', mode.len) == NULL &&
                memchr(mode.data, 'W', mode.len) == NULL;
            ptn_string_operand_free(mode);
        }
        free(kind);
        return ptn_process_set_pipe_descriptor(descriptor, child_reads, 0);
    }

    if (ptn_ascii_case_equal(kind, "socket")) {
        free(kind);
        return ptn_process_set_pipe_descriptor(descriptor, 0, 1);
    }

    if (ptn_ascii_case_equal(kind, "null")) {
        free(kind);
        return ptn_process_open_null_descriptor(descriptor);
    }

    if (ptn_ascii_case_equal(kind, "file")) {
        free(kind);
        if (spec->len < 3) {
            ptn_emit_warning(&runtime->diagnostics, "proc_open(): file descriptor spec must include path and mode", line);
            return 0;
        }
        return ptn_process_open_file_descriptor(
            runtime,
            descriptor,
            spec->entries[1].value,
            spec->entries[2].value,
            line
        );
    }

    if (ptn_ascii_case_equal(kind, "redirect")) {
        free(kind);
        if (spec->len < 2) {
            ptn_throw_exception(runtime, "ValueError", "Missing redirection target");
            return 0;
        }
        PtnValue target = ptn_value_deref(spec->entries[1].value);
        if (target.type != PTN_INT) {
            char message[128];
            int written = snprintf(
                message,
                sizeof(message),
                "Redirection target must be of type int, %s given",
                ptn_offset_container_type_name(target)
            );
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_throw_exception(runtime, "ValueError", message);
            return 0;
        }
        if (target.as.integer < 0 || target.as.integer > INT_MAX ||
            !ptn_process_descriptor_is_available(list, (int)target.as.integer)) {
            char message[128];
            int written = snprintf(
                message,
                sizeof(message),
                "proc_open(): Redirection target %lld not found",
                (long long)target.as.integer
            );
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_emit_warning(&runtime->diagnostics, message, line);
            return 0;
        }
        descriptor->is_redirect = 1;
        descriptor->redirect_fd = (int)target.as.integer;
        return 1;
    }

    char message[192];
    int written = snprintf(
        message,
        sizeof(message),
        "proc_open(): %s is not a valid descriptor spec/mode",
        kind
    );
    free(kind);
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_warning(&runtime->diagnostics, message, line);
    return 0;
}

static int ptn_process_parse_descriptor_spec(
    PtnRuntime *runtime,
    PtnValue descriptor_spec,
    PtnProcessDescriptorList *list,
    size_t line
) {
    PtnValue value = ptn_value_deref(descriptor_spec);
    if (value.type != PTN_ARRAY) {
        char message[160];
        int written = snprintf(
            message,
            sizeof(message),
            "proc_open(): Argument #2 ($descriptor_spec) must be of type array, %s given",
            ptn_offset_container_type_name(value)
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "TypeError", message);
        return 0;
    }

    PtnArray *array = value.as.array;
    for (size_t i = 0; i < array->len; i++) {
        int target_fd = 0;
        if (!ptn_process_array_key_fd(array->entries[i].key, &target_fd)) {
            continue;
        }
        PtnValue spec = ptn_value_deref(array->entries[i].value);
        PtnProcessDescriptor *descriptor =
            ptn_process_descriptor_list_add(list, target_fd);
        if (spec.type == PTN_ARRAY) {
            if (!ptn_process_parse_descriptor_array(runtime, list, descriptor, spec.as.array, line)) {
                return 0;
            }
        } else if (spec.type == PTN_RESOURCE) {
            if (!ptn_process_open_stream_descriptor(descriptor, spec.as.resource)) {
                ptn_emit_warning(&runtime->diagnostics, "proc_open(): supplied stream descriptor is not valid", line);
                return 0;
            }
        } else {
            ptn_throw_exception(
                runtime,
                "ValueError",
                "proc_open(): Argument #2 ($descriptor_spec) must only contain arrays and streams"
            );
            return 0;
        }
    }
    return 1;
}

static void ptn_process_data_retain_pipe(PtnProcessData *data, PtnResource *resource) {
    if (data == NULL || resource == NULL) {
        return;
    }
    if (data->pipe_count == data->pipe_capacity) {
        size_t new_capacity = data->pipe_capacity == 0 ? 4 : data->pipe_capacity * 2;
        if (new_capacity < data->pipe_capacity ||
            new_capacity > SIZE_MAX / sizeof(PtnResource *)) {
            ptn_abort_out_of_memory();
        }
        PtnResource **new_pipes = realloc(data->pipes, new_capacity * sizeof(PtnResource *));
        if (new_pipes == NULL) {
            ptn_abort_out_of_memory();
        }
        data->pipes = new_pipes;
        data->pipe_capacity = new_capacity;
    }
    ptn_resource_retain(resource);
    data->pipes[data->pipe_count++] = resource;
}

static void ptn_process_data_close_pipes(PtnProcessData *data) {
    if (data == NULL) {
        return;
    }
    for (size_t i = 0; i < data->pipe_count; i++) {
        ptn_resource_close(data->pipes[i]);
    }
}

static int ptn_process_wait(PtnProcessData *data) {
    if (data == NULL) {
        return -1;
    }
    if (data->has_status) {
        return ptn_shell_status_code(data->status);
    }
    int status = 0;
    while (waitpid(data->pid, &status, 0) < 0) {
        if (errno == EINTR) {
            continue;
        }
        return -1;
    }
    data->status = status;
    data->has_status = 1;
    return ptn_shell_status_code(status);
}

static int ptn_process_poll(PtnProcessData *data) {
    if (data == NULL || data->has_status) {
        return 0;
    }
    int status = 0;
    pid_t result;
    do {
        result = waitpid(data->pid, &status, WNOHANG | WUNTRACED);
    } while (result < 0 && errno == EINTR);
    if (result == data->pid) {
        data->status = status;
        data->has_status = 1;
        return 0;
    }
    return result == 0;
}

static void ptn_process_close_hook(PtnResource *resource, void *hook_data) {
    (void)resource;
    PtnProcessData *data = (PtnProcessData *)hook_data;
    if (data == NULL || data->closed) {
        return;
    }
    data->closed = 1;
    ptn_process_data_close_pipes(data);
    (void)ptn_process_wait(data);
}

static void ptn_process_data_free(void *hook_data) {
    PtnProcessData *data = (PtnProcessData *)hook_data;
    if (data == NULL) {
        return;
    }
    for (size_t i = 0; i < data->pipe_count; i++) {
        ptn_resource_release(data->pipes[i]);
    }
    free(data->pipes);
    free(data->command);
    free(data);
}

static PtnProcessData *ptn_process_data_from_value(
    PtnRuntime *runtime,
    const char *function_name,
    PtnValue value
) {
    value = ptn_value_deref(value);
    if (value.type != PTN_RESOURCE ||
        strcmp(value.as.resource->type_name, "process") != 0 ||
        value.as.resource->close_hook_data == NULL) {
        char message[128];
        int written = snprintf(
            message,
            sizeof(message),
            "%s(): supplied resource is not a valid process resource",
            function_name
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "TypeError", message);
        return NULL;
    }
    return (PtnProcessData *)value.as.resource->close_hook_data;
}

static char **ptn_process_build_argv(
    PtnRuntime *runtime,
    PtnValue command,
    char **display_command_out,
    size_t line
) {
    PtnValue value = ptn_value_deref(command);
    if (value.type != PTN_ARRAY) {
        return NULL;
    }
    PtnArray *array = value.as.array;
    if (array->len == 0) {
        ptn_throw_exception(runtime, "ValueError", "proc_open(): Argument #1 ($command) must not be empty");
        return NULL;
    }
    if (array->len > (SIZE_MAX / sizeof(char *)) - 1) {
        ptn_abort_out_of_memory();
    }
    char **argv = calloc(array->len + 1, sizeof(char *));
    if (argv == NULL) {
        ptn_abort_out_of_memory();
    }
    for (size_t i = 0; i < array->len; i++) {
        PtnStringOperand operand =
            ptn_value_to_string_operand_with_runtime(runtime, array->entries[i].value, line);
        if (runtime->exceptions->active_exception != NULL) {
            ptn_string_operand_free(operand);
            for (size_t j = 0; j < i; j++) {
                free(argv[j]);
            }
            free(argv);
            return NULL;
        }
        if (memchr(operand.data, '\0', operand.len) != NULL) {
            char message[96];
            int written = snprintf(
                message,
                sizeof(message),
                "Command array element %zu contains a null byte",
                i + 1
            );
            ptn_string_operand_free(operand);
            for (size_t j = 0; j < i; j++) {
                free(argv[j]);
            }
            free(argv);
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_throw_exception(runtime, "ValueError", message);
            return NULL;
        }
        if (i == 0 && operand.len == 0) {
            ptn_string_operand_free(operand);
            free(argv);
            ptn_throw_exception(runtime, "ValueError", "First element must contain a non-empty program name");
            return NULL;
        }
        argv[i] = ptn_duplicate_string_len(operand.data, operand.len);
        if (i == 0) {
            *display_command_out = ptn_duplicate_string_len(operand.data, operand.len);
        }
        ptn_string_operand_free(operand);
    }
    argv[array->len] = NULL;
    return argv;
}

static void ptn_process_free_argv(char **argv) {
    if (argv == NULL) {
        return;
    }
    for (size_t i = 0; argv[i] != NULL; i++) {
        free(argv[i]);
    }
    free(argv);
}

static char *ptn_process_env_key(PtnArrayKey key) {
    if (key.type == PTN_ARRAY_KEY_STRING) {
        return ptn_duplicate_string_len(key.as.string, key.string_len);
    }
    char buffer[64];
    int written = snprintf(buffer, sizeof(buffer), "%lld", (long long)key.as.integer);
    if (written < 0 || (size_t)written >= sizeof(buffer)) {
        ptn_abort_out_of_memory();
    }
    return ptn_duplicate_string(buffer);
}

static char **ptn_process_build_envp(PtnRuntime *runtime, PtnValue env_value, size_t line) {
    PtnValue env = ptn_value_deref(env_value);
    if (env.type == PTN_NULL) {
        return NULL;
    }
    if (env.type != PTN_ARRAY) {
        ptn_throw_exception(
            runtime,
            "TypeError",
            "proc_open(): Argument #5 ($env_vars) must be of type ?array, string given"
        );
        return NULL;
    }
    PtnArray *array = env.as.array;
    if (array->len > (SIZE_MAX / sizeof(char *)) - 1) {
        ptn_abort_out_of_memory();
    }
    char **envp = calloc(array->len + 1, sizeof(char *));
    if (envp == NULL) {
        ptn_abort_out_of_memory();
    }
    for (size_t i = 0; i < array->len; i++) {
        char *key = ptn_process_env_key(array->entries[i].key);
        PtnStringOperand value =
            ptn_value_to_string_operand_with_runtime(runtime, array->entries[i].value, line);
        if (runtime->exceptions->active_exception != NULL) {
            ptn_string_operand_free(value);
            free(key);
            for (size_t j = 0; j < i; j++) {
                free(envp[j]);
            }
            free(envp);
            return NULL;
        }
        if (memchr(key, '\0', strlen(key)) != NULL ||
            memchr(value.data, '\0', value.len) != NULL) {
            ptn_string_operand_free(value);
            free(key);
            continue;
        }
        size_t key_len = strlen(key);
        if (key_len > SIZE_MAX - value.len - 2) {
            ptn_abort_out_of_memory();
        }
        envp[i] = malloc(key_len + value.len + 2);
        if (envp[i] == NULL) {
            ptn_abort_out_of_memory();
        }
        memcpy(envp[i], key, key_len);
        envp[i][key_len] = '=';
        memcpy(envp[i] + key_len + 1, value.data, value.len);
        envp[i][key_len + value.len + 1] = '\0';
        ptn_string_operand_free(value);
        free(key);
    }
    envp[array->len] = NULL;
    return envp;
}

static void ptn_process_free_envp(char **envp) {
    if (envp == NULL) {
        return;
    }
    for (size_t i = 0; envp[i] != NULL; i++) {
        free(envp[i]);
    }
    free(envp);
}

static const char *ptn_process_env_lookup(char **envp, const char *name) {
    size_t name_len = strlen(name);
    char **source = envp == NULL ? PTN_ENVIRON : envp;
    if (source == NULL) {
        return NULL;
    }
    for (size_t i = 0; source[i] != NULL; i++) {
        if (strncmp(source[i], name, name_len) == 0 && source[i][name_len] == '=') {
            return source[i] + name_len + 1;
        }
    }
    return NULL;
}

static void ptn_process_exec_path_search(char **argv, char **envp) {
    const char *program = argv[0];
    if (strchr(program, '/') != NULL) {
        execve(program, argv, envp == NULL ? PTN_ENVIRON : envp);
        return;
    }
    const char *path = ptn_process_env_lookup(envp, "PATH");
    if (path == NULL || path[0] == '\0') {
        path = "/bin:/usr/bin";
    }
    const char *cursor = path;
    while (1) {
        const char *colon = strchr(cursor, ':');
        size_t dir_len = colon == NULL ? strlen(cursor) : (size_t)(colon - cursor);
        size_t program_len = strlen(program);
        char *candidate = malloc(dir_len + program_len + 2);
        if (candidate == NULL) {
            _exit(127);
        }
        if (dir_len == 0) {
            candidate[0] = '.';
            candidate[1] = '/';
            memcpy(candidate + 2, program, program_len + 1);
        } else {
            memcpy(candidate, cursor, dir_len);
            candidate[dir_len] = '/';
            memcpy(candidate + dir_len + 1, program, program_len + 1);
        }
        execve(candidate, argv, envp == NULL ? PTN_ENVIRON : envp);
        free(candidate);
        if (colon == NULL) {
            break;
        }
        cursor = colon + 1;
    }
}

static void ptn_process_child_apply_descriptors(PtnProcessDescriptorList *list) {
    for (size_t i = 0; i < list->len; i++) {
        PtnProcessDescriptor *descriptor = &list->items[i];
        if (descriptor->is_redirect || descriptor->child_fd < 0) {
            continue;
        }
        if (descriptor->child_fd != descriptor->target_fd) {
            if (dup2(descriptor->child_fd, descriptor->target_fd) < 0) {
                _exit(127);
            }
        }
    }
    for (size_t i = 0; i < list->len; i++) {
        PtnProcessDescriptor *descriptor = &list->items[i];
        if (!descriptor->is_redirect) {
            continue;
        }
        if (dup2(descriptor->redirect_fd, descriptor->target_fd) < 0) {
            _exit(127);
        }
    }
    for (size_t i = 0; i < list->len; i++) {
        PtnProcessDescriptor *descriptor = &list->items[i];
        if (descriptor->parent_fd >= 0) {
            close(descriptor->parent_fd);
        }
        if (descriptor->child_fd >= 0 && descriptor->child_fd != descriptor->target_fd) {
            close(descriptor->child_fd);
        }
    }
}

static PtnValue ptn_process_parent_streams_value(
    PtnRuntime *runtime,
    PtnProcessDescriptorList *list,
    PtnProcessData *process_data,
    pid_t child,
    size_t line
) {
    PtnValue pipes = ptn_array_from_literal_entries(0, NULL);
    for (size_t i = 0; i < list->len; i++) {
        PtnProcessDescriptor *descriptor = &list->items[i];
        if (!descriptor->has_parent || descriptor->parent_fd < 0) {
            continue;
        }
        char uri[64];
        int written = snprintf(uri, sizeof(uri), "php://fd/%d", descriptor->parent_fd);
        if (written < 0 || (size_t)written >= sizeof(uri)) {
            ptn_abort_out_of_memory();
        }
        FILE *stream = fdopen(descriptor->parent_fd, descriptor->parent_mode);
        descriptor->parent_fd = -1;
        if (stream == NULL) {
            kill(child, SIGTERM);
            (void)waitpid(child, NULL, 0);
            ptn_value_destroy(&pipes);
            ptn_emit_warning(&runtime->diagnostics, "proc_open(): unable to open parent pipe stream", line);
            return ptn_bool(0);
        }
        PtnResource *resource = ptn_resource_new_stream(stream, uri, descriptor->parent_mode);
        resource->stream_backend = PTN_STREAM_BACKEND_PIPE;
        ptn_process_data_retain_pipe(process_data, resource);
        ptn_array_set_entry(
            pipes.as.array,
            ptn_array_int_key((int64_t)descriptor->target_fd),
            ptn_resource(resource)
        );
    }
    return pipes;
}

static char *ptn_process_cwd_arg(
    PtnRuntime *runtime,
    size_t argc,
    const PtnValue *args,
    size_t line
) {
    if (argc < 4 || ptn_value_deref(args[3]).type == PTN_NULL) {
        return NULL;
    }
    PtnStringOperand cwd = ptn_internal_expect_string_arg(runtime, "proc_open", 4, "cwd", args[3], line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(cwd);
        return NULL;
    }
    if (memchr(cwd.data, '\0', cwd.len) != NULL) {
        ptn_string_operand_free(cwd);
        ptn_throw_exception(
            runtime,
            "ValueError",
            "proc_open(): Argument #4 ($cwd) must not contain any null bytes"
        );
        return NULL;
    }
    char *result = ptn_duplicate_string_len(cwd.data, cwd.len);
    ptn_string_operand_free(cwd);
    return result;
}

static PtnValue ptn_internal_proc_open(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnValue command_value = ptn_value_deref(args[0]);
    int command_is_array = command_value.type == PTN_ARRAY;
    char *display_command = NULL;
    char **argv = NULL;
    PtnStringOperand command_string = {0};
    if (command_is_array) {
        argv = ptn_process_build_argv(runtime, args[0], &display_command, line);
        if (runtime->exceptions->active_exception != NULL) {
            ptn_process_free_argv(argv);
            free(display_command);
            return ptn_null();
        }
    } else {
        command_string = ptn_internal_expect_string_arg(runtime, "proc_open", 1, "command", args[0], line);
        if (!ptn_shell_validate_command(runtime, "proc_open", command_string)) {
            ptn_string_operand_free(command_string);
            return ptn_null();
        }
        display_command = ptn_duplicate_string_len(command_string.data, command_string.len);
    }

    PtnProcessDescriptorList descriptors;
    ptn_process_descriptor_list_init(&descriptors);
    if (!ptn_process_parse_descriptor_spec(runtime, args[1], &descriptors, line)) {
        ptn_process_descriptor_list_free(&descriptors);
        ptn_process_free_argv(argv);
        if (!command_is_array) {
            ptn_string_operand_free(command_string);
        }
        free(display_command);
        if (runtime->exceptions->active_exception != NULL) {
            return ptn_null();
        }
        return ptn_bool(0);
    }

    char *cwd = ptn_process_cwd_arg(runtime, argc, args, line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_process_descriptor_list_free(&descriptors);
        ptn_process_free_argv(argv);
        if (!command_is_array) {
            ptn_string_operand_free(command_string);
        }
        free(display_command);
        free(cwd);
        return ptn_null();
    }

    char **envp = NULL;
    if (argc >= 5) {
        envp = ptn_process_build_envp(runtime, args[4], line);
        if (runtime->exceptions->active_exception != NULL) {
            ptn_process_descriptor_list_free(&descriptors);
            ptn_process_free_argv(argv);
            if (!command_is_array) {
                ptn_string_operand_free(command_string);
            }
            free(display_command);
            free(cwd);
            return ptn_null();
        }
    }

    pid_t child = fork();
    if (child < 0) {
        ptn_emit_warning(&runtime->diagnostics, "proc_open(): unable to fork child process", line);
        ptn_process_descriptor_list_free(&descriptors);
        ptn_process_free_argv(argv);
        ptn_process_free_envp(envp);
        if (!command_is_array) {
            ptn_string_operand_free(command_string);
        }
        free(display_command);
        free(cwd);
        return ptn_bool(0);
    }

    if (child == 0) {
        if (cwd != NULL && chdir(cwd) != 0) {
            _exit(127);
        }
        ptn_process_child_apply_descriptors(&descriptors);
        if (command_is_array) {
            ptn_process_exec_path_search(argv, envp);
        } else {
            char *shell_argv[4] = { (char *)"sh", (char *)"-c", (char *)command_string.data, NULL };
            execve("/bin/sh", shell_argv, envp == NULL ? PTN_ENVIRON : envp);
        }
        _exit(127);
    }

    for (size_t i = 0; i < descriptors.len; i++) {
        if (descriptors.items[i].child_fd >= 0) {
            close(descriptors.items[i].child_fd);
            descriptors.items[i].child_fd = -1;
        }
    }

    PtnProcessData *process_data = calloc(1, sizeof(PtnProcessData));
    if (process_data == NULL) {
        kill(child, SIGTERM);
        (void)waitpid(child, NULL, 0);
        ptn_process_descriptor_list_free(&descriptors);
        ptn_process_free_argv(argv);
        ptn_process_free_envp(envp);
        if (!command_is_array) {
            ptn_string_operand_free(command_string);
        }
        free(display_command);
        free(cwd);
        ptn_abort_out_of_memory();
    }
    process_data->pid = child;
    process_data->command = display_command;

    PtnValue pipes = ptn_process_parent_streams_value(runtime, &descriptors, process_data, child, line);
    if (ptn_value_deref(pipes).type == PTN_BOOL && !ptn_value_deref(pipes).as.boolean) {
        ptn_process_descriptor_list_free(&descriptors);
        ptn_process_free_argv(argv);
        ptn_process_free_envp(envp);
        if (!command_is_array) {
            ptn_string_operand_free(command_string);
        }
        free(cwd);
        ptn_process_data_free(process_data);
        return ptn_bool(0);
    }

    if (args[2].type == PTN_REFERENCE) {
        ptn_reference_assign(runtime, args[2].as.reference, pipes);
    }
    ptn_value_destroy(&pipes);

    PtnResource *resource = ptn_resource_new_named("process");
    resource->close_hook = ptn_process_close_hook;
    resource->close_hook_data = process_data;
    resource->close_hook_data_free = ptn_process_data_free;

    ptn_process_descriptor_list_free(&descriptors);
    ptn_process_free_argv(argv);
    ptn_process_free_envp(envp);
    if (!command_is_array) {
        ptn_string_operand_free(command_string);
    }
    free(cwd);
    return ptn_resource(resource);
}

static PtnValue ptn_internal_proc_close(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)line;
    PtnValue value = ptn_value_deref(args[0]);
    PtnProcessData *data = ptn_process_data_from_value(runtime, "proc_close", value);
    if (data == NULL) {
        return ptn_null();
    }
    ptn_process_data_close_pipes(data);
    int exit_code = ptn_process_wait(data);
    ptn_resource_close(value.as.resource);
    return ptn_int(exit_code);
}

static PtnValue ptn_process_status_value(PtnProcessData *data, int running, int cached) {
    PtnValue status = ptn_array_from_literal_entries(0, NULL);
    ptn_array_set_entry(status.as.array, ptn_array_string_key("command"), ptn_string(data->command == NULL ? "" : data->command));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("pid"), ptn_int((int64_t)data->pid));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("cached"), ptn_bool(cached));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("running"), ptn_bool(running));
#if !defined(_WIN32)
    int signaled = data->has_status && WIFSIGNALED(data->status);
    int stopped = data->has_status && WIFSTOPPED(data->status);
    int exitcode = data->has_status && WIFEXITED(data->status) ? WEXITSTATUS(data->status) : -1;
    int termsig = signaled ? WTERMSIG(data->status) : 0;
    int stopsig = stopped ? WSTOPSIG(data->status) : 0;
#else
    int signaled = 0;
    int stopped = 0;
    int exitcode = data->has_status ? data->status : -1;
    int termsig = 0;
    int stopsig = 0;
#endif
    ptn_array_set_entry(status.as.array, ptn_array_string_key("signaled"), ptn_bool(signaled));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("stopped"), ptn_bool(stopped));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("exitcode"), ptn_int(exitcode));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("termsig"), ptn_int(termsig));
    ptn_array_set_entry(status.as.array, ptn_array_string_key("stopsig"), ptn_int(stopsig));
    return status;
}

static PtnValue ptn_internal_proc_get_status(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)line;
    PtnProcessData *data = ptn_process_data_from_value(runtime, "proc_get_status", args[0]);
    if (data == NULL) {
        return ptn_null();
    }
    int had_status = data->has_status;
    int running = ptn_process_poll(data);
    return ptn_process_status_value(data, running, had_status);
}

static PtnValue ptn_internal_proc_terminate(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnProcessData *data = ptn_process_data_from_value(runtime, "proc_terminate", args[0]);
    if (data == NULL) {
        return ptn_null();
    }
    int64_t signal_number = argc >= 2
        ? ptn_internal_expect_integer_arg(runtime, "proc_terminate", 2, "signal", args[1], line)
        : SIGTERM;
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    if (signal_number < 0 || signal_number > INT_MAX) {
        return ptn_bool(0);
    }
    if (data->has_status) {
        return ptn_bool(0);
    }
    return ptn_bool(kill(data->pid, (int)signal_number) == 0);
}

static size_t ptn_shell_command_max_len(void) {
#ifdef _SC_ARG_MAX
    long value = sysconf(_SC_ARG_MAX);
    if (value > 0) {
        return (size_t)value;
    }
#ifdef _POSIX_ARG_MAX
    return (size_t)_POSIX_ARG_MAX;
#else
    return 4096;
#endif
#elif defined(ARG_MAX)
    return (size_t)ARG_MAX;
#elif defined(_WIN32)
    return 8192;
#else
    return 4096;
#endif
}

static int ptn_shell_input_length_ok(
    PtnRuntime *runtime,
    const char *kind,
    size_t len
) {
    size_t max_len = ptn_shell_command_max_len();
    if (len <= max_len - 3) {
        return 1;
    }
    char message[128];
    int written = snprintf(message, sizeof(message), "%s exceeds the allowed length of %zu bytes", kind, max_len);
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "ValueError", message);
    return 0;
}

static int ptn_shell_escaped_length_ok(
    PtnRuntime *runtime,
    const char *kind,
    size_t len
) {
    size_t max_len = ptn_shell_command_max_len();
    if (len <= max_len + 1) {
        return 1;
    }
    char message[128];
    int written = snprintf(message, sizeof(message), "Escaped %s exceeds the allowed length of %zu bytes", kind, max_len);
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "ValueError", message);
    return 0;
}

static PtnValue ptn_internal_escapeshellarg(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand argument = ptn_internal_expect_string_arg(runtime, "escapeshellarg", 1, "arg", args[0], line);
    if (memchr(argument.data, '\0', argument.len) != NULL) {
        ptn_string_operand_free(argument);
        ptn_throw_exception(runtime, "ValueError", "escapeshellarg(): Argument #1 ($arg) must not contain any null bytes");
        return ptn_null();
    }
    if (!ptn_shell_input_length_ok(runtime, "Argument", argument.len)) {
        ptn_string_operand_free(argument);
        return ptn_null();
    }

    PtnStringBuffer escaped;
    ptn_string_buffer_init(&escaped);
    ptn_string_buffer_append_char(&escaped, '\'');
    for (size_t i = 0; i < argument.len; i++) {
        if (argument.data[i] == '\'') {
            ptn_string_buffer_append(&escaped, "'\\''");
        } else {
            ptn_string_buffer_append_char(&escaped, argument.data[i]);
        }
    }
    ptn_string_buffer_append_char(&escaped, '\'');
    ptn_string_operand_free(argument);
    if (!ptn_shell_escaped_length_ok(runtime, "argument", escaped.len)) {
        free(escaped.data);
        return ptn_null();
    }
    return ptn_owned_string_len(escaped.data, escaped.len);
}

static int ptn_shellcmd_byte_needs_escape(char byte) {
    switch (byte) {
        case '"':
        case '#':
        case '&':
        case ';':
        case '`':
        case '|':
        case '*':
        case '?':
        case '~':
        case '<':
        case '>':
        case '^':
        case '(':
        case ')':
        case '[':
        case ']':
        case '{':
        case '}':
        case '$':
        case '\\':
        case '\n':
        case (char)0xff:
            return 1;
        default:
            return 0;
    }
}

static PtnValue ptn_internal_escapeshellcmd(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand command =
        ptn_internal_expect_string_arg(runtime, "escapeshellcmd", 1, "command", args[0], line);
    if (memchr(command.data, '\0', command.len) != NULL) {
        ptn_string_operand_free(command);
        ptn_throw_exception(runtime, "ValueError", "escapeshellcmd(): Argument #1 ($command) must not contain any null bytes");
        return ptn_null();
    }
    if (!ptn_shell_input_length_ok(runtime, "Command", command.len)) {
        ptn_string_operand_free(command);
        return ptn_null();
    }

    PtnStringBuffer escaped;
    ptn_string_buffer_init(&escaped);
    char active_quote = '\0';
    for (size_t i = 0; i < command.len; i++) {
        char byte = command.data[i];
        if (byte == '\'' || byte == '"') {
            if (active_quote == '\0') {
                const void *next = memchr(command.data + i + 1, byte, command.len - i - 1);
                if (next != NULL) {
                    active_quote = byte;
                } else {
                    ptn_string_buffer_append_char(&escaped, '\\');
                }
            } else if (active_quote == byte) {
                active_quote = '\0';
            } else {
                ptn_string_buffer_append_char(&escaped, '\\');
            }
            ptn_string_buffer_append_char(&escaped, byte);
            continue;
        }
        if (ptn_shellcmd_byte_needs_escape(byte)) {
            ptn_string_buffer_append_char(&escaped, '\\');
        }
        ptn_string_buffer_append_char(&escaped, byte);
    }
    ptn_string_operand_free(command);
    if (!ptn_shell_escaped_length_ok(runtime, "command", escaped.len)) {
        free(escaped.data);
        return ptn_null();
    }
    return ptn_owned_string_len(escaped.data, escaped.len);
}

static PtnValue ptn_internal_uniqid(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand prefix = argc >= 1
        ? ptn_internal_expect_string_arg(runtime, "uniqid", 1, "prefix", args[0], line)
        : ptn_string_operand_borrowed("");
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(prefix);
        return ptn_null();
    }
    int more_entropy = argc >= 2 && ptn_is_truthy(args[1]);
    static uint64_t ptn_uniqid_counter = 0;
    ptn_uniqid_counter++;

#if defined(_WIN32)
    uint64_t seconds = (uint64_t)time(NULL);
    uint64_t micros = ptn_uniqid_counter % 1000000u;
#else
    struct timeval now;
    gettimeofday(&now, NULL);
    uint64_t seconds = (uint64_t)now.tv_sec;
    uint64_t micros = ((uint64_t)now.tv_usec + ptn_uniqid_counter) % 1000000u;
#endif

    char core[32];
    int written = snprintf(
        core,
        sizeof(core),
        "%08llx%05llx",
        (unsigned long long)(seconds & 0xffffffffu),
        (unsigned long long)(micros & 0xfffffu)
    );
    if (written < 0 || (size_t)written >= sizeof(core)) {
        ptn_abort_out_of_memory();
    }

    PtnStringBuffer output;
    ptn_string_buffer_init(&output);
    ptn_string_buffer_append_len(&output, prefix.data, prefix.len);
    ptn_string_buffer_append_len(&output, core, (size_t)written);
    if (more_entropy) {
        char entropy[32];
        int entropy_written = snprintf(
            entropy,
            sizeof(entropy),
            ".%010llu",
            (unsigned long long)(ptn_uniqid_counter % 10000000000ull)
        );
        if (entropy_written < 0 || (size_t)entropy_written >= sizeof(entropy)) {
            ptn_abort_out_of_memory();
        }
        ptn_string_buffer_append_len(&output, entropy, (size_t)entropy_written);
    }
    ptn_string_operand_free(prefix);
    return ptn_owned_string_len(output.data, output.len);
}

static int ptn_setlocale_category(int64_t category, int *out) {
    switch (category) {
        case PTN_LC_CTYPE:
            *out = LC_CTYPE;
            return 1;
        case PTN_LC_NUMERIC:
            *out = LC_NUMERIC;
            return 1;
        case PTN_LC_TIME:
            *out = LC_TIME;
            return 1;
        case PTN_LC_COLLATE:
            *out = LC_COLLATE;
            return 1;
        case PTN_LC_MONETARY:
            *out = LC_MONETARY;
            return 1;
        case PTN_LC_MESSAGES:
#if defined(LC_MESSAGES)
            *out = LC_MESSAGES;
            return 1;
#else
            return 0;
#endif
        case PTN_LC_ALL:
            *out = LC_ALL;
            return 1;
        default:
            return 0;
    }
}

static char *ptn_setlocale_try_string(PtnRuntime *runtime, int category, const char *locale, size_t line) {
    const char *result = NULL;
    if (strcmp(locale, "0") == 0) {
        result = setlocale(category, NULL);
    } else {
        if (strlen(locale) >= 255) {
            ptn_emit_warning(&runtime->diagnostics, "setlocale(): Specified locale name is too long", line);
            return NULL;
        }
        result = setlocale(category, locale);
    }
    return result == NULL ? NULL : ptn_duplicate_string(result);
}

static void ptn_setlocale_throw_locale_type_error(PtnRuntime *runtime, size_t position, PtnValue value) {
    value = ptn_value_deref(value);
    char message[192];
    int written = position == 2
        ? snprintf(
              message,
              sizeof(message),
              "setlocale(): Argument #2 ($locales) must be of type array|string|null, %s given",
              ptn_internal_string_arg_type_name(value)
          )
        : snprintf(
              message,
              sizeof(message),
              "setlocale(): Argument #%zu must be of type array|string|null, %s given",
              position,
              ptn_internal_string_arg_type_name(value)
          );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "TypeError", message);
}

static int ptn_setlocale_strict_top_level_value_allowed(PtnValue value) {
    value = ptn_value_deref(value);
    return value.type == PTN_NULL ||
        value.type == PTN_STRING ||
        value.type == PTN_ARRAY ||
        value.type == PTN_OBJECT;
}

static char *ptn_setlocale_try_operand(PtnRuntime *runtime, int category, PtnStringOperand locale, size_t line) {
    char *locale_c = ptn_duplicate_string_len(locale.data, locale.len);
    char *result = ptn_setlocale_try_string(runtime, category, locale_c, line);
    free(locale_c);
    return result;
}

static char *ptn_setlocale_try_scalar_value(
    PtnRuntime *runtime,
    int category,
    PtnValue value,
    size_t position,
    size_t line,
    int strict_top_level
) {
    value = ptn_value_deref(value);
    if (value.type == PTN_NULL) {
        return ptn_setlocale_try_string(runtime, category, "0", line);
    }
    if (strict_top_level && !ptn_setlocale_strict_top_level_value_allowed(value)) {
        ptn_setlocale_throw_locale_type_error(runtime, position, value);
        return NULL;
    }

    PtnStringOperand locale = ptn_value_to_string_operand_with_runtime(runtime, value, line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(locale);
        return NULL;
    }
    char *result = ptn_setlocale_try_operand(runtime, category, locale, line);
    ptn_string_operand_free(locale);
    return result;
}

static char *ptn_setlocale_try_value(PtnRuntime *runtime, int category, PtnValue value, size_t position, size_t line) {
    value = ptn_value_deref(value);
    if (value.type == PTN_ARRAY) {
        PtnArray *array = value.as.array;
        for (size_t i = 0; i < array->len; i++) {
            PtnValue candidate = ptn_value_deref(array->entries[i].value);
            char *result = ptn_setlocale_try_scalar_value(runtime, category, candidate, position, line, 0);
            if (runtime->exceptions->active_exception != NULL) {
                return NULL;
            }
            if (result != NULL) {
                return result;
            }
        }
        return NULL;
    }
    return ptn_setlocale_try_scalar_value(runtime, category, value, position, line, runtime->strict_types);
}

static PtnValue ptn_internal_setlocale(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    int64_t category_value = ptn_internal_expect_integer_arg(runtime, "setlocale", 1, "category", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }

    int category = 0;
    if (!ptn_setlocale_category(category_value, &category)) {
        return ptn_bool(0);
    }

    if (runtime->strict_types) {
        for (size_t i = 1; i < argc; i++) {
            if (!ptn_setlocale_strict_top_level_value_allowed(args[i])) {
                ptn_setlocale_throw_locale_type_error(runtime, i + 1, args[i]);
                return ptn_null();
            }
        }
    }

    for (size_t i = 1; i < argc; i++) {
        char *result = ptn_setlocale_try_value(runtime, category, args[i], i + 1, line);
        if (runtime->exceptions->active_exception != NULL) {
            return ptn_null();
        }
        if (result != NULL) {
            return ptn_owned_string(result);
        }
    }
    return ptn_bool(0);
}

static void ptn_localeconv_set_string(PtnArray *array, const char *key, const char *value) {
    ptn_array_set_entry(array, ptn_array_string_key(key), ptn_string(value == NULL ? "" : value));
}

static void ptn_localeconv_set_int(PtnArray *array, const char *key, char value) {
    ptn_array_set_entry(array, ptn_array_string_key(key), ptn_int((int64_t)(unsigned char)value));
}

static PtnValue ptn_localeconv_grouping_array(const char *grouping) {
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    if (grouping == NULL) {
        return result;
    }
    for (size_t i = 0; grouping[i] != '\0' && (unsigned char)grouping[i] != CHAR_MAX; i++) {
        ptn_array_set_entry(
            result.as.array,
            ptn_array_int_key(result.as.array->next_auto_key),
            ptn_int((int64_t)(unsigned char)grouping[i])
        );
    }
    return result;
}

static void ptn_localeconv_set_grouping(PtnArray *array, const char *key, const char *grouping) {
    ptn_array_set_entry(array, ptn_array_string_key(key), ptn_localeconv_grouping_array(grouping));
}

static PtnValue ptn_internal_localeconv(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)argc;
    (void)args;
    (void)line;
    struct lconv *locale = localeconv();
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    ptn_localeconv_set_string(result.as.array, "decimal_point", locale->decimal_point);
    ptn_localeconv_set_string(result.as.array, "thousands_sep", locale->thousands_sep);
    ptn_localeconv_set_string(result.as.array, "int_curr_symbol", locale->int_curr_symbol);
    ptn_localeconv_set_string(result.as.array, "currency_symbol", locale->currency_symbol);
    ptn_localeconv_set_string(result.as.array, "mon_decimal_point", locale->mon_decimal_point);
    ptn_localeconv_set_string(result.as.array, "mon_thousands_sep", locale->mon_thousands_sep);
    ptn_localeconv_set_string(result.as.array, "positive_sign", locale->positive_sign);
    ptn_localeconv_set_string(result.as.array, "negative_sign", locale->negative_sign);
    ptn_localeconv_set_int(result.as.array, "int_frac_digits", locale->int_frac_digits);
    ptn_localeconv_set_int(result.as.array, "frac_digits", locale->frac_digits);
    ptn_localeconv_set_int(result.as.array, "p_cs_precedes", locale->p_cs_precedes);
    ptn_localeconv_set_int(result.as.array, "p_sep_by_space", locale->p_sep_by_space);
    ptn_localeconv_set_int(result.as.array, "n_cs_precedes", locale->n_cs_precedes);
    ptn_localeconv_set_int(result.as.array, "n_sep_by_space", locale->n_sep_by_space);
    ptn_localeconv_set_int(result.as.array, "p_sign_posn", locale->p_sign_posn);
    ptn_localeconv_set_int(result.as.array, "n_sign_posn", locale->n_sign_posn);
    ptn_localeconv_set_grouping(result.as.array, "grouping", locale->grouping);
    ptn_localeconv_set_grouping(result.as.array, "mon_grouping", locale->mon_grouping);
    return result;
}

static PtnValue ptn_internal_strcoll(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand left = ptn_internal_expect_string_arg(runtime, "strcoll", 1, "string1", args[0], line);
    PtnStringOperand right = ptn_internal_expect_string_arg(runtime, "strcoll", 2, "string2", args[1], line);
    char *left_c = ptn_duplicate_string_len(left.data, left.len);
    char *right_c = ptn_duplicate_string_len(right.data, right.len);
    int compared = strcoll(left_c, right_c);
    free(left_c);
    free(right_c);
    ptn_string_operand_free(left);
    ptn_string_operand_free(right);
    return ptn_int(compared < 0 ? -1 : (compared > 0 ? 1 : 0));
}

