static PtnOutputBuffer *ptn_output_buffer_top(PtnRuntime *runtime) {
    PtnRuntime *root = ptn_runtime_root(runtime);
    if (root == NULL || root->output_buffers_len == 0) {
        return NULL;
    }
    return &root->output_buffers[root->output_buffers_len - 1];
}

static int ptn_output_buffer_forbid_display_handler_operation(
    PtnRuntime *runtime,
    const char *function_name,
    size_t line
) {
    PtnRuntime *root = ptn_runtime_root(runtime);
    if (root == NULL || root->output_buffer_callback_depth == 0) {
        return 0;
    }
    char message[160];
    int written = snprintf(
        message,
        sizeof(message),
        "%s(): Cannot use output buffering in output buffering display handlers",
        function_name
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_fatal_error_at(runtime, message, runtime->source_path, line);
    return 1;
}

static int ptn_internal_ob_start_callback_arg(
    PtnRuntime *runtime,
    PtnValue callback,
    size_t line,
    PtnValue *callback_out
) {
    PtnValue checked = ptn_value_clone_deref(callback);
    if (ptn_callable_is_valid(runtime, checked, 0)) {
        *callback_out = checked;
        return 1;
    }

    char *reason = ptn_invalid_callback_reason(runtime, checked);
    ptn_value_destroy(&checked);
    int needed = snprintf(NULL, 0, "ob_start(): %s", reason);
    if (needed < 0) {
        free(reason);
        ptn_abort_out_of_memory();
    }
    char *message = malloc((size_t)needed + 1);
    if (message == NULL) {
        free(reason);
        ptn_abort_out_of_memory();
    }
    snprintf(message, (size_t)needed + 1, "ob_start(): %s", reason);
    free(reason);

    PtnRuntime *root = ptn_runtime_root(runtime);
    int leading_newline = root != NULL && root->output_has_started;
    PtnOutputBuffer *active = ptn_output_buffer_top(runtime);
    if (active != NULL && active->buffer.len != 0) {
        leading_newline = 1;
    }
    ptn_emit_warning_with_handler_frame_and_newline(
        &runtime->diagnostics,
        message,
        line,
        1,
        leading_newline
    );
    free(message);
    ptn_emit_notice_with_handler_frame(
        &runtime->diagnostics,
        "ob_start(): Failed to create buffer",
        line,
        1,
        1
    );
    return 0;
}

static PtnValue ptn_internal_ob_start(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    if (ptn_output_buffer_forbid_display_handler_operation(runtime, "ob_start", line)) {
        return ptn_null();
    }

    int has_callback = 0;
    PtnValue callback = ptn_null();
    size_t chunk_size = 0;
    int64_t requested_flags = PTN_PHP_OUTPUT_HANDLER_STDFLAGS;
    if (argc >= 1) {
        PtnValue resolved = ptn_value_deref(args[0]);
        if (resolved.type != PTN_NULL) {
            if (!ptn_internal_ob_start_callback_arg(runtime, args[0], line, &callback)) {
                return ptn_bool(0);
            }
            has_callback = 1;
        }
    }
    if (argc >= 2) {
        int64_t requested_chunk_size =
            ptn_internal_expect_integer_arg(runtime, "ob_start", 2, "chunk_size", args[1], line);
        if (requested_chunk_size > 0) {
            chunk_size = (size_t)requested_chunk_size;
        }
    }
    if (argc >= 3) {
        requested_flags = ptn_internal_expect_integer_arg(runtime, "ob_start", 3, "flags", args[2], line);
    }
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    int64_t buffer_flags = requested_flags & PTN_PHP_OUTPUT_HANDLER_STDFLAGS;
    if (has_callback) {
        buffer_flags |= PTN_PHP_OUTPUT_HANDLER_TYPE_USER;
    }
    ptn_output_buffer_push(runtime, has_callback, callback, chunk_size, buffer_flags);
    if (has_callback) {
        ptn_value_destroy(&callback);
    }
    return ptn_bool(1);
}

static PtnValue ptn_internal_ob_get_contents(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnOutputBuffer *buffer = ptn_output_buffer_top(runtime);
    if (buffer == NULL) {
        return ptn_bool(0);
    }
    return ptn_output_buffer_contents_value(buffer);
}

static PtnValue ptn_internal_ob_get_length(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnOutputBuffer *buffer = ptn_output_buffer_top(runtime);
    if (buffer == NULL) {
        return ptn_bool(0);
    }
    if (buffer->buffer.len > (size_t)INT64_MAX) {
        ptn_abort_out_of_memory();
    }
    return ptn_int((int64_t)buffer->buffer.len);
}

static PtnValue ptn_internal_ob_get_level(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnRuntime *root = ptn_runtime_root(runtime);
    size_t level = root == NULL ? 0 : root->output_buffers_len;
    if (level > (size_t)INT64_MAX) {
        ptn_abort_out_of_memory();
    }
    return ptn_int((int64_t)level);
}

static PtnValue ptn_internal_ob_implicit_flush(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)argc;
    (void)args;
    (void)line;
    return ptn_null();
}

static PtnValue ptn_internal_ob_list_handlers(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    PtnRuntime *root = ptn_runtime_root(runtime);
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    if (root == NULL) {
        return result;
    }
    for (size_t i = 0; i < root->output_buffers_len; i++) {
        PtnOutputBuffer *buffer = &root->output_buffers[i];
        PtnValue name = buffer->has_callback
            ? ptn_owned_string(ptn_callable_output_name(buffer->callback))
            : ptn_string("default output handler");
        if (i > (size_t)INT64_MAX) {
            ptn_abort_out_of_memory();
        }
        ptn_array_set_entry(result.as.array, ptn_array_int_key((int64_t)i), name);
    }
    return result;
}

static size_t ptn_output_buffer_reported_size(PtnOutputBuffer *buffer) {
    if (buffer == NULL || buffer->chunk_size == 0) {
        return 16384;
    }
    size_t blocks = (buffer->chunk_size + 4095) / 4096;
    if (blocks == 0) {
        blocks = 1;
    }
    if (blocks > SIZE_MAX / 4096) {
        ptn_abort_out_of_memory();
    }
    return blocks * 4096;
}

static PtnValue ptn_output_buffer_status_value(PtnOutputBuffer *buffer, size_t level) {
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    char *name = ptn_output_buffer_name(buffer);
    ptn_array_set_entry(result.as.array, ptn_array_string_key("name"), ptn_owned_string(name));
    ptn_array_set_entry(
        result.as.array,
        ptn_array_string_key("type"),
        ptn_int(buffer->has_callback ? PTN_PHP_OUTPUT_HANDLER_TYPE_USER : PTN_PHP_OUTPUT_HANDLER_TYPE_INTERNAL)
    );
    ptn_array_set_entry(result.as.array, ptn_array_string_key("flags"), ptn_int(buffer->flags));
    size_t reported_size = ptn_output_buffer_reported_size(buffer);
    if (level > (size_t)INT64_MAX || buffer->chunk_size > (size_t)INT64_MAX ||
        buffer->buffer.len > (size_t)INT64_MAX || reported_size > (size_t)INT64_MAX) {
        ptn_abort_out_of_memory();
    }
    ptn_array_set_entry(result.as.array, ptn_array_string_key("level"), ptn_int((int64_t)level));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("chunk_size"), ptn_int((int64_t)buffer->chunk_size));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("buffer_size"), ptn_int((int64_t)reported_size));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("buffer_used"), ptn_int((int64_t)buffer->buffer.len));
    return result;
}

static PtnValue ptn_internal_ob_get_status(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)line;
    PtnRuntime *root = ptn_runtime_root(runtime);
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    if (root == NULL || root->output_buffers_len == 0) {
        return result;
    }
    int full_status = argc >= 1 && ptn_is_truthy(args[0]);
    if (!full_status) {
        return ptn_output_buffer_status_value(
            &root->output_buffers[root->output_buffers_len - 1],
            root->output_buffers_len - 1
        );
    }
    for (size_t i = 0; i < root->output_buffers_len; i++) {
        if (i > (size_t)INT64_MAX) {
            ptn_abort_out_of_memory();
        }
        ptn_array_set_entry(
            result.as.array,
            ptn_array_int_key((int64_t)i),
            ptn_output_buffer_status_value(&root->output_buffers[i], i)
        );
    }
    return result;
}

static PtnValue ptn_internal_ob_clean(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    PtnOutputBuffer *buffer = ptn_output_buffer_top(runtime);
    if (buffer == NULL) {
        PtnRuntime *root = ptn_runtime_root(runtime);
        ptn_emit_notice_with_handler_frame(
            &runtime->diagnostics,
            "ob_clean(): Failed to delete buffer. No buffer to delete",
            line,
            1,
            root != NULL && root->output_has_started
        );
        return ptn_bool(0);
    }
    if ((buffer->flags & PTN_PHP_OUTPUT_HANDLER_CLEANABLE) == 0) {
        ptn_output_buffer_emit_operation_notice(runtime, buffer, "ob_clean", "delete", line);
        return ptn_bool(0);
    }
    int64_t operation_flags = PTN_PHP_OUTPUT_HANDLER_CLEAN;
    if ((buffer->flags & PTN_PHP_OUTPUT_HANDLER_STARTED) == 0) {
        operation_flags |= PTN_PHP_OUTPUT_HANDLER_START;
    }
    buffer->flags |= PTN_PHP_OUTPUT_HANDLER_STARTED | PTN_PHP_OUTPUT_HANDLER_PROCESSED;
    int handler_output_warned = 0;
    PtnValue output = ptn_output_buffer_apply_callback(
        runtime,
        buffer,
        buffer,
        line,
        operation_flags,
        "ob_clean",
        0,
        &handler_output_warned
    );
    if (handler_output_warned) {
        char *handler_name = ptn_output_buffer_name(buffer);
        ptn_output_buffer_emit_handler_output_deprecation(runtime, "ob_clean", handler_name, line, 0);
        free(handler_name);
    }
    ptn_value_destroy(&output);
    buffer->buffer.len = 0;
    if (buffer->buffer.data != NULL) {
        buffer->buffer.data[0] = '\0';
    }
    return ptn_bool(1);
}

static PtnValue ptn_internal_ob_end_clean(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    return ptn_bool(ptn_output_buffer_close(runtime, 0, line, "ob_end_clean"));
}

static PtnValue ptn_internal_ob_end_flush(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    return ptn_bool(ptn_output_buffer_close(runtime, 1, line, "ob_end_flush"));
}

static PtnValue ptn_internal_ob_flush(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    if (ptn_output_buffer_top(runtime) == NULL) {
        PtnRuntime *root = ptn_runtime_root(runtime);
        ptn_emit_notice_with_handler_frame(
            &runtime->diagnostics,
            "ob_flush(): Failed to flush buffer. No buffer to flush",
            line,
            1,
            root != NULL && root->output_has_started
        );
        return ptn_bool(0);
    }
    PtnOutputBuffer *buffer = ptn_output_buffer_top(runtime);
    if ((buffer->flags & PTN_PHP_OUTPUT_HANDLER_FLUSHABLE) == 0) {
        ptn_output_buffer_emit_operation_notice(runtime, buffer, "ob_flush", "flush", line);
        return ptn_bool(0);
    }
    (void)ptn_output_buffer_flush_top_chunk(runtime, line, PTN_PHP_OUTPUT_HANDLER_FLUSH, "ob_flush");
    return ptn_bool(1);
}

static PtnValue ptn_internal_ob_get_clean(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    PtnOutputBuffer *buffer = ptn_output_buffer_top(runtime);
    if (buffer == NULL) {
        return ptn_bool(0);
    }
    PtnValue contents = ptn_output_buffer_contents_value(buffer);
    int failed = 0;
    if ((buffer->flags & PTN_PHP_OUTPUT_HANDLER_CLEANABLE) == 0) {
        ptn_output_buffer_emit_operation_notice(runtime, buffer, "ob_get_clean", "discard", line);
        failed = 1;
    }
    if ((buffer->flags & PTN_PHP_OUTPUT_HANDLER_REMOVABLE) == 0) {
        ptn_output_buffer_emit_operation_notice(runtime, buffer, "ob_get_clean", "delete", line);
        failed = 1;
    }
    if (failed) {
        return contents;
    }
    (void)ptn_output_buffer_close(runtime, 0, line, "ob_get_clean");
    return contents;
}

static PtnValue ptn_internal_ob_get_flush(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    if (ptn_output_buffer_forbid_display_handler_operation(runtime, "ob_get_flush", line)) {
        return ptn_null();
    }
    PtnOutputBuffer *buffer = ptn_output_buffer_top(runtime);
    if (buffer == NULL) {
        return ptn_bool(0);
    }
    PtnValue contents = ptn_output_buffer_contents_value(buffer);
    int failed = 0;
    if ((buffer->flags & PTN_PHP_OUTPUT_HANDLER_FLUSHABLE) == 0) {
        ptn_output_buffer_emit_operation_notice(runtime, buffer, "ob_get_flush", "send", line);
        failed = 1;
    }
    if ((buffer->flags & PTN_PHP_OUTPUT_HANDLER_REMOVABLE) == 0) {
        ptn_output_buffer_emit_operation_notice(runtime, buffer, "ob_get_flush", "delete", line);
        failed = 1;
    }
    if (failed) {
        return contents;
    }
    (void)ptn_output_buffer_close(runtime, 1, line, "ob_get_flush");
    return contents;
}

static PtnCallFrame *ptn_current_call_frame(PtnRuntime *runtime, const char *function_name, size_t line) {
    if (runtime->call_frame != NULL) {
        return runtime->call_frame;
    }
    char message[128];
    const char *format = ptn_runtime_shutdown_line_without_active_file(runtime, line)
        ? "Cannot call %s() dynamically"
        : strcmp(function_name, "func_num_args") == 0
        ? "%s() must be called from a function context"
        : "%s() cannot be called from the global scope";
    int written = snprintf(message, sizeof(message), format, function_name);
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception_at(
        runtime,
        "Error",
        message,
        ptn_runtime_internal_call_path(runtime, line),
        line
    );
    return NULL;
}

static PtnValue ptn_call_frame_arg_value(PtnRuntime *runtime, PtnCallFrame *frame, size_t position) {
    if (position < frame->parameter_count) {
        PtnValue value;
        if (ptn_symbols_get(&runtime->symbols, frame->parameter_names[position], &value)) {
            return ptn_value_clone_deref(value);
        }
    }
    if (position < frame->argc) {
        return ptn_value_clone_deref(frame->args[position]);
    }
    return ptn_null();
}

static int ptn_call_frame_arg_visible_to_func_api(PtnCallFrame *frame, size_t position) {
    return frame->arg_names == NULL ||
        position < frame->parameter_count ||
        frame->arg_names[position] == NULL;
}

static size_t ptn_call_frame_func_arg_count(PtnCallFrame *frame) {
    size_t count = 0;
    for (size_t i = 0; i < frame->argc; i++) {
        if (ptn_call_frame_arg_visible_to_func_api(frame, i)) {
            count++;
        }
    }
    return count;
}

static int ptn_call_frame_func_arg_position(PtnCallFrame *frame, size_t visible_position, size_t *position_out) {
    size_t visible = 0;
    for (size_t i = 0; i < frame->argc; i++) {
        if (!ptn_call_frame_arg_visible_to_func_api(frame, i)) {
            continue;
        }
        if (visible == visible_position) {
            *position_out = i;
            return 1;
        }
        visible++;
    }
    return 0;
}

static PtnValue ptn_internal_func_num_args(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    PtnCallFrame *frame = ptn_current_call_frame(runtime, "func_num_args", line);
    size_t visible_arg_count = ptn_call_frame_func_arg_count(frame);
    if (visible_arg_count > (size_t)INT64_MAX) {
        ptn_abort_out_of_memory();
    }
    return ptn_int((int64_t)visible_arg_count);
}

static PtnValue ptn_internal_func_get_arg(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnCallFrame *frame = ptn_current_call_frame(runtime, "func_get_arg", line);
    int64_t position = ptn_value_to_integer(args[0]);
    if (position < 0) {
        ptn_throw_exception(
            runtime,
            "ValueError",
            "func_get_arg(): Argument #1 ($position) must be greater than or equal to 0"
        );
    }
    size_t source_position = 0;
    if (!ptn_call_frame_func_arg_position(frame, (size_t)position, &source_position)) {
        ptn_throw_exception(
            runtime,
            "ValueError",
            "func_get_arg(): Argument #1 ($position) must be less than the number of the arguments passed to the currently executed function"
        );
    }
    return ptn_call_frame_arg_value(runtime, frame, source_position);
}

static PtnValue ptn_internal_func_get_args(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    PtnCallFrame *frame = ptn_current_call_frame(runtime, "func_get_args", line);
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    size_t visible = 0;
    for (size_t i = 0; i < frame->argc; i++) {
        if (!ptn_call_frame_arg_visible_to_func_api(frame, i)) {
            continue;
        }
        if (visible > (size_t)INT64_MAX) {
            ptn_abort_out_of_memory();
        }
        ptn_array_set_entry(
            result.as.array,
            ptn_array_int_key((int64_t)visible),
            ptn_call_frame_arg_value(runtime, frame, i)
        );
        visible++;
    }
    return result;
}

static int ptn_internal_named_argument_index(
    size_t argc,
    const char *const *arg_names,
    const char *name,
    size_t fallback,
    size_t *index_out
) {
    if (arg_names != NULL) {
        for (size_t i = 0; i < argc; i++) {
            if (arg_names[i] != NULL && strcmp(arg_names[i], name) == 0) {
                *index_out = i;
                return 1;
            }
        }
    }
    if (fallback < argc) {
        *index_out = fallback;
        return 1;
    }
    return 0;
}

static PtnValue ptn_internal_call_user_func(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    size_t previous_call_site_line = runtime->call_site_line;
    runtime->call_site_line = line;
    const char *const *call_arg_names = runtime->next_call_arg_names;
    runtime->next_call_arg_names = NULL;
    size_t callback_index = 0;
    if (!ptn_internal_named_argument_index(argc, call_arg_names, "callback", 0, &callback_index)) {
        ptn_throw_internal_argument_count_error(
            runtime,
            "call_user_func",
            "at least",
            1,
            argc,
            line,
            args
        );
        runtime->call_site_line = previous_call_site_line;
        return ptn_null();
    }
    PtnValue callback = ptn_internal_expect_callback_arg_autoload(runtime, "call_user_func", 1, "callback", args[callback_index]);
    if (runtime->exceptions->active_exception != NULL) {
        runtime->call_site_line = previous_call_site_line;
        return ptn_null();
    }
    size_t target_argc = argc > 0 ? argc - 1 : 0;
    PtnValue *target_args = NULL;
    const char *const *target_arg_names = NULL;
    const char **allocated_target_names = NULL;
    if (target_argc != 0) {
        target_args = malloc(target_argc * sizeof(PtnValue));
        if (call_arg_names != NULL) {
            allocated_target_names = malloc(target_argc * sizeof(char *));
        }
        if (target_args == NULL || (call_arg_names != NULL && allocated_target_names == NULL)) {
            free(target_args);
            free(allocated_target_names);
            ptn_abort_out_of_memory();
        }
        size_t target_index = 0;
        for (size_t i = 0; i < argc; i++) {
            if (i == callback_index) {
                continue;
            }
            target_args[target_index] =
                ptn_value_disable_by_ref_argument_source(ptn_value_clone(args[i]));
            if (allocated_target_names != NULL) {
                allocated_target_names[target_index] = call_arg_names[i];
            }
            target_index++;
        }
        if (allocated_target_names != NULL) {
            target_arg_names = (const char *const *)allocated_target_names;
        }
    }
    int previous_warn_by_ref_argument_mismatch = runtime->warn_by_ref_argument_mismatch;
    runtime->warn_by_ref_argument_mismatch = 1;
    PtnTraceFrame call_user_func_trace_frame;
    int pushed_call_user_func_trace_frame =
        runtime->trace_frame == NULL ||
        runtime->trace_frame->function_name == NULL ||
        !ptn_ascii_case_equal(runtime->trace_frame->function_name, "call_user_func");
    if (pushed_call_user_func_trace_frame) {
        const char *const *previous_trace_arg_names = runtime->next_call_arg_names;
        runtime->next_call_arg_names = call_arg_names;
        ptn_runtime_push_trace_frame(
            runtime,
            &call_user_func_trace_frame,
            "call_user_func",
            ptn_runtime_internal_trace_file(runtime, line),
            line,
            argc,
            args
        );
        runtime->next_call_arg_names = previous_trace_arg_names;
    }
    PtnValue result = ptn_null();
    int callback_ok = ptn_internal_call_callback_capturing_exception_impl(
        runtime,
        callback,
        target_argc,
        target_args,
        target_arg_names,
        line,
        1,
        0,
        &result
    );
    if (pushed_call_user_func_trace_frame) {
        ptn_runtime_pop_trace_frame(runtime, &call_user_func_trace_frame);
    }
    runtime->warn_by_ref_argument_mismatch = previous_warn_by_ref_argument_mismatch;
    for (size_t i = 0; i < target_argc; i++) {
        ptn_value_destroy(&target_args[i]);
    }
    free(target_args);
    free(allocated_target_names);
    ptn_value_destroy(&callback);
    runtime->call_site_line = previous_call_site_line;
    if (!callback_ok) {
        ptn_rethrow_exception(runtime);
    }
    return result;
}

static PtnValue ptn_internal_call_user_func_array(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    const char *const *call_arg_names = runtime->next_call_arg_names;
    runtime->next_call_arg_names = NULL;
    size_t callback_index = 0;
    size_t arguments_index = 1;
    if (!ptn_internal_named_argument_index(argc, call_arg_names, "callback", 0, &callback_index) ||
        !ptn_internal_named_argument_index(argc, call_arg_names, "args", 1, &arguments_index)) {
        ptn_throw_internal_argument_count_error(
            runtime,
            "call_user_func_array",
            "exactly",
            2,
            argc,
            line,
            args
        );
        return ptn_null();
    }
    PtnArray *arguments = ptn_internal_expect_array_arg(runtime, "call_user_func_array", 2, "args", args[arguments_index]);
    size_t previous_call_site_line = runtime->call_site_line;
    runtime->call_site_line = line;
    PtnValue callback = ptn_internal_expect_callback_arg_autoload(runtime, "call_user_func_array", 1, "callback", args[callback_index]);
    if (runtime->exceptions->active_exception != NULL) {
        runtime->call_site_line = previous_call_site_line;
        return ptn_null();
    }
    PtnCallArguments expanded;
    ptn_call_arguments_init(&expanded);
    ptn_call_arguments_reserve(&expanded, arguments->len);
    for (size_t i = 0; i < arguments->len; i++) {
        PtnArrayEntry *entry = &arguments->entries[i];
        char *argument_name = NULL;
        if (entry->key.type == PTN_ARRAY_KEY_STRING) {
            argument_name = ptn_duplicate_string_len(entry->key.as.string, entry->key.string_len);
        }
        PtnValue argument_value = ptn_value_clone(entry->value);
        if (!entry->by_ref_argument_eligible) {
            argument_value = ptn_value_disable_by_ref_argument_source(argument_value);
        }
        ptn_call_arguments_append_named_owned(&expanded, argument_name, argument_value);
        free(argument_name);
    }

    int previous_warn_by_ref_argument_mismatch = runtime->warn_by_ref_argument_mismatch;
    runtime->warn_by_ref_argument_mismatch = 1;
    PtnValue result = ptn_internal_call_user_callback_named_hidden_frame(
        runtime,
        callback,
        expanded.len,
        expanded.values,
        (const char *const *)expanded.names,
        line
    );
    runtime->warn_by_ref_argument_mismatch = previous_warn_by_ref_argument_mismatch;
    ptn_call_arguments_destroy(&expanded);
    ptn_value_destroy(&callback);
    runtime->call_site_line = previous_call_site_line;
    return result;
}

static PtnValue ptn_internal_forward_static_call(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    if (runtime->current_class_name == NULL && runtime->current_called_class_name == NULL) {
        PtnRuntime *root = ptn_runtime_root(runtime);
        const char *path =
            line == 0 &&
            root != NULL &&
            root->shutdown_functions_running
                ? "[no active file]"
                : runtime->source_path;
        ptn_throw_exception_at(
            runtime,
            "Error",
            "Cannot call forward_static_call() when no class scope is active",
            path,
            line
        );
        return ptn_null();
    }

    size_t previous_call_site_line = runtime->call_site_line;
    runtime->call_site_line = line;
    PtnValue callback = ptn_internal_expect_callback_arg(runtime, "forward_static_call", 1, "callback", args[0]);
    if (runtime->exceptions->active_exception != NULL) {
        runtime->call_site_line = previous_call_site_line;
        return ptn_null();
    }

    const char *previous_forward_static_called_class_name =
        runtime->forward_static_called_class_name;
    int previous_warn_by_ref_argument_mismatch = runtime->warn_by_ref_argument_mismatch;
    const char *forward_called_class = runtime->current_called_class_name != NULL
        ? runtime->current_called_class_name
        : runtime->current_class_name;
    runtime->forward_static_called_class_name = forward_called_class;
    runtime->warn_by_ref_argument_mismatch = 1;

    PtnValue result = ptn_null();
    int ok = ptn_internal_call_callback_capturing_exception_impl(
        runtime,
        callback,
        argc - 1,
        argc > 1 ? args + 1 : NULL,
        NULL,
        line,
        1,
        0,
        &result
    );

    runtime->warn_by_ref_argument_mismatch = previous_warn_by_ref_argument_mismatch;
    runtime->forward_static_called_class_name = previous_forward_static_called_class_name;
    ptn_value_destroy(&callback);
    runtime->call_site_line = previous_call_site_line;
    if (!ok) {
        ptn_rethrow_exception(runtime);
    }
    return result;
}

static PtnValue ptn_internal_forward_static_call_array(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    const char *const *call_arg_names = runtime->next_call_arg_names;
    runtime->next_call_arg_names = NULL;
    size_t callback_index = 0;
    size_t arguments_index = 1;
    if (!ptn_internal_named_argument_index(argc, call_arg_names, "callback", 0, &callback_index) ||
        !ptn_internal_named_argument_index(argc, call_arg_names, "args", 1, &arguments_index)) {
        ptn_throw_internal_argument_count_error(
            runtime,
            "forward_static_call_array",
            "exactly",
            2,
            argc,
            line,
            args
        );
        return ptn_null();
    }

    PtnValue callback = ptn_internal_expect_callback_arg(runtime, "forward_static_call_array", 1, "callback", args[callback_index]);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }

    PtnCallArguments expanded;
    ptn_call_arguments_init(&expanded);
    expanded.use_plain_positional_after_named_message = 1;
    ptn_call_arguments_unpack(runtime, &expanded, args[arguments_index], line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_call_arguments_destroy(&expanded);
        ptn_value_destroy(&callback);
        return ptn_null();
    }

    if (runtime->current_class_name == NULL && runtime->current_called_class_name == NULL) {
        ptn_call_arguments_destroy(&expanded);
        ptn_value_destroy(&callback);
        PtnRuntime *root = ptn_runtime_root(runtime);
        const char *path =
            line == 0 &&
            root != NULL &&
            root->shutdown_functions_running
                ? "[no active file]"
                : runtime->source_path;
        ptn_throw_exception_at(
            runtime,
            "Error",
            "Cannot call forward_static_call_array() when no class scope is active",
            path,
            line
        );
        return ptn_null();
    }

    size_t previous_call_site_line = runtime->call_site_line;
    runtime->call_site_line = line;
    const char *previous_forward_static_called_class_name =
        runtime->forward_static_called_class_name;
    int previous_warn_by_ref_argument_mismatch = runtime->warn_by_ref_argument_mismatch;
    const char *forward_called_class = runtime->current_called_class_name != NULL
        ? runtime->current_called_class_name
        : runtime->current_class_name;
    runtime->forward_static_called_class_name = forward_called_class;
    runtime->warn_by_ref_argument_mismatch = 1;

    PtnValue result = ptn_null();
    int ok = ptn_internal_call_callback_capturing_exception_impl(
        runtime,
        callback,
        expanded.len,
        expanded.values,
        (const char *const *)expanded.names,
        line,
        1,
        0,
        &result
    );

    runtime->warn_by_ref_argument_mismatch = previous_warn_by_ref_argument_mismatch;
    runtime->forward_static_called_class_name = previous_forward_static_called_class_name;
    runtime->call_site_line = previous_call_site_line;
    ptn_call_arguments_destroy(&expanded);
    ptn_value_destroy(&callback);
    if (!ok) {
        ptn_rethrow_exception(runtime);
    }
    return result;
}

static int ptn_spl_object_id(PtnValue value, size_t *id_out) {
    value = ptn_value_deref(value);
    switch (value.type) {
        case PTN_OBJECT:
            *id_out = value.as.object->object_id;
            return 1;
        case PTN_CLOSURE:
            *id_out = value.as.closure->object_id;
            return 1;
        case PTN_EXCEPTION:
            *id_out = value.as.exception->object_id;
            return 1;
        case PTN_NULL:
        case PTN_BOOL:
        case PTN_INT:
        case PTN_FLOAT:
        case PTN_STRING:
        case PTN_RESOURCE:
        case PTN_ARRAY:
        case PTN_REFERENCE:
            return 0;
    }
    return 0;
}

static PtnValue ptn_internal_spl_object_id(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)line;
    size_t id = 0;
    if (ptn_spl_object_id(args[0], &id)) {
        return ptn_int((int64_t)id);
    }

    PtnValue value = ptn_value_deref(args[0]);
    char message[192];
    int written = snprintf(
        message,
        sizeof(message),
        "spl_object_id(): Argument #1 ($object) must be of type object, %s given",
        ptn_offset_container_type_name(value)
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "TypeError", message);
    return ptn_null();
}

static PtnValue ptn_internal_spl_object_hash(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)line;
    size_t id = 0;
    if (!ptn_spl_object_id(args[0], &id)) {
        PtnValue value = ptn_value_deref(args[0]);
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "spl_object_hash(): Argument #1 ($object) must be of type object, %s given",
            ptn_offset_container_type_name(value)
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "TypeError", message);
        return ptn_null();
    }

    char buffer[33];
    int written = snprintf(buffer, sizeof(buffer), "%016llx0000000000000000", (unsigned long long)id);
    if (written < 0 || written != 32) {
        ptn_abort_out_of_memory();
    }
    return ptn_owned_string(ptn_duplicate_string(buffer));
}

static PtnValue ptn_internal_assert_options(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    ptn_emit_deprecation(&runtime->diagnostics, "Function assert_options() is deprecated since 8.3", line);
    int64_t option = ptn_value_to_integer(args[0]);
    PtnValue previous = ptn_null();
    switch (option) {
        case 1:
            previous = ptn_int(ptn_runtime_assert_active(runtime));
            if (argc >= 2) {
                ptn_runtime_set_assert_active(runtime, ptn_is_truthy(args[1]));
            }
            return previous;
        case 2:
            previous = ptn_runtime_assert_callback(runtime);
            if (argc >= 2) {
                ptn_runtime_set_assert_callback_value(runtime, args[1]);
            }
            return previous;
        case 3:
            previous = ptn_int(ptn_runtime_assert_bail(runtime));
            if (argc >= 2) {
                ptn_runtime_set_assert_bail(runtime, ptn_is_truthy(args[1]));
            }
            return previous;
        case 4:
            previous = ptn_int(ptn_runtime_assert_warning(runtime));
            if (argc >= 2) {
                ptn_runtime_set_assert_warning(runtime, ptn_is_truthy(args[1]));
            }
            return previous;
        case 5:
            previous = ptn_int(ptn_runtime_assert_exception(runtime));
            if (argc >= 2) {
                ptn_runtime_set_assert_exception(runtime, ptn_is_truthy(args[1]));
            }
            return previous;
        default:
            ptn_throw_exception(runtime, "ValueError", "assert_options(): Argument #1 ($option) must be an ASSERT_* constant");
            return ptn_null();
    }
}

static char *ptn_assert_invalid_callback_reason(PtnRuntime *runtime, PtnValue callback) {
    PtnValue resolved = ptn_value_deref(callback);
    if (resolved.type == PTN_STRING) {
        char *name = ptn_value_to_string(resolved);
        int needed = snprintf(
            NULL,
            0,
            "function \"%s\" not found or invalid function name",
            name
        );
        if (needed < 0) {
            ptn_abort_out_of_memory();
        }
        char *reason = malloc((size_t)needed + 1);
        if (reason == NULL) {
            ptn_abort_out_of_memory();
        }
        snprintf(
            reason,
            (size_t)needed + 1,
            "function \"%s\" not found or invalid function name",
            name
        );
        free(name);
        return reason;
    }
    if (resolved.type == PTN_ARRAY) {
        char *reason = ptn_invalid_array_callback_reason(runtime, resolved);
        return reason == NULL ? ptn_duplicate_string("not a valid method callback") : reason;
    }
    return ptn_duplicate_string("no array or string given");
}

static void ptn_assert_set_invalid_callback_exception(PtnRuntime *runtime, PtnValue callback, size_t line) {
    char *name = ptn_callable_output_name(callback);
    char *reason = ptn_assert_invalid_callback_reason(runtime, callback);
    int needed = snprintf(NULL, 0, "Invalid callback %s, %s", name, reason);
    if (needed < 0) {
        ptn_abort_out_of_memory();
    }
    char *message = malloc((size_t)needed + 1);
    if (message == NULL) {
        ptn_abort_out_of_memory();
    }
    snprintf(message, (size_t)needed + 1, "Invalid callback %s, %s", name, reason);
    free(name);
    free(reason);
    PtnValue previous = ptn_exception_previous_or_active(runtime, ptn_null());
    PtnException *exception = ptn_exception_new_owned(
        runtime,
        "Error",
        message,
        strlen(message),
        0,
        previous,
        PTN_E_ERROR,
        runtime->source_path,
        line
    );
    ptn_exception_free(runtime->exceptions->active_exception);
    runtime->exceptions->active_exception = exception;
}

static void ptn_assert_set_assertion_exception(PtnRuntime *runtime, char *message, size_t line) {
    PtnValue previous = ptn_exception_previous_or_active(runtime, ptn_null());
    PtnException *exception = ptn_exception_new_owned(
        runtime,
        "AssertionError",
        message,
        strlen(message),
        0,
        previous,
        PTN_E_ERROR,
        runtime->source_path,
        line
    );
    ptn_exception_free(runtime->exceptions->active_exception);
    runtime->exceptions->active_exception = exception;
}

static PtnValue ptn_internal_assert(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    if (ptn_runtime_current_zend_assertions(runtime) <= 0) {
        return ptn_bool(1);
    }
    if (!ptn_runtime_assert_active(runtime)) {
        return ptn_bool(1);
    }
    if (ptn_is_truthy(args[0])) {
        return ptn_bool(1);
    }

    char *message = argc >= 2 ? ptn_value_to_string(args[1]) : ptn_duplicate_string("");
    int has_callback_exception = 0;
    PtnValue callback = ptn_null();
    if (ptn_runtime_assert_callback_configured(runtime)) {
        callback = ptn_runtime_assert_callback(runtime);
        if (ptn_callable_is_valid(runtime, callback, 0)) {
            PtnValue callback_args[4] = {
                ptn_owned_string(ptn_duplicate_string(runtime->source_path == NULL ? "" : runtime->source_path)),
                ptn_int((int64_t)line),
                ptn_null(),
                ptn_owned_string(ptn_duplicate_string(message))
            };
            PtnValue callback_result = ptn_null();
            int callback_succeeded = ptn_internal_call_callback_capturing_exception(
                runtime,
                callback,
                4,
                callback_args,
                line,
                &callback_result
            );
            for (size_t i = 0; i < 4; i++) {
                ptn_value_destroy(&callback_args[i]);
            }
            ptn_value_destroy(&callback_result);
            if (!callback_succeeded) {
                has_callback_exception = 1;
            }
        } else {
            ptn_assert_set_invalid_callback_exception(runtime, callback, line);
            has_callback_exception = 1;
        }
    }

    if (ptn_runtime_assert_exception(runtime)) {
        if (argc >= 2) {
            PtnValue reason = ptn_value_deref(args[1]);
            if (
                reason.type == PTN_EXCEPTION ||
                (reason.type == PTN_OBJECT && ptn_object_is_declared_throwable(runtime, reason.as.object))
            ) {
                if (
                    runtime->trace_frame != NULL &&
                    runtime->trace_frame->function_name != NULL &&
                    ptn_exception_name_equal(runtime->trace_frame->function_name, "assert")
                ) {
                    runtime->trace_frame = runtime->trace_frame->previous;
                }
                ptn_throw_value(runtime, reason, runtime->source_path, line);
                ptn_value_destroy(&callback);
                free(message);
                return ptn_bool(0);
            }
        }
        ptn_assert_set_assertion_exception(runtime, message, line);
        if (ptn_runtime_assert_bail(runtime)) {
            ptn_value_destroy(&callback);
            ptn_emit_uncaught_exception(runtime, runtime->exceptions->active_exception);
            ptn_runtime_shutdown_before_exit(runtime);
            exit(255);
        }
        ptn_value_destroy(&callback);
        ptn_rethrow_exception(runtime);
        return ptn_bool(0);
    } else {
        if (ptn_runtime_assert_warning(runtime)) {
            size_t message_len = strlen(message);
            const char *prefix = "assert(): ";
            const char *suffix = " failed";
            size_t warning_len = strlen(prefix) + message_len + strlen(suffix);
            char *warning = malloc(warning_len + 1);
            if (warning == NULL) {
                ptn_value_destroy(&callback);
                free(message);
                ptn_abort_out_of_memory();
            }
            snprintf(warning, warning_len + 1, "%s%s%s", prefix, message, suffix);
            ptn_emit_warning(&runtime->diagnostics, warning, line);
            free(warning);
        }
        if (has_callback_exception) {
            if (ptn_runtime_assert_bail(runtime)) {
                ptn_value_destroy(&callback);
                free(message);
                ptn_emit_uncaught_exception_warning(runtime, runtime->exceptions->active_exception);
                exit(0);
            }
            ptn_value_destroy(&callback);
            free(message);
            ptn_rethrow_exception(runtime);
            return ptn_null();
        }
        if (ptn_runtime_assert_bail(runtime)) {
            ptn_value_destroy(&callback);
            free(message);
            exit(0);
        }
    }
    ptn_value_destroy(&callback);
    free(message);
    return ptn_bool(0);
}

static const char *ptn_date_weekday_short(int wday) {
    static const char *names[] = { "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat" };
    return names[wday >= 0 && wday < 7 ? wday : 0];
}

static const char *ptn_date_weekday_long(int wday) {
    static const char *names[] = { "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday" };
    return names[wday >= 0 && wday < 7 ? wday : 0];
}

static const char *ptn_date_month_short(int mon) {
    static const char *names[] = { "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" };
    return names[mon >= 0 && mon < 12 ? mon : 0];
}

static const char *ptn_date_month_long(int mon) {
    static const char *names[] = {
        "January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December"
    };
    return names[mon >= 0 && mon < 12 ? mon : 0];
}

static int ptn_date_is_leap_year(int year) {
    return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
}

static int ptn_date_is_leap_year_i64(int64_t year) {
    return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
}

static int ptn_date_days_in_month(int year, int month) {
    static const int days[] = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    if (month == 2 && ptn_date_is_leap_year(year)) {
        return 29;
    }
    return month >= 1 && month <= 12 ? days[month - 1] : 31;
}

static int ptn_date_days_in_month_i64(int64_t year, int month) {
    static const int days[] = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    if (month == 2 && ptn_date_is_leap_year_i64(year)) {
        return 29;
    }
    return month >= 1 && month <= 12 ? days[month - 1] : 31;
}

static int ptn_date_weekday_for_date(int year, int month, int day) {
    static const int offsets[] = { 0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4 };
    if (month < 3) {
        year--;
    }
    int weekday = (year + year / 4 - year / 100 + year / 400 + offsets[month - 1] + day) % 7;
    return weekday < 0 ? weekday + 7 : weekday;
}

static int64_t ptn_date_floor_div_i64(int64_t value, int64_t divisor) {
    int64_t quotient = value / divisor;
    int64_t remainder = value % divisor;
    if (remainder != 0 && ((remainder < 0) != (divisor < 0))) {
        quotient--;
    }
    return quotient;
}

static int ptn_date_weekday_for_date_i64(int64_t year, int month, int day) {
    static const int offsets[] = { 0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4 };
    if (month < 3) {
        year--;
    }
    int64_t weekday =
        year +
        ptn_date_floor_div_i64(year, 4) -
        ptn_date_floor_div_i64(year, 100) +
        ptn_date_floor_div_i64(year, 400) +
        offsets[month - 1] +
        day;
    weekday %= 7;
    return weekday < 0 ? (int)(weekday + 7) : (int)weekday;
}

static int ptn_date_iso_weeks_in_year(int year) {
    int jan1 = ptn_date_weekday_for_date(year, 1, 1);
    int jan1_iso = jan1 == 0 ? 7 : jan1;
    return jan1_iso == 4 || (jan1_iso == 3 && ptn_date_is_leap_year(year)) ? 53 : 52;
}

static int ptn_date_iso_weeks_in_year_i64(int64_t year) {
    int jan1 = ptn_date_weekday_for_date_i64(year, 1, 1);
    int jan1_iso = jan1 == 0 ? 7 : jan1;
    return jan1_iso == 4 || (jan1_iso == 3 && ptn_date_is_leap_year_i64(year)) ? 53 : 52;
}

static void ptn_date_iso_week_info(const struct tm *parts, int *iso_year_out, int *iso_week_out) {
    int year = parts->tm_year + 1900;
    int iso_weekday = parts->tm_wday == 0 ? 7 : parts->tm_wday;
    int ordinal = parts->tm_yday + 1;
    int week = (ordinal - iso_weekday + 10) / 7;
    if (week < 1) {
        year--;
        week = ptn_date_iso_weeks_in_year(year);
    } else {
        int weeks_in_year = ptn_date_iso_weeks_in_year(year);
        if (week > weeks_in_year) {
            year++;
            week = 1;
        }
    }
    *iso_year_out = year;
    *iso_week_out = week;
}

static void ptn_date_iso_week_info_i64(
    int64_t year,
    int yearday,
    int weekday,
    int64_t *iso_year_out,
    int *iso_week_out
) {
    int64_t iso_year = year;
    int iso_weekday = weekday == 0 ? 7 : weekday;
    int ordinal = yearday + 1;
    int week = (ordinal - iso_weekday + 10) / 7;
    if (week < 1) {
        iso_year--;
        week = ptn_date_iso_weeks_in_year_i64(iso_year);
    } else {
        int weeks_in_year = ptn_date_iso_weeks_in_year_i64(iso_year);
        if (week > weeks_in_year) {
            iso_year++;
            week = 1;
        }
    }
    *iso_year_out = iso_year;
    *iso_week_out = week;
}

static const char *ptn_date_day_suffix(int day) {
    if (day >= 11 && day <= 13) {
        return "th";
    }
    switch (day % 10) {
        case 1:
            return "st";
        case 2:
            return "nd";
        case 3:
            return "rd";
        default:
            return "th";
    }
}

static void ptn_tzset(void) {
#if defined(_WIN32)
    _tzset();
#else
    tzset();
#endif
}

static void ptn_set_timezone_env(const char *timezone) {
#if defined(_WIN32)
    size_t len = strlen(timezone) + 4;
    char *assignment = malloc(len);
    if (assignment == NULL) {
        ptn_abort_out_of_memory();
    }
    snprintf(assignment, len, "TZ=%s", timezone);
    _putenv(assignment);
    free(assignment);
#else
    setenv("TZ", timezone, 1);
#endif
    ptn_tzset();
}

static int ptn_timezone_identifier_is_known(const char *name);
static int ptn_configured_date_timezone_is_invalid(const char **value_out) {
    const char *timezone = getenv("PTN_DATE_TIMEZONE");
    if (timezone == NULL) {
        return 0;
    }
    if (value_out != NULL) {
        *value_out = timezone;
    }
    return !ptn_timezone_identifier_is_known(timezone);
}

static const char *ptn_current_timezone_name(void) {
    const char *timezone = getenv("TZ");
    if (timezone != NULL && timezone[0] != '\0') {
        return timezone;
    }
    timezone = getenv("PTN_DATE_TIMEZONE");
    return timezone != NULL && ptn_timezone_identifier_is_known(timezone) ? timezone : "UTC";
}

static int ptn_timezone_uses_z_designator(const char *name);

static int ptn_timezone_name_is_supported(PtnStringOperand timezone) {
    if (timezone.len == 0 || memchr(timezone.data, '\0', timezone.len) != NULL) {
        return 0;
    }
    char *name = ptn_duplicate_string_len(timezone.data, timezone.len);
    int supported = ptn_timezone_identifier_is_known(name);
    free(name);
    return supported;
}

static time_t ptn_mktime_in_utc(struct tm *parts) {
    const char *old_tz = getenv("TZ");
    char *old_copy = old_tz == NULL ? NULL : ptn_duplicate_string(old_tz);
    ptn_set_timezone_env("UTC");
    time_t result = mktime(parts);
    if (old_copy == NULL) {
#if defined(_WIN32)
        _putenv("TZ=");
#else
        unsetenv("TZ");
#endif
        ptn_tzset();
    } else {
        ptn_set_timezone_env(old_copy);
        free(old_copy);
    }
    return result;
}

static int64_t ptn_date_timezone_offset(time_t timestamp) {
    struct tm utc_parts;
    struct tm *utc = gmtime(&timestamp);
    if (utc == NULL) {
        return 0;
    }
    utc_parts = *utc;
    utc_parts.tm_isdst = -1;
    time_t local_interpretation = mktime(&utc_parts);
    if (local_interpretation == (time_t)-1) {
        return 0;
    }
    return (int64_t)difftime(timestamp, local_interpretation);
}

static void ptn_date_append_offset(PtnStringBuffer *buffer, int64_t offset, int colon) {
    char sign = offset < 0 ? '-' : '+';
    int64_t absolute = offset < 0 ? -offset : offset;
    int64_t hours = absolute / 3600;
    int64_t minutes = (absolute % 3600) / 60;
    if (colon) {
        ptn_string_buffer_append_format(buffer, "%c%02lld:%02lld", sign, (long long)hours, (long long)minutes);
    } else {
        ptn_string_buffer_append_format(buffer, "%c%02lld%02lld", sign, (long long)hours, (long long)minutes);
    }
}

static void ptn_date_append_year(PtnStringBuffer *buffer, int64_t year) {
    if (year < 0) {
        ptn_string_buffer_append_format(buffer, "-%04lld", (long long)-year);
    } else {
        ptn_string_buffer_append_format(buffer, "%04lld", (long long)year);
    }
}

static void ptn_date_append_expanded_year(PtnStringBuffer *buffer, int64_t year) {
    if (year < 0) {
        ptn_string_buffer_append_format(buffer, "-%04lld", (long long)-year);
    } else {
        ptn_string_buffer_append_format(buffer, "+%04lld", (long long)year);
    }
}

static void ptn_date_append_iso_year(PtnStringBuffer *buffer, int64_t year) {
    if (year < 0) {
        ptn_string_buffer_append_format(buffer, "%lld", (long long)year);
    } else {
        ptn_string_buffer_append_format(buffer, "%04lld", (long long)year);
    }
}

static int ptn_date_swatch_beats(time_t timestamp) {
    struct tm *utc = gmtime(&timestamp);
    if (utc == NULL) {
        return 0;
    }
    int seconds = utc->tm_hour * 3600 + utc->tm_min * 60 + utc->tm_sec + 3600;
    seconds %= 86400;
    if (seconds < 0) {
        seconds += 86400;
    }
    return (int)floor((double)seconds / 86.4);
}

static PtnValue ptn_format_date_value(PtnRuntime *runtime, const char *function_name, PtnStringOperand format, time_t timestamp, int use_gmt, size_t line) {
    (void)runtime;
    (void)function_name;
    (void)line;
    struct tm parts_storage;
    struct tm *parts = use_gmt ? gmtime(&timestamp) : localtime(&timestamp);
    if (parts == NULL) {
        return ptn_bool(0);
    }
    parts_storage = *parts;
    parts = &parts_storage;

    PtnStringBuffer buffer;
    ptn_string_buffer_init(&buffer);
    int year = parts->tm_year + 1900;
    int month = parts->tm_mon + 1;
    int64_t offset = use_gmt ? 0 : ptn_date_timezone_offset(timestamp);
    for (size_t i = 0; i < format.len; i++) {
        char ch = format.data[i];
        if (ch == '\\' && i + 1 < format.len) {
            i++;
            ptn_string_buffer_append_char(&buffer, format.data[i]);
            continue;
        }
        switch (ch) {
            case 'D':
                ptn_string_buffer_append(&buffer, ptn_date_weekday_short(parts->tm_wday));
                break;
            case 'l':
                ptn_string_buffer_append(&buffer, ptn_date_weekday_long(parts->tm_wday));
                break;
            case 'N':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_wday == 0 ? 7 : parts->tm_wday);
                break;
            case 'w':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_wday);
                break;
            case 'z':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_yday);
                break;
            case 'W': {
                int64_t iso_year = 0;
                int iso_week = 0;
                ptn_date_iso_week_info_i64(year, parts->tm_yday, parts->tm_wday, &iso_year, &iso_week);
                (void)iso_year;
                ptn_string_buffer_append_format(&buffer, "%02d", iso_week);
                break;
            }
            case 'o': {
                int64_t iso_year = 0;
                int iso_week = 0;
                ptn_date_iso_week_info_i64(year, parts->tm_yday, parts->tm_wday, &iso_year, &iso_week);
                (void)iso_week;
                ptn_date_append_iso_year(&buffer, iso_year);
                break;
            }
            case 'c':
                ptn_date_append_year(&buffer, year);
                ptn_string_buffer_append_format(&buffer, "-%02d-%02dT%02d:%02d:%02d", month, parts->tm_mday, parts->tm_hour, parts->tm_min, parts->tm_sec);
                ptn_date_append_offset(&buffer, offset, 1);
                break;
            case 'r':
                ptn_string_buffer_append_format(&buffer, "%s, %02d %s ", ptn_date_weekday_short(parts->tm_wday), parts->tm_mday, ptn_date_month_short(parts->tm_mon));
                ptn_date_append_year(&buffer, year);
                ptn_string_buffer_append_format(&buffer, " %02d:%02d:%02d ", parts->tm_hour, parts->tm_min, parts->tm_sec);
                ptn_date_append_offset(&buffer, offset, 0);
                break;
            case 'F':
                ptn_string_buffer_append(&buffer, ptn_date_month_long(parts->tm_mon));
                break;
            case 'M':
                ptn_string_buffer_append(&buffer, ptn_date_month_short(parts->tm_mon));
                break;
            case 'Y':
                ptn_date_append_year(&buffer, year);
                break;
            case 'X':
                ptn_date_append_expanded_year(&buffer, year);
                break;
            case 'y':
                ptn_string_buffer_append_format(&buffer, "%02d", year % 100);
                break;
            case 'm':
                ptn_string_buffer_append_format(&buffer, "%02d", month);
                break;
            case 'n':
                ptn_string_buffer_append_format(&buffer, "%d", month);
                break;
            case 't':
                ptn_string_buffer_append_format(&buffer, "%d", ptn_date_days_in_month(year, month));
                break;
            case 'L':
                ptn_string_buffer_append_format(&buffer, "%d", ptn_date_is_leap_year(year));
                break;
            case 'd':
                ptn_string_buffer_append_format(&buffer, "%02d", parts->tm_mday);
                break;
            case 'j':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_mday);
                break;
            case 'S':
                ptn_string_buffer_append(&buffer, ptn_date_day_suffix(parts->tm_mday));
                break;
            case 'a':
                ptn_string_buffer_append(&buffer, parts->tm_hour < 12 ? "am" : "pm");
                break;
            case 'A':
                ptn_string_buffer_append(&buffer, parts->tm_hour < 12 ? "AM" : "PM");
                break;
            case 'B':
                ptn_string_buffer_append_format(&buffer, "%03d", ptn_date_swatch_beats(timestamp));
                break;
            case 'g': {
                int hour = parts->tm_hour % 12;
                if (hour == 0) {
                    hour = 12;
                }
                ptn_string_buffer_append_format(&buffer, "%d", hour);
                break;
            }
            case 'G':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_hour);
                break;
            case 'H':
                ptn_string_buffer_append_format(&buffer, "%02d", parts->tm_hour);
                break;
            case 'h': {
                int hour = parts->tm_hour % 12;
                if (hour == 0) {
                    hour = 12;
                }
                ptn_string_buffer_append_format(&buffer, "%02d", hour);
                break;
            }
            case 'i':
                ptn_string_buffer_append_format(&buffer, "%02d", parts->tm_min);
                break;
            case 's':
                ptn_string_buffer_append_format(&buffer, "%02d", parts->tm_sec);
                break;
            case 'u':
                ptn_string_buffer_append(&buffer, "000000");
                break;
            case 'v':
                ptn_string_buffer_append(&buffer, "000");
                break;
            case 'I':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_isdst > 0 ? 1 : 0);
                break;
            case 'O':
                ptn_date_append_offset(&buffer, offset, 0);
                break;
            case 'P':
                ptn_date_append_offset(&buffer, offset, 1);
                break;
            case 'p':
                if (offset == 0 && ptn_timezone_uses_z_designator(use_gmt ? "UTC" : ptn_current_timezone_name())) {
                    ptn_string_buffer_append_char(&buffer, 'Z');
                } else {
                    ptn_date_append_offset(&buffer, offset, 1);
                }
                break;
            case 'T': {
                char zone[64];
                if (strftime(zone, sizeof(zone), "%Z", parts) == 0) {
                    zone[0] = '\0';
                }
                ptn_string_buffer_append(&buffer, use_gmt ? "GMT" : zone);
                break;
            }
            case 'e':
                ptn_string_buffer_append(&buffer, use_gmt ? "UTC" : ptn_current_timezone_name());
                break;
            case 'Z':
                ptn_string_buffer_append_format(&buffer, "%lld", (long long)offset);
                break;
            case 'U':
                ptn_string_buffer_append_format(&buffer, "%lld", (long long)timestamp);
                break;
            default:
                ptn_string_buffer_append_char(&buffer, ch);
                break;
        }
    }
    return ptn_owned_string_len(buffer.data, buffer.len);
}

static int ptn_timezone_offset_for_name(const char *name, time_t timestamp);
static int ptn_timezone_offset_for_wall_timestamp(const char *name, time_t wall_timestamp);
static int ptn_datetime_timestamp_dst_month(time_t timestamp);
static int ptn_timezone_is_dst_for_name(const char *name, time_t timestamp);
static const char *ptn_timezone_abbreviation_for_name(const char *name, time_t timestamp);

typedef struct {
    int64_t year;
    int month;
    int day;
    int hour;
    int minute;
    int second;
    int weekday;
    int yearday;
} PtnDateTimeCivilParts;

static int64_t ptn_datetime_clamp_i128_to_i64(__int128 value);
static void ptn_datetime_break_timestamp(int64_t timestamp, PtnDateTimeCivilParts *out);

static PtnValue ptn_format_date_value_for_timezone(
    PtnRuntime *runtime,
    const char *function_name,
    PtnStringOperand format,
    time_t timestamp,
    int microsecond,
    const char *timezone,
    size_t line
) {
    (void)runtime;
    (void)function_name;
    (void)line;
    int64_t offset = ptn_timezone_offset_for_name(timezone, timestamp);
    int64_t wall_timestamp = ptn_datetime_clamp_i128_to_i64((__int128)timestamp + (__int128)offset);
    PtnDateTimeCivilParts civil;
    ptn_datetime_break_timestamp(wall_timestamp, &civil);
    struct tm parts_storage;
    memset(&parts_storage, 0, sizeof(parts_storage));
    if (civil.year - 1900 > INT_MAX) {
        parts_storage.tm_year = INT_MAX;
    } else if (civil.year - 1900 < INT_MIN) {
        parts_storage.tm_year = INT_MIN;
    } else {
        parts_storage.tm_year = (int)(civil.year - 1900);
    }
    parts_storage.tm_mon = civil.month - 1;
    parts_storage.tm_mday = civil.day;
    parts_storage.tm_hour = civil.hour;
    parts_storage.tm_min = civil.minute;
    parts_storage.tm_sec = civil.second;
    parts_storage.tm_wday = civil.weekday;
    parts_storage.tm_yday = civil.yearday;
    struct tm *parts = &parts_storage;

    PtnStringBuffer buffer;
    ptn_string_buffer_init(&buffer);
    int64_t year = civil.year;
    int month = civil.month;
    for (size_t i = 0; i < format.len; i++) {
        char ch = format.data[i];
        if (ch == '\\' && i + 1 < format.len) {
            i++;
            ptn_string_buffer_append_char(&buffer, format.data[i]);
            continue;
        }
        switch (ch) {
            case 'D':
                ptn_string_buffer_append(&buffer, ptn_date_weekday_short(parts->tm_wday));
                break;
            case 'l':
                ptn_string_buffer_append(&buffer, ptn_date_weekday_long(parts->tm_wday));
                break;
            case 'N':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_wday == 0 ? 7 : parts->tm_wday);
                break;
            case 'w':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_wday);
                break;
            case 'z':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_yday);
                break;
            case 'W': {
                int64_t iso_year = 0;
                int iso_week = 0;
                ptn_date_iso_week_info_i64(year, parts->tm_yday, parts->tm_wday, &iso_year, &iso_week);
                (void)iso_year;
                ptn_string_buffer_append_format(&buffer, "%02d", iso_week);
                break;
            }
            case 'o': {
                int64_t iso_year = 0;
                int iso_week = 0;
                ptn_date_iso_week_info_i64(year, parts->tm_yday, parts->tm_wday, &iso_year, &iso_week);
                (void)iso_week;
                ptn_date_append_iso_year(&buffer, iso_year);
                break;
            }
            case 'c':
                ptn_date_append_year(&buffer, year);
                ptn_string_buffer_append_format(&buffer, "-%02d-%02dT%02d:%02d:%02d", month, parts->tm_mday, parts->tm_hour, parts->tm_min, parts->tm_sec);
                ptn_date_append_offset(&buffer, offset, 1);
                break;
            case 'r':
                ptn_string_buffer_append_format(&buffer, "%s, %02d %s ", ptn_date_weekday_short(parts->tm_wday), parts->tm_mday, ptn_date_month_short(parts->tm_mon));
                ptn_date_append_year(&buffer, year);
                ptn_string_buffer_append_format(&buffer, " %02d:%02d:%02d ", parts->tm_hour, parts->tm_min, parts->tm_sec);
                ptn_date_append_offset(&buffer, offset, 0);
                break;
            case 'F':
                ptn_string_buffer_append(&buffer, ptn_date_month_long(parts->tm_mon));
                break;
            case 'M':
                ptn_string_buffer_append(&buffer, ptn_date_month_short(parts->tm_mon));
                break;
            case 'Y':
                ptn_date_append_year(&buffer, year);
                break;
            case 'X':
                ptn_date_append_expanded_year(&buffer, year);
                break;
            case 'y':
                ptn_string_buffer_append_format(&buffer, "%02lld", (long long)(year % 100));
                break;
            case 'm':
                ptn_string_buffer_append_format(&buffer, "%02d", month);
                break;
            case 'n':
                ptn_string_buffer_append_format(&buffer, "%d", month);
                break;
            case 't':
                ptn_string_buffer_append_format(&buffer, "%d", ptn_date_days_in_month_i64(year, month));
                break;
            case 'L':
                ptn_string_buffer_append_format(&buffer, "%d", ptn_date_is_leap_year_i64(year));
                break;
            case 'd':
                ptn_string_buffer_append_format(&buffer, "%02d", parts->tm_mday);
                break;
            case 'j':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_mday);
                break;
            case 'S':
                ptn_string_buffer_append(&buffer, ptn_date_day_suffix(parts->tm_mday));
                break;
            case 'a':
                ptn_string_buffer_append(&buffer, parts->tm_hour < 12 ? "am" : "pm");
                break;
            case 'A':
                ptn_string_buffer_append(&buffer, parts->tm_hour < 12 ? "AM" : "PM");
                break;
            case 'B':
                ptn_string_buffer_append_format(&buffer, "%03d", ptn_date_swatch_beats(timestamp));
                break;
            case 'g': {
                int hour = parts->tm_hour % 12;
                if (hour == 0) {
                    hour = 12;
                }
                ptn_string_buffer_append_format(&buffer, "%d", hour);
                break;
            }
            case 'G':
                ptn_string_buffer_append_format(&buffer, "%d", parts->tm_hour);
                break;
            case 'H':
                ptn_string_buffer_append_format(&buffer, "%02d", parts->tm_hour);
                break;
            case 'h': {
                int hour = parts->tm_hour % 12;
                if (hour == 0) {
                    hour = 12;
                }
                ptn_string_buffer_append_format(&buffer, "%02d", hour);
                break;
            }
            case 'i':
                ptn_string_buffer_append_format(&buffer, "%02d", parts->tm_min);
                break;
            case 's':
                ptn_string_buffer_append_format(&buffer, "%02d", parts->tm_sec);
                break;
            case 'u':
                ptn_string_buffer_append_format(&buffer, "%06d", microsecond);
                break;
            case 'v':
                ptn_string_buffer_append_format(&buffer, "%03d", microsecond / 1000);
                break;
            case 'I':
                ptn_string_buffer_append_format(&buffer, "%d", ptn_timezone_is_dst_for_name(timezone, timestamp));
                break;
            case 'O':
                ptn_date_append_offset(&buffer, offset, 0);
                break;
            case 'P':
                ptn_date_append_offset(&buffer, offset, 1);
                break;
            case 'p':
                if (offset == 0 && ptn_timezone_uses_z_designator(timezone)) {
                    ptn_string_buffer_append_char(&buffer, 'Z');
                } else {
                    ptn_date_append_offset(&buffer, offset, 1);
                }
                break;
            case 'T':
                ptn_string_buffer_append(&buffer, ptn_timezone_abbreviation_for_name(timezone, timestamp));
                break;
            case 'e':
                ptn_string_buffer_append(&buffer, timezone);
                break;
            case 'Z':
                ptn_string_buffer_append_format(&buffer, "%lld", (long long)offset);
                break;
            case 'U':
                ptn_string_buffer_append_format(&buffer, "%lld", (long long)timestamp);
                break;
            default:
                ptn_string_buffer_append_char(&buffer, ch);
                break;
        }
    }
    return ptn_owned_string_len(buffer.data, buffer.len);
}

static time_t ptn_date_mktime_from_args(size_t argc, const PtnValue *args, int use_gmt) {
    time_t now = time(NULL);
    struct tm parts_storage;
    struct tm *current = use_gmt ? gmtime(&now) : localtime(&now);
    if (current == NULL) {
        memset(&parts_storage, 0, sizeof(parts_storage));
        parts_storage.tm_mday = 1;
        parts_storage.tm_year = 70;
    } else {
        parts_storage = *current;
    }
    if (argc >= 1) {
        parts_storage.tm_hour = (int)ptn_value_to_integer(args[0]);
    }
    if (argc >= 2) {
        parts_storage.tm_min = (int)ptn_value_to_integer(args[1]);
    }
    if (argc >= 3) {
        parts_storage.tm_sec = (int)ptn_value_to_integer(args[2]);
    }
    if (argc >= 4) {
        parts_storage.tm_mon = (int)ptn_value_to_integer(args[3]) - 1;
    }
    if (argc >= 5) {
        parts_storage.tm_mday = (int)ptn_value_to_integer(args[4]);
    }
    if (argc >= 6) {
        int year = (int)ptn_value_to_integer(args[5]);
        if (year >= 0 && year <= 69) {
            year += 2000;
        } else if (year >= 70 && year <= 100) {
            year += 1900;
        }
        parts_storage.tm_year = year - 1900;
    }
    parts_storage.tm_isdst = -1;
    return use_gmt ? ptn_mktime_in_utc(&parts_storage) : mktime(&parts_storage);
}

static PtnValue ptn_internal_date(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand format = ptn_internal_expect_string_arg(runtime, "date", 1, "format", args[0], line);
    time_t timestamp = argc >= 2 ? (time_t)ptn_value_to_integer(args[1]) : time(NULL);
    PtnValue result = ptn_format_date_value_for_timezone(
        runtime,
        "date",
        format,
        timestamp,
        0,
        ptn_current_timezone_name(),
        line
    );
    ptn_string_operand_free(format);
    return result;
}

static PtnValue ptn_internal_gmdate(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand format = ptn_internal_expect_string_arg(runtime, "gmdate", 1, "format", args[0], line);
    time_t timestamp = argc >= 2 ? (time_t)ptn_value_to_integer(args[1]) : time(NULL);
    PtnValue result = ptn_format_date_value_for_timezone(runtime, "gmdate", format, timestamp, 0, "UTC", line);
    ptn_string_operand_free(format);
    return result;
}

static PtnValue ptn_internal_strftime_named(PtnRuntime *runtime, const char *function_name, int use_gmt, size_t argc, const PtnValue *args, size_t line) {
    char deprecation[128];
    int written = snprintf(
        deprecation,
        sizeof(deprecation),
        "Function %s() is deprecated since 8.1, use IntlDateFormatter::format() instead",
        function_name
    );
    if (written < 0 || (size_t)written >= sizeof(deprecation)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_deprecation(&runtime->diagnostics, deprecation, line);

    PtnStringOperand format = ptn_internal_expect_string_arg(runtime, function_name, 1, "format", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(format);
        return ptn_null();
    }
    time_t timestamp = argc >= 2 && ptn_value_deref(args[1]).type != PTN_NULL
        ? (time_t)ptn_value_to_integer(args[1])
        : time(NULL);
    struct tm parts_storage;
    struct tm *parts = use_gmt ? gmtime(&timestamp) : localtime(&timestamp);
    if (parts == NULL) {
        ptn_string_operand_free(format);
        return ptn_bool(0);
    }
    parts_storage = *parts;

    if (format.len == 0) {
        ptn_string_operand_free(format);
        return ptn_bool(0);
    }

    char *format_c = ptn_duplicate_string_len(format.data, format.len);
    if (format.len > (SIZE_MAX - 64) / 4) {
        free(format_c);
        ptn_string_operand_free(format);
        ptn_abort_out_of_memory();
    }
    size_t cap = (format.len * 4) + 64;
    if (cap < 128) {
        cap = 128;
    }
    for (;;) {
        char *output = malloc(cap);
        if (output == NULL) {
            free(format_c);
            ptn_string_operand_free(format);
            ptn_abort_out_of_memory();
        }
        size_t written = strftime(output, cap, format_c, &parts_storage);
        if (written > 0) {
            free(format_c);
            ptn_string_operand_free(format);
            return ptn_owned_string_len(output, written);
        }
        free(output);
        if (cap >= (1u << 20)) {
            free(format_c);
            ptn_string_operand_free(format);
            return ptn_string("");
        }
        cap *= 2;
    }
}

static PtnValue ptn_internal_strftime(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_strftime_named(runtime, "strftime", 0, argc, args, line);
}

static PtnValue ptn_internal_gmstrftime(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    return ptn_internal_strftime_named(runtime, "gmstrftime", 1, argc, args, line);
}

static PtnValue ptn_internal_mktime(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)line;
    return ptn_int((int64_t)ptn_date_mktime_from_args(argc, args, 0));
}

static PtnValue ptn_internal_gmmktime(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)line;
    return ptn_int((int64_t)ptn_date_mktime_from_args(argc, args, 1));
}

static PtnValue ptn_internal_time(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)argc;
    (void)args;
    (void)line;
    return ptn_int((int64_t)time(NULL));
}

static PtnValue ptn_internal_microtime(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)line;
    struct timeval now;
    if (gettimeofday(&now, NULL) != 0) {
        return ptn_bool(0);
    }
    double seconds = (double)now.tv_sec + ((double)now.tv_usec / 1000000.0);
    if (argc >= 1 && ptn_is_truthy(args[0])) {
        return ptn_float(seconds);
    }
    char buffer[64];
    int written = snprintf(buffer, sizeof(buffer), "%.6f %lld", (double)now.tv_usec / 1000000.0, (long long)now.tv_sec);
    if (written < 0 || (size_t)written >= sizeof(buffer)) {
        ptn_abort_out_of_memory();
    }
    return ptn_owned_string(ptn_duplicate_string(buffer));
}

static PtnValue ptn_internal_gettimeofday(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)line;
    struct timeval now;
    if (gettimeofday(&now, NULL) != 0) {
        return ptn_bool(0);
    }

    if (argc >= 1 && ptn_is_truthy(args[0])) {
        double seconds = (double)now.tv_sec + ((double)now.tv_usec / 1000000.0);
        return ptn_float(seconds);
    }

    time_t seconds = (time_t)now.tv_sec;
    int offset = ptn_timezone_offset_for_name(ptn_current_timezone_name(), seconds);
    int dsttime = 0;
    struct tm *local_parts = localtime(&seconds);
    if (local_parts != NULL && local_parts->tm_isdst > 0) {
        dsttime = 1;
    }

    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    ptn_array_set_entry(result.as.array, ptn_array_string_key("sec"), ptn_int((int64_t)now.tv_sec));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("usec"), ptn_int((int64_t)now.tv_usec));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("minuteswest"), ptn_int((int64_t)(-offset / 60)));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("dsttime"), ptn_int(dsttime));
    return result;
}

static PtnValue ptn_internal_date_default_timezone_get(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)args;
    (void)line;
    const char *configured_timezone = NULL;
    PtnRuntime *root = ptn_runtime_root(runtime);
    if (root == NULL) {
        root = runtime;
    }
    if (ptn_configured_date_timezone_is_invalid(&configured_timezone) && !root->date_timezone_startup_warning_emitted) {
        size_t message_len = strlen(configured_timezone) + 72;
        char *message = malloc(message_len);
        if (message == NULL) {
            ptn_abort_out_of_memory();
        }
        snprintf(message, message_len, "PHP Startup: Invalid date.timezone value '%s', using 'UTC' instead", configured_timezone);
        ptn_emit_compile_warning(runtime, message, "Unknown", 0);
        root->date_timezone_startup_warning_emitted = 1;
        free(message);
    }
    return ptn_string(ptn_current_timezone_name());
}

static PtnValue ptn_internal_date_default_timezone_set(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand timezone = ptn_internal_expect_string_arg(runtime, "date_default_timezone_set", 1, "timezoneId", args[0], line);
    if (!ptn_timezone_name_is_supported(timezone)) {
        char *name = ptn_duplicate_string_len(timezone.data, timezone.len);
        size_t message_len = strlen(name) + 64;
        char *message = malloc(message_len);
        if (message == NULL) {
            free(name);
            ptn_abort_out_of_memory();
        }
        snprintf(message, message_len, "date_default_timezone_set(): Timezone ID '%s' is invalid", name);
        ptn_emit_notice_with_path(&runtime->diagnostics, message, runtime->source_path, line, 1);
        runtime->diagnostics.emitted_warning = 1;
        free(message);
        free(name);
        ptn_string_operand_free(timezone);
        return ptn_bool(0);
    }
    char *name = ptn_duplicate_string_len(timezone.data, timezone.len);
    ptn_set_timezone_env(name);
    free(name);
    ptn_string_operand_free(timezone);
    return ptn_bool(1);
}

static PtnValue ptn_internal_checkdate(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)argc;
    (void)line;
    int month = (int)ptn_value_to_integer(args[0]);
    int day = (int)ptn_value_to_integer(args[1]);
    int year = (int)ptn_value_to_integer(args[2]);
    if (year < 1 || year > 32767 || month < 1 || month > 12 || day < 1) {
        return ptn_bool(0);
    }
    return ptn_bool(day <= ptn_date_days_in_month(year, month));
}

static int ptn_idate_value(char token, const struct tm *parts, time_t timestamp, int64_t offset, int *out) {
    int year = parts->tm_year + 1900;
    int month = parts->tm_mon + 1;
    switch (token) {
        case 'B':
            *out = ptn_date_swatch_beats(timestamp);
            return 1;
        case 'd':
            *out = parts->tm_mday;
            return 1;
        case 'h': {
            int hour = parts->tm_hour % 12;
            *out = hour == 0 ? 12 : hour;
            return 1;
        }
        case 'H':
            *out = parts->tm_hour;
            return 1;
        case 'i':
            *out = parts->tm_min;
            return 1;
        case 'I':
            *out = parts->tm_isdst > 0 ? 1 : 0;
            return 1;
        case 'L':
            *out = ptn_date_is_leap_year(year);
            return 1;
        case 'm':
        case 'n':
            *out = month;
            return 1;
        case 's':
            *out = parts->tm_sec;
            return 1;
        case 't':
            *out = ptn_date_days_in_month(year, month);
            return 1;
        case 'U':
            *out = (int)timestamp;
            return 1;
        case 'w':
            *out = parts->tm_wday;
            return 1;
        case 'W': {
            int iso_year = 0;
            int iso_week = 0;
            ptn_date_iso_week_info(parts, &iso_year, &iso_week);
            (void)iso_year;
            *out = iso_week;
            return 1;
        }
        case 'y':
            *out = year % 100;
            return 1;
        case 'Y':
            *out = year;
            return 1;
        case 'z':
            *out = parts->tm_yday;
            return 1;
        case 'Z':
            *out = (int)offset;
            return 1;
        default:
            return 0;
    }
}

static PtnValue ptn_internal_idate(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand format = ptn_internal_expect_string_arg(runtime, "idate", 1, "format", args[0], line);
    if (format.len != 1) {
        ptn_emit_warning(&runtime->diagnostics, "idate(): idate format is one char", line);
        ptn_string_operand_free(format);
        return ptn_bool(0);
    }
    time_t timestamp = argc >= 2 ? (time_t)ptn_value_to_integer(args[1]) : time(NULL);
    struct tm *parts = localtime(&timestamp);
    if (parts == NULL) {
        ptn_string_operand_free(format);
        return ptn_bool(0);
    }
    int value = 0;
    if (!ptn_idate_value(format.data[0], parts, timestamp, ptn_date_timezone_offset(timestamp), &value)) {
        ptn_emit_warning(&runtime->diagnostics, "idate(): Unrecognized date format token", line);
        ptn_string_operand_free(format);
        return ptn_bool(0);
    }
    ptn_string_operand_free(format);
    return ptn_int(value);
}

static PtnValue ptn_internal_getdate(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)line;
    time_t timestamp = argc >= 1 ? (time_t)ptn_value_to_integer(args[0]) : time(NULL);
    struct tm *parts = localtime(&timestamp);
    if (parts == NULL) {
        return ptn_bool(0);
    }
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    ptn_array_set_entry(result.as.array, ptn_array_string_key("seconds"), ptn_int(parts->tm_sec));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("minutes"), ptn_int(parts->tm_min));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("hours"), ptn_int(parts->tm_hour));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("mday"), ptn_int(parts->tm_mday));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("wday"), ptn_int(parts->tm_wday));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("mon"), ptn_int(parts->tm_mon + 1));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("year"), ptn_int(parts->tm_year + 1900));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("yday"), ptn_int(parts->tm_yday));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("weekday"), ptn_string(ptn_date_weekday_long(parts->tm_wday)));
    ptn_array_set_entry(result.as.array, ptn_array_string_key("month"), ptn_string(ptn_date_month_long(parts->tm_mon)));
    ptn_array_set_entry(result.as.array, ptn_array_int_key(0), ptn_int((int64_t)timestamp));
    return result;
}

static PtnValue ptn_internal_localtime(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)runtime;
    (void)line;
    time_t timestamp = argc >= 1 ? (time_t)ptn_value_to_integer(args[0]) : time(NULL);
    int associative = argc >= 2 && ptn_is_truthy(args[1]);
    struct tm *parts = localtime(&timestamp);
    if (parts == NULL) {
        return ptn_bool(0);
    }
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    const char *keys[] = { "tm_sec", "tm_min", "tm_hour", "tm_mday", "tm_mon", "tm_year", "tm_wday", "tm_yday", "tm_isdst" };
    int values[] = {
        parts->tm_sec, parts->tm_min, parts->tm_hour, parts->tm_mday, parts->tm_mon,
        parts->tm_year, parts->tm_wday, parts->tm_yday, parts->tm_isdst
    };
    for (int i = 0; i < 9; i++) {
        ptn_array_set_entry(
            result.as.array,
            associative ? ptn_array_string_key(keys[i]) : ptn_array_int_key(i),
            ptn_int(values[i])
        );
    }
    return result;
}

