static const char *ptn_xml_node_class_name(PtnXmlNode *node) {
    if (node == NULL) {
        return "DOMNode";
    }
    if (node->modern_dom) {
        switch (node->type) {
            case PTN_XML_NODE_DOCUMENT:
                return node->html_document ? "Dom\\HTMLDocument" : "Dom\\XMLDocument";
            case PTN_XML_NODE_DOCUMENT_FRAGMENT:
                return "Dom\\DocumentFragment";
            case PTN_XML_NODE_DOCUMENT_TYPE:
                return "Dom\\DocumentType";
            case PTN_XML_NODE_ELEMENT:
                return "Dom\\Element";
            case PTN_XML_NODE_ATTRIBUTE:
                return "Dom\\Attr";
            case PTN_XML_NODE_ENTITY:
                return "Dom\\Entity";
            case PTN_XML_NODE_NOTATION:
                return "Dom\\Notation";
            case PTN_XML_NODE_ENTITY_REFERENCE:
                return "Dom\\EntityReference";
            case PTN_XML_NODE_PROCESSING_INSTRUCTION:
                return "Dom\\ProcessingInstruction";
            case PTN_XML_NODE_TEXT:
                return "Dom\\Text";
            case PTN_XML_NODE_CDATA:
                return "Dom\\CdataSection";
            case PTN_XML_NODE_COMMENT:
                return "Dom\\Comment";
            default:
                return "Dom\\Node";
        }
    }
    switch (node->type) {
        case PTN_XML_NODE_DOCUMENT:
            return "DOMDocument";
        case PTN_XML_NODE_DOCUMENT_FRAGMENT:
            return "DOMDocumentFragment";
        case PTN_XML_NODE_DOCUMENT_TYPE:
            return "DOMDocumentType";
        case PTN_XML_NODE_ELEMENT:
            return "DOMElement";
        case PTN_XML_NODE_ATTRIBUTE:
            if (node->namespace_declaration) {
                return "DOMNameSpaceNode";
            }
            return "DOMAttr";
        case PTN_XML_NODE_ENTITY:
            return "DOMEntity";
        case PTN_XML_NODE_NOTATION:
            return "DOMNotation";
        case PTN_XML_NODE_ENTITY_REFERENCE:
            return "DOMEntityReference";
        case PTN_XML_NODE_PROCESSING_INSTRUCTION:
            return "DOMProcessingInstruction";
        case PTN_XML_NODE_TEXT:
            return "DOMText";
        case PTN_XML_NODE_CDATA:
            return "DOMCdataSection";
        case PTN_XML_NODE_COMMENT:
            return "DOMComment";
        default:
            return "DOMNode";
    }
}

static void ptn_xml_node_native_data_free(void *data) {
    PtnXmlNode *node = (PtnXmlNode *)data;
    if (node != NULL) {
        node->object = NULL;
    }
}

static char *ptn_xml_node_default_name(int type) {
    switch (type) {
        case PTN_XML_NODE_DOCUMENT:
            return ptn_duplicate_string("#document");
        case PTN_XML_NODE_DOCUMENT_FRAGMENT:
            return ptn_duplicate_string("#document-fragment");
        case PTN_XML_NODE_TEXT:
            return ptn_duplicate_string("#text");
        case PTN_XML_NODE_CDATA:
            return ptn_duplicate_string("#cdata-section");
        case PTN_XML_NODE_COMMENT:
            return ptn_duplicate_string("#comment");
        default:
            return ptn_duplicate_string("");
    }
}

static PtnXmlNode *ptn_xml_node_alloc(int type, const char *name, const char *value) {
    PtnXmlNode *node = calloc(1, sizeof(PtnXmlNode));
    if (node == NULL) {
        ptn_abort_out_of_memory();
    }
    node->boundary = ptn_libxml_boundary_for_surface(PTN_LIBXML_SURFACE_DOM_TREE);
    node->type = type;
    node->name = name == NULL ? ptn_xml_node_default_name(type) : ptn_duplicate_string(name);
    node->value = ptn_duplicate_string(value == NULL ? "" : value);
    node->value_len = strlen(node->value == NULL ? "" : node->value);
    node->version = type == PTN_XML_NODE_DOCUMENT ? ptn_duplicate_string("1.0") : NULL;
    node->encoding = NULL;
    node->owner_document = type == PTN_XML_NODE_DOCUMENT ? node : NULL;
    return node;
}

static PtnXmlNode *ptn_xml_node_data(PtnValue value) {
    value = ptn_value_deref(value);
    if (value.type != PTN_OBJECT || value.as.object->native_data == NULL) {
        return NULL;
    }
    const char *class_name = ptn_dom_effective_class_name(value.as.object->class_name);
    if (!ptn_dom_effective_class_is_modeled(class_name)) {
        return NULL;
    }
    if (ptn_ascii_case_equal(class_name, "DOMNodeList") ||
        ptn_ascii_case_equal(class_name, "DOMNamedNodeMap") ||
        ptn_ascii_case_equal(class_name, "DOMTokenList")) {
        return NULL;
    }
    return (PtnXmlNode *)value.as.object->native_data;
}

