static PtnValue ptn_internal_socket_accept(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)line;
    PtnResource *resource = ptn_internal_expect_socket_arg(runtime, "socket_accept", 1, "socket", args[0]);
    if (resource == NULL) {
        return ptn_null();
    }
    PtnSocketData *data = ptn_socket_data(resource);
#if defined(_WIN32)
    return ptn_socket_false_with_error(data, 0);
#else
    int fd;
    do {
        fd = accept(data->fd, NULL, NULL);
    } while (fd < 0 && errno == EINTR);
    if (fd < 0) {
        return ptn_socket_false_from_errno(data);
    }
    ptn_socket_set_last_error(data, 0);
    return ptn_resource(ptn_socket_new_resource(runtime, fd, data->domain, data->type, data->protocol));
#endif
}

static int ptn_socket_length_is_usable(int64_t length) {
    return length > 0 && length <= INT_MAX;
}

static PtnValue ptn_internal_socket_read(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnResource *resource = ptn_internal_expect_socket_arg(runtime, "socket_read", 1, "socket", args[0]);
    if (resource == NULL) {
        return ptn_null();
    }
    PtnSocketData *data = ptn_socket_data(resource);
    int64_t length = ptn_internal_expect_integer_arg(runtime, "socket_read", 2, "length", args[1], line);
    int64_t mode = argc >= 3
        ? ptn_internal_expect_integer_arg(runtime, "socket_read", 3, "mode", args[2], line)
        : 2;
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    if (!ptn_socket_length_is_usable(length)) {
        return ptn_socket_false_with_error(data, EINVAL);
    }
#if defined(_WIN32)
    (void)mode;
    return ptn_socket_false_with_error(data, 0);
#else
    char *buffer = malloc((size_t)length);
    if (buffer == NULL) {
        ptn_abort_out_of_memory();
    }
    size_t used = 0;
    if (mode == 1) {
        while (used < (size_t)length) {
            char byte = '\0';
            ssize_t received = recv(data->fd, &byte, 1, 0);
            if (received <= 0) {
                if (received < 0) {
                    free(buffer);
                    return ptn_socket_false_from_errno(data);
                }
                break;
            }
            buffer[used++] = byte;
            if (byte == '\n') {
                break;
            }
        }
    } else {
        ssize_t received;
        do {
            received = recv(data->fd, buffer, (size_t)length, 0);
        } while (received < 0 && errno == EINTR);
        if (received < 0) {
            free(buffer);
            return ptn_socket_false_from_errno(data);
        }
        used = (size_t)received;
    }
    ptn_socket_set_last_error(data, 0);
    return ptn_owned_string_len(buffer, used);
#endif
}

static PtnValue ptn_internal_socket_write(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnResource *resource = ptn_internal_expect_socket_arg(runtime, "socket_write", 1, "socket", args[0]);
    if (resource == NULL) {
        return ptn_null();
    }
    PtnSocketData *data = ptn_socket_data(resource);
    PtnStringOperand buffer = ptn_internal_expect_string_arg(runtime, "socket_write", 2, "data", args[1], line);
    int64_t length = argc >= 3
        ? ptn_internal_expect_integer_arg(runtime, "socket_write", 3, "length", args[2], line)
        : (int64_t)buffer.len;
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(buffer);
        return ptn_null();
    }
    if (length < 0) {
        ptn_string_operand_free(buffer);
        return ptn_socket_false_with_error(data, EINVAL);
    }
    size_t write_len = (size_t)length;
    if (write_len > buffer.len) {
        write_len = buffer.len;
    }
#if defined(_WIN32)
    ptn_string_operand_free(buffer);
    return ptn_socket_false_with_error(data, 0);
#else
    ssize_t sent;
    do {
        sent = send(data->fd, buffer.data, write_len, 0);
    } while (sent < 0 && errno == EINTR);
    ptn_string_operand_free(buffer);
    if (sent < 0) {
        return ptn_socket_false_from_errno(data);
    }
    ptn_socket_set_last_error(data, 0);
    return ptn_int((int64_t)sent);
#endif
}

static PtnValue ptn_internal_socket_recv(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnResource *resource = ptn_internal_expect_socket_arg(runtime, "socket_recv", 1, "socket", args[0]);
    if (resource == NULL) {
        return ptn_null();
    }
    PtnSocketData *data = ptn_socket_data(resource);
    int64_t length = ptn_internal_expect_integer_arg(runtime, "socket_recv", 3, "length", args[2], line);
    int64_t flags = ptn_internal_expect_integer_arg(runtime, "socket_recv", 4, "flags", args[3], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    if (!ptn_socket_length_is_usable(length)) {
        ptn_socket_assign_reference(runtime, args[1], ptn_string(""));
        return ptn_socket_false_with_error(data, EINVAL);
    }
#if defined(_WIN32)
    (void)flags;
    ptn_socket_assign_reference(runtime, args[1], ptn_string(""));
    return ptn_socket_false_with_error(data, 0);
#else
    char *buffer = malloc((size_t)length);
    if (buffer == NULL) {
        ptn_abort_out_of_memory();
    }
    ssize_t received;
    do {
        received = recv(data->fd, buffer, (size_t)length, (int)flags);
    } while (received < 0 && errno == EINTR);
    if (received < 0) {
        free(buffer);
        ptn_socket_assign_reference(runtime, args[1], ptn_string(""));
        return ptn_socket_false_from_errno(data);
    }
    ptn_socket_assign_reference(runtime, args[1], ptn_owned_string_len(buffer, (size_t)received));
    ptn_socket_set_last_error(data, 0);
    return ptn_int((int64_t)received);
#endif
}

static PtnValue ptn_internal_socket_sendto(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnResource *resource = ptn_internal_expect_socket_arg(runtime, "socket_sendto", 1, "socket", args[0]);
    if (resource == NULL) {
        return ptn_null();
    }
    PtnSocketData *data = ptn_socket_data(resource);
    PtnStringOperand buffer = ptn_internal_expect_string_arg(runtime, "socket_sendto", 2, "data", args[1], line);
    int64_t length = ptn_internal_expect_integer_arg(runtime, "socket_sendto", 3, "length", args[2], line);
    int64_t flags = ptn_internal_expect_integer_arg(runtime, "socket_sendto", 4, "flags", args[3], line);
    PtnStringOperand address = ptn_internal_expect_string_arg(runtime, "socket_sendto", 5, "address", args[4], line);
    int64_t port = argc >= 6
        ? ptn_internal_expect_integer_arg(runtime, "socket_sendto", 6, "port", args[5], line)
        : 0;
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(buffer);
        ptn_string_operand_free(address);
        return ptn_null();
    }
    if (length < 0) {
        ptn_string_operand_free(buffer);
        ptn_string_operand_free(address);
        return ptn_socket_false_with_error(data, EINVAL);
    }
    size_t send_len = (size_t)length;
    if (send_len > buffer.len) {
        send_len = buffer.len;
    }
#if defined(_WIN32)
    ptn_string_operand_free(buffer);
    ptn_string_operand_free(address);
    return ptn_socket_false_with_error(data, 0);
#else
    struct sockaddr_storage storage;
    struct sockaddr *sockaddr_ptr = (struct sockaddr *)&storage;
    socklen_t sockaddr_len = 0;
    if (data->domain == AF_UNIX) {
        struct sockaddr_un *unix_addr = (struct sockaddr_un *)&storage;
        if (!ptn_socket_make_unix_addr(runtime, "socket_sendto", address, unix_addr, &sockaddr_len, line)) {
            ptn_string_operand_free(buffer);
            ptn_string_operand_free(address);
            return ptn_socket_false_with_error(data, EINVAL);
        }
    } else if (data->domain == AF_INET) {
        struct sockaddr_in *inet_addr = (struct sockaddr_in *)&storage;
        if (!ptn_socket_make_inet_addr(address, port, inet_addr)) {
            ptn_string_operand_free(buffer);
            ptn_string_operand_free(address);
            return ptn_socket_false_with_error(data, EINVAL);
        }
        sockaddr_len = sizeof(*inet_addr);
    } else {
        ptn_string_operand_free(buffer);
        ptn_string_operand_free(address);
        return ptn_socket_false_with_error(data, EAFNOSUPPORT);
    }
    ssize_t sent;
    do {
        sent = sendto(data->fd, buffer.data, send_len, (int)flags, sockaddr_ptr, sockaddr_len);
    } while (sent < 0 && errno == EINTR);
    ptn_string_operand_free(buffer);
    ptn_string_operand_free(address);
    if (sent < 0) {
        return ptn_socket_false_from_errno(data);
    }
    ptn_socket_set_last_error(data, 0);
    return ptn_int((int64_t)sent);
#endif
}

static PtnValue ptn_internal_socket_recvfrom(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnResource *resource = ptn_internal_expect_socket_arg(runtime, "socket_recvfrom", 1, "socket", args[0]);
    if (resource == NULL) {
        return ptn_null();
    }
    PtnSocketData *data = ptn_socket_data(resource);
    int64_t length = ptn_internal_expect_integer_arg(runtime, "socket_recvfrom", 3, "length", args[2], line);
    int64_t flags = ptn_internal_expect_integer_arg(runtime, "socket_recvfrom", 4, "flags", args[3], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    if (!ptn_socket_length_is_usable(length)) {
        ptn_socket_assign_reference(runtime, args[1], ptn_string(""));
        ptn_socket_assign_reference(runtime, args[4], ptn_string(""));
        if (argc >= 6) {
            ptn_socket_assign_reference(runtime, args[5], ptn_int(0));
        }
        return ptn_socket_false_with_error(data, EINVAL);
    }
#if defined(_WIN32)
    (void)flags;
    ptn_socket_assign_reference(runtime, args[1], ptn_string(""));
    ptn_socket_assign_reference(runtime, args[4], ptn_string(""));
    if (argc >= 6) {
        ptn_socket_assign_reference(runtime, args[5], ptn_int(0));
    }
    return ptn_socket_false_with_error(data, 0);
#else
    char *buffer = malloc((size_t)length);
    if (buffer == NULL) {
        ptn_abort_out_of_memory();
    }
    struct sockaddr_storage from;
    socklen_t from_len = sizeof(from);
    ssize_t received;
    do {
        received = recvfrom(data->fd, buffer, (size_t)length, (int)flags, (struct sockaddr *)&from, &from_len);
    } while (received < 0 && errno == EINTR);
    if (received < 0) {
        free(buffer);
        ptn_socket_assign_reference(runtime, args[1], ptn_string(""));
        ptn_socket_assign_reference(runtime, args[4], ptn_string(""));
        if (argc >= 6) {
            ptn_socket_assign_reference(runtime, args[5], ptn_int(0));
        }
        return ptn_socket_false_from_errno(data);
    }
    ptn_socket_assign_reference(runtime, args[1], ptn_owned_string_len(buffer, (size_t)received));
    if (from.ss_family == AF_UNIX) {
        char *path = ptn_socket_sockaddr_un_path((struct sockaddr_un *)&from, from_len);
        ptn_socket_assign_reference(runtime, args[4], ptn_owned_string(path));
        if (argc >= 6) {
            ptn_socket_assign_reference(runtime, args[5], ptn_int(0));
        }
    } else if (from.ss_family == AF_INET) {
        char addr_buffer[INET_ADDRSTRLEN];
        struct sockaddr_in *inet_addr = (struct sockaddr_in *)&from;
        const char *formatted = inet_ntop(AF_INET, &inet_addr->sin_addr, addr_buffer, sizeof(addr_buffer));
        ptn_socket_assign_reference(runtime, args[4], formatted == NULL ? ptn_string("") : ptn_string(formatted));
        if (argc >= 6) {
            ptn_socket_assign_reference(runtime, args[5], ptn_int((int64_t)ntohs(inet_addr->sin_port)));
        }
    } else {
        ptn_socket_assign_reference(runtime, args[4], ptn_string(""));
        if (argc >= 6) {
            ptn_socket_assign_reference(runtime, args[5], ptn_int(0));
        }
    }
    ptn_socket_set_last_error(data, 0);
    return ptn_int((int64_t)received);
#endif
}

static int ptn_socket_set_blocking(PtnSocketData *data, int enabled) {
#if defined(_WIN32)
    (void)data;
    (void)enabled;
    return 0;
#else
    int flags = fcntl(data->fd, F_GETFL, 0);
    if (flags < 0) {
        return 0;
    }
    if (enabled) {
        flags &= ~O_NONBLOCK;
    } else {
        flags |= O_NONBLOCK;
    }
    return fcntl(data->fd, F_SETFL, flags) == 0;
#endif
}

static PtnValue ptn_internal_socket_set_nonblock(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)line;
    PtnResource *resource = ptn_internal_expect_socket_arg(runtime, "socket_set_nonblock", 1, "socket", args[0]);
    if (resource == NULL) {
        return ptn_null();
    }
    PtnSocketData *data = ptn_socket_data(resource);
    if (!ptn_socket_set_blocking(data, 0)) {
        return ptn_socket_false_from_errno(data);
    }
    ptn_socket_set_last_error(data, 0);
    return ptn_bool(1);
}

static PtnValue ptn_internal_socket_set_block(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)line;
    PtnResource *resource = ptn_internal_expect_socket_arg(runtime, "socket_set_block", 1, "socket", args[0]);
    if (resource == NULL) {
        return ptn_null();
    }
    PtnSocketData *data = ptn_socket_data(resource);
    if (!ptn_socket_set_blocking(data, 1)) {
        return ptn_socket_false_from_errno(data);
    }
    ptn_socket_set_last_error(data, 0);
    return ptn_bool(1);
}

static void ptn_socket_linger_missing_key(PtnRuntime *runtime, const char *key_name) {
    char message[128];
    int written = snprintf(
        message,
        sizeof(message),
        "socket_set_option(): Argument #4 ($value) must have key \"%s\"",
        key_name
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "ValueError", message);
}

static int ptn_socket_array_integer_value(PtnArray *array, const char *key_name, int *out) {
    PtnArrayKey key = ptn_array_string_key(key_name);
    PtnArrayEntry *entry = ptn_array_entry_for_key(array, key);
    ptn_array_key_free(key);
    if (entry == NULL) {
        return 0;
    }
    *out = (int)ptn_value_to_integer(entry->value);
    return 1;
}

static PtnValue ptn_internal_socket_set_option(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnResource *resource = ptn_internal_expect_socket_arg(runtime, "socket_set_option", 1, "socket", args[0]);
    if (resource == NULL) {
        return ptn_null();
    }
    PtnSocketData *data = ptn_socket_data(resource);
    int64_t level = ptn_internal_expect_integer_arg(runtime, "socket_set_option", 2, "level", args[1], line);
    int64_t option = ptn_internal_expect_integer_arg(runtime, "socket_set_option", 3, "option", args[2], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
#if defined(_WIN32)
    (void)level;
    (void)option;
    return ptn_socket_false_with_error(data, 0);
#else
    int result = -1;
    if (level == SOL_SOCKET && option == SO_LINGER) {
        PtnValue option_value = ptn_value_deref(args[3]);
        if (option_value.type != PTN_ARRAY) {
            ptn_socket_linger_missing_key(runtime, "l_onoff");
            return ptn_null();
        }
        struct linger linger_value;
        if (!ptn_socket_array_integer_value(option_value.as.array, "l_onoff", &linger_value.l_onoff)) {
            ptn_socket_linger_missing_key(runtime, "l_onoff");
            return ptn_null();
        }
        if (!ptn_socket_array_integer_value(option_value.as.array, "l_linger", &linger_value.l_linger)) {
            ptn_socket_linger_missing_key(runtime, "l_linger");
            return ptn_null();
        }
        result = setsockopt(data->fd, (int)level, (int)option, &linger_value, sizeof(linger_value));
    } else {
        int value = (int)ptn_value_to_integer(args[3]);
        result = setsockopt(data->fd, (int)level, (int)option, &value, sizeof(value));
    }
    if (result != 0) {
        int error_code = errno;
        char message[256];
        int written = snprintf(
            message,
            sizeof(message),
            "socket_set_option(): Unable to set socket option [%d]: %s",
            error_code,
            strerror(error_code)
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_emit_warning(&runtime->diagnostics, message, line);
        return ptn_socket_false_with_error(data, error_code);
    }
    ptn_socket_set_last_error(data, 0);
    return ptn_bool(1);
#endif
}

static PtnValue ptn_internal_socket_get_option(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    (void)line;
    PtnResource *resource = ptn_internal_expect_socket_arg(runtime, "socket_get_option", 1, "socket", args[0]);
    if (resource == NULL) {
        return ptn_null();
    }
    PtnSocketData *data = ptn_socket_data(resource);
    int64_t level = ptn_internal_expect_integer_arg(runtime, "socket_get_option", 2, "level", args[1], line);
    int64_t option = ptn_internal_expect_integer_arg(runtime, "socket_get_option", 3, "option", args[2], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
#if defined(_WIN32)
    (void)level;
    (void)option;
    return ptn_socket_false_with_error(data, 0);
#else
    if (level == SOL_SOCKET && option == SO_LINGER) {
        struct linger linger_value;
        socklen_t len = sizeof(linger_value);
        if (getsockopt(data->fd, (int)level, (int)option, &linger_value, &len) != 0) {
            return ptn_socket_false_from_errno(data);
        }
        PtnValue result = ptn_array_from_literal_entries(0, NULL);
        ptn_array_set_entry(result.as.array, ptn_array_string_key("l_onoff"), ptn_int(linger_value.l_onoff));
        ptn_array_set_entry(result.as.array, ptn_array_string_key("l_linger"), ptn_int(linger_value.l_linger));
        ptn_socket_set_last_error(data, 0);
        return result;
    }
    int value = 0;
    socklen_t len = sizeof(value);
    if (getsockopt(data->fd, (int)level, (int)option, &value, &len) != 0) {
        return ptn_socket_false_from_errno(data);
    }
    ptn_socket_set_last_error(data, 0);
    return ptn_int(value);
#endif
}

static PtnValue ptn_internal_socket_last_error(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)line;
    if (argc == 0 || ptn_value_deref(args[0]).type == PTN_NULL) {
        (void)runtime;
        return ptn_int(ptn_socket_last_error_global);
    }
    PtnResource *resource = ptn_internal_expect_socket_arg(runtime, "socket_last_error", 1, "socket", args[0]);
    if (resource == NULL) {
        return ptn_null();
    }
    PtnSocketData *data = ptn_socket_data(resource);
    return ptn_int(data == NULL ? ptn_socket_last_error_global : data->last_error);
}

static PtnValue ptn_internal_socket_clear_error(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)line;
    if (argc == 0 || ptn_value_deref(args[0]).type == PTN_NULL) {
        (void)runtime;
        ptn_socket_last_error_global = 0;
        return ptn_null();
    }
    PtnResource *resource = ptn_internal_expect_socket_arg(runtime, "socket_clear_error", 1, "socket", args[0]);
    if (resource == NULL) {
        return ptn_null();
    }
    PtnSocketData *data = ptn_socket_data(resource);
    ptn_socket_set_last_error(data, 0);
    return ptn_null();
}

static int ptn_socket_select_arg_array(
    PtnRuntime *runtime,
    size_t position,
    const char *argument_name,
    PtnValue value,
    PtnArray **array_out,
    int *is_null_out
) {
    value = ptn_value_deref(value);
    if (value.type == PTN_NULL) {
        *array_out = NULL;
        *is_null_out = 1;
        return 1;
    }
    *is_null_out = 0;
    if (value.type != PTN_ARRAY) {
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "socket_select(): Argument #%zu ($%s) must be of type ?array, %s given",
            position,
            argument_name,
            ptn_offset_container_type_name(value)
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "TypeError", message);
        return 0;
    }
    *array_out = value.as.array;
    return 1;
}

static int ptn_socket_select_add_array(
    PtnRuntime *runtime,
    PtnArray *array,
    size_t position,
    const char *argument_name,
    fd_set *set,
    int *max_fd
) {
    if (array == NULL) {
        return 1;
    }
    for (size_t i = 0; i < array->len; i++) {
        PtnValue value = ptn_value_deref(array->entries[i].value);
        PtnSocketData *data = value.type == PTN_RESOURCE ? ptn_socket_data(value.as.resource) : NULL;
        if (data == NULL) {
            char message[192];
            int written = snprintf(
                message,
                sizeof(message),
                "socket_select(): Argument #%zu ($%s) must only have elements of type Socket, %s given",
                position,
                argument_name,
                ptn_offset_container_type_name(value)
            );
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_throw_exception(runtime, "TypeError", message);
            return 0;
        }
        if (data->fd < 0 || data->fd >= FD_SETSIZE) {
            ptn_throw_exception(runtime, "ValueError", "socket_select(): supplied Socket is not a valid select descriptor");
            return 0;
        }
        FD_SET(data->fd, set);
        if (data->fd > *max_fd) {
            *max_fd = data->fd;
        }
    }
    return 1;
}

static PtnValue ptn_socket_select_selected_array(PtnArray *array, fd_set *set) {
    PtnValue selected = ptn_array_from_literal_entries(0, NULL);
    if (array == NULL) {
        return selected;
    }
    for (size_t i = 0; i < array->len; i++) {
        PtnValue value = ptn_value_deref(array->entries[i].value);
        PtnSocketData *data = value.type == PTN_RESOURCE ? ptn_socket_data(value.as.resource) : NULL;
        if (data != NULL && data->fd >= 0 && data->fd < FD_SETSIZE && FD_ISSET(data->fd, set)) {
            ptn_array_set_entry(
                selected.as.array,
                ptn_array_key_clone(array->entries[i].key),
                ptn_value_clone_deref(array->entries[i].value)
            );
        }
    }
    return selected;
}

static PtnValue ptn_internal_socket_select(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnArray *read_array = NULL;
    PtnArray *write_array = NULL;
    PtnArray *except_array = NULL;
    int read_null = 0;
    int write_null = 0;
    int except_null = 0;
    if (!ptn_socket_select_arg_array(runtime, 1, "read", args[0], &read_array, &read_null) ||
        !ptn_socket_select_arg_array(runtime, 2, "write", args[1], &write_array, &write_null) ||
        !ptn_socket_select_arg_array(runtime, 3, "except", args[2], &except_array, &except_null)) {
        return ptn_null();
    }
    if ((read_array == NULL || read_array->len == 0) &&
        (write_array == NULL || write_array->len == 0) &&
        (except_array == NULL || except_array->len == 0)) {
        ptn_throw_exception(runtime, "ValueError", "socket_select(): At least one array argument must be passed");
        return ptn_null();
    }
    int64_t seconds = ptn_value_deref(args[3]).type == PTN_NULL
        ? -1
        : ptn_internal_expect_integer_arg(runtime, "socket_select", 4, "seconds", args[3], line);
    int64_t microseconds = argc >= 5
        ? ptn_internal_expect_integer_arg(runtime, "socket_select", 5, "microseconds", args[4], line)
        : 0;
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    if (seconds < -1 || microseconds < 0) {
        ptn_throw_exception(runtime, "ValueError", "socket_select(): timeout must be greater than or equal to 0");
        return ptn_null();
    }
#if defined(_WIN32)
    (void)read_null;
    (void)write_null;
    (void)except_null;
    return ptn_bool(0);
#else
    fd_set read_set;
    fd_set write_set;
    fd_set except_set;
    FD_ZERO(&read_set);
    FD_ZERO(&write_set);
    FD_ZERO(&except_set);
    int max_fd = -1;
    if (!ptn_socket_select_add_array(runtime, read_array, 1, "read", &read_set, &max_fd) ||
        !ptn_socket_select_add_array(runtime, write_array, 2, "write", &write_set, &max_fd) ||
        !ptn_socket_select_add_array(runtime, except_array, 3, "except", &except_set, &max_fd)) {
        return ptn_null();
    }
    struct timeval timeout;
    struct timeval *timeout_ptr = NULL;
    if (seconds >= 0) {
        timeout.tv_sec = (time_t)seconds;
        timeout.tv_usec = (suseconds_t)microseconds;
        timeout_ptr = &timeout;
    }
    int selected;
    do {
        selected = select(
            max_fd + 1,
            read_array == NULL ? NULL : &read_set,
            write_array == NULL ? NULL : &write_set,
            except_array == NULL ? NULL : &except_set,
            timeout_ptr
        );
    } while (selected < 0 && errno == EINTR);
    if (selected < 0) {
        return ptn_socket_false_from_errno(NULL);
    }
    ptn_socket_assign_reference(runtime, args[0], read_null ? ptn_null() : ptn_socket_select_selected_array(read_array, &read_set));
    ptn_socket_assign_reference(runtime, args[1], write_null ? ptn_null() : ptn_socket_select_selected_array(write_array, &write_set));
    ptn_socket_assign_reference(runtime, args[2], except_null ? ptn_null() : ptn_socket_select_selected_array(except_array, &except_set));
    ptn_socket_set_last_error(NULL, 0);
    return ptn_int(selected);
#endif
}

static PtnValue ptn_internal_socket_import_stream(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnResource *stream = ptn_internal_expect_open_stream_arg(runtime, "socket_import_stream", args[0], line);
    if (stream == NULL) {
        return ptn_null();
    }
#if defined(_WIN32)
    return ptn_bool(0);
#else
    if (stream->stream == NULL) {
        return ptn_bool(0);
    }
    int fd = fileno(stream->stream);
    if (fd < 0) {
        return ptn_bool(0);
    }
    int dup_fd = dup(fd);
    if (dup_fd < 0) {
        return ptn_socket_false_from_errno(NULL);
    }
    int domain = AF_UNIX;
    struct sockaddr_storage addr;
    socklen_t addr_len = sizeof(addr);
    if (getsockname(dup_fd, (struct sockaddr *)&addr, &addr_len) == 0) {
        domain = addr.ss_family;
    }
    int type = SOCK_STREAM;
    socklen_t type_len = sizeof(type);
    (void)getsockopt(dup_fd, SOL_SOCKET, SO_TYPE, &type, &type_len);
    return ptn_resource(ptn_socket_new_resource(runtime, dup_fd, domain, type, 0));
#endif
}

static void ptn_stream_socket_server_assign_error(
    PtnRuntime *runtime,
    size_t argc,
    const PtnValue *args,
    int error_code,
    const char *message
);

static void ptn_stream_socket_client_assign_reference(PtnRuntime *runtime, PtnValue arg, PtnValue value) {
    if (arg.type == PTN_REFERENCE) {
        (void)ptn_reference_assign(runtime, arg.as.reference, value);
    }
    ptn_value_destroy(&value);
}

static int ptn_stream_socket_address_is_unix_like(
    PtnStringOperand address,
    const char **prefix_out,
    int *socktype_out
) {
    const char *prefix = "unix://";
    size_t prefix_len = strlen(prefix);
    if (address.len >= prefix_len && memcmp(address.data, prefix, prefix_len) == 0) {
        *prefix_out = prefix;
        *socktype_out = SOCK_STREAM;
        return 1;
    }
    prefix = "udg://";
    prefix_len = strlen(prefix);
    if (address.len >= prefix_len && memcmp(address.data, prefix, prefix_len) == 0) {
        *prefix_out = prefix;
        *socktype_out = SOCK_DGRAM;
        return 1;
    }
    return 0;
}

static int ptn_stream_socket_address_parse_tcp(
    PtnStringOperand address,
    char **host_out,
    char **service_out
) {
    const char *prefix = "tcp://";
    size_t prefix_len = strlen(prefix);
    *host_out = NULL;
    *service_out = NULL;
    if (address.len <= prefix_len || memcmp(address.data, prefix, prefix_len) != 0) {
        return 0;
    }

    const char *body = address.data + prefix_len;
    size_t body_len = address.len - prefix_len;
    const char *host = body;
    size_t host_len = 0;
    const char *service = NULL;
    size_t service_len = 0;

    if (body_len >= 4 && body[0] == '[') {
        const char *end = memchr(body, ']', body_len);
        if (end == NULL || end + 1 >= body + body_len || end[1] != ':') {
            return 0;
        }
        host = body + 1;
        host_len = (size_t)(end - host);
        service = end + 2;
        service_len = (size_t)((body + body_len) - service);
    } else {
        const char *colon = NULL;
        for (size_t i = 0; i < body_len; i++) {
            if (body[i] == ':') {
                colon = body + i;
            }
        }
        if (colon == NULL) {
            return 0;
        }
        host_len = (size_t)(colon - body);
        service = colon + 1;
        service_len = (size_t)((body + body_len) - service);
    }

    if (host_len == 0 || service_len == 0) {
        return 0;
    }
    *host_out = ptn_duplicate_string_len(host, host_len);
    *service_out = ptn_duplicate_string_len(service, service_len);
    return 1;
}

static PtnValue ptn_stream_socket_client_open_tcp(
    PtnRuntime *runtime,
    const char *function_name,
    PtnStringOperand address,
    PtnValue error_code_arg,
    PtnValue error_message_arg,
    size_t line
) {
#if defined(_WIN32)
    (void)address;
    (void)function_name;
    ptn_emit_warning(&runtime->diagnostics, "stream_socket_client(): TCP sockets are not supported on this platform", line);
    ptn_stream_socket_client_assign_reference(runtime, error_code_arg, ptn_int(0));
    ptn_stream_socket_client_assign_reference(runtime, error_message_arg, ptn_string("not supported on this platform"));
    return ptn_bool(0);
#else
    char *host = NULL;
    char *service = NULL;
    if (!ptn_stream_socket_address_parse_tcp(address, &host, &service)) {
        char *address_c = ptn_duplicate_string_len(address.data, address.len);
        int message_needed = snprintf(NULL, 0, "Failed to parse address \"%s\"", address_c);
        if (message_needed < 0) {
            free(address_c);
            ptn_abort_out_of_memory();
        }
        char *parse_message = malloc((size_t)message_needed + 1);
        if (parse_message == NULL) {
            free(address_c);
            ptn_abort_out_of_memory();
        }
        int message_written = snprintf(parse_message, (size_t)message_needed + 1, "Failed to parse address \"%s\"", address_c);
        if (message_written < 0 || message_written != message_needed) {
            free(parse_message);
            free(address_c);
            ptn_abort_out_of_memory();
        }
        char warning[256];
        int warning_written = snprintf(
            warning,
            sizeof(warning),
            "%s(): Unable to connect to %s (%s)",
            function_name,
            address_c,
            parse_message
        );
        if (warning_written < 0 || (size_t)warning_written >= sizeof(warning)) {
            free(parse_message);
            free(address_c);
            ptn_abort_out_of_memory();
        }
        ptn_emit_warning(&runtime->diagnostics, warning, line);
        ptn_stream_socket_client_assign_reference(runtime, error_code_arg, ptn_int(0));
        ptn_stream_socket_client_assign_reference(runtime, error_message_arg, ptn_owned_string(parse_message));
        free(address_c);
        return ptn_bool(0);
    }

    struct addrinfo hints;
    memset(&hints, 0, sizeof(hints));
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_family = AF_UNSPEC;
    struct addrinfo *addresses = NULL;
    int gai = getaddrinfo(host, service, &hints, &addresses);
    if (gai != 0) {
        char warning[256];
        int warning_written = snprintf(
            warning,
            sizeof(warning),
            "%s(): Unable to connect to %.*s (%s)",
            function_name,
            (int)address.len,
            address.data,
            gai_strerror(gai)
        );
        if (warning_written < 0 || (size_t)warning_written >= sizeof(warning)) {
            free(host);
            free(service);
            ptn_abort_out_of_memory();
        }
        ptn_emit_warning(&runtime->diagnostics, warning, line);
        ptn_stream_socket_client_assign_reference(runtime, error_code_arg, ptn_int(gai));
        ptn_stream_socket_client_assign_reference(runtime, error_message_arg, ptn_owned_string(ptn_duplicate_string(gai_strerror(gai))));
        free(host);
        free(service);
        return ptn_bool(0);
    }

    int descriptor = -1;
    int error_code = 0;
    for (struct addrinfo *candidate = addresses; candidate != NULL; candidate = candidate->ai_next) {
        descriptor = socket(candidate->ai_family, candidate->ai_socktype, candidate->ai_protocol);
        if (descriptor < 0) {
            error_code = errno;
            continue;
        }
        if (connect(descriptor, candidate->ai_addr, candidate->ai_addrlen) == 0) {
            error_code = 0;
            break;
        }
        error_code = errno;
        close(descriptor);
        descriptor = -1;
    }
    freeaddrinfo(addresses);
    if (descriptor < 0) {
        char warning[256];
        const char *message = error_code == 0 ? "connection failed" : strerror(error_code);
        int warning_written = snprintf(
            warning,
            sizeof(warning),
            "%s(): Unable to connect to %.*s (%s)",
            function_name,
            (int)address.len,
            address.data,
            message
        );
        if (warning_written < 0 || (size_t)warning_written >= sizeof(warning)) {
            free(host);
            free(service);
            ptn_abort_out_of_memory();
        }
        ptn_emit_warning(&runtime->diagnostics, warning, line);
        ptn_stream_socket_client_assign_reference(runtime, error_code_arg, ptn_int(error_code));
        ptn_stream_socket_client_assign_reference(runtime, error_message_arg, ptn_owned_string(ptn_duplicate_string(message)));
        free(host);
        free(service);
        return ptn_bool(0);
    }

    FILE *stream = fdopen(descriptor, "r+");
    if (stream == NULL) {
        int saved_errno = errno;
        close(descriptor);
        ptn_emit_warning(&runtime->diagnostics, "stream_socket_client(): unable to open socket stream", line);
        ptn_stream_socket_client_assign_reference(runtime, error_code_arg, ptn_int(saved_errno));
        ptn_stream_socket_client_assign_reference(runtime, error_message_arg, ptn_owned_string(ptn_duplicate_string(strerror(saved_errno))));
        free(host);
        free(service);
        return ptn_bool(0);
    }

    char *uri = ptn_duplicate_string_len(address.data, address.len);
    PtnValue result = ptn_resource(ptn_resource_new_stream(stream, uri, "r+"));
    free(uri);
    ptn_stream_socket_client_assign_reference(runtime, error_code_arg, ptn_int(0));
    ptn_stream_socket_client_assign_reference(runtime, error_message_arg, ptn_string(""));
    free(host);
    free(service);
    return result;
#endif
}

static PtnValue ptn_stream_socket_server_open_tcp(
    PtnRuntime *runtime,
    PtnStringOperand address,
    size_t argc,
    const PtnValue *args,
    size_t line
) {
#if defined(_WIN32)
    (void)address;
    ptn_emit_warning(&runtime->diagnostics, "stream_socket_server(): TCP sockets are not supported on this platform", line);
    ptn_stream_socket_server_assign_error(runtime, argc, args, 0, "not supported on this platform");
    return ptn_bool(0);
#else
    char *host = NULL;
    char *service = NULL;
    if (!ptn_stream_socket_address_parse_tcp(address, &host, &service)) {
        ptn_emit_warning(&runtime->diagnostics, "stream_socket_server(): failed to parse tcp socket address", line);
        ptn_stream_socket_server_assign_error(runtime, argc, args, 0, "failed to parse address");
        return ptn_bool(0);
    }

    struct addrinfo hints;
    memset(&hints, 0, sizeof(hints));
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_family = AF_UNSPEC;
    hints.ai_flags = AI_PASSIVE;
    struct addrinfo *addresses = NULL;
    int gai = getaddrinfo(host, service, &hints, &addresses);
    if (gai != 0) {
        ptn_emit_warning(&runtime->diagnostics, "stream_socket_server(): unable to resolve tcp socket address", line);
        ptn_stream_socket_server_assign_error(runtime, argc, args, gai, gai_strerror(gai));
        free(host);
        free(service);
        return ptn_bool(0);
    }

    int descriptor = -1;
    int error_code = 0;
    for (struct addrinfo *candidate = addresses; candidate != NULL; candidate = candidate->ai_next) {
        descriptor = socket(candidate->ai_family, candidate->ai_socktype, candidate->ai_protocol);
        if (descriptor < 0) {
            error_code = errno;
            continue;
        }
        int reuse = 1;
        (void)setsockopt(descriptor, SOL_SOCKET, SO_REUSEADDR, &reuse, sizeof(reuse));
        if (bind(descriptor, candidate->ai_addr, candidate->ai_addrlen) == 0 &&
            listen(descriptor, 32) == 0) {
            error_code = 0;
            break;
        }
        error_code = errno;
        close(descriptor);
        descriptor = -1;
    }
    freeaddrinfo(addresses);
    if (descriptor < 0) {
        char detail[192];
        const char *message = error_code == 0 ? "bind failed" : strerror(error_code);
        int written = snprintf(detail, sizeof(detail), "stream_socket_server(): unable to bind tcp socket: %s", message);
        if (written < 0 || (size_t)written >= sizeof(detail)) {
            free(host);
            free(service);
            ptn_abort_out_of_memory();
        }
        ptn_emit_warning(&runtime->diagnostics, detail, line);
        ptn_stream_socket_server_assign_error(runtime, argc, args, error_code, message);
        free(host);
        free(service);
        return ptn_bool(0);
    }

    FILE *stream = fdopen(descriptor, "r+");
    if (stream == NULL) {
        int saved_errno = errno;
        close(descriptor);
        ptn_emit_warning(&runtime->diagnostics, "stream_socket_server(): unable to open socket stream", line);
        ptn_stream_socket_server_assign_error(runtime, argc, args, saved_errno, strerror(saved_errno));
        free(host);
        free(service);
        return ptn_bool(0);
    }
    char *uri = ptn_duplicate_string_len(address.data, address.len);
    PtnValue result = ptn_resource(ptn_resource_new_stream(stream, uri, "r+"));
    free(uri);
    ptn_stream_socket_server_assign_error(runtime, argc, args, 0, "");
    free(host);
    free(service);
    return result;
#endif
}

static PtnPersistentSocketEntry *ptn_persistent_socket_find(const char *key) {
    for (size_t i = 0; i < ptn_persistent_socket_count; i++) {
        if (strcmp(ptn_persistent_sockets[i].key, key) == 0) {
            return &ptn_persistent_sockets[i];
        }
    }
    return NULL;
}

static void ptn_persistent_socket_store(const char *key, PtnResource *resource) {
    PtnPersistentSocketEntry *entry = ptn_persistent_socket_find(key);
    if (entry != NULL) {
        entry->resource = resource;
        return;
    }
    if (ptn_persistent_socket_count == ptn_persistent_socket_capacity) {
        size_t new_capacity = ptn_persistent_socket_capacity == 0 ? 8 : ptn_persistent_socket_capacity * 2;
        if (new_capacity < ptn_persistent_socket_capacity ||
            new_capacity > SIZE_MAX / sizeof(PtnPersistentSocketEntry)) {
            ptn_abort_out_of_memory();
        }
        PtnPersistentSocketEntry *new_entries = realloc(
            ptn_persistent_sockets,
            new_capacity * sizeof(PtnPersistentSocketEntry)
        );
        if (new_entries == NULL) {
            ptn_abort_out_of_memory();
        }
        ptn_persistent_sockets = new_entries;
        ptn_persistent_socket_capacity = new_capacity;
    }
    ptn_persistent_sockets[ptn_persistent_socket_count].key = ptn_duplicate_string(key);
    ptn_persistent_sockets[ptn_persistent_socket_count].resource = resource;
    ptn_persistent_socket_count++;
}

static PtnValue ptn_internal_pfsockopen(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand hostname = ptn_internal_expect_string_arg(runtime, "pfsockopen", 1, "hostname", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    int64_t port = argc >= 2 && ptn_value_deref(args[1]).type != PTN_NULL
        ? ptn_internal_expect_integer_arg(runtime, "pfsockopen", 2, "port", args[1], line)
        : -1;
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(hostname);
        return ptn_null();
    }
    const char *udp_prefix = "udp://";
    size_t udp_prefix_len = strlen(udp_prefix);
    if (hostname.len < udp_prefix_len ||
        memcmp(hostname.data, udp_prefix, udp_prefix_len) != 0 ||
        port < 0 ||
        port > 65535) {
        ptn_stream_socket_client_assign_reference(runtime, argc >= 3 ? args[2] : ptn_null(), ptn_int(0));
        ptn_stream_socket_client_assign_reference(runtime, argc >= 4 ? args[3] : ptn_null(), ptn_string("unsupported persistent socket address"));
        ptn_string_operand_free(hostname);
        return ptn_bool(0);
    }

    char *host = ptn_duplicate_string_len(hostname.data + udp_prefix_len, hostname.len - udp_prefix_len);
    char service[16];
    int service_written = snprintf(service, sizeof(service), "%lld", (long long)port);
    if (service_written < 0 || (size_t)service_written >= sizeof(service)) {
        free(host);
        ptn_string_operand_free(hostname);
        ptn_abort_out_of_memory();
    }
    int key_len = snprintf(NULL, 0, "udp://%s:%s", host, service);
    if (key_len < 0) {
        free(host);
        ptn_string_operand_free(hostname);
        ptn_abort_out_of_memory();
    }
    char *key = malloc((size_t)key_len + 1);
    if (key == NULL) {
        free(host);
        ptn_string_operand_free(hostname);
        ptn_abort_out_of_memory();
    }
    int key_written = snprintf(key, (size_t)key_len + 1, "udp://%s:%s", host, service);
    if (key_written < 0 || key_written != key_len) {
        free(key);
        free(host);
        ptn_string_operand_free(hostname);
        ptn_abort_out_of_memory();
    }

    PtnPersistentSocketEntry *existing = ptn_persistent_socket_find(key);
    if (existing != NULL && ptn_stream_resource_is_open(existing->resource)) {
        ptn_stream_socket_client_assign_reference(runtime, argc >= 3 ? args[2] : ptn_null(), ptn_int(0));
        ptn_stream_socket_client_assign_reference(runtime, argc >= 4 ? args[3] : ptn_null(), ptn_string(""));
        free(key);
        free(host);
        ptn_string_operand_free(hostname);
        return ptn_resource(existing->resource);
    }

#if defined(_WIN32)
    ptn_stream_socket_client_assign_reference(runtime, argc >= 3 ? args[2] : ptn_null(), ptn_int(0));
    ptn_stream_socket_client_assign_reference(runtime, argc >= 4 ? args[3] : ptn_null(), ptn_string("pfsockopen UDP is not supported on this platform"));
    free(key);
    free(host);
    ptn_string_operand_free(hostname);
    return ptn_bool(0);
#else
    struct addrinfo hints;
    memset(&hints, 0, sizeof(hints));
    hints.ai_socktype = SOCK_DGRAM;
    hints.ai_family = AF_UNSPEC;
    struct addrinfo *addresses = NULL;
    int gai = getaddrinfo(host, service, &hints, &addresses);
    if (gai != 0) {
        ptn_stream_socket_client_assign_reference(runtime, argc >= 3 ? args[2] : ptn_null(), ptn_int(gai));
        ptn_stream_socket_client_assign_reference(runtime, argc >= 4 ? args[3] : ptn_null(), ptn_owned_string(ptn_duplicate_string(gai_strerror(gai))));
        free(key);
        free(host);
        ptn_string_operand_free(hostname);
        return ptn_bool(0);
    }
    int descriptor = -1;
    for (struct addrinfo *candidate = addresses; candidate != NULL; candidate = candidate->ai_next) {
        descriptor = socket(candidate->ai_family, candidate->ai_socktype, candidate->ai_protocol);
        if (descriptor < 0) {
            continue;
        }
        if (connect(descriptor, candidate->ai_addr, candidate->ai_addrlen) == 0) {
            break;
        }
        close(descriptor);
        descriptor = -1;
    }
    freeaddrinfo(addresses);
    if (descriptor < 0) {
        int error_code = errno;
        ptn_stream_socket_client_assign_reference(runtime, argc >= 3 ? args[2] : ptn_null(), ptn_int(error_code));
        ptn_stream_socket_client_assign_reference(runtime, argc >= 4 ? args[3] : ptn_null(), ptn_owned_string(ptn_duplicate_string(strerror(error_code))));
        free(key);
        free(host);
        ptn_string_operand_free(hostname);
        return ptn_bool(0);
    }
    FILE *stream = fdopen(descriptor, "r+");
    if (stream == NULL) {
        int error_code = errno;
        close(descriptor);
        ptn_stream_socket_client_assign_reference(runtime, argc >= 3 ? args[2] : ptn_null(), ptn_int(error_code));
        ptn_stream_socket_client_assign_reference(runtime, argc >= 4 ? args[3] : ptn_null(), ptn_owned_string(ptn_duplicate_string(strerror(error_code))));
        free(key);
        free(host);
        ptn_string_operand_free(hostname);
        return ptn_bool(0);
    }
    PtnResource *resource = ptn_resource_new_stream(stream, key, "r+");
    resource->persistent = 1;
    ptn_persistent_socket_store(key, resource);
    ptn_stream_socket_client_assign_reference(runtime, argc >= 3 ? args[2] : ptn_null(), ptn_int(0));
    ptn_stream_socket_client_assign_reference(runtime, argc >= 4 ? args[3] : ptn_null(), ptn_string(""));
    free(key);
    free(host);
    ptn_string_operand_free(hostname);
    return ptn_resource(resource);
#endif
}

static char *ptn_fsockopen_tcp_address(PtnStringOperand hostname, int64_t port) {
    const char *prefix = "tcp://";
    size_t prefix_len = strlen(prefix);
    int has_tcp_prefix = hostname.len >= prefix_len && memcmp(hostname.data, prefix, prefix_len) == 0;
    if (has_tcp_prefix) {
        PtnStringOperand borrowed = hostname;
        char *parsed_host = NULL;
        char *parsed_service = NULL;
        if (ptn_stream_socket_address_parse_tcp(borrowed, &parsed_host, &parsed_service)) {
            free(parsed_host);
            free(parsed_service);
            return ptn_duplicate_string_len(hostname.data, hostname.len);
        }
        if (port < 0 || port > 65535) {
            return NULL;
        }
        int needed = snprintf(NULL, 0, "%.*s:%lld", (int)hostname.len, hostname.data, (long long)port);
        if (needed < 0) {
            ptn_abort_out_of_memory();
        }
        char *address = malloc((size_t)needed + 1);
        if (address == NULL) {
            ptn_abort_out_of_memory();
        }
        int written = snprintf(address, (size_t)needed + 1, "%.*s:%lld", (int)hostname.len, hostname.data, (long long)port);
        if (written < 0 || written != needed) {
            free(address);
            ptn_abort_out_of_memory();
        }
        return address;
    }

    if (port < 0 || port > 65535) {
        return NULL;
    }
    int needed = snprintf(NULL, 0, "tcp://%.*s:%lld", (int)hostname.len, hostname.data, (long long)port);
    if (needed < 0) {
        ptn_abort_out_of_memory();
    }
    char *address = malloc((size_t)needed + 1);
    if (address == NULL) {
        ptn_abort_out_of_memory();
    }
    int written = snprintf(address, (size_t)needed + 1, "tcp://%.*s:%lld", (int)hostname.len, hostname.data, (long long)port);
    if (written < 0 || written != needed) {
        free(address);
        ptn_abort_out_of_memory();
    }
    return address;
}

static PtnValue ptn_internal_fsockopen(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand hostname = ptn_internal_expect_string_arg(runtime, "fsockopen", 1, "hostname", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    int64_t port = argc >= 2 && ptn_value_deref(args[1]).type != PTN_NULL
        ? ptn_internal_expect_integer_arg(runtime, "fsockopen", 2, "port", args[1], line)
        : -1;
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(hostname);
        return ptn_null();
    }
    char *address = ptn_fsockopen_tcp_address(hostname, port);
    ptn_string_operand_free(hostname);
    if (address == NULL) {
        ptn_stream_socket_client_assign_reference(runtime, argc >= 3 ? args[2] : ptn_null(), ptn_int(0));
        ptn_stream_socket_client_assign_reference(runtime, argc >= 4 ? args[3] : ptn_null(), ptn_string("unsupported socket address"));
        return ptn_bool(0);
    }
    PtnStringOperand address_operand = {
        .data = address,
        .owned = NULL,
        .len = strlen(address),
    };
    PtnValue result = ptn_stream_socket_client_open_tcp(
        runtime,
        "fsockopen",
        address_operand,
        argc >= 3 ? args[2] : ptn_null(),
        argc >= 4 ? args[3] : ptn_null(),
        line
    );
    free(address);
    return result;
}

static int ptn_stream_socket_server_path_limit(int abstract);

static PtnValue ptn_internal_stream_socket_client(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand address = ptn_internal_expect_string_arg(runtime, "stream_socket_client", 1, "address", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    const char *tcp_prefix = "tcp://";
    size_t tcp_prefix_len = strlen(tcp_prefix);
    if (address.len >= tcp_prefix_len && memcmp(address.data, tcp_prefix, tcp_prefix_len) == 0) {
        PtnValue result = ptn_stream_socket_client_open_tcp(
            runtime,
            "stream_socket_client",
            address,
            argc >= 2 ? args[1] : ptn_null(),
            argc >= 3 ? args[2] : ptn_null(),
            line
        );
        ptn_string_operand_free(address);
        return result;
    }
#if !defined(_WIN32)
    const char *prefix = NULL;
    int socktype = 0;
    if (ptn_stream_socket_address_is_unix_like(address, &prefix, &socktype)) {
        size_t prefix_len = strlen(prefix);
        const char *socket_path = address.data + prefix_len;
        size_t socket_path_len = address.len - prefix_len;
        int abstract = socket_path_len > 0 && socket_path[0] == '\0';
        int max_len = ptn_stream_socket_server_path_limit(abstract);
        if (max_len <= 0 || socket_path_len > (size_t)max_len) {
            ptn_emit_warning(&runtime->diagnostics, "stream_socket_client(): unable to connect to unix socket", line);
            ptn_stream_socket_client_assign_reference(runtime, argc >= 2 ? args[1] : ptn_null(), ptn_int(0));
            ptn_stream_socket_client_assign_reference(runtime, argc >= 3 ? args[2] : ptn_null(), ptn_string("unix socket path is invalid"));
            ptn_string_operand_free(address);
            return ptn_bool(0);
        }

        int descriptor = socket(AF_UNIX, socktype, 0);
        if (descriptor < 0) {
            int error_code = errno;
            ptn_emit_warning(&runtime->diagnostics, "stream_socket_client(): unable to create unix socket", line);
            ptn_stream_socket_client_assign_reference(runtime, argc >= 2 ? args[1] : ptn_null(), ptn_int(error_code));
            ptn_stream_socket_client_assign_reference(runtime, argc >= 3 ? args[2] : ptn_null(), ptn_owned_string(ptn_duplicate_string(strerror(error_code))));
            ptn_string_operand_free(address);
            return ptn_bool(0);
        }

        struct sockaddr_un unix_addr;
        memset(&unix_addr, 0, sizeof(unix_addr));
        unix_addr.sun_family = AF_UNIX;
        memcpy(unix_addr.sun_path, socket_path, socket_path_len);
        socklen_t connect_len = (socklen_t)(offsetof(struct sockaddr_un, sun_path) + socket_path_len);
        if (!abstract) {
            unix_addr.sun_path[socket_path_len] = '\0';
            connect_len++;
        }
        if (connect(descriptor, (struct sockaddr *)&unix_addr, connect_len) != 0) {
            int error_code = errno;
            char detail[256];
            int written = snprintf(
                detail,
                sizeof(detail),
                "stream_socket_client(): Unable to connect to %.*s (%s)",
                (int)address.len,
                address.data,
                strerror(error_code)
            );
            if (written < 0 || (size_t)written >= sizeof(detail)) {
                close(descriptor);
                ptn_string_operand_free(address);
                ptn_abort_out_of_memory();
            }
            close(descriptor);
            ptn_emit_warning(&runtime->diagnostics, detail, line);
            ptn_stream_socket_client_assign_reference(runtime, argc >= 2 ? args[1] : ptn_null(), ptn_int(error_code));
            ptn_stream_socket_client_assign_reference(runtime, argc >= 3 ? args[2] : ptn_null(), ptn_owned_string(ptn_duplicate_string(strerror(error_code))));
            ptn_string_operand_free(address);
            return ptn_bool(0);
        }

        FILE *stream = fdopen(descriptor, "r+");
        if (stream == NULL) {
            int error_code = errno;
            close(descriptor);
            ptn_emit_warning(&runtime->diagnostics, "stream_socket_client(): unable to open socket stream", line);
            ptn_stream_socket_client_assign_reference(runtime, argc >= 2 ? args[1] : ptn_null(), ptn_int(error_code));
            ptn_stream_socket_client_assign_reference(runtime, argc >= 3 ? args[2] : ptn_null(), ptn_owned_string(ptn_duplicate_string(strerror(error_code))));
            ptn_string_operand_free(address);
            return ptn_bool(0);
        }

        char *uri = ptn_duplicate_string_len(address.data, address.len);
        PtnValue result = ptn_resource(ptn_resource_new_stream(stream, uri, "r+"));
        free(uri);
        ptn_stream_socket_client_assign_reference(runtime, argc >= 2 ? args[1] : ptn_null(), ptn_int(0));
        ptn_stream_socket_client_assign_reference(runtime, argc >= 3 ? args[2] : ptn_null(), ptn_string(""));
        ptn_string_operand_free(address);
        return result;
    }
#endif
    int message_needed = snprintf(
        NULL,
        0,
        "Failed to parse address \"%.*s\"",
        (int)address.len,
        address.data
    );
    if (message_needed < 0) {
        ptn_string_operand_free(address);
        ptn_abort_out_of_memory();
    }
    char *parse_message = malloc((size_t)message_needed + 1);
    if (parse_message == NULL) {
        ptn_string_operand_free(address);
        ptn_abort_out_of_memory();
    }
    int message_written = snprintf(
        parse_message,
        (size_t)message_needed + 1,
        "Failed to parse address \"%.*s\"",
        (int)address.len,
        address.data
    );
    if (message_written < 0 || message_written != message_needed) {
        free(parse_message);
        ptn_string_operand_free(address);
        ptn_abort_out_of_memory();
    }
    int warning_needed = snprintf(
        NULL,
        0,
        "stream_socket_client(): Unable to connect to %.*s (%s)",
        (int)address.len,
        address.data,
        parse_message
    );
    if (warning_needed < 0) {
        free(parse_message);
        ptn_string_operand_free(address);
        ptn_abort_out_of_memory();
    }
    char *warning = malloc((size_t)warning_needed + 1);
    if (warning == NULL) {
        free(parse_message);
        ptn_string_operand_free(address);
        ptn_abort_out_of_memory();
    }
    int warning_written = snprintf(
        warning,
        (size_t)warning_needed + 1,
        "stream_socket_client(): Unable to connect to %.*s (%s)",
        (int)address.len,
        address.data,
        parse_message
    );
    if (warning_written < 0 || warning_written != warning_needed) {
        free(warning);
        free(parse_message);
        ptn_string_operand_free(address);
        ptn_abort_out_of_memory();
    }
    ptn_emit_warning(&runtime->diagnostics, warning, line);
    free(warning);
    if (argc >= 2) {
        ptn_stream_socket_client_assign_reference(runtime, args[1], ptn_int(0));
    }
    if (argc >= 3) {
        ptn_stream_socket_client_assign_reference(runtime, args[2], ptn_owned_string(ptn_duplicate_string(parse_message)));
    }
    free(parse_message);
    ptn_string_operand_free(address);
    return ptn_bool(0);
}

static PtnValue ptn_internal_stream_socket_get_name(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnResource *resource = ptn_internal_expect_open_stream_arg(runtime, "stream_socket_get_name", args[0], line);
    if (resource == NULL) {
        return ptn_null();
    }
    if (argc >= 2) {
        (void)ptn_is_truthy(args[1]);
    }
    return ptn_bool(0);
}

static void ptn_stream_socket_recvfrom_assign_address(PtnRuntime *runtime, size_t argc, const PtnValue *args, PtnValue value) {
    if (argc >= 4 && args[3].type == PTN_REFERENCE) {
        (void)ptn_reference_assign(runtime, args[3].as.reference, value);
    }
    ptn_value_destroy(&value);
}

static PtnValue ptn_internal_stream_socket_recvfrom(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnResource *resource = ptn_internal_expect_open_stream_arg(runtime, "stream_socket_recvfrom", args[0], line);
    if (resource == NULL) {
        return ptn_null();
    }
    int64_t length = ptn_internal_expect_integer_arg(runtime, "stream_socket_recvfrom", 2, "length", args[1], line);
    int64_t flags = argc >= 3
        ? ptn_internal_expect_integer_arg(runtime, "stream_socket_recvfrom", 3, "flags", args[2], line)
        : 0;
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    if (length < 0) {
        ptn_throw_exception(
            runtime,
            "ValueError",
            "stream_socket_recvfrom(): Argument #2 ($length) must be greater than or equal to 0"
        );
        return ptn_null();
    }
    if (length == 0) {
        ptn_stream_socket_recvfrom_assign_address(runtime, argc, args, ptn_string(""));
        return ptn_string("");
    }
#if defined(_WIN32)
    (void)resource;
    (void)flags;
    ptn_stream_socket_recvfrom_assign_address(runtime, argc, args, ptn_null());
    return ptn_bool(0);
#else
    if (resource->stream == NULL) {
        ptn_stream_socket_recvfrom_assign_address(runtime, argc, args, ptn_null());
        return ptn_bool(0);
    }
    int descriptor = fileno(resource->stream);
    if (descriptor < 0) {
        ptn_stream_socket_recvfrom_assign_address(runtime, argc, args, ptn_null());
        return ptn_bool(0);
    }
    size_t buffer_len = (size_t)length;
    if ((int64_t)buffer_len != length) {
        ptn_abort_out_of_memory();
    }
    char *buffer = malloc(buffer_len);
    if (buffer == NULL) {
        ptn_abort_out_of_memory();
    }
    int recv_flags = 0;
#if defined(MSG_OOB)
    if ((flags & PTN_STREAM_OOB) != 0) {
        recv_flags |= MSG_OOB;
    }
#endif
#if defined(MSG_PEEK)
    if ((flags & PTN_STREAM_PEEK) != 0) {
        recv_flags |= MSG_PEEK;
    }
#endif
    ssize_t received;
    do {
        received = recv(descriptor, buffer, buffer_len, recv_flags);
    } while (received < 0 && errno == EINTR);
    if (received < 0) {
        free(buffer);
        ptn_stream_socket_recvfrom_assign_address(runtime, argc, args, ptn_null());
        return ptn_bool(0);
    }
    ptn_stream_socket_recvfrom_assign_address(runtime, argc, args, ptn_string(""));
    return ptn_owned_string_len(buffer, (size_t)received);
#endif
}

static PtnValue ptn_internal_stream_socket_pair(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    int64_t domain = ptn_internal_expect_integer_arg(runtime, "stream_socket_pair", 1, "domain", args[0], line);
    int64_t type = ptn_internal_expect_integer_arg(runtime, "stream_socket_pair", 2, "type", args[1], line);
    int64_t protocol = ptn_internal_expect_integer_arg(runtime, "stream_socket_pair", 3, "protocol", args[2], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
#if defined(_WIN32)
    (void)domain;
    (void)type;
    (void)protocol;
    ptn_emit_warning(&runtime->diagnostics, "stream_socket_pair(): not supported on this platform", line);
    return ptn_bool(0);
#else
    int descriptors[2] = { -1, -1 };
    if (socketpair((int)domain, (int)type, (int)protocol, descriptors) != 0) {
        char detail[192];
        int needed = snprintf(detail, sizeof(detail), "unable to create socket pair: %s", strerror(errno));
        if (needed < 0 || (size_t)needed >= sizeof(detail)) {
            ptn_abort_out_of_memory();
        }
        ptn_emit_warning(&runtime->diagnostics, detail, line);
        return ptn_bool(0);
    }
    FILE *left = fdopen(descriptors[0], "r+");
    FILE *right = fdopen(descriptors[1], "r+");
    if (left == NULL || right == NULL) {
        if (left != NULL) {
            fclose(left);
        } else if (descriptors[0] >= 0) {
            close(descriptors[0]);
        }
        if (right != NULL) {
            fclose(right);
        } else if (descriptors[1] >= 0) {
            close(descriptors[1]);
        }
        ptn_emit_warning(&runtime->diagnostics, "stream_socket_pair(): unable to open socket streams", line);
        return ptn_bool(0);
    }
    PtnValue result = ptn_array_from_literal_entries(0, NULL);
    ptn_array_set_entry(
        result.as.array,
        ptn_array_int_key(0),
        ptn_resource(ptn_resource_new_stream(left, "php://fd/socketpair/0", "r+"))
    );
    ptn_array_set_entry(
        result.as.array,
        ptn_array_int_key(1),
        ptn_resource(ptn_resource_new_stream(right, "php://fd/socketpair/1", "r+"))
    );
    return result;
#endif
}

static int ptn_stream_socket_server_path_limit(int abstract) {
#if defined(_WIN32)
    (void)abstract;
    return 0;
#else
    size_t sun_path_len = sizeof(((struct sockaddr_un *)0)->sun_path);
    if (abstract) {
        return sun_path_len > (size_t)INT_MAX ? INT_MAX : (int)sun_path_len;
    }
    return sun_path_len == 0 ? 0 : (int)(sun_path_len - 1);
#endif
}

static void ptn_stream_socket_server_emit_truncated_path_notice(
    PtnRuntime *runtime,
    int max_len,
    size_t line
) {
    char message[160];
    int written = snprintf(
        message,
        sizeof(message),
        "stream_socket_server(): socket path exceeded the maximum allowed length of %d bytes and was truncated",
        max_len
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_notice(&runtime->diagnostics, message, line);
}

static void ptn_stream_socket_server_assign_error(
    PtnRuntime *runtime,
    size_t argc,
    const PtnValue *args,
    int error_code,
    const char *message
) {
    if (argc >= 2) {
        ptn_stream_socket_client_assign_reference(runtime, args[1], ptn_int(error_code));
    }
    if (argc >= 3) {
        ptn_stream_socket_client_assign_reference(
            runtime,
            args[2],
            ptn_owned_string(ptn_duplicate_string(message == NULL ? "" : message))
        );
    }
}

static PtnValue ptn_internal_stream_socket_server(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnStringOperand address = ptn_internal_expect_string_arg(runtime, "stream_socket_server", 1, "address", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    const char *tcp_prefix = "tcp://";
    size_t tcp_prefix_len = strlen(tcp_prefix);
    if (address.len >= tcp_prefix_len && memcmp(address.data, tcp_prefix, tcp_prefix_len) == 0) {
        PtnValue result = ptn_stream_socket_server_open_tcp(runtime, address, argc, args, line);
        ptn_string_operand_free(address);
        return result;
    }
#if defined(_WIN32)
    ptn_string_operand_free(address);
    ptn_emit_warning(&runtime->diagnostics, "stream_socket_server(): not supported on this platform", line);
    ptn_stream_socket_server_assign_error(runtime, argc, args, 0, "not supported on this platform");
    return ptn_bool(0);
#else
    const char *prefix = NULL;
    int socktype = 0;
    if (!ptn_stream_socket_address_is_unix_like(address, &prefix, &socktype)) {
        ptn_string_operand_free(address);
        ptn_emit_warning(&runtime->diagnostics, "stream_socket_server(): only unix:// and udg:// addresses are supported", line);
        ptn_stream_socket_server_assign_error(runtime, argc, args, 0, "unsupported address scheme");
        return ptn_bool(0);
    }

    size_t prefix_len = strlen(prefix);
    const char *socket_path = address.data + prefix_len;
    size_t socket_path_len = address.len - prefix_len;
    int abstract = socket_path_len > 0 && socket_path[0] == '\0';
    int max_len = ptn_stream_socket_server_path_limit(abstract);
    if (max_len <= 0) {
        ptn_string_operand_free(address);
        ptn_stream_socket_server_assign_error(runtime, argc, args, 0, "unix socket paths are unavailable");
        return ptn_bool(0);
    }
    if (socket_path_len > (size_t)max_len) {
        ptn_stream_socket_server_emit_truncated_path_notice(runtime, max_len, line);
        socket_path_len = (size_t)max_len;
    }

    int descriptor = socket(AF_UNIX, socktype, 0);
    if (descriptor < 0) {
        int error_code = errno;
        const char *message = strerror(error_code);
        ptn_string_operand_free(address);
        ptn_emit_warning(&runtime->diagnostics, "stream_socket_server(): unable to create unix socket", line);
        ptn_stream_socket_server_assign_error(runtime, argc, args, error_code, message);
        return ptn_bool(0);
    }

    struct sockaddr_un unix_addr;
    memset(&unix_addr, 0, sizeof(unix_addr));
    unix_addr.sun_family = AF_UNIX;
    memcpy(unix_addr.sun_path, socket_path, socket_path_len);
    socklen_t bind_len = (socklen_t)(offsetof(struct sockaddr_un, sun_path) + socket_path_len);
    if (!abstract) {
        unix_addr.sun_path[socket_path_len] = '\0';
        bind_len++;
    }

    if (bind(descriptor, (struct sockaddr *)&unix_addr, bind_len) != 0 ||
        (socktype == SOCK_STREAM && listen(descriptor, 32) != 0)) {
        int error_code = errno;
        char detail[192];
        int written = snprintf(
            detail,
            sizeof(detail),
            "stream_socket_server(): unable to bind unix socket: %s",
            strerror(error_code)
        );
        if (written < 0 || (size_t)written >= sizeof(detail)) {
            close(descriptor);
            ptn_string_operand_free(address);
            ptn_abort_out_of_memory();
        }
        close(descriptor);
        ptn_string_operand_free(address);
        ptn_emit_warning(&runtime->diagnostics, detail, line);
        ptn_stream_socket_server_assign_error(runtime, argc, args, error_code, strerror(error_code));
        return ptn_bool(0);
    }

    FILE *stream = fdopen(descriptor, "r+");
    if (stream == NULL) {
        int error_code = errno;
        const char *message = strerror(error_code);
        close(descriptor);
        ptn_string_operand_free(address);
        ptn_emit_warning(&runtime->diagnostics, "stream_socket_server(): unable to open socket stream", line);
        ptn_stream_socket_server_assign_error(runtime, argc, args, error_code, message);
        return ptn_bool(0);
    }
    char *uri = ptn_duplicate_string_len(address.data, address.len);
    ptn_string_operand_free(address);
    PtnValue result = ptn_resource(ptn_resource_new_stream(stream, uri, "r+"));
    free(uri);
    ptn_stream_socket_server_assign_error(runtime, argc, args, 0, "");
    return result;
#endif
}

static int ptn_stream_resource_is_socket_like(PtnResource *resource) {
    if (resource == NULL || resource->stream_uri == NULL) {
        return 0;
    }
    const char *uri = resource->stream_uri;
    return ptn_ascii_case_has_prefix(uri, "tcp://") ||
        ptn_ascii_case_has_prefix(uri, "udp://") ||
        ptn_ascii_case_has_prefix(uri, "unix://") ||
        ptn_ascii_case_has_prefix(uri, "udg://");
}

static PtnValue ptn_internal_stream_set_blocking(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnResource *resource = ptn_internal_expect_open_stream_arg(runtime, "stream_set_blocking", args[0], line);
    if (resource == NULL) {
        return ptn_null();
    }
    int enabled = ptn_is_truthy(args[1]);
#if defined(_WIN32)
    (void)resource;
    (void)enabled;
    return ptn_bool(0);
#else
    if (resource->stream == NULL) {
        return ptn_bool(0);
    }
    int fd = fileno(resource->stream);
    if (fd < 0) {
        return ptn_bool(0);
    }
    int flags = fcntl(fd, F_GETFL, 0);
    if (flags < 0) {
        return ptn_bool(0);
    }
    if (enabled) {
        flags &= ~O_NONBLOCK;
    } else {
        flags |= O_NONBLOCK;
    }
    return ptn_bool(fcntl(fd, F_SETFL, flags) == 0);
#endif
}

static PtnValue ptn_internal_stream_set_timeout(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnResource *resource = ptn_internal_expect_open_stream_arg(runtime, "stream_set_timeout", args[0], line);
    if (resource == NULL) {
        return ptn_null();
    }
    int64_t seconds = ptn_internal_expect_integer_arg(runtime, "stream_set_timeout", 2, "seconds", args[1], line);
    int64_t microseconds = argc >= 3
        ? ptn_internal_expect_integer_arg(runtime, "stream_set_timeout", 3, "microseconds", args[2], line)
        : 0;
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    if (seconds < 0) {
        ptn_throw_exception(runtime, "ValueError", "stream_set_timeout(): Argument #2 ($seconds) must be greater than or equal to 0");
        return ptn_null();
    }
    if (microseconds < 0) {
        ptn_throw_exception(runtime, "ValueError", "stream_set_timeout(): Argument #3 ($microseconds) must be greater than or equal to 0");
        return ptn_null();
    }
#if defined(_WIN32)
    (void)resource;
    (void)seconds;
    (void)microseconds;
    return ptn_bool(0);
#else
    if (resource->stream == NULL || !ptn_stream_resource_is_socket_like(resource)) {
        return ptn_bool(0);
    }
    int fd = fileno(resource->stream);
    if (fd < 0) {
        return ptn_bool(0);
    }
    struct timeval timeout;
    timeout.tv_sec = (time_t)seconds;
    timeout.tv_usec = (suseconds_t)microseconds;
    int receive_ok = setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout)) == 0;
    int send_ok = setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &timeout, sizeof(timeout)) == 0;
    return ptn_bool(receive_ok && send_ok);
#endif
}

static PtnValue ptn_internal_stream_set_write_buffer(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnResource *resource = ptn_internal_expect_open_stream_arg(runtime, "stream_set_write_buffer", args[0], line);
    if (resource == NULL) {
        return ptn_null();
    }
    int64_t size = ptn_internal_expect_integer_arg(runtime, "stream_set_write_buffer", 2, "size", args[1], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    PtnUserStreamResourceData *user_stream = ptn_user_stream_resource_data(resource);
    if (user_stream != NULL) {
        if (user_stream->runtime == NULL ||
            user_stream->runtime->method_dispatch == NULL ||
            !ptn_object_has_declared_method(user_stream->runtime, user_stream->wrapper_object, "stream_set_option")) {
            PtnValue wrapper_object = ptn_value_deref(user_stream->wrapper_object);
            const char *class_name = wrapper_object.type == PTN_OBJECT && wrapper_object.as.object != NULL
                ? wrapper_object.as.object->class_name
                : "user-space";
            char message[224];
            int written = snprintf(
                message,
                sizeof(message),
                "%s::stream_set_option is not implemented!",
                class_name == NULL ? "user-space" : class_name
            );
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_stream_report_resource_error(
                runtime,
                resource,
                "stream_set_write_buffer",
                message,
                "user-space",
                "NotImplemented",
                0,
                1,
                line
            );
            return ptn_bool(0);
        }
        PtnValue option_args[3] = {
            ptn_int(3),
            ptn_int(size == 0 ? 0 : 2),
            ptn_int(size)
        };
        PtnValue option_result = user_stream->runtime->method_dispatch(
            user_stream->runtime,
            user_stream->wrapper_object,
            "stream_set_option",
            3,
            option_args,
            line
        );
        ptn_value_destroy(&option_args[0]);
        ptn_value_destroy(&option_args[1]);
        ptn_value_destroy(&option_args[2]);
        if (user_stream->runtime->exceptions->active_exception != NULL) {
            ptn_value_destroy(&option_result);
            return ptn_null();
        }
        int ok = ptn_is_truthy(option_result);
        ptn_value_destroy(&option_result);
        return ptn_int(ok ? 0 : -1);
    }
#if defined(_IONBF) && defined(_IOFBF)
    if (resource->stream != NULL) {
        int mode = size == 0 ? _IONBF : _IOFBF;
        return ptn_int(setvbuf(resource->stream, NULL, mode, size <= 0 ? 0 : (size_t)size) == 0 ? 0 : -1);
    }
#endif
    return ptn_int(0);
}

static PtnValue ptn_internal_stream_set_chunk_size(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnResource *resource = ptn_internal_expect_open_stream_arg(runtime, "stream_set_chunk_size", args[0], line);
    if (resource == NULL) {
        return ptn_null();
    }
    int64_t size = ptn_internal_positive_length_arg(
        runtime,
        "stream_set_chunk_size",
        2,
        "size",
        args[1],
        line
    );
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    size_t previous = resource->chunk_size == 0 ? 8192 : resource->chunk_size;
    resource->chunk_size = (size_t)size;
    if (previous > (size_t)INT64_MAX) {
        ptn_abort_out_of_memory();
    }
    return ptn_int((int64_t)previous);
}

static int ptn_stream_select_arg_array(
    PtnRuntime *runtime,
    const char *function_name,
    size_t position,
    const char *argument_name,
    PtnValue value,
    PtnArray **array_out,
    int *is_null_out
) {
    value = ptn_value_deref(value);
    if (value.type == PTN_NULL) {
        *array_out = NULL;
        *is_null_out = 1;
        return 1;
    }
    *is_null_out = 0;
    if (value.type != PTN_ARRAY) {
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "%s(): Argument #%zu ($%s) must be of type ?array, %s given",
            function_name,
            position,
            argument_name,
            ptn_offset_container_type_name(value)
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "TypeError", message);
        return 0;
    }
    *array_out = value.as.array;
    return 1;
}

static const char *ptn_user_stream_wrapper_class_name(PtnUserStreamResourceData *data) {
    if (data == NULL) {
        return "user-space";
    }
    PtnValue wrapper_object = ptn_value_deref(data->wrapper_object);
    return wrapper_object.type == PTN_OBJECT && wrapper_object.as.object != NULL
        ? wrapper_object.as.object->class_name
        : "user-space";
}

static void ptn_stream_select_report_user_stream_not_representable(
    PtnRuntime *runtime,
    const char *function_name,
    PtnResource *resource,
    size_t line,
    int replace_existing
) {
    ptn_stream_report_resource_error(
        runtime,
        resource,
        function_name,
        "Cannot represent a stream of type user-space as a select()able descriptor",
        "user-space",
        "CastNotSupported",
        1,
        replace_existing,
        line
    );
}

static PtnResource *ptn_stream_select_cast_resource(
    PtnRuntime *runtime,
    const char *function_name,
    PtnResource *resource,
    size_t line,
    size_t depth
) {
    PtnUserStreamResourceData *user_stream = ptn_user_stream_resource_data(resource);
    if (user_stream == NULL) {
        ptn_resource_retain(resource);
        return resource;
    }
    const char *class_name = ptn_user_stream_wrapper_class_name(user_stream);
    if (depth > 8 ||
        user_stream->runtime == NULL ||
        user_stream->runtime->method_dispatch == NULL ||
        !ptn_object_has_declared_method(user_stream->runtime, user_stream->wrapper_object, "stream_cast")) {
        char not_implemented[192];
        int written = snprintf(
            not_implemented,
            sizeof(not_implemented),
            "%s::stream_cast is not implemented!",
            class_name == NULL ? "user-space" : class_name
        );
        if (written < 0 || (size_t)written >= sizeof(not_implemented)) {
            ptn_abort_out_of_memory();
        }
        ptn_stream_report_resource_error(
            runtime,
            resource,
            function_name,
            not_implemented,
            "user-space",
            "NotImplemented",
            1,
            1,
            line
        );
        if (runtime->exceptions->active_exception != NULL) {
            return NULL;
        }
        ptn_stream_select_report_user_stream_not_representable(runtime, function_name, resource, line, 0);
        return NULL;
    }

    PtnValue cast_arg = ptn_int(3);
    PtnValue cast_result = user_stream->runtime->method_dispatch(
        user_stream->runtime,
        user_stream->wrapper_object,
        "stream_cast",
        1,
        &cast_arg,
        line
    );
    ptn_value_destroy(&cast_arg);
    if (user_stream->runtime->exceptions->active_exception != NULL) {
        ptn_value_destroy(&cast_result);
        return NULL;
    }

    PtnValue resolved = ptn_value_deref(cast_result);
    if (resolved.type == PTN_BOOL && !resolved.as.boolean) {
        ptn_value_destroy(&cast_result);
        ptn_stream_select_report_user_stream_not_representable(runtime, function_name, resource, line, 1);
        return NULL;
    }
    if (resolved.type != PTN_RESOURCE || resolved.as.resource == NULL) {
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "%s::stream_cast must return a stream resource",
            class_name == NULL ? "user-space" : class_name
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_value_destroy(&cast_result);
        ptn_stream_report_resource_error(
            runtime,
            resource,
            function_name,
            message,
            "user-space",
            "CastInvalidReturn",
            1,
            1,
            line
        );
        if (runtime->exceptions->active_exception != NULL) {
            return NULL;
        }
        ptn_stream_select_report_user_stream_not_representable(runtime, function_name, resource, line, 0);
        return NULL;
    }
    PtnResource *cast_resource = resolved.as.resource;
    if (cast_resource == resource) {
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "%s::stream_cast must not return itself",
            class_name == NULL ? "user-space" : class_name
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_value_destroy(&cast_result);
        ptn_stream_report_resource_error(
            runtime,
            resource,
            function_name,
            message,
            "user-space",
            "CastInvalidReturn",
            1,
            1,
            line
        );
        if (runtime->exceptions->active_exception != NULL) {
            return NULL;
        }
        ptn_stream_select_report_user_stream_not_representable(runtime, function_name, resource, line, 0);
        return NULL;
    }
    if (!ptn_resource_is_open(cast_resource)) {
        ptn_value_destroy(&cast_result);
        ptn_stream_select_report_user_stream_not_representable(runtime, function_name, resource, line, 1);
        return NULL;
    }
    if (ptn_user_stream_resource_data(cast_resource) != NULL) {
        PtnResource *nested = ptn_stream_select_cast_resource(runtime, function_name, cast_resource, line, depth + 1);
        ptn_value_destroy(&cast_result);
        if (nested == NULL && runtime->exceptions->active_exception == NULL) {
            ptn_stream_select_report_user_stream_not_representable(runtime, function_name, resource, line, 0);
        }
        return nested;
    }
    ptn_resource_retain(cast_resource);
    ptn_value_destroy(&cast_result);
    return cast_resource;
}

static int ptn_stream_select_add_array(
    PtnRuntime *runtime,
    const char *function_name,
    PtnArray *array,
    fd_set *set,
    int *max_fd,
    int read_interest,
    int *preselected,
    size_t line
) {
    if (array == NULL) {
        return 1;
    }
    for (size_t i = 0; i < array->len; i++) {
        PtnValue value = ptn_value_deref(array->entries[i].value);
        if (value.type != PTN_RESOURCE || !ptn_stream_resource_is_open(value.as.resource)) {
            char message[128];
            int written = snprintf(
                message,
                sizeof(message),
                "%s(): supplied resource is not a valid stream resource",
                function_name
            );
            if (written < 0 || (size_t)written >= sizeof(message)) {
                ptn_abort_out_of_memory();
            }
            ptn_emit_warning(&runtime->diagnostics, message, line);
            return 0;
        }
        PtnResource *select_resource = value.as.resource;
        int release_select_resource = 0;
        if (ptn_user_stream_resource_data(value.as.resource) != NULL) {
            select_resource = ptn_stream_select_cast_resource(runtime, function_name, value.as.resource, line, 0);
            if (runtime->exceptions->active_exception != NULL) {
                return 0;
            }
            if (select_resource == NULL) {
                continue;
            }
            release_select_resource = 1;
        }
        if (read_interest && select_resource->memory_stream != NULL) {
            if (select_resource->memory_stream->position < select_resource->memory_stream->len) {
                (*preselected)++;
            }
            if (release_select_resource) {
                ptn_resource_release(select_resource);
            }
            continue;
        }
        if (select_resource->stream == NULL) {
            ptn_emit_warning(&runtime->diagnostics, "stream_select(): supplied stream file descriptor cannot be selected", line);
            if (release_select_resource) {
                ptn_resource_release(select_resource);
            }
            return 0;
        }
        int fd = fileno(select_resource->stream);
        if (fd < 0 || fd >= FD_SETSIZE) {
            ptn_emit_warning(&runtime->diagnostics, "stream_select(): supplied stream file descriptor cannot be selected", line);
            if (release_select_resource) {
                ptn_resource_release(select_resource);
            }
            return 0;
        }
        FD_SET(fd, set);
        if (fd > *max_fd) {
            *max_fd = fd;
        }
        if (release_select_resource) {
            ptn_resource_release(select_resource);
        }
    }
    return 1;
}

static PtnValue ptn_stream_select_selected_array(PtnArray *array, fd_set *set, int read_interest) {
    PtnValue selected = ptn_array_from_literal_entries(0, NULL);
    if (array == NULL) {
        return selected;
    }
    for (size_t i = 0; i < array->len; i++) {
        PtnValue value = ptn_value_deref(array->entries[i].value);
        if (value.type != PTN_RESOURCE) {
            continue;
        }
        if (read_interest &&
            value.as.resource->memory_stream != NULL &&
            value.as.resource->memory_stream->position < value.as.resource->memory_stream->len) {
            ptn_array_set_entry(
                selected.as.array,
                ptn_array_key_clone(array->entries[i].key),
                ptn_value_clone_deref(array->entries[i].value)
            );
            continue;
        }
        if (value.as.resource->stream == NULL) {
            continue;
        }
        int fd = fileno(value.as.resource->stream);
        if (fd >= 0 && fd < FD_SETSIZE && FD_ISSET(fd, set)) {
            ptn_array_set_entry(
                selected.as.array,
                ptn_array_key_clone(array->entries[i].key),
                ptn_value_clone_deref(array->entries[i].value)
            );
        }
    }
    return selected;
}

static void ptn_stream_select_assign_result(PtnRuntime *runtime, PtnValue arg, PtnValue value) {
    if (arg.type == PTN_REFERENCE) {
        (void)ptn_reference_assign(runtime, arg.as.reference, value);
    }
    ptn_value_destroy(&value);
}

static PtnValue ptn_internal_stream_select(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
#if defined(_WIN32)
    (void)runtime;
    (void)args;
    (void)line;
    return ptn_bool(0);
#else
    PtnArray *read_array = NULL;
    PtnArray *write_array = NULL;
    PtnArray *except_array = NULL;
    int read_null = 0;
    int write_null = 0;
    int except_null = 0;
    if (!ptn_stream_select_arg_array(runtime, "stream_select", 1, "read", args[0], &read_array, &read_null) ||
        !ptn_stream_select_arg_array(runtime, "stream_select", 2, "write", args[1], &write_array, &write_null) ||
        !ptn_stream_select_arg_array(runtime, "stream_select", 3, "except", args[2], &except_array, &except_null)) {
        return ptn_null();
    }

    fd_set read_set;
    fd_set write_set;
    fd_set except_set;
    FD_ZERO(&read_set);
    FD_ZERO(&write_set);
    FD_ZERO(&except_set);
    int max_fd = -1;
    int preselected = 0;
    if (!ptn_stream_select_add_array(runtime, "stream_select", read_array, &read_set, &max_fd, 1, &preselected, line) ||
        !ptn_stream_select_add_array(runtime, "stream_select", write_array, &write_set, &max_fd, 0, &preselected, line) ||
        !ptn_stream_select_add_array(runtime, "stream_select", except_array, &except_set, &max_fd, 0, &preselected, line)) {
        return ptn_bool(0);
    }
    if (max_fd < 0 && preselected == 0) {
        ptn_throw_exception(runtime, "ValueError", "No stream arrays were passed");
        return ptn_null();
    }

    struct timeval timeout;
    struct timeval immediate_timeout;
    struct timeval *timeout_ptr = NULL;
    PtnValue seconds_value = ptn_value_deref(args[3]);
    if (seconds_value.type != PTN_NULL) {
        int64_t seconds = ptn_internal_expect_integer_arg(runtime, "stream_select", 4, "seconds", args[3], line);
        int64_t microseconds = argc >= 5
            ? ptn_internal_expect_integer_arg(runtime, "stream_select", 5, "microseconds", args[4], line)
            : 0;
        if (runtime->exceptions->active_exception != NULL) {
            return ptn_null();
        }
        if (seconds < 0 || microseconds < 0) {
            ptn_throw_exception(runtime, "ValueError", "stream_select(): timeout must be greater than or equal to 0");
            return ptn_null();
        }
        timeout.tv_sec = (time_t)seconds;
        timeout.tv_usec = (suseconds_t)microseconds;
        timeout_ptr = &timeout;
    } else if (argc >= 5 && ptn_value_deref(args[4]).type != PTN_NULL) {
        int64_t microseconds = ptn_internal_expect_integer_arg(runtime, "stream_select", 5, "microseconds", args[4], line);
        if (runtime->exceptions->active_exception != NULL) {
            return ptn_null();
        }
        if (microseconds != 0) {
            ptn_throw_exception(
                runtime,
                "ValueError",
                "stream_select(): Argument #5 ($microseconds) must be null when argument #4 ($seconds) is null"
            );
            return ptn_null();
        }
    }
    if (preselected > 0) {
        immediate_timeout.tv_sec = 0;
        immediate_timeout.tv_usec = 0;
        timeout_ptr = &immediate_timeout;
    }

    int selected = preselected;
    if (max_fd >= 0) {
        int fd_selected = 0;
        do {
            fd_selected = select(
                max_fd + 1,
                read_array == NULL ? NULL : &read_set,
                write_array == NULL ? NULL : &write_set,
                except_array == NULL ? NULL : &except_set,
                timeout_ptr
            );
        } while (fd_selected < 0 && errno == EINTR);
        if (fd_selected < 0) {
            ptn_emit_warning(&runtime->diagnostics, "stream_select(): unable to select on supplied streams", line);
            return ptn_bool(0);
        }
        selected += fd_selected;
    }

    ptn_stream_select_assign_result(
        runtime,
        args[0],
        read_null ? ptn_null() : ptn_stream_select_selected_array(read_array, &read_set, 1)
    );
    ptn_stream_select_assign_result(
        runtime,
        args[1],
        write_null ? ptn_null() : ptn_stream_select_selected_array(write_array, &write_set, 0)
    );
    ptn_stream_select_assign_result(
        runtime,
        args[2],
        except_null ? ptn_null() : ptn_stream_select_selected_array(except_array, &except_set, 0)
    );
    return ptn_int(selected);
#endif
}

static PtnValue ptn_internal_stream_socket_shutdown(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnResource *resource = ptn_internal_expect_open_stream_arg(runtime, "stream_socket_shutdown", args[0], line);
    if (resource == NULL) {
        return ptn_null();
    }
    int64_t how = ptn_internal_expect_integer_arg(runtime, "stream_socket_shutdown", 2, "mode", args[1], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
#if defined(_WIN32)
    (void)resource;
    (void)how;
    return ptn_bool(0);
#else
    if (resource->stream == NULL) {
        errno = EBADF;
        return ptn_bool(0);
    }
    if (fflush(resource->stream) != 0) {
        return ptn_bool(0);
    }
    int descriptor = fileno(resource->stream);
    if (descriptor < 0) {
        return ptn_bool(0);
    }
    return ptn_bool(shutdown(descriptor, (int)how) == 0);
#endif
}

static int ptn_zlib_encoding_is_valid(int64_t encoding) {
    return encoding == PTN_ZLIB_ENCODING_RAW ||
        encoding == PTN_ZLIB_ENCODING_GZIP ||
        encoding == PTN_ZLIB_ENCODING_DEFLATE;
}

static void ptn_zlib_throw_encoding_value_error(
    PtnRuntime *runtime,
    const char *function_name,
    size_t position,
    const char *argument_name
) {
    char message[192];
    int written = snprintf(
        message,
        sizeof(message),
        "%s(): Argument #%zu ($%s) must be one of ZLIB_ENCODING_RAW, ZLIB_ENCODING_GZIP, or ZLIB_ENCODING_DEFLATE",
        function_name,
        position,
        argument_name
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "ValueError", message);
}

static int ptn_zlib_level_is_valid(int64_t level) {
    return level >= -1 && level <= 9;
}

static void ptn_zlib_throw_level_value_error(PtnRuntime *runtime, const char *function_name) {
    char message[128];
    int written = snprintf(
        message,
        sizeof(message),
        "%s(): Argument #2 ($level) must be between -1 and 9",
        function_name
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "ValueError", message);
}

static int ptn_zlib_option_value(PtnValue options, const char *name, PtnValue *value_out) {
    options = ptn_value_deref(options);
    if (options.type == PTN_ARRAY && options.as.array != NULL) {
        PtnArrayKey key = ptn_array_string_key(name);
        PtnArrayEntry *entry = ptn_array_entry_for_key(options.as.array, key);
        ptn_array_key_free(key);
        *value_out = entry == NULL ? ptn_null() : ptn_value_clone_deref(entry->value);
        return entry != NULL;
    }
    if (options.type == PTN_OBJECT && options.as.object != NULL && options.as.object->properties != NULL) {
        PtnArrayKey key = ptn_array_string_key(name);
        PtnArrayEntry *entry = ptn_array_entry_for_key(options.as.object->properties, key);
        ptn_array_key_free(key);
        if (entry != NULL) {
            *value_out = ptn_value_clone_deref(entry->value);
            return 1;
        }
        const PtnObjectPropertyMetadata *metadata =
            ptn_object_property_metadata(options.as.object, name);
        if (metadata != NULL && metadata->read_visibility == PTN_PROPERTY_PUBLIC) {
            *value_out = ptn_null();
            return 1;
        }
    }
    *value_out = ptn_null();
    return 0;
}

static void ptn_zlib_throw_option_range_value_error(
    PtnRuntime *runtime,
    const char *function_name,
    const char *option_name,
    int64_t min,
    int64_t max
) {
    char message[160];
    int written = snprintf(
        message,
        sizeof(message),
        "%s(): \"%s\" option must be between %lld and %lld",
        function_name,
        option_name,
        (long long)min,
        (long long)max
    );
    if (written < 0 || (size_t)written >= sizeof(message)) {
        ptn_abort_out_of_memory();
    }
    ptn_throw_exception(runtime, "ValueError", message);
}

static int ptn_zlib_option_integer(
    PtnRuntime *runtime,
    const char *function_name,
    PtnValue options,
    const char *option_name,
    int64_t min,
    int64_t max,
    int64_t *out
) {
    PtnValue option = ptn_null();
    if (!ptn_zlib_option_value(options, option_name, &option)) {
        return 1;
    }

    PtnValue resolved = ptn_value_deref(option);
    if (resolved.type != PTN_INT) {
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "%s(): Argument #2 ($options) the value for option \"%s\" must be of type int, %s given",
            function_name,
            option_name,
            ptn_offset_container_type_name(resolved)
        );
        ptn_value_destroy(&option);
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "TypeError", message);
        return 0;
    }
    if (resolved.as.integer < min || resolved.as.integer > max) {
        ptn_value_destroy(&option);
        ptn_zlib_throw_option_range_value_error(runtime, function_name, option_name, min, max);
        return 0;
    }
    *out = resolved.as.integer;
    ptn_value_destroy(&option);
    return 1;
}

static int ptn_zlib_option_int(
    PtnRuntime *runtime,
    const char *function_name,
    const char *option_name,
    PtnValue options,
    int64_t *value_out,
    int *found_out
) {
    PtnValue option = ptn_null();
    int found = ptn_zlib_option_value(options, option_name, &option);
    *found_out = found;
    if (!found) {
        return 1;
    }
    PtnValue resolved = ptn_value_deref(option);
    if (resolved.type != PTN_INT) {
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "%s(): Argument #2 ($options) the value for option \"%s\" must be of type int, %s given",
            function_name,
            option_name,
            ptn_offset_container_type_name(resolved)
        );
        ptn_value_destroy(&option);
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "TypeError", message);
        return 0;
    }
    *value_out = resolved.as.integer;
    ptn_value_destroy(&option);
    return 1;
}

static int ptn_zlib_dictionary_append_array_entry(
    PtnRuntime *runtime,
    const char *function_name,
    PtnStringBuffer *buffer,
    PtnValue value,
    size_t line
) {
    PtnStringOperand string = ptn_value_to_string_operand_with_runtime(runtime, value, line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(string);
        return 0;
    }
    if (string.len == 0) {
        ptn_string_operand_free(string);
        char message[160];
        int written = snprintf(
            message,
            sizeof(message),
            "%s(): Argument #2 ($options) must not contain empty strings",
            function_name
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "ValueError", message);
        return 0;
    }
    if (memchr(string.data, '\0', string.len) != NULL) {
        ptn_string_operand_free(string);
        char message[176];
        int written = snprintf(
            message,
            sizeof(message),
            "%s(): Argument #2 ($options) must not contain strings with null bytes",
            function_name
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "ValueError", message);
        return 0;
    }
    ptn_string_buffer_append_len(buffer, string.data, string.len);
    ptn_string_operand_free(string);
    return 1;
}

static int ptn_zlib_resolve_dictionary_option(
    PtnRuntime *runtime,
    const char *function_name,
    PtnValue options,
    unsigned char **dictionary_out,
    size_t *dictionary_len_out,
    size_t line
) {
    *dictionary_out = NULL;
    *dictionary_len_out = 0;
    PtnValue dictionary = ptn_null();
    if (!ptn_stream_filter_option(options, "dictionary", &dictionary)) {
        return 1;
    }

    PtnValue resolved = ptn_value_deref(dictionary);
    PtnStringBuffer buffer;
    ptn_string_buffer_init(&buffer);
    if (resolved.type == PTN_ARRAY && resolved.as.array != NULL) {
        for (size_t i = 0; i < resolved.as.array->len; i++) {
            if (!ptn_zlib_dictionary_append_array_entry(
                runtime,
                function_name,
                &buffer,
                resolved.as.array->entries[i].value,
                line
            )) {
                free(buffer.data);
                ptn_value_destroy(&dictionary);
                return 0;
            }
        }
    } else {
        PtnStringOperand string = ptn_value_to_string_operand_with_runtime(runtime, resolved, line);
        if (runtime->exceptions->active_exception != NULL) {
            ptn_string_operand_free(string);
            free(buffer.data);
            ptn_value_destroy(&dictionary);
            return 0;
        }
        ptn_string_buffer_append_len(&buffer, string.data, string.len);
        ptn_string_operand_free(string);
    }

    ptn_value_destroy(&dictionary);
    *dictionary_out = (unsigned char *)buffer.data;
    *dictionary_len_out = buffer.len;
    return 1;
}

static PtnValue ptn_zlib_context_resource(
    int64_t encoding,
    int64_t level,
    unsigned char *dictionary,
    size_t dictionary_len,
    const char *type_name
);

static PtnValue ptn_internal_inflate_init(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    int64_t encoding = ptn_internal_expect_integer_arg(runtime, "inflate_init", 1, "encoding", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    if (argc >= 2 && ptn_value_deref(args[1]).type != PTN_NULL) {
        int found_window = 0;
        int64_t window = encoding;
        if (!ptn_zlib_option_int(runtime, "inflate_init", "window", args[1], &window, &found_window)) {
            return ptn_null();
        }
        if (found_window) {
            encoding = window;
        }
    }
    if (!ptn_zlib_encoding_is_valid(encoding)) {
        ptn_zlib_throw_encoding_value_error(runtime, "inflate_init", 1, "encoding");
        return ptn_null();
    }
    unsigned char *dictionary = NULL;
    size_t dictionary_len = 0;
    if (argc >= 2 && ptn_value_deref(args[1]).type != PTN_NULL &&
        !ptn_zlib_resolve_dictionary_option(runtime, "inflate_init", args[1], &dictionary, &dictionary_len, line)) {
        return ptn_null();
    }
    return ptn_zlib_context_resource(encoding, -1, dictionary, dictionary_len, "zlib inflate");
}

static PtnValue ptn_internal_deflate_init(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    int64_t encoding = ptn_internal_expect_integer_arg(runtime, "deflate_init", 1, "encoding", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    if (!ptn_zlib_encoding_is_valid(encoding)) {
        ptn_zlib_throw_encoding_value_error(runtime, "deflate_init", 1, "encoding");
        return ptn_null();
    }
    int64_t level_value = -1;
    int64_t memory_value = 8;
    if (argc >= 2 && ptn_value_deref(args[1]).type != PTN_NULL) {
        if (!ptn_zlib_option_integer(
            runtime,
            "deflate_init",
            args[1],
            "level",
            -1,
            9,
            &level_value
        )) {
            return ptn_null();
        }
        if (!ptn_zlib_option_integer(
            runtime,
            "deflate_init",
            args[1],
            "memory",
            1,
            9,
            &memory_value
        )) {
            return ptn_null();
        }
    }
    (void)memory_value;
    unsigned char *dictionary = NULL;
    size_t dictionary_len = 0;
    if (argc >= 2 && ptn_value_deref(args[1]).type != PTN_NULL &&
        !ptn_zlib_resolve_dictionary_option(runtime, "deflate_init", args[1], &dictionary, &dictionary_len, line)) {
        return ptn_null();
    }
    return ptn_zlib_context_resource(encoding, level_value, dictionary, dictionary_len, "zlib deflate");
}

typedef struct {
    int64_t encoding;
    int64_t level;
    unsigned char *dictionary;
    size_t dictionary_len;
    unsigned char *input;
    size_t input_len;
    size_t input_capacity;
    unsigned char *output;
    size_t output_len;
    int64_t status;
    pid_t worker_pid;
    int worker_input_fd;
    int worker_output_fd;
    int worker_failed;
#if PTN_HAVE_ZLIB
    z_stream native_stream;
    int native_stream_initialized;
    int native_stream_ended;
    int native_dictionary_applied;
    int native_stream_is_deflate;
#endif
} PtnZlibContext;

static void ptn_zlib_context_end_native(PtnZlibContext *context) {
#if PTN_HAVE_ZLIB
    if (context != NULL && context->native_stream_initialized) {
        if (context->native_stream_is_deflate) {
            deflateEnd(&context->native_stream);
        } else {
            inflateEnd(&context->native_stream);
        }
        memset(&context->native_stream, 0, sizeof(context->native_stream));
        context->native_stream_initialized = 0;
        context->native_dictionary_applied = 0;
        context->native_stream_is_deflate = 0;
    }
#else
    (void)context;
#endif
}

static void ptn_zlib_context_data_free(void *data) {
    PtnZlibContext *context = (PtnZlibContext *)data;
    if (context == NULL) {
        return;
    }
    ptn_zlib_context_end_native(context);
    if (context->worker_input_fd >= 0) {
        close(context->worker_input_fd);
        context->worker_input_fd = -1;
    }
    if (context->worker_output_fd >= 0) {
        close(context->worker_output_fd);
        context->worker_output_fd = -1;
    }
    if (context->worker_pid > 0) {
        (void)ptn_zlib_wait_success(context->worker_pid);
        context->worker_pid = -1;
    }
    free(context->dictionary);
    free(context->input);
    free(context->output);
    free(context);
}

static void ptn_zlib_context_reset_stream(PtnZlibContext *context) {
    if (context == NULL) {
        return;
    }
    context->input_len = 0;
    context->output_len = 0;
    context->status = PTN_ZLIB_OK;
}

static void ptn_zlib_context_append_input(PtnZlibContext *context, const unsigned char *data, size_t len) {
    if (len == 0) {
        return;
    }
    if (len > SIZE_MAX - context->input_len) {
        ptn_abort_out_of_memory();
    }
    size_t required = context->input_len + len;
    if (required > context->input_capacity) {
        size_t capacity = context->input_capacity == 0 ? 64 : context->input_capacity;
        while (capacity < required) {
            if (capacity > SIZE_MAX / 2) {
                ptn_abort_out_of_memory();
            }
            capacity *= 2;
        }
        unsigned char *input = realloc(context->input, capacity);
        if (input == NULL) {
            ptn_abort_out_of_memory();
        }
        context->input = input;
        context->input_capacity = capacity;
    }
    memcpy(context->input + context->input_len, data, len);
    context->input_len = required;
}

static PtnValue ptn_zlib_context_resource(
    int64_t encoding,
    int64_t level,
    unsigned char *dictionary,
    size_t dictionary_len,
    const char *type_name
) {
    PtnZlibContext *context = malloc(sizeof(PtnZlibContext));
    if (context == NULL) {
        free(dictionary);
        ptn_abort_out_of_memory();
    }
    context->encoding = encoding;
    context->level = level;
    context->dictionary = dictionary;
    context->dictionary_len = dictionary_len;
    context->input = NULL;
    context->input_len = 0;
    context->input_capacity = 0;
    context->output = NULL;
    context->output_len = 0;
    context->status = PTN_ZLIB_OK;
    context->worker_pid = -1;
    context->worker_input_fd = -1;
    context->worker_output_fd = -1;
    context->worker_failed = 0;
#if PTN_HAVE_ZLIB
    memset(&context->native_stream, 0, sizeof(context->native_stream));
    context->native_stream_initialized = 0;
    context->native_stream_ended = 0;
    context->native_dictionary_applied = 0;
    context->native_stream_is_deflate = 0;
#endif
    PtnResource *resource = ptn_resource_new_named(type_name);
    resource->close_hook_data = context;
    resource->close_hook_data_free = ptn_zlib_context_data_free;
    return ptn_resource(resource);
}

static PtnValue ptn_zlib_transform_string_value_limited(
    PtnRuntime *runtime,
    const char *function_name,
    PtnStringOperand data,
    int decompress,
    int64_t encoding,
    int64_t level,
    int64_t max_length,
    size_t line
) {
    unsigned char *transformed = NULL;
    size_t transformed_len = 0;
    int ok = ptn_zlib_transform_bytes_no_dictionary(
        (const unsigned char *)data.data,
        data.len,
        decompress,
        encoding,
        level,
        decompress && max_length > 0 && data.len > 0,
        &transformed,
        &transformed_len
    );
    if (ok <= 0) {
        char detail[192];
        int written = snprintf(
            detail,
            sizeof(detail),
            "%s(): %s",
            function_name,
            decompress ? "data error" : "compression"
        );
        if (written < 0 || (size_t)written >= sizeof(detail)) {
            ptn_abort_out_of_memory();
        }
        ptn_emit_warning(&runtime->diagnostics, detail, line);
        return ptn_bool(0);
    }
    if (decompress && max_length > 0 && transformed_len > (uint64_t)max_length) {
        free(transformed);
        char detail[128];
        int written = snprintf(detail, sizeof(detail), "%s(): insufficient memory", function_name);
        if (written < 0 || (size_t)written >= sizeof(detail)) {
            ptn_abort_out_of_memory();
        }
        ptn_emit_warning(&runtime->diagnostics, detail, line);
        return ptn_bool(0);
    }
    return ptn_owned_string_len((char *)transformed, transformed_len);
}

static PtnValue ptn_zlib_transform_string_value(
    PtnRuntime *runtime,
    const char *function_name,
    PtnStringOperand data,
    int decompress,
    int64_t encoding,
    int64_t level,
    int64_t max_length,
    size_t line
) {
    return ptn_zlib_transform_string_value_limited(
        runtime,
        function_name,
        data,
        decompress,
        encoding,
        level,
        max_length,
        line
    );
}

static int ptn_zlib_context_deflate_with_zlib(
    PtnZlibContext *context,
    PtnStringOperand data,
    int64_t flush_mode,
    unsigned char **data_out,
    size_t *len_out
);

static PtnValue ptn_zlib_transform_context_string_value(
    PtnRuntime *runtime,
    const char *function_name,
    PtnStringOperand data,
    int decompress,
    PtnZlibContext *context,
    int64_t flush_mode,
    size_t line
) {
    unsigned char *transformed = NULL;
    size_t transformed_len = 0;
    int ok = 0;
    if (!decompress) {
        ok = ptn_zlib_context_deflate_with_zlib(
            context,
            data,
            flush_mode,
            &transformed,
            &transformed_len
        );
    }
    if (ok == 0) {
        ok = ptn_zlib_transform_bytes(
            (const unsigned char *)data.data,
            data.len,
            decompress,
            context->encoding,
            context->level,
            flush_mode,
            context->dictionary,
            context->dictionary_len,
            0,
            &transformed,
            &transformed_len
        );
    }
    if (ok <= 0) {
        char detail[192];
        int written = decompress
            ? snprintf(detail, sizeof(detail), "%s(): data error", function_name)
            : snprintf(detail, sizeof(detail), "%s(): compression failed", function_name);
        if (written < 0 || (size_t)written >= sizeof(detail)) {
            ptn_abort_out_of_memory();
        }
        ptn_emit_warning(&runtime->diagnostics, detail, line);
        return ptn_bool(0);
    }
    return ptn_owned_string_len((char *)transformed, transformed_len);
}

static int ptn_zlib_max_length_arg(
    PtnRuntime *runtime,
    const char *function_name,
    size_t argc,
    const PtnValue *args,
    size_t line,
    size_t *max_length_out
) {
    *max_length_out = 0;
    if (argc < 2 || ptn_value_deref(args[1]).type == PTN_NULL) {
        return 1;
    }
    int64_t max_length = ptn_internal_expect_integer_arg(
        runtime,
        function_name,
        2,
        "max_length",
        args[1],
        line
    );
    if (runtime->exceptions->active_exception != NULL) {
        return 0;
    }
    if (max_length < 0) {
        char message[160];
        int written = snprintf(
            message,
            sizeof(message),
            "%s(): Argument #2 ($max_length) must be greater than or equal to 0",
            function_name
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "ValueError", message);
        return 0;
    }
    *max_length_out = (size_t)max_length;
    return 1;
}

static int ptn_zlib_read_exact_fd(int fd, unsigned char *data, size_t len) {
    size_t offset = 0;
    while (offset < len) {
        size_t remaining = len - offset;
        size_t chunk_len = remaining > (size_t)SSIZE_MAX ? (size_t)SSIZE_MAX : remaining;
        ssize_t read_len = read(fd, data + offset, chunk_len);
        if (read_len < 0) {
            if (errno == EINTR) {
                continue;
            }
            return 0;
        }
        if (read_len == 0) {
            errno = EIO;
            return 0;
        }
        offset += (size_t)read_len;
    }
    return 1;
}

static void ptn_zlib_u64_to_be(uint64_t value, unsigned char out[8]) {
    for (int i = 7; i >= 0; i--) {
        out[i] = (unsigned char)(value & 0xff);
        value >>= 8;
    }
}

static uint64_t ptn_zlib_u64_from_be(const unsigned char data[8]) {
    uint64_t value = 0;
    for (size_t i = 0; i < 8; i++) {
        value = (value << 8) | data[i];
    }
    return value;
}

static void ptn_zlib_context_close_worker(PtnZlibContext *context) {
    if (context == NULL) {
        return;
    }
    if (context->worker_input_fd >= 0) {
        close(context->worker_input_fd);
        context->worker_input_fd = -1;
    }
    if (context->worker_output_fd >= 0) {
        close(context->worker_output_fd);
        context->worker_output_fd = -1;
    }
    if (context->worker_pid > 0) {
        (void)ptn_zlib_wait_success(context->worker_pid);
        context->worker_pid = -1;
    }
}

static int ptn_zlib_context_start_inflate_worker(PtnZlibContext *context) {
#if defined(_WIN32)
    (void)context;
    errno = ENOSYS;
    return 0;
#else
    if (context->worker_failed) {
        errno = EIO;
        return 0;
    }
    if (context->worker_pid > 0) {
        return 1;
    }

    int input_fds[2];
    int output_fds[2];
    if (pipe(input_fds) != 0) {
        return 0;
    }
    if (pipe(output_fds) != 0) {
        close(input_fds[0]);
        close(input_fds[1]);
        return 0;
    }

    char window_arg[32];
    snprintf(window_arg, sizeof(window_arg), "%lld", (long long)context->encoding);
    const char *script =
        "import sys,zlib\n"
        "wbits=int(sys.argv[1])\n"
        "has_dict=sys.argv[2] == '1'\n"
        "inp=sys.stdin.buffer\n"
        "outp=sys.stdout.buffer\n"
        "def read_exact(n):\n"
        "    chunks=[]\n"
        "    got=0\n"
        "    while got<n:\n"
        "        chunk=inp.read(n-got)\n"
        "        if not chunk:\n"
        "            return None\n"
        "        chunks.append(chunk)\n"
        "        got += len(chunk)\n"
        "    return b''.join(chunks)\n"
        "zdict=b''\n"
        "if has_dict:\n"
        "    hdr=read_exact(8)\n"
        "    if hdr is None:\n"
        "        sys.exit(0)\n"
        "    dict_len=int.from_bytes(hdr, 'big')\n"
        "    zdict=read_exact(dict_len)\n"
        "    if zdict is None:\n"
        "        sys.exit(1)\n"
        "def make_obj():\n"
        "    return zlib.decompressobj(wbits, zdict=zdict) if has_dict else zlib.decompressobj(wbits)\n"
        "d=make_obj()\n"
        "while True:\n"
        "    hdr=read_exact(9)\n"
        "    if hdr is None:\n"
        "        break\n"
        "    finish=hdr[0] == 1\n"
        "    data_len=int.from_bytes(hdr[1:], 'big')\n"
        "    data=read_exact(data_len)\n"
        "    if data is None:\n"
        "        break\n"
        "    try:\n"
        "        payload=d.decompress(data)\n"
        "        if finish:\n"
        "            payload += d.flush()\n"
        "            d=make_obj()\n"
        "        outp.write(len(payload).to_bytes(8, 'big'))\n"
        "        outp.write(payload)\n"
        "        outp.flush()\n"
        "    except Exception:\n"
        "        outp.write((2**64-1).to_bytes(8, 'big'))\n"
        "        outp.flush()\n"
        "        sys.exit(1)\n";

    pid_t child = fork();
    if (child < 0) {
        close(input_fds[0]);
        close(input_fds[1]);
        close(output_fds[0]);
        close(output_fds[1]);
        return 0;
    }
    if (child == 0) {
        close(input_fds[1]);
        close(output_fds[0]);
        (void)dup2(input_fds[0], STDIN_FILENO);
        (void)dup2(output_fds[1], STDOUT_FILENO);
        if (input_fds[0] > STDERR_FILENO) {
            close(input_fds[0]);
        }
        if (output_fds[1] > STDERR_FILENO) {
            close(output_fds[1]);
        }
        ptn_zlib_child_silence_stderr();
        execlp(
            "python3",
            "python3",
            "-c",
            script,
            window_arg,
            context->dictionary != NULL && context->dictionary_len != 0 ? "1" : "0",
            (char *)NULL
        );
        _exit(127);
    }

    close(input_fds[0]);
    close(output_fds[1]);
    context->worker_pid = child;
    context->worker_input_fd = input_fds[1];
    context->worker_output_fd = output_fds[0];

    if (context->dictionary != NULL && context->dictionary_len != 0) {
        unsigned char header[8];
        ptn_zlib_u64_to_be((uint64_t)context->dictionary_len, header);
        if (!ptn_zlib_write_all_fd(context->worker_input_fd, header, sizeof(header)) ||
            !ptn_zlib_write_all_fd(context->worker_input_fd, context->dictionary, context->dictionary_len)) {
            context->worker_failed = 1;
            ptn_zlib_context_close_worker(context);
            return 0;
        }
    }

    return 1;
#endif
}

static int ptn_zlib_context_inflate_with_worker(
    PtnZlibContext *context,
    PtnStringOperand data,
    int finish,
    unsigned char **data_out,
    size_t *len_out
) {
    *data_out = NULL;
    *len_out = 0;
    if (!ptn_zlib_context_start_inflate_worker(context)) {
        return 0;
    }
    unsigned char header[9];
    header[0] = finish ? 1 : 0;
    ptn_zlib_u64_to_be((uint64_t)data.len, header + 1);
    if (!ptn_zlib_write_all_fd(context->worker_input_fd, header, sizeof(header)) ||
        !ptn_zlib_write_all_fd(context->worker_input_fd, (const unsigned char *)data.data, data.len)) {
        context->worker_failed = 1;
        ptn_zlib_context_close_worker(context);
        return 0;
    }
    unsigned char len_header[8];
    if (!ptn_zlib_read_exact_fd(context->worker_output_fd, len_header, sizeof(len_header))) {
        context->worker_failed = 1;
        ptn_zlib_context_close_worker(context);
        return 0;
    }
    uint64_t payload_len = ptn_zlib_u64_from_be(len_header);
    if (payload_len == UINT64_MAX || payload_len > SIZE_MAX) {
        context->worker_failed = 1;
        ptn_zlib_context_close_worker(context);
        return 0;
    }
    unsigned char *payload = NULL;
    if (payload_len == 0) {
        payload = (unsigned char *)ptn_duplicate_string_len("", 0);
    } else {
        payload = malloc((size_t)payload_len);
        if (payload == NULL) {
            ptn_abort_out_of_memory();
        }
        if (!ptn_zlib_read_exact_fd(context->worker_output_fd, payload, (size_t)payload_len)) {
            free(payload);
            context->worker_failed = 1;
            ptn_zlib_context_close_worker(context);
            return 0;
        }
    }
    *data_out = payload;
    *len_out = (size_t)payload_len;
    return 1;
}

static int ptn_zlib_context_start_native_inflate(PtnZlibContext *context) {
#if PTN_HAVE_ZLIB
    if (context->native_stream_initialized) {
        if (context->native_stream_is_deflate) {
            return -1;
        }
        return 1;
    }
    memset(&context->native_stream, 0, sizeof(context->native_stream));
    int status = inflateInit2(&context->native_stream, (int)context->encoding);
    if (status != Z_OK) {
        memset(&context->native_stream, 0, sizeof(context->native_stream));
        return -1;
    }
    context->native_stream_initialized = 1;
    context->native_stream_ended = 0;
    context->native_dictionary_applied = 0;
    context->native_stream_is_deflate = 0;
    if (context->encoding == PTN_ZLIB_ENCODING_RAW &&
        context->dictionary != NULL &&
        context->dictionary_len != 0) {
        if (context->dictionary_len > UINT_MAX ||
            inflateSetDictionary(&context->native_stream, context->dictionary, (uInt)context->dictionary_len) != Z_OK) {
            ptn_zlib_context_end_native(context);
            return -1;
        }
        context->native_dictionary_applied = 1;
    }
    return 1;
#else
    (void)context;
    return 0;
#endif
}

static int ptn_zlib_context_start_native_deflate(PtnZlibContext *context) {
#if PTN_HAVE_ZLIB
    if (context->native_stream_initialized) {
        if (!context->native_stream_is_deflate) {
            return -1;
        }
        return 1;
    }
    memset(&context->native_stream, 0, sizeof(context->native_stream));
    int level = context->level < -1 ? -1 : (int)context->level;
    int status = deflateInit2(
        &context->native_stream,
        level,
        Z_DEFLATED,
        (int)context->encoding,
        8,
        Z_DEFAULT_STRATEGY
    );
    if (status != Z_OK) {
        memset(&context->native_stream, 0, sizeof(context->native_stream));
        return -1;
    }
    context->native_stream_initialized = 1;
    context->native_stream_ended = 0;
    context->native_dictionary_applied = 0;
    context->native_stream_is_deflate = 1;
    if (context->dictionary != NULL && context->dictionary_len != 0) {
        if (context->dictionary_len > UINT_MAX ||
            deflateSetDictionary(&context->native_stream, context->dictionary, (uInt)context->dictionary_len) != Z_OK) {
            ptn_zlib_context_end_native(context);
            return -1;
        }
        context->native_dictionary_applied = 1;
    }
    return 1;
#else
    (void)context;
    return 0;
#endif
}

static int ptn_zlib_context_deflate_with_zlib(
    PtnZlibContext *context,
    PtnStringOperand data,
    int64_t flush_mode,
    unsigned char **data_out,
    size_t *len_out
) {
    *data_out = NULL;
    *len_out = 0;
#if !PTN_HAVE_ZLIB
    (void)context;
    (void)data;
    (void)flush_mode;
    return 0;
#else
    int start_status = ptn_zlib_context_start_native_deflate(context);
    if (start_status <= 0) {
        return start_status;
    }
    if (data.len > UINT_MAX) {
        ptn_zlib_context_end_native(context);
        return -1;
    }

    z_stream *stream = &context->native_stream;
    stream->next_in = (Bytef *)(const unsigned char *)data.data;
    stream->avail_in = (uInt)data.len;

    PtnStringBuffer buffer;
    ptn_string_buffer_init(&buffer);
    int native_flush = ptn_zlib_native_flush_mode(flush_mode);
    int status = Z_OK;
    for (;;) {
        unsigned char chunk[8192];
        stream->next_out = chunk;
        stream->avail_out = (uInt)sizeof(chunk);
        uInt before_in = stream->avail_in;
        status = deflate(stream, native_flush);
        if (status == Z_STREAM_ERROR || status == Z_DATA_ERROR || status == Z_MEM_ERROR) {
            free(buffer.data);
            ptn_zlib_context_end_native(context);
            return -1;
        }
        size_t produced = sizeof(chunk) - stream->avail_out;
        if (produced != 0) {
            ptn_string_buffer_append_len(&buffer, (const char *)chunk, produced);
        }
        if (status == Z_STREAM_END) {
            ptn_zlib_context_end_native(context);
            context->native_stream_ended = 1;
            break;
        }
        if (status == Z_BUF_ERROR && produced == 0 && stream->avail_in == before_in) {
            break;
        }
        if (stream->avail_in == 0 && stream->avail_out != 0) {
            break;
        }
    }
    if (buffer.data == NULL) {
        buffer.data = ptn_duplicate_string_len("", 0);
        buffer.len = 0;
    }
    *data_out = (unsigned char *)buffer.data;
    *len_out = buffer.len;
    return 1;
#endif
}

static int ptn_zlib_context_inflate_with_zlib(
    PtnZlibContext *context,
    PtnStringOperand data,
    int64_t flush_mode,
    unsigned char **data_out,
    size_t *len_out
) {
    *data_out = NULL;
    *len_out = 0;
#if !PTN_HAVE_ZLIB
    (void)context;
    (void)data;
    (void)flush_mode;
    return 0;
#else
    if (context->native_stream_ended) {
        if (data.len == 0 && flush_mode == PTN_ZLIB_FINISH) {
            context->native_stream_ended = 0;
            *data_out = (unsigned char *)ptn_duplicate_string_len("", 0);
            *len_out = 0;
            return 1;
        }
        context->native_stream_ended = 0;
    }
    int start_status = ptn_zlib_context_start_native_inflate(context);
    if (start_status <= 0) {
        return start_status;
    }
    if (data.len > UINT_MAX) {
        ptn_zlib_context_end_native(context);
        return -1;
    }

    z_stream *stream = &context->native_stream;
    stream->next_in = (Bytef *)(const unsigned char *)data.data;
    stream->avail_in = (uInt)data.len;

    PtnStringBuffer buffer;
    ptn_string_buffer_init(&buffer);
    int status = Z_OK;
    int saw_stream_end = 0;
    do {
        unsigned char chunk[8192];
        stream->next_out = chunk;
        stream->avail_out = (uInt)sizeof(chunk);
        uInt before_in = stream->avail_in;
        status = inflate(stream, (int)flush_mode);
        if (status == Z_NEED_DICT) {
            if (context->dictionary == NULL ||
                context->dictionary_len == 0 ||
                context->dictionary_len > UINT_MAX ||
                inflateSetDictionary(stream, context->dictionary, (uInt)context->dictionary_len) != Z_OK) {
                free(buffer.data);
                ptn_zlib_context_end_native(context);
                return -1;
            }
            context->native_dictionary_applied = 1;
            continue;
        }
        if (status == Z_STREAM_ERROR || status == Z_DATA_ERROR || status == Z_MEM_ERROR) {
            free(buffer.data);
            ptn_zlib_context_end_native(context);
            return -1;
        }
        size_t produced = sizeof(chunk) - stream->avail_out;
        if (produced != 0) {
            ptn_string_buffer_append_len(&buffer, (const char *)chunk, produced);
        }
        if (status == Z_STREAM_END) {
            saw_stream_end = 1;
            break;
        }
        if (status == Z_BUF_ERROR) {
            if (produced == 0 && stream->avail_in == before_in) {
                break;
            }
            status = Z_OK;
        }
    } while (stream->avail_out == 0 || stream->avail_in > 0);

    if (saw_stream_end) {
        ptn_zlib_context_end_native(context);
        context->native_stream_ended = 1;
    }
    *data_out = (unsigned char *)buffer.data;
    *len_out = buffer.len;
    return 1;
#endif
}

static PtnValue ptn_zlib_inflate_context_string_value(
    PtnRuntime *runtime,
    const char *function_name,
    PtnStringOperand data,
    PtnZlibContext *context,
    int64_t flush_mode,
    size_t line
) {
    unsigned char *transformed = NULL;
    size_t transformed_len = 0;
    int ok = ptn_zlib_context_inflate_with_zlib(
        context,
        data,
        flush_mode,
        &transformed,
        &transformed_len
    );
    if (ok == 0) {
        ok = ptn_zlib_context_inflate_with_worker(
            context,
            data,
            flush_mode == PTN_ZLIB_FINISH,
            &transformed,
            &transformed_len
        );
    }
    if (ok <= 0) {
        char detail[192];
        int written = snprintf(
            detail,
            sizeof(detail),
            "%s(): data error failed",
            function_name
        );
        if (written < 0 || (size_t)written >= sizeof(detail)) {
            ptn_abort_out_of_memory();
        }
        ptn_emit_warning(&runtime->diagnostics, detail, line);
        return ptn_bool(0);
    }
    return ptn_owned_string_len((char *)transformed, transformed_len);
}

