static PtnValue ptn_internal_ob_gzhandler(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand data = ptn_internal_expect_string_arg(runtime, "ob_gzhandler", 1, "data", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(data);
        return ptn_null();
    }
    const char *accept_encoding = getenv("HTTP_ACCEPT_ENCODING");
    int accepts_gzip = 0;
    if (accept_encoding != NULL) {
        size_t accept_len = strlen(accept_encoding);
        for (size_t i = 0; i + 4 <= accept_len; i++) {
            if (ptn_ascii_case_equal_n(accept_encoding + i, "gzip", 4)) {
                accepts_gzip = 1;
                break;
            }
        }
    }
    if (!accepts_gzip) {
        ptn_string_operand_free(data);
        return ptn_bool(0);
    }
    PtnValue result = ptn_zlib_transform_string_value(
        runtime,
        "ob_gzhandler",
        data,
        0,
        PTN_ZLIB_ENCODING_GZIP,
        -1,
        0,
        line
    );
    ptn_string_operand_free(data);
    return result;
}

static PtnValue ptn_internal_ob_iconv_handler(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnStringOperand data = ptn_internal_expect_string_arg(runtime, "ob_iconv_handler", 1, "data", args[0], line);
    if (runtime->exceptions->active_exception != NULL) {
        ptn_string_operand_free(data);
        return ptn_null();
    }
    const char *from_encoding = ptn_iconv_effective_internal_encoding(runtime);
    const char *to_encoding = ptn_iconv_effective_output_encoding(runtime);
    size_t from_encoding_len = strlen(from_encoding);
    size_t to_encoding_len = strlen(to_encoding);
    PtnStringOperand from_operand = ptn_string_operand_borrowed_len(from_encoding, from_encoding_len);
    PtnStringOperand to_operand = ptn_string_operand_borrowed_len(to_encoding, to_encoding_len);
    char *resolved_from = from_encoding_len > 64 ? NULL : ptn_iconv_resolve_encoding_alloc(from_operand);
    char *resolved_to = to_encoding_len > 64 ? NULL : ptn_iconv_resolve_encoding_alloc(to_operand);
    if (resolved_from == NULL || resolved_to == NULL) {
        free(resolved_from);
        free(resolved_to);
        PtnValue passthrough = ptn_owned_string_len(ptn_duplicate_string_len(data.data, data.len), data.len);
        ptn_string_operand_free(data);
        return passthrough;
    }
    size_t output_len = 0;
    int status = PTN_ICONV_CONVERT_OK;
    char *output = ptn_iconv_convert_alloc(
        data.data,
        data.len,
        resolved_from,
        resolved_to,
        &status,
        &output_len
    );
    free(resolved_from);
    free(resolved_to);
    ptn_string_operand_free(data);
    if (status == PTN_ICONV_CONVERT_ILLEGAL) {
        ptn_iconv_emit_conversion_notice(runtime, "ob_iconv_handler(): Detected an illegal character in input string", line);
    } else if (status == PTN_ICONV_CONVERT_INCOMPLETE) {
        ptn_iconv_emit_conversion_notice(runtime, "ob_iconv_handler(): Detected an incomplete multibyte character in input string", line);
    }
    if (output == NULL) {
        return ptn_bool(0);
    }
    return ptn_owned_string_len(output, output_len);
}

static int ptn_try_open_plain_gz_read_stream(const char *path, const char *mode, PtnValue *out) {
    if (!ptn_zlib_stream_mode_can_read(mode) || ptn_zlib_stream_mode_can_write(mode)) {
        return 0;
    }
    FILE *stream = fopen(path, "rb");
    if (stream == NULL) {
        return 0;
    }
    unsigned char header[2] = { 0, 0 };
    size_t header_len = fread(header, 1, sizeof(header), stream);
    if (ferror(stream)) {
        fclose(stream);
        return 0;
    }
    if (header_len == sizeof(header) && header[0] == 0x1f && header[1] == 0x8b) {
        fclose(stream);
        errno = EIO;
        return 0;
    }
    if (fseek(stream, 0, SEEK_SET) != 0) {
        fclose(stream);
        return 0;
    }
    *out = ptn_resource(ptn_resource_new_stream(stream, path, mode));
    return 1;
}

static PtnValue ptn_internal_gzopen(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    char *path = ptn_internal_path_arg_c_string_or_value_error(runtime, "gzopen", 1, "filename", args[0], line);
    if (path == NULL) {
        return ptn_null();
    }
    PtnStringOperand mode_operand = ptn_internal_expect_string_arg(runtime, "gzopen", 2, "mode", args[1], line);
    char *mode = ptn_path_operand_to_c_string(mode_operand);
    ptn_string_operand_free(mode_operand);
    if (runtime->exceptions->active_exception != NULL) {
        free(path);
        free(mode);
        return ptn_null();
    }
    if (mode == NULL) {
        ptn_emit_warning(&runtime->diagnostics, "gzopen(): Argument #2 ($mode) must not contain any null bytes", line);
        free(path);
        return ptn_bool(0);
    }
    if (ptn_zlib_stream_mode_has_plus(mode)) {
        ptn_emit_warning(
            &runtime->diagnostics,
            "gzopen(): Cannot open a zlib stream for reading and writing at the same time!",
            line
        );
        free(mode);
        free(path);
        return ptn_bool(0);
    }
    int invalid_zlib_create_mode =
        !ptn_zlib_stream_mode_can_read(mode) &&
        !ptn_zlib_stream_mode_can_write(mode) &&
        (mode[0] == 'c' || mode[0] == 'C' || mode[0] == 'x' || mode[0] == 'X');
    if (argc >= 3 && ptn_is_truthy(args[2]) && !ptn_zlib_stream_mode_can_write(mode)) {
        char *resolved_path = ptn_resolve_existing_include_path(runtime, path);
        if (resolved_path != NULL) {
            free(path);
            path = resolved_path;
        }
    }
    if (strlen(path) >= 6 && ptn_ascii_case_equal_n(path, "php://", 6)) {
        size_t needed = (size_t)snprintf(
            NULL,
            0,
            "gzopen(%s): could not make seekable - %s",
            path,
            path
        );
        char *message = malloc(needed + 1);
        if (message == NULL) {
            ptn_abort_out_of_memory();
        }
        int written = snprintf(
            message,
            needed + 1,
            "gzopen(%s): could not make seekable - %s",
            path,
            path
        );
        if (written < 0 || (size_t)written != needed) {
            free(message);
            ptn_abort_out_of_memory();
        }
        ptn_emit_warning(&runtime->diagnostics, message, line);
        free(message);
        free(mode);
        free(path);
        return ptn_bool(0);
    }
    PtnValue stream;
    int opened = ptn_try_open_zlib_path_stream(path, path, mode, -1, &stream);
    if (opened > 0) {
        free(mode);
        free(path);
        return stream;
    }
    if (opened < 0 && ptn_try_open_plain_gz_read_stream(path, mode, &stream)) {
        free(mode);
        free(path);
        return stream;
    }
    if (opened == 0 && invalid_zlib_create_mode) {
        FILE *side_effect_stream = ptn_fopen_php_mode(path, mode);
        if (side_effect_stream != NULL) {
            fclose(side_effect_stream);
            ptn_emit_warning(&runtime->diagnostics, "gzopen(): gzopen failed", line);
            free(mode);
            free(path);
            return ptn_bool(0);
        }
    }
    char detail[192];
    int needed = snprintf(
        detail,
        sizeof(detail),
        "%s: %s",
        opened == 0 ? "Failed to open stream" : "Failed to read stream",
        strerror(errno)
    );
    if (needed < 0 || (size_t)needed >= sizeof(detail)) {
        ptn_abort_out_of_memory();
    }
    ptn_emit_file_warning(runtime, "gzopen", path, detail, line);
    free(mode);
    free(path);
    return ptn_bool(0);
}

static PtnValue ptn_internal_gzread(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    (void)argc;
    PtnResource *resource = ptn_internal_expect_open_stream_arg(runtime, "gzread", args[0], line);
    if (resource == NULL) {
        return ptn_null();
    }
    int64_t requested = ptn_internal_positive_length_arg(runtime, "gzread", 2, "length", args[1], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    if (!ptn_phar_stream_mode_can_read(resource->stream_mode)) {
        return ptn_bool(0);
    }
    size_t length = (size_t)requested;
    if (length == SIZE_MAX) {
        ptn_abort_out_of_memory();
    }
    size_t filtered_len = 0;
    int ok = 0;
    char *filtered = ptn_stream_read_filtered_bytes(
        runtime,
        "gzread",
        resource,
        length,
        line,
        &filtered_len,
        &ok
    );
    if (!ok) {
        return ptn_bool(0);
    }
    return ptn_owned_string_len(filtered, filtered_len);
}

static PtnValue ptn_internal_gzwrite(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnResource *resource = ptn_internal_expect_open_stream_arg(runtime, "gzwrite", args[0], line);
    if (resource == NULL) {
        return ptn_null();
    }
    PtnStringOperand data = ptn_internal_expect_string_arg(runtime, "gzwrite", 2, "data", args[1], line);
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    size_t length = data.len;
    if (argc >= 3 && ptn_value_deref(args[2]).type != PTN_NULL) {
        int64_t requested = ptn_internal_expect_integer_arg(runtime, "gzwrite", 3, "length", args[2], line);
        if (runtime->exceptions->active_exception != NULL) {
            ptn_string_operand_free(data);
            return ptn_null();
        }
        if (requested <= 0) {
            ptn_string_operand_free(data);
            return ptn_int(0);
        }
        if ((uint64_t)requested < length) {
            length = (size_t)requested;
        }
    }
    size_t written = ptn_stream_write_filtered(runtime, "gzwrite", resource, data.data, length, line);
    ptn_string_operand_free(data);
    if (written != length && ptn_stream_error(resource)) {
        ptn_emit_stream_write_notice(runtime, "gzwrite", length, line);
        ptn_stream_clear_error(resource);
        return ptn_bool(0);
    }
    if (written > (size_t)INT64_MAX) {
        ptn_abort_out_of_memory();
    }
    return ptn_int((int64_t)written);
}

static PtnValue ptn_internal_gzseek(PtnRuntime *runtime, size_t argc, const PtnValue *args, size_t line) {
    PtnValue stream_value = ptn_value_deref(args[0]);
    int64_t offset = ptn_internal_expect_integer_arg(runtime, "gzseek", 2, "offset", args[1], line);
    int64_t whence = argc >= 3
        ? ptn_internal_expect_integer_arg(runtime, "gzseek", 3, "whence", args[2], line)
        : PTN_SEEK_SET;
    if (runtime->exceptions->active_exception != NULL) {
        return ptn_null();
    }
    if (stream_value.type != PTN_RESOURCE) {
        char message[192];
        int written = snprintf(
            message,
            sizeof(message),
            "gzseek(): Argument #1 ($stream) must be of type resource, %s given",
            ptn_offset_container_type_name(stream_value)
        );
        if (written < 0 || (size_t)written >= sizeof(message)) {
            ptn_abort_out_of_memory();
        }
        ptn_throw_exception(runtime, "TypeError", message);
        return ptn_null();
    }
    if (!ptn_stream_resource_is_open(stream_value.as.resource)) {
        ptn_throw_exception(
            runtime,
            "TypeError",
            "gzseek(): Argument #1 ($stream) must be an open stream resource"
        );
        return ptn_null();
    }
    PtnResource *resource = stream_value.as.resource;
    int seek_whence = (int)whence;
    if (seek_whence == SEEK_END) {
        ptn_emit_warning(&runtime->diagnostics, "gzseek(): SEEK_END is not supported", line);
        return ptn_int(-1);
    }
    if (seek_whence != SEEK_SET && seek_whence != SEEK_CUR) {
        return ptn_int(-1);
    }
    if (ptn_stream_seek(resource, offset, seek_whence) == 0) {
        ptn_stream_filtered_read_pending_clear(resource);
        ptn_stream_filter_chain_reset(resource->read_filters);
        ptn_stream_filter_chain_reset_on_seek(resource->write_filters);
        return ptn_int(0);
    }
    return ptn_int(-1);
}

