static void ptn_phar_clear_last_stream_error(void) {
    free(ptn_phar_last_stream_error);
    ptn_phar_last_stream_error = NULL;
}

static char *ptn_phar_take_last_stream_error(void) {
    char *message = ptn_phar_last_stream_error;
    ptn_phar_last_stream_error = NULL;
    return message;
}

