typedef struct {
    char *name;
    int has_reflected_object;
    PtnValue reflected_object;
} PtnReflectionClassData;

static void ptn_reflection_class_data_free(void *data) {
    PtnReflectionClassData *class_data = (PtnReflectionClassData *)data;
    if (class_data == NULL) {
        return;
    }
    free(class_data->name);
    if (class_data->has_reflected_object) {
        ptn_value_destroy(&class_data->reflected_object);
    }
    free(class_data);
}

static int ptn_reflection_class_symbol_exists(const char *name) {
    return ptn_declared_class_exists(name)
        || ptn_declared_interface_exists(name)
        || ptn_declared_trait_exists(name)
        || ptn_internal_class_exists_name(name)
        || ptn_internal_interface_exists_name(name);
}

static int ptn_reflection_class_runtime_symbol_exists(PtnRuntime *runtime, const char *name) {
    return ptn_declared_runtime_class_exists(runtime, name)
        || ptn_declared_runtime_interface_exists(runtime, name)
        || ptn_declared_runtime_trait_exists(runtime, name)
        || ptn_internal_class_exists_name(name)
        || ptn_internal_interface_exists_name(name);
}

static int ptn_reflection_class_runtime_symbol_exists_after_autoload(
    PtnRuntime *runtime,
    const char *lookup_name,
    size_t line,
    const char **resolved_name_out
) {
    const char *resolved_name = ptn_runtime_resolve_class_alias(runtime, lookup_name);
    if (
        !ptn_reflection_class_runtime_symbol_exists(runtime, resolved_name) &&
        !ptn_declared_runtime_class_is_linking(runtime, resolved_name) &&
        ptn_class_name_should_autoload(lookup_name)
    ) {
        runtime->call_site_line = line;
        ptn_runtime_autoload_class(runtime, lookup_name, line);
        if (runtime->exceptions->active_exception != NULL) {
            if (resolved_name_out != NULL) {
                *resolved_name_out = resolved_name;
            }
            return 0;
        }
        resolved_name = ptn_runtime_resolve_class_alias(runtime, lookup_name);
    }
    int exists = ptn_reflection_class_runtime_symbol_exists(runtime, resolved_name);
    if (resolved_name_out != NULL) {
        *resolved_name_out = exists ? ptn_declared_class_canonical_name(resolved_name) : resolved_name;
    }
    return exists;
}

static int ptn_reflection_class_is_interface_name(const char *name) {
    return ptn_declared_interface_exists(name) || ptn_internal_interface_exists_name(name);
}

static int ptn_reflection_class_runtime_is_interface_name(PtnRuntime *runtime, const char *name) {
    return ptn_declared_runtime_interface_exists(runtime, name) || ptn_internal_interface_exists_name(name);
}

static int ptn_reflection_class_is_user_defined_name(const char *name) {
    return ptn_declared_user_class_or_interface_exists(name)
        || ptn_declared_trait_exists(name);
}

static int ptn_reflection_class_is_internal_name(const char *name) {
    return ptn_reflection_class_symbol_exists(name) && !ptn_reflection_class_is_user_defined_name(name);
}

static PtnReflectionClassData *ptn_reflection_class_data(PtnRuntime *runtime, PtnValue receiver) {
    receiver = ptn_value_deref(receiver);
    if (
        receiver.type != PTN_OBJECT
        || (!ptn_internal_class_name_is_reflection_class(receiver.as.object->class_name)
            && !ptn_internal_class_name_is_reflection_enum(receiver.as.object->class_name)
            && !ptn_internal_class_name_is_reflection_object(receiver.as.object->class_name))
        || receiver.as.object->native_data == NULL
    ) {
        ptn_throw_exception(runtime, "Error", "Invalid ReflectionClass object");
        return NULL;
    }
    return (PtnReflectionClassData *)receiver.as.object->native_data;
}

static PtnValue ptn_reflection_class_string_before_last_namespace_separator(const char *name) {
    const char *last_separator = strrchr(name, '\\');
    if (last_separator == NULL) {
        return ptn_string("");
    }
    size_t len = (size_t)(last_separator - name);
    return ptn_owned_string_len(ptn_duplicate_string_len(name, len), len);
}

static PtnValue ptn_reflection_class_string_after_last_namespace_separator(const char *name) {
    const char *last_separator = strrchr(name, '\\');
    const char *short_name = last_separator == NULL ? name : last_separator + 1;
    return ptn_owned_string(ptn_duplicate_string(short_name));
}

